                        + text(task.get("nodeDefinitionId")) + "  "
                        + text(task.get("nodeExecutionId")));
            }
        }
        System.out.println();

        System.out.println("Latest Agent Runs:");
        var runListing = new RunMetadataReader().listWithWarnings(paths);
