                  "title": "summary test",
                  "status": "created",
                  "repository": {
                    "originalWorkdir": "%s",
                    "gitRoot": "%s"
                  }
                }
                """.formatted(jsonPath(tempDir), jsonPath(tempDir)), StandardCharsets.UTF_8);
        Files.writeString(root.resolve("workflow/current.json"), """
