        writeSummary("""
                {
                  "final_status": "WAITING_FOR_RECOVERY",
                  "final_acceptance_decision": "REJECT",
                  "repair_loop_count": 0,
                  "verification_confidence": "LOW",
                  "original_repo_clean": true
