                user_id,utc_date,model,wallet_type,cost,currency
                user,2026-06-01,deepseek-v4-pro,Paid,0.8136378000000000,CNY
                """, StandardCharsets.UTF_8);

        var command = new CalibrationBillingCsvCommand();
