        item.put("displayName", text(node.get("displayName"), text(node.get("nodeDefinitionId"))));
        item.put("status", text(node.get("status")));
        item.put("kind", text(node.get("kind")));
        item.put("iterationId", text(node.get("iterationId")));
        item.put("durationMs", text(node.get("durationMs")));
        item.put("latestExecutionId", text(node.get("latestExecutionId")));
        return item;
    }

    private List<Map<String, Object>> latestAgentRuns(Path root, WorkstreamPaths paths, int limit) throws IOException {
        if (!Files.isDirectory(paths.runsDir())) {
            return List.of();
        }
        try (var stream = Files.list(paths.runsDir())) {
            return stream
                    .filter(Files::isDirectory)
                    .sorted(Comparator.comparing(WorkstreamQueryService::lastModified).reversed())
                    .limit(limit)
                    .map(path -> runSummary(root, path))
                    .toList();
        }
    }

    private Map<String, Object> runSummary(Path root, Path runDir) {
        var runJson = runDir.resolve("run.json");
        var source = readJson(runJson);
        var item = new LinkedHashMap<String, Object>();
        item.put("runId", text(source.get("runId"), runDir.getFileName().toString()));
        item.put("agent", text(source.get("agent")));
        item.put("nodeId", text(source.get("nodeId")));
        item.put("status", text(source.get("status")));
        item.put("executionOutcome", map(source.get("executionOutcome")));
        item.put("outcomeStatus", text(map(source.get("executionOutcome")).get("status")));
        item.put("outcomePrimaryReason", text(map(source.get("executionOutcome")).get("primaryReason")));
        item.put("durationMs", text(source.get("durationMs")));
        item.put("usage", map(source.get("usage")));
        item.put("toolUsage", map(source.get("toolUsage")));
        item.put("contextGovernanceActualReportPath", text(source.get("contextGovernanceActualReportPath")));
        item.put("ref", root.relativize(runDir.toAbsolutePath().normalize()).toString());
        return item;
    }

    private Map<String, Object> artifacts(Path root, WorkstreamPaths paths) {
        var artifacts = new LinkedHashMap<String, Object>();
        artifact(artifacts, root, "finalReport", paths.workstreamDir().resolve("reports").resolve("latest-final-report.md"));
        artifact(artifacts, root, "workstreamSummary", paths.workstreamDir().resolve("reports").resolve("workstream-summary.md"));
        artifact(artifacts, root, "handoffJson", paths.workstreamDir().resolve("artifacts").resolve("next-stage").resolve("handoff.json"));
        artifact(artifacts, root, "nextStagePrompt", paths.workstreamDir().resolve("artifacts").resolve("next-stage").resolve("next-stage-prompt.md"));
        artifact(artifacts, root, "deliveryPrBody", paths.workstreamDir().resolve("delivery").resolve("pr-body.md"));
        artifact(artifacts, root, "currentFailure", paths.currentFailureMarkdown());
        latestContextPackageMetadata(paths).ifPresent(path ->
                artifact(artifacts, root, "contextPackageMetadata", path));
        artifact(artifacts, root, "repoMap", paths.workstreamDir().resolve("memory").resolve("repo-map.json"));
        latestNamedArtifact(paths.workstreamDir().resolve("memory"), "file-relevance-plan-", ".json").ifPresent(path ->
                artifact(artifacts, root, "fileRelevancePlan", path));
        latestNamedArtifact(paths.workstreamDir().resolve("memory"), "stage-scope-policy-", ".json").ifPresent(path ->
                artifact(artifacts, root, "stageScopePolicy", path));
        latestNamedArtifact(paths.workstreamDir().resolve("artifacts").resolve("context-governance"), "", ".json").ifPresent(path ->
                artifact(artifacts, root, "contextGovernanceReport", path));
        return artifacts;
    }

    private java.util.Optional<Path> latestContextPackageMetadata(WorkstreamPaths paths) {
        var contextDir = paths.workstreamDir().resolve("context");
        if (!Files.isDirectory(contextDir)) {
            return java.util.Optional.empty();
        }
        try (var stream = Files.list(contextDir)) {
            return stream
                    .filter(path -> path.getFileName().toString().endsWith(".json"))
                    .max(Comparator.comparingLong(this::lastModifiedMillis));
        } catch (IOException ignored) {
            return java.util.Optional.empty();
        }
    }

    private java.util.Optional<Path> latestNamedArtifact(Path dir, String prefix, String suffix) {
        if (!Files.isDirectory(dir)) {
            return java.util.Optional.empty();
        }
        try (var stream = Files.list(dir)) {
            return stream
                    .filter(Files::isRegularFile)
                    .filter(path -> path.getFileName().toString().startsWith(prefix))
                    .filter(path -> path.getFileName().toString().endsWith(suffix))
                    .max(Comparator.comparingLong(this::lastModifiedMillis));
        } catch (IOException ignored) {
            return java.util.Optional.empty();
        }
    }

    private long lastModifiedMillis(Path path) {
        try {
            return Files.getLastModifiedTime(path).toMillis();
        } catch (IOException ignored) {
            return 0L;
        }
    }

    private Map<String, Object> completionAudit(WorkstreamPaths paths) {
        if (Files.isRegularFile(paths.completionAuditJson())) {
            var audit = readJson(paths.completionAuditJson());
            if (!audit.isEmpty()) {
                return audit;
            }
            return Map.of(
                    "status", "invalid",
                    "gaps", List.of("completion audit is unreadable or invalid")
            );
        }
        return Map.of(
                "status", "not_available",
                "gaps", List.of("completion audit is missing")
        );
    }

    private static String readText(Path path) {
        try {
            return Files.readString(path, StandardCharsets.UTF_8);
        } catch (IOException ignored) {
            return "";
        }
    }

    private void artifact(Map<String, Object> artifacts, Path root, String key, Path path) {
        var normalized = path.toAbsolutePath().normalize();
        artifacts.put(key, Map.of(
                "available", Files.isRegularFile(path),
                "path", root.relativize(normalized).toString()
        ));
    }

    private Map<String, Object> readJson(Path path) {
        try {
            return objectMapper.readValue(path.toFile(), MAP_TYPE);
        } catch (IOException e) {
            return Map.of();
        }
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> mapValue(Object value) {
        return value instanceof Map<?, ?> map ? (Map<String, Object>) map : Map.of();
    }

    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> mapList(Object value) {
        if (value instanceof List<?> list) {
            return list.stream()
                    .filter(Map.class::isInstance)
                    .map(item -> (Map<String, Object>) item)
                    .toList();
        }
        return List.of();
    }

    private static List<Map<String, Object>> recent(List<Map<String, Object>> nodes, int limit) {
        return nodes.stream()
                .skip(Math.max(0, nodes.size() - limit))
                .toList();
    }

    private static List<Map<String, Object>> sortedTimelineNodes(List<Map<String, Object>> nodes) {
        return nodes.stream()
                .sorted(WorkstreamQueryService::compareTimelineNodes)
                .toList();
    }

    private static int compareTimelineNodes(Map<String, Object> left, Map<String, Object> right) {
        var byTime = timelineInstant(left).compareTo(timelineInstant(right));
        if (byTime != 0) {
            return byTime;
        }
        return text(left.get("nodeInstanceId")).compareTo(text(right.get("nodeInstanceId")));
    }

    private static Instant timelineInstant(Map<String, Object> node) {
        var startedAt = parseInstant(text(node.get("startedAt")));
        if (startedAt != null) {
            return startedAt;
        }
        var finishedAt = parseInstant(text(node.get("finishedAt")));
        if (finishedAt != null) {
            return finishedAt;
        }
        return Instant.MAX;
    }

    private static Instant parseInstant(String value) {
        if (value.isBlank() || "null".equals(value)) {
            return null;
        }
        try {
            return Instant.parse(value);
        } catch (RuntimeException ignored) {
            return null;
        }
    }

    private static List<String> textList(Object value) {
        if (value instanceof List<?> list) {
            return list.stream().map(String::valueOf).toList();
        }
        return List.of();
    }

    private static Map<String, Object> map(Object value) {
        if (value instanceof Map<?, ?> source) {
            var result = new LinkedHashMap<String, Object>();
            for (var entry : source.entrySet()) {
                if (entry.getKey() instanceof String key) {
                    result.put(key, entry.getValue());
                }
            }
            return result;
        }
        return Map.of();
    }

    private static int number(Object value) {
        if (value instanceof Number number) {
            return number.intValue();
        }
        if (value == null) {
            return 0;
        }
        try {
            return Integer.parseInt(String.valueOf(value));
        } catch (NumberFormatException ignored) {
            return 0;
        }
    }

    private static String confidence(String finalDecision) {
        return switch (finalDecision) {
            case "ACCEPT" -> "HIGH";
            case "ACCEPT_WITH_NOTES" -> "MEDIUM";
            case "REJECT" -> "LOW";
            default -> "UNKNOWN";
        };
    }

    private static Object defaultValueFor(String key) {
        return switch (key) {
            case "must_fix", "open_risks", "changed_files" -> List.of();
            default -> "";
        };
    }

    private static Instant lastModified(Path path) {
        try {
            return Files.readAttributes(path, BasicFileAttributes.class).lastModifiedTime().toInstant();
        } catch (IOException ignored) {
            return Instant.EPOCH;
        }
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    private static String text(Object value, String fallback) {
        return value == null ? fallback : String.valueOf(value);
    }

    private static String safeRelative(Path root, Path path) {
        var normalizedRoot = root.toAbsolutePath().normalize();
        var normalizedPath = path.toAbsolutePath().normalize();
        if (normalizedPath.startsWith(normalizedRoot)) {
            return normalizedRoot.relativize(normalizedPath).toString();
        }
        return normalizedPath.toString();
    }

    private static int sizeOf(Object value) {
        return value instanceof List<?> list ? list.size() : 0;
    }

    static final class WorkstreamQueryException extends RuntimeException {
        WorkstreamQueryException(IOException cause) {
            super(cause);
        }
    }
}

package dev.dual.server;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Map;

@Service
public class SchedulerService {
    private final WorkstreamQueryService queryService;
    private final WorkstreamActionService actionService;
    private final SchedulerPolicy schedulerPolicy;

    @Autowired
    public SchedulerService(WorkstreamQueryService queryService, WorkstreamActionService actionService) {
        this(queryService, actionService, new SchedulerPolicy());
    }

    SchedulerService(WorkstreamQueryService queryService, WorkstreamActionService actionService, SchedulerPolicy schedulerPolicy) {
        this.queryService = queryService;
        this.actionService = actionService;
        this.schedulerPolicy = schedulerPolicy;
    }

    @SuppressWarnings("unchecked")
    public Map<String, Object> tick(Path workspaceRoot, int maxWorkstreams, int maxStepsPerWorkstream) throws Exception {
        return tick(workspaceRoot, maxWorkstreams, maxStepsPerWorkstream, false);
    }

    @SuppressWarnings("unchecked")
    public Map<String, Object> tick(
            Path workspaceRoot,
            int maxWorkstreams,
            int maxStepsPerWorkstream,
            boolean autoRecover
    ) throws Exception {
        validatePositive(maxWorkstreams, "maxWorkstreams");
        validatePositive(maxStepsPerWorkstream, "maxStepsPerWorkstream");

        var summaries = (java.util.List<Map<String, Object>>) queryService.list(workspaceRoot).get("workstreams");
        var items = new ArrayList<SchedulerWorkstreamResult>();
        for (var summary : summaries) {
            if (items.size() >= maxWorkstreams) {
                break;
            }
            items.add(tickWorkstream(workspaceRoot, summary, maxStepsPerWorkstream, autoRecover));
        }
        return new SchedulerTickResult(workspaceRoot, maxWorkstreams, maxStepsPerWorkstream, autoRecover, items).toMap();
    }

    private SchedulerWorkstreamResult tickWorkstream(
            Path workspaceRoot,
            Map<String, Object> summary,
            int maxStepsPerWorkstream,
            boolean autoRecover
    ) throws Exception {
        var workstreamId = text(summary.get("workstreamId"));
        var statusSource = text(summary.get("statusSource"));
        if (!"workflow_current".equals(statusSource)) {
            return SchedulerWorkstreamResult.skipped(workstreamId, "canonical workflow current is unavailable");
        }
        var status = text(summary.get("status"));
        var assessment = recoveryAssessment(workspaceRoot, workstreamId, status, autoRecover);
        var decision = schedulerPolicy.decide(status, autoRecover, assessment);
        return switch (decision.action()) {
            case RESUME -> resume(workspaceRoot, workstreamId, maxStepsPerWorkstream);
            case AUTO_RECOVER -> autoRecover(workspaceRoot, workstreamId, maxStepsPerWorkstream, decision);
            case SKIP -> SchedulerWorkstreamResult.skipped(workstreamId, decision.reason());
        };
    }

    private Map<String, Object> recoveryAssessment(
            Path workspaceRoot,
            String workstreamId,
            String status,
            boolean autoRecover
    ) {
        if (!autoRecover || !"WAITING_FOR_RECOVERY".equals(status)) {
            return Map.of();
        }
        return queryService.recoveryAssessment(workspaceRoot, workstreamId);
    }

    private SchedulerWorkstreamResult resume(Path workspaceRoot, String workstreamId, int maxStepsPerWorkstream) throws Exception {
        var runResult = actionService.resume(workspaceRoot, workstreamId, maxStepsPerWorkstream);
        return SchedulerWorkstreamResult.resumed(workstreamId, runResult);
    }

    private SchedulerWorkstreamResult autoRecover(
            Path workspaceRoot,
            String workstreamId,
            int maxStepsPerWorkstream,
            SchedulerDecision decision
    ) throws Exception {
        var retryResult = actionService.retry(
                workspaceRoot,
                workstreamId,
                "auto recovery retry from scheduler"
        );
        var runResult = actionService.resume(workspaceRoot, workstreamId, maxStepsPerWorkstream);
        return SchedulerWorkstreamResult.autoRecovered(workstreamId, decision, retryResult, runResult);
    }

    private static void validatePositive(int value, String name) {
        if (value <= 0) {
            throw new IllegalArgumentException(name + " must be positive");
        }
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }
}

package dev.dual.server;

import java.util.Map;

final class SchedulerPolicy {
    private static final String RUNNING = "RUNNING";
    private static final String WAITING_FOR_RECOVERY = "WAITING_FOR_RECOVERY";
    private static final String RECOVERABLE_AGENT_RUNTIME = "recoverable_agent_runtime";
    private static final String RETRY_AFTER_EXTERNAL_FIX = "RETRY_AFTER_EXTERNAL_FIX";

    SchedulerDecision decide(String workflowStatus, boolean autoRecover, Map<String, Object> recoveryAssessment) {
        if (RUNNING.equals(workflowStatus)) {
            return SchedulerDecision.resume();
        }
        if (autoRecover && WAITING_FOR_RECOVERY.equals(workflowStatus)) {
            return recoveryDecision(recoveryAssessment);
        }
        return SchedulerDecision.skip(workflowStatus);
    }

    private SchedulerDecision recoveryDecision(Map<String, Object> assessment) {
        var classification = text(assessment.get("classification"));
        var readiness = text(assessment.get("retryReadiness"));
        if (RECOVERABLE_AGENT_RUNTIME.equals(classification) && RETRY_AFTER_EXTERNAL_FIX.equals(readiness)) {
            return SchedulerDecision.autoRecover(classification, readiness);
        }
        return SchedulerDecision.skip(recoverySkipReason(classification, readiness));
    }

    private static String recoverySkipReason(String classification, String readiness) {
        if (classification.isBlank() && readiness.isBlank()) {
            return "recovery:not_assessed";
        }
        return "recovery:" + classification + "/" + readiness;
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }
}

package dev.dual.server;

import java.util.LinkedHashMap;
import java.util.Map;

record SchedulerWorkstreamResult(
        String workstreamId,
        String result,
        String status,
        String activeNode,
        String message,
        String reason,
        String retryAction,
        String recoveryClassification,
        String retryReadiness
) {
    static SchedulerWorkstreamResult resumed(String workstreamId, Map<String, Object> runResult) {
        return new SchedulerWorkstreamResult(
                workstreamId,
                "resumed",
                text(runResult.get("status")),
                text(runResult.get("activeNode")),
                text(runResult.get("message")),
                "",
                "",
                "",
                ""
        );
    }

    static SchedulerWorkstreamResult autoRecovered(
            String workstreamId,
            SchedulerDecision decision,
            Map<String, Object> retryResult,
            Map<String, Object> runResult
    ) {
        return new SchedulerWorkstreamResult(
                workstreamId,
                "auto_recovered",
                text(runResult.get("status")),
                text(runResult.get("activeNode")),
                text(runResult.get("message")),
                "",
                text(retryResult.get("action")),
                decision.recoveryClassification(),
                decision.retryReadiness()
        );
    }

    static SchedulerWorkstreamResult skipped(String workstreamId, String reason) {
        return new SchedulerWorkstreamResult(
                workstreamId,
                "skipped",
                "",
                "",
                "",
                reason,
                "",
                "",
                ""
        );
    }

    Map<String, Object> toMap() {
        var map = new LinkedHashMap<String, Object>();
        map.put("workstreamId", workstreamId);
        map.put("result", result);
        putIfPresent(map, "status", status);
        putIfPresent(map, "activeNode", activeNode);
        putIfPresent(map, "message", message);
        putIfPresent(map, "reason", reason);
        putIfPresent(map, "retryAction", retryAction);
        putIfPresent(map, "recoveryClassification", recoveryClassification);
        putIfPresent(map, "retryReadiness", retryReadiness);
        return map;
    }

    private static void putIfPresent(Map<String, Object> map, String key, String value) {
        if (value != null && !value.isBlank()) {
            map.put(key, value);
        }
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }
}

