for (const element of [els.newTaskName, els.newTaskRepo, els.newTaskDescription, els.newTaskLanguage, els.newTaskMode, els.newTaskLifecycle, els.newTaskMaxSteps]) {
  element.addEventListener("input", updateNewTaskCommand);
  element.addEventListener("change", updateNewTaskCommand);
}
els.copyNewTaskCommand.addEventListener("click", () => copyText(els.newTaskCommand.textContent));

switchView(state.view);
renderWorkspace();
renderLifecycle();
loadWorkspaceRegistry().then(refreshList);

:root {
  color-scheme: light;
  --bg: #f4f6f9;
  --surface: #ffffff;
  --surface-2: #fbfcfe;
  --border: #e7eaf0;
  --border-strong: #d7dde7;
  --text: #15202e;
  --text-2: #566073;
  --muted: #8a93a3;
  --brand: #2563eb;
  --brand-dark: #1d4fd1;
  --brand-soft: #eef4ff;
  --ok: #16a34a;
  --ok-soft: #e7f6ee;
  --warn: #d97706;
  --warn-soft: #fdf2e2;
  --bad: #dc2626;
  --bad-soft: #fdeceb;
  --dark: #101828;
  --shadow: 0 1px 2px rgba(16, 24, 40, 0.05), 0 1px 3px rgba(16, 24, 40, 0.06);
  --shadow-lg: 0 12px 34px rgba(16, 24, 40, 0.10);
  --radius: 14px;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
}

body {
  min-width: 1280px;
  background: var(--bg);
  color: var(--text);
  font: 14px/1.55 -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", Inter, sans-serif;
  -webkit-font-smoothing: antialiased;
}

button,
input,
textarea,
select {
  font: inherit;
}

button {
  cursor: pointer;
  border: 1px solid transparent;
  border-radius: 9px;
}

a {
  color: var(--brand);
  text-decoration: none;
}

.app {
  width: 100%;
  min-height: 100vh;
  margin: 0;
  padding: 20px 22px 48px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.logo {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, #2563eb, #5b8def);
  color: #fff;
  font-size: 18px;
  font-weight: 800;
  box-shadow: 0 4px 12px rgba(37, 107, 235, 0.35);
}

.brand-name {
  font-size: 16px;
  font-weight: 700;
}

.brand-sub {
  font-size: 12px;
  color: var(--muted);
}

.top-right {
