  align-items: center;
  gap: 7px;
  font-size: 12px;
  color: var(--text-2);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 6px 12px;
  box-shadow: var(--shadow);
}

.conn i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ok);
  box-shadow: 0 0 0 3px var(--ok-soft);
}

.conn.warn i {
  background: var(--warn);
  box-shadow: 0 0 0 3px var(--warn-soft);
}

.conn.bad i {
  background: var(--bad);
  box-shadow: 0 0 0 3px var(--bad-soft);
}

.seg {
  display: flex;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 3px;
  box-shadow: var(--shadow);
}

.seg button {
  border: 0;
  background: transparent;
  color: var(--text-2);
  font-size: 12px;
  font-weight: 700;
  padding: 6px 12px;
  border-radius: 999px;
}

.seg button.active {
