  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.sidebar {
  padding: 14px;
  position: sticky;
  top: 20px;
  height: calc(100vh - 40px);
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.workspace-card {
  display: grid;
  gap: 10px;
  margin-bottom: 14px;
  padding: 12px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 12px;
}

.workspace-title,
.workspace-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.workspace-title span:first-child {
