}

.task-tools {
  display: flex;
  gap: 8px;
  margin-bottom: 10px;
}

.task-tools .btn {
  flex: 1;
  justify-content: center;
}

.task-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-height: 0;
  overflow: auto;
  padding-right: 2px;
}

.task {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
  padding: 10px 11px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  text-align: left;
  transition: 120ms ease;
}

.task:hover {
  background: var(--surface-2);
}

.task.active {
  background: var(--brand-soft);
  border-color: #cfe0ff;
}

.task .t {
  color: var(--text);
