}

.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex: 0 0 auto;
}

.dot.warn {
  background: var(--warn);
}

.dot.info {
  background: var(--brand);
}

.dot.bad {
  background: var(--bad);
}

.dot.ok {
  background: var(--ok);
}

.btn {
  min-height: 38px;
  padding: 0 16px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 13.5px;
  font-weight: 650;
  transition: 120ms ease;
}

.btn.primary {
  background: var(--brand);
  color: #fff;
  box-shadow: 0 1px 2px rgba(37, 107, 235, 0.3);
}

.btn.primary:hover {
  background: var(--brand-dark);
}

.btn.ghost {
  background: #fff;
  color: var(--text);
  border-color: var(--border-strong);
}

.btn.subtle {
  background: var(--surface-2);
  color: var(--text-2);
  border-color: var(--border);
}

.btn.danger {
  background: var(--bad);
  color: #fff;
}

.btn.sm {
  min-height: 32px;
  padding: 0 12px;
  font-size: 12.5px;
}

.new-task {
  width: 100%;
}

.task-pager {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--border);
  color: var(--muted);
  font-size: 12px;
}

.main {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}

.operator,
.management {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.decision {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 360px;
  gap: 16px;
  align-items: stretch;
  min-width: 0;
}

.decision > * {
  min-width: 0;
}

.token-summary {
  display: flex;
  min-width: 0;
}

.token-summary > .card {
  width: 100%;
  height: 100%;
}

.operator.hidden,
.management {
  display: none;
}

.management.active {
  display: flex;
}

.task-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.eyebrow {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.7px;
}

.task-head h1 {
  margin: 4px 0 6px;
  font-size: 23px;
  line-height: 1.25;
  font-weight: 720;
}

.task-sub {
  color: var(--muted);
  font-size: 12.5px;
}

.task-sub b {
  color: var(--text-2);
  font-weight: 600;
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 13px;
  border-radius: 999px;
  white-space: nowrap;
  font-size: 13px;
  font-weight: 650;
}

.pill.warn,
.small-pill.warn {
  background: var(--warn-soft);
  color: #9a5800;
}

.pill.info,
.small-pill.info {
  background: var(--brand-soft);
  color: #1c4ec4;
}

.pill.bad,
.small-pill.bad {
  background: var(--bad-soft);
  color: #b3221a;
}

.pill.ok,
.small-pill.ok {
  background: var(--ok-soft);
  color: #0f7a37;
}

.pill.muted,
.small-pill.muted {
  background: #eef1f5;
  color: var(--text-2);
}

.lifecycle,
.card {
  padding: 18px;
}

.lc-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.lc-head h2,
.card h3 {
  margin: 0 0 4px;
  font-size: 14.5px;
  font-weight: 700;
}

.cap {
  margin-bottom: 14px;
  color: var(--muted);
  font-size: 12px;
