.stages {
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr));
  gap: 0;
}

.stage {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  padding: 0 4px 4px;
}

.stage:not(:last-child)::after {
  content: "";
  position: absolute;
  top: 13px;
  left: calc(50% + 14px);
  right: calc(-50% + 14px);
  height: 2px;
  background: var(--border-strong);
}

.stage.done:not(:last-child)::after {
  background: var(--ok);
}

.node {
  width: 28px;
  height: 28px;
  border: 2px solid var(--border-strong);
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #fff;
  color: var(--muted);
  position: relative;
  z-index: 1;
  font-size: 12px;
  font-weight: 700;
}

.stage.done .node {
  background: var(--ok);
  border-color: var(--ok);
  color: #fff;
}

.stage.current .node {
  background: var(--brand);
  border-color: var(--brand);
  color: #fff;
  box-shadow: 0 0 0 4px var(--brand-soft);
}

.stage.recovery .node {
  background: var(--bad);
  border-color: var(--bad);
  color: #fff;
}

.stage.recovery:not(:last-child)::after {
  background: var(--bad);
}

.stage:focus-visible {
  outline: 3px solid rgba(37, 107, 235, 0.22);
  outline-offset: 4px;
  border-radius: 12px;
}

.stage .lab {
  color: var(--text-2);
  font-size: 12.5px;
  font-weight: 600;
}

.stage .sub {
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.3;
}

.stage .roles {
  min-height: 14px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.25;
}

.stage[aria-pressed="true"] .lab {
  color: var(--brand-dark);
}

.stage[aria-pressed="true"] .node {
  box-shadow: 0 0 0 4px var(--brand-soft);
