}

.flow-start {
  position: absolute;
  width: 48px;
  height: 48px;
  border: 2px solid var(--border-strong);
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #fff;
  color: var(--text-2);
  font-weight: 850;
  box-shadow: var(--shadow);
}

.flow-start span {
  position: absolute;
  top: 52px;
  color: var(--muted);
  font-size: 11px;
  white-space: nowrap;
}

.flow-node {
  position: absolute;
  width: var(--flow-node-width, 260px);
  min-height: 132px;
  padding: 12px;
  border: 1.5px solid var(--border);
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.06), 0 7px 18px rgba(16, 24, 40, 0.06);
  text-align: left;
  color: inherit;
