}

.flow-node.claude {
  border-color: #bcd4ff;
}

.flow-node.router {
  border-color: #f1cf98;
  background: #fffaf1;
}

.flow-node.codex {
  border-color: #dac9ff;
}

.flow-node.human {
  border-color: #d7dce8;
  background: #fbfcff;
}

.flow-node.final {
  width: 162px;
  min-height: 100px;
  border-color: #bce8ca;
}

.flow-node-head {
  display: flex;
  align-items: center;
