  border: 1px solid var(--border);
  border-radius: 999px;
  background: #fff;
  padding: 6px 12px;
  box-shadow: var(--shadow);
  color: var(--text-2);
  font-size: 12px;
  font-weight: 850;
}

.flow-flag.reject,
.flow-flag.revise,
.flow-flag.recovery {
  color: var(--bad);
}

.flow-flag.pass {
