.flow-inspector-doc section {
  border-top: 1px solid var(--border);
  padding: 10px 0;
}

.flow-inspector-doc section:first-of-type {
  padding-top: 0;
  border-top: 0;
}

.flow-inspector-doc h4 {
  margin: 0 0 4px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.flow-inspector-doc p {
  margin: 0;
  color: var(--text);
  font-size: 13px;
  line-height: 1.5;
  overflow-wrap: anywhere;
}

.flow-empty {
  border: 1px dashed var(--border-strong);
  border-radius: 12px;
  background: var(--surface-2);
  color: var(--muted);
  padding: 18px;
}

.primary-card {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px 24px;
  box-shadow: var(--shadow-lg);
}

.primary-card.waiting {
  background: linear-gradient(180deg, #fffaf0, #fff);
  border-color: #f3d9a8;
}

.primary-card.recovery {
  background: linear-gradient(180deg, #fff5f4, #fff);
  border-color: #f3c4c0;
}

.primary-card.running {
  background: linear-gradient(180deg, #f3f8ff, #fff);
  border-color: #cfe0ff;
}

.primary-card.completed {
  background: linear-gradient(180deg, #f1faf4, #fff);
  border-color: #bfe6cc;
}

.primary-card .eb {
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--brand-soft);
  color: var(--brand-dark);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.8px;
  text-transform: uppercase;
}

.primary-card h2 {
  margin: 10px 0 8px;
  font-size: 19px;
  line-height: 1.3;
  font-weight: 720;
}

.why {
  max-width: 72ch;
  margin: 0 0 16px;
  color: var(--text-2);
  font-size: 14px;
  line-height: 1.6;
}

.next {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 16px;
  border: 1px solid #dbe7ff;
  border-radius: 10px;
  background: rgba(37, 107, 235, 0.06);
  padding: 10px 14px;
  font-size: 13px;
}

.next .k {
  color: var(--brand-dark);
  font-weight: 700;
  white-space: nowrap;
}

.revision-box {
  margin: 0 0 16px;
}

.revision-box label {
  display: block;
  margin-bottom: 7px;
  color: var(--text-2);
  font-size: 12px;
  font-weight: 800;
}

.revision-box textarea {
  width: 100%;
  min-height: 92px;
  resize: vertical;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: #fff;
  padding: 11px 12px;
  color: var(--text);
  line-height: 1.55;
}

.revision-box textarea:focus {
  border-color: var(--brand);
  box-shadow: 0 0 0 3px rgba(37, 107, 235, 0.12);
  outline: none;
}

.primary-actions,
.cmd-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.loop-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 16px;
}

.grid2 {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr);
  gap: 16px;
}

.grid3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.kv {
  display: grid;
  grid-template-columns: 128px 1fr;
  gap: 8px 14px;
  padding: 7px 0;
  border-top: 1px solid #eef1f5;
  font-size: 13px;
}

.kv:first-of-type {
  border-top: 0;
  padding-top: 0;
}

.kv .k {
  color: var(--muted);
  font-weight: 600;
}

.kv .v {
  color: var(--text);
  overflow-wrap: anywhere;
}

.clean {
  display: flex;
  flex-direction: column;
  gap: 7px;
  list-style: none;
  margin: 6px 0 0;
  padding: 0;
}

.clean li {
  position: relative;
  padding-left: 20px;
  color: var(--text-2);
  font-size: 13px;
  line-height: 1.5;
}

#evidence .clean li {
  overflow-wrap: anywhere;
}

.clean li::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 8px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--brand);
}

.token-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(112px, 1fr));
  gap: 10px;
}

.token {
  border: 1px solid var(--border);
  border-radius: 11px;
  background: var(--surface-2);
  padding: 12px;
}

.token .k {
  color: var(--muted);
  font-size: 11.5px;
  font-weight: 700;
}

.token .v {
  margin-top: 4px;
  font-size: 18px;
  font-weight: 760;
}

.token .s {
  color: var(--muted);
  font-size: 11px;
}

.token-runs {
  display: grid;
  gap: 6px;
  margin-top: 12px;
}

.token-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 72px 80px;
  gap: 8px;
  align-items: center;
  border: 1px solid var(--border);
  border-radius: 9px;
  background: #fff;
  padding: 7px 9px;
  color: var(--text-2);
  font-size: 12px;
}

.token-row span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.token-row strong {
  color: var(--text);
  text-align: right;
}

.budget {
  height: 7px;
  margin-top: 10px;
  border-radius: 99px;
  background: #edf1f6;
  overflow: hidden;
}

.budget i {
  display: block;
  width: 0;
  height: 100%;
  border-radius: 99px;
  background: linear-gradient(90deg, #16a34a, #2563eb);
}

.loop-line {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.loop-item {
  display: grid;
  grid-template-columns: 96px 1fr auto;
  gap: 12px;
  align-items: start;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface-2);
  padding: 10px;
}

.loop-item strong {
  display: block;
  font-size: 13px;
}

.loop-item span {
  color: var(--muted);
  font-size: 12px;
}

.small-pill {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 4px 8px;
  font-size: 11px;
  font-weight: 800;
}

.rca-step {
  border-left: 4px solid var(--brand);
  border-radius: 10px;
  background: var(--surface-2);
  padding: 12px;
}

.rca-step.warn {
  border-left-color: var(--warn);
}

.rca-step.bad {
  border-left-color: var(--bad);
}

.rca-step.ok {
  border-left-color: var(--ok);
}

.rca-step strong {
  display: block;
  margin-bottom: 4px;
}

.rca-step p {
  margin: 0;
  color: var(--text-2);
  font-size: 12.5px;
}

.cmd {
  margin: 8px 0 0;
  border-radius: 9px;
  background: var(--dark);
  color: #e5edf7;
  padding: 11px 13px;
  white-space: pre-wrap;
  font: 12px/1.6 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

.diag-dark {
  border: 1px solid #222b3a;
  border-radius: 14px;
  background: var(--dark);
  color: #dfe7f1;
  box-shadow: var(--shadow);
  overflow: hidden;
}

.diag-dark h3 {
  margin: 0;
  padding: 14px 16px;
  border-bottom: 1px solid #222b3a;
  color: #fff;
  font-size: 14px;
}

.diag-dark pre {
  margin: 0;
  padding: 14px 16px;
  white-space: pre-wrap;
  font: 12px/1.55 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

.foot-note {
  margin-top: 22px;
  color: var(--muted);
  font-size: 12px;
  text-align: center;
  line-height: 1.6;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 10;
  display: none;
  align-items: center;
  justify-content: center;
  background: rgba(15, 23, 42, 0.38);
  padding: 28px;
}

.modal-backdrop.active {
  display: flex;
}

.modal {
  width: 900px;
  max-height: 92vh;
  overflow: auto;
  border: 1px solid var(--border);
  border-radius: 18px;
  background: #fff;
  box-shadow: 0 30px 80px rgba(15, 23, 42, 0.30);
}

.modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 22px 24px;
  border-bottom: 1px solid var(--border);
}

.modal-head h2 {
  margin: 0;
  font-size: 20px;
}

.modal-head p {
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.modal-body {
  display: grid;
  gap: 16px;
  padding: 20px 24px;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.field {
  display: grid;
  gap: 7px;
}

.field.full {
  grid-column: 1 / -1;
}

.field span {
  color: var(--text-2);
  font-size: 12px;
  font-weight: 700;
}

.field em {
  color: var(--muted);
  font-size: 12px;
  font-style: normal;
}

.field input,
.field textarea,
.field select {
  border: 1px solid var(--border-strong);
  border-radius: 10px;
  background: #fff;
  color: var(--text);
  padding: 10px 12px;
}

.field textarea {
  min-height: 120px;
  resize: vertical;
}

.modal-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-top: 1px solid var(--border);
  background: var(--surface-2);
  padding: 18px 24px;
}

.modal-foot span {
  color: var(--muted);
  font-size: 12px;
}

.command-preview {
  box-shadow: none;
}

.empty {
  color: var(--muted);
  font-size: 13px;
}
.flow-node.selected {
  box-shadow: 0 0 0 4px var(--brand-soft), 0 16px 30px rgba(37, 99, 235, 0.14);
}

.flow-node:focus-visible {
  outline: 3px solid rgba(37, 99, 235, 0.22);
  outline-offset: 3px;
}

dual-server/src/main/resources/static/mg:
:root {
  color-scheme: light;
  --bg: #f6f7f9;
  --panel: #ffffff;
  --text: #1d2430;
  --muted: #667085;
  --line: #d9dee7;
  --accent: #1769aa;
  --accent-dark: #0f4f86;
  --ok: #147a42;
  --warn: #a15c00;
  --bad: #b42318;
  --shadow: 0 1px 2px rgba(16, 24, 40, 0.06);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

button,
input,
textarea {
  font: inherit;
}

button {
  min-height: 36px;
  border: 1px solid var(--accent);
  border-radius: 6px;
  background: var(--accent);
  color: #fff;
  padding: 0 12px;
  cursor: pointer;
}

button:hover {
  background: var(--accent-dark);
}

button.secondary {
  background: #fff;
  color: var(--accent);
}

button.secondary:hover {
  background: #f2f8fd;
}

button.danger {
  border-color: var(--bad);
  background: var(--bad);
}

button.danger:hover {
  background: #8f1f16;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.shell {
  max-width: 1500px;
  margin: 0 auto;
  padding: 20px;
}

.topbar,
.toolbar,
.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: var(--shadow);
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 20px;
}

.top-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  font-size: 22px;
  line-height: 1.2;
}

h2 {
  font-size: 15px;
  line-height: 1.3;
}

p,
.subtle {
  color: var(--muted);
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 12px;
  margin: 16px 0;
  padding: 14px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
}

.field-grow {
  flex: 1 1 420px;
  min-width: 260px;
}

.workspace-picker {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: end;
}

.workspace-card {
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #fff;
  padding: 8px 10px;
}

.workspace-card strong,
.workspace-card span {
  display: block;
  overflow-wrap: anywhere;
}

.workspace-card strong {
  font-size: 13px;
}

.workspace-card span {
  margin-top: 4px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.4;
}

.workspace-chooser {
  position: fixed;
  z-index: 50;
  left: 50%;
  top: 50%;
  width: min(760px, calc(100vw - 32px));
  max-height: min(720px, calc(100vh - 32px));
  transform: translate(-50%, -50%);
  display: grid;
  gap: 10px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: #fff;
  box-shadow: 0 20px 60px rgba(16, 24, 40, 0.22);
  padding: 14px;
  overflow: auto;
}

.workspace-chooser::before {
  content: "";
  position: fixed;
  z-index: -1;
  inset: -100vh -100vw;
  background: rgba(16, 24, 40, 0.36);
}

.workspace-chooser-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid var(--line);
  padding-bottom: 12px;
}

.workspace-chooser-head strong,
.workspace-chooser-head span {
  display: block;
}

.workspace-chooser-head strong {
  font-size: 16px;
}

.workspace-chooser-head span {
  margin-top: 4px;
  color: var(--muted);
  font-size: 12px;
}

.path-row,
.path-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
}

.workspace-browser {
  display: grid;
  gap: 6px;
  max-height: 360px;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #fff;
  padding: 8px;
}

.workspace-browser-header {
  display: grid;
  gap: 4px;
  border-bottom: 1px solid #edf0f4;
  padding-bottom: 8px;
  margin-bottom: 2px;
}

.workspace-browser-header strong,
.workspace-browser-header span {
  overflow-wrap: anywhere;
}

.workspace-browser button {
  justify-content: flex-start;
  min-height: 32px;
  border-color: var(--line);
  background: #fff;
  color: var(--text);
  text-align: left;
}

.workspace-browser button:hover {
  border-color: var(--accent);
  background: #f2f8fd;
}

.action-field .subtle {
  font-size: 11px;
}

.action-field {
  flex: 0 1 220px;
  min-width: 200px;
}

.action-field button {
  width: 100%;
}

.advanced-controls {
  flex: 1 1 100%;
  border-top: 1px solid #edf0f4;
  padding-top: 10px;
}

.advanced-controls summary {
  width: max-content;
  cursor: pointer;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.advanced-control-grid {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 12px;
  margin-top: 10px;
}

.compact {
  width: 100px;
}

.recovery-toggle {
  flex: 0 1 190px;
  min-width: 180px;
}

.checkbox-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.25;
}

.checkbox-row input {
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
}

input,
textarea {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 6px;
  color: var(--text);
  background: #fff;
  padding: 8px 10px;
}

textarea {
  resize: vertical;
}

.layout {
  display: grid;
  grid-template-columns: minmax(260px, 320px) minmax(0, 1fr);
  gap: 16px;
  align-items: start;
}

.panel {
  padding: 14px;
}

.panel-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
}

.list-panel {
  position: sticky;
  top: 16px;
}

.workstreams {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.workstream {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
  padding: 10px;
  text-align: left;
}

.workstream:hover,
.workstream.active {
  border-color: var(--accent);
  background: #f2f8fd;
}

.workstream strong {
  display: block;
  font-size: 13px;
  overflow-wrap: anywhere;
}

.workstream span {
  display: block;
  color: var(--muted);
  font-size: 12px;
  margin-top: 3px;
}

.main-panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.progress-panel {
  padding: 18px;
  border-color: #c9d9ea;
}

.progress-panel .panel-title h2 {
  font-size: 18px;
}

.progress {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(118px, 1fr));
  gap: 8px;
}

.stage {
  position: relative;
  min-height: 96px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: #fff;
  padding: 12px 9px;
  cursor: pointer;
  transition: border-color 120ms ease, box-shadow 120ms ease, transform 120ms ease;
}

.stage:hover,
.stage:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(23, 105, 170, 0.12);
  outline: none;
}

.stage:active {
  transform: translateY(1px);
}

.stage:not(:last-child)::after {
  content: "";
  position: absolute;
  top: 34px;
  right: -9px;
  width: 9px;
  border-top: 2px solid #b8c0cc;
}

.stage.done {
  border-color: #a9dec2;
  background: #edf8f2;
}

.stage.current {
  border-color: #e3aa4d;
  background: #fff6e8;
}

.stage.pending {
  background: #fbfcfd;
}

.stage strong,
.stage span,
.stage small {
  display: block;
  text-align: center;
}

.stage strong {
  font-size: 13px;
  line-height: 1.25;
}

.stage span {
  margin-top: 7px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.25;
}

.stage small {
  margin-top: 8px;
  color: #475467;
  font-size: 10px;
  line-height: 1.3;
}

.stage.selected {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(23, 105, 170, 0.16);
}

.node-inspector {
  margin-top: 14px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: #fbfcfe;
  padding: 12px;
}

.node-inspector-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.node-inspector h3 {
  margin: 0;
  font-size: 15px;
  line-height: 1.3;
}

.node-list {
  display: grid;
  gap: 8px;
}

.node-card {
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #fff;
  padding: 10px;
}

.node-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.node-card-head strong {
  font-size: 13px;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.node-detail-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 8px;
}

.node-detail-grid div {
  border-top: 1px solid #edf0f5;
  padding-top: 7px;
}

.node-detail-grid span {
  display: block;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.node-detail-grid p {
  margin-top: 3px;
  color: var(--text);
  font-size: 12px;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.node-gate-action {
  margin-top: 10px;
}

.gate-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(300px, 0.7fr);
  gap: 16px;
  align-items: start;
}

.gate-grid-single {
  grid-template-columns: 1fr;
}

.gate-grid-single .current-node {
  grid-column: 1 / -1;
}

.gate-grid-history {
  grid-template-columns: 1fr;
}

.gate-grid-history #reviewPanel {
  grid-column: 1 / -1;
}

.current-node {
  display: grid;
  gap: 12px;
}

.callout,
.decision-panel,
.operation-strip,
.debug-grid .overview-split section {
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #fff;
  padding: 12px;
}

.callout {
  border-left: 4px solid var(--warn);
  background: #fffdf8;
}

.callout p,
.debug-text {
  margin-top: 6px;
  color: var(--text);
  font-size: 13px;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.decision-panel {
  display: grid;
  gap: 10px;
}

.decision-actions {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 8px;
  align-items: start;
}

.operation-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding-top: 10px;
  border-color: #eef1f5;
}

.operation-strip button {
  min-height: 32px;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}

.hint {
  margin-bottom: 12px;
  color: var(--muted);
  font-size: 13px;
}

.overview-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 10px;
  margin-bottom: 12px;
}

.metrics-grid {
  margin-bottom: 0;
}

.overview-card,
.overview-row section,
.overview-split section,
.overview-attention {
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #fff;
  padding: 12px;
}

.overview-card span,
.eyebrow,
.mini-title {
  display: block;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.overview-card strong {
  display: block;
  margin-top: 6px;
  font-size: 18px;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.overview-row,
.overview-split {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 10px;
  margin-bottom: 12px;
}

.overview-row p {
  margin-top: 6px;
  color: var(--text);
  font-size: 13px;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.mini-list {
  display: grid;
  gap: 8px;
  margin-top: 8px;
  color: var(--muted);
  font-size: 12px;
}

.overview-attention {
  margin-bottom: 12px;
}

.attention-list {
  display: grid;
  gap: 8px;
  margin-top: 8px;
  color: var(--muted);
  font-size: 12px;
}

.attention-item {
  border-left: 3px solid var(--line);
  padding: 8px 10px;
  background: #fbfcfe;
}

.attention-item strong {
  display: block;
  color: var(--text);
  font-size: 13px;
  margin-bottom: 3px;
}

.attention-item p {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

.attention-item code {
  display: block;
  margin-top: 6px;
  color: var(--text);
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 11px;
  overflow-wrap: anywhere;
}

.attention-critical {
  border-left-color: var(--bad);
}

.attention-warning {
  border-left-color: var(--warn);
}

.attention-ok {
  border-left-color: var(--ok);
}

.attention-info {
  border-left-color: var(--accent);
}

.mini-item {
  display: grid;
  gap: 3px;
  border-top: 1px solid #edf0f5;
  padding-top: 8px;
}

.mini-item:first-child {
  border-top: 0;
  padding-top: 0;
}

.mini-item strong {
  color: var(--text);
  font-size: 12px;
  overflow-wrap: anywhere;
}

.mini-item span {
  overflow-wrap: anywhere;
}

.muted-item strong,
.muted-item span {
  color: var(--muted);
}

.hidden {
  display: none !important;
}

.debug-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 10px;
  margin-bottom: 12px;
}

.grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 16px;
}

.json,
.timeline,
.markdown {
  min-height: 260px;
  max-height: 520px;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #101828;
  color: #eef4ff;
  padding: 12px;
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 12px;
  line-height: 1.5;
}

.debug-panel {
  padding: 0;
  overflow: hidden;
}

.debug-panel summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 48px;
  padding: 0 14px;
  cursor: pointer;
  list-style: none;
}

.debug-panel summary::-webkit-details-marker {
  display: none;
}

.debug-panel summary span {
  font-size: 15px;
  font-weight: 700;
}

.debug-panel summary em {
  color: var(--muted);
  font-size: 12px;
  font-style: normal;
}

.debug-panel[open] {
  padding: 0 14px 14px;
}

.debug-panel[open] summary {
  margin: 0 -14px 12px;
  border-bottom: 1px solid var(--line);
}

.markdown {
  background: #fff;
  color: var(--text);
  white-space: pre-wrap;
}

.timeline {
  background: #fff;
  color: var(--text);
  font-family: inherit;
}

.iteration {
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow: hidden;
  background: #fff;
  margin-bottom: 10px;
}

.iteration-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 10px 12px;
  background: #f8fafc;
  border-bottom: 1px solid var(--line);
}

.timeline-item {
  display: grid;
  grid-template-columns: minmax(160px, 1.1fr) minmax(0, 1.2fr) minmax(90px, 0.6fr) minmax(180px, 1fr) minmax(80px, 0.5fr);
  gap: 10px;
  align-items: center;
  padding: 10px 12px;
  border-bottom: 1px solid #eef1f5;
}

.timeline-item:last-child {
  border-bottom: 0;
}

.timeline-item strong,
.timeline-item span {
  overflow-wrap: anywhere;
}

.timeline-item strong {
  display: block;
  font-size: 13px;
}

.timeline-item span {
  display: block;
  color: var(--muted);
  font-size: 12px;
  margin-top: 2px;
}

.artifact-list {
  display: grid;
  gap: 10px;
}

.artifact-item {
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 12px;
  background: #fff;
}

.artifact-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}

.artifact-head strong {
  font-size: 13px;
  overflow-wrap: anywhere;
}

.artifact-item p,
.artifact-line p {
  font-size: 13px;
  line-height: 1.45;
}

.artifact-line {
  display: grid;
  grid-template-columns: 110px minmax(0, 1fr);
  gap: 8px;
  margin-top: 8px;
}

.artifact-line span,
.artifact-ref {
  color: var(--muted);
  font-size: 12px;
}

.artifact-ref {
  display: block;
  margin-top: 10px;
  overflow-wrap: anywhere;
}

.review-structured {
  display: grid;
  gap: 8px;
}

.packet-list {
  display: grid;
  gap: 8px;
}

.review-card {
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #fff;
  padding: 12px;
  overflow: hidden;
}

.review-card-primary {
  border-color: #b8d4ea;
  background: #f7fbff;
}

.review-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
}

.review-card h3 {
  margin: 0 0 10px;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.review-card-primary h3 {
  margin-bottom: 0;
  font-size: 15px;
}

.review-card p,
.review-card li {
  color: var(--text);
  font-size: 13px;
  line-height: 1.5;
}

.review-card ul {
  margin: 0;
  padding-left: 18px;
}

.review-row {
  display: grid;
  grid-template-columns: minmax(150px, 220px) minmax(0, 1fr);
  gap: 10px;
  padding: 8px 0;
  border-top: 1px solid #edf0f4;
}

.review-row > * {
  min-width: 0;
}

.review-row:first-of-type {
  border-top: 0;
  padding-top: 0;
}

.review-row span,
.eyebrow {
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.eyebrow {
  display: block;
  margin-bottom: 4px;
  text-transform: uppercase;
