}

.review-row p {
  overflow-wrap: anywhere;
}

.review-row pre {
  margin: 0;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #101828;
  color: #eef4ff;
  padding: 10px;
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 12px;
  line-height: 1.5;
}

.raw-packet {
  margin-top: 12px;
}

.raw-packet summary {
  cursor: pointer;
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
}

.raw-packet .markdown {
  margin-top: 10px;
}

.badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  border-radius: 999px;
  padding: 0 10px;
  font-size: 12px;
  font-weight: 700;
  color: #fff;
  background: var(--accent);
}

.badge.ok {
  background: var(--ok);
}

.badge.warn {
  background: var(--warn);
}

.badge.bad {
  background: var(--bad);
}

.badge.muted {
