}

@media (max-width: 900px) {
  .layout,
  .grid,
  .gate-grid,
  .debug-grid,
  .overview-grid,
  .overview-row,
  .overview-split {
    grid-template-columns: 1fr;
  }

  .toolbar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .toolbar .field-grow,
  .toolbar .action-field,
  .toolbar .advanced-controls {
    grid-column: 1 / -1;
  }

  .toolbar > button {
    min-width: 0;
    width: 100%;
  }

  .compact {
    width: auto;
  }

  .list-panel {
    position: static;
  }

  .review-card-head,
  .review-row,
  .timeline-item,
  .decision-actions,
  .path-row,
  .path-actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .stage:not(:last-child)::after {
    display: none;
  }

  .progress {
    grid-template-columns: repeat(2, minmax(0, 1fr));
