    private static WorkstreamSessionCloser recordingCloser(List<String> sink) {
        return (root, workstreamId) -> {
            sink.add(workstreamId);
            return new WorkstreamSessionCloser.CloseSummary(workstreamId, 0, 0, 0);
        };
    }

    private static WorkstreamSessionCloser throwingCloser() {
        return (root, workstreamId) -> {
            throw new RuntimeException("simulated acpx close failure");
        };
    }

    private WorkstreamPaths createWorkstream(String workstreamId, WorkflowDefinition definition) throws Exception {
        var paths = new WorkstreamPaths(tempDir, new DualId(workstreamId));
        Files.createDirectories(paths.workstreamDir());
        new WorkflowFileLedger().initialize(paths, "wf-" + workstreamId, definition);
        return paths;
    }

    private Path writeDeadRun(WorkstreamPaths paths) throws Exception {
        var runJson = paths.runsDir().resolve("run-dead/run.json");
        Files.createDirectories(runJson.getParent());
        var startedAt = Instant.now().minusSeconds(30);
        var run = MAPPER.createObjectNode();
        run.put("schemaVersion", 3);
        run.put("status", "running");
        run.put("runId", "run-dead");
        run.put("workstreamId", paths.workstreamId().value());
        run.put("nodeId", "first");
        run.put("agent", "claude");
        run.put("startedAt", startedAt.toString());
        var attempt = run.putObject("executionAttempt");
        attempt.put("attemptId", "att-dead");
        attempt.put("runId", "run-dead");
        attempt.put("workstreamId", paths.workstreamId().value());
        attempt.put("nodeId", "first");
        attempt.put("agent", "claude");
        attempt.put("status", "RUNNING");
        attempt.put("processStatus", "RUNNING");
        attempt.put("startedAt", startedAt.toString());
        var event = MAPPER.createObjectNode();
        event.put("kind", "process_started");
        event.put("source", "adapter");
        event.put("sequence", 1);
        event.put("observedAt", startedAt.toString());
        event.put("elapsedMs", 0);
        event.putObject("details").put("pid", Long.MAX_VALUE);
        run.putArray("executionTimeline").add(event);
        MAPPER.writerWithDefaultPrettyPrinter().writeValue(runJson.toFile(), run);
        return runJson;
    }

    private static WorkflowDefinition simpleDefinition() {
        return new WorkflowDefinition(
                "api-action-workflow",
                1,
                "first",
                List.of(new NodeDefinition("first", NodeKind.TASK, "noop.task", Map.of())),
                List.of()
        );
    }

    private static WorkflowDefinition gateDefinition() {
        return new WorkflowDefinition(
                "api-action-workflow",
                1,
                "before.gate",
                List.of(
                        new NodeDefinition("before.gate", NodeKind.TASK, "noop.task", Map.of()),
                        new NodeDefinition("gate.review", NodeKind.GATE, "human.review", Map.of()),
                        new NodeDefinition("after.approve", NodeKind.TASK, "noop.task", Map.of())
                ),
                List.of(
                        new EdgeDefinition("before.gate", "completed", "gate.review"),
                        new EdgeDefinition("gate.review", "approved", "after.approve")
                )
        );
    }

    private static WorkflowDefinition completeGateDefinition() {
        return new WorkflowDefinition(
                "api-action-workflow",
                1,
                "before.gate",
                List.of(
                        new NodeDefinition("before.gate", NodeKind.TASK, "noop.task", Map.of()),
                        new NodeDefinition("gate.review", NodeKind.GATE, "human.review",
                                Map.of("allowed_actions", List.of("approve", "revise", "complete")))
                ),
                List.of(
                        new EdgeDefinition("before.gate", "completed", "gate.review")
                )
        );
    }
}

package dev.dual.server;

import org.junit.jupiter.api.Test;

import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;

class SchedulerPolicyTest {
    private final SchedulerPolicy policy = new SchedulerPolicy();

    @Test
    void runningWorkstreamCanResume() {
        var decision = policy.decide("RUNNING", false, Map.of());

        assertEquals(SchedulerDecision.Action.RESUME, decision.action());
    }

    @Test
    void recoveryWorkstreamIsSkippedWhenAutoRecoverDisabled() {
        var decision = policy.decide("WAITING_FOR_RECOVERY", false, Map.of(
                "classification", "recoverable_agent_runtime",
                "retryReadiness", "RETRY_AFTER_EXTERNAL_FIX"
        ));

        assertEquals(SchedulerDecision.Action.SKIP, decision.action());
        assertEquals("WAITING_FOR_RECOVERY", decision.reason());
    }

    @Test
    void retryReadyRuntimeRecoveryCanAutoRecoverWhenEnabled() {
        var decision = policy.decide("WAITING_FOR_RECOVERY", true, Map.of(
                "classification", "recoverable_agent_runtime",
                "retryReadiness", "RETRY_AFTER_EXTERNAL_FIX"
        ));

        assertEquals(SchedulerDecision.Action.AUTO_RECOVER, decision.action());
        assertEquals("recoverable_agent_runtime", decision.recoveryClassification());
        assertEquals("RETRY_AFTER_EXTERNAL_FIX", decision.retryReadiness());
    }

    @Test
    void artifactContractFailureCannotAutoRecover() {
        var decision = policy.decide("WAITING_FOR_RECOVERY", true, Map.of(
                "classification", "artifact_contract_failure",
                "retryReadiness", "RETRY_AFTER_OUTPUT_CONTRACT_FIX"
        ));

        assertEquals(SchedulerDecision.Action.SKIP, decision.action());
        assertEquals("recovery:artifact_contract_failure/RETRY_AFTER_OUTPUT_CONTRACT_FIX", decision.reason());
    }

    @Test
    void semanticRevisionLimitCannotAutoRecover() {
        var decision = policy.decide("WAITING_FOR_RECOVERY", true, Map.of(
                "classification", "semantic_revision_limit",
                "retryReadiness", "NEEDS_HUMAN_DECISION"
        ));

        assertEquals(SchedulerDecision.Action.SKIP, decision.action());
        assertEquals("recovery:semantic_revision_limit/NEEDS_HUMAN_DECISION", decision.reason());
    }
}

package dev.dual.server;

import org.junit.jupiter.api.Test;

import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.assertEquals;

class BackgroundSchedulerServiceTest {
    @Test
    void disabledSchedulerSkipsWithoutCallingTick() {
        var tickCalls = new AtomicInteger();
        var service = new BackgroundSchedulerService(
                new SchedulerServiceStub(tickCalls),
                false,
                "/tmp/ws-a",
                10,
                1,
                false,
                NotificationService.disabled()
        );

        var result = service.runOnce();

        assertEquals("skipped", result.get("status"));
        assertEquals("disabled", result.get("reason"));
        assertEquals(0, tickCalls.get());
    }

    @Test
    void enabledSchedulerTicksConfiguredWorkdirs() {
        var tickCalls = new AtomicInteger();
        var service = new BackgroundSchedulerService(
                new SchedulerServiceStub(tickCalls),
                true,
                "/tmp/ws-a,/tmp/ws-b",
                3,
                2,
                true,
                NotificationService.disabled()
        );

        var result = service.runOnce();

        assertEquals("completed", result.get("status"));
        assertEquals(2, tickCalls.get());
        assertEquals(2, result.get("resumed"));
        assertEquals(2, result.get("autoRecovered"));
        assertEquals(4, result.get("skipped"));
    }

    @Test
    void statusShowsLastRun() {
        var service = new BackgroundSchedulerService(
                new SchedulerServiceStub(new AtomicInteger()),
                false,
                "",
                10,
                1,
                false,
                NotificationService.disabled()
        );

        service.runOnce();
        var status = service.status();

        assertEquals("scheduler.background.status", status.get("action"));
        assertEquals(false, status.get("enabled"));
        assertEquals("skipped", ((Map<?, ?>) status.get("lastRun")).get("status"));
    }

    private static final class SchedulerServiceStub extends SchedulerService {
        private final AtomicInteger calls;

        SchedulerServiceStub(AtomicInteger calls) {
            super(null, null);
            this.calls = calls;
        }

        @Override
        public Map<String, Object> tick(Path workspaceRoot, int maxWorkstreams, int maxStepsPerWorkstream, boolean autoRecover) {
            calls.incrementAndGet();
            var response = new LinkedHashMap<String, Object>();
            response.put("action", "scheduler.tick");
            response.put("workdir", workspaceRoot.toString());
            response.put("resumed", 1);
            response.put("autoRecovered", autoRecover ? 1 : 0);
            response.put("skipped", 2);
            response.put("limits", maxWorkstreams + ":" + maxStepsPerWorkstream);
            return response;
        }
    }
}

