package dev.dual.flow.liteflow;

import dev.dual.core.workflow.EdgeDefinition;
import dev.dual.core.workflow.WorkflowDefinition;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class LiteFlowElCompiler {
    public LiteFlowCompiledDefinition compile(WorkflowDefinition definition) {
        if (definition == null) {
            throw new IllegalArgumentException("workflow definition is required");
        }
        var chainNameByRouteKey = new LinkedHashMap<String, String>();
        var componentIdsByRouteKey = new LinkedHashMap<String, List<String>>();
        var edgesByComponentId = new LinkedHashMap<String, EdgeDefinition>();

        var groupedEdges = groupEdges(definition);
        var xml = new StringBuilder();
        xml.append("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
        xml.append("<flow>\n");
        xml.append("    <nodes>\n");
        xml.append("        <node id=\"prepare\" class=\"dev.dual.flow.liteflow.PrepareFlowComponent\"/>\n");
        xml.append("        <node id=\"emit\" class=\"dev.dual.flow.liteflow.EmitFlowComponent\"/>\n");

        var componentOrdinal = 1;
        for (var entry : groupedEdges.entrySet()) {
            var componentIds = new ArrayList<String>();
            for (var edge : entry.getValue()) {
                var componentId = "edge_" + String.format("%04d", componentOrdinal++);
                componentIds.add(componentId);
                edgesByComponentId.put(componentId, edge);
                xml.append("        <node id=\"")
                        .append(componentId)
                        .append("\" class=\"dev.dual.flow.liteflow.RouteCandidateFlowComponent\"/>\n");
            }
            componentIdsByRouteKey.put(entry.getKey(), List.copyOf(componentIds));
        }
        xml.append("    </nodes>\n\n");

        var chainOrdinal = 1;
        for (var entry : componentIdsByRouteKey.entrySet()) {
            var chainName = "route_" + String.format("%04d", chainOrdinal++);
            chainNameByRouteKey.put(entry.getKey(), chainName);
            xml.append("    <chain name=\"").append(chainName).append("\">\n");
            xml.append("        ").append(renderThenExpression(entry.getValue())).append("\n");
            xml.append("    </chain>\n");
        }
        xml.append("</flow>\n");

        return new LiteFlowCompiledDefinition(
                xml.toString(),
                chainNameByRouteKey,
                componentIdsByRouteKey,
                edgesByComponentId
        );
    }

    private static Map<String, List<EdgeDefinition>> groupEdges(WorkflowDefinition definition) {
        var grouped = new LinkedHashMap<String, List<EdgeDefinition>>();
        for (var edge : definition.edges()) {
            var routeKey = LiteFlowCompiledDefinition.routeKey(edge.from(), edge.on());
            grouped.computeIfAbsent(routeKey, ignored -> new ArrayList<>()).add(edge);
        }
        return grouped;
    }

    private static String renderThenExpression(List<String> componentIds) {
        var steps = new ArrayList<String>();
        steps.add("prepare");
        steps.addAll(componentIds);
        steps.add("emit");
        return "THEN(" + String.join(", ", steps) + ");";
    }
}

package dev.dual.flow.liteflow;

import com.yomahub.liteflow.core.NodeComponent;

import java.util.LinkedHashMap;

public final class RouteCandidateFlowComponent extends NodeComponent {
    @Override
    public void process() {
        var context = getContextBean(LiteFlowKernelContext.class);
        var componentId = getNodeId();
        context.recordStep(componentId);
        var edge = context.candidateEdge(componentId);
        if (edge == null) {
            throw new IllegalStateException("no edge bound to LiteFlow component: " + componentId);
        }
        var routingContext = new LinkedHashMap<String, Object>();
        routingContext.put("outcome", context.signal().outcome());
        routingContext.putAll(context.signal().context());
        if (edge.condition().evaluate(routingContext)) {
            context.acceptCandidate(componentId);
        }
    }
}

package dev.dual.flow.liteflow;

import dev.dual.core.workflow.EdgeDefinition;

import java.util.List;
import java.util.Map;

public record LiteFlowCompiledDefinition(
        String xml,
        Map<String, String> chainNameByRouteKey,
        Map<String, List<String>> componentIdsByRouteKey,
        Map<String, EdgeDefinition> edgesByComponentId
) {
    public LiteFlowCompiledDefinition {
        if (xml == null || xml.isBlank()) {
            throw new IllegalArgumentException("LiteFlow XML is required");
        }
        chainNameByRouteKey = chainNameByRouteKey == null ? Map.of() : Map.copyOf(chainNameByRouteKey);
        componentIdsByRouteKey = componentIdsByRouteKey == null ? Map.of() : Map.copyOf(componentIdsByRouteKey);
        edgesByComponentId = edgesByComponentId == null ? Map.of() : Map.copyOf(edgesByComponentId);
    }

    public String chainName(String fromNodeDefinitionId, String outcome) {
        return chainNameByRouteKey.get(routeKey(fromNodeDefinitionId, outcome));
    }

    public Map<String, EdgeDefinition> candidateEdges(String fromNodeDefinitionId, String outcome) {
        var routeKey = routeKey(fromNodeDefinitionId, outcome);
        var componentIds = componentIdsByRouteKey.get(routeKey);
        if (componentIds == null || componentIds.isEmpty()) {
            return Map.of();
        }
        var selected = new java.util.LinkedHashMap<String, EdgeDefinition>();
        for (var componentId : componentIds) {
            selected.put(componentId, edgesByComponentId.get(componentId));
        }
        return selected;
    }

    public static String routeKey(String fromNodeDefinitionId, String outcome) {
        return fromNodeDefinitionId + "::" + outcome;
    }
}

package dev.dual.flow.liteflow;

import com.yomahub.liteflow.core.NodeComponent;
import dev.dual.core.flow.FlowAdvanceResult;
import dev.dual.core.flow.FlowTransitionCandidate;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.Map;

public final class EmitFlowComponent extends NodeComponent {
    @Override
    public void process() {
        var context = getContextBean(LiteFlowKernelContext.class);
        context.recordStep(getNodeId());
        var result = context.advanceResult();
        if (result != null) {
            context.setAdvanceResult(new FlowAdvanceResult(result.transitions(), context.executedStepIds()));
            return;
        }
        var transitions = new ArrayList<FlowTransitionCandidate>();
        for (var componentId : context.acceptedCandidateComponentIds()) {
            var edge = context.candidateEdge(componentId);
            transitions.add(new FlowTransitionCandidate(edge.from(), edge.on(), edge.to(), edgeAttributes(edge)));
        }
        context.setAdvanceResult(new FlowAdvanceResult(transitions, context.executedStepIds()));
    }

    private static Map<String, Object> edgeAttributes(dev.dual.core.workflow.EdgeDefinition edge) {
        var attributes = new LinkedHashMap<String, Object>(edge.metadata().toAttributes());
        attributes.put("condition", edge.condition().type());
        return Map.copyOf(attributes);
    }
}

package dev.dual.flow.liteflow;

import dev.dual.core.flow.BuiltInFlowOrchestrationKernel;
import dev.dual.core.flow.FlowOrchestrationKernel;

/**
 * 统一选择工作流编排内核。
 *
 * <p>默认使用 LiteFlow 作为 routing kernel；保留 built-in 作为诊断和回退入口。
 * 这里返回的是抽象接口，调用方不应该越过 {@link FlowOrchestrationKernel}
 * 直接依赖 LiteFlow 的实现细节。</p>
 */
public final class FlowKernelProvider {
    public static final String LITEFLOW = "liteflow";
    public static final String BUILTIN = "builtin";

    private FlowKernelProvider() {
    }

    public static FlowOrchestrationKernel create(String configuredKernel) {
        var kernel = normalize(configuredKernel);
        return switch (kernel) {
            case LITEFLOW -> new LiteFlowPrototypeKernel();
            case BUILTIN -> new BuiltInFlowOrchestrationKernel();
            default -> throw new IllegalArgumentException(
                    "unsupported flow kernel: " + configuredKernel + ". Supported values: liteflow, builtin"
            );
        };
    }

    public static String normalize(String configuredKernel) {
        if (configuredKernel == null || configuredKernel.isBlank()) {
            return LITEFLOW;
        }
        return configuredKernel.trim().toLowerCase();
    }
}

package dev.dual.flow.liteflow;

import dev.dual.core.flow.FlowAdvanceResult;
import dev.dual.core.flow.FlowExecutionSnapshot;
import dev.dual.core.flow.FlowSignal;
import dev.dual.core.workflow.WorkflowDefinition;
import dev.dual.core.workflow.EdgeDefinition;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;

public final class LiteFlowKernelContext {
    private final WorkflowDefinition definition;
    private final FlowExecutionSnapshot snapshot;
    private final FlowSignal signal;
    private final Map<String, EdgeDefinition> candidateEdgesByComponentId;
    private final List<String> executedStepIds = new ArrayList<>();
    private final CopyOnWriteArrayList<String> acceptedCandidateComponentIds = new CopyOnWriteArrayList<>();
    private FlowAdvanceResult advanceResult;

    public LiteFlowKernelContext(WorkflowDefinition definition, FlowExecutionSnapshot snapshot, FlowSignal signal) {
        this(definition, snapshot, signal, Map.of());
    }

    public LiteFlowKernelContext(
            WorkflowDefinition definition,
            FlowExecutionSnapshot snapshot,
            FlowSignal signal,
            Map<String, EdgeDefinition> candidateEdgesByComponentId
    ) {
        if (definition == null) {
            throw new IllegalArgumentException("workflow definition is required");
        }
        if (snapshot == null) {
            throw new IllegalArgumentException("flow execution snapshot is required");
        }
        if (signal == null) {
            throw new IllegalArgumentException("flow signal is required");
        }
        this.definition = definition;
        this.snapshot = snapshot;
        this.signal = signal;
        this.candidateEdgesByComponentId = copyCandidateEdges(candidateEdgesByComponentId);
    }

    public WorkflowDefinition definition() {
        return definition;
    }

    public FlowExecutionSnapshot snapshot() {
        return snapshot;
    }

    public FlowSignal signal() {
        return signal;
    }

    public void recordStep(String stepId) {
        executedStepIds.add(stepId);
    }

    public List<String> executedStepIds() {
        return List.copyOf(executedStepIds);
    }

    public FlowAdvanceResult advanceResult() {
        return advanceResult;
    }

    public void setAdvanceResult(FlowAdvanceResult advanceResult) {
        this.advanceResult = advanceResult;
    }

    public EdgeDefinition candidateEdge(String componentId) {
        return candidateEdgesByComponentId.get(componentId);
    }

    public List<String> acceptedCandidateComponentIds() {
        return List.copyOf(acceptedCandidateComponentIds);
    }

    public void acceptCandidate(String componentId) {
        acceptedCandidateComponentIds.add(componentId);
    }

    private static Map<String, EdgeDefinition> copyCandidateEdges(Map<String, EdgeDefinition> source) {
        if (source == null || source.isEmpty()) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, EdgeDefinition>();
        for (var entry : source.entrySet()) {
            if (entry.getKey() == null || entry.getKey().isBlank()) {
                throw new IllegalArgumentException("candidate component id is required");
            }
            if (entry.getValue() == null) {
                throw new IllegalArgumentException("candidate edge is required");
            }
            copy.put(entry.getKey(), entry.getValue());
        }
        return Map.copyOf(copy);
    }
}

