package dev.dual.ledger.file;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.workflow.WorkflowStatus;

import java.io.IOException;
import java.nio.file.Files;
import java.util.List;
import java.util.Map;

/**
 * Builds the shared "where is it, why did it stop, what next" read model.
 *
 * CLI, API, and UI should consume this projection instead of recomputing status
 * hints independently. The evaluator reads authoritative ledger/domain facts
 * and returns one operator-facing attention item; it does not mutate workflow
 * state.
 */
public final class WorkstreamAttentionEvaluator {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper().findAndRegisterModules();
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    private WorkstreamAttentionEvaluator() {
    }

    public static WorkstreamAttention evaluate(WorkstreamPaths paths) {
        try {
            return evaluateOrThrow(paths);
        } catch (Exception failure) {
            return new WorkstreamAttention(
                    WorkstreamAttentionCategory.UNKNOWN,
                    "warning",
                    "Workflow attention unavailable",
                    failure.getMessage() == null ? "Could not read workstream attention facts." : failure.getMessage(),
                    "Inspect the workstream ledger.",
                    "",
                    false,
                    "",
                    "",
                    "",
                    "",
                    List.of()
            );
        }
    }

    private static WorkstreamAttention evaluateOrThrow(WorkstreamPaths paths) throws IOException {
        if (!Files.isRegularFile(paths.workflowCurrentJson())) {
            return unknown("Workflow current state is not available.");
        }
        var current = OBJECT_MAPPER.readValue(paths.workflowCurrentJson().toFile(), WorkflowCurrentDocument.class);
        var activeNode = activeNode(paths, current);
        var goal = readMap(paths.goalSatisfactionJson());
        var domainOutcome = text(goal.get("domainOutcome"));
        var goalReason = text(goal.get("reason"));
        var evidenceRefs = textList(goal.get("evidenceRefs"));
        var nodeId = activeNode == null ? "" : activeNode.nodeDefinitionId();
        var nodeInstanceId = activeNode == null ? "" : activeNode.nodeInstanceId();
        var base = "--workdir " + quote(paths.workspaceRoot().toAbsolutePath().normalize().toString()) + " " + paths.workstreamId().value();

        // Human gates are actionable only while current; historical gate
        // evidence belongs to review packet projections, not this attention item.
        if (current.status() == WorkflowStatus.WAITING_FOR_HUMAN) {
            return new WorkstreamAttention(
                    WorkstreamAttentionCategory.WAITING_FOR_HUMAN,
                    "info",
                    "Human gate is open",
                    current.openGateIds().isEmpty()
                            ? "Waiting for human review."
                            : "Waiting for human review: " + String.join(", ", current.openGateIds()),
                    "Read the review packet, then approve, revise, or complete from the current gate.",
                    "dualctl review show " + base,
                    false,
                    current.status().name(),
                    nodeId,
                    nodeInstanceId,
                    domainOutcome,
                    evidenceRefs
            );
        }
        if (current.status() == WorkflowStatus.WAITING_FOR_RECOVERY
                || current.status() == WorkflowStatus.FAILED
                || current.status() == WorkflowStatus.BLOCKED) {
            return recovery(paths, current, activeNode, domainOutcome, evidenceRefs, base);
        }
        if (current.status() == WorkflowStatus.RUNNING) {
            var stale = staleRunningAttention(paths, current, activeNode, nodeId, nodeInstanceId, domainOutcome, evidenceRefs, base);
            if (stale != null) {
                return stale;
            }
            return new WorkstreamAttention(
                    WorkstreamAttentionCategory.RUNNING,
                    "info",
                    "Workflow is running",
                    nodeId.isBlank() ? "Workflow is running." : "Workflow is running at " + nodeId + ".",
                    "Let the active node finish, or inspect the active execution if it appears stale.",
                    "",
                    false,
                    current.status().name(),
                    nodeId,
                    nodeInstanceId,
                    domainOutcome,
                    evidenceRefs
            );
        }
        // Terminal workflows can still carry goal warnings, but they must not
        // suggest run/resume. Observation and audit are the only safe actions.
        if (current.status() == WorkflowStatus.COMPLETED) {
            return completed(current, nodeId, nodeInstanceId, domainOutcome, goalReason, evidenceRefs, base);
        }
        if ("NEEDS_REDESIGN".equals(domainOutcome) && isRevisionLimit(activeNode)) {
            return new WorkstreamAttention(
                    WorkstreamAttentionCategory.SEMANTIC_REVISION_LIMIT,
                    "critical",
                    "Design loop did not converge",
                    blankDefault(goalReason, "The workflow exhausted its design revision budget. Blind retry is unsafe because it will likely repeat the same review loop."),
                    "Inspect the design review evidence, then revise the task contract, scope, or test policy before continuing.",
                    "dualctl recovery show " + base,
                    false,
                    current.status().name(),
                    nodeId,
                    nodeInstanceId,
                    domainOutcome,
                    evidenceRefs
            );
        }
        if ("NEEDS_REPAIR".equals(domainOutcome)) {
            return goalLoop(
                    WorkstreamAttentionCategory.GOAL_REPAIR_REQUIRED,
                    "Goal needs repair",
                    blankDefault(goalReason, "Verifier evidence indicates the implementation does not satisfy the goal yet."),
                    "Continue the goal loop only after reviewing the rejection evidence and repair scope.",
                    "dualctl run " + base,
                    current,
                    nodeId,
                    nodeInstanceId,
                    domainOutcome,
                    evidenceRefs
            );
        }
        if ("NEEDS_REDESIGN".equals(domainOutcome)) {
            return goalLoop(
                    WorkstreamAttentionCategory.GOAL_REDESIGN_REQUIRED,
                    "Goal needs redesign",
                    blankDefault(goalReason, "Review evidence indicates the design or plan is not ready for implementation."),
                    "Continue the goal loop with the recorded design evidence.",
                    "dualctl run " + base,
                    current,
                    nodeId,
                    nodeInstanceId,
                    domainOutcome,
                    evidenceRefs
            );
        }
        return unknown("Workflow status is " + current.status() + ".");
    }

    private static WorkstreamAttention completed(
            WorkflowCurrentDocument current,
            String nodeId,
            String nodeInstanceId,
            String domainOutcome,
            String goalReason,
            List<String> evidenceRefs,
            String base
    ) throws IOException {
        var unsatisfiedGoal = "NEEDS_REPAIR".equals(domainOutcome) || "NEEDS_REDESIGN".equals(domainOutcome);
        var warningDetail = "Workflow is terminal, but the latest goal outcome is " + domainOutcome
                + ". " + blankDefault(goalReason, "Inspect artifacts before delivery.");
        return new WorkstreamAttention(
                WorkstreamAttentionCategory.COMPLETED,
                unsatisfiedGoal ? "warning" : "info",
                unsatisfiedGoal ? "Workflow completed with goal warning" : "Workflow completed",
                unsatisfiedGoal ? warningDetail : "Workflow completed. Further actions should inspect artifacts only.",
                "Review final artifacts and Git status.",
                "dualctl summary " + base,
                false,
                current.status().name(),
                nodeId,
                nodeInstanceId,
                domainOutcome,
                evidenceRefs
        );
    }

    private static WorkstreamAttention staleRunningAttention(
            WorkstreamPaths paths,
            WorkflowCurrentDocument current,
            NodeInstanceDocument activeNode,
            String nodeId,
            String nodeInstanceId,
            String domainOutcome,
            List<String> evidenceRefs,
            String base
    ) {
        if (activeNode == null) {
            return null;
        }
        var runningPid = runningPid(activeNode.result().get("running_pid"));
        if (runningPid > 0 && ProcessHandle.of(runningPid).map(ProcessHandle::isAlive).orElse(false)) {
            return null;
        }
        var detail = "";
        if (runningPid > 0) {
            detail = "Workflow is marked RUNNING at " + blankDefault(nodeId, "the current node")
                    + ", but its recorded process is no longer alive (PID=" + runningPid + ").";
        } else if (Files.isRegularFile(paths.currentFailureMarkdown())) {
            detail = "Workflow is marked RUNNING, but a current failure summary exists. Inspect recovery before continuing.";
        } else {
            return null;
        }
        return new WorkstreamAttention(
                WorkstreamAttentionCategory.RUNTIME_RECOVERY,
                "critical",
                "Running state looks stale",
                detail,
                "Move the stale running node into recovery.",
                "dualctl resume " + base,
                false,
                current.status().name(),
                nodeId,
                nodeInstanceId,
                domainOutcome,
                evidenceRefs
        );
    }

    private static WorkstreamAttention recovery(
            WorkstreamPaths paths,
            WorkflowCurrentDocument current,
            NodeInstanceDocument activeNode,
            String domainOutcome,
            List<String> evidenceRefs,
            String base
    ) {
        if (activeNode == null) {
            return unknown("Workflow is waiting for recovery but no active node is recorded.");
        }
        var assessment = RecoveryAssessment.from(activeNode, paths.workspaceRoot(), paths.workstreamId().value());
        var classification = assessment.classification();
        if ("artifact_contract_failure".equals(classification)) {
            return new WorkstreamAttention(
                    WorkstreamAttentionCategory.ARTIFACT_CONTRACT_FAILURE,
                    "critical",
                    "Artifact contract failed",
                    assessment.reason(),
                    "Inspect the contract diagnostic and fix the output contract before retrying.",
                    assessment.suggestedCommand(),
                    assessment.retrySafe(),
                    current.status().name(),
                    activeNode.nodeDefinitionId(),
                    activeNode.nodeInstanceId(),
                    domainOutcome,
                    mergeEvidence(evidenceRefs, assessment.diagnosticJsonRef(), assessment.diagnosticMarkdownRef())
            );
        }
        if ("recoverable_agent_runtime".equals(classification)) {
            return new WorkstreamAttention(
                    WorkstreamAttentionCategory.RUNTIME_RECOVERY,
                    "critical",
                    "Runtime recovery required",
                    assessment.reason(),
                    "Fix the external runtime cause, then retry the same active node.",
                    assessment.suggestedCommand(),
                    assessment.retrySafe(),
                    current.status().name(),
                    activeNode.nodeDefinitionId(),
                    activeNode.nodeInstanceId(),
                    domainOutcome,
                    evidenceRefs
            );
        }
        if ("agent_session_recovery".equals(classification)) {
            // agent_session_recovery maps to two readiness values: REBUILD (reconnect)
            // and INSPECT_BEFORE_RETRY (generic bootstrap failure). Project the assessment's
            // authoritative readiness into the next action; do not hardcode "Rebuild".
            var nextAction = "REBUILD_ACPX_SESSION_THEN_RETRY".equals(assessment.retryReadiness())
                    ? "Rebuild the acpx agent session, then retry the same active node."
                    : "Inspect the session bootstrap failure before retrying the same active node.";
            return new WorkstreamAttention(
                    WorkstreamAttentionCategory.RUNTIME_RECOVERY,
                    "critical",
                    "Agent session recovery required",
                    assessment.reason(),
                    nextAction,
                    assessment.suggestedCommand(),
                    assessment.retrySafe(),
                    current.status().name(),
                    activeNode.nodeDefinitionId(),
                    activeNode.nodeInstanceId(),
                    domainOutcome,
                    evidenceRefs
            );
        }
        if ("agent_output_interrupted".equals(classification)) {
            return new WorkstreamAttention(
                    WorkstreamAttentionCategory.RUNTIME_RECOVERY,
                    "critical",
                    "Agent output interrupted",
                    assessment.reason(),
                    "Rebuild the acpx agent session, then retry the same active node.",
                    assessment.suggestedCommand(),
                    assessment.retrySafe(),
                    current.status().name(),
                    activeNode.nodeDefinitionId(),
                    activeNode.nodeInstanceId(),
                    domainOutcome,
                    evidenceRefs
            );
        }
        if ("agent_output_incomplete".equals(classification)) {
            return new WorkstreamAttention(
                    WorkstreamAttentionCategory.RUNTIME_RECOVERY,
                    "critical",
                    "Agent output incomplete",
                    assessment.reason(),
                    "RETRY_AFTER_EXTERNAL_FIX".equals(assessment.retryReadiness())
                            ? "Inspect the recorded agent process and external failure before a manual retry."
                            : "Inspect the agent output contract, then retry the same active node.",
                    assessment.suggestedCommand(),
                    assessment.retrySafe(),
                    current.status().name(),
                    activeNode.nodeDefinitionId(),
                    activeNode.nodeInstanceId(),
                    domainOutcome,
                    evidenceRefs
            );
        }
        if ("agent_capacity_recovery".equals(classification)) {
            return new WorkstreamAttention(
                    WorkstreamAttentionCategory.RUNTIME_RECOVERY,
                    "critical",
                    "Agent capacity recovery required",
                    assessment.reason(),
                    "Wait for quota or provider capacity to recover, then retry the same active node.",
                    assessment.suggestedCommand(),
                    assessment.retrySafe(),
                    current.status().name(),
                    activeNode.nodeDefinitionId(),
                    activeNode.nodeInstanceId(),
                    domainOutcome,
                    evidenceRefs
            );
        }
        if ("agent_model_mismatch".equals(classification)) {
            return new WorkstreamAttention(
                    WorkstreamAttentionCategory.RUNTIME_RECOVERY,
                    "critical",
                    "Agent session model mismatch",
                    assessment.reason(),
                    "Rebuild the acpx agent session, then retry the same active node.",
                    assessment.suggestedCommand(),
                    assessment.retrySafe(),
                    current.status().name(),
                    activeNode.nodeDefinitionId(),
                    activeNode.nodeInstanceId(),
                    domainOutcome,
                    evidenceRefs
            );
        }
        if ("semantic_revision_limit".equals(classification)) {
            return new WorkstreamAttention(
                    WorkstreamAttentionCategory.SEMANTIC_REVISION_LIMIT,
                    "critical",
                    "Design loop did not converge",
                    assessment.reason(),
                    "Inspect the review evidence and revise the task contract, scope, or test policy before continuing.",
                    "dualctl recovery show " + base,
                    assessment.retrySafe(),
                    current.status().name(),
                    activeNode.nodeDefinitionId(),
                    activeNode.nodeInstanceId(),
                    domainOutcome,
                    evidenceRefs
            );
        }
        return new WorkstreamAttention(
                WorkstreamAttentionCategory.FAILED,
                "critical",
                "Workflow needs inspection",
                assessment.reason(),
                "Inspect recovery evidence before deciding whether retry is safe.",
                assessment.suggestedCommand(),
                assessment.retrySafe(),
                current.status().name(),
                activeNode.nodeDefinitionId(),
                activeNode.nodeInstanceId(),
                domainOutcome,
                evidenceRefs
        );
    }

    private static WorkstreamAttention goalLoop(
            WorkstreamAttentionCategory category,
            String title,
            String detail,
            String nextAction,
            String command,
            WorkflowCurrentDocument current,
            String nodeId,
            String nodeInstanceId,
            String domainOutcome,
            List<String> evidenceRefs
    ) {
        return new WorkstreamAttention(
                category,
                "warning",
                title,
                detail,
                nextAction,
                command,
                false,
                current.status().name(),
                nodeId,
                nodeInstanceId,
                domainOutcome,
                evidenceRefs
        );
    }

    private static NodeInstanceDocument activeNode(WorkstreamPaths paths, WorkflowCurrentDocument current) throws IOException {
        if (current.activeNodeInstanceIds().isEmpty()) {
            return null;
        }
        return OBJECT_MAPPER.readValue(paths.nodeJson(current.activeNodeInstanceIds().get(0)).toFile(), NodeInstanceDocument.class);
    }

    private static boolean isRevisionLimit(NodeInstanceDocument node) {
        return node != null && "revision_limit_reached".equals(text(node.result().get("reason")));
    }

    private static Map<String, Object> readMap(java.nio.file.Path path) throws IOException {
        if (!Files.isRegularFile(path)) {
            return Map.of();
        }
        return OBJECT_MAPPER.readValue(path.toFile(), MAP_TYPE);
    }

    private static List<String> textList(Object value) {
        if (!(value instanceof List<?> list)) {
            return List.of();
        }
        return list.stream().map(WorkstreamAttentionEvaluator::text).filter(s -> !s.isBlank()).toList();
    }

    private static List<String> mergeEvidence(List<String> refs, String... extraRefs) {
        var merged = new java.util.ArrayList<String>();
        if (refs != null) {
            merged.addAll(refs);
        }
        for (var ref : extraRefs) {
            if (ref != null && !ref.isBlank()) {
                merged.add(ref);
            }
        }
        return List.copyOf(merged);
    }

    private static long runningPid(Object value) {
        if (value instanceof Number number) {
            return number.longValue();
        }
        if (value == null) {
            return 0;
        }
        try {
            return Long.parseLong(String.valueOf(value));
        } catch (NumberFormatException ignored) {
            return 0;
        }
    }

    private static WorkstreamAttention unknown(String detail) {
        return new WorkstreamAttention(
                WorkstreamAttentionCategory.UNKNOWN,
                "warning",
                "Workflow state is unclear",
                detail,
                "Inspect the workstream ledger.",
                "",
                false,
                "",
                "",
                "",
                "",
                List.of()
        );
    }

    private static String blankDefault(String value, String fallback) {
        return value == null || value.isBlank() ? fallback : value;
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    private static String quote(String value) {
        if (value.contains(" ")) {
            return "\"" + value.replace("\"", "\\\"") + "\"";
        }
        return value;
    }
}

package dev.dual.ledger.file;

import dev.dual.core.workflow.NodeStatus;

import java.io.IOException;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Optional;

final class GoalSatisfactionWriter {
    private final AtomicJsonWriter jsonWriter;

    GoalSatisfactionWriter(AtomicJsonWriter jsonWriter) {
        this.jsonWriter = jsonWriter;
    }

    Optional<GoalSatisfactionDocument> evaluateAndWrite(
            WorkstreamPaths paths,
            WorkflowCurrentDocument current,
            NodeInstanceDocument node,
            NodeStatus nodeStatus,
            String outcome,
            List<String> evidenceRefs,
            Map<String, Object> result
    ) throws IOException {
        var domainOutcome = domainOutcome(node.nodeDefinitionId(), nodeStatus, outcome);
        if (domainOutcome.isEmpty()) {
            return Optional.empty();
        }
        var document = new GoalSatisfactionDocument(
                1,
                current.workstreamId(),
                current.workflowInstanceId(),
                node.nodeInstanceId(),
                node.nodeDefinitionId(),
                node.iterationId(),
                outcome,
                domainOutcome.get(),
                reason(outcome, result),
                evidenceRefs,
                result,
                Instant.now()
        );
        jsonWriter.write(paths.goalSatisfactionJson(), document);
        return Optional.of(document);
    }

    private static Optional<GoalDomainOutcome> domainOutcome(String nodeDefinitionId, NodeStatus nodeStatus, String outcome) {
        if (nodeStatus != NodeStatus.COMPLETED) {
            return Optional.empty();
        }
        if ("acceptance.decision".equals(nodeDefinitionId)) {
            return switch (outcome) {
                case "ACCEPT" -> Optional.of(GoalDomainOutcome.SATISFIED);
                case "ACCEPT_WITH_NOTES" -> Optional.of(GoalDomainOutcome.SATISFIED_WITH_NOTES);
                case "REJECT" -> Optional.of(GoalDomainOutcome.NEEDS_REPAIR);
                case "BLOCKED" -> Optional.of(GoalDomainOutcome.BLOCKED);
                default -> Optional.empty();
            };
        }
        if ("acceptance.classify_failure".equals(nodeDefinitionId)) {
            if (outcome != null && outcome.startsWith("REJECT_")) {
                return Optional.of(GoalDomainOutcome.NEEDS_REPAIR);
            }
            if (outcome != null && outcome.startsWith("NOTED_")) {
                return Optional.of(GoalDomainOutcome.SATISFIED_WITH_NOTES);
            }
        }
        if (outcome != null && "NEEDS_REVISION".equals(outcome)) {
            return Optional.of(GoalDomainOutcome.NEEDS_REDESIGN);
        }
        if (outcome != null && "BLOCKED".equals(outcome)) {
            return Optional.of(GoalDomainOutcome.BLOCKED);
        }
        return Optional.empty();
    }

    private static String reason(String outcome, Map<String, Object> result) {
        if (result == null || result.isEmpty()) {
            return outcome == null ? "" : outcome;
        }
        for (var key : List.of("reason", "summary", "message", "review_decision", "decision")) {
            var value = result.get(key);
            if (value != null && !String.valueOf(value).isBlank()) {
                return String.valueOf(value);
            }
        }
        return outcome == null ? "" : outcome;
    }
}

package dev.dual.ledger.file;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowStatus;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

final class NodeStateWriter {
    private final AtomicJsonWriter jsonWriter;
    private final ObjectMapper objectMapper;
    private final LedgerEventLog eventLog;

    NodeStateWriter(AtomicJsonWriter jsonWriter, ObjectMapper objectMapper, LedgerEventLog eventLog) {
        this.jsonWriter = jsonWriter;
        this.objectMapper = objectMapper;
        this.eventLog = eventLog;
    }

    NodeInstanceDocument loadNode(WorkstreamPaths paths, String nodeInstanceId) throws IOException {
        return objectMapper.readValue(paths.nodeJson(nodeInstanceId).toFile(), NodeInstanceDocument.class);
    }

    WorkflowCurrentDocument loadCurrent(WorkstreamPaths paths) throws IOException {
        return objectMapper.readValue(paths.workflowCurrentJson().toFile(), WorkflowCurrentDocument.class);
    }

    NodeInstanceDocument markRunning(WorkstreamPaths paths, String nodeInstanceId, long pid) throws IOException {
        var node = loadNode(paths, nodeInstanceId);
        var now = Instant.now();
        var updated = new NodeInstanceDocument(
                node.schemaVersion(),
                node.nodeInstanceId(),
                node.nodeDefinitionId(),
                node.kind(),
                node.handlerType(),
                NodeStatus.RUNNING,
                node.stageId(),
                node.iterationId(),
                node.inputRefs(),
                node.inputTransition(),
                node.outputRefs(),
                LedgerUtils.mergedResult(node.result(), Map.of("running_pid", pid)),
                node.runRef(),
                node.latestExecutionId(),
                now,
                null
        );
        jsonWriter.write(paths.nodeJson(nodeInstanceId), updated);
        return updated;
    }

    NodeInstanceDocument markQueuedForAgentTask(WorkstreamPaths paths, String nodeInstanceId, String agentTaskId)
            throws IOException {
        var node = loadNode(paths, nodeInstanceId);
        var now = Instant.now();
        var updated = new NodeInstanceDocument(
                node.schemaVersion(),
                node.nodeInstanceId(),
                node.nodeDefinitionId(),
                node.kind(),
                node.handlerType(),
                NodeStatus.RUNNING,
                node.stageId(),
                node.iterationId(),
                node.inputRefs(),
                node.inputTransition(),
                node.outputRefs(),
                LedgerUtils.mergedResult(node.result(), Map.of(
                        "queued_agent_task_id", agentTaskId,
                        "dispatch_state", "QUEUED"
                )),
                node.runRef(),
                node.latestExecutionId(),
                now,
                null
        );
        jsonWriter.write(paths.nodeJson(nodeInstanceId), updated);
        return updated;
    }

    NodeInstanceDocument autoRetryNode(WorkstreamPaths paths, String nodeInstanceId) throws IOException {
        return autoRetryNode(paths, nodeInstanceId, 0);
    }

    NodeInstanceDocument autoRetryNode(WorkstreamPaths paths, String nodeInstanceId, long retryDelayMs) throws IOException {
        var node = loadNode(paths, nodeInstanceId);
        if (node.status() != NodeStatus.FAILED) {
            throw new IOException("auto-retry only applies to FAILED nodes, got: " + node.status());
        }
        var countValue = LedgerUtils.resultValueOrDefault(node.result(), "auto_retry_count", 0);
        int retryCount = (countValue instanceof Number n) ? n.intValue() : 0;
        var retry = new NodeInstanceDocument(
                node.schemaVersion(),
                node.nodeInstanceId(),
                node.nodeDefinitionId(),
                node.kind(),
                node.handlerType(),
                NodeStatus.READY,
                node.stageId(),
                node.iterationId(),
                node.inputRefs(),
                node.inputTransition(),
                List.of(),
                Map.of(
                        "retry_of_status", node.status().name(),
                        "auto_retry", true,
                        "auto_retry_count", retryCount + 1,
                        "previous_running_pid", LedgerUtils.resultValueOrDefault(node.result(), "running_pid", "")
                ),
                node.runRef(),
                node.latestExecutionId(),
                null,
                null
        );
        jsonWriter.write(paths.nodeJson(node.nodeInstanceId()), retry);

        var current = loadCurrent(paths);
        var eventId = LedgerUtils.nextEventId(current.lastEventId());
        var eventPayload = new LinkedHashMap<String, Object>();
        eventPayload.put("node", node.nodeDefinitionId());
        eventPayload.put("node_instance_id", node.nodeInstanceId());
        eventPayload.put("previous_status", node.status().name());
        eventPayload.put("auto_retry_count", retryCount + 1);
        if (retryDelayMs > 0) {
            eventPayload.put("retry_delay_ms", retryDelayMs);
        }
        eventLog.appendEvent(paths, eventId, "node_auto_retry", eventPayload);
        var now = Instant.now();
        var resumed = new WorkflowCurrentDocument(
                1,
                current.workstreamId(),
                current.workflowInstanceId(),
                current.workflowId(),
                current.definitionVersion(),
                WorkflowStatus.RUNNING,
                List.of(node.nodeInstanceId()),
                List.of(),
                eventId,
                now
        );
        jsonWriter.write(paths.workflowCurrentJson(), resumed);
        eventLog.writeInstanceFromCurrent(paths, resumed, now);
        return retry;
    }

    void retryActiveNode(WorkstreamPaths paths, String note) throws IOException {
        retryActiveNode(paths, note, Map.of(), "node_retry_requested");
    }

    void approvePublicWebSearch(WorkstreamPaths paths, String note, boolean publicRepositoryAttested)
            throws IOException {
        if (!publicRepositoryAttested) {
            throw new IOException("public repository attestation is required to approve WebSearch");
        }
        if (note == null || note.isBlank()) {
            throw new IOException("a human approval note is required to approve WebSearch");
        }
        var current = loadCurrent(paths);
        if (current.activeNodeInstanceIds().isEmpty()) {
            throw new IOException("no active node awaiting permission approval");
        }
        var node = loadNode(paths, current.activeNodeInstanceIds().get(0));
        if (node.status() != NodeStatus.FAILED) {
            throw new IOException("active node is not awaiting permission approval: "
                    + node.nodeDefinitionId() + " (" + node.status() + ")");
        }
        var assessment = RecoveryAssessment.from(
                node,
                paths.workspaceRoot(),
                paths.workstreamId().value());
        if (!assessment.allowedActions().contains("approve_public_websearch")) {
            throw new IOException("current failure does not allow public WebSearch approval");
        }
        var request = publicWebSearchEscalation(paths, node);
        var approval = new LinkedHashMap<String, Object>();
        approval.put("schema_version", 1);
        approval.put("type", "PUBLIC_WEBSEARCH");
        approval.put("workstream_id", paths.workstreamId().value());
        approval.put("node_instance_id", node.nodeInstanceId());
        approval.put("tool_name", "WebSearch");
        approval.put("tool_kind", "fetch");
        approval.put("source_run_ref", request.runRef());
        approval.put("source_tool_call_id", request.toolCallId());
        approval.put("source_query_sha256", sha256(request.resource()));
        approval.put("public_repository_attested", true);
        approval.put("note", note.trim());
        approval.put("approved_at", Instant.now().toString());
        retryActiveNode(
                paths,
                note,
                Map.of("permission_approval", Map.copyOf(approval)),
                "public_websearch_approved");
    }

    private void retryActiveNode(
            WorkstreamPaths paths,
            String note,
            Map<String, Object> additionalResult,
            String eventType
    ) throws IOException {
        var current = loadCurrent(paths);
        if (current.activeNodeInstanceIds().isEmpty()) {
            throw new IOException("no active node to retry");
        }
        var node = loadNode(paths, current.activeNodeInstanceIds().get(0));
        if (node.status() != NodeStatus.FAILED && node.status() != NodeStatus.BLOCKED) {
            throw new IOException("active node is not retryable: " + node.nodeDefinitionId() + " (" + node.status() + ")");
        }
        var retryResult = new LinkedHashMap<String, Object>();
        retryResult.put("retry_of_status", node.status().name());
        retryResult.put("retry_note", note == null ? "" : note);
        if ("node_retry_requested".equals(eventType)
                && node.status() == NodeStatus.FAILED
                && "acpx.agent_run".equals(node.handlerType())
                && "AGENT_OUTPUT_CONTRACT_VIOLATION".equals(node.result().get("reason"))) {
            if (current.status() != WorkflowStatus.WAITING_FOR_RECOVERY) {
                throw new IOException("contract diagnostic retry requires WAITING_FOR_RECOVERY");
            }
            // Copy advisory data with READY in one write; never dereference a mutable diagnostic file.
            retryResult.put("retry_failure_context", retryFailureContext(node));
        }
        retryResult.putAll(additionalResult);
        var retry = new NodeInstanceDocument(
                node.schemaVersion(),
                node.nodeInstanceId(),
                node.nodeDefinitionId(),
                node.kind(),
                node.handlerType(),
                NodeStatus.READY,
                node.stageId(),
                node.iterationId(),
                node.inputRefs(),
                node.inputTransition(),
                List.of(),
                retryResult,
                node.runRef(),
                node.latestExecutionId(),
                null,
                null
        );
        jsonWriter.write(paths.nodeJson(node.nodeInstanceId()), retry);

        var eventId = LedgerUtils.nextEventId(current.lastEventId());
        var eventDetails = new LinkedHashMap<String, Object>();
        eventDetails.put("node", node.nodeDefinitionId());
        eventDetails.put("node_instance_id", node.nodeInstanceId());
        eventDetails.put("previous_status", node.status().name());
        eventDetails.put("note", note == null ? "" : note);
        eventDetails.put("recovery_gate_ids", current.openGateIds());
        if (additionalResult.containsKey("permission_approval")) {
            eventDetails.put("permission_approval", additionalResult.get("permission_approval"));
        }
        eventLog.appendEvent(paths, eventId, eventType, Map.copyOf(eventDetails));
        var now = Instant.now();
        var resumed = new WorkflowCurrentDocument(
                1,
                current.workstreamId(),
                current.workflowInstanceId(),
                current.workflowId(),
                current.definitionVersion(),
                WorkflowStatus.RUNNING,
                List.of(node.nodeInstanceId()),
                List.of(),
                eventId,
                now
        );
        jsonWriter.write(paths.workflowCurrentJson(), resumed);
        eventLog.writeInstanceFromCurrent(paths, resumed, now);
    }

    private Map<String, Object> retryFailureContext(NodeInstanceDocument node) throws IOException {
        if (!(node.result().get("parse_error") instanceof Map<?, ?> error)
                || !(error.get("code") instanceof String code) || code.isBlank()
                || !(error.get("message") instanceof String message) || message.isBlank()
                || !(error.get("details") instanceof Map<?, ?> details)) {
            throw new IOException("contract diagnostic retry requires a structured parse_error");
        }
        var diagnostic = new LinkedHashMap<String, Object>();
        diagnostic.put("code", code);
        diagnostic.put("message", message);
        diagnostic.put("details", details);
        var full = objectMapper.writeValueAsString(diagnostic);
        int end = 0;
        int bytes = 0;
        while (end < full.length()) {
            int point = full.codePointAt(end);
            int size = point <= 0x7f ? 1 : point <= 0x7ff ? 2 : point <= 0xffff ? 3 : 4;
            if (bytes + size > 8192) break;
            bytes += size;
            end += Character.charCount(point);
        }
        return Map.of(
                "schema_version", 1,
                "diagnostic_text", full.substring(0, end),
                "truncated", end < full.length(),
                "source_run_id", node.result().get("run_id") instanceof String id ? id : "",
                "source_execution_id", node.latestExecutionId());
    }

    private PermissionEscalation publicWebSearchEscalation(WorkstreamPaths paths, NodeInstanceDocument node)
            throws IOException {
        var runRef = text(node.result().get("run_metadata"));
        if (runRef.isBlank()) {
            throw new IOException("permission escalation is missing run metadata");
        }
        var root = paths.workspaceRoot().toAbsolutePath().normalize();
        var runPath = root.resolve(runRef).normalize();
        if (!runPath.startsWith(paths.workstreamDir().toAbsolutePath().normalize())
                || !Files.isRegularFile(runPath)) {
            throw new IOException("permission escalation run metadata is invalid: " + runRef);
        }
        var run = objectMapper.readTree(runPath.toFile());
        var timeline = run.path("executionTimeline");
        if (!timeline.isArray()) {
            throw new IOException("permission escalation execution timeline is missing");
        }
        for (var index = timeline.size() - 1; index >= 0; index--) {
            var event = timeline.get(index);
            if (!"permission_decision".equals(event.path("kind").asText())) {
                continue;
            }
            var details = event.path("details");
            if ("ESCALATION_REQUIRED".equals(details.path("authorityDisposition").asText())
                    && "fetch".equals(details.path("toolKind").asText())
                    && "WebSearch".equals(details.path("toolName").asText())
                    && !details.path("toolCallId").asText().isBlank()
                    && !details.path("resource").asText().isBlank()) {
                return new PermissionEscalation(
                        runRef,
                        details.path("toolCallId").asText(),
                        details.path("resource").asText());
            }
        }
        throw new IOException("no exact WebSearch permission escalation is awaiting approval");
    }

    private static String sha256(String value) throws IOException {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException failure) {
            throw new IOException("SHA-256 is unavailable", failure);
        }
    }

    private static String text(Object value) {
        return value == null ? "" : value.toString().trim();
    }

    private record PermissionEscalation(String runRef, String toolCallId, String resource) {
    }

    void replayDeterministicClassification(WorkstreamPaths paths, String note) throws IOException {
        if (note == null || note.isBlank()) {
            throw new IOException("classification replay note is required");
        }
        var current = loadCurrent(paths);
        if (current.status() != WorkflowStatus.WAITING_FOR_RECOVERY
                || current.activeNodeInstanceIds().size() != 1) {
            throw new IOException("classification replay requires exactly one active recovery node");
        }
        var failed = loadNode(paths, current.activeNodeInstanceIds().getFirst());
        if (failed.status() != NodeStatus.FAILED
                || !"contract.compile".equals(failed.nodeDefinitionId())
                || !"TASK_CONTRACT_PROPOSAL_APPROVAL_MISSING".equals(
                LedgerUtils.text(LedgerUtils.resultValue(failed.result(), "reason")))) {
            throw new IOException("active recovery node is not a replayable classification misroute");
        }

        var iteration = objectMapper.readValue(
                paths.iterationJson(failed.iterationId()).toFile(), WorkflowIterationDocument.class);
        if (!failed.nodeDefinitionId().equals(iteration.targetNodeDefinitionId())
                || iteration.triggerNodeInstanceId().isBlank()) {
            throw new IOException("failed node does not have an authoritative classification trigger");
        }
        var classifier = loadNode(paths, iteration.triggerNodeInstanceId());
        if (!"acceptance.classify_failure".equals(classifier.nodeDefinitionId())
                || !"acceptance.failure_classify".equals(classifier.handlerType())
                || classifier.status() != NodeStatus.COMPLETED
                || !classifier.outputRefs().equals(failed.inputRefs())) {
            throw new IOException("failed node is not lineage-bound to a completed acceptance classifier");
        }

        GateDocument recoveryGate = null;
        for (var gateId : current.openGateIds()) {
            var gatePath = paths.gateJson(gateId);
            if (!java.nio.file.Files.isRegularFile(gatePath)) {
                continue;
            }
            var candidate = objectMapper.readValue(gatePath.toFile(), GateDocument.class);
            if (failed.nodeInstanceId().equals(candidate.nodeInstanceId()) && "open".equals(candidate.status())) {
                recoveryGate = candidate;
                break;
            }
        }
        if (recoveryGate == null) {
            throw new IOException("classification replay requires the failed node recovery gate");
        }

        var now = Instant.now();
        jsonWriter.write(paths.nodeJson(failed.nodeInstanceId()), new NodeInstanceDocument(
                failed.schemaVersion(),
                failed.nodeInstanceId(),
                failed.nodeDefinitionId(),
                failed.kind(),
                failed.handlerType(),
                NodeStatus.SKIPPED,
                failed.stageId(),
                failed.iterationId(),
                failed.inputRefs(),
                failed.inputTransition(),
                failed.outputRefs(),
                LedgerUtils.mergedResult(failed.result(), Map.of(
                        "classification_replay_compensated", true,
                        "classification_node_instance_id", classifier.nodeInstanceId(),
                        "compensation_note", note
                )),
                failed.runRef(),
                failed.latestExecutionId(),
                failed.startedAt(),
                now
        ));
        jsonWriter.write(paths.nodeJson(classifier.nodeInstanceId()), new NodeInstanceDocument(
                classifier.schemaVersion(),
                classifier.nodeInstanceId(),
                classifier.nodeDefinitionId(),
                classifier.kind(),
                classifier.handlerType(),
                NodeStatus.READY,
                classifier.stageId(),
                classifier.iterationId(),
                classifier.inputRefs(),
                classifier.inputTransition(),
                List.of(),
                Map.of(
                        "replay_of_status", classifier.status().name(),
                        "recovery_note", note,
                        "superseded_node_instance_id", failed.nodeInstanceId()
                ),
                classifier.runRef(),
                classifier.latestExecutionId(),
                null,
                null
        ));
        jsonWriter.write(
                paths.gateJson(recoveryGate.gateId()),
                recoveryGate.resolved("replay_classification", note)
        );

        var eventId = LedgerUtils.nextEventId(current.lastEventId());
        eventLog.appendEvent(paths, eventId, "deterministic_classification_replay_requested", Map.of(
                "classification_node_instance_id", classifier.nodeInstanceId(),
                "superseded_node_instance_id", failed.nodeInstanceId(),
                "recovery_gate_id", recoveryGate.gateId(),
                "note", note
        ));
        var resumed = new WorkflowCurrentDocument(
                current.schemaVersion(),
                current.workstreamId(),
                current.workflowInstanceId(),
                current.workflowId(),
                current.definitionVersion(),
                WorkflowStatus.RUNNING,
                List.of(classifier.nodeInstanceId()),
                List.of(),
                eventId,
                now
        );
        jsonWriter.write(paths.workflowCurrentJson(), resumed);
        eventLog.writeInstanceFromCurrent(paths, resumed, now);
    }

    void recoverStaleRunningNode(WorkstreamPaths paths, String note) throws IOException {
        var current = loadCurrent(paths);
        if (current.status() != WorkflowStatus.RUNNING) {
            throw new IOException("workflow is not running: " + current.status());
        }
        if (current.activeNodeInstanceIds().isEmpty()) {
            throw new IOException("no active running node to recover");
        }
        var node = loadNode(paths, current.activeNodeInstanceIds().get(0));
        if (node.status() != NodeStatus.RUNNING) {
            throw new IOException("active node is not running: " + node.nodeDefinitionId() + " (" + node.status() + ")");
        }
        var pid = runningPid(node);
        if (pid > 0 && ProcessHandle.of(pid).map(ProcessHandle::isAlive).orElse(false)) {
            throw new IOException("running process is still alive: " + pid);
        }

        var now = Instant.now();
        var failed = new NodeInstanceDocument(
                node.schemaVersion(),
                node.nodeInstanceId(),
                node.nodeDefinitionId(),
                node.kind(),
                node.handlerType(),
                NodeStatus.FAILED,
                node.stageId(),
                node.iterationId(),
                node.inputRefs(),
                node.inputTransition(),
                node.outputRefs(),
                LedgerUtils.mergedResult(node.result(), Map.of(
                        "reason", "STALE_RUNNING_PROCESS",
                        "message", "Running node had no live process and was moved to recovery.",
                        "recoverable", true,
                        "stale_running_pid", pid <= 0 ? "" : pid,
                        "recovery_note", note == null ? "" : note
                )),
                node.runRef(),
                node.latestExecutionId(),
                node.startedAt(),
                now
        );
        jsonWriter.write(paths.nodeJson(node.nodeInstanceId()), failed);

        var recoveryGateId = "recovery-" + node.nodeInstanceId();
        jsonWriter.write(paths.gateJson(recoveryGateId), new GateDocument(
                1,
                recoveryGateId,
                node.nodeInstanceId(),
                "recovery.review",
                "open",
                List.of("retry", "abort"),
                now,
                null,
                Map.of(
                        "node", node.nodeDefinitionId(),
                        "node_status", NodeStatus.FAILED.name(),
                        "outcome", "STALE_RUNNING_PROCESS",
                        "reason", "STALE_RUNNING_PROCESS",
                        "stale_running_pid", pid <= 0 ? "" : pid,
                        "note", note == null ? "" : note
                )
        ));

        var eventId = LedgerUtils.nextEventId(current.lastEventId());
        eventLog.appendEvent(paths, eventId, "node_stale_running_recovered", Map.of(
                "node", node.nodeDefinitionId(),
                "node_instance_id", node.nodeInstanceId(),
                "previous_status", node.status().name(),
                "stale_running_pid", pid <= 0 ? "" : pid,
                "recovery_gate_id", recoveryGateId,
                "note", note == null ? "" : note
        ));
        var recovered = new WorkflowCurrentDocument(
                1,
                current.workstreamId(),
                current.workflowInstanceId(),
                current.workflowId(),
                current.definitionVersion(),
                WorkflowStatus.WAITING_FOR_RECOVERY,
                List.of(node.nodeInstanceId()),
                List.of(recoveryGateId),
                eventId,
                now
        );
        jsonWriter.write(paths.workflowCurrentJson(), recovered);
        eventLog.writeInstanceFromCurrent(paths, recovered, now);
    }

    private static long runningPid(NodeInstanceDocument node) {
        var value = node.result() == null ? null : node.result().get("running_pid");
        if (value instanceof Number number) {
            return number.longValue();
        }
        if (value == null) {
            return 0;
        }
        try {
            return Long.parseLong(String.valueOf(value));
        } catch (NumberFormatException ignored) {
            return 0;
        }
    }

    void abortRecovery(WorkstreamPaths paths, String note) throws IOException {
        var current = loadCurrent(paths);
        if (current.status() != WorkflowStatus.WAITING_FOR_RECOVERY) {
            throw new IOException("workflow is not waiting for recovery: " + current.status());
        }
        if (current.activeNodeInstanceIds().isEmpty()) {
            throw new IOException("no active recovery node to abort");
        }
        var node = loadNode(paths, current.activeNodeInstanceIds().get(0));
        var eventId = LedgerUtils.nextEventId(current.lastEventId());
        eventLog.appendEvent(paths, eventId, "workflow_aborted", Map.of(
                "node", node.nodeDefinitionId(),
                "node_instance_id", node.nodeInstanceId(),
                "note", note == null ? "" : note,
                "recovery_gate_ids", current.openGateIds()
        ));
        var now = Instant.now();
        var aborted = new WorkflowCurrentDocument(
                1,
                current.workstreamId(),
                current.workflowInstanceId(),
                current.workflowId(),
                current.definitionVersion(),
                WorkflowStatus.FAILED,
                List.of(),
                List.of(),
                eventId,
                now
        );
        jsonWriter.write(paths.workflowCurrentJson(), aborted);
        eventLog.writeInstanceFromCurrent(paths, aborted, now);
    }

    void closeMistakenIteration(WorkstreamPaths paths, String note) throws IOException {
        var current = loadCurrent(paths);
        if (current.status() != WorkflowStatus.WAITING_FOR_RECOVERY) {
            throw new IOException("workflow is not waiting for recovery: " + current.status());
        }
        if (current.activeNodeInstanceIds().isEmpty()) {
            throw new IOException("no active recovery node to close");
        }
        var node = loadNode(paths, current.activeNodeInstanceIds().get(0));
        var iteration = objectMapper.readValue(paths.iterationJson(node.iterationId()).toFile(), WorkflowIterationDocument.class);
        if (!"approved".equals(iteration.triggerAction())) {
            throw new IOException("active iteration was not started by a final gate approval: " + iteration.iterationId());
        }
        if (iteration.triggerNodeInstanceId().isBlank()) {
            throw new IOException("active iteration does not record a trigger node");
        }
        var trigger = loadNode(paths, iteration.triggerNodeInstanceId());
        if (!"gate.human_next_stage_approval".equals(trigger.nodeDefinitionId())) {
            throw new IOException("active iteration was not started from final next-stage gate: " + trigger.nodeDefinitionId());
        }

        var now = Instant.now();
        var skipped = new NodeInstanceDocument(
                node.schemaVersion(),
                node.nodeInstanceId(),
                node.nodeDefinitionId(),
                node.kind(),
                node.handlerType(),
                NodeStatus.SKIPPED,
                node.stageId(),
                node.iterationId(),
                node.inputRefs(),
                node.inputTransition(),
                node.outputRefs(),
                LedgerUtils.mergedResult(node.result(), Map.of(
                        "closed_as_mistaken_iteration", true,
                        "close_note", note == null ? "" : note
                )),
                node.runRef(),
                node.latestExecutionId(),
                node.startedAt(),
                now
        );
        jsonWriter.write(paths.nodeJson(node.nodeInstanceId()), skipped);

        for (var gateId : current.openGateIds()) {
            var gatePath = paths.gateJson(gateId);
            if (!java.nio.file.Files.isRegularFile(gatePath)) {
                continue;
            }
            var gate = objectMapper.readValue(gatePath.toFile(), GateDocument.class);
            jsonWriter.write(gatePath, gate.resolved("close_mistaken_iteration", note));
        }

        var closeEventId = LedgerUtils.nextEventId(current.lastEventId());
        eventLog.appendEvent(paths, closeEventId, "mistaken_iteration_closed", Map.of(
                "node", node.nodeDefinitionId(),
                "node_instance_id", node.nodeInstanceId(),
                "iteration_id", node.iterationId(),
                "trigger_node_instance_id", iteration.triggerNodeInstanceId(),
                "trigger_action", iteration.triggerAction(),
                "note", note == null ? "" : note
        ));
        var completedEventId = LedgerUtils.nextEventId(closeEventId);
        eventLog.appendEvent(paths, completedEventId, "workflow_completed", Map.of(
                "last_node", trigger.nodeDefinitionId(),
                "outcome", "close_mistaken_iteration"
        ));
        var completed = new WorkflowCurrentDocument(
                1,
                current.workstreamId(),
                current.workflowInstanceId(),
                current.workflowId(),
                current.definitionVersion(),
                WorkflowStatus.COMPLETED,
                List.of(),
                List.of(),
                completedEventId,
                now
        );
        jsonWriter.write(paths.workflowCurrentJson(), completed);
        eventLog.writeInstanceFromCurrent(paths, completed, now);
    }

    NodeInstanceDocument setLatestExecution(WorkstreamPaths paths, String nodeInstanceId, String nodeExecutionId) throws IOException {
        var node = loadNode(paths, nodeInstanceId);
        var updated = new NodeInstanceDocument(
                node.schemaVersion(),
                node.nodeInstanceId(),
                node.nodeDefinitionId(),
                node.kind(),
                node.handlerType(),
                node.status(),
                node.stageId(),
                node.iterationId(),
                node.inputRefs(),
                node.inputTransition(),
                node.outputRefs(),
                node.result(),
                node.runRef(),
                nodeExecutionId,
                node.startedAt(),
                node.finishedAt()
        );
        jsonWriter.write(paths.nodeJson(nodeInstanceId), updated);
        return updated;
    }
}

package dev.dual.ledger.file;

import java.time.Instant;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public record GateDocument(
        int schemaVersion,
        String gateId,
        String nodeInstanceId,
        String gateType,
        String status,
        List<String> allowedActions,
        Instant openedAt,
        Instant resolvedAt,
        Map<String, Object> result
) {
    public GateDocument {
        if (schemaVersion <= 0) {
            throw new IllegalArgumentException("schemaVersion must be positive");
        }
        requireText(gateId, "gateId");
        requireText(nodeInstanceId, "nodeInstanceId");
        requireText(gateType, "gateType");
        requireText(status, "status");
        allowedActions = List.copyOf(allowedActions == null ? List.of() : allowedActions);
        allowedActions.forEach(value -> requireText(value, "allowedActions"));
        if (openedAt == null) {
            throw new IllegalArgumentException("openedAt is required");
        }
        result = copyMapAllowingNullValues(result);
    }

    GateDocument resolved(String action, String note) {
        var resolvedResult = new LinkedHashMap<String, Object>(result);
        resolvedResult.put("human_action", action == null ? "" : action);
        resolvedResult.put("note", note == null ? "" : note);
        return new GateDocument(
                schemaVersion,
                gateId,
                nodeInstanceId,
                gateType,
                "resolved",
                allowedActions,
                openedAt,
                Instant.now(),
                resolvedResult
        );
    }

    private static Map<String, Object> copyMapAllowingNullValues(Map<String, Object> source) {
        if (source == null) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, Object>();
        for (Map.Entry<?, ?> entry : source.entrySet()) {
            if (!(entry.getKey() instanceof String key) || key.isBlank()) {
                throw new IllegalArgumentException("result key is required");
            }
            copy.put(key, entry.getValue());
        }
        return Collections.unmodifiableMap(copy);
    }

    private static void requireText(String value, String field) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(field + " is required");
        }
    }
}

