    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> mapList(Object value) {
        if (value instanceof List<?> list) {
            return list.stream()
                    .filter(Map.class::isInstance)
                    .map(item -> (Map<String, Object>) item)
                    .toList();
        }
        return List.of();
    }

    private static long longValue(Object value) {
        if (value instanceof Number number) {
            return number.longValue();
        }
        if (value != null) {
            try {
                return Long.parseLong(String.valueOf(value));
            } catch (NumberFormatException ignored) {
                return 0;
            }
        }
        return 0;
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    @SuppressWarnings("unchecked")
    private static List<String> textList(Object value) {
        if (value instanceof List<?> list) {
            return list.stream()
                    .map(MetricsProjectionWriter::text)
                    .filter(item -> !item.isBlank())
                    .toList();
        }
        return List.of();
    }

    private static String nonBlank(String value, String fallback) {
        return value == null || value.isBlank() ? fallback : value;
    }

    private static String normalizePath(String value) {
        var text = text(value);
        while (text.startsWith("./")) {
            text = text.substring(2);
        }
        return text;
    }

    private static boolean ignoredTelemetryFile(String value) {
        return value.startsWith(".agent/") || value.startsWith(".git/") || value.startsWith("/Users/") || value.startsWith("/private/");
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> map(Object value) {
        if (value instanceof Map<?, ?> source) {
            var result = new LinkedHashMap<String, Object>();
            for (var entry : source.entrySet()) {
                if (entry.getKey() instanceof String key) {
                    result.put(key, entry.getValue());
                }
            }
            return result;
        }
        return Map.of();
    }

    private static BigDecimal decimalValue(Object value) {
        if (value instanceof BigDecimal decimal) {
            return decimal;
        }
        if (value instanceof Number number) {
            return BigDecimal.valueOf(number.doubleValue());
        }
        if (value != null) {
            try {
                return new BigDecimal(String.valueOf(value));
            } catch (NumberFormatException ignored) {
                return BigDecimal.ZERO;
            }
        }
        return BigDecimal.ZERO;
    }

    private static final class CostEconomicsSummary {
        private final LinkedHashMap<String, Long> byReliability = new LinkedHashMap<>();
        private final LinkedHashMap<String, Long> byCostEstimateReliability = new LinkedHashMap<>();
        private final LinkedHashMap<String, Long> byDecision = new LinkedHashMap<>();
        private final LinkedHashMap<String, BigDecimal> clientReportedByCurrency = new LinkedHashMap<>();
        private final LinkedHashMap<String, BigDecimal> officialCalculatedByCurrency = new LinkedHashMap<>();

        void add(Map<String, Object> costEconomics) {
            var reliability = nonBlank(text(costEconomics.get("cacheSignalReliability")), "unknown");
            byReliability.merge(reliability, 1L, Long::sum);
            var costReliability = nonBlank(text(costEconomics.get("costEstimateReliability")), "unknown");
            byCostEstimateReliability.merge(costReliability, 1L, Long::sum);
            var decision = nonBlank(text(costEconomics.get("providerCacheDecision")), "unknown");
            byDecision.merge(decision, 1L, Long::sum);
            var reported = decimalValue(costEconomics.get("clientReportedCost"));
            var reportedCurrency = text(costEconomics.get("clientReportedCurrency"));
            if (!reportedCurrency.isBlank() && reported.signum() != 0) {
                clientReportedByCurrency.merge(reportedCurrency, reported, BigDecimal::add);
            }
            var calculated = decimalValue(costEconomics.get("officialCalculatedCost"));
            var calculatedCurrency = text(costEconomics.get("officialCalculatedCurrency"));
            if (!calculatedCurrency.isBlank() && calculated.signum() != 0) {
                officialCalculatedByCurrency.merge(calculatedCurrency, calculated, BigDecimal::add);
            }
        }

        Map<String, Object> toMap() {
            var out = new LinkedHashMap<String, Object>();
            out.put("byReliability", byReliability);
            out.put("byCostEstimateReliability", byCostEstimateReliability);
            out.put("byDecision", byDecision);
            out.put("clientReportedCostByCurrency", clientReportedByCurrency);
            out.put("officialCalculatedCostByCurrency", officialCalculatedByCurrency);
            out.put("providerReportedCostByCurrency", clientReportedByCurrency);
            out.put("dualCalculatedCostByCurrency", officialCalculatedByCurrency);
            return out;
        }
    }

    private static final class UsageMetric {
        private long inputTokens;
        private long outputTokens;
        private long cachedReadTokens;
        private long cachedWriteTokens;
        private long totalTokens;
        private long contextUsedTokens;
        private final LinkedHashMap<String, BigDecimal> costByCurrency = new LinkedHashMap<>();

        static UsageMetric from(Map<String, Object> usage) {
            var metric = new UsageMetric();
            metric.inputTokens = longValue(usage.get("inputTokens"));
            metric.outputTokens = longValue(usage.get("outputTokens"));
            metric.cachedReadTokens = longValue(usage.get("cachedReadTokens"));
            metric.cachedWriteTokens = longValue(usage.get("cachedWriteTokens"));
            metric.totalTokens = longValue(usage.get("totalTokens"));
            if (metric.totalTokens == 0) {
                metric.totalTokens = metric.inputTokens + metric.outputTokens + metric.cachedReadTokens + metric.cachedWriteTokens;
            }
            var currency = text(usage.get("costCurrency"));
            var amount = decimalValue(usage.get("costAmount"));
            if (!currency.isBlank() && amount.signum() != 0) {
                metric.costByCurrency.put(currency, amount);
            }
            metric.contextUsedTokens = longValue(usage.get("contextUsedTokens"));
            return metric;
        }

        void add(UsageMetric other) {
            inputTokens += other.inputTokens;
            outputTokens += other.outputTokens;
            cachedReadTokens += other.cachedReadTokens;
            cachedWriteTokens += other.cachedWriteTokens;
            totalTokens += other.totalTokens;
            contextUsedTokens = Math.max(contextUsedTokens, other.contextUsedTokens);
            for (var entry : other.costByCurrency.entrySet()) {
                costByCurrency.merge(entry.getKey(), entry.getValue(), BigDecimal::add);
            }
        }

        Map<String, Object> toMap() {
            var map = new LinkedHashMap<String, Object>();
            map.put("inputTokens", inputTokens);
            map.put("outputTokens", outputTokens);
            map.put("cachedReadTokens", cachedReadTokens);
            map.put("cachedWriteTokens", cachedWriteTokens);
            map.put("totalTokens", totalTokens);
            map.put("contextUsedTokens", contextUsedTokens);
            map.put("costByCurrency", new LinkedHashMap<>(costByCurrency));
            return map;
        }
    }

    private static final class ToolMetric {
        private long toolCallCount;
        private long readCount;
        private long writeCount;
        private long bashCount;
        private long otherCount;

        static ToolMetric from(Map<String, Object> toolUsage) {
            var metric = new ToolMetric();
            metric.toolCallCount = longValue(toolUsage.get("toolCallCount"));
            metric.readCount = longValue(toolUsage.get("readCount"));
            metric.writeCount = longValue(toolUsage.get("writeCount"));
            metric.bashCount = longValue(toolUsage.get("bashCount"));
            metric.otherCount = longValue(toolUsage.get("otherCount"));
            return metric;
        }

        void add(ToolMetric other) {
            toolCallCount += other.toolCallCount;
            readCount += other.readCount;
            writeCount += other.writeCount;
            bashCount += other.bashCount;
            otherCount += other.otherCount;
        }

        Map<String, Object> toMap() {
            var map = new LinkedHashMap<String, Object>();
            map.put("toolCallCount", toolCallCount);
            map.put("readCount", readCount);
            map.put("writeCount", writeCount);
            map.put("bashCount", bashCount);
            map.put("otherCount", otherCount);
            return map;
        }
    }

    private static final class ReadFileMetric {
        private final String path;
        private final Set<String> runIds = new LinkedHashSet<>();
        private final Set<String> nodes = new LinkedHashSet<>();
        private final Set<String> agents = new LinkedHashSet<>();
        private boolean evidenceKnown;
        private boolean rereadReasonRequired;
        private boolean reasonDeclared;

        private ReadFileMetric(String path) {
            this.path = path;
        }

        void accept(String runId, String nodeId, String agent, boolean evidenceKnown,
                    boolean rereadReasonRequired, boolean reasonDeclared) {
            runIds.add(runId);
            nodes.add(nodeId);
            agents.add(agent);
            this.evidenceKnown = this.evidenceKnown || evidenceKnown;
            this.rereadReasonRequired = this.rereadReasonRequired || rereadReasonRequired;
            this.reasonDeclared = this.reasonDeclared || reasonDeclared;
        }

        boolean isRepeated() {
            return runIds.size() > 1;
        }

        int count() {
            return runIds.size();
        }

        String path() {
            return path;
        }

        boolean rereadReasonRequired() {
            return rereadReasonRequired;
        }

        boolean rereadReasonMissing() {
            return isRepeated() && rereadReasonRequired && !reasonDeclared;
        }

        String rereadReasonStatus() {
            if (!isRepeated() || !rereadReasonRequired) {
                return "not_required";
            }
            return reasonDeclared ? "recorded" : "missing";
        }

        Map<String, Object> toMap() {
            var map = new LinkedHashMap<String, Object>();
            map.put("path", path);
            map.put("count", count());
            map.put("runIds", List.copyOf(runIds));
            map.put("nodes", List.copyOf(nodes));
            map.put("agents", List.copyOf(agents));
            map.put("evidenceKnown", evidenceKnown);
            map.put("rereadReasonRequired", rereadReasonRequired);
            map.put("rereadReasonStatus", rereadReasonStatus());
            return map;
        }
    }

    private static Set<String> declaredRereadPaths(Object value) {
        if (!(value instanceof List<?> list)) {
            return Set.of();
        }
        var paths = new LinkedHashSet<String>();
        for (var item : list) {
            if (item instanceof Map<?, ?> map) {
                var normalized = normalizePath(text(map.get("path")));
                if (!normalized.isBlank()) {
                    paths.add(normalized);
                }
            }
        }
        return paths;
    }

    private record ReadReusePolicy(Set<String> reusableFiles, List<String> allowedReasons) {
        static ReadReusePolicy empty() {
            return new ReadReusePolicy(Set.of(), List.of());
        }

        boolean requiresReason(String path) {
            return reusableFiles.contains(path);
        }
    }

    private static final class ProviderMetric {
        private long runCount;
        private long completedCount;
        private long failedCount;
        private long preparedCount;
        private long recoverableFailureCount;
        private long totalDurationMs;

        void accept(String status, long durationMs, boolean recoverable) {
            runCount++;
            totalDurationMs += Math.max(0, durationMs);
            switch (status) {
                case "completed" -> completedCount++;
                case "failed" -> {
                    failedCount++;
                    if (recoverable) {
                        recoverableFailureCount++;
                    }
                }
                case "prepared" -> preparedCount++;
                case "recoverable_failed" -> {
                    failedCount++;
                    recoverableFailureCount++;
                }
                default -> {
                    if (status.contains("recoverable")) {
                        recoverableFailureCount++;
                    }
                }
            }
        }

        Map<String, Object> toMap() {
            var map = new LinkedHashMap<String, Object>();
            map.put("runCount", runCount);
            map.put("completedCount", completedCount);
            map.put("failedCount", failedCount);
            map.put("preparedCount", preparedCount);
            map.put("recoverableFailureCount", recoverableFailureCount);
            map.put("totalDurationMs", totalDurationMs);
            map.put("averageDurationMs", runCount == 0 ? 0 : totalDurationMs / runCount);
            return map;
        }
    }

    private static final class MetricsProjectionException extends RuntimeException {
        MetricsProjectionException(IOException cause) {
            super(cause);
        }

        IOException unwrap() {
            return (IOException) getCause();
        }
    }
}

package dev.dual.ledger.file;

import dev.dual.core.workflow.NodeKind;

import java.time.Instant;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

public record AgentTaskDocument(
        int schemaVersion,
        String agentTaskId,
        String workflowExecutionId,
        String nodeInstanceId,
        String nodeDefinitionId,
        NodeKind nodeKind,
        String handlerType,
        AgentTaskStatus status,
        String agent,
        String session,
        String promptTemplate,
        String contextPackageRef,
        String expectedContract,
        Map<String, Object> dispatch,
        String nodeExecutionId,
        String errorMessage,
        Instant createdAt,
        Instant claimedAt,
        Instant completedAt
) {
    public AgentTaskDocument {
        if (schemaVersion <= 0) {
            throw new IllegalArgumentException("schemaVersion must be positive");
        }
        requireText(agentTaskId, "agentTaskId");
        requireText(workflowExecutionId, "workflowExecutionId");
        requireText(nodeInstanceId, "nodeInstanceId");
        requireText(nodeDefinitionId, "nodeDefinitionId");
        if (nodeKind == null) {
            throw new IllegalArgumentException("nodeKind is required");
        }
        requireText(handlerType, "handlerType");
        if (status == null) {
            throw new IllegalArgumentException("status is required");
        }
        agent = agent == null ? "" : agent;
        session = session == null ? "" : session;
        promptTemplate = promptTemplate == null ? "" : promptTemplate;
        contextPackageRef = contextPackageRef == null ? "" : contextPackageRef;
        expectedContract = expectedContract == null ? "" : expectedContract;
        dispatch = copyMapAllowingNullValues(dispatch);
        nodeExecutionId = nodeExecutionId == null ? "" : nodeExecutionId;
        errorMessage = errorMessage == null ? "" : errorMessage;
        if (createdAt == null) {
            throw new IllegalArgumentException("createdAt is required");
        }
    }

    private static Map<String, Object> copyMapAllowingNullValues(Map<String, Object> source) {
        if (source == null) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, Object>();
        for (Map.Entry<?, ?> entry : source.entrySet()) {
            if (!(entry.getKey() instanceof String key) || key.isBlank()) {
                throw new IllegalArgumentException("dispatch key is required");
            }
            copy.put(key, entry.getValue());
        }
        return Collections.unmodifiableMap(copy);
    }

    private static void requireText(String value, String field) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(field + " is required");
        }
    }
}

package dev.dual.ledger.file;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import dev.dual.core.flow.BuiltInFlowOrchestrationKernel;
import dev.dual.core.flow.FlowOrchestrationKernel;
import dev.dual.core.workflow.NodeInstance;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowDefinition;
import dev.dual.core.workflow.WorkflowStatus;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Optional;

public final class WorkflowFileLedger {
    private final AtomicJsonWriter jsonWriter;
    private final ObjectMapper objectMapper;
    private final LedgerEventLog eventLog;
    private final RoutingEngine routingEngine;
    private final NodeStateWriter nodeStateWriter;
    private final TimelineProjectionWriter timelineProjectionWriter;
    private final MetricsProjectionWriter metricsProjectionWriter;
    private final FailureSummaryWriter failureSummaryWriter;
    private final ExecutionLedgerWriter executionLedgerWriter;
    private final AgentTaskLedgerWriter agentTaskLedgerWriter;

    public WorkflowFileLedger() {
        this(new BuiltInFlowOrchestrationKernel());
    }

    public WorkflowFileLedger(FlowOrchestrationKernel flowKernel) {
        this(new AtomicJsonWriter(), flowKernel);
    }

    WorkflowFileLedger(AtomicJsonWriter jsonWriter) {
        this(jsonWriter, new BuiltInFlowOrchestrationKernel());
    }

    WorkflowFileLedger(AtomicJsonWriter jsonWriter, FlowOrchestrationKernel flowKernel) {
        if (flowKernel == null) {
            throw new IllegalArgumentException("flow orchestration kernel is required");
        }
        this.jsonWriter = jsonWriter;
        this.objectMapper = jsonWriter.objectMapper();
        var jsonlMapper = jsonWriter.objectMapper().copy()
                .disable(SerializationFeature.INDENT_OUTPUT);
        this.eventLog = new LedgerEventLog(jsonWriter, jsonlMapper);
        var revisionTracker = new RevisionTracker(jsonWriter, this.objectMapper, eventLog);
        this.routingEngine = new RoutingEngine(jsonWriter, this.objectMapper, eventLog, revisionTracker, flowKernel);
        this.nodeStateWriter = new NodeStateWriter(jsonWriter, this.objectMapper, eventLog);
        this.timelineProjectionWriter = new TimelineProjectionWriter(jsonWriter, this.objectMapper);
        this.metricsProjectionWriter = new MetricsProjectionWriter(jsonWriter, this.objectMapper);
        this.failureSummaryWriter = new FailureSummaryWriter(this.objectMapper);
        this.executionLedgerWriter = new ExecutionLedgerWriter(jsonWriter);
        this.agentTaskLedgerWriter = new AgentTaskLedgerWriter(jsonWriter);
    }

    public void initialize(WorkstreamPaths paths, String workflowInstanceId, WorkflowDefinition definition)
            throws IOException {
        if (Files.exists(paths.workflowCurrentJson()) || Files.exists(paths.eventsJsonl())) {
            throw new IOException("workflow ledger already initialized: " + paths.workstreamDir());
        }
        Files.createDirectories(paths.workflowDir());
        Files.createDirectories(paths.workflowExecutionsDir());
        Files.createDirectories(paths.nodeExecutionsDir());
        Files.createDirectories(paths.agentTasksDir());
        Files.createDirectories(paths.nodesDir());
        Files.createDirectories(paths.gatesDir());
        Files.createDirectories(paths.iterationsDir());

        var now = Instant.now();
        var entry = definition.node(definition.entryNodeId());
        var nodeInstanceId = LedgerUtils.nodeInstanceId(entry.id(), 1);
        var eventId = "evt-000001";

        appendEvent(paths, eventId, "workflow_started", Map.of(
                "workflow_id", definition.workflowId(),
                "entry_node", entry.id()
        ));
        jsonWriter.write(paths.workflowDefinitionJson(), new WorkflowDefinitionDocument(
                1,
                definition.workflowId(),
                definition.version(),
                definition.entryNodeId(),
                definition.nodes(),
                definition.edges()
        ));
        jsonWriter.write(paths.iterationJson("iter-001"), WorkflowIterationDocument.initial(entry.id(), now));
        jsonWriter.write(paths.workflowInstanceJson(), new WorkflowInstanceDocument(
                1,
                workflowInstanceId,
                definition.workflowId(),
                definition.version(),
                WorkflowStatus.RUNNING,
                List.of(nodeInstanceId),
                eventId,
                now,
                now
        ));
        jsonWriter.write(paths.workflowCurrentJson(), new WorkflowCurrentDocument(
                1,
                paths.workstreamId().value(),
                workflowInstanceId,
                definition.workflowId(),
                definition.version(),
                WorkflowStatus.RUNNING,
                List.of(nodeInstanceId),
                List.of(),
                eventId,
                now
        ));
        jsonWriter.write(paths.nodeJson(nodeInstanceId), new NodeInstanceDocument(
                1,
                nodeInstanceId,
                entry.id(),
                entry.kind(),
                entry.handlerType(),
                NodeStatus.READY,
                LedgerUtils.stageId(entry.id()),
                "iter-001",
                List.of(),
                Map.of(),
                List.of(),
                Map.of(),
                null,
                "",
                null,
                null
        ));
        refreshProjections(paths);
    }

    public WorkflowCurrentDocument loadCurrent(WorkstreamPaths paths) throws IOException {
        return objectMapper.readValue(paths.workflowCurrentJson().toFile(), WorkflowCurrentDocument.class);
    }

    public WorkflowDefinition loadDefinition(WorkstreamPaths paths) throws IOException {
        var jsonPath = paths.workflowDefinitionJson();
        var json = Files.readString(jsonPath, StandardCharsets.UTF_8);
        var doc = objectMapper.readValue(json, WorkflowDefinitionDocument.class);

        // Migrate if schema version is older than current
        if (doc.schemaVersion() < LedgerMigrator.currentVersion()) {
            json = LedgerMigrator.migrate(json, doc.schemaVersion());
            // Write migrated version back
            Files.writeString(jsonPath, json, StandardCharsets.UTF_8);
            doc = objectMapper.readValue(json, WorkflowDefinitionDocument.class);
        }

        return new WorkflowDefinition(
                doc.workflowId(),
                doc.version(),
                doc.entryNodeId(),
                doc.nodes(),
                doc.edges()
        );
    }

    public NodeInstanceDocument loadNode(WorkstreamPaths paths, String nodeInstanceId) throws IOException {
        return objectMapper.readValue(paths.nodeJson(nodeInstanceId).toFile(), NodeInstanceDocument.class);
    }

    public GateDocument loadOpenGateForNode(WorkstreamPaths paths, String nodeInstanceId) throws IOException {
        var current = loadCurrent(paths);
        for (var gateId : current.openGateIds()) {
            var gatePath = paths.gateJson(gateId);
            if (!Files.isRegularFile(gatePath)) {
                continue;
            }
            var gate = objectMapper.readValue(gatePath.toFile(), GateDocument.class);
            if (nodeInstanceId.equals(gate.nodeInstanceId()) && "open".equals(gate.status())) {
                return gate;
            }
        }
        throw new IOException("no matching open gate document for node: " + nodeInstanceId);
    }

    public NodeInstance loadCoreNode(WorkstreamPaths paths, String nodeInstanceId) throws IOException {
        var node = loadNode(paths, nodeInstanceId);
        return new NodeInstance(
                node.nodeInstanceId(),
                node.nodeDefinitionId(),
                node.kind(),
                node.handlerType(),
                node.status(),
                node.stageId(),
                node.iterationId(),
                node.inputRefs(),
                node.outputRefs(),
                node.result(),
                node.runRef(),
                node.startedAt(),
                node.finishedAt()
        );
    }

    public void completeAndRoute(
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            String nodeInstanceId,
            NodeStatus completedStatus,
            String outcome,
            List<String> outputRefs,
            Map<String, Object> result
    ) throws IOException {
        routingEngine.completeAndRoute(paths, definition, nodeInstanceId, completedStatus, outcome, outputRefs, result);
        if (completedStatus == NodeStatus.FAILED || completedStatus == NodeStatus.BLOCKED) {
            failureSummaryWriter.write(paths, nodeInstanceId);
        }
        refreshProjections(paths);
    }

    public void appendEvent(WorkstreamPaths paths, String eventId, String eventType, Map<String, Object> payload)
            throws IOException {
        eventLog.appendEvent(paths, eventId, eventType, payload);
    }

    public WorkflowExecutionDocument startWorkflowExecution(
            WorkstreamPaths paths,
            WorkflowCurrentDocument current,
            String trigger
    ) throws IOException {
        return executionLedgerWriter.startWorkflowExecution(paths, current, trigger);
    }

    public WorkflowExecutionDocument finishWorkflowExecution(
            WorkstreamPaths paths,
            WorkflowExecutionDocument workflowExecution,
            List<String> nodeExecutionIds,
            WorkflowExecutionStatus status,
            String stopReason
    ) throws IOException {
        return executionLedgerWriter.finishWorkflowExecution(paths, workflowExecution, nodeExecutionIds, status, stopReason);
    }

    public AgentTaskDocument createAgentTask(
            WorkstreamPaths paths,
            String workflowExecutionId,
            dev.dual.core.workflow.NodeDefinition definition,
            NodeInstanceDocument node
    ) throws IOException {
        var task = agentTaskLedgerWriter.create(paths, workflowExecutionId, definition, node);
        appendEvent(paths, "agent-task-" + task.agentTaskId(), "agent_task_queued", Map.of(
                "agent_task_id", task.agentTaskId(),
                "workflow_execution_id", workflowExecutionId,
                "node", node.nodeDefinitionId(),
                "node_instance_id", node.nodeInstanceId(),
                "handler_type", node.handlerType(),
                "agent", task.agent(),
                "session", task.session()
        ));
        refreshProjections(paths);
        return task;
    }

    public AgentTaskDocument markAgentTaskRunning(
            WorkstreamPaths paths,
            AgentTaskDocument task,
            String nodeExecutionId
    ) throws IOException {
        var updated = agentTaskLedgerWriter.markRunning(paths, task, nodeExecutionId);
        appendEvent(paths, "agent-task-running-" + updated.agentTaskId(), "agent_task_started", Map.of(
                "agent_task_id", updated.agentTaskId(),
                "node_execution_id", nodeExecutionId,
                "node", updated.nodeDefinitionId(),
                "node_instance_id", updated.nodeInstanceId()
        ));
        refreshProjections(paths);
        return updated;
    }

    public AgentTaskDocument markAgentTaskFinished(
            WorkstreamPaths paths,
            AgentTaskDocument task,
            dev.dual.core.workflow.NodeResult result
    ) throws IOException {
        var updated = agentTaskLedgerWriter.markFinished(paths, task, result);
        var failed = updated.status() == AgentTaskStatus.FAILED;
        appendEvent(paths, (failed ? "agent-task-failed-" : "agent-task-succeeded-") + updated.agentTaskId(),
                failed ? "agent_task_failed" : "agent_task_completed", Map.of(
                "agent_task_id", updated.agentTaskId(),
                "node_execution_id", updated.nodeExecutionId(),
                "node", updated.nodeDefinitionId(),
                "node_instance_id", updated.nodeInstanceId(),
                "status", updated.status(),
                "error", failed ? updated.errorMessage() : ""
        ));
        refreshProjections(paths);
        return updated;
    }

    public AgentTaskDocument markAgentTaskFailed(
            WorkstreamPaths paths,
            AgentTaskDocument task,
            Exception failure
    ) throws IOException {
        var updated = agentTaskLedgerWriter.markFailed(paths, task, failure);
        appendEvent(paths, "agent-task-failed-" + updated.agentTaskId(), "agent_task_failed", Map.of(
                "agent_task_id", updated.agentTaskId(),
                "node_execution_id", updated.nodeExecutionId(),
                "node", updated.nodeDefinitionId(),
                "node_instance_id", updated.nodeInstanceId(),
                "error", failure == null ? "" : String.valueOf(failure.getMessage())
        ));
        refreshProjections(paths);
        return updated;
    }

    public List<AgentTaskDocument> readAgentTasks(WorkstreamPaths paths) throws IOException {
        return agentTaskLedgerWriter.readAgentTasks(paths);
    }

    public Optional<AgentTaskDocument> readAgentTask(WorkstreamPaths paths, String agentTaskId) throws IOException {
        return agentTaskLedgerWriter.readAgentTask(paths, agentTaskId);
    }

    public Optional<AgentTaskDocument> firstQueuedAgentTask(WorkstreamPaths paths) throws IOException {
        return agentTaskLedgerWriter.firstQueued(paths);
    }

    public NodeExecutionDocument startNodeExecution(
            WorkstreamPaths paths,
            String workflowExecutionId,
            NodeInstanceDocument node,
            AgentTaskDocument agentTask,
            long pid
    ) throws IOException {
        var execution = executionLedgerWriter.startNodeExecution(paths, workflowExecutionId, node, agentTask, pid);
        nodeStateWriter.setLatestExecution(paths, node.nodeInstanceId(), execution.nodeExecutionId());
