package dev.dual.ledger.file;

import java.time.Instant;
import java.util.List;

/** Mutable application lifecycle for one accepted immutable delivery candidate. */
public record DeliveryMergePlan(
        int schemaVersion,
        String workstreamId,
        String sourceWorktree,
        String targetRepo,
        String acceptanceDecision,
        String candidateRef,
        String candidateSha256,
        String baseCommit,
        String baseTree,
        String expectedResultTree,
        List<String> changedFiles,
        List<String> excludedFiles,
        DeliveryMergeStatus status,
        String commit,
        String failureCode,
        String failureReason,
        Instant updatedAt
) {
    public DeliveryMergePlan {
        candidateRef = blank(candidateRef);
        candidateSha256 = blank(candidateSha256);
        baseCommit = blank(baseCommit);
        baseTree = blank(baseTree);
        expectedResultTree = blank(expectedResultTree);
        changedFiles = changedFiles == null ? List.of() : List.copyOf(changedFiles);
        excludedFiles = excludedFiles == null ? List.of() : List.copyOf(excludedFiles);
        commit = blank(commit);
        failureCode = blank(failureCode);
        failureReason = blank(failureReason);
    }

    public static DeliveryMergePlan create(
            String workstreamId,
            String sourceWorktree,
            String targetRepo,
            String acceptanceDecision,
            String candidateRef,
            String candidateSha256,
            String baseCommit,
            String baseTree,
            String expectedResultTree,
            List<String> changedFiles,
            List<String> excludedFiles,
            DeliveryMergeStatus status,
            String failureCode,
            String failureReason
    ) {
        return new DeliveryMergePlan(
                2, workstreamId, sourceWorktree, targetRepo, acceptanceDecision,
                blank(candidateRef), blank(candidateSha256), blank(baseCommit), blank(baseTree), blank(expectedResultTree),
                List.copyOf(changedFiles), List.copyOf(excludedFiles), status, "", blank(failureCode),
                blank(failureReason), Instant.now()
        );
    }

    public DeliveryMergePlan withStatus(
            DeliveryMergeStatus nextStatus,
            String nextFailureCode,
            String nextFailureReason
    ) {
        return new DeliveryMergePlan(
                schemaVersion, workstreamId, sourceWorktree, targetRepo, acceptanceDecision,
                candidateRef, candidateSha256, baseCommit, baseTree, expectedResultTree,
                changedFiles, excludedFiles, nextStatus, commit, blank(nextFailureCode), blank(nextFailureReason), Instant.now()
        );
    }

    public DeliveryMergePlan withCommitted(String commitSha) {
        if (commitSha == null || commitSha.isBlank()) throw new IllegalArgumentException("commitSha is required");
        return new DeliveryMergePlan(
                schemaVersion, workstreamId, sourceWorktree, targetRepo, acceptanceDecision,
                candidateRef, candidateSha256, baseCommit, baseTree, expectedResultTree,
                changedFiles, excludedFiles, DeliveryMergeStatus.COMMITTED, commitSha, "", "", Instant.now()
        );
    }

    public DeliveryMergePlan withFailure(String nextFailureCode, String nextFailureReason) {
        return new DeliveryMergePlan(
                schemaVersion, workstreamId, sourceWorktree, targetRepo, acceptanceDecision,
                candidateRef, candidateSha256, baseCommit, baseTree, expectedResultTree,
                changedFiles, excludedFiles, status, commit, blank(nextFailureCode), blank(nextFailureReason), Instant.now()
        );
    }

    private static String blank(String value) {
        return value == null ? "" : value;
    }
}

package dev.dual.ledger.file;

import dev.dual.core.workflow.NodeKind;
import dev.dual.core.workflow.NodeStatus;

import java.time.Instant;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public record NodeInstanceDocument(
        int schemaVersion,
        String nodeInstanceId,
        String nodeDefinitionId,
        NodeKind kind,
        String handlerType,
        NodeStatus status,
        String stageId,
        String iterationId,
        List<String> inputRefs,
        Map<String, Object> inputTransition,
        List<String> outputRefs,
        Map<String, Object> result,
        String runRef,
        String latestExecutionId,
        Instant startedAt,
        Instant finishedAt
) {
    public NodeInstanceDocument {
        if (schemaVersion <= 0) {
            throw new IllegalArgumentException("schemaVersion must be positive");
        }
        requireText(nodeInstanceId, "nodeInstanceId");
        requireText(nodeDefinitionId, "nodeDefinitionId");
        if (kind == null) {
            throw new IllegalArgumentException("kind is required");
        }
        requireText(handlerType, "handlerType");
        if (status == null) {
            throw new IllegalArgumentException("status is required");
        }
        requireText(stageId, "stageId");
        requireText(iterationId, "iterationId");
        inputRefs = List.copyOf(inputRefs == null ? List.of() : inputRefs);
        inputRefs.forEach(value -> requireText(value, "inputRefs"));
        inputTransition = copyMapAllowingNullValues(inputTransition, "inputTransition");
        outputRefs = List.copyOf(outputRefs == null ? List.of() : outputRefs);
        outputRefs.forEach(value -> requireText(value, "outputRefs"));
        result = copyMapAllowingNullValues(result, "result");
        latestExecutionId = latestExecutionId == null ? "" : latestExecutionId;
    }

    private static Map<String, Object> copyMapAllowingNullValues(Map<String, Object> source, String field) {
        if (source == null) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, Object>();
        for (Map.Entry<?, ?> entry : source.entrySet()) {
            if (!(entry.getKey() instanceof String key) || key.isBlank()) {
                throw new IllegalArgumentException(field + " key is required");
            }
            copy.put(key, entry.getValue());
        }
        return Collections.unmodifiableMap(copy);
    }

    private static void requireText(String value, String field) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(field + " is required");
        }
    }
}

package dev.dual.ledger.file;

import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;

final class LedgerEventLog {
    private final AtomicJsonWriter jsonWriter;
    private final ObjectMapper jsonlMapper;

    LedgerEventLog(AtomicJsonWriter jsonWriter, ObjectMapper jsonlMapper) {
        this.jsonWriter = jsonWriter;
        this.jsonlMapper = jsonlMapper;
    }

    void appendEvent(WorkstreamPaths paths, String eventId, String eventType, Map<String, Object> payload)
            throws IOException {
        var event = new LinkedHashMap<String, Object>();
        event.put("event_id", eventId);
        event.put("ts", Instant.now().toString());
        event.put("event_type", eventType);
        event.put("payload", payload == null ? Map.of() : payload);
        Files.createDirectories(paths.workstreamDir());
        var line = jsonlMapper.writeValueAsString(event);
        Files.writeString(
                paths.eventsJsonl(),
                line + System.lineSeparator(),
                StandardCharsets.UTF_8,
                StandardOpenOption.CREATE,
                StandardOpenOption.APPEND
        );
    }

    void writeInstanceFromCurrent(WorkstreamPaths paths, WorkflowCurrentDocument current, Instant updatedAt)
            throws IOException {
        var objectMapper = jsonWriter.objectMapper();
        var existing = objectMapper.readValue(paths.workflowInstanceJson().toFile(), WorkflowInstanceDocument.class);
        jsonWriter.write(paths.workflowInstanceJson(), new WorkflowInstanceDocument(
                existing.schemaVersion(),
                existing.workflowInstanceId(),
                existing.workflowId(),
                existing.definitionVersion(),
                current.status(),
                current.activeNodeInstanceIds(),
                current.lastEventId(),
                existing.createdAt(),
                updatedAt
        ));
    }
}

package dev.dual.ledger.file;

import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeInstance;
import dev.dual.core.workflow.NodeResult;

import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

/**
 * Writes the AgentTask dispatch ledger.
 *
 * AgentTask captures "which external agent/tool should execute this node and
 * with which prompt/context contract". It links workflow execution to node
 * execution, but it must not own workflow routing, retry policy, or
 * agent-internal tool calls.
 */
final class AgentTaskLedgerWriter {
    private final AtomicJsonWriter jsonWriter;

    AgentTaskLedgerWriter(AtomicJsonWriter jsonWriter) {
        this.jsonWriter = jsonWriter;
    }

    AgentTaskDocument create(
            WorkstreamPaths paths,
            String workflowExecutionId,
            NodeDefinition definition,
            NodeInstanceDocument node
    ) throws IOException {
        var now = Instant.now();
        var dispatch = new LinkedHashMap<String, Object>();
        dispatch.put("kind", definition.kind().name());
        dispatch.put("handler_type", definition.handlerType());
        dispatch.put("agent", text(definition.config().get("agent")));
        dispatch.put("session", text(definition.config().get("session")));
        dispatch.put("prompt_template", text(definition.config().get("prompt_template")));
        dispatch.put("context_package_ref", latestInputRef(node, "context/").orElse(""));
        dispatch.put("expected_contract", text(definition.config().get("expected_contract")));
        dispatch.put("node_config", definition.config());

        var document = new AgentTaskDocument(
                1,
                nextId("agt"),
                workflowExecutionId,
                node.nodeInstanceId(),
                node.nodeDefinitionId(),
                node.kind(),
                node.handlerType(),
                AgentTaskStatus.QUEUED,
                text(definition.config().get("agent")),
                text(definition.config().get("session")),
                text(definition.config().get("prompt_template")),
                latestInputRef(node, "context/").orElse(""),
                text(definition.config().get("expected_contract")),
                dispatch,
                "",
                "",
                now,
                null,
                null
        );
        jsonWriter.write(paths.agentTaskJson(document.agentTaskId()), document);
        return document;
    }

    AgentTaskDocument markRunning(WorkstreamPaths paths, AgentTaskDocument task, String nodeExecutionId)
            throws IOException {
        var document = new AgentTaskDocument(
                task.schemaVersion(),
                task.agentTaskId(),
                task.workflowExecutionId(),
                task.nodeInstanceId(),
                task.nodeDefinitionId(),
                task.nodeKind(),
                task.handlerType(),
                AgentTaskStatus.RUNNING,
                task.agent(),
                task.session(),
                task.promptTemplate(),
                task.contextPackageRef(),
                task.expectedContract(),
                task.dispatch(),
                nodeExecutionId,
                "",
                task.createdAt(),
                Instant.now(),
                null
        );
        jsonWriter.write(paths.agentTaskJson(document.agentTaskId()), document);
        return document;
    }

    AgentTaskDocument markFinished(WorkstreamPaths paths, AgentTaskDocument task, NodeResult result)
            throws IOException {
        var dispatch = new LinkedHashMap<String, Object>();
        dispatch.putAll(task.dispatch());
        if (result != null) {
            dispatch.put("outcome", result.outcome());
            dispatch.put("node_status", result.status() == null ? "" : result.status().name());
            dispatch.put("output_ref_count", result.outputRefs() == null ? 0 : result.outputRefs().size());
        }
        var failed = result != null && result.status() == dev.dual.core.workflow.NodeStatus.FAILED;
        var document = complete(
                task,
                failed ? AgentTaskStatus.FAILED : AgentTaskStatus.SUCCEEDED,
                failed ? nullToEmpty(result.errorMessage()) : "",
                dispatch
        );
        jsonWriter.write(paths.agentTaskJson(document.agentTaskId()), document);
        return document;
    }

    AgentTaskDocument markFailed(WorkstreamPaths paths, AgentTaskDocument task, Exception failure)
            throws IOException {
        var dispatch = new LinkedHashMap<String, Object>();
        dispatch.putAll(task.dispatch());
        dispatch.put("exception_type", failure == null ? "" : failure.getClass().getName());
        dispatch.put("exception_message", failure == null ? "" : nullToEmpty(failure.getMessage()));
        var document = complete(task, AgentTaskStatus.FAILED, failure == null ? "" : nullToEmpty(failure.getMessage()), dispatch);
        jsonWriter.write(paths.agentTaskJson(document.agentTaskId()), document);
        return document;
    }

    List<AgentTaskDocument> readAgentTasks(WorkstreamPaths paths) throws IOException {
        if (!java.nio.file.Files.isDirectory(paths.agentTasksDir())) {
            return List.of();
        }
        var documents = new ArrayList<AgentTaskDocument>();
        try (var stream = java.nio.file.Files.list(paths.agentTasksDir())) {
            var files = stream
                    .filter(path -> path.getFileName().toString().endsWith(".json"))
                    .sorted()
                    .toList();
            for (var file : files) {
                documents.add(jsonWriter.objectMapper().readValue(file.toFile(), AgentTaskDocument.class));
            }
        }
        return documents;
    }

    Optional<AgentTaskDocument> readAgentTask(WorkstreamPaths paths, String agentTaskId) throws IOException {
        if (agentTaskId == null || agentTaskId.isBlank()) {
            return Optional.empty();
        }
        var path = paths.agentTaskJson(agentTaskId);
        if (!java.nio.file.Files.isRegularFile(path)) {
            return Optional.empty();
        }
        return Optional.of(jsonWriter.objectMapper().readValue(path.toFile(), AgentTaskDocument.class));
    }

    Optional<AgentTaskDocument> firstQueued(WorkstreamPaths paths) throws IOException {
        return readAgentTasks(paths).stream()
                .filter(task -> task.status() == AgentTaskStatus.QUEUED)
                .findFirst();
    }

    private AgentTaskDocument complete(
            AgentTaskDocument task,
            AgentTaskStatus status,
            String errorMessage,
            LinkedHashMap<String, Object> dispatch
    ) {
        return new AgentTaskDocument(
                task.schemaVersion(),
                task.agentTaskId(),
                task.workflowExecutionId(),
                task.nodeInstanceId(),
                task.nodeDefinitionId(),
                task.nodeKind(),
                task.handlerType(),
                status,
                task.agent(),
                task.session(),
                task.promptTemplate(),
                task.contextPackageRef(),
                task.expectedContract(),
                dispatch,
                task.nodeExecutionId(),
                errorMessage,
                task.createdAt(),
                task.claimedAt(),
                Instant.now()
        );
    }

    private static Optional<String> latestInputRef(NodeInstanceDocument node, String marker) {
        if (node.inputRefs() == null || node.inputRefs().isEmpty()) {
            return Optional.empty();
        }
        for (int i = node.inputRefs().size() - 1; i >= 0; i--) {
            var ref = node.inputRefs().get(i);
            if (ref != null && ref.contains(marker)) {
                return Optional.of(ref);
            }
        }
        return Optional.empty();
    }

    private static String nextId(String prefix) {
        return prefix + "-" + Instant.now().toEpochMilli() + "-" + UUID.randomUUID().toString().substring(0, 8);
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    private static String nullToEmpty(String value) {
        return value == null ? "" : value;
    }
}

package dev.dual.ledger.file;

import dev.dual.core.contract.TaskContractValidator;
import java.util.List;

/** Machine-produced approval fact; not a model-supplied permission grant. */
public record EvidenceCollectionBaseline(String gateNodeInstanceId, String contractRef, String contractSha256,
                                         String head, String indexSha256, String sourceSha256,
                                         List<String> paths) {
    public EvidenceCollectionBaseline {
        if (gateNodeInstanceId == null || !gateNodeInstanceId.matches("[A-Za-z0-9._-]+")
                || contractRef == null || !contractRef.matches("\\.agent/workstreams/[A-Za-z0-9_-]+/artifacts/task-contract\\.json")
                || !sha(contractSha256) || !sha(indexSha256) || !sha(sourceSha256)
                || head == null || !head.matches("[0-9a-f]{40}|[0-9a-f]{64}") || paths == null || paths.isEmpty()) {
            throw new IllegalArgumentException("invalid evidence collection baseline");
        }
        paths = List.copyOf(paths);
        if (!paths.equals(paths.stream().distinct().sorted().toList()) || paths.stream().anyMatch(path ->
                !TaskContractValidator.isCanonicalPath(path) || path.equals(".git") || path.startsWith(".git/")
                        || path.equals(".agent") || path.startsWith(".agent/"))) {
            throw new IllegalArgumentException("invalid evidence collection source paths");
        }
    }
    private static boolean sha(String value) { return value != null && value.matches("[0-9a-f]{64}"); }
}

package dev.dual.ledger.file;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.io.IOException;

/**
 * Migrates ledger JSON files from older schema versions to the current version.
 * Each migration step is version N → N+1, applied sequentially.
 */
final class LedgerMigrator {
    private static final int CURRENT_SCHEMA_VERSION = 2;

    static int currentVersion() { return CURRENT_SCHEMA_VERSION; }

    /**
     * Migrate a JSON document to the current schema version.
     * Returns the migrated JSON string.
     *
     * @param json       the raw JSON string to migrate
     * @param fromVersion the schema version of the input JSON
     * @return the migrated JSON string
     * @throws IOException if migration or JSON parsing fails
     */
    static String migrate(String json, int fromVersion) throws IOException {
        if (fromVersion <= 0) {
            throw new IOException("invalid schema version: " + fromVersion);
        }
        if (fromVersion > CURRENT_SCHEMA_VERSION) {
            throw new IOException("schema version " + fromVersion + " is newer than current version " + CURRENT_SCHEMA_VERSION + " — cannot downgrade");
        }
        if (fromVersion == CURRENT_SCHEMA_VERSION) {
            return json;
        }

        var mapper = new ObjectMapper();
        var node = mapper.readTree(json);

        // v1 → v2: add condition field to edges (null = unconditional)
        if (fromVersion < 2) {
            node = v1toV2((ObjectNode) node, mapper);
        }

        // Future migrations go here:
        // if (fromVersion < 3) { node = v2toV3(...); }

        // Update the schema version field
        ((ObjectNode) node).put("schemaVersion", CURRENT_SCHEMA_VERSION);
        return mapper.writeValueAsString(node);
    }

    /** v1 → v2: Edge definitions gained a condition field. */
    private static JsonNode v1toV2(ObjectNode root, ObjectMapper mapper) {
        if (root.has("edges") && root.get("edges").isArray()) {
            var edges = root.withArray("edges");
            for (var edge : edges) {
                if (edge.isObject() && !edge.has("condition")) {
                    ((ObjectNode) edge).putNull("condition");
                }
            }
        }
        return root;
    }
}

package dev.dual.ledger.file;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowStatus;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

final class RevisionTracker {
    private final AtomicJsonWriter jsonWriter;
    private final ObjectMapper objectMapper;
    private final LedgerEventLog eventLog;
    private final FailureSummaryWriter failureSummaryWriter;

    RevisionTracker(AtomicJsonWriter jsonWriter, ObjectMapper objectMapper, LedgerEventLog eventLog) {
        this.jsonWriter = jsonWriter;
        this.objectMapper = objectMapper;
        this.eventLog = eventLog;
        this.failureSummaryWriter = new FailureSummaryWriter(objectMapper);
    }

    WorkflowIterationDocument nextRevisionIteration(
            WorkstreamPaths paths,
            NodeInstanceDocument triggerNode,
            String triggerAction,
            String targetNodeDefinitionId,
            Map<String, Object> result
    ) throws IOException {
        var nextNumber = maxIterationNumber(paths) + 1;
        var iterationId = "iter-" + String.format("%03d", nextNumber);
        return WorkflowIterationDocument.revision(
                iterationId,
                nextNumber,
                triggerNode.iterationId(),
                triggerNode.nodeInstanceId(),
                triggerAction,
                targetNodeDefinitionId,
                LedgerUtils.revisionReason(result),
                Instant.now()
        );
    }

    void blockOnRevisionLimit(
            WorkstreamPaths paths,
            WorkflowCurrentDocument current,
            NodeInstanceDocument node,
            List<String> outputRefs,
            Map<String, Object> result,
            String outcome,
            int maxRevisions,
            int currentRevisionCount
    ) throws IOException {
        var blockedResult = new LinkedHashMap<String, Object>();
        if (result != null) {
            blockedResult.putAll(result);
        }
        blockedResult.put("reason", "revision_limit_reached");
        blockedResult.put("outcome", outcome);
        blockedResult.put("max_revisions", maxRevisions);
        blockedResult.put("current_revision_count", currentRevisionCount);
        var now = Instant.now();
        jsonWriter.write(paths.nodeJson(node.nodeInstanceId()), new NodeInstanceDocument(
                node.schemaVersion(),
                node.nodeInstanceId(),
                node.nodeDefinitionId(),
                node.kind(),
                node.handlerType(),
                NodeStatus.BLOCKED,
                node.stageId(),
                node.iterationId(),
                node.inputRefs(),
                node.inputTransition(),
                outputRefs,
                blockedResult,
                node.runRef(),
                node.latestExecutionId(),
                node.startedAt(),
                now
        ));

        var recoveryGateId = "recovery-" + node.nodeInstanceId();
        jsonWriter.write(paths.gateJson(recoveryGateId), new GateDocument(
                1,
                recoveryGateId,
                node.nodeInstanceId(),
                "recovery.review",
                "open",
                List.of("retry", "abort"),
                now,
                null,
                Map.of(
                        "node", node.nodeDefinitionId(),
                        "node_status", NodeStatus.BLOCKED.name(),
                        "outcome", outcome,
                        "reason", "revision_limit_reached",
                        "max_revisions", maxRevisions,
                        "current_revision_count", currentRevisionCount
                )
        ));
        var eventId = LedgerUtils.nextEventId(current.lastEventId());
        eventLog.appendEvent(paths, eventId, "revision_limit_reached", Map.of(
                "node", node.nodeDefinitionId(),
                "node_instance_id", node.nodeInstanceId(),
                "outcome", outcome,
                "max_revisions", maxRevisions,
                "current_revision_count", currentRevisionCount,
                "recovery_gate_id", recoveryGateId
        ));
        var stopped = new WorkflowCurrentDocument(
                1,
                current.workstreamId(),
                current.workflowInstanceId(),
                current.workflowId(),
                current.definitionVersion(),
                WorkflowStatus.WAITING_FOR_RECOVERY,
                List.of(node.nodeInstanceId()),
                List.of(recoveryGateId),
                eventId,
                now
        );
        jsonWriter.write(paths.workflowCurrentJson(), stopped);
        eventLog.writeInstanceFromCurrent(paths, stopped, now);
        failureSummaryWriter.write(paths, node.nodeInstanceId());
    }

    int maxIterationNumber(WorkstreamPaths paths) throws IOException {
        if (!Files.exists(paths.iterationsDir())) {
            return 1;
        }
        try (var stream = Files.list(paths.iterationsDir())) {
            return stream
                    .filter(Files::isRegularFile)
                    .map(path -> path.getFileName().toString())
                    .filter(name -> name.matches("iter-\\d{3}\\.json"))
                    .mapToInt(name -> Integer.parseInt(name.substring("iter-".length(), "iter-000".length())))
                    .max()
                    .orElse(1);
        }
    }

    int revisionCount(
            WorkstreamPaths paths,
            String triggerNodeDefinitionId,
            String targetNodeDefinitionId
    ) throws IOException {
        if (!Files.exists(paths.iterationsDir())) {
            return 0;
        }
        try (var stream = Files.list(paths.iterationsDir())) {
            var iterations = stream
                    .filter(Files::isRegularFile)
                    .filter(path -> path.getFileName().toString().matches("iter-\\d{3}\\.json"))
                    .map(path -> readIterationOrNull(path))
                    .filter(iteration -> iteration != null)
                    .filter(iteration -> targetNodeDefinitionId.equals(iteration.targetNodeDefinitionId()))
                    .filter(iteration -> !"workflow_started".equals(iteration.triggerAction()))
                    .toList();
            var count = 0;
            for (var iteration : iterations) {
                var triggerNode = objectMapper.readValue(
                        paths.nodeJson(iteration.triggerNodeInstanceId()).toFile(),
                        NodeInstanceDocument.class
                );
                if (triggerNodeDefinitionId.equals(triggerNode.nodeDefinitionId())) {
                    count++;
                }
            }
            return count;
        }
    }

    private WorkflowIterationDocument readIterationOrNull(Path path) {
        try {
            return objectMapper.readValue(path.toFile(), WorkflowIterationDocument.class);
        } catch (IOException e) {
            return null;
        }
    }

    static boolean startsNewIteration(String nodeDefinitionId, String outcome, String targetNodeDefinitionId) {
        return IterationSemantics.startsNewIteration(outcome, targetNodeDefinitionId);
    }

    static boolean isRevisionAction(String outcome) {
        return IterationSemantics.isRevisionTrigger(outcome);
    }

    static int maxRevisions(NodeDefinition definition) {
        var configured = definition.config().get("max_revisions");
        if (configured instanceof Number number) {
            return number.intValue();
        }
        if (configured instanceof String text && !text.isBlank()) {
            try {
                return Integer.parseInt(text);
            } catch (NumberFormatException ignored) {
                return -1;
            }
        }
        return -1;
    }
}

package dev.dual.ledger.file;

import dev.dual.core.workflow.NodeStatus;

import java.time.Instant;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public record NodeExecutionDocument(
        int schemaVersion,
        String nodeExecutionId,
        String agentTaskId,
        String workflowExecutionId,
        String nodeInstanceId,
        String nodeDefinitionId,
        String handlerType,
        NodeExecutionStatus status,
        Long pid,
        String outcome,
        NodeStatus nodeStatus,
        List<String> outputRefs,
        Map<String, Object> result,
        String errorMessage,
        String runRef,
        String agentRunRef,
        String agent,
        String session,
        Integer exitCode,
        Instant startedAt,
        Instant finishedAt,
        Long durationMs
) {
    public NodeExecutionDocument {
        if (schemaVersion <= 0) {
            throw new IllegalArgumentException("schemaVersion must be positive");
        }
        requireText(nodeExecutionId, "nodeExecutionId");
        agentTaskId = agentTaskId == null ? "" : agentTaskId;
        requireText(workflowExecutionId, "workflowExecutionId");
        requireText(nodeInstanceId, "nodeInstanceId");
        requireText(nodeDefinitionId, "nodeDefinitionId");
        requireText(handlerType, "handlerType");
        if (status == null) {
            throw new IllegalArgumentException("status is required");
        }
        outputRefs = List.copyOf(outputRefs == null ? List.of() : outputRefs);
        outputRefs.forEach(value -> requireText(value, "outputRefs"));
        result = copyMapAllowingNullValues(result);
    }

    private static Map<String, Object> copyMapAllowingNullValues(Map<String, Object> source) {
        if (source == null) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, Object>();
        for (Map.Entry<?, ?> entry : source.entrySet()) {
            if (!(entry.getKey() instanceof String key) || key.isBlank()) {
                throw new IllegalArgumentException("result key is required");
            }
            copy.put(key, entry.getValue());
        }
        return Collections.unmodifiableMap(copy);
    }

    private static void requireText(String value, String field) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(field + " is required");
        }
    }
}

package dev.dual.ledger.file;

import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.file.Files;
import java.time.Duration;
import java.time.Instant;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

final class TimelineProjectionWriter {
    private final AtomicJsonWriter jsonWriter;
    private final ObjectMapper objectMapper;

    TimelineProjectionWriter(AtomicJsonWriter jsonWriter, ObjectMapper objectMapper) {
        this.jsonWriter = jsonWriter;
        this.objectMapper = objectMapper;
    }

    void write(WorkstreamPaths paths) throws IOException {
        if (!Files.exists(paths.workflowCurrentJson())) {
            return;
        }
        var current = objectMapper.readValue(paths.workflowCurrentJson().toFile(), WorkflowCurrentDocument.class);
        var nodes = readNodes(paths).stream()
                .sorted(TimelineProjectionWriter::compareNodes)
                .map(this::nodeView)
                .toList();

        var projection = new LinkedHashMap<String, Object>();
        projection.put("schemaVersion", 1);
        projection.put("workstreamId", current.workstreamId());
        projection.put("workflowInstanceId", current.workflowInstanceId());
        projection.put("workflowId", current.workflowId());
        projection.put("definitionVersion", current.definitionVersion());
        projection.put("workflowStatus", current.status());
        projection.put("activeNodeInstanceIds", current.activeNodeInstanceIds());
        projection.put("openGateIds", current.openGateIds());
        projection.put("updatedAt", current.updatedAt());
        projection.put("nodes", nodes);

        jsonWriter.write(paths.timelineJson(), projection);
    }

    private List<NodeInstanceDocument> readNodes(WorkstreamPaths paths) throws IOException {
        if (!Files.exists(paths.nodesDir())) {
            return List.of();
        }
        try (var stream = Files.list(paths.nodesDir())) {
            return stream
                    .filter(path -> path.getFileName().toString().endsWith(".json"))
                    .sorted(Comparator.comparing(path -> path.getFileName().toString()))
                    .map(path -> {
                        try {
                            return objectMapper.readValue(path.toFile(), NodeInstanceDocument.class);
                        } catch (IOException e) {
                            throw new TimelineProjectionException(e);
                        }
                    })
                    .toList();
        } catch (TimelineProjectionException e) {
            throw e.unwrap();
        }
    }

    private Map<String, Object> nodeView(NodeInstanceDocument node) {
        var view = new LinkedHashMap<String, Object>();
        view.put("nodeInstanceId", node.nodeInstanceId());
        view.put("nodeDefinitionId", node.nodeDefinitionId());
        view.put("displayName", TimelineDisplaySemantics.displayName(node));
        view.put("kind", node.kind());
        view.put("handlerType", node.handlerType());
        view.put("status", node.status());
        view.put("stageId", node.stageId());
        view.put("iterationId", node.iterationId());
        view.put("inputRefs", node.inputRefs());
        view.put("outputRefs", node.outputRefs());
        view.put("runRef", node.runRef());
        view.put("latestExecutionId", node.latestExecutionId());
        view.put("startedAt", node.startedAt());
        view.put("finishedAt", node.finishedAt());
        view.put("durationMs", durationMs(node.startedAt(), node.finishedAt()));
        view.put("result", node.result());
        return view;
    }

    private Long durationMs(Instant startedAt, Instant finishedAt) {
        if (startedAt == null || finishedAt == null) {
            return null;
        }
        return Duration.between(startedAt, finishedAt).toMillis();
    }

    private static int compareNodes(NodeInstanceDocument left, NodeInstanceDocument right) {
        var leftInstant = timelineInstant(left);
        var rightInstant = timelineInstant(right);
        var byTime = leftInstant.compareTo(rightInstant);
        if (byTime != 0) {
            return byTime;
        }
        return left.nodeInstanceId().compareTo(right.nodeInstanceId());
    }

    private static Instant timelineInstant(NodeInstanceDocument node) {
        if (node.startedAt() != null) {
            return node.startedAt();
        }
        if (node.finishedAt() != null) {
            return node.finishedAt();
        }
        return Instant.MAX;
    }

    private static final class TimelineProjectionException extends RuntimeException {
        TimelineProjectionException(IOException cause) {
            super(cause);
        }

        IOException unwrap() {
            return (IOException) getCause();
        }
    }
}

package dev.dual.ledger.file;

import java.time.Instant;
import java.util.List;

/** Immutable byte identity presented to the final human acceptance gate. */
public record DeliveryCandidateDocument(
        int schemaVersion,
        String workstreamId,
        String producerNodeInstanceId,
        String iterationId,
        String sourceWorkspaceId,
        String sourceEffectiveWorkdir,
        String baseCommit,
        String baseTree,
        List<String> acceptedFiles,
        List<String> excludedFiles,
        ArtifactReference patch,
        String expectedResultTree,
        ArtifactReference commitMessage,
        ArtifactReference prBody,
        Instant createdAt
) {
    public DeliveryCandidateDocument {
        if (schemaVersion <= 0) throw new IllegalArgumentException("schemaVersion must be positive");
        requireText(workstreamId, "workstreamId");
        requireText(producerNodeInstanceId, "producerNodeInstanceId");
        requireText(iterationId, "iterationId");
        requireText(sourceWorkspaceId, "sourceWorkspaceId");
        requireText(sourceEffectiveWorkdir, "sourceEffectiveWorkdir");
        requireHash(baseCommit, "baseCommit");
        requireHash(baseTree, "baseTree");
        acceptedFiles = sortedCopy(acceptedFiles, "acceptedFiles", false);
        excludedFiles = sortedCopy(excludedFiles, "excludedFiles", true);
        if (patch == null) throw new IllegalArgumentException("patch is required");
        requireHash(expectedResultTree, "expectedResultTree");
        if (commitMessage == null) throw new IllegalArgumentException("commitMessage is required");
        if (prBody == null) throw new IllegalArgumentException("prBody is required");
        if (createdAt == null) throw new IllegalArgumentException("createdAt is required");
    }

    private static List<String> sortedCopy(List<String> values, String field, boolean allowEmpty) {
        var copy = List.copyOf(values == null ? List.of() : values);
        if (!allowEmpty && copy.isEmpty()) throw new IllegalArgumentException(field + " is required");
        copy.forEach(value -> requireText(value, field));
        var sorted = copy.stream().sorted().toList();
        if (!copy.equals(sorted) || copy.stream().distinct().count() != copy.size()) {
            throw new IllegalArgumentException(field + " must be sorted and unique");
        }
        return copy;
    }

    private static void requireHash(String value, String field) {
        requireText(value, field);
        if (!value.matches("[0-9a-f]{40}|[0-9a-f]{64}")) {
            throw new IllegalArgumentException(field + " must be a lowercase Git or SHA-256 identity");
        }
    }

    private static void requireText(String value, String field) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(field + " is required");
    }

    public record ArtifactReference(String ref, String sha256) {
        public ArtifactReference {
            requireText(ref, "artifact ref");
            requireText(sha256, "artifact sha256");
            if (!sha256.matches("[0-9a-f]{64}")) {
                throw new IllegalArgumentException("artifact sha256 must be 64 lowercase hexadecimal characters");
            }
        }
    }
}

package dev.dual.ledger.file;

import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.List;
import java.util.Map;

final class FailureSummaryWriter {
    private final ObjectMapper objectMapper;

    FailureSummaryWriter(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
    }

    void write(WorkstreamPaths paths, String nodeInstanceId) throws IOException {
        var node = objectMapper.readValue(paths.nodeJson(nodeInstanceId).toFile(), NodeInstanceDocument.class);
        var current = objectMapper.readValue(paths.workflowCurrentJson().toFile(), WorkflowCurrentDocument.class);
        Files.createDirectories(paths.recoveryDir());
        Files.writeString(paths.currentFailureMarkdown(), render(paths, current, node), StandardCharsets.UTF_8);
    }

    private String render(WorkstreamPaths paths, WorkflowCurrentDocument current, NodeInstanceDocument node) {
        var result = node.result() == null ? Map.<String, Object>of() : node.result();
        var outputRefs = node.outputRefs() == null ? List.<String>of() : node.outputRefs();
        var reason = text(firstNonBlank(
                result.get("acpx_failure.reason"),
                result.get("reason"),
                result.get("error"),
                result.get("message"),
                ""
        ));
        var recoverable = text(firstNonBlank(result.get("acpx_failure.recoverable"), result.get("recoverable"), ""));
        var exitCode = text(firstNonBlank(result.get("exit_code"), ""));
        var runId = text(firstNonBlank(result.get("run_id"), ""));
        var agent = text(firstNonBlank(result.get("agent"), ""));
        var session = text(firstNonBlank(result.get("session"), ""));
        var attention = WorkstreamAttentionEvaluator.evaluate(paths);

        var content = new StringBuilder();
        content.append("# Current Failure\n\n");
        content.append("## Summary\n\n");
        line(content, "Workflow Status", current.status().name());
        line(content, "Node", node.nodeDefinitionId());
        line(content, "Node Instance", node.nodeInstanceId());
        line(content, "Node Status", node.status().name());
        line(content, "Handler", node.handlerType());
        line(content, "Reason", reason);
        line(content, "Recoverable", recoverable);
        line(content, "Exit Code", exitCode);
        line(content, "Run ID", runId);
        line(content, "Agent", agent);
        line(content, "Session", session);
        line(content, "Attention Category", attention.category().name());
        line(content, "Retry Safe", String.valueOf(attention.retrySafe()));
        appendContractFailureDiagnostic(content, result);
        content.append("\n## Evidence\n\n");
        if (outputRefs.isEmpty()) {
            content.append("- Output refs: N/A\n");
        } else {
            for (var ref : outputRefs) {
                content.append("- ").append(ref).append('\n');
            }
        }
        content.append("\n## Suggested Action\n\n");
        content.append("- ").append(blankDefault(attention.detail(), "Inspect the evidence files listed above.")).append('\n');
        content.append("- ").append(blankDefault(attention.nextAction(), "Inspect the workstream ledger before choosing the next action.")).append('\n');
        if (!attention.command().isBlank()) {
            content.append("- Command: `").append(attention.command()).append("`.\n");
        }
        return content.toString();
    }

    @SuppressWarnings("unchecked")
    private static void appendContractFailureDiagnostic(StringBuilder content, Map<String, Object> result) {
        var diagnosticJson = text(result.get("contract_failure_diagnostic_ref"));
        var diagnosticMarkdown = text(result.get("contract_failure_diagnostic_markdown_ref"));
        if (diagnosticJson.isBlank() && diagnosticMarkdown.isBlank() && !result.containsKey("parse_error")) {
            return;
        }
        content.append("\n## Contract Failure Diagnostic\n\n");
        line(content, "Diagnostic JSON", diagnosticJson);
        line(content, "Diagnostic Markdown", diagnosticMarkdown);
        if (result.get("parse_error") instanceof Map<?, ?> parseError) {
            line(content, "Error Code", text(parseError.get("code")));
            line(content, "Error Message", text(parseError.get("message")));
            var details = parseError.get("details");
            if (details instanceof Map<?, ?> detailsMap && !detailsMap.isEmpty()) {
                content.append("- Details:\n");
                for (var entry : detailsMap.entrySet()) {
                    content.append("  - ").append(text(entry.getKey())).append(": ")
                            .append(text(entry.getValue())).append('\n');
                }
            }
        }
    }

    private static void line(StringBuilder content, String label, String value) {
        content.append("- ").append(label).append(": ");
        content.append(value == null || value.isBlank() ? "N/A" : value);
        content.append('\n');
    }

    private static Object firstNonBlank(Object... values) {
        for (var value : values) {
            if (value != null && !value.toString().isBlank()) {
                return value;
            }
        }
        return "";
    }

    private static String text(Object value) {
        return value == null ? "" : value.toString();
    }

    private static String blankDefault(String value, String fallback) {
        return value == null || value.isBlank() ? fallback : value;
    }
}

package dev.dual.ledger.file;

final class IterationRef {
    private final int number;

    private IterationRef(int number) {
        if (number < 1) {
            throw new IllegalArgumentException("iteration number must be positive");
        }
        this.number = number;
    }

    static IterationRef first() {
        return new IterationRef(1);
    }

    static IterationRef ofNumber(int number) {
        return new IterationRef(number);
    }

    static IterationRef parse(String iterationId) {
        if (iterationId == null || !iterationId.matches("iter-\\d{3}")) {
            throw new IllegalArgumentException("invalid iteration id: " + iterationId);
        }
        return new IterationRef(Integer.parseInt(iterationId.substring("iter-".length())));
    }

    int number() {
        return number;
    }

    String id() {
        return "iter-" + dirName();
    }

    String dirName() {
        return "%03d".formatted(number);
    }

    String artifactSuffix() {
        return dirName();
    }

    IterationRef next() {
        return new IterationRef(number + 1);
    }
}

package dev.dual.ledger.file;

import dev.dual.core.domain.TimelineEvent;

import java.time.Instant;
