package dev.dual.ledger.file;

import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HexFormat;
import java.util.List;
import java.util.Locale;

/**
 * Local operator index for projects and workstream entry points.
 *
 * This registry is intentionally not a workflow source of truth. It only helps
 * CLI, autorun, and the local UI find known repository roots and effective
 * workdirs. Workflow status, gates, recovery, and artifacts remain owned by the
 * per-workstream ledger.
 */
public final class OperatorWorkspaceRegistry {
    public static final String REGISTRY_PATH_PROPERTY = "dual.operator.registry.path";
    public static final String REGISTRY_PATH_ENV = "DUAL_OPERATOR_REGISTRY";

    private final AtomicJsonWriter jsonWriter;
    private final ObjectMapper objectMapper;
    private final Path registryPath;

    public OperatorWorkspaceRegistry() {
        this(defaultRegistryPath());
    }

    public OperatorWorkspaceRegistry(Path registryPath) {
        this.jsonWriter = new AtomicJsonWriter();
        this.objectMapper = jsonWriter.objectMapper();
        this.registryPath = registryPath.toAbsolutePath().normalize();
    }

    public synchronized OperatorWorkspaceRegistryDocument read() throws IOException {
        if (!Files.isRegularFile(registryPath)) {
            return OperatorWorkspaceRegistryDocument.empty();
        }
        return objectMapper.readValue(registryPath.toFile(), OperatorWorkspaceRegistryDocument.class)
                .normalized();
    }

    public synchronized OperatorWorkspaceRegistryDocument registerProject(Path repoRoot) throws IOException {
        var normalizedRepoRoot = normalizeRepositoryRoot(repoRoot);
        var document = read();
        var project = projectEntry(normalizedRepoRoot, List.of(), Instant.now());
        var projects = upsertProject(document.projects(), project);
        var next = new OperatorWorkspaceRegistryDocument(
                1,
                project.projectId(),
                sortedProjects(projects)
        );
        write(next);
        return next;
    }

    public synchronized OperatorWorkspaceRegistryDocument registerWorkstream(
            Path originalRepoRoot,
            Path effectiveWorkdir,
            String workstreamId,
            String title,
            String status,
            Instant updatedAt
    ) throws IOException {
        var normalizedRepoRoot = normalizeRepositoryRoot(originalRepoRoot);
        var normalizedEffectiveWorkdir = effectiveWorkdir.toAbsolutePath().normalize();
        var document = read();
        var now = updatedAt == null ? Instant.now() : updatedAt;
        var projectId = projectId(normalizedRepoRoot);
        var existingProject = document.projects().stream()
                .filter(project -> project.projectId().equals(projectId))
                .findFirst();
        var existingWorkstreams = existingProject
                .map(OperatorWorkspaceProject::workstreams)
                .orElse(List.of());
        var workstream = new OperatorWorkspaceWorkstream(
                workstreamId,
                normalizedEffectiveWorkdir.toString(),
                nullToBlank(title),
                nullToBlank(status),
                now
        );
        var project = projectEntry(normalizedRepoRoot, upsertWorkstream(existingWorkstreams, workstream), now);
        var next = new OperatorWorkspaceRegistryDocument(
                1,
                project.projectId(),
                sortedProjects(upsertProject(document.projects(), project))
        );
        write(next);
        return next;
    }

    public synchronized OperatorWorkspaceRegistryDocument registerFromLedger(Path effectiveWorkdir, String workstreamId) throws IOException {
        var root = effectiveWorkdir.toAbsolutePath().normalize();
        var status = new FileLedgerStore().loadStatus(root, workstreamId);
        return registerWorkstream(
                Path.of(status.workspace().originalWorkdir()),
                root,
                workstreamId,
                status.workstream().title(),
                status.workstream().status(),
                status.workstream().updatedAt()
        );
    }

    public Path registryPath() {
        return registryPath;
    }

    public static Path defaultAgentRunsDir(Path repoRoot) {
        var root = repoRoot.toAbsolutePath().normalize();
        var parent = root.getParent();
        var name = root.getFileName() == null ? "repo" : root.getFileName().toString();
        return (parent == null ? Path.of(".") : parent).resolve(name + "-agent-runs").toAbsolutePath().normalize();
    }

    private void write(OperatorWorkspaceRegistryDocument document) throws IOException {
        jsonWriter.write(registryPath, document.normalized());
    }

    private static OperatorWorkspaceProject projectEntry(Path repoRoot, List<OperatorWorkspaceWorkstream> workstreams, Instant lastOpenedAt) {
        var name = repoRoot.getFileName() == null ? repoRoot.toString() : repoRoot.getFileName().toString();
        return new OperatorWorkspaceProject(
                projectId(repoRoot),
                name,
                repoRoot.toString(),
                defaultAgentRunsDir(repoRoot).toString(),
                lastOpenedAt,
                sortedWorkstreams(workstreams)
        );
    }

    private static List<OperatorWorkspaceProject> upsertProject(
            List<OperatorWorkspaceProject> projects,
            OperatorWorkspaceProject next
    ) {
        var result = new ArrayList<OperatorWorkspaceProject>();
        var replaced = false;
        for (var project : projects) {
            if (project.projectId().equals(next.projectId())) {
                var mergedWorkstreams = next.workstreams().isEmpty()
                        ? project.workstreams()
                        : next.workstreams();
                result.add(new OperatorWorkspaceProject(
                        next.projectId(),
                        next.name(),
                        next.repoRoot(),
                        next.agentRunsDir(),
                        next.lastOpenedAt(),
                        mergedWorkstreams
                ));
                replaced = true;
            } else {
                result.add(project);
            }
        }
        if (!replaced) {
            result.add(next);
        }
        return result;
    }

    private static List<OperatorWorkspaceWorkstream> upsertWorkstream(
            List<OperatorWorkspaceWorkstream> workstreams,
            OperatorWorkspaceWorkstream next
    ) {
        var result = new ArrayList<OperatorWorkspaceWorkstream>();
        var replaced = false;
        for (var workstream : workstreams) {
            if (workstream.workstreamId().equals(next.workstreamId())) {
                result.add(next);
                replaced = true;
            } else {
                result.add(workstream);
            }
        }
        if (!replaced) {
            result.add(next);
        }
        return sortedWorkstreams(result);
    }

    private static List<OperatorWorkspaceProject> sortedProjects(List<OperatorWorkspaceProject> projects) {
        return projects.stream()
                .map(OperatorWorkspaceProject::normalized)
                .sorted(Comparator
                        .comparing(OperatorWorkspaceProject::lastOpenedAt, Comparator.nullsLast(Comparator.reverseOrder()))
                        .thenComparing(OperatorWorkspaceProject::name))
                .toList();
    }

    private static List<OperatorWorkspaceWorkstream> sortedWorkstreams(List<OperatorWorkspaceWorkstream> workstreams) {
        return workstreams.stream()
                .map(OperatorWorkspaceWorkstream::normalized)
                .sorted(Comparator
                        .comparing(OperatorWorkspaceWorkstream::updatedAt, Comparator.nullsLast(Comparator.reverseOrder()))
                        .thenComparing(OperatorWorkspaceWorkstream::workstreamId))
                .toList();
    }

    private static Path normalizeRepositoryRoot(Path repoRoot) {
        var root = repoRoot.toAbsolutePath().normalize();
        if (!Files.isDirectory(root)) {
            throw new IllegalArgumentException("repository root is not a directory: " + root);
        }
        if (!Files.exists(root.resolve(".git"))) {
            throw new IllegalArgumentException("repository root does not look like a git repository: " + root);
        }
        return root;
    }

    private static String projectId(Path repoRoot) {
        var name = repoRoot.getFileName() == null ? "repo" : slug(repoRoot.getFileName().toString());
        return name + "-" + shortHash(repoRoot.toString());
    }

    private static String slug(String value) {
        var slug = value.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9._-]+", "-");
        return slug.isBlank() ? "repo" : slug;
    }

    private static String shortHash(String value) {
        try {
            var digest = MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(digest).substring(0, 8);
        } catch (Exception e) {
            throw new IllegalStateException("SHA-256 digest is unavailable", e);
        }
    }

    private static Path defaultRegistryPath() {
        var property = System.getProperty(REGISTRY_PATH_PROPERTY);
        if (property != null && !property.isBlank()) {
            return Path.of(property);
        }
        var env = System.getenv(REGISTRY_PATH_ENV);
        if (env != null && !env.isBlank()) {
            return Path.of(env);
        }
        return Path.of(System.getProperty("user.home"), ".dual", "operator-workspaces.json");
    }

    private static String nullToBlank(String value) {
        return value == null ? "" : value;
    }
}

package dev.dual.ledger.file;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.contract.TaskContractValidator;
import dev.dual.core.workflow.NodeStatus;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashSet;
import java.util.HexFormat;

/** Pre-mutation integrity check for a human request, not a scope approval. */
final class ScopeRevisionRequestGuard {
    private ScopeRevisionRequestGuard() {}

    static void verify(WorkstreamPaths paths, NodeInstanceDocument gateNode, GateDocument gate,
                       ObjectMapper mapper) throws IOException {
        var root = paths.workstreamDir().toAbsolutePath().normalize().getParent().getParent().getParent();
        var sourceId = String.valueOf(gate.result().get("source_node_instance_id"));
        require(sourceId.matches("[A-Za-z0-9._-]+"), "scope source identity is missing");
        var source = mapper.readValue(paths.nodeJson(sourceId).toFile(), NodeInstanceDocument.class);
        require(sourceId.equals(source.nodeInstanceId()) && source.status() == NodeStatus.COMPLETED
                && source.nodeDefinitionId().equals("implement.artifact_validation")
                && source.handlerType().equals("artifact.validate")
                && source.iterationId().equals(gateNode.iterationId())
                && "FAIL".equals(source.result().get("change_scope_status"))
                && "CHANGE_SCOPE_VIOLATION".equals(source.result().get("change_scope_disposition")),
                "scope source is not a completed violation");
        var binding = mapper.valueToTree(source.result().get("scope_rework_baseline"));
        require(binding != null && binding.isObject(), "scope rework baseline is missing");
        var ref = binding.path("evaluation_ref").asText();
        var sha = binding.path("evaluation_sha256").asText();
        require(ref.equals(source.result().get("change_scope_evaluation_ref"))
                && sha.equals(source.result().get("change_scope_evaluation_sha256"))
                && gateNode.inputRefs().contains(ref) && source.outputRefs().contains(ref)
                && mapper.valueToTree(gateNode.inputRefs()).equals(mapper.valueToTree(gate.result().get("subject_input_refs"))),
                "scope evaluation is not the gate subject");
        var doc = mapper.readTree(verifiedPath(root, paths, ref, sha).toFile());
        require(doc.path("sourceNodeInstanceId").asText().equals(sourceId)
                && doc.path("schemaVersion").asInt() == 1, "scope evaluation identity is invalid");
        var evaluation = doc.path("evaluation");
        require("FAIL".equals(evaluation.path("status").asText()) && evaluation.path("violations").isArray()
                && !evaluation.path("violations").isEmpty(), "scope evaluation has no violations");
        var seen = new HashSet<String>();
        for (var violation : evaluation.path("violations")) {
            var path = violation.path("path").asText();
            require("UNEXPECTED_ACTUAL_CHANGE".equals(violation.path("code").asText())
                    && "CREATE".equals(violation.path("actualOperation").asText())
                    && violation.path("declaredOperation").isNull() && violation.path("previousPath").isNull()
                    && TaskContractValidator.isCanonicalPath(path) && seen.add(path),
                    "scope revision only supports ordinary new file violations");
        }
        for (var field : new String[]{"proposal_review", "contract_gate", "requirement_gate"}) {
            verifiedPath(root, paths, binding.path(field + "_ref").asText(), binding.path(field + "_sha256").asText());
        }
        var proposal = binding.path("proposal_reference");
        verifiedPath(root, paths, proposal.path("artifact_ref").asText(), proposal.path("sha256").asText());
        var artifactPrefix = root.relativize(paths.workstreamDir().toAbsolutePath().normalize()).toString() + "/artifacts/";
        verifiedPath(root, paths, artifactPrefix + "task-contract.json", binding.path("task_contract_sha256").asText());
        verifiedPath(root, paths, artifactPrefix + "contract-resolution.json", binding.path("contract_resolution_sha256").asText());
        var compileId = binding.path("compile_node_instance_id").asText();
        require(compileId.matches("[A-Za-z0-9._-]+"), "scope compile identity is invalid");
        var compile = mapper.readValue(paths.nodeJson(compileId).toFile(), NodeInstanceDocument.class);
        require(compile.status() == NodeStatus.COMPLETED && compile.nodeDefinitionId().equals("contract.compile")
                && binding.path("task_contract_sha256").asText().equals(compile.result().get("task_contract_sha256"))
                && binding.path("contract_resolution_sha256").asText().equals(compile.result().get("contract_resolution_sha256")),
                "scope compile baseline changed");
        var workspaceId = binding.path("workspace_id").asText();
        require(workspaceId.matches("[A-Za-z0-9._-]+"), "scope workspace is missing");
        var workspace = mapper.readTree(paths.workstreamDir().resolve("workspaces/" + workspaceId + ".json").toFile());
        require(binding.path("base_commit").asText().matches("[0-9a-f]{40}|[0-9a-f]{64}")
                && binding.path("base_commit").equals(workspace.path("baseCommit")), "scope original base changed");
    }

    private static Path verifiedPath(Path root, WorkstreamPaths paths, String ref, String sha) throws IOException {
        var target = root.resolve(ref).normalize();
        require(!ref.isBlank() && !Path.of(ref).isAbsolute() && root.relativize(target).toString().equals(ref)
                && target.startsWith(paths.workstreamDir().toAbsolutePath().normalize())
                && Files.isRegularFile(target) && target.toRealPath().equals(root.toRealPath().resolve(ref))
                && sha.matches("[0-9a-f]{64}"), "scope baseline reference is missing or noncanonical");
        try {
            require(sha.equals(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(target)))),
                    "scope baseline hash mismatch");
        } catch (NoSuchAlgorithmException impossible) { throw new IOException(impossible); }
        return target;
    }

    private static void require(boolean condition, String reason) throws IOException {
        if (!condition) throw new IOException(reason);
    }
}

package dev.dual.ledger.file;

import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeKind;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowDefinition;
import dev.dual.core.workflow.WorkflowStatus;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/** Operator authority for one execution; callers hold the workstream lock. */
public final class ExecutionNetworkGrantStore {
    public static final String REF_KEY = "execution_network_grant_ref";
    private static final String SHA_KEY = "execution_network_grant_sha256";
    private final AtomicJsonWriter writer = new AtomicJsonWriter();
    private final WorkflowFileLedger ledger = new WorkflowFileLedger();

    public record Grant(int schemaVersion, String workstreamId, String sourceNodeInstanceId,
                        String targetNodeDefinitionId, String definitionSha256, List<String> domains,
                        String note, String approvedAt, String state, String claimedNodeInstanceId,
                        String claimedRunId) {
        public Grant {
            domains = List.copyOf(domains == null ? List.of() : domains);
        }
    }

    public record Claim(String ref, String sha256, List<String> domains) {
        public Claim { domains = List.copyOf(domains); }
        public Map<String, Object> metadata() {
            return Map.of("grantRef", ref, "grantSha256", sha256, "allowedDomains", domains);
        }
    }

    public String approve(WorkstreamPaths paths, String target, List<String> domains, String note) throws IOException {
        var source = waitingSource(paths);
        var definition = ledger.loadDefinition(paths);
        var canonical = canonicalDomains(domains);
        if (note == null || note.isBlank()) throw new IOException("network approval note is required");
        if (!eligible(definition.node(target))) throw new IOException("target must use Claude implement profile");
        if (source.kind() == NodeKind.GATE) {
            if (!targets(definition, source).contains(target)) throw new IOException("target is not reachable before another gate");
        } else if (!source.nodeDefinitionId().equals(target)) {
            throw new IOException("a failed execution can authorize only its own retry");
        }
        if (source.inputTransition().containsKey(REF_KEY)) {
            var previous = read(paths, source.inputTransition().get(REF_KEY).toString());
            if (previous.state().equals("PENDING")) throw new IOException("cancel the pending network grant before replacing it");
        }
        var path = directory(paths).resolve("grant-" + UUID.randomUUID() + ".json");
        var ref = paths.workspaceRoot().relativize(path).toString();
        var grant = new Grant(1, paths.workstreamId().value(), source.nodeInstanceId(), target,
                sha(Files.readAllBytes(paths.workflowDefinitionJson())), canonical, note.trim(),
                Instant.now().toString(), "PENDING", "", "");
        writer.write(path, grant);
        var transition = new LinkedHashMap<>(source.inputTransition());
        transition.put(REF_KEY, ref);
        transition.put(SHA_KEY, sha(writer.objectMapper().writeValueAsBytes(grant)));
        writer.write(paths.nodeJson(source.nodeInstanceId()), new NodeInstanceDocument(
                source.schemaVersion(), source.nodeInstanceId(), source.nodeDefinitionId(), source.kind(),
                source.handlerType(), source.status(), source.stageId(), source.iterationId(), source.inputRefs(),
                transition, source.outputRefs(), source.result(), source.runRef(), source.latestExecutionId(),
                source.startedAt(), source.finishedAt()));
        return ref;
    }

    public void cancel(WorkstreamPaths paths) throws IOException {
        var source = waitingSource(paths);
        var value = source.inputTransition().get(REF_KEY);
        if (!(value instanceof String ref)) throw new IOException("no network grant on the current waiting node");
        var grant = read(paths, ref);
        if (!grant.state().equals("PENDING")) throw new IOException("only an unclaimed network grant can be cancelled");
        writer.write(resolve(paths, ref), withState(grant, "CANCELLED", "", ""));
    }

    public Map<String, Object> view(WorkstreamPaths paths) throws IOException {
        try { return validView(paths); }
        catch (IOException invalid) {
            return Map.of("canApprove", false, "canCancel", false, "status", "INVALID", "reason", invalid.getMessage());
        }
    }

    private Map<String, Object> validView(WorkstreamPaths paths) throws IOException {
        var current = ledger.loadCurrent(paths);
        if (current.activeNodeInstanceIds().size() != 1) return Map.of("canApprove", false, "canCancel", false);
        var node = ledger.loadNode(paths, current.activeNodeInstanceIds().getFirst());
        var result = new LinkedHashMap<String, Object>();
        var waiting = isWaiting(current, node);
        if (waiting) waitingSource(paths);
        var candidates = waiting ? targets(ledger.loadDefinition(paths), node) : List.<String>of();
        result.put("canApprove", !candidates.isEmpty());
        result.put("targets", candidates);
        result.put("canCancel", false);
        result.put("scope", "one_execution");
        var value = node.inputTransition().get(REF_KEY);
        if (value instanceof String ref) {
            var grant = read(paths, ref);
            result.put("grant", grant);
            result.put("grantRef", ref);
            var pending = grant.state().equals("PENDING");
            result.put("canApprove", !candidates.isEmpty() && !pending);
            result.put("canCancel", waiting && pending);
        }
        return Map.copyOf(result);
    }

    /** The atomic claim deliberately burns the grant even if subsequent startup fails. */
    public Claim claimIfPresent(WorkstreamPaths paths, String nodeId, String runId) throws IOException {
        if (!Files.isRegularFile(paths.nodeJson(nodeId))) return null;
        if (!ledger.loadNode(paths, nodeId).inputTransition().containsKey(REF_KEY)) return null;
        return claim(paths, nodeId, runId);
    }

    public Claim claim(WorkstreamPaths paths, String nodeId, String runId) throws IOException {
        var current = ledger.loadCurrent(paths);
        if (current.status() != WorkflowStatus.RUNNING || !current.activeNodeInstanceIds().contains(nodeId)) {
            throw new IOException("network grant requires the current running execution");
        }
        var node = ledger.loadNode(paths, nodeId);
        var value = node.inputTransition().get(REF_KEY);
        if (value == null) return null;
        if (!(value instanceof String ref)) throw new IOException("invalid network grant reference");
        var grant = read(paths, ref);
        if (!grant.targetNodeDefinitionId().equals(node.nodeDefinitionId())) return null;
        if (!eligible(ledger.loadDefinition(paths).node(node.nodeDefinitionId()))) throw new IOException("network grant target capability mismatch");
        if (node.status() != NodeStatus.RUNNING) throw new IOException("network grant target is not running");
        if (!grant.state().equals("PENDING")) return null;
        if (runId == null || !runId.matches("[A-Za-z0-9._-]+")) throw new IOException("invalid network grant run id");
        var source = ledger.loadNode(paths, grant.sourceNodeInstanceId());
        if (!ref.equals(source.inputTransition().get(REF_KEY))) throw new IOException("network grant was superseded");
        if (source.kind() == NodeKind.GATE) {
            if (source.status() != NodeStatus.COMPLETED
                    || !List.of("approve", "approved", "revise").contains(source.result().get("human_action"))) {
                throw new IOException("network grant does not replace the business gate decision");
            }
        } else if (!source.nodeInstanceId().equals(nodeId)) {
            throw new IOException("network retry grant cannot cross node instances");
        }
        var path = resolve(paths, ref);
        writer.write(path, withState(grant, "CLAIMED", nodeId, runId));
        return new Claim(ref, sha(Files.readAllBytes(path)), grant.domains());
    }

    public static Map<String, Object> forward(WorkstreamPaths paths, NodeInstanceDocument source,
                                               NodeDefinition next, Map<String, Object> attributes) throws IOException {
        var result = new LinkedHashMap<>(attributes);
        result.remove(REF_KEY);
        var value = source.inputTransition().get(REF_KEY);
        if (value instanceof String ref && next.kind() != NodeKind.GATE) {
            var grant = new ExecutionNetworkGrantStore().read(paths, ref);
            if (grant.state().equals("PENDING") && !source.nodeDefinitionId().equals(grant.targetNodeDefinitionId())) {
                result.put(REF_KEY, ref);
            }
        }
        return Map.copyOf(result);
    }

    public void verifyClaim(WorkstreamPaths paths, Claim claim, String nodeId, String runId) throws IOException {
        // Historical execution evidence is bound by its recorded SHA, not today's source pointer.
        var grant = readDocument(paths, claim.ref());
        if (!grant.state().equals("CLAIMED") || !nodeId.equals(grant.claimedNodeInstanceId())
                || !runId.equals(grant.claimedRunId()) || !claim.domains().equals(grant.domains())
                || !claim.sha256().equals(sha(Files.readAllBytes(resolve(paths, claim.ref()))))) {
            throw new IOException("network grant claim mismatch");
        }
    }

    private NodeInstanceDocument waitingSource(WorkstreamPaths paths) throws IOException {
        var current = ledger.loadCurrent(paths);
        if (current.activeNodeInstanceIds().size() != 1) throw new IOException("network approval requires one active waiting node");
        var node = ledger.loadNode(paths, current.activeNodeInstanceIds().getFirst());
        if (!isWaiting(current, node)) throw new IOException("network approval requires a human gate or failed execution");
        if (node.kind() == NodeKind.GATE) {
            var open = false;
            for (var gateId : current.openGateIds()) {
                var gate = writer.objectMapper().readValue(paths.gateJson(gateId).toFile(), GateDocument.class);
                open |= gate.nodeInstanceId().equals(node.nodeInstanceId()) && gate.status().equals("open");
            }
            if (!open) throw new IOException("network approval requires a matching open gate");
        }
        return node;
    }

    private static boolean isWaiting(WorkflowCurrentDocument current, NodeInstanceDocument node) {
        return current.status() == WorkflowStatus.WAITING_FOR_HUMAN && node.kind() == NodeKind.GATE && node.status() == NodeStatus.WAITING
                || current.status() == WorkflowStatus.WAITING_FOR_RECOVERY && node.kind() == NodeKind.TASK
                && (node.status() == NodeStatus.FAILED || node.status() == NodeStatus.BLOCKED);
    }

    private static boolean eligible(NodeDefinition node) {
        return node.handlerType().equals("acpx.agent_run") && "claude".equals(node.config().get("agent"))
                && "implement".equals(node.config().get("permission_profile"));
    }

    private static List<String> targets(WorkflowDefinition definition, NodeInstanceDocument source) {
        if (source.kind() != NodeKind.GATE) return eligible(definition.node(source.nodeDefinitionId())) ? List.of(source.nodeDefinitionId()) : List.of();
        var queue = new ArrayDeque<String>();
        definition.edgesFrom(source.nodeDefinitionId()).stream()
                .filter(e -> List.of("approve", "approved", "revise").contains(e.on())).forEach(e -> queue.add(e.to()));
        var seen = new HashSet<String>();
        var targets = new java.util.TreeSet<String>();
        while (!queue.isEmpty()) {
            var id = queue.removeFirst();
            if (!seen.add(id)) continue;
            var node = definition.node(id);
            if (node.kind() == NodeKind.GATE) continue;
            if (eligible(node)) targets.add(id);
            definition.edgesFrom(id).forEach(e -> queue.add(e.to()));
        }
        return List.copyOf(targets);
    }

    private Grant read(WorkstreamPaths paths, String ref) throws IOException {
        var grant = readDocument(paths, ref);
        var source = ledger.loadNode(paths, grant.sourceNodeInstanceId());
        var originalSha = sha(writer.objectMapper().writeValueAsBytes(withState(grant, "PENDING", "", "")));
        if (!ref.equals(source.inputTransition().get(REF_KEY)) || !originalSha.equals(source.inputTransition().get(SHA_KEY))) {
            throw new IOException("network grant approval binding mismatch");
        }
        return grant;
    }

    private Grant readDocument(WorkstreamPaths paths, String ref) throws IOException {
        var grant = writer.objectMapper().readValue(resolve(paths, ref).toFile(), Grant.class);
        if (grant == null || grant.schemaVersion() != 1 || !paths.workstreamId().value().equals(grant.workstreamId())
                || !sha(Files.readAllBytes(paths.workflowDefinitionJson())).equals(grant.definitionSha256())
                || grant.state() == null || !List.of("PENDING", "CLAIMED", "CANCELLED").contains(grant.state())
                || grant.targetNodeDefinitionId() == null || !grant.targetNodeDefinitionId().matches("[A-Za-z0-9._-]+")
                || grant.sourceNodeInstanceId() == null || !grant.sourceNodeInstanceId().matches("[A-Za-z0-9._-]+")
                || grant.note() == null || grant.note().isBlank() || grant.approvedAt() == null || grant.approvedAt().isBlank()
                || !canonicalDomains(grant.domains()).equals(grant.domains())) throw new IOException("invalid execution network grant");
        return grant;
    }

    public static List<String> canonicalDomains(List<String> domains) throws IOException {
        if (domains == null || domains.isEmpty() || domains.size() > 32) throw new IOException("provide 1-32 exact public DNS names");
        var result = new java.util.TreeSet<String>();
        for (var domain : domains) {
            if (domain == null || domain.length() > 253 || !domain.equals(domain.toLowerCase(java.util.Locale.ROOT))
                    || !domain.matches("[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+")
                    || domain.matches("[0-9.]+") || domain.endsWith(".localhost") || domain.endsWith(".local")
                    || java.util.Arrays.stream(domain.split("\\.")).anyMatch(label -> label.length() > 63)) {
                throw new IOException("network domain must be an exact canonical DNS name without URL, wildcard, IP or local suffix");
            }
            result.add(domain);
        }
        return List.copyOf(result);
    }

    private static Grant withState(Grant g, String state, String node, String run) {
        return new Grant(g.schemaVersion(), g.workstreamId(), g.sourceNodeInstanceId(), g.targetNodeDefinitionId(),
                g.definitionSha256(), g.domains(), g.note(), g.approvedAt(), state, node, run);
    }

    private static Path directory(WorkstreamPaths paths) { return paths.workstreamDir().resolve("execution-authority/network-grants"); }
    private static Path resolve(WorkstreamPaths paths, String ref) throws IOException {
        var path = paths.workspaceRoot().resolve(ref).normalize();
        if (!path.getParent().equals(directory(paths).normalize())
                || !path.getFileName().toString().matches("grant-[0-9a-f-]{36}\\.json")
                || !path.toRealPath().equals(path.toAbsolutePath())) throw new IOException("invalid network grant path");
        return path;
    }
    private static String sha(byte[] bytes) {
        try { return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes)); }
        catch (java.security.NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); }
    }
}

package dev.dual.ledger.file;

import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;

import java.io.IOException;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;

/**
 * Writes durable execution facts for workflow and node executions.
 *
 * This writer is intentionally narrow: it records runtime evidence such as
 * status, pid, duration, output refs, adapter metadata, and exceptions. It does
 * not route workflow state and does not decide whether the product goal is
 * satisfied; those belong to workflow routing and domain artifacts.
 */
final class ExecutionLedgerWriter {
    private final AtomicJsonWriter jsonWriter;

    ExecutionLedgerWriter(AtomicJsonWriter jsonWriter) {
        this.jsonWriter = jsonWriter;
    }

    WorkflowExecutionDocument startWorkflowExecution(
            WorkstreamPaths paths,
            WorkflowCurrentDocument current,
            String trigger
    ) throws IOException {
        var now = Instant.now();
        var document = new WorkflowExecutionDocument(
                1,
                nextId("wfe"),
                current.workflowInstanceId(),
                paths.workstreamId().value(),
                textOrDefault(trigger, "resume"),
                WorkflowExecutionStatus.RUNNING,
                List.of(),
                "",
                now,
                null,
                null
        );
        jsonWriter.write(paths.workflowExecutionJson(document.workflowExecutionId()), document);
        return document;
    }

    WorkflowExecutionDocument finishWorkflowExecution(
            WorkstreamPaths paths,
            WorkflowExecutionDocument workflowExecution,
            List<String> nodeExecutionIds,
            WorkflowExecutionStatus status,
            String stopReason
    ) throws IOException {
        var finishedAt = Instant.now();
        var document = new WorkflowExecutionDocument(
                workflowExecution.schemaVersion(),
                workflowExecution.workflowExecutionId(),
                workflowExecution.workflowInstanceId(),
                workflowExecution.workstreamId(),
                workflowExecution.trigger(),
                status == null ? WorkflowExecutionStatus.STOPPED : status,
                List.copyOf(nodeExecutionIds == null ? List.of() : nodeExecutionIds),
                stopReason == null ? "" : stopReason,
                workflowExecution.startedAt(),
                finishedAt,
                durationMs(workflowExecution.startedAt(), finishedAt)
        );
        jsonWriter.write(paths.workflowExecutionJson(document.workflowExecutionId()), document);
        return document;
    }

    NodeExecutionDocument startNodeExecution(
            WorkstreamPaths paths,
            String workflowExecutionId,
            NodeInstanceDocument node,
            AgentTaskDocument agentTask,
            long pid
    ) throws IOException {
        var now = Instant.now();
        var document = new NodeExecutionDocument(
                1,
                nextId("nxe"),
                agentTask == null ? "" : agentTask.agentTaskId(),
                workflowExecutionId,
                node.nodeInstanceId(),
                node.nodeDefinitionId(),
                node.handlerType(),
                NodeExecutionStatus.RUNNING,
                pid,
                "",
                null,
                List.of(),
                Map.of(),
                "",
                node.runRef(),
                "",
                "",
                "",
                null,
                now,
                null,
                null
        );
        jsonWriter.write(paths.nodeExecutionJson(document.nodeExecutionId()), document);
        return document;
    }

    NodeExecutionDocument finishNodeExecution(
            WorkstreamPaths paths,
            NodeExecutionDocument nodeExecution,
            NodeResult result
    ) throws IOException {
        var finishedAt = Instant.now();
        var resultMap = result == null ? Map.<String, Object>of() : result.result();
        var document = new NodeExecutionDocument(
                nodeExecution.schemaVersion(),
                nodeExecution.nodeExecutionId(),
                nodeExecution.agentTaskId(),
                nodeExecution.workflowExecutionId(),
                nodeExecution.nodeInstanceId(),
                nodeExecution.nodeDefinitionId(),
                nodeExecution.handlerType(),
                executionStatus(result == null ? null : result.status()),
                nodeExecution.pid(),
                result == null ? "" : result.outcome(),
                result == null ? null : result.status(),
                result == null ? List.of() : result.outputRefs(),
                resultMap,
                result == null ? "" : nullToEmpty(result.errorMessage()),
                text(resultMap.get("run_id")),
                text(resultMap.get("run_metadata")),
                text(resultMap.get("agent")),
                text(resultMap.get("session")),
                intValue(resultMap.get("exit_code")),
                nodeExecution.startedAt(),
                finishedAt,
                durationMs(nodeExecution.startedAt(), finishedAt)
        );
        jsonWriter.write(paths.nodeExecutionJson(document.nodeExecutionId()), document);
        return document;
    }

    NodeExecutionDocument failNodeExecution(
            WorkstreamPaths paths,
            NodeExecutionDocument nodeExecution,
            Exception failure
    ) throws IOException {
        var finishedAt = Instant.now();
        var details = new LinkedHashMap<String, Object>();
        details.put("exception_type", failure == null ? "" : failure.getClass().getName());
        details.put("exception_message", failure == null ? "" : nullToEmpty(failure.getMessage()));
        var document = new NodeExecutionDocument(
                nodeExecution.schemaVersion(),
                nodeExecution.nodeExecutionId(),
                nodeExecution.agentTaskId(),
                nodeExecution.workflowExecutionId(),
                nodeExecution.nodeInstanceId(),
                nodeExecution.nodeDefinitionId(),
                nodeExecution.handlerType(),
                NodeExecutionStatus.FAILED,
                nodeExecution.pid(),
                "exception",
                NodeStatus.FAILED,
                List.of(),
                details,
                failure == null ? "" : nullToEmpty(failure.getMessage()),
                nodeExecution.runRef(),
                nodeExecution.agentRunRef(),
                nodeExecution.agent(),
                nodeExecution.session(),
                null,
                nodeExecution.startedAt(),
                finishedAt,
                durationMs(nodeExecution.startedAt(), finishedAt)
        );
        jsonWriter.write(paths.nodeExecutionJson(document.nodeExecutionId()), document);
        return document;
    }

    List<NodeExecutionDocument> readNodeExecutions(WorkstreamPaths paths) throws IOException {
        if (!java.nio.file.Files.isDirectory(paths.nodeExecutionsDir())) {
            return List.of();
        }
        var documents = new ArrayList<NodeExecutionDocument>();
        try (var stream = java.nio.file.Files.list(paths.nodeExecutionsDir())) {
            var files = stream
                    .filter(path -> path.getFileName().toString().endsWith(".json"))
                    .sorted()
                    .toList();
            for (var file : files) {
                documents.add(jsonWriter.objectMapper().readValue(file.toFile(), NodeExecutionDocument.class));
            }
        }
        return documents;
    }

    Optional<NodeExecutionDocument> latestNodeExecution(WorkstreamPaths paths, NodeInstanceDocument node) throws IOException {
        if (node.latestExecutionId().isBlank()) {
            return Optional.empty();
        }
        var path = paths.nodeExecutionJson(node.latestExecutionId());
        if (!java.nio.file.Files.isRegularFile(path)) {
            return Optional.empty();
        }
        return Optional.of(jsonWriter.objectMapper().readValue(path.toFile(), NodeExecutionDocument.class));
    }

    NodeExecutionDocument markNodeExecutionStale(
            WorkstreamPaths paths,
            NodeExecutionDocument nodeExecution,
            String note
    ) throws IOException {
        var finishedAt = Instant.now();
        var staleResult = new LinkedHashMap<String, Object>();
        staleResult.putAll(nodeExecution.result());
        staleResult.put("reason", "STALE_RUNNING_PROCESS");
        staleResult.put("stale_running_pid", nodeExecution.pid() == null ? "" : nodeExecution.pid());
        staleResult.put("recovery_note", nullToEmpty(note));
        var document = new NodeExecutionDocument(
                nodeExecution.schemaVersion(),
                nodeExecution.nodeExecutionId(),
                nodeExecution.agentTaskId(),
                nodeExecution.workflowExecutionId(),
                nodeExecution.nodeInstanceId(),
                nodeExecution.nodeDefinitionId(),
                nodeExecution.handlerType(),
                NodeExecutionStatus.STALE,
                nodeExecution.pid(),
                "STALE_RUNNING_PROCESS",
                NodeStatus.FAILED,
                nodeExecution.outputRefs(),
                staleResult,
                "Running node had no live process.",
                nodeExecution.runRef(),
                nodeExecution.agentRunRef(),
                nodeExecution.agent(),
                nodeExecution.session(),
                nodeExecution.exitCode(),
                nodeExecution.startedAt(),
                finishedAt,
                durationMs(nodeExecution.startedAt(), finishedAt)
        );
        jsonWriter.write(paths.nodeExecutionJson(document.nodeExecutionId()), document);
        return document;
    }

    private static NodeExecutionStatus executionStatus(NodeStatus status) {
        if (status == null) {
            return NodeExecutionStatus.FAILED;
        }
        return switch (status) {
            case COMPLETED -> NodeExecutionStatus.SUCCEEDED;
            case FAILED, BLOCKED -> NodeExecutionStatus.FAILED;
            case RUNNING -> NodeExecutionStatus.RUNNING;
            case WAITING -> NodeExecutionStatus.WAITING;
            case READY -> NodeExecutionStatus.READY;
            case CREATED -> NodeExecutionStatus.CREATED;
            case SKIPPED -> NodeExecutionStatus.SKIPPED;
        };
    }

    private static Long durationMs(Instant startedAt, Instant finishedAt) {
        if (startedAt == null || finishedAt == null) {
            return null;
        }
        return Duration.between(startedAt, finishedAt).toMillis();
    }

    private static String nextId(String prefix) {
        return prefix + "-" + Instant.now().toEpochMilli() + "-" + UUID.randomUUID().toString().substring(0, 8);
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    private static String textOrDefault(String value, String fallback) {
        return value == null || value.isBlank() ? fallback : value;
    }

    private static String nullToEmpty(String value) {
        return value == null ? "" : value;
    }

    private static Integer intValue(Object value) {
        return value instanceof Number number ? number.intValue() : null;
    }
}

package dev.dual.ledger.file;

import java.time.Instant;

public record OperatorWorkspaceWorkstream(
        String workstreamId,
        String effectiveWorkdir,
        String title,
        String status,
        Instant updatedAt
) {
    OperatorWorkspaceWorkstream normalized() {
        return new OperatorWorkspaceWorkstream(
                blank(workstreamId),
                blank(effectiveWorkdir),
                blank(title),
                blank(status),
                updatedAt
        );
    }

    private static String blank(String value) {
        return value == null ? "" : value;
    }
}

package dev.dual.ledger.file;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Builds a deterministic recovery read model for CLI and API callers.
 *
 * Runtime handlers write the raw node result and optional contract diagnostic.
 * This class does not decide workflow transitions; it only explains why the
 * current node stopped and what an operator should inspect next.
 *
 * <p>{@code retrySafe} is the authoritative operator recovery fact: whether the
 * operator may continue recovery by running {@code suggestedCommand}. It is
 * declared at construction for every recovery result; downstream renderers
 * (WorkstreamAttention, CLI, API, reports) must copy it and never re-derive it
 * from {@code classification} or {@code retryReadiness}.
 */
public record RecoveryAssessment(
        String classification,
        String retryReadiness,
        String reason,
        String suggestedCommand,
        String diagnosticJsonRef,
        String diagnosticMarkdownRef,
        Map<String, Object> contractDiagnostic,
        boolean retrySafe,
        Map<String, Object> permissionRequest,
        java.util.List<String> allowedActions
) {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    public RecoveryAssessment(
            String classification,
            String retryReadiness,
            String reason,
            String suggestedCommand,
            String diagnosticJsonRef,
            String diagnosticMarkdownRef,
            Map<String, Object> contractDiagnostic,
            boolean retrySafe
    ) {
        this(classification, retryReadiness, reason, suggestedCommand, diagnosticJsonRef,
                diagnosticMarkdownRef, contractDiagnostic, retrySafe, Map.of(), java.util.List.of());
    }

    public RecoveryAssessment {
        permissionRequest = permissionRequest == null ? Map.of() : Map.copyOf(permissionRequest);
        allowedActions = allowedActions == null ? java.util.List.of() : java.util.List.copyOf(allowedActions);
    }

    public static RecoveryAssessment from(
            NodeInstanceDocument node,
            Path workspaceRoot,
            String workstreamId
    ) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var result = node.result() == null ? Map.<String, Object>of() : node.result();
        var retry = "dualctl retry --workdir " + root + " " + workstreamId;
        var abort = "dualctl recovery abort --workdir " + root + " " + workstreamId;
        var diagnosticJsonRef = text(result.get("contract_failure_diagnostic_ref"));
        var diagnosticMarkdownRef = text(result.get("contract_failure_diagnostic_markdown_ref"));
        var diagnostic = readDiagnostic(root, diagnosticJsonRef);
        var agent = blankDefault(text(result.get("agent")), "claude");
        var session = blankDefault(text(result.get("session")), agent + "-main");
        if (result.get("input_preparation_failure") instanceof Map<?, ?> failure
                && node.status() == dev.dual.core.workflow.NodeStatus.FAILED
                && Boolean.FALSE.equals(failure.get("providerInvoked"))) {
            return new RecoveryAssessment("input_preparation_failure", "FIX_INPUTS_BEFORE_MANUAL_RETRY",
                    "Input preparation rejected before provider dispatch: " + text(failure.get("reason"))
                            + " / " + text(failure.get("code")) + ": " + text(failure.get("details")),
                    "Inspect the current input identity and approval evidence before `" + retry
                            + "`; or stop with `" + abort + "`.",
                    "", "", Map.of(), false);
        }
        var outcomeAssessment = fromAgentExecutionOutcome(
                result.get("agent_execution_outcome"),
                retry,
                agent,
                session,
                diagnosticJsonRef,
                diagnosticMarkdownRef,
                diagnostic
        );
        if (outcomeAssessment != null) {
            var permissionRequest = readPermissionEscalation(root, workstreamId, result);
            if ("agent_permission_blocked".equals(outcomeAssessment.classification())
                    && !permissionRequest.isEmpty()) {
                return new RecoveryAssessment(
                        "agent_permission_approval_required",
                        "HUMAN_APPROVE_PUBLIC_WEBSEARCH_OR_ABORT",
                        "The agent requested exact WebSearch for a public fact. The current turn was denied; a human may approve WebSearch for one retry only after confirming this repository is public.",
                        "dualctl recovery approve-websearch --public-repository --note \"<reason>\" --workdir "
                                + root + " " + workstreamId,
                        diagnosticJsonRef,
                        diagnosticMarkdownRef,
                        diagnostic,
                        false,
                        permissionRequest,
                        java.util.List.of("approve_public_websearch", "abort")
                );
            }
            return outcomeAssessment;
        }
        var diagnosticCategory = text(diagnostic.get("category"));
        var diagnosticHint = text(diagnostic.get("recovery_hint"));
        var failureReason = text(firstNonBlank(
                result.get("acpx_failure.reason"),
                result.get("reason"),
                result.get("error"),
                result.get("message")
        ));
        var recoverable = Boolean.TRUE.equals(result.get("acpx_failure.recoverable"))
                || Boolean.TRUE.equals(result.get("recoverable"));

        if ("revision_limit_reached".equals(failureReason) || "BLOCKED".equals(node.status().name())) {
            return new RecoveryAssessment(
                    "semantic_revision_limit",
                    "NEEDS_HUMAN_DECISION",
                    "The workflow exhausted its revision budget. Blind retry will likely repeat the same loop.",
                    "Inspect evidence, adjust the task/contract, then run `" + retry + "`; or stop with `" + abort + "`.",
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if (!diagnosticCategory.isBlank() || FailureReasonSemantics.isArtifactContractFailure(failureReason)) {
            return new RecoveryAssessment(
                    "artifact_contract_failure",
                    "RETRY_AFTER_OUTPUT_CONTRACT_FIX",
                    diagnosticHint.isBlank()
                            ? "The agent output contract was invalid or missing. Inspect the diagnostic before retrying."
                            : diagnosticHint,
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if ("RECOVERABLE_AGENT_MODEL_MISMATCH".equals(failureReason)) {
            return new RecoveryAssessment(
                    "agent_model_mismatch",
                    "REBUILD_ACPX_SESSION_THEN_RETRY",
                    "The acpx session model state is stale or incompatible with the current Claude Code/provider configuration. Rebuild the acpx session before retrying.",
                    "acpx " + agent + " sessions close " + session
                            + " && acpx " + agent + " sessions new --name " + session
                            + " && " + retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    true
            );
        }
        if ("RECOVERABLE_AGENT_AUTH_FAILED".equals(failureReason)) {
            return new RecoveryAssessment(
                    "agent_auth_failed",
                    "FIX_AGENT_AUTH_THEN_RETRY",
                    "The agent adapter failed authentication. Fix the underlying Claude/Codex runtime credentials or adapter configuration, then retry the same active node.",
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if ("RECOVERABLE_PROVIDER_CONNECTION_FAILED".equals(failureReason)) {
            return new RecoveryAssessment(
                    "provider_connection_failed",
                    "WAIT_OR_FIX_PROVIDER_CONNECTION_THEN_RETRY",
                    "The agent provider connection failed before a trustworthy agent output boundary. Verify provider/network/socket availability, then retry the same active node.",
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if ("RECOVERABLE_AGENT_RECONNECT".equals(failureReason)
                || "RECOVERABLE_AGENT_OUTPUT_INTERRUPTED".equals(failureReason)
                || "RECOVERABLE_AGENT_PERMISSION_BLOCKED".equals(failureReason)
                || "RECOVERABLE_SESSION_MISSING".equals(failureReason)
                || "RECOVERABLE_CONTEXT_WINDOW".equals(failureReason)) {
            var classification = "RECOVERABLE_AGENT_OUTPUT_INTERRUPTED".equals(failureReason)
                    ? "agent_output_interrupted"
                    : "RECOVERABLE_AGENT_PERMISSION_BLOCKED".equals(failureReason)
                    ? "agent_permission_blocked"
                    : "agent_session_recovery";
            // A blocked permission is not safe to retry blindly; session/output
            // recovery rebuilds the session first, so the suggested command is safe.
            var branchRetrySafe = !"agent_permission_blocked".equals(classification);
            return new RecoveryAssessment(
                    classification,
                    "REBUILD_ACPX_SESSION_THEN_RETRY",
                    sessionRecoveryReason(failureReason),
                    "acpx " + agent + " sessions close " + session
                            + " && acpx " + agent + " sessions new --name " + session
                            + " && " + retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    branchRetrySafe
            );
        }
        if ("RECOVERABLE_RATE_LIMIT".equals(failureReason)
                || "RECOVERABLE_AGENT_OVERLOADED".equals(failureReason)) {
            return new RecoveryAssessment(
                    "agent_capacity_recovery",
                    "WAIT_THEN_RETRY",
                    capacityRecoveryReason(failureReason),
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    true
            );
        }
        if (recoverable) {
            return new RecoveryAssessment(
                    "recoverable_agent_runtime",
                    "RETRY_AFTER_EXTERNAL_FIX",
                    "The failed node is marked recoverable, but its typed reason is not mapped to a specific operator action yet. Inspect adapter evidence before retrying.",
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    true
            );
        }
        if (FailureReasonSemantics.isArtifactContractFailure(failureReason)) {
            return new RecoveryAssessment(
                    "artifact_contract_failure",
                    "RETRY_AFTER_OUTPUT_CONTRACT_FIX",
                    "The agent output contract was invalid or missing. Inspect the output before retrying.",
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        return new RecoveryAssessment(
                "manual_recovery_required",
                "INSPECT_BEFORE_RETRY",
                "The failure is not marked recoverable. Read the evidence before deciding whether retry is safe.",
                retry + "  # only after fixing the cause",
                diagnosticJsonRef,
                diagnosticMarkdownRef,
                diagnostic,
                false
        );
    }

    private static RecoveryAssessment fromAgentExecutionOutcome(
            Object value,
            String retry,
            String agent,
            String session,
            String diagnosticJsonRef,
            String diagnosticMarkdownRef,
            Map<String, Object> diagnostic
    ) {
        if (!(value instanceof Map<?, ?> raw)) {
            return null;
        }
        var outcome = asStringMap(raw);
        var recoveryCategory = text(outcome.get("recoveryCategory"));
        var primaryReason = text(outcome.get("primaryReason"));
        var operatorMessage = text(outcome.get("operatorMessage"));
        if ("ARTIFACT_CONTRACT_FAILURE".equals(recoveryCategory)) {
            var diagnosticHint = text(diagnostic.get("recovery_hint"));
            return new RecoveryAssessment(
                    "artifact_contract_failure",
                    "RETRY_AFTER_OUTPUT_CONTRACT_FIX",
                    diagnosticHint.isBlank()
                            ? blankDefault(operatorMessage, "The agent output contract was invalid or missing. Inspect the diagnostic before retrying.")
                            : diagnosticHint,
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if ("OUTPUT_INCOMPLETE".equals(recoveryCategory)) {
            return new RecoveryAssessment(
                    "agent_output_incomplete",
                    "process_output_incomplete".equals(primaryReason)
                            ? "RETRY_AFTER_EXTERNAL_FIX" : "RETRY_AFTER_OUTPUT_CONTRACT_FIX",
                    blankDefault(operatorMessage, "The agent output stopped before a valid terminal control and artifact boundary."),
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if ("TIMEOUT_OR_STALLED".equals(recoveryCategory)) {
            return new RecoveryAssessment(
                    "agent_timeout_or_stalled",
                    "RETRY_AFTER_EXTERNAL_FIX",
                    blankDefault(operatorMessage, "The agent process timed out or stalled before completing the execution boundary."),
                    retry,
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if ("INTERRUPTED".equals(recoveryCategory)) {
            return new RecoveryAssessment(
                    "agent_interrupted",
                    "INSPECT_BEFORE_RETRY",
                    blankDefault(operatorMessage, "The agent execution was interrupted before completion."),
                    retry + "  # only after confirming the interruption cause",
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        if ("RECOVERABLE_ADAPTER_FAILURE".equals(recoveryCategory)) {
            return new RecoveryAssessment(
                    adapterClassification(primaryReason),
                    adapterRetryReadiness(primaryReason),
                    blankDefault(operatorMessage, "The adapter reported a recoverable execution failure."),
                    adapterSuggestedCommand(primaryReason, agent, session, retry),
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    adapterRetrySafe(primaryReason)
            );
        }
        if ("NON_RECOVERABLE_ADAPTER_FAILURE".equals(recoveryCategory)) {
            return new RecoveryAssessment(
                    "non_recoverable_adapter_failure",
                    "NEEDS_HUMAN_DECISION",
                    blankDefault(operatorMessage, "The adapter reported a non-recoverable execution failure."),
                    retry + "  # only after changing adapter configuration or task boundary",
                    diagnosticJsonRef,
                    diagnosticMarkdownRef,
                    diagnostic,
                    false
            );
        }
        return null;
    }

    private static Map<String, Object> asStringMap(Map<?, ?> raw) {
        var map = new LinkedHashMap<String, Object>();
        for (var entry : raw.entrySet()) {
            if (entry.getKey() != null) {
                map.put(entry.getKey().toString(), entry.getValue());
            }
        }
        return map;
    }

    private static String adapterClassification(String primaryReason) {
        return switch (primaryReason) {
            case "auth_failed" -> "agent_auth_failed";
            case "permission_blocked" -> "agent_permission_blocked";
            case "provider_connection_failed" -> "provider_connection_failed";
            case "context_window_exceeded" -> "agent_context_window";
            case "rate_limited" -> "agent_capacity_recovery";
            case "agent_reconnect_required", "session_bootstrap_failed" -> "agent_session_recovery";
            default -> "manual_recovery_required";
        };
    }

    private static String adapterRetryReadiness(String primaryReason) {
        return switch (primaryReason) {
            case "auth_failed" -> "FIX_AGENT_AUTH_THEN_RETRY";
            case "rate_limited" -> "WAIT_THEN_RETRY";
            case "provider_connection_failed" -> "WAIT_OR_FIX_PROVIDER_CONNECTION_THEN_RETRY";
            case "agent_reconnect_required" -> "REBUILD_ACPX_SESSION_THEN_RETRY";
            // session_bootstrap_failed is generic: it may be a command timeout, spawn
            // failure, config error or any non-zero exit, not necessarily a missing
            // session. Do not assume `sessions new` recovers it; inspect before retry.
            case "session_bootstrap_failed" -> "INSPECT_BEFORE_RETRY";
            case "permission_blocked",
                 "context_window_exceeded" -> "RETRY_AFTER_EXTERNAL_FIX";
            default -> "INSPECT_BEFORE_RETRY";
        };
    }

    private static boolean adapterRetrySafe(String primaryReason) {
        // Only adapter failures whose suggested action rebuilds the session or
        // waits for capacity are safe to continue without a human decision.
        return switch (primaryReason) {
            case "rate_limited", "agent_reconnect_required" -> true;
            // A generic bootstrap failure is not blindly retry-safe: its cause is
            // unknown, so retrySafe must match the inspect-then-retry command.
            case "session_bootstrap_failed" -> false;
            default -> false;
        };
    }

    private static String adapterSuggestedCommand(
            String primaryReason,
            String agent,
            String session,
            String retry
    ) {
        return switch (primaryReason) {
            case "agent_reconnect_required" ->
                    "acpx " + agent + " sessions close " + session
                            + " && acpx " + agent + " sessions new --name " + session
                            + " && " + retry;
            // Bootstrap failure is generic (timeout/spawn/config/nonzero); do not assume
            // `sessions new` recovers it. retrySafe is false and the command asks for
            // inspection before a manual retry.
            case "session_bootstrap_failed" ->
                    retry + "  # only after inspecting the session bootstrap failure";
            case "permission_blocked" ->
                    retry + "  # only after changing the permission policy and rebuilding the acpx session";
            case "auth_failed",
                 "provider_connection_failed",
                 "context_window_exceeded",
                 "rate_limited" -> retry;
            default -> retry + "  # only after inspecting the typed adapter failure";
        };
    }

    public Map<String, Object> toMap() {
        var map = new LinkedHashMap<String, Object>();
        map.put("classification", classification);
        map.put("retryReadiness", retryReadiness);
        map.put("retrySafe", retrySafe);
        map.put("reason", reason);
        map.put("suggestedCommand", suggestedCommand);
        map.put("diagnosticJsonRef", diagnosticJsonRef);
        map.put("diagnosticMarkdownRef", diagnosticMarkdownRef);
        map.put("contractDiagnostic", contractDiagnostic);
        map.put("permissionRequest", permissionRequest);
        map.put("allowedActions", allowedActions);
        return map;
    }

    private static Map<String, Object> readPermissionEscalation(
            Path root,
            String workstreamId,
            Map<String, Object> result
    ) {
        var runRef = text(result.get("run_metadata"));
        if (runRef.isBlank()) {
            return Map.of();
        }
        try {
            var path = root.resolve(runRef).normalize();
            var workstreamRoot = root.resolve(".agent/workstreams").resolve(workstreamId).normalize();
            if (!path.startsWith(workstreamRoot) || !Files.isRegularFile(path)) {
                return Map.of();
            }
            var run = OBJECT_MAPPER.readTree(path.toFile());
            var timeline = run.path("executionTimeline");
            if (!timeline.isArray()) {
                return Map.of();
            }
            for (var index = timeline.size() - 1; index >= 0; index--) {
                var event = timeline.get(index);
                var details = event.path("details");
                if ("permission_decision".equals(event.path("kind").asText())
                        && "ESCALATION_REQUIRED".equals(details.path("authorityDisposition").asText())
                        && "fetch".equals(details.path("toolKind").asText())
                        && "WebSearch".equals(details.path("toolName").asText())) {
                    var request = new LinkedHashMap<String, Object>();
                    request.put("toolName", "WebSearch");
                    request.put("toolKind", "fetch");
                    request.put("toolCallId", details.path("toolCallId").asText());
                    request.put("query", details.path("resource").asText());
                    request.put("runRef", runRef);
                    request.put("disposition", details.path("disposition").asText());
                    return Map.copyOf(request);
                }
            }
        } catch (Exception ignored) {
            return Map.of();
        }
        return Map.of();
    }

    private static Map<String, Object> readDiagnostic(Path root, String ref) {
        if (ref.isBlank()) {
            return Map.of();
        }
        try {
            var path = root.resolve(ref).normalize();
            if (!path.startsWith(root) || !Files.isRegularFile(path)) {
                return Map.of();
            }
            return OBJECT_MAPPER.readValue(path.toFile(), MAP_TYPE);
        } catch (Exception ignored) {
            return Map.of();
        }
    }

    private static Object firstNonBlank(Object... values) {
        for (var value : values) {
            if (value != null && !value.toString().isBlank()) {
                return value;
            }
        }
        return "";
    }

    private static String text(Object value) {
        return value == null ? "" : value.toString().trim();
    }

    private static String blankDefault(String value, String fallback) {
        return value == null || value.isBlank() ? fallback : value;
    }

    private static String sessionRecoveryReason(String failureReason) {
        return switch (failureReason) {
            case "RECOVERABLE_AGENT_OUTPUT_INTERRUPTED" ->
                    "The agent output stopped before the terminal contract after the acpx timeout. Rebuild the acpx session to avoid continuing a partial context, then retry the same active node.";
            case "RECOVERABLE_AGENT_PERMISSION_BLOCKED" ->
                    "The agent attempted a tool action that was blocked by non-interactive permissions. Inspect the agent output and either adjust the task/session permission policy or retry after confirming the node is allowed to use those tools.";
            case "RECOVERABLE_SESSION_MISSING" ->
                    "The acpx session is missing. Create the session again, then retry the same active node.";
            case "RECOVERABLE_CONTEXT_WINDOW" ->
                    "The agent context window appears exhausted. Rebuild the acpx session to get a fresh context, then retry the same active node.";
            default ->
                    "The acpx agent session needs reconnect. Rebuild the acpx session, then retry the same active node.";
        };
    }

    private static String capacityRecoveryReason(String failureReason) {
        if ("RECOVERABLE_AGENT_OVERLOADED".equals(failureReason)) {
            return "The agent provider is overloaded. Wait for provider capacity to recover, then retry the same active node.";
        }
        return "The agent quota or rate limit was hit. Wait for quota recovery, then retry the same active node.";
    }
}

    package dev.dual.ledger.file;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.module.SimpleModule;
import com.fasterxml.jackson.databind.ser.std.StdSerializer;
import dev.dual.core.workflow.EdgeCondition;

import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Jackson module for serializing/deserializing {@link EdgeCondition} polymorphic instances.
 * Uses the {@code type()} and {@code params()} methods on EdgeCondition so the module
 * stays decoupled from concrete implementation classes.
 */
public final class EdgeConditionModule extends SimpleModule {

    public EdgeConditionModule() {
        super("EdgeConditionModule");
        addSerializer(EdgeCondition.class, new Serializer());
        addDeserializer(EdgeCondition.class, new Deserializer());
    }

    static final class Serializer extends StdSerializer<EdgeCondition> {
        Serializer() { super(EdgeCondition.class); }

        @Override
        public void serialize(EdgeCondition value, JsonGenerator gen, SerializerProvider provider) throws IOException {
            // Unconditional → write null (consumers treat missing/null condition as unconditional)
            if ("unconditional".equals(value.type())) {
                gen.writeNull();
                return;
            }
            gen.writeStartObject();
            gen.writeStringField("type", value.type());
            gen.writeObjectFieldStart("params");
            for (var entry : value.params().entrySet()) {
                gen.writeObjectField(entry.getKey(), entry.getValue());
            }
            gen.writeEndObject();
            gen.writeEndObject();
        }
    }

    static final class Deserializer extends StdDeserializer<EdgeCondition> {
        Deserializer() { super(EdgeCondition.class); }

        @Override
        public EdgeCondition deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
            JsonNode node = p.getCodec().readTree(p);
            if (node == null || node.isNull()) {
                return EdgeCondition.unconditional();
            }
            String type = node.has("type") ? node.get("type").asText() : "unconditional";
            Map<String, Object> params = new LinkedHashMap<>();
            if (node.has("params") && node.get("params").isObject()) {
                var fields = node.get("params").fields();
                while (fields.hasNext()) {
                    var entry = fields.next();
                    params.put(entry.getKey(), textValue(entry.getValue()));
                }
            }
            return EdgeCondition.fromTypeAndParams(type, params);
        }

        private static Object textValue(JsonNode node) {
            if (node.isTextual()) return node.asText();
            if (node.isNumber()) return node.numberValue();
            if (node.isBoolean()) return node.asBoolean();
            return node.asText();
        }
    }
}

