                                TransitionMetadata.fork("parallel-review", true, "first review branch")),
                        new EdgeDefinition("node_a", "DONE", "node_c", EdgeCondition.unconditional(),
                                TransitionMetadata.fork("parallel-review", true, "second review branch"))
