package dev.dual.adapter.acpx;

import java.io.IOException;
import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Optional;
import java.util.regex.Pattern;

/**
 * 读取 acpx session stream 中属于当前 prompt 的 token usage。
 *
 * <p>参数说明：</p>
 * <ul>
 *     <li>{@code promptPath}: 当前 NodeExecution 写入 acpx 的 prompt 文件。</li>
 *     <li>{@code stderrPath}: acpx stderr 文件，用于提取真实 session id。</li>
 * </ul>
 *
 * <p>归因优先级（必须严格区分，不得伪装）：</p>
 * <ol>
 *     <li>优先按 request id 链路定位本次 prompt 的 {@code result.usage}：
 *     先尝试 prompt 文本精确匹配，命中则 {@code attribution=EXACT_PROMPT_MATCH}；
 *     命中不了则取会话内最近一条 {@code session/prompt} 的 request id，再找同 id 的
 *     {@code result.usage}，{@code attribution=LATEST_PROMPT_IN_SESSION}。两者都是真实的
 *     provider run usage，允许聚合。</li>
 *     <li>若该 request id 一直没有 {@code result.usage}（部分 adapter 只回 usage_update），
 *     则把最新 {@code usage_update.used} 记录为 {@code SESSION_USED_SNAPSHOT} 会话累计快照，
 *     {@code attribution=SESSION_USAGE_UPDATE}，<b>不</b>当作单次 run 用量加总。</li>
 *     <li>都没有则返回空，交由 ledger 侧 fallback 到 artifact_estimate。</li>
 * </ol>
 *
 * <p>result.usage 是由 acpx 异步追加到 stream 的，常常晚于 agent 进程退出。本读取器会
 * 在首次没拿到 provider run usage 时按 {@code retryAttempts}×{@code retryDelayMs} 轮询
 * 重读（默认窗口远大于旧的 1.2s），<b>且</b>即便已经看到 usage_update 快照也会继续等
 * provider run usage，避免被早到的快照短路成假阴性的 measured=0。</p>
 *
 * <p>这个类只产出外部 adapter 的结构化观测事实，不参与 workflow 路由，也不解析自然语言正文。</p>
 */
final class AcpxUsageReader {
    private static final int DEFAULT_RETRY_ATTEMPTS = 50;
    private static final long DEFAULT_RETRY_DELAY_MS = 200L;
    private static final String RETRY_ATTEMPTS_ENV = "DUAL_ACPX_USAGE_READ_ATTEMPTS";
    private static final String RETRY_DELAY_ENV = "DUAL_ACPX_USAGE_READ_DELAY_MS";
    private static final Pattern SESSION_ID_PATTERN = Pattern.compile(
            "\\(([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\\)"
    );

    private final Path sessionsDir;
    private final int retryAttempts;
    private final long retryDelayMs;
    private final AcpxProviderMetadata fallbackMetadata;

    AcpxUsageReader() {
        this(Path.of(System.getProperty("user.home"), ".acpx", "sessions"));
    }

    AcpxUsageReader(Path sessionsDir) {
        this(sessionsDir, configuredRetryAttempts(), configuredRetryDelayMs());
    }

    AcpxUsageReader(Path sessionsDir, int retryAttempts, long retryDelayMs) {
        this(sessionsDir, retryAttempts, retryDelayMs, null);
    }

    AcpxUsageReader(Path sessionsDir, int retryAttempts, long retryDelayMs, AcpxProviderMetadata fallbackMetadata) {
        this.sessionsDir = sessionsDir;
        this.retryAttempts = Math.max(1, retryAttempts);
        this.retryDelayMs = Math.max(0, retryDelayMs);
        this.fallbackMetadata = fallbackMetadata;
    }

    private static int configuredRetryAttempts() {
        return envInt(RETRY_ATTEMPTS_ENV, DEFAULT_RETRY_ATTEMPTS);
    }

    private static long configuredRetryDelayMs() {
        return envLong(RETRY_DELAY_ENV, DEFAULT_RETRY_DELAY_MS);
    }

    private static int envInt(String name, int fallback) {
        var value = System.getenv(name);
        if (value == null || value.isBlank()) {
            return fallback;
        }
        try {
            var parsed = Integer.parseInt(value.trim());
            return parsed > 0 ? parsed : fallback;
        } catch (NumberFormatException ignored) {
            return fallback;
        }
    }

    private static long envLong(String name, long fallback) {
        var value = System.getenv(name);
        if (value == null || value.isBlank()) {
            return fallback;
        }
        try {
            var parsed = Long.parseLong(value.trim());
            return parsed >= 0 ? parsed : fallback;
        } catch (NumberFormatException ignored) {
            return fallback;
        }
    }

    Optional<AcpxUsage> read(String agent, Path promptPath, Path stderrPath) {
        try {
            var stderr = Files.exists(stderrPath) ? Files.readString(stderrPath) : "";
            var sessionId = sessionIdFrom(stderr);
            if (sessionId.isEmpty() || !Files.isRegularFile(promptPath)) {
                var metadata = fallbackMetadata != null ? fallbackMetadata : agentFallbackMetadata(agent);
                return metadata.isEmpty()
                        ? Optional.empty()
                        : Optional.of(AcpxUsage.unavailable("NO_ACPX_SESSION_ID", metadata));
            }
            var streamPath = sessionsDir.resolve(sessionId.get() + ".stream.ndjson");
            if (!Files.isRegularFile(streamPath)) {
                return Optional.empty();
            }
            var metadata = AcpxProviderMetadata.read(sessionsDir.resolve(sessionId.get() + ".json"));
            return readMatchingUsageWithRetry(streamPath, Files.readString(promptPath), metadata);
        } catch (IOException ignored) {
            return Optional.empty();
        }
    }

    /**
     * Identity fallback when no current-agent session metadata is observable. Only
     * Claude may reuse Claude settings/env as a labelled fallback; any other agent
     * (e.g. Codex) must remain {@code unknown} rather than be projected through a
     * Claude-specific config. This affects metrics/metadata projection only.
     */
    private static AcpxProviderMetadata agentFallbackMetadata(String agent) {
        return "claude".equals(agent) ? AcpxProviderMetadata.runtimeDefault() : AcpxProviderMetadata.empty();
    }

    private Optional<AcpxUsage> readMatchingUsageWithRetry(
            Path streamPath,
            String promptText,
            AcpxProviderMetadata metadata
    ) throws IOException {
        for (var attempt = 0; attempt < retryAttempts; attempt++) {
            var match = readMatchingUsage(streamPath, promptText);
            if (match.hasProviderUsage() || attempt == retryAttempts - 1) {
                var best = match.best();
                return best == null ? Optional.empty() : Optional.of(best.withProviderMetadata(metadata));
            }
            sleepBeforeRetry();
        }
        return Optional.empty();
    }

    /**
     * 一次扫描 stream 的结果。三档按优先级取：精确 provider &gt; 最近 provider &gt; 会话快照。
     * 包级可见以便单测直接验证归因/优先级，而不依赖重试时序。
     */
    record Match(AcpxUsage exact, AcpxUsage latest, AcpxUsage snapshot) {
        boolean hasProviderUsage() {
            return exact != null || latest != null;
        }

        AcpxUsage best() {
            return exact != null ? exact : latest != null ? latest : snapshot;
        }
    }

    Match readMatchingUsage(Path streamPath, String promptText) throws IOException {
        String matchedRequestId = null;
        String latestPromptRequestId = null;
        AcpxUsage exactUsage = null;
        AcpxUsage fallbackUsage = null;
        AcpxUsage usageUpdateFallback = null;
        BigDecimal costAmount = null;
        String costCurrency = "";
        BigDecimal matchedPromptStartingCost = null;
        BigDecimal latestPromptStartingCost = null;
        for (var line : Files.readAllLines(streamPath)) {
            if (line == null || line.isBlank()) {
                continue;
            }
            var wire = AcpxStreamWireLine.parse(line);
            if (wire.kind() == AcpxStreamWireLine.Kind.MALFORMED) {
                continue;
            }
            if (isPrompt(wire)) {
                var firstPrompt = latestPromptRequestId == null;
                latestPromptRequestId = wire.requestId();
                latestPromptStartingCost = startingCostForPrompt(costAmount, firstPrompt);
                if (matchedRequestId == null && isMatchingPrompt(wire, promptText)) {
                    matchedRequestId = latestPromptRequestId;
                    matchedPromptStartingCost = latestPromptStartingCost;
                }
                continue;
            }
            if (isUsageUpdate(wire)) {
                var update = wire.notification().usageUpdate();
                if (update.costAmount() != null) {
                    costAmount = update.costAmount();
                    costCurrency = update.costCurrency();
                }
                var used = update.used();
                if (used > 0) {
                    usageUpdateFallback = new AcpxUsage(
                            0,
                            0,
                            0,
                            0,
                            0,
                            null,
                            "",
                            "acpx_usage_update",
                            AcpxUsage.SESSION_USED_SNAPSHOT,
                            AcpxUsage.ATTR_SESSION_USAGE_UPDATE,
                            true,
                            used,
                            costAmount,
                            costCurrency,
                            "",
                            "",
                            "",
                            "",
                            ""
                    );
                }
            }
            if (wire.kind() == AcpxStreamWireLine.Kind.JSONRPC_OK
                    && wire.result() != null
                    && wire.result().usage() != null) {
                var requestId = wire.requestId();
                if (matchedRequestId != null && matchedRequestId.equals(requestId)) {
                    exactUsage = usageFrom(
                            wire.result().usage(),
                            matchedPromptStartingCost,
                            costAmount,
                            costCurrency,
                            AcpxUsage.ATTR_EXACT_PROMPT_MATCH
                    );
                }
                if (latestPromptRequestId != null && latestPromptRequestId.equals(requestId)) {
                    fallbackUsage = usageFrom(
                            wire.result().usage(),
                            latestPromptStartingCost,
                            costAmount,
                            costCurrency,
                            AcpxUsage.ATTR_LATEST_PROMPT_IN_SESSION
                    );
                }
            }
        }
        return new Match(exactUsage, fallbackUsage, usageUpdateFallback);
    }

    private BigDecimal startingCostForPrompt(BigDecimal observedCostAmount, boolean firstPrompt) {
        if (observedCostAmount != null) {
            return observedCostAmount;
        }
        return firstPrompt ? BigDecimal.ZERO : null;
    }

    private boolean isPrompt(AcpxStreamWireLine wire) {
        return wire.kind() == AcpxStreamWireLine.Kind.JSONRPC_REQUEST
                && "session/prompt".equals(wire.method());
    }

    private boolean isMatchingPrompt(AcpxStreamWireLine wire, String promptText) {
        return isPrompt(wire)
                && wire.request() != null
                && promptText.equals(wire.request().promptText());
    }

    private AcpxUsage usageFrom(
            AcpxStreamWireLine.Usage usage,
            BigDecimal startingCostAmount,
            BigDecimal sessionCostAmount,
            String sessionCostCurrency,
            String attribution
    ) {
        var runCostAmount = costDelta(startingCostAmount, sessionCostAmount);
        return new AcpxUsage(
                usage.inputTokens(),
                usage.outputTokens(),
                usage.cachedReadTokens(),
                usage.cachedWriteTokens(),
                usage.totalTokens(),
                runCostAmount,
                sessionCostCurrency,
                "acpx_stream",
                AcpxUsage.PROVIDER_RUN_USAGE,
                attribution,
                false,
                0,
                sessionCostAmount,
                sessionCostCurrency,
                "",
                "",
                "",
                "",
                ""
        );
    }

    private BigDecimal costDelta(BigDecimal startingCostAmount, BigDecimal sessionCostAmount) {
        if (sessionCostAmount == null || startingCostAmount == null) {
            return null;
        }
        var delta = sessionCostAmount.subtract(startingCostAmount);
        return delta.signum() < 0 ? null : delta;
    }

    private boolean isUsageUpdate(AcpxStreamWireLine wire) {
        return wire.kind() == AcpxStreamWireLine.Kind.NOTIFICATION
                && "session/update".equals(wire.method())
                && wire.notification() != null
                && wire.notification().usageUpdate() != null;
    }

    private Optional<String> sessionIdFrom(String stderr) {
        if (stderr == null || stderr.isBlank() || !stderr.contains("[acpx] session")) {
            return Optional.empty();
        }
        var matcher = SESSION_ID_PATTERN.matcher(stderr);
        String latest = null;
        while (matcher.find()) {
            latest = matcher.group(1);
        }
        return Optional.ofNullable(latest);
    }

    private void sleepBeforeRetry() {
        if (retryDelayMs == 0) {
            return;
        }
        try {
            Thread.sleep(retryDelayMs);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

package dev.dual.adapter.acpx;

import java.math.BigDecimal;

/**
 * 一次 acpx agent run 的 token usage 观测事实。
 *
 * <p>三种 measurementType 必须严格区分，不能互相伪装：</p>
 * <ul>
 *     <li>{@link #PROVIDER_RUN_USAGE}：来自 stream 中 {@code result.usage} 的本次 provider
 *     用量，允许聚合进 metrics 总量。</li>
 *     <li>{@link #SESSION_USED_SNAPSHOT}：来自 {@code usage_update.used} 的会话累计/上下文
 *     快照，<b>不允许</b>当作单次 run 用量加总，只能单独展示用于判断 session 是否滚雪球。</li>
 *     <li>{@code ARTIFACT_ESTIMATE}（由 ledger 侧按文件大小估算，不在此 record 构造）：
 *     仅作 fallback，不进入总量。</li>
 * </ul>
 *
 * <p>{@link #attribution} 进一步说明 provider_run_usage 是如何归因到本次 run 的，避免把
 * “最近一条 prompt 的 result”伪装成精确匹配。</p>
 */
record AcpxUsage(
        long inputTokens,
        long outputTokens,
        long cachedReadTokens,
        long cachedWriteTokens,
        long totalTokens,
        BigDecimal costAmount,
        String costCurrency,
        String source,
        String measurementType,
        String attribution,
        boolean cumulative,
        long contextUsedTokens,
        BigDecimal sessionCostAmount,
        String sessionCostCurrency,
        String providerId,
        String model,
        String billingMode,
        String providerMetadataSource,
        String unavailableReason
) {
    static final String PROVIDER_RUN_USAGE = "PROVIDER_RUN_USAGE";
    static final String SESSION_USED_SNAPSHOT = "SESSION_USED_SNAPSHOT";
    static final String UNAVAILABLE = "UNAVAILABLE";

    /** result.usage 精确匹配到本次 prompt 文本。 */
    static final String ATTR_EXACT_PROMPT_MATCH = "EXACT_PROMPT_MATCH";
    /** 无法精确匹配 prompt 文本，按 request id 取会话内最近一条 prompt 的 result.usage。 */
    static final String ATTR_LATEST_PROMPT_IN_SESSION = "LATEST_PROMPT_IN_SESSION";
    /** 只有 usage_update，没有 result.usage，记录为会话累计快照。 */
    static final String ATTR_SESSION_USAGE_UPDATE = "SESSION_USAGE_UPDATE";
    static final String ATTR_MULTI_PROMPT_SUM = "MULTI_PROMPT_SUM";
    AcpxUsage {
        if (measurementType == null || measurementType.isBlank()) {
            measurementType = PROVIDER_RUN_USAGE;
        }
        if (attribution == null) {
            attribution = "";
        }
        if (costCurrency == null) {
            costCurrency = "";
        }
        if (sessionCostCurrency == null) {
            sessionCostCurrency = "";
        }
        if (providerId == null) {
            providerId = "";
        }
        if (model == null) {
            model = "";
        }
        if (billingMode == null) {
            billingMode = "";
        }
        if (providerMetadataSource == null) {
            providerMetadataSource = "";
        }
        if (unavailableReason == null) {
            unavailableReason = "";
        }
    }

    static AcpxUsage unavailable(String reason) {
        return unavailable(reason, AcpxProviderMetadata.empty());
    }

    static AcpxUsage unavailable(String reason, AcpxProviderMetadata metadata) {
        return new AcpxUsage(
                0,
                0,
                0,
                0,
                0,
                null,
                "",
                "not_available",
                UNAVAILABLE,
                "",
                false,
                0,
                null,
                "",
                "",
                "",
                "",
                "",
                reason == null ? "" : reason
        ).withProviderMetadata(metadata);
    }

    AcpxUsage withProviderMetadata(AcpxProviderMetadata metadata) {
        if (metadata == null || metadata.isEmpty()) {
            return this;
        }
        return new AcpxUsage(
                inputTokens,
                outputTokens,
                cachedReadTokens,
                cachedWriteTokens,
                totalTokens,
                costAmount,
                costCurrency,
                source,
                measurementType,
                attribution,
                cumulative,
                contextUsedTokens,
                sessionCostAmount,
                sessionCostCurrency,
                firstNonBlank(providerId, metadata.providerId()),
                firstNonBlank(model, metadata.model()),
                firstNonBlank(billingMode, metadata.billingMode()),
                firstNonBlank(providerMetadataSource, metadata.source()),
                unavailableReason
        );
    }

    AcpxUsage withUnavailableReason(String reason) {
        return new AcpxUsage(
                inputTokens,
                outputTokens,
                cachedReadTokens,
                cachedWriteTokens,
                totalTokens,
                costAmount,
                costCurrency,
                source,
                measurementType,
                attribution,
                cumulative,
                contextUsedTokens,
                sessionCostAmount,
                sessionCostCurrency,
                providerId,
                model,
                billingMode,
                providerMetadataSource,
                reason == null ? "" : reason
        );
    }

    static AcpxUsage aggregatePromptOccurrences(AcpxUsage first, AcpxUsage second) {
        if (first == null) {
            return second;
        }
        if (second == null) {
            return first;
        }
        if (!PROVIDER_RUN_USAGE.equals(first.measurementType)
                || !PROVIDER_RUN_USAGE.equals(second.measurementType)
                || first.cumulative
                || second.cumulative
                || !first.providerId.equals(second.providerId)
                || !first.model.equals(second.model)
                || !first.billingMode.equals(second.billingMode)) {
            return second.withUnavailableReason("MULTI_PROMPT_USAGE_REQUIRES_OCCURRENCE_SUM");
        }
        var currency = first.costCurrency.equals(second.costCurrency) ? first.costCurrency : "";
        var cost = currency.isBlank() || first.costAmount == null || second.costAmount == null
                ? null
                : first.costAmount.add(second.costAmount);
        return new AcpxUsage(
                first.inputTokens + second.inputTokens,
                first.outputTokens + second.outputTokens,
                first.cachedReadTokens + second.cachedReadTokens,
                first.cachedWriteTokens + second.cachedWriteTokens,
                first.totalTokens + second.totalTokens,
                cost,
                currency,
                "agent_result_acquisition",
                PROVIDER_RUN_USAGE,
                ATTR_MULTI_PROMPT_SUM,
                false,
                second.contextUsedTokens,
                second.sessionCostAmount,
                second.sessionCostCurrency,
                second.providerId,
                second.model,
                second.billingMode,
                second.providerMetadataSource,
                ""
        );
    }

    private static String firstNonBlank(String current, String fallback) {
        return current == null || current.isBlank() ? (fallback == null ? "" : fallback) : current;
    }
}

package dev.dual.adapter.acpx;

import dev.dual.core.execution.AdapterSignal;
import dev.dual.core.execution.AdapterSignalType;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;

/**
 * Per-run health tracker for an acpx Agent execution.
 *
 * This object is deliberately stateful and must be created for one run only.
 * It consumes ordered runtime observations and turns them into the current
 * execution health. Post-run failure classification remains a separate concern:
 * completed runs can still be classified from final stdout/stderr, but mid-run
 * polling must not repeatedly consume historical diagnostics as current state.
 */
final class AgentExecutionHealth {
    private static final String STALLED_AGENT_OUTPUT =
            "agent process produced no observed progress before the progress timeout";

    private final AcpxFailureSignalCatalog signalCatalog;
    private final Duration recoverableSignalGrace;
    private final Duration progressStallTimeout;
    private final java.util.Set<String> escalatedPermissionKinds;

    private long lastConsumedSequence = -1;
    private long lastProgressSequence = -1;
    private Duration lastProgressAt = Duration.ZERO;
    private AcpxFailureSignal currentSignal;
    private AdapterSignal currentAdapterSignal;
    private Duration currentFailureSince = Duration.ZERO;
    private final List<AdapterSignal> observedSignals = new ArrayList<>();

    AgentExecutionHealth(AcpxFailureSignalCatalog signalCatalog, Duration recoverableSignalGrace) {
        this(signalCatalog, recoverableSignalGrace, recoverableSignalGrace);
    }

    AgentExecutionHealth(
            AcpxFailureSignalCatalog signalCatalog,
            Duration recoverableSignalGrace,
            Duration progressStallTimeout
    ) {
        this(signalCatalog, recoverableSignalGrace, progressStallTimeout, java.util.Set.of());
    }

    AgentExecutionHealth(
            AcpxFailureSignalCatalog signalCatalog,
            Duration recoverableSignalGrace,
            Duration progressStallTimeout,
            java.util.Collection<String> escalatedPermissionKinds
    ) {
        this.signalCatalog = signalCatalog;
        this.recoverableSignalGrace = recoverableSignalGrace;
        this.progressStallTimeout = progressStallTimeout;
        this.escalatedPermissionKinds = java.util.Set.copyOf(
                escalatedPermissionKinds == null ? java.util.Set.of() : escalatedPermissionKinds);
    }

    void observe(AgentLifecycleEvent event) {
        observe(event, Duration.ZERO);
    }

    void observe(AgentLifecycleEvent event, Duration elapsed) {
        if (event.sequence() <= lastConsumedSequence) {
            return;
        }
        lastConsumedSequence = event.sequence();
        switch (event.kind()) {
            case SESSION_NEW_CREATED, PROMPT_ACCEPTED, PROMPT_COMPLETED, TOOL_RESULT, USAGE_UPDATE -> {
                markProgress(event, elapsed);
                if (isReconnect(currentSignal)) {
                    supersedeCurrentSignal();
                }
            }
            case AGENT_ACTIVITY -> {
                markProgress(event, elapsed);
                // Plain stdout growth proves that bytes are still arriving, but it
                // is not a trusted lifecycle signal. A reconnect diagnostic is
                // superseded only by structured acpx stream progress or a
                // completed ACP prompt.
                if (event.source() == AgentLifecycleEvent.Source.ACPX_STREAM && isReconnect(currentSignal)) {
                    supersedeCurrentSignal();
                }
            }
            case SESSION_NEW_REQUESTED -> markProgress(event, elapsed);
            case PERMISSION_REQUESTED, PERMISSION_APPROVED -> markProgress(event, elapsed);
            case PERMISSION_DENIED, PERMISSION_CANCELLED -> observePermissionDecision(event);
            case SESSION_RESUME_FAILED, RECONNECT_SIGNAL, PROVIDER_FAILURE -> observeFailure(event, elapsed);
            case OTHER -> {
                // Other text is evidence, not lifecycle state.
            }
        }
    }

    Assessment assess(Duration elapsed) {
        if (currentSignal != null && currentSignal.recoverable()) {
            if (immediateFailure(currentSignal)
                    || elapsed.minus(currentFailureSince).compareTo(recoverableSignalGrace) >= 0) {
                return new Assessment(Status.RECOVERABLE_FAILURE, currentAdapterSignal, signals());
            }
            return new Assessment(Status.RECOVERING, currentAdapterSignal, signals());
        }
        if (elapsed.minus(lastProgressAt).compareTo(progressStallTimeout) >= 0) {
            var stalled = new AdapterSignal(
                    AdapterSignalType.PROCESS_STALLED,
                    STALLED_AGENT_OUTPUT,
                    Math.max(0, lastConsumedSequence + 1),
                    "health",
                    "",
                    false
            );
            return new Assessment(Status.RECOVERABLE_FAILURE, stalled, appendSignal(stalled));
        }
        if (lastProgressSequence >= 0) {
            return new Assessment(Status.HEALTHY, null, signals());
        }
        return new Assessment(Status.UNKNOWN, null, signals());
    }

    private void observeFailure(AgentLifecycleEvent event, Duration elapsed) {
        var evidenceText = event.source() == AgentLifecycleEvent.Source.ACPX_STREAM
                ? typedStreamErrorText(event.streamError())
                : event.text();
        if (evidenceText.isBlank()) {
            return;
        }
        var signal = signalCatalog.match(new AcpxFailureEvidence("", evidenceText, 4));
        if (signal.isEmpty()) {
            return;
        }
        var nextSignal = signal.get();
        if (currentSignal == null
                || nextSignal.priority() >= currentSignal.priority()
                || !sameReason(nextSignal, currentSignal)) {
            currentSignal = nextSignal;
            currentAdapterSignal = nextSignal.toAdapterSignal(event.sequence(), event.source().name().toLowerCase());
            observedSignals.add(currentAdapterSignal);
            currentFailureSince = elapsed;
        }
    }

    private void observePermissionDecision(AgentLifecycleEvent event) {
        var evidence = event.permissionEvidence();
        var escalationRequired = evidence != null && escalatedPermissionKinds.contains(evidence.toolKind());
        var disposition = event.kind() == AgentLifecycleEvent.Kind.PERMISSION_DENIED ? "denied" : "cancelled";
        var message = escalationRequired
                ? "current ACP turn permission requires human approval: " + event.text()
                : "current ACP turn permission " + disposition + ": " + event.text();
        observedSignals.add(new AdapterSignal(
                AdapterSignalType.PERMISSION_BLOCKED,
                message,
                event.sequence(),
                "acpx_stream",
                "",
                false
        ));
    }

    private void supersedeCurrentSignal() {
        if (currentAdapterSignal != null) {
            var superseded = new AdapterSignal(
                    currentAdapterSignal.type(),
                    currentAdapterSignal.message(),
                    currentAdapterSignal.observedSequence(),
                    currentAdapterSignal.source(),
                    currentAdapterSignal.sessionId(),
                    true
            );
            for (int index = observedSignals.size() - 1; index >= 0; index--) {
                if (observedSignals.get(index) == currentAdapterSignal) {
                    observedSignals.set(index, superseded);
                    break;
                }
            }
        }
        currentSignal = null;
        currentAdapterSignal = null;
    }

    private List<AdapterSignal> signals() {
        return List.copyOf(observedSignals);
    }

    private List<AdapterSignal> appendSignal(AdapterSignal signal) {
        var signals = new ArrayList<>(observedSignals);
        if (signals.stream().noneMatch(existing -> existing.type() == signal.type()
                && existing.observedSequence() == signal.observedSequence())) {
            signals.add(signal);
        }
        return List.copyOf(signals);
    }

    private String typedStreamErrorText(AcpxStreamEvidence.TypedError error) {
        return error == null
                ? ""
                : new AcpxStreamEvidence(java.util.List.of(error)).normalizedErrorText();
    }

    private void markProgress(AgentLifecycleEvent event, Duration elapsed) {
        lastProgressSequence = event.sequence();
        lastProgressAt = elapsed;
    }

    private boolean isReconnect(AcpxFailureSignal signal) {
        return signal != null && signal.reason() == AcpxFailureReason.AGENT_RECONNECT;
    }

    private boolean immediateFailure(AcpxFailureSignal signal) {
        return signal.reason() == AcpxFailureReason.AGENT_AUTH_FAILED
                || signal.reason() == AcpxFailureReason.AGENT_MODEL_MISMATCH
                || signal.reason() == AcpxFailureReason.AGENT_OVERLOADED;
    }

    private boolean sameReason(AcpxFailureSignal left, AcpxFailureSignal right) {
        return left.reason() == right.reason();
    }

    Duration lastProgressAt() {
        return lastProgressAt;
    }

    enum Status {
        UNKNOWN,
        HEALTHY,
        RECOVERING,
        RECOVERABLE_FAILURE
    }

    record Assessment(Status status, AdapterSignal signal, List<AdapterSignal> signals) {
        Assessment {
            signals = signals == null ? List.of() : List.copyOf(signals);
        }
    }
}

package dev.dual.adapter.acpx;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.runtime.handler.RepositoryFactBinding;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.HexFormat;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Writes execution-derived context governance evidence.
 *
 * The planned report is created before an agent run. This writer creates the
 * matching "actual" report after an acpx execution, using run telemetry as the
 * source of truth and keeping workflow routing untouched.
 */
final class ContextGovernanceActualReportWriter {
    private static final String WORKSTREAM_DIR = ".agent/workstreams";
    private static final String MEMORY_DIR = "memory";
    private static final String GOVERNANCE_DIR = "artifacts/context-governance";
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper()
            .registerModule(new JavaTimeModule())
            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
            .enable(SerializationFeature.INDENT_OUTPUT);

    Optional<Path> write(
            Path workspaceRoot,
            String workstreamId,
            String nodeDefinitionId,
            String runId,
            Path transcriptPath,
            AcpxToolUsage toolUsage,
            RepositoryFactBinding.Verified repositoryFactBinding
    ) throws IOException {
        return write(workspaceRoot, workstreamId, nodeDefinitionId, runId, null, transcriptPath, toolUsage,
                repositoryFactBinding);
    }

    Optional<Path> write(
            Path workspaceRoot,
            String workstreamId,
            String nodeDefinitionId,
            String runId,
            Path outputPath,
            Path transcriptPath,
            AcpxToolUsage toolUsage,
            RepositoryFactBinding.Verified repositoryFactBinding
    ) throws IOException {
        if (workspaceRoot == null || workstreamId == null || workstreamId.isBlank() || toolUsage == null) {
            return Optional.empty();
        }
        var workstreamDir = workspaceRoot.resolve(WORKSTREAM_DIR).resolve(workstreamId);
        if (!Files.isDirectory(workstreamDir)) {
            return Optional.empty();
        }
        var memoryDir = workstreamDir.resolve(MEMORY_DIR);
        if (repositoryFactBinding == null) {
            throw new IOException("repository fact binding is required for an actual governance report");
        }
        var bindingVerification = RepositoryFactBinding.verify(
                workspaceRoot,
                workstreamId,
                repositoryFactBinding.ref(),
                repositoryFactBinding.sha256(),
                repositoryFactBinding.document().nodeInstanceId(),
                runId,
                OBJECT_MAPPER);
        if (!bindingVerification.valid()) {
            throw new IOException("repository fact binding is invalid: " + bindingVerification.errors());
        }
        var binding = bindingVerification.verified();
        var plan = boundDocument(workspaceRoot, binding, "fileRelevancePlan");
        var policy = boundDocument(workspaceRoot, binding, "stageScopePolicy");
        var capabilityCatalog = boundDocument(workspaceRoot, binding, "agentCapabilityCatalog");
        var repoMap = boundDocument(workspaceRoot, binding, "repoMap");
        var plannedRead = textList(plan.map(doc -> doc.get("readCandidates")).orElse(null));
        var plannedWrite = firstNonEmpty(textList(plan.map(doc -> doc.get("writeCandidates")).orElse(null)),
                textList(policy.map(doc -> doc.get("writeScope")).orElse(null)));
        var actualRead = filterRepoFiles(toolUsage.readFiles());
        var actualDirectRead = filterRepoFiles(toolUsage.directReadFiles());
        var actualReadKinds = readKinds(repoMap.orElse(null), actualRead);
        var actualDirectReadKinds = readKinds(repoMap.orElse(null), actualDirectRead);
        var actualWrite = filterRepoFiles(toolUsage.writeFiles());
        var actualCapabilityUsages = ToolUsageCapabilityClassifier.classifyUsages(toolUsage, map(capabilityCatalog.orElse(null)));
        var actualCapabilities = actualCapabilityUsages.stream()
                .map(item -> textValue(item.get("kind")))
                .filter(kind -> !kind.isBlank())
                .distinct()
                .toList();
        var evidenceFiles = evidenceFiles(workstreamDir);
        var repeatedReadFiles = repeatedReads(workstreamDir, runId, actualRead, evidenceFiles);
        var report = new LinkedHashMap<String, Object>();
        report.put("schemaVersion", 1);
        report.put("artifactType", "context_governance_report");
        report.put("workstreamId", workstreamId);
        report.put("nodeDefinitionId", nodeDefinitionId);
        report.put("policyNodeDefinitionId", text(policy.map(doc -> doc.get("nodeDefinitionId")).orElse(null)));
        report.put("targetNodeDefinitionId", firstNonBlank(
                text(policy.map(doc -> doc.get("targetNodeDefinitionId")).orElse(null)),
                text(plan.map(doc -> doc.get("targetNodeDefinitionId")).orElse(null)),
                nodeDefinitionId
        ));
        report.put("nodeInstanceId", text(policy.map(doc -> doc.get("nodeInstanceId")).orElse(null)));
        report.put("iterationId", text(policy.map(doc -> doc.get("iterationId")).orElse(null)));
        report.put("stageId", text(policy.map(doc -> doc.get("stageId")).orElse(null)));
        report.put("runId", runId);
        report.put("repositoryFactBinding", binding.ref());
        report.put("repositoryFactBindingSha256", binding.sha256());
        report.put("inventoryHead", binding.document().inventoryHead());
        report.put("inventorySha256", binding.document().inventorySha256());
        report.put("inventoryPathCount", binding.document().inventoryPathCount());
        report.put("reportPhase", "actual");
        report.put("planningAvailable", plan.isPresent() || policy.isPresent());
        report.put("recommendedReadFiles", plannedRead);
        report.put("expectedWriteFiles", plannedWrite);
        report.put("actualReadFiles", actualRead);
        report.put("actualDirectReadFiles", actualDirectRead);
        report.put("actualReadEvidence", readEvidence(workspaceRoot, actualRead));
        report.put("actualReadFileKinds", actualReadKinds);
        report.put("actualDirectReadFileKinds", actualDirectReadKinds);
        report.put("actualCapabilityUsages", actualCapabilityUsages);
        report.put("actualWriteFiles", actualWrite);
        report.put("repeatedReadFiles", repeatedReadFiles);
        report.put("toolUsage", toolUsage);
        report.put("transcriptPath", relativeOrNull(workspaceRoot, transcriptPath));
        report.put("telemetryPending", false);
        report.put("generatedAt", Instant.now().toString());

        var outputDir = workstreamDir.resolve(GOVERNANCE_DIR);
        Files.createDirectories(outputDir);
        var fileName = safeFileName(nodeDefinitionId) + "-actual-" + safeFileName(runId) + ".json";
        var reportPath = outputDir.resolve(fileName);
        OBJECT_MAPPER.writeValue(reportPath.toFile(), report);
        writeMemoryMetrics(memoryDir, workstreamId, nodeDefinitionId, runId, plannedRead, actualRead, repeatedReadFiles);
        return Optional.of(reportPath);
    }

    private static void writeMemoryMetrics(
            Path memoryDir,
            String workstreamId,
            String nodeDefinitionId,
            String runId,
            List<String> plannedRead,
            List<String> actualRead,
            List<Map<String, Object>> repeatedReadFiles
    ) throws IOException {
        Files.createDirectories(memoryDir);
        var uniqueRead = new LinkedHashSet<>(actualRead);
        var planned = new LinkedHashSet<>(plannedRead);
        var repeatedReadCount = repeatedReadFiles.size();
        var allowedRepeatedReadCount = repeatedReadFiles.stream()
                .filter(item -> Boolean.TRUE.equals(item.get("evidenceKnown")))
                .count();
        var workingSetHitCount = actualRead.stream().filter(planned::contains).count();

        var document = new LinkedHashMap<String, Object>();
        document.put("schemaVersion", 1);
        document.put("artifactType", "memory_metrics");
        document.put("workstreamId", workstreamId);
        document.put("nodeDefinitionId", nodeDefinitionId);
        document.put("runId", runId);
        document.put("readCount", actualRead.size());
        document.put("uniqueReadCount", uniqueRead.size());
        document.put("repeatedReadCount", repeatedReadCount);
        document.put("allowedRepeatedReadCount", allowedRepeatedReadCount);
        document.put("unexplainedRepeatedReadCount", Math.max(0, repeatedReadCount - (int) allowedRepeatedReadCount));
        document.put("workingSetHitCount", workingSetHitCount);
        document.put("workingSetHitRate", actualRead.isEmpty() ? 0.0 : (double) workingSetHitCount / actualRead.size());
        document.put("generatedAt", Instant.now().toString());
        OBJECT_MAPPER.writeValue(memoryDir.resolve("memory-metrics.json").toFile(), document);
    }

    private static Optional<JsonNode> boundDocument(
            Path workspaceRoot,
            RepositoryFactBinding.Verified binding,
            String artifactName
    ) throws IOException {
        var artifact = binding.document().artifacts().get(artifactName);
        if (artifact == null) {
            return Optional.empty();
        }
        var path = workspaceRoot.toAbsolutePath().normalize().resolve(artifact.ref()).normalize();
        return Optional.of(OBJECT_MAPPER.readTree(path.toFile()));
    }

    private static Map<String, String> readKinds(JsonNode repoMap, List<String> actualReadFiles) {
        if (repoMap == null || actualReadFiles == null || actualReadFiles.isEmpty()) {
            return Map.of();
        }
        var byPath = new LinkedHashMap<String, String>();
        var files = repoMap.get("files");
        if (files != null && files.isArray()) {
            for (var item : files) {
                var path = normalize(text(item.get("path")));
                var kind = text(item.get("kind"));
                if (!path.isBlank() && !kind.isBlank()) {
                    byPath.put(path, kind);
                }
            }
        }
        var result = new LinkedHashMap<String, String>();
        for (var path : actualReadFiles) {
            var normalized = normalize(path);
            var kind = byPath.get(normalized);
            if (kind != null && !kind.isBlank()) {
                result.put(normalized, kind);
            }
        }
        return Map.copyOf(result);
    }

    private static List<Map<String, Object>> readEvidence(Path workspaceRoot, List<String> actualReadFiles)
            throws IOException {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var evidence = new ArrayList<Map<String, Object>>();
        for (var ref : actualReadFiles) {
            var path = root.resolve(ref).normalize();
            if (!path.startsWith(root) || !Files.isRegularFile(path)) {
                continue;
            }
            evidence.add(Map.of(
                    "path", normalize(ref),
                    "sha256", sha256(path),
                    "sizeBytes", Files.size(path)
            ));
        }
        return List.copyOf(evidence);
    }

    private static String sha256(Path path) throws IOException {
        try {
            var digest = MessageDigest.getInstance("SHA-256");
            digest.update(Files.readAllBytes(path));
            return HexFormat.of().formatHex(digest.digest());
        } catch (NoSuchAlgorithmException impossible) {
            throw new IOException("SHA-256 is unavailable", impossible);
        }
    }

    private static List<String> textList(JsonNode node) {
        if (node == null || !node.isArray()) {
            return List.of();
        }
        var values = new LinkedHashSet<String>();
        for (var item : node) {
            var text = text(item);
            if (!text.isBlank()) {
                values.add(text);
            }
        }
        return List.copyOf(values);
    }

    private static List<String> firstNonEmpty(List<String> first, List<String> second) {
        return first.isEmpty() ? second : first;
    }

    private static String firstNonBlank(String first, String second, String fallback) {
        if (first != null && !first.isBlank()) {
            return first;
        }
        if (second != null && !second.isBlank()) {
            return second;
        }
        return fallback == null ? "" : fallback;
    }

    private static List<String> filterRepoFiles(List<String> files) {
        if (files == null || files.isEmpty()) {
            return List.of();
        }
        var values = new LinkedHashSet<String>();
        for (var file : files) {
            var normalized = normalize(file);
            if (isRepoEvidenceFile(normalized)) {
                values.add(normalized);
            }
        }
        return List.copyOf(values);
    }

    private List<Map<String, Object>> repeatedReads(
            Path workstreamDir,
            String currentRunId,
            List<String> actualRead,
            List<String> evidenceFiles
    ) throws IOException {
        if (actualRead.isEmpty()) {
            return List.of();
        }
        var previousCounts = previousReadCounts(workstreamDir, currentRunId);
        var evidence = new LinkedHashSet<>(evidenceFiles);
        var repeated = new ArrayList<Map<String, Object>>();
        for (var path : actualRead) {
            var count = previousCounts.getOrDefault(path, 0);
            if (count <= 0) {
                continue;
            }
            var item = new LinkedHashMap<String, Object>();
            item.put("path", path);
            item.put("previousCount", count);
            item.put("evidenceKnown", evidence.contains(path));
            repeated.add(item);
        }
        return List.copyOf(repeated);
    }

    private Map<String, Integer> previousReadCounts(Path workstreamDir, String currentRunId) throws IOException {
        var runsDir = workstreamDir.resolve("runs");
        if (!Files.isDirectory(runsDir)) {
            return Map.of();
        }
        var counts = new LinkedHashMap<String, Integer>();
        try (var stream = Files.list(runsDir)) {
            for (var runDir : stream.filter(Files::isDirectory).sorted(Comparator.comparing(path -> path.getFileName().toString())).toList()) {
                if (runDir.getFileName().toString().equals(currentRunId)) {
                    continue;
                }
                var runJson = runDir.resolve("run.json");
                if (!Files.isRegularFile(runJson)) {
                    continue;
                }
                var run = OBJECT_MAPPER.readTree(runJson.toFile());
                for (var file : textList(run.path("toolUsage").path("readFiles"))) {
                    var normalized = normalize(file);
                    if (isRepoEvidenceFile(normalized)) {
                        counts.merge(normalized, 1, Integer::sum);
                    }
                }
            }
        }
        return counts;
    }

    private static List<String> evidenceFiles(Path workstreamDir) throws IOException {
        var manifest = workstreamDir.resolve("memory").resolve("evidence-manifest.json");
        if (!Files.isRegularFile(manifest)) {
            return List.of();
        }
        var files = new LinkedHashSet<String>();
        var document = OBJECT_MAPPER.readTree(manifest.toFile());
        for (var item : document.path("items")) {
            for (var file : textList(item.path("files"))) {
                var normalized = normalize(file);
                if (isRepoEvidenceFile(normalized)) {
                    files.add(normalized);
                }
            }
        }
        return List.copyOf(files);
    }

    private static boolean isRepoEvidenceFile(String normalized) {
        return !normalized.isBlank()
                && !normalized.startsWith(".agent/")
                && !normalized.startsWith(".git/")
                && !normalized.startsWith("/Users/")
                && !normalized.startsWith("/private/");
    }

    private static String normalize(String value) {
        var text = value == null ? "" : value.trim();
        while (text.startsWith("./")) {
            text = text.substring(2);
        }
        return text;
    }

    private static String text(JsonNode node) {
        if (node == null || node.isNull()) {
            return "";
        }
        return node.asText("");
    }

    private static String textValue(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> map(JsonNode node) {
        if (node == null || node.isNull()) {
            return Map.of();
        }
        return OBJECT_MAPPER.convertValue(node, Map.class);
    }

    private static String relativeOrNull(Path workspaceRoot, Path path) {
        if (workspaceRoot == null || path == null) {
            return null;
        }
        try {
            return workspaceRoot.toAbsolutePath().normalize().relativize(path.toAbsolutePath().normalize()).toString();
        } catch (RuntimeException ignored) {
            return path.toString();
        }
    }

    private static String safeFileName(String value) {
        var text = value == null || value.isBlank() ? "unknown" : value;
        return text.replaceAll("[^A-Za-z0-9._-]", "_");
    }
}

package dev.dual.adapter.acpx;

import dev.dual.core.execution.AgentExecutionTimelineEventKind;

import java.time.Duration;
import java.time.Instant;
import java.util.Map;

public record AcpxExecutionEvent(
        AgentExecutionTimelineEventKind kind,
        String source,
        long sequence,
        Instant observedAt,
        long elapsedMs,
        Map<String, Object> details
) {
    public AcpxExecutionEvent {
        if (kind == null) {
            throw new IllegalArgumentException("kind is required");
        }
        source = source == null ? "" : source;
        if (observedAt == null) {
            throw new IllegalArgumentException("observedAt is required");
        }
        if (elapsedMs < 0) {
            throw new IllegalArgumentException("elapsedMs must be non-negative");
        }
        details = details == null ? Map.of() : Map.copyOf(details);
    }

    public AcpxExecutionEvent(
            AgentExecutionTimelineEventKind kind,
            String source,
            long sequence,
            Instant observedAt,
            long elapsedMs
    ) {
        this(kind, source, sequence, observedAt, elapsedMs, Map.of());
    }

    static AcpxExecutionEvent now(AgentExecutionTimelineEventKind kind, String source, long sequence, Instant startedAt) {
        return now(kind, source, sequence, startedAt, Map.of());
    }

    static AcpxExecutionEvent now(
            AgentExecutionTimelineEventKind kind,
            String source,
            long sequence,
            Instant startedAt,
            Map<String, Object> details
    ) {
        var now = Instant.now();
        return new AcpxExecutionEvent(kind, source, sequence, now, Duration.between(startedAt, now).toMillis(), details);
    }

    Map<String, Object> toMap() {
        if (details.isEmpty()) {
            return Map.of(
                "kind", kind.wireName(),
                "source", source,
                "sequence", sequence,
                "observedAt", observedAt.toString(),
                "elapsedMs", elapsedMs
            );
        }
        return Map.of(
                "kind", kind.wireName(),
                "source", source,
                "sequence", sequence,
                "observedAt", observedAt.toString(),
                "elapsedMs", elapsedMs,
                "details", details
        );
    }
}

package dev.dual.adapter.acpx;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import dev.dual.core.id.DualId;
import dev.dual.ledger.file.ExecutionNetworkGrantStore;
import dev.dual.ledger.file.WorkstreamPaths;

final class ClaudeExecutionPolicy {
    static final String SCHEMA = "claude_execution_policy.v2";
    static final String NETWORK_TRANSPORT_OWNER = "claude_sandbox";
    private static final List<String> PROVIDER_DENIED_ENV_NAMES = List.of(
            "ANTHROPIC_API_KEY",
            "ANTHROPIC_AUTH_TOKEN",
            "ANTHROPIC_BASE_URL"
    );
    private static final ObjectMapper MAPPER = new ObjectMapper()
            .enable(SerializationFeature.INDENT_OUTPUT)
            .enable(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS);

    private ClaudeExecutionPolicy() {
    }

    static Binding write(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            String runId,
            Path runDir
    ) throws IOException {
        return write(workspaceRoot, workstreamId, nodeInstanceId, runId, runDir, false, false, null);
    }

    static Binding write(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            String runId,
            Path runDir,
            AcpxPermissionProfile permissionProfile
    ) throws IOException {
        if (permissionProfile == null) {
            throw new IllegalArgumentException("permissionProfile is required");
        }
        return write(
                workspaceRoot,
                workstreamId,
                nodeInstanceId,
                runId,
                runDir,
                permissionProfile.allowsLocalBinding(), permissionProfile.autoAllowsSandboxedBash(), null);
    }

    static Binding write(Path workspaceRoot, String workstreamId, String nodeInstanceId, String runId,
                         Path runDir, AcpxPermissionProfile profile, ExecutionNetworkGrantStore.Claim claim) throws IOException {
        if (profile == null || claim != null && !profile.allowsLocalBinding()) {
            throw new IOException("network grant requires implement profile");
        }
        if (claim != null) new ExecutionNetworkGrantStore().verifyClaim(
                new WorkstreamPaths(workspaceRoot.toRealPath(), new DualId(workstreamId)), claim, nodeInstanceId, runId);
        return write(workspaceRoot, workstreamId, nodeInstanceId, runId, runDir,
                profile.allowsLocalBinding(), profile.autoAllowsSandboxedBash(), claim);
    }

    private static Binding write(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            String runId,
            Path runDir,
            boolean allowLocalBinding,
            boolean autoAllowSandboxedBash,
            ExecutionNetworkGrantStore.Claim claim
    ) throws IOException {
        var root = workspaceRoot.toRealPath();
        var realRunDir = runDir.toRealPath();
        if (!realRunDir.startsWith(root)) {
            throw new IOException("Claude execution policy run directory is outside workspace");
        }
        var scratch = Path.of(System.getProperty("java.io.tmpdir")).toRealPath();
        var policyPath = runDir.resolve("execution-authority").resolve("claude-execution-policy.json");
        Files.createDirectories(policyPath.getParent());

        var network = new LinkedHashMap<String, Object>();
        network.put("strict_allowlist", true);
        network.put("allowed_domains", claim == null ? List.of() : claim.domains());
        network.put("allow_local_binding", allowLocalBinding);
        network.put("allow_unix_sockets", List.of());

        var filesystem = new LinkedHashMap<String, Object>();
        filesystem.put("allow_read", List.of(root.toString(), scratch.toString()));
        filesystem.put("allow_write", List.of(root.toString(), scratch.toString()));
        filesystem.put("deny_read", List.of());
        var controlRoot = root.resolve(".agent/workstreams").resolve(requireIdentifier(workstreamId, "workstreamId"));
        filesystem.put("deny_write", List.of(controlRoot.resolve("nodes").toString(),
                controlRoot.resolve("execution-authority").toString()));

        var sandbox = new LinkedHashMap<String, Object>();
        sandbox.put("enabled", true);
        sandbox.put("fail_if_unavailable", true);
        sandbox.put("allow_unsandboxed_commands", false);
        sandbox.put("auto_allow_sandboxed_bash", autoAllowSandboxedBash);
        sandbox.put("network", network);
        sandbox.put("filesystem", filesystem);

        var document = new LinkedHashMap<String, Object>();
        document.put("schema_version", SCHEMA);
        document.put("workstream_id", requireIdentifier(workstreamId, "workstreamId"));
        document.put("node_instance_id", requireIdentifier(nodeInstanceId, "nodeInstanceId"));
        document.put("run_id", requireIdentifier(runId, "runId"));
        document.put("network_transport_owner", NETWORK_TRANSPORT_OWNER);
        document.put("setting_sources", List.of());
        document.put("sandbox", sandbox);
        document.put("provider_subprocess_denied_env_names", PROVIDER_DENIED_ENV_NAMES);
        document.put("generated_at", Instant.now().toString());

        var bytes = MAPPER.writeValueAsBytes(document);
        writeAtomically(policyPath, bytes);
        var ref = root.relativize(policyPath.toRealPath()).toString();
        var binding = new Binding(ref, sha256(bytes), workstreamId, nodeInstanceId, runId, claim);
        binding.verify(root);
        return binding;
    }

    record Binding(
            String ref,
            String sha256,
            String workstreamId,
            String nodeInstanceId,
            String runId,
            ExecutionNetworkGrantStore.Claim networkGrant
    ) {
        Binding(String ref, String sha256, String workstreamId, String nodeInstanceId, String runId) {
            this(ref, sha256, workstreamId, nodeInstanceId, runId, null);
        }
        Binding {
            requireText(ref, "policy ref");
            if (!sha256.matches("[a-f0-9]{64}")) {
                throw new IllegalArgumentException("policy SHA-256 is invalid");
            }
            requireIdentifier(workstreamId, "workstreamId");
            requireIdentifier(nodeInstanceId, "nodeInstanceId");
            requireIdentifier(runId, "runId");
        }

        void verify(Path workspaceRoot) throws IOException {
            var root = workspaceRoot.toRealPath();
            var resolved = root.resolve(ref).normalize();
            if (!resolved.startsWith(root) || !Files.isRegularFile(resolved)) {
                throw new IOException("Claude execution policy is missing or outside workspace");
            }
            var realPolicy = resolved.toRealPath();
            if (!realPolicy.startsWith(root)) {
                throw new IOException("Claude execution policy resolves outside workspace");
            }
            var bytes = Files.readAllBytes(realPolicy);
            if (!sha256.equals(ClaudeExecutionPolicy.sha256(bytes))) {
                throw new IOException("Claude execution policy SHA-256 mismatch");
            }
            Map<String, Object> document = MAPPER.readValue(bytes, new TypeReference<>() {
            });
            requireEquals(document, "schema_version", SCHEMA);
            requireEquals(document, "workstream_id", workstreamId);
            requireEquals(document, "node_instance_id", nodeInstanceId);
            requireEquals(document, "run_id", runId);
            requireEquals(document, "network_transport_owner", NETWORK_TRANSPORT_OWNER);
            if (networkGrant != null) new ExecutionNetworkGrantStore().verifyClaim(
                    new WorkstreamPaths(root, new DualId(workstreamId)), networkGrant, nodeInstanceId, runId);
        }

        Map<String, Object> metadata(String disposition) {
            var metadata = new LinkedHashMap<String, Object>(Map.of(
                    "schema", SCHEMA,
                    "policyRef", ref,
                    "policySha256", sha256,
                    "transportDisposition", disposition
            ));
            if (networkGrant != null) metadata.put("networkGrant", networkGrant.metadata());
            return Map.copyOf(metadata);
        }
    }

    private static void requireEquals(Map<String, Object> document, String key, String expected) throws IOException {
        if (!expected.equals(document.get(key))) {
            throw new IOException("Claude execution policy lineage mismatch: " + key);
        }
    }

    private static String requireIdentifier(String value, String label) {
        requireText(value, label);
        if (!value.matches("[A-Za-z0-9._-]+")) {
            throw new IllegalArgumentException(label + " must be a canonical identifier");
        }
        return value;
    }

    private static void requireText(String value, String label) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(label + " is required");
        }
    }

    private static String sha256(byte[] bytes) {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
        } catch (NoSuchAlgorithmException impossible) {
            throw new IllegalStateException(impossible);
        }
    }

    private static void writeAtomically(Path path, byte[] bytes) throws IOException {
        var temp = path.resolveSibling(path.getFileName() + ".tmp");
        Files.write(temp, bytes);
        try {
            Files.move(temp, path, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        } catch (java.nio.file.AtomicMoveNotSupportedException ignored) {
            Files.move(temp, path, StandardCopyOption.REPLACE_EXISTING);
        }
    }
}

package dev.dual.adapter.acpx;

/**
 * The external runner path an acpx agent node actually uses, derived from the
 * node's agent + permission_profile. This is the execution-boundary semantic a
 * preflight probe must match: a native {@code claude --print} probe proves only
 * the runner. The workflow runtime uses acpx sessions for Claude and Codex;
 * native Claude is not a workflow runner kind.
 *
 * <p>dual does not own Claude Code / Codex model selection; it owns matching the
 * probe to the actual runner and attributing usage from whatever the runner
 * returns. The map from (agent, permission_profile) to runner kind lives here
 * not in CLI if-else or bash.
 */
public enum AgentRunnerKind {
    ACPX_CLAUDE_SESSION("acpx_claude_session"),
    ACPX_CODEX_SESSION("acpx_codex_session"),
    UNKNOWN("unknown");

    private final String wire;

    AgentRunnerKind(String wire) {
        this.wire = wire;
    }

    public String wire() {
        return wire;
    }

    /**
     * Resolve the runner kind from a node's agent + permission_profile.
     *
 * <p>{@code codex} → acpx codex session; {@code claude} + a supported profile
 * ({@code contract_discovery}/{@code observe}/{@code review}/{@code implement}/blank)
 * → acpx claude session; anything unresolved (unknown agent, unsupported
 * profile) → {@link #UNKNOWN}. Never throws.
     */
    public static AgentRunnerKind from(String agent, String permissionProfile) {
        if ("codex".equals(agent)) {
            return ACPX_CODEX_SESSION;
        }
        if ("claude".equals(agent)) {
            try {
                AcpxPermissionProfile.fromName(permissionProfile, false);
                return ACPX_CLAUDE_SESSION;
            } catch (RuntimeException ignored) {
                return UNKNOWN;
            }
        }
        return UNKNOWN;
    }
}

package dev.dual.adapter.acpx;

/**
 * One ordered runtime observation from an Agent execution.
 *
 * The sequence is the authoritative ordering because acpx stdout/stderr and
 * session stream lines do not provide stable timestamps. Wall-clock time is
 * useful for diagnostics, but execution health must be derived from consumed
 * event order plus the polling elapsed time.
 */
record AgentLifecycleEvent(
        long sequence,
        Source source,
        Kind kind,
        String text,
        AcpxStreamEvidence.TypedError streamError,
        PermissionEvidence permissionEvidence
) {
    static AgentLifecycleEvent stderrLine(long sequence, String text) {
        return textLine(sequence, Source.STDERR, text);
    }

    static AgentLifecycleEvent stdoutLine(long sequence, String text) {
        return textLine(sequence, Source.STDOUT, text);
    }

    static AgentLifecycleEvent sessionNewRequested(long sequence) {
        return streamEvent(sequence, Kind.SESSION_NEW_REQUESTED, null);
    }

    static AgentLifecycleEvent sessionNewCreated(long sequence) {
        return streamEvent(sequence, Kind.SESSION_NEW_CREATED, null);
    }

    static AgentLifecycleEvent promptAccepted(long sequence) {
        return streamEvent(sequence, Kind.PROMPT_ACCEPTED, null);
    }

    static AgentLifecycleEvent promptCompleted(long sequence) {
        return streamEvent(sequence, Kind.PROMPT_COMPLETED, null);
    }

    static AgentLifecycleEvent usageUpdate(long sequence) {
        return streamEvent(sequence, Kind.USAGE_UPDATE, null);
    }

    static AgentLifecycleEvent agentActivity(long sequence) {
        return streamEvent(sequence, Kind.AGENT_ACTIVITY, null);
    }

    static AgentLifecycleEvent sessionResumeFailed(long sequence, AcpxStreamEvidence.TypedError error) {
        return streamEvent(sequence, Kind.SESSION_RESUME_FAILED, error);
    }

    static AgentLifecycleEvent providerFailure(long sequence, AcpxStreamEvidence.TypedError error) {
        return streamEvent(sequence, Kind.PROVIDER_FAILURE, error);
    }

    static AgentLifecycleEvent permissionRequested(long sequence, PermissionEvidence evidence) {
        return permissionEvent(sequence, Kind.PERMISSION_REQUESTED, evidence);
    }

    static AgentLifecycleEvent permissionApproved(long sequence, PermissionEvidence evidence) {
        return permissionEvent(sequence, Kind.PERMISSION_APPROVED, evidence);
    }

    static AgentLifecycleEvent permissionDenied(long sequence, PermissionEvidence evidence) {
        return permissionEvent(sequence, Kind.PERMISSION_DENIED, evidence);
    }

    static AgentLifecycleEvent permissionCancelled(long sequence, PermissionEvidence evidence) {
        return permissionEvent(sequence, Kind.PERMISSION_CANCELLED, evidence);
    }

    private static AgentLifecycleEvent textLine(long sequence, Source source, String text) {
        return new AgentLifecycleEvent(sequence, source, classifyText(source, text), text == null ? "" : text, null, null);
    }

    private static AgentLifecycleEvent streamEvent(
            long sequence,
            Kind kind,
            AcpxStreamEvidence.TypedError error
    ) {
        return streamEvent(sequence, kind, "", error);
    }

    private static AgentLifecycleEvent streamEvent(
            long sequence,
            Kind kind,
            String text,
            AcpxStreamEvidence.TypedError error
    ) {
        return new AgentLifecycleEvent(sequence, Source.ACPX_STREAM, kind, text == null ? "" : text, error, null);
    }

    private static AgentLifecycleEvent permissionEvent(long sequence, Kind kind, PermissionEvidence evidence) {
        var normalized = evidence == null ? PermissionEvidence.EMPTY : evidence;
        return new AgentLifecycleEvent(
                sequence,
                Source.ACPX_STREAM,
                kind,
                normalized.summary(),
                null,
                normalized
        );
    }

    /** Wrapper stdout/stderr compatibility only; ACP stream lines are decoded structurally. */
    private static Kind classifyText(Source source, String text) {
        var lower = text == null ? "" : text.toLowerCase();
        var trimmed = lower.stripLeading();
        if (source == Source.STDERR && lower.contains("agent needs reconnect")) {
            return Kind.RECONNECT_SIGNAL;
        }
        if (source == Source.STDERR && (lower.contains("api error:")
                || lower.contains("failed to authenticate")
                || lower.contains("unable to connect to api"))) {
            return Kind.PROVIDER_FAILURE;
        }
        if ((source == Source.STDOUT || source == Source.STDERR) && (trimmed.startsWith("[error]")
                || trimmed.startsWith("runtime:")
                || trimmed.startsWith("no acpx session found"))) {
            return Kind.PROVIDER_FAILURE;
        }
        if (sourceLikeWrapperActivity(lower)) {
            return Kind.AGENT_ACTIVITY;
        }
        return Kind.OTHER;
    }

    private static boolean sourceLikeWrapperActivity(String lower) {
        return lower.contains("[thinking]")
                || lower.contains("[assistant]")
                || lower.contains("[tool]");
    }

    enum Source {
        STDOUT,
        STDERR,
        ACPX_STREAM
    }

    record PermissionEvidence(
            String toolCallId,
            String toolKind,
            String toolName,
            String title,
            String resource,
            java.util.List<String> requestedOptions,
            String disposition
    ) {
        static final PermissionEvidence EMPTY = new PermissionEvidence(
                "", "", "", "", "", java.util.List.of(), "UNAVAILABLE");

        PermissionEvidence {
            toolCallId = toolCallId == null ? "" : toolCallId;
            toolKind = toolKind == null ? "" : toolKind;
            toolName = toolName == null ? "" : toolName;
            title = title == null ? "" : title;
            resource = resource == null ? "" : resource;
            requestedOptions = requestedOptions == null ? java.util.List.of() : java.util.List.copyOf(requestedOptions);
            disposition = disposition == null ? "UNAVAILABLE" : disposition;
        }

        PermissionEvidence withDisposition(String value) {
            return new PermissionEvidence(toolCallId, toolKind, toolName, title, resource, requestedOptions, value);
        }

        String summary() {
            if (!title.isBlank() && !resource.isBlank()) {
                return title + ": " + resource;
            }
            return !resource.isBlank() ? resource : (!title.isBlank() ? title : "permission request");
        }
    }

    enum Kind {
        OTHER,
        AGENT_ACTIVITY,
        SESSION_RESUME_FAILED,
        SESSION_NEW_REQUESTED,
        SESSION_NEW_CREATED,
        PROMPT_ACCEPTED,
        PROMPT_COMPLETED,
        PERMISSION_REQUESTED,
        PERMISSION_APPROVED,
        PERMISSION_DENIED,
        PERMISSION_CANCELLED,
        TOOL_RESULT,
        USAGE_UPDATE,
        RECONNECT_SIGNAL,
        PROVIDER_FAILURE
    }
}

package dev.dual.adapter.acpx;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Classifies observed tool usage into capability kinds declared by the
 * orchestrator capability catalog. Provider names come from the catalog; this
 * class does not know about concrete tools such as rtk/codegraph/gitnexus.
 */
final class ToolUsageCapabilityClassifier {
    private ToolUsageCapabilityClassifier() {
    }

    static List<String> classify(AcpxToolUsage toolUsage, Map<String, Object> capabilityCatalog) {
        return classifyUsages(toolUsage, capabilityCatalog).stream()
                .map(item -> text(item.get("kind")))
                .filter(kind -> !kind.isBlank())
                .distinct()
                .toList();
    }

    static List<Map<String, Object>> classifyUsages(AcpxToolUsage toolUsage, Map<String, Object> capabilityCatalog) {
        if (toolUsage == null) {
            return List.of();
        }
        var usages = new ArrayList<Map<String, Object>>();
        for (var capability : capabilities(capabilityCatalog)) {
            var kind = text(capability.get("kind"));
            var provider = text(capability.get("provider"));
            if (kind.isBlank() || provider.isBlank()) {
                continue;
            }
            var source = providerUsed(toolUsage, provider);
            if (!source.isBlank()) {
                usages.add(Map.of(
                        "kind", kind,
                        "provider", provider,
                        "source", source
                ));
                continue;
            }
        }
        return List.copyOf(usages);
    }

    private static String providerUsed(AcpxToolUsage toolUsage, String provider) {
        var normalizedProvider = normalizeToken(provider);
        if (normalizedProvider.isBlank()) {
            return "";
        }
        for (var toolId : toolUsage.toolIds()) {
            if (normalizeToken(toolId).equals(normalizedProvider)) {
                return "tool_id";
            }
        }
        for (var executable : toolUsage.commandExecutables()) {
            if (normalizeToken(executable).equals(normalizedProvider)) {
                return "command_executable";
            }
        }
        return "";
    }

    private static String normalizeToken(Object value) {
        var text = text(value).toLowerCase(Locale.ROOT);
        while (text.startsWith("./")) {
            text = text.substring(2);
        }
        var slash = text.lastIndexOf('/');
        return slash >= 0 ? text.substring(slash + 1) : text;
    }

    private static List<Map<String, Object>> capabilities(Map<String, Object> catalog) {
        if (catalog == null || !(catalog.get("capabilities") instanceof List<?> raw)) {
            return List.of();
        }
        var result = new ArrayList<Map<String, Object>>();
        for (var item : raw) {
            if (item instanceof Map<?, ?> map) {
                var copy = new java.util.LinkedHashMap<String, Object>();
                for (var entry : map.entrySet()) {
                    if (entry.getKey() instanceof String key) {
                        copy.put(key, entry.getValue());
                    }
                }
                result.add(copy);
            }
        }
        return List.copyOf(result);
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }
}

package dev.dual.adapter.acpx;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.domain.PromptLanguage;
import dev.dual.runtime.handler.AgentEvidenceIndex;
import dev.dual.runtime.handler.AgentOutputContractDocument;
import dev.dual.runtime.handler.ContractRegistry;
import dev.dual.runtime.handler.AgentResultPromptContract;
import dev.dual.runtime.handler.TypedContextPayloadBoundary;
import dev.dual.runtime.handler.TaskContractProposalReference;
import dev.dual.runtime.handler.AgentRunGovernanceContext;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;

final class AgentPromptRenderer {
    private static final String TEMPLATE_ROOT = "dev/dual/adapter/acpx/prompts/";
    private static final String PRINCIPLE_TEMPLATE_ROOT = "dev/dual/adapter/acpx/templates/";
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();
    private static final Set<String> KNOWN_VARIABLES = Set.of(
            "workstream_id", "run_id", "node_id", "prompt_template",
            "ledger_path", "requirement", "context_package",
            "contract_review_principles", "allowed_decisions",
            "required_control_keys", "decision_example", "agent_result_contract"
    );
    private static final Pattern VARIABLE_PATTERN = Pattern.compile("\\{\\{([a-z_]+)}}");
    private static final Pattern ABSOLUTE_PATH_PATTERN = Pattern.compile(
            "(?<![<\\p{Alnum}._-])(/[^\\s\"'`)]+)",
            Pattern.UNICODE_CHARACTER_CLASS);

    String render(Path workspaceRoot, String workstreamId, String nodeId, String promptTemplate, List<String> inputRefs) {
        return renderWithSections(workspaceRoot, workstreamId, "", nodeId, promptTemplate, inputRefs).content();
    }

    /**
     * Same final prompt as {@link #render}, plus section provenance for prompt manifests.
     * Provenance records source metadata only and must not change prompt content.
     */
    RenderedPrompt renderWithSections(Path workspaceRoot, String workstreamId, String nodeId, String promptTemplate, List<String> inputRefs) {
        return renderWithSections(workspaceRoot, workstreamId, "", nodeId, promptTemplate, inputRefs);
    }

    RenderedPrompt renderWithSections(
            Path workspaceRoot,
            String workstreamId,
            String runId,
            String nodeId,
            String promptTemplate,
            List<String> inputRefs
    ) {
        return renderWithSections(
                workspaceRoot, workstreamId, runId, nodeId, promptTemplate, inputRefs, null);
    }

    RenderedPrompt renderWithSections(
            Path workspaceRoot,
            String workstreamId,
            String runId,
            String nodeId,
            String promptTemplate,
            List<String> inputRefs,
            String agentResultContract
    ) {
        return renderWithSections(
                workspaceRoot, workstreamId, runId, nodeId, promptTemplate, inputRefs,
                agentResultContract, null);
    }

    RenderedPrompt renderWithSections(
            Path workspaceRoot,
            String workstreamId,
            String runId,
            String nodeId,
            String promptTemplate,
            List<String> inputRefs,
            String agentResultContract,
            String trustedTaskContractPayload
    ) {
        var template = loadTemplate(promptTemplate);
        if (agentResultContract == null) {
            var contract = promptContract(nodeId);
            agentResultContract = AgentResultPromptContract.render(
                    workstreamId, runId, nodeId, contract.decisionExample(),
                    contract.allowedDecisionValues());
        }
        var workstreamDir = ".agent/workstreams/" + workstreamId;
        var requirementPath = workspaceRoot.resolve(workstreamDir).resolve("requirement.md");
        var requirement = readIfExists(requirementPath);
        var languagePolicy = languagePolicy(workspaceRoot.resolve(workstreamDir), requirement);
        var contextPackage = contextPackageSection(
                workspaceRoot, workstreamId, nodeId, inputRefs, trustedTaskContractPayload);
        var contractReviewPrinciples = principleTemplate(workspaceRoot, "contract-review-principles.md");
        var promptContract = promptContract(nodeId);
        var workspaceGuard = workspaceGuard(workspaceRoot, nodeId);
        var structuredArtifactFieldSemantics = structuredArtifactFieldSemantics(nodeId);
        var readReuseContractSection = readReuseContractSection(workspaceRoot, workstreamId, inputRefs);
        var hasInputs = inputRefs != null && !inputRefs.isEmpty();

        var content = workspaceGuard + "\n\n" + languagePolicy + "\n\n"
                + structuredArtifactFieldSemantics + "\n\n" + template
                .replace("{{workstream_id}}", workstreamId)
                .replace("{{run_id}}", runId)
                .replace("{{node_id}}", nodeId)
                .replace("{{prompt_template}}", promptTemplate)
                .replace("{{ledger_path}}", workstreamDir)
                .replace("{{requirement}}", requirement)
                .replace("{{context_package}}", contextPackage)
                .replace("{{contract_review_principles}}", contractReviewPrinciples)
                .replace("{{allowed_decisions}}", promptContract.allowedDecisions())
                .replace("{{required_control_keys}}", promptContract.requiredControlKeys())
                .replace("{{decision_example}}", promptContract.decisionExample());
        content = content.replace(
                "{{agent_result_contract}}",
                agentResultContract
        );

        var sections = new ArrayList<PromptSection>();
        sections.add(new PromptSection("workspace_guard", "static_instruction", "workspace-guard",
                workspaceGuard, "execution safety boundary", true));
        sections.add(new PromptSection("language_policy", "static_instruction", "language-policy",
                languagePolicy, "output language policy", true));
        sections.add(new PromptSection("structured_artifact_field_semantics", "tool_policy",
                "structured-artifact-field-semantics",
                structuredArtifactFieldSemantics, "structured artifact field semantics",
                !structuredArtifactFieldSemantics.isBlank()));
        sections.add(new PromptSection("template_static_frame", "static_instruction",
                TEMPLATE_ROOT + promptTemplate + ".md",
                VARIABLE_PATTERN.matcher(template).replaceAll(""), "prompt skeleton instructions", true));
        sections.add(new PromptSection("requirement", "requirement", workstreamDir + "/requirement.md",
                requirement, "task requirement", true));
        sections.add(new PromptSection("context_package", "context_package",
                hasInputs ? String.join(",", inputRefs) : "(none)",
                contextPackage, "prior artifacts / assembled context", hasInputs));
        sections.add(new PromptSection("read_reuse_contract", "read_reuse_contract",
                hasInputs ? String.join(",", inputRefs) : "(none)",
                readReuseContractSection, "typed memory read-reuse projection",
                !readReuseContractSection.isBlank()));
        sections.add(new PromptSection("contract_review_principles", "static_instruction",
                "contract-review-principles.md", contractReviewPrinciples, "review principles", true));
        sections.add(new PromptSection("prompt_contract", "tool_policy", "ContractRegistry:" + nodeId,
                agentResultContract,
                "strict agent result envelope", true));
        return new RenderedPrompt(content, sections);
    }

    private PromptContract promptContract(String nodeId) {
        if (!ContractRegistry.hasContract(nodeId)) {
            return new PromptContract(
                    "- (no runtime contract registered)",
                    "- decision\n- summary",
                    "<one allowed decision>",
                    Set.of());
        }
        var contract = ContractRegistry.forNode(nodeId);
        return new PromptContract(
                bulletList(contract.allowedDecisions()),
                bulletList(contract.requiredKeys()),
                contract.allowedDecisions().size() == 1
                        ? contract.allowedDecisions().iterator().next()
                        : "<one allowed decision>",
                contract.allowedDecisions()
        );
    }

    private String bulletList(Set<String> values) {
        return values.stream()
                .sorted()
                .map(value -> "- " + value)
                .reduce((left, right) -> left + "\n" + right)
                .orElse("- (none)");
    }

    private String loadTemplate(String promptTemplate) {
        var resource = TEMPLATE_ROOT + promptTemplate + ".md";
        try (var stream = Thread.currentThread().getContextClassLoader().getResourceAsStream(resource)) {
            if (stream == null) {
                throw new IllegalArgumentException("missing prompt template resource: " + resource);
            }
            var content = new String(stream.readAllBytes(), StandardCharsets.UTF_8);
            validateTemplateVariables(promptTemplate, content);
            return content;
        } catch (IOException e) {
            throw new UncheckedIOException("failed to load prompt template: " + resource, e);
        }
    }

    private void validateTemplateVariables(String templateName, String templateContent) {
        var matcher = VARIABLE_PATTERN.matcher(templateContent);
        var unknown = new LinkedHashSet<String>();
        while (matcher.find()) {
            var variable = matcher.group(1);
            if (!KNOWN_VARIABLES.contains(variable)) {
                unknown.add(variable);
            }
        }
        if (!unknown.isEmpty()) {
            throw new IllegalArgumentException(
                    "prompt template '" + templateName + "' references unknown variables: " + unknown
                            + ". Known: " + KNOWN_VARIABLES);
        }
    }

    private String readIfExists(Path path) {
        if (!Files.exists(path)) {
            return "(requirement.md not found)";
        }
        try {
            return Files.readString(path, StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException("failed to read requirement: " + path, e);
        }
    }

    private String languagePolicy(Path workstreamDir, String requirement) {
        var selected = resolvePromptLanguage(workstreamDir, requirement);
        return switch (selected) {
            case "zh-CN" -> """
                    ## Response Language Policy

                    - Use Simplified Chinese for human-readable string values inside the final JSON result.
                    - Keep JSON keys, enum values, file paths, and code identifiers exactly as specified.
                    - Do not wrap the final JSON in Markdown.
                    """.stripTrailing();
            case "en" -> """
                    ## Response Language Policy

                    - Use English for human-readable string values inside the final JSON result.
                    - Keep JSON keys, enum values, file paths, and code identifiers exactly as specified.
                    - Do not wrap the final JSON in Markdown.
                    """.stripTrailing();
            default -> throw new IllegalStateException("unexpected prompt language: " + selected);
        };
    }

    private String resolvePromptLanguage(Path workstreamDir, String requirement) {
        var configured = readConfiguredPromptLanguage(workstreamDir.resolve("settings.json"));
        if ("auto".equals(configured)) {
            return containsCjk(requirement) ? "zh-CN" : "en";
        }
        return configured;
    }

    private String structuredArtifactFieldSemantics(String nodeId) {
        if (!ContractRegistry.hasContract(nodeId)) {
            return "";
        }
        var contract = ContractRegistry.forNode(nodeId);
        if (contract.emitsArtifact("design_result")) {
            return """
                    ## Structured Artifact Field Semantics

                    - `must_fix` and `missing_evidence` mean unresolved blockers; keep them empty for a ready design.
                    - Put resolved review comments in `checks` or `evidence`, not `must_fix`.
                    - `design.planned_files` declares intended changes only; exact paths and operations must be authorized by the approved TaskContract.
                    """.stripTrailing();
        }
        if (!contract.emitsArtifact("agent_output_contract")
                && !contract.emitsArtifact("plan_result")
                && !contract.emitsArtifact("acceptance_review")) {
            return "";
        }
        return """
                ## Structured Artifact Field Semantics

                - `must_fix`, `missing_evidence`, `open_risks`, and `failure.reason` mean unresolved blockers for the current decision.
                - If the decision is positive, ready, or accepted, keep blocking fields empty: `blocking=false`, `must_fix=[]`, `missing_evidence=[]`, and `failure.reason=""`.
                - Do not use `must_fix` to list review comments that you already resolved. Put resolved review comments in `checks`, `evidence`, or `acceptance_notes` instead.
                """.stripTrailing();
    }

    private String readReuseContractSection(Path workspaceRoot, String workstreamId, List<String> inputRefs) {
        return contextPackageSubsection(workspaceRoot, workstreamId, inputRefs, "Read reuse contract:");
    }

    private String contextPackageSubsection(
            Path workspaceRoot,
            String workstreamId,
            List<String> inputRefs,
            String marker
    ) {
        if (inputRefs == null || inputRefs.isEmpty()) {
            return "";
        }
        for (String inputRef : inputRefs) {
            if (!isCanonicalContextPackageRef(workspaceRoot, workstreamId, inputRef)) {
                continue;
            }
            var path = workspaceRoot.resolve(inputRef).normalize();
            if (!Files.isRegularFile(path)) {
                continue;
            }
            var extracted = extractContextPackageSubsection(readIfExists(path), marker);
            if (!extracted.isBlank()) {
                return extracted;
            }
        }
        return "";
    }

    private String extractContextPackageSubsection(String contextPackage, String marker) {
        var start = contextPackage.indexOf(marker);
        if (start < 0) {
            return "";
        }
        var end = contextPackage.indexOf("\n## ", start + marker.length());
        var userRequirement = contextPackage.indexOf("## User Requirement", start);
        if (userRequirement >= 0 && (end < 0 || userRequirement < end)) {
            end = userRequirement;
        }
        if (end < 0) {
            end = contextPackage.length();
        }
        return contextPackage.substring(start, end).stripTrailing();
    }

    private String readConfiguredPromptLanguage(Path settingsPath) {
        if (!Files.isRegularFile(settingsPath)) {
            return "auto";
        }
        try {
            var node = OBJECT_MAPPER.readTree(settingsPath.toFile());
            return PromptLanguage.normalize(node.path("promptLanguage").asText("auto"));
        } catch (IOException e) {
            throw new UncheckedIOException("failed to read workstream settings: " + settingsPath, e);
        }
    }

    private boolean containsCjk(String text) {
        return text != null && text.codePoints().anyMatch(codePoint ->
                (codePoint >= 0x4E00 && codePoint <= 0x9FFF)
                        || (codePoint >= 0x3400 && codePoint <= 0x4DBF)
                        || (codePoint >= 0x20000 && codePoint <= 0x2A6DF)
        );
    }

    private String principleTemplate(Path workspaceRoot, String templateName) {
        var builder = new StringBuilder(loadPrincipleResource(templateName).stripTrailing());
        appendProjectPrinciple(builder, workspaceRoot.resolve(".agent").resolve("templates").resolve(templateName));
        appendProjectPrinciple(builder, workspaceRoot.resolve(".agent").resolve("templates").resolve("domain-principles.md"));
        return builder.toString().stripTrailing();
    }

    private String loadPrincipleResource(String templateName) {
        var resource = PRINCIPLE_TEMPLATE_ROOT + templateName;
        try (var stream = Thread.currentThread().getContextClassLoader().getResourceAsStream(resource)) {
            if (stream == null) {
                return "(no built-in principle template found: " + templateName + ")";
            }
            return new String(stream.readAllBytes(), StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException("failed to load principle template: " + resource, e);
        }
    }

    private void appendProjectPrinciple(StringBuilder builder, Path path) {
        if (!Files.isRegularFile(path)) {
            return;
        }
        builder.append("\n\n## Project Principles: ")
                .append(path.getFileName())
                .append("\n\n")
                .append(readIfExists(path).stripTrailing());
    }

    private String contextPackageSection(
            Path workspaceRoot,
            String workstreamId,
            String nodeId,
            List<String> inputRefs,
            String trustedTaskContractPayload
    ) {
        if (inputRefs == null || inputRefs.isEmpty()) {
            return "(no context package provided)";
        }
        var contextRefs = inputRefs.stream()
                .filter(ref -> isCanonicalContextPackageRef(workspaceRoot, workstreamId, ref))
                .toList();
        var directInputRefs = inputRefs.stream()
                .filter(ref -> !contextRefs.contains(ref))
                .filter(ref -> !isCanonicalContextPackageMetadataRef(workspaceRoot, workstreamId, ref))
                .toList();
        if (contextRefs.isEmpty() && directInputRefs.isEmpty()) {
            return "(no context package provided)";
        }
        var builder = new StringBuilder();
        var trustedTypedPayloads = TypedContextPayloadBoundary.trustOnce(
                trustedTypedPayloads(
                        workspaceRoot, workstreamId, nodeId, inputRefs, trustedTaskContractPayload));
        if (!directInputRefs.isEmpty()) {
            builder.append("### Direct Input Artifacts\n\n");
            var renderedEvidence = new LinkedHashSet<String>();
            for (String inputRef : directInputRefs) {
                var path = workspaceRoot.resolve(inputRef).normalize();
                builder.append("- ").append(inputRef).append("\n");
                var validatedDocument = AgentEvidenceIndex.validatedDocument(
                        workspaceRoot, workstreamId, inputRef, OBJECT_MAPPER);
                if (validatedDocument.isPresent()) {
                    var document = validatedDocument.get();
                    var evidenceKey = document.runId() + "\n"
                            + document.nodeInstanceId() + "\n"
                            + document.sourceOutputRef();
                    if (!renderedEvidence.add(evidenceKey)) {
                        builder.append("  (validated typed evidence already projected)\n\n");
                        continue;
                    }
                    builder.append("\n```json\n");
                    builder.append(renderTypedAgentEvidence(document));
                    builder.append("\n```\n\n");
                    appendVerifiedRevisionBaseline(
                            builder, workspaceRoot, workstreamId, nodeId, document);
                } else if (isCanonicalDirectInputRef(workspaceRoot, workstreamId, inputRef)
                        && !(trustedTaskContractPayload != null && isStableContractProjectionRef(inputRef))) {
                    builder.append("\n```text\n");
                    builder.append(readContextPreview(workspaceRoot, path));
                    builder.append("\n```\n\n");
                } else if (Files.exists(path) && Files.isRegularFile(path)) {
                    builder.append("  (content omitted; no typed context projection)\n\n");
                }
            }
        }
        for (String contextRef : contextRefs) {
            var path = workspaceRoot.resolve(contextRef).normalize();
            builder.append("- ").append(contextRef).append("\n");
            if (Files.exists(path)) {
                builder.append("\n```text\n");
                builder.append(readCompleteContextPackage(workspaceRoot, path, trustedTypedPayloads));
                builder.append("\n```\n\n");
            }
        }
        return builder.toString().stripTrailing();
    }

    private void appendVerifiedRevisionBaseline(
            StringBuilder builder,
            Path workspaceRoot,
            String workstreamId,
            String nodeId,
            AgentOutputContractDocument document
    ) {
        if (!"intake.claude_brainstorm".equals(nodeId)
                || !"intake.codex_product_review".equals(document.nodeId())
                || !"NEEDS_REVISION".equals(document.decision())
                || document.reviewSubject() == null) {
            return;
        }
        var baseline = TypedContextPayloadBoundary
                .wrapVerifiedProposal(document.reviewSubject(), workspaceRoot, workstreamId, OBJECT_MAPPER)
                .orElseThrow(() -> new IllegalArgumentException(
                        "verified previous task-contract proposal is required for intake revision"));
        builder.append("### Verified Previous Task Contract Proposal\n\n");
        builder.append("- Proposal ID: ").append(document.reviewSubject().proposalId()).append("\n");
        builder.append("- Proposal SHA-256: ").append(document.reviewSubject().sha256()).append("\n\n");
        builder.append(baseline).append("\n\n");
    }

    private boolean isCanonicalDirectInputRef(Path workspaceRoot, String workstreamId, String inputRef) {
        if (workstreamId == null || workstreamId.isBlank() || inputRef == null || inputRef.isBlank()) {
            return false;
        }
        var root = workspaceRoot.toAbsolutePath().normalize();
        var workstreamDir = root.resolve(".agent/workstreams").resolve(workstreamId).normalize();
        var path = root.resolve(inputRef).normalize();
        if (!workstreamDir.startsWith(root)
                || !isRegularFileWithin(root, path, workstreamDir, false)) {
            return false;
        }
        var relative = workstreamDir.relativize(path).toString().replace('\\', '/');
        if (Set.of(
                "artifacts/task-contract.json",
                "artifacts/task-contract.md",
                "artifacts/contract-resolution.json",
                "artifacts/contract-resolution.md",
                "artifacts/next-stage/next-stage-prompt.md",
                "artifacts/next-stage/handoff.json",
                "delivery/commit-message.txt",
                "delivery/pr-body.md"
        ).contains(relative)) {
            return true;
        }
        var segments = relative.split("/");
        return segments.length == 4
                && "runs".equals(segments[0])
                && !segments[1].isBlank()
                && "prompts".equals(segments[2])
                && "session-compaction-seed.md".equals(segments[3]);
    }

    private boolean isStableContractProjectionRef(String inputRef) {
        var normalized = inputRef == null ? "" : inputRef.replace('\\', '/');
        return normalized.endsWith("/artifacts/task-contract.json")
                || normalized.endsWith("/artifacts/task-contract.md")
                || normalized.endsWith("/artifacts/contract-resolution.json")
                || normalized.endsWith("/artifacts/contract-resolution.md");
    }

    private boolean isCanonicalContextPackageRef(Path workspaceRoot, String workstreamId, String inputRef) {
        if (workstreamId == null || workstreamId.isBlank() || inputRef == null || inputRef.isBlank()) {
            return false;
        }
        var root = workspaceRoot.toAbsolutePath().normalize();
        var contextDir = root.resolve(".agent/workstreams").resolve(workstreamId).resolve("context").normalize();
        var path = root.resolve(inputRef).normalize();
        return contextDir.startsWith(root)
                && contextDir.equals(path.getParent())
                && path.getFileName().toString().endsWith(".md")
                && isRegularFileWithin(root, path, contextDir, true);
    }

    private boolean isCanonicalContextPackageMetadataRef(
            Path workspaceRoot,
            String workstreamId,
            String inputRef
    ) {
        if (workstreamId == null || workstreamId.isBlank() || inputRef == null || inputRef.isBlank()) {
            return false;
        }
        var root = workspaceRoot.toAbsolutePath().normalize();
        var contextDir = root.resolve(".agent/workstreams").resolve(workstreamId).resolve("context").normalize();
        var path = root.resolve(inputRef).normalize();
        return contextDir.startsWith(root)
                && contextDir.equals(path.getParent())
                && path.getFileName().toString().endsWith(".json")
                && isRegularFileWithin(root, path, contextDir, true);
    }

    private boolean isRegularFileWithin(
            Path workspaceRoot,
            Path path,
            Path expectedDirectory,
            boolean directChild
    ) {
        if (!Files.isRegularFile(path) || Files.isSymbolicLink(path)) {
            return false;
        }
        try {
            var realRoot = workspaceRoot.toRealPath();
            var realPath = path.toRealPath();
            var realDirectory = expectedDirectory.toRealPath();
            return realDirectory.startsWith(realRoot)
                    && realPath.startsWith(realDirectory)
                    && (!directChild || realDirectory.equals(realPath.getParent()));
        } catch (IOException e) {
            return false;
        }
    }

    private String renderTypedAgentEvidence(Object document) {
        try {
            return OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(document);
        } catch (IOException e) {
            throw new UncheckedIOException("failed to render validated agent evidence", e);
        }
    }

    private Set<String> trustedTypedPayloads(
            Path workspaceRoot,
            String workstreamId,
            String nodeId,
            List<String> inputRefs,
            String trustedTaskContractPayload
    ) {
        var trusted = new LinkedHashSet<String>();
        TaskContractProposalReference.resolveProposalFromRefs(
                        workspaceRoot, workstreamId, inputRefs, OBJECT_MAPPER)
                .map(subject -> TypedContextPayloadBoundary.wrapJson(subject.proposal()))
                .ifPresent(trusted::add);
        if (trustedTaskContractPayload == null) {
            AgentRunGovernanceContext.trustedTaskContractPayload(
                            workspaceRoot, workstreamId, nodeId, inputRefs)
                    .ifPresent(trusted::add);
        } else {
            trusted.add(trustedTaskContractPayload);
        }
        return Set.copyOf(trusted);
    }

    private String readCompleteContextPackage(
            Path workspaceRoot,
            Path path,
            TypedContextPayloadBoundary.TrustedPayloads trustedTypedPayloads
    ) {
        try {
            return sanitizeOutsideWorkspacePaths(
                    workspaceRoot,
                    Files.readString(path, StandardCharsets.UTF_8),
                    trustedTypedPayloads).stripTrailing();
        } catch (IOException e) {
            throw new UncheckedIOException("failed to read context package: " + path, e);
        }
    }

    private String readContextPreview(Path workspaceRoot, Path path) {
        try {
            var content = Files.readString(path, StandardCharsets.UTF_8);
            content = sanitizeOutsideWorkspacePaths(
                    workspaceRoot, content, TypedContextPayloadBoundary.trustOnce(Set.of()));
            if (content.length() <= 6_000) {
                return content.stripTrailing();
            }
            return content.substring(0, 6_000).stripTrailing()
                    + "\n\n[truncated; read the full context package at " + path.toAbsolutePath().normalize() + "]";
        } catch (IOException e) {
            throw new UncheckedIOException("failed to read context package: " + path, e);
        }
    }

    private String workspaceGuard(Path workspaceRoot, String nodeId) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        if ("intake.claude_brainstorm".equals(nodeId)) {
            return """
                    ## Execution Workspace Guard

                    - Effective workspace: %s
                    - This intake run uses restricted contract discovery. Use orchestrator-provided context and bounded discovery only.
                    - Do not output shell commands or Bash code fences as a substitute for the required structured artifact.
                    - Modify files only inside the effective workspace.
                    - Ignore absolute paths outside the effective workspace even if they appear in quoted prior outputs.
                    - Do not run commands with `git -C` pointing outside the effective workspace.
                    """.formatted(root).stripTrailing();
        }
        return """
                ## Execution Workspace Guard

                - Effective workspace: %s
                - Run all shell commands from the effective workspace above.
                - Modify files only inside the effective workspace.
                - Ignore absolute paths outside the effective workspace even if they appear in quoted prior outputs.
                - Do not run commands with `git -C` pointing outside the effective workspace.
                """.formatted(root).stripTrailing();
    }

    private String sanitizeOutsideWorkspacePaths(Path workspaceRoot, String content) {
        return sanitizeOutsideWorkspacePaths(
                workspaceRoot, content, TypedContextPayloadBoundary.trustOnce(Set.of()));
    }

    private String sanitizeOutsideWorkspacePaths(
            Path workspaceRoot,
            String content,
            TypedContextPayloadBoundary.TrustedPayloads trustedTypedPayloads
    ) {
        return TypedContextPayloadBoundary.transformUntyped(
                content,
                trustedTypedPayloads,
                segment -> sanitizeUntypedOutsideWorkspacePaths(workspaceRoot, segment));
    }

    private String sanitizeUntypedOutsideWorkspacePaths(Path workspaceRoot, String content) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var matcher = ABSOLUTE_PATH_PATTERN.matcher(content);
        var result = new StringBuilder();
        while (matcher.find()) {
            var rawPath = matcher.group(1);
            var replacement = rawPath;
            try {
                var path = Path.of(rawPath).toAbsolutePath().normalize();
                if (!path.startsWith(root)) {
                    replacement = "[outside-workspace path removed]";
                }
            } catch (RuntimeException ignored) {
                replacement = "[outside-workspace path removed]";
            }
            matcher.appendReplacement(result, java.util.regex.Matcher.quoteReplacement(replacement));
        }
        matcher.appendTail(result);
        return result.toString();
    }

    private record PromptContract(
            String allowedDecisions,
            String requiredControlKeys,
            String decisionExample,
            Set<String> allowedDecisionValues
    ) {}

    /** Source metadata for one prompt section; content is only used to compute bytes/sha. */
    record PromptSection(String name, String sourceType, String sourceRef, String content,
                         String includedReason, boolean required) {
    }

    /** Rendered prompt text plus its section provenance. */
    record RenderedPrompt(String content, List<PromptSection> sections) {
    }
}

package dev.dual.adapter.acpx;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.contract.TaskContract;
import dev.dual.core.execution.AdapterSignal;
import dev.dual.runtime.handler.AgentOutputContractDocument;
import dev.dual.runtime.handler.AgentOutputContractSidecar;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.function.Function;

/**
 * Updates the per-workstream semantic memory from typed execution facts.
 *
 * <p>This is the single writer for orchestrator-owned semantic memory. It
 * consumes only typed sources: {@link AcpxToolUsage#readFiles()} for reads,
 * the current run's qualified contract snapshot for decided scope / non-goals, and the
 * run's validated {@code agent_output_contract} sidecar for decisions / verdicts / open
 * issues / stage outcome, plus the classified failure for prior failures. It
 * does not parse agent prose, stdout, or markdown summaries as fact. The memory
 * file is a durable artifact owned by the workstream; prompt manifests, context
 * package projections, and trace commands remain projections over it.</p>
 */
final class WorkstreamMemoryUpdater {
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };
    private static final int MAX_DECISIONS = 12;
    private static final int MAX_PRIOR_VERDICTS = 8;
    private static final int MAX_OPEN_ISSUES = 24;
    private static final int MAX_PRIOR_FAILURES = 8;
    private static final int MAX_READ_FILES = 64;

    private final ObjectMapper objectMapper = new ObjectMapper()
            .registerModule(new JavaTimeModule())
            .enable(SerializationFeature.INDENT_OUTPUT);

    Path memoryPath(Path workspaceRoot, String workstreamId) {
        return workspaceRoot.resolve(".agent").resolve("workstreams").resolve(workstreamId)
                .resolve("memory").resolve("workstream-memory.json");
    }

    /**
     * Single entry point for all semantic-memory updates after one agent run.
     * Reads existing memory, merges typed facts, and atomically rewrites the
     * file. Every branch tolerates missing inputs (no task contract, no
     * envelope, no failure) so a partial run still records what it can.
     */
    void updateMemory(
            Path workspaceRoot,
            String workstreamId,
            String runId,
            String nodeId,
            String stage,
            String agent,
            Path outputPath,
            AcpxToolUsage toolUsage,
            List<AdapterSignal> adapterSignals,
            Optional<TaskContract> qualifiedTaskContract,
            String taskContractRef,
            String taskContractSha256
    ) throws IOException {
        if (workspaceRoot == null || workstreamId == null || workstreamId.isBlank()) {
            return;
        }
        var memoryPath = memoryPath(workspaceRoot, workstreamId);
        var memory = readExisting(memoryPath, workstreamId);
        var taskContract = qualifiedTaskContract == null ? Optional.<TaskContract>empty() : qualifiedTaskContract;
        mergeContractScope(memory, taskContract, taskContractRef, taskContractSha256);
        var keywords = contractKeywords(taskContract);

        var readFiles = byPath(memory.get("readFiles"));
        refreshInvalidation(workspaceRoot, readFiles);
        mergeReadFiles(memory, workspaceRoot, runId, nodeId, stage, toolUsage, keywords, readFiles);

        extractContract(outputPath).ifPresent(
                contract -> mergeRunOutcome(memory, contract, runId, nodeId, stage, agent));
        var activeSignal = adapterSignals == null ? null : adapterSignals.stream()
                .filter(signal -> !signal.superseded() && signal.type().blocksSuccess())
                .findFirst()
                .orElse(null);
        if (activeSignal != null) {
            mergeFailure(memory, activeSignal, runId, nodeId);
        }

        writeMemory(memoryPath, workstreamId, memory);
    }

    /**
     * Legacy entry retained so existing callers/tests keep compiling. Delegates
     * to {@link #updateMemory} with no output/failure context (reads only).
     */
    void updateReadFiles(
            Path workspaceRoot,
            String workstreamId,
            String runId,
            String nodeId,
            String stage,
            AcpxToolUsage toolUsage
    ) throws IOException {
        updateMemory(workspaceRoot, workstreamId, runId, nodeId, stage, "", null, toolUsage, null,
                Optional.empty(), "", "");
    }

    private void mergeContractScope(
            Map<String, Object> memory,
            Optional<TaskContract> contract,
            String contractRef,
            String contractSha256
    ) {
        if (contract.isEmpty()) {
            memory.putIfAbsent("decidedScope", List.of());
            memory.putIfAbsent("nonGoals", List.of());
            if (memory.containsKey("qualifiedTaskContract")) {
                var stale = new LinkedHashMap<String, Object>(mapValue(memory.get("qualifiedTaskContract")));
                stale.put("status", "stale_projection");
                memory.put("qualifiedTaskContract", stale);
            } else {
                memory.put("qualifiedTaskContract", Map.of("status", "unavailable"));
            }
            return;
        }
        var document = contract.orElseThrow();
        var decidedScope = document.scope() == null
                ? List.<String>of()
                : document.scope().included().stream()
                        .map(TaskContract.ScopeEntry::path)
                        .toList();
        memory.put("decidedScope", decidedScope);
        memory.put("nonGoals", document.nonGoals());
        memory.put("qualifiedTaskContract", Map.of(
                "status", "qualified_projection",
                "contractId", document.id(),
                "contractVersion", document.version(),
                "ref", text(contractRef),
                "sha256", text(contractSha256)));
    }

    void updateMemory(
            Path workspaceRoot,
            String workstreamId,
            String runId,
            String nodeId,
            String stage,
            String agent,
            Path outputPath,
            AcpxToolUsage toolUsage,
            List<AdapterSignal> adapterSignals
    ) throws IOException {
        updateMemory(workspaceRoot, workstreamId, runId, nodeId, stage, agent, outputPath, toolUsage,
                adapterSignals, Optional.empty(), "", "");
    }

    private static Set<String> contractKeywords(Optional<TaskContract> contract) {
        var phrases = new ArrayList<String>();
        contract.ifPresent(document -> {
            if (document.scope() != null) {
                document.scope().included().stream()
                        .map(TaskContract.ScopeEntry::path)
                        .forEach(phrases::add);
            }
            phrases.addAll(document.acceptanceCriteria());
        });
        var tokens = new LinkedHashSet<String>();
        for (var phrase : phrases) {
            for (var token : phrase.toLowerCase(Locale.ROOT).split("[^\\p{IsAlphabetic}\\p{IsDigit}_/-]+")) {
                if (token.length() >= 4) {
                    tokens.add(token);
                }
            }
        }
        return tokens;
    }

    private void mergeReadFiles(
            Map<String, Object> memory,
            Path workspaceRoot,
            String runId,
            String nodeId,
            String stage,
            AcpxToolUsage toolUsage,
            Set<String> keywords,
            Map<String, Map<String, Object>> readFiles
    ) {
        var files = toolUsage == null ? List.<String>of() : normalizedRepoFiles(toolUsage.readFiles());
        var now = Instant.now().toString();
        for (var path : files) {
            var absolute = workspaceRoot.resolve(path).normalize();
            if (!Files.isRegularFile(absolute)) {
                continue;
            }
            var entry = readFiles.computeIfAbsent(path, ignored -> new LinkedHashMap<>());
            entry.put("path", path);
            entry.put("evidenceRole", evidenceRole(path));
            entry.put("readAt", now);
            entry.put("readRunId", runId);
            entry.put("readNodeId", nodeId);
            entry.put("lastSeenStage", stage == null ? "" : stage);
            try {
                entry.put("sha", sha256(absolute));
                entry.put("summary", semanticSummary(absolute, path, keywords));
                entry.put("trusted", true);
                entry.put("invalidationReason", "");
            } catch (IOException ignored) {
                entry.put("trusted", false);
                entry.put("invalidationReason", "file metadata unavailable");
            }
        }
        memory.put("readFiles", readFiles.values().stream()
                .sorted(Comparator.comparing(item -> String.valueOf(item.get("path"))))
                .limit(MAX_READ_FILES)
                .toList());
    }

    private Optional<AgentOutputContractDocument> extractContract(Path outputPath) {
        if (outputPath == null || !Files.isRegularFile(outputPath)) {
            return Optional.empty();
        }
        try {
            return AgentOutputContractSidecar.read(outputPath, objectMapper);
        } catch (RuntimeException ignored) {
            return Optional.empty();
        }
    }

    private void mergeRunOutcome(
            Map<String, Object> memory,
            AgentOutputContractDocument contract,
            String runId,
            String nodeId,
            String stage,
            String agent
    ) {
        if (contract.hasDecision()) {
            var decision = new LinkedHashMap<String, Object>();
            decision.put("stage", text(stage));
            decision.put("nodeId", text(nodeId));
            decision.put("runId", text(runId));
            decision.put("decision", contract.decision());
            decision.put("summary", contract.summary());
            appendDedup(memory, "decisions", decision,
                    d -> text(d.get("nodeId")) + "|" + text(d.get("decision")) + "|" + text(d.get("summary")),
                    MAX_DECISIONS);

            if (isReviewVerdictNode(nodeId, stage)) {
                var verdict = new LinkedHashMap<String, Object>();
                verdict.put("iterationId", "");
                verdict.put("nodeId", text(nodeId));
                verdict.put("stage", text(stage));
                verdict.put("decision", contract.decision());
                verdict.put("blocking", contract.blocking());
                verdict.put("mustFix", contract.mustFix());
                appendDedup(memory, "priorVerdicts", verdict,
                        v -> text(v.get("nodeId")) + "|" + text(v.get("decision")),
                        MAX_PRIOR_VERDICTS);
            }
        }

        if (isOpenVerdict(contract) || contract.blocking()) {
            addOpenIssues(memory, contract, runId, nodeId, agent);
        } else if (isPositiveVerdict(contract)) {
            resolveOpenIssuesFor(memory, nodeId);
        }

        var outcome = new LinkedHashMap<String, Object>();
        outcome.put("stage", text(stage));
        outcome.put("nodeId", text(nodeId));
        outcome.put("runId", text(runId));
        outcome.put("outcome", contract.canonicalStageOutcome());
        outcome.put("decision", contract.decision());
        outcome.put("verificationSummary", contract.verificationSummary());
        memory.put("lastStageOutcome", outcome);
    }

    private void addOpenIssues(
            Map<String, Object> memory,
            AgentOutputContractDocument contract,
            String runId,
            String nodeId,
            String agent
    ) {
        var byId = new LinkedHashMap<String, Map<String, Object>>();
        for (var item : listValue(memory.get("openIssues"))) {
            var id = text(item.get("id"));
            if (!id.isBlank()) {
                byId.put(id, new LinkedHashMap<>(item));
            }
        }
        var raisedBy = !text(agent).isBlank() ? agent : text(nodeId);
        for (var fact : combinedOpenIssueFacts(contract)) {
            var desc = fact.desc();
            if (desc.isBlank()) {
                continue;
            }
            var id = shortHash(desc);
            var issue = byId.computeIfAbsent(id, ignored -> new LinkedHashMap<String, Object>());
            issue.put("id", id);
            issue.put("sourceField", fact.sourceField());
            issue.put("desc", desc);
            issue.put("raisedBy", raisedBy);
            issue.put("raisedNodeId", text(nodeId));
            issue.put("raisedRunId", text(runId));
            issue.put("raisedIterationId", "");
            issue.put("status", "open");
        }
        memory.put("openIssues", byId.values().stream().limit(MAX_OPEN_ISSUES).toList());
    }

    private void resolveOpenIssuesFor(Map<String, Object> memory, String nodeId) {
        var existing = listValue(memory.get("openIssues"));
        if (existing.isEmpty()) {
            return;
        }
        var updated = new ArrayList<Map<String, Object>>();
        var changed = false;
        for (var item : existing) {
            if ("open".equals(text(item.get("status"))) && text(nodeId).equals(text(item.get("raisedNodeId")))) {
                var copy = new LinkedHashMap<>(item);
                copy.put("status", "resolved");
                updated.add(copy);
                changed = true;
            } else {
                updated.add(item);
            }
        }
        if (changed) {
            memory.put("openIssues", updated);
        }
    }

    private static List<OpenIssueFact> combinedOpenIssueFacts(AgentOutputContractDocument contract) {
        var all = new ArrayList<OpenIssueFact>();
        contract.mustFix().forEach(item -> all.add(new OpenIssueFact("must_fix", item)));
        contract.openRisks().forEach(item -> all.add(new OpenIssueFact("open_risks", item)));
        contract.missingEvidence().forEach(item -> all.add(new OpenIssueFact("missing_evidence", item)));
        return all;
    }

    private record OpenIssueFact(String sourceField, String desc) {
    }

    private void mergeFailure(
            Map<String, Object> memory,
            AdapterSignal signal,
            String runId,
            String nodeId
    ) {
        var entry = new LinkedHashMap<String, Object>();
        entry.put("node", text(nodeId));
        entry.put("runId", text(runId));
        entry.put("reason", signal.type().name());
        entry.put("resolved", false);
        appendDedup(memory, "priorFailures", entry,
                f -> text(f.get("node")) + "|" + text(f.get("reason")),
                MAX_PRIOR_FAILURES);
    }

    @SuppressWarnings("unchecked")
    private void appendDedup(
            Map<String, Object> memory,
            String key,
            Map<String, Object> newEntry,
            Function<Map<String, Object>, String> keyFn,
            int max
    ) {
        var existing = new ArrayList<Map<String, Object>>();
        for (var item : listValue(memory.get(key))) {
            existing.add(new LinkedHashMap<>(item));
        }
        var newKey = keyFn.apply(newEntry);
        existing.removeIf(item -> newKey.equals(keyFn.apply(item)));
        existing.add(newEntry);
        if (existing.size() > max) {
            existing = new ArrayList<>(existing.subList(existing.size() - max, existing.size()));
        }
        memory.put(key, existing);
    }

    private void writeMemory(Path memoryPath, String workstreamId, Map<String, Object> memory) throws IOException {
        memory.put("schemaVersion", 1);
        memory.put("artifactType", "workstream_memory");
        memory.put("workstreamId", workstreamId);
        memory.putIfAbsent("decidedScope", List.of());
        memory.putIfAbsent("nonGoals", List.of());
        memory.putIfAbsent("decisions", List.of());
        memory.putIfAbsent("readFiles", List.of());
        memory.putIfAbsent("openIssues", List.of());
        memory.putIfAbsent("priorVerdicts", List.of());
        memory.putIfAbsent("priorFailures", List.of());
        memory.putIfAbsent("lastStageOutcome", Map.of());
        memory.putIfAbsent("fieldSemantics", fieldSemantics());
        memory.put("updatedAt", Instant.now().toString());
        Files.createDirectories(memoryPath.getParent());
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(memoryPath.toFile(), memory);
    }

    private Map<String, Object> readExisting(Path memoryPath, String workstreamId) throws IOException {
        if (!Files.isRegularFile(memoryPath)) {
            var memory = new LinkedHashMap<String, Object>();
            memory.put("schemaVersion", 1);
            memory.put("artifactType", "workstream_memory");
            memory.put("workstreamId", workstreamId);
            memory.put("decidedScope", List.of());
            memory.put("nonGoals", List.of());
            memory.put("decisions", List.of());
            memory.put("readFiles", List.of());
            memory.put("openIssues", List.of());
            memory.put("priorVerdicts", List.of());
            memory.put("priorFailures", List.of());
            memory.put("lastStageOutcome", Map.of());
            memory.put("fieldSemantics", fieldSemantics());
            return memory;
        }
        try {
            return new LinkedHashMap<>(objectMapper.readValue(memoryPath.toFile(), MAP_TYPE));
        } catch (IOException ignored) {
            var memory = new LinkedHashMap<String, Object>();
            memory.put("schemaVersion", 1);
            memory.put("artifactType", "workstream_memory");
            memory.put("workstreamId", workstreamId);
            memory.put("readFiles", List.of());
            memory.put("fieldSemantics", fieldSemantics());
            return memory;
        }
    }

    private static Map<String, Object> fieldSemantics() {
        return Map.of(
                "machineDecisionFields", List.of("decision", "stage_outcome", "lifecycle_status", "blocking", "sourceField", "status"),
                "projectionOnlyFields", List.of("summary", "desc", "verificationSummary")
        );
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Map<String, Object>> byPath(Object value) {
        var byPath = new LinkedHashMap<String, Map<String, Object>>();
        if (!(value instanceof List<?> list)) {
            return byPath;
        }
        for (var item : list) {
            if (!(item instanceof Map<?, ?> map)) {
                continue;
            }
            var path = text(map.get("path"));
            if (path.isBlank()) {
                continue;
            }
            byPath.put(path, new LinkedHashMap<>((Map<String, Object>) map));
        }
        return byPath;
    }

    private static void refreshInvalidation(Path workspaceRoot, Map<String, Map<String, Object>> readFiles) {
        for (var entry : readFiles.values()) {
            var path = text(entry.get("path"));
            if (path.isBlank()) {
                continue;
            }
            var absolute = workspaceRoot.resolve(path).normalize();
            if (!Files.isRegularFile(absolute)) {
                entry.put("trusted", false);
                entry.put("invalidationReason", "file missing since prior read");
                continue;
            }
            try {
                var currentSha = sha256(absolute);
                var priorSha = text(entry.get("sha"));
                if (!priorSha.isBlank() && !priorSha.equals(currentSha)) {
                    entry.put("trusted", false);
                    entry.put("invalidationReason", "file changed since prior read");
                }
            } catch (IOException ignored) {
                entry.put("trusted", false);
                entry.put("invalidationReason", "file hash unavailable");
            }
        }
    }

    private static boolean isReviewVerdictNode(String nodeId, String stage) {
        var n = text(nodeId).toLowerCase(Locale.ROOT);
        var s = text(stage).toLowerCase(Locale.ROOT);
        return n.contains("review") || n.contains("verifier") || n.contains("acceptance")
                || s.contains("review") || s.contains("acceptance");
    }

    private static boolean isOpenVerdict(AgentOutputContractDocument contract) {
        var d = contract.decision();
        return "REJECT".equals(d) || "REJECTED".equals(d)
                || "NEEDS_REVISION".equals(d) || "BLOCKED".equals(d)
                || "NEEDS_CLARIFICATION".equals(d) || "NEEDS_SCOPE_REDUCTION".equals(d);
    }

    private static boolean isPositiveVerdict(AgentOutputContractDocument contract) {
        var d = contract.decision();
        if (d.isBlank() || contract.blocking() || !contract.mustFix().isEmpty()) {
            return false;
        }
        return d.startsWith("READY_") || d.equals("HANDOFF_READY")
                || d.equals("ACCEPT") || d.equals("ACCEPT_WITH_NOTES")
                || d.equals("ACCEPTED") || d.equals("ACCEPTED_WITH_NOTES");
    }

    private static List<String> normalizedRepoFiles(List<String> files) {
        if (files == null || files.isEmpty()) {
            return List.of();
        }
        var normalized = new LinkedHashSet<String>();
        for (var file : files) {
            var path = normalize(file);
            if (!path.isBlank() && !path.startsWith("/") && !path.startsWith(".agent/") && !ignoredPath(path)) {
                normalized.add(path);
            }
        }
        return new ArrayList<>(normalized);
    }

    private static boolean ignoredPath(String path) {
        return path.contains("/node_modules/")
                || path.contains("/target/")
                || path.contains("/dist/")
                || path.contains("/build/")
                || path.startsWith(".git/");
    }

    private static String normalize(String value) {
        var text = value == null ? "" : value.trim();
        while (text.startsWith("./")) {
            text = text.substring(2);
        }
        return text;
    }

    /**
     * Structural, deterministic summary of a read file (symbols / headings /
     * test names), scoped by task-contract keywords. Falls back to a metadata
     * summary when no structure can be extracted. Never throws.
     */
    private static String semanticSummary(Path absolute, String path, Set<String> keywords) {
        var content = readBounded(absolute, 8192);
        var summary = content == null ? "" : ReadFileSummary.summarize(content, path, keywords);
        if (!summary.isBlank()) {
            return summary;
        }
        try {
            return metadataSummary(absolute, path);
        } catch (IOException e) {
            return "Previously read " + evidenceRole(path) + " file.";
        }
    }

    private static String readBounded(Path path, int maxChars) {
        try {
            var content = Files.readString(path);
            return content.length() <= maxChars ? content : content.substring(0, maxChars);
        } catch (IOException e) {
            return null;
        }
    }

    private static String metadataSummary(Path absolute, String path) throws IOException {
        return "Previously read " + evidenceRole(path) + " file (" + Files.size(absolute) + " bytes).";
    }

    private static String evidenceRole(String path) {
        var lower = path.toLowerCase(Locale.ROOT);
        if (lower.endsWith(".md") || lower.startsWith("docs/")) {
            return "documentation";
        }
        if (lower.contains("/test/") || lower.contains("/tests/")
                || lower.endsWith(".test.js") || lower.endsWith(".test.ts")
                || lower.endsWith(".spec.js") || lower.endsWith(".spec.ts")) {
            return "test";
        }
        if (lower.endsWith(".json") || lower.endsWith(".yaml") || lower.endsWith(".yml")
                || lower.endsWith(".toml") || lower.endsWith(".xml")) {
            return "configuration";
        }
        return "source";
    }

    private static String shortHash(String text) {
        try {
            var sha = MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(sha).substring(0, 12);
        } catch (NoSuchAlgorithmException e) {
            return Integer.toHexString(text.hashCode());
        }
    }

    private static String sha256(Path path) throws IOException {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(path)));
        } catch (NoSuchAlgorithmException e) {
            throw new IOException("SHA-256 digest is not available", e);
        }
    }

    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> listValue(Object value) {
        if (!(value instanceof List<?> list)) {
            return new ArrayList<>();
        }
        var out = new ArrayList<Map<String, Object>>();
        for (var item : list) {
            if (item instanceof Map<?, ?> map) {
                var copy = new LinkedHashMap<String, Object>();
                for (var e : map.entrySet()) {
                    if (e.getKey() instanceof String key) {
                        copy.put(key, e.getValue());
                    }
                }
                out.add(copy);
            }
        }
        return out;
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> mapValue(Object value) {
        if (!(value instanceof Map<?, ?> map)) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, Object>();
        for (var e : map.entrySet()) {
            if (e.getKey() instanceof String key) {
                copy.put(key, e.getValue());
            }
        }
        return copy;
    }

    private static List<String> stringList(Object value) {
        if (!(value instanceof List<?> list)) {
            return List.of();
        }
        var out = new ArrayList<String>();
        for (var item : list) {
            var t = text(item);
            if (!t.isBlank()) {
                out.add(t);
            }
        }
        return List.copyOf(out);
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }
}

