package dev.dual.adapter.acpx;

import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Writes prompt provenance manifests: which sections formed the final prompt,
 * where each section came from, and its approximate token size.
 *
 * <p>The manifest is a projection/read model, not a source of truth. It does
 * not store prompt body text; full content is only written when
 * DUAL_AGENT_PROMPT_DEBUG is enabled. The manifest stores section
 * bytes/estimatedTokens/sha256 plus source metadata so memory optimizations can
 * be verified without re-parsing prompt text.</p>
 */
class PromptManifestWriter {

    static Path manifestPathFor(Path promptPath) {
        return promptPath.resolveSibling(promptPath.getFileName() + ".manifest.json");
    }

    private final ObjectMapper objectMapper = new ObjectMapper();

    void write(Path manifestPath,
               String workstreamId,
               String runId,
               String nodeId,
               String agent,
               String promptTemplate,
               Path promptPath,
               List<AgentPromptRenderer.PromptSection> sections) throws IOException {
        write(manifestPath, workstreamId, runId, nodeId, agent, promptTemplate, promptPath, sections, null);
    }

    void write(Path manifestPath, String workstreamId, String runId, String nodeId, String agent,
               String promptTemplate, Path promptPath, List<AgentPromptRenderer.PromptSection> sections,
               dev.dual.runtime.handler.AuthoredExecutionContext.Snapshot authoredContext) throws IOException {
        Files.createDirectories(manifestPath.getParent());
        var sectionEntries = new ArrayList<Map<String, Object>>();
        for (var section : sections) {
            var bytes = section.content().getBytes(StandardCharsets.UTF_8);
            var estimatedTokens = estimatedTokens(bytes.length);
            var entry = new LinkedHashMap<String, Object>();
            entry.put("name", section.name());
            entry.put("sourceType", section.sourceType());
            entry.put("sourceRef", section.sourceRef());
            entry.put("bytes", bytes.length);
            entry.put("estimatedTokens", estimatedTokens);
            entry.put("sha256", sha256(bytes));
            entry.put("includedReason", section.includedReason());
            entry.put("required", section.required());
            sectionEntries.add(entry);
        }
        var promptBytes = Files.exists(promptPath) ? Files.readAllBytes(promptPath) : new byte[0];
        var manifest = new LinkedHashMap<String, Object>();
        manifest.put("schemaVersion", 1);
        manifest.put("workstreamId", workstreamId);
        manifest.put("runId", runId);
        manifest.put("nodeId", nodeId);
        manifest.put("agent", agent);
        manifest.put("promptTemplate", promptTemplate);
        manifest.put("promptPath", promptPath.toString());
        manifest.put("totalBytes", promptBytes.length);
        manifest.put("totalEstimatedTokens", estimatedTokens(promptBytes.length));
        manifest.put("sections", sectionEntries);
        if (authoredContext != null) manifest.put("authoredContext", authoredContext);
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(manifestPath.toFile(), manifest);
    }

    private static long estimatedTokens(long byteSize) {
        return (byteSize + 3) / 4;
    }

    private static String sha256(byte[] bytes) {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
        } catch (NoSuchAlgorithmException ignored) {
            return "";
        }
    }
}

package dev.dual.adapter.acpx;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Locale;
import java.util.Map;

/**
 * Typed read model consumed by session compaction policy.
 *
 * <p>The underlying source is the token metrics projection, but policy code
 * must not know the projection layout. This class is the compatibility
 * boundary until token attribution has a first-class ledger read model.</p>
 */
record SessionCompactionSignal(Map<String, Long> cachedReadTokensByAgent, Long totalCachedReadTokens) {
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();

    static SessionCompactionSignal unavailable() {
        return new SessionCompactionSignal(Map.of(), null);
    }

    static SessionCompactionSignal load(Path workspaceRoot, String workstreamId) {
        if (workspaceRoot == null || workstreamId == null || workstreamId.isBlank()) {
            return unavailable();
        }
        var metricsPath = workspaceRoot.resolve(".agent")
                .resolve("workstreams")
                .resolve(workstreamId)
                .resolve("metrics")
                .resolve("workstream-metrics.json");
        if (!Files.isRegularFile(metricsPath)) {
            return unavailable();
        }
        try {
            return from(OBJECT_MAPPER.readValue(metricsPath.toFile(), MAP_TYPE));
        } catch (IOException | RuntimeException ignored) {
            return unavailable();
        }
    }

    @SuppressWarnings("unchecked")
    static SessionCompactionSignal from(Map<String, Object> doc) {
        var tokenMetrics = doc.get("tokenMetrics") instanceof Map<?, ?> map
                ? (Map<String, Object>) map
                : Map.<String, Object>of();
        var total = tokenMetrics.get("total") instanceof Map<?, ?> map
                ? (Map<String, Object>) map
                : Map.<String, Object>of();
        var byAgent = tokenMetrics.get("byAgent") instanceof Map<?, ?> map
                ? (Map<String, Object>) map
                : Map.<String, Object>of();
        var out = new java.util.LinkedHashMap<String, Long>();
        for (var entry : byAgent.entrySet()) {
            if (entry.getValue() instanceof Map<?, ?> agentMetric) {
                out.put(normalizeAgent(entry.getKey()), longValue(((Map<String, Object>) agentMetric).get("cachedReadTokens"), 0));
            }
        }
        var totalCachedRead = total.containsKey("cachedReadTokens")
                ? longValue(total.get("cachedReadTokens"), 0)
                : null;
        return new SessionCompactionSignal(Map.copyOf(out), totalCachedRead);
    }

    long cachedReadTokensFor(String agent) {
        if (!cachedReadTokensByAgent.isEmpty()) {
            return cachedReadTokensByAgent.getOrDefault(normalizeAgent(agent), 0L);
        }
        return totalCachedReadTokens == null ? 0L : totalCachedReadTokens;
    }

    boolean available() {
        return !cachedReadTokensByAgent.isEmpty() || totalCachedReadTokens != null;
    }

    private static String normalizeAgent(String agent) {
        return agent == null ? "" : agent.trim().toLowerCase(Locale.ROOT);
    }

    private static long longValue(Object value, long defaultValue) {
        if (value instanceof Number number) {
            return number.longValue();
        }
        if (value != null) {
            try {
                return Long.parseLong(String.valueOf(value).trim());
            } catch (NumberFormatException ignored) {
                return defaultValue;
            }
        }
        return defaultValue;
    }
}

package dev.dual.adapter.acpx;

import java.nio.file.Path;

/**
 * 关闭一个 workstream 持有的 acpx provider session（P0 session 生命周期止损）。
 *
 * <p>实现必须：</p>
 * <ul>
 *     <li><b>永不抛异常</b>——session 清理是 best-effort，绝不能影响 workflow 主状态。</li>
 *     <li>只调用 {@code acpx <agent> sessions close}，不删除磁盘上的 session 文件。</li>
 *     <li>幂等：对已关闭的 session 再次关闭应为 no-op。</li>
 * </ul>
 *
 * <p>这层只做 session lifecycle cleanup，<b>不</b>解决 token 雪球（留 P1/P2 A/B）。</p>
 */
public interface WorkstreamSessionCloser {

    CloseSummary closeWorkstreamSessions(Path workspaceRoot, String workstreamId);

    /** 测试/回退用的 no-op 实现，不发起任何 acpx 调用。 */
    static WorkstreamSessionCloser noop() {
        return (root, workstreamId) -> new CloseSummary(workstreamId, 0, 0, 0);
    }

    /**
     * @param workstreamId     被清理的 workstream
     * @param distinctSessions 从 run ledger 读出的不同 (agent, session) 数
     * @param closed           成功 close 的数量
     * @param failed           close 失败（含异常）的数量
     */
    record CloseSummary(String workstreamId, int distinctSessions, int closed, int failed) {
    }
}

package dev.dual.adapter.acpx;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.provider.ProviderCachePolicy;
import dev.dual.core.provider.ProviderPricingCatalog;

import java.nio.file.Path;
import java.util.Locale;
import java.util.function.Function;

/**
 * Experimental session transcript compaction policy.
 *
 * <p>Default is off. When enabled, it changes only adapter execution session
 * naming and prompt seed inputs; workflow state and default session scope remain
 * unchanged.</p>
 */
final class SessionCompactionPolicy {
    static final String ENV = "DUAL_SESSION_COMPACTION_EXPERIMENT";
    static final String STABILITY_CACHED_READ_THRESHOLD_ENV = "DUAL_SESSION_COMPACTION_STABILITY_CACHED_READ_TOKENS";
    static final String IMPLEMENT_STABILITY_CACHED_READ_THRESHOLD_ENV =
            "DUAL_SESSION_COMPACTION_IMPLEMENT_STABILITY_CACHED_READ_TOKENS";
    private static final long DEFAULT_STABILITY_CACHED_READ_THRESHOLD = 1_000_000L;
    private static final long DEFAULT_IMPLEMENT_STABILITY_CACHED_READ_THRESHOLD = 500_000L;
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();

    enum Mode {
        OFF("off"),
        IMPLEMENT_BOUNDARY("implement_boundary"),
        CODEX_INCREMENTAL("codex_incremental"),
        BOTH("both"),
        PROVIDER_CACHE_AWARE("provider_cache_aware");

        private final String wire;

        Mode(String wire) {
            this.wire = wire;
        }

        String wire() {
            return wire;
        }
    }

    record Decision(
            Mode mode,
            boolean enabled,
            String sessionName,
            String segmentKey,
            String seedKind,
            String reason
    ) {
        static Decision off(String sessionName, String segmentKey) {
            return new Decision(Mode.OFF, false, sessionName, segmentKey, "", "default:off");
        }
    }

    Decision decide(
            String agent,
            String nodeId,
            String workstreamId,
            String runId,
            String baseSessionName,
            SessionScopePolicy.Decision baseDecision
    ) {
        return decide(agent, nodeId, workstreamId, runId, baseSessionName, baseDecision, null, SessionCompactionPolicy::lookup);
    }

    Decision decide(
            String agent,
            String nodeId,
            String workstreamId,
            String runId,
            String baseSessionName,
            SessionScopePolicy.Decision baseDecision,
            Path workspaceRoot
    ) {
        return decide(agent, nodeId, workstreamId, runId, baseSessionName, baseDecision, workspaceRoot, SessionCompactionPolicy::lookup);
    }

    Decision decide(
            String agent,
            String nodeId,
            String workstreamId,
            String runId,
            String baseSessionName,
            SessionScopePolicy.Decision baseDecision,
            Function<String, String> lookup
    ) {
        return decide(agent, nodeId, workstreamId, runId, baseSessionName, baseDecision, null, lookup);
    }

    Decision decide(
            String agent,
            String nodeId,
            String workstreamId,
            String runId,
            String baseSessionName,
            SessionScopePolicy.Decision baseDecision,
            Path workspaceRoot,
            Function<String, String> lookup
    ) {
        var configured = mode(lookup.apply(ENV));
        if (configured == Mode.OFF) {
            return Decision.off(baseDecision.sessionName(), baseDecision.segmentKey());
        }
        if (configured == Mode.PROVIDER_CACHE_AWARE) {
            var stabilityDecision = stabilityDecision(agent, nodeId, workstreamId, workspaceRoot, lookup);
            if (stabilityDecision.shouldCompact()) {
                return compactDecision(agent, nodeId, workstreamId, runId, baseSessionName, configured)
                        .map(decision -> new Decision(
                                decision.mode(),
                                true,
                                decision.sessionName(),
                                decision.segmentKey(),
                                decision.seedKind(),
                                "env:" + ENV + "=provider_cache_aware; stability_compaction; " + stabilityDecision.reason()
                        ))
                        .orElseGet(() -> notApplicable(baseDecision, "stability_compaction; " + stabilityDecision.reason()));
            }
            var cacheDecision = providerCacheDecision(agent, workspaceRoot, lookup);
            if (!"consider_compaction".equals(cacheDecision.recommendation())) {
                return new Decision(
                        Mode.PROVIDER_CACHE_AWARE,
                        false,
                        baseDecision.sessionName(),
                        baseDecision.segmentKey(),
                        "",
                        "env:" + ENV + "=provider_cache_aware; " + cacheDecision.recommendation() + "; " + cacheDecision.reason()
                );
            }
            return compactDecision(agent, nodeId, workstreamId, runId, baseSessionName, configured)
                    .orElseGet(() -> notApplicable(baseDecision, cacheDecision.recommendation() + "; " + cacheDecision.reason()));
        }
        return compactDecision(agent, nodeId, workstreamId, runId, baseSessionName, configured)
                .orElseGet(() -> Decision.off(baseDecision.sessionName(), baseDecision.segmentKey()));
    }

    private static StabilityDecision stabilityDecision(
            String agent,
            String nodeId,
            String workstreamId,
            Path workspaceRoot,
            Function<String, String> lookup
    ) {
        if (workspaceRoot == null || workstreamId == null || workstreamId.isBlank()) {
            return StabilityDecision.off("metrics unavailable");
        }
        var threshold = longValue(
                lookup.apply(STABILITY_CACHED_READ_THRESHOLD_ENV),
                DEFAULT_STABILITY_CACHED_READ_THRESHOLD
        );
        var signal = SessionCompactionSignal.load(workspaceRoot, workstreamId);
        if (!signal.available()) {
            return StabilityDecision.off("metrics unavailable");
        }
        var cachedRead = signal.cachedReadTokensFor(agent);
        if (threshold > 0 && cachedRead >= threshold) {
            return new StabilityDecision(
                    true,
                    "cachedReadTokens=" + cachedRead + " >= " + threshold
            );
        }
        var implementThreshold = longValue(
                lookup.apply(IMPLEMENT_STABILITY_CACHED_READ_THRESHOLD_ENV),
                DEFAULT_IMPLEMENT_STABILITY_CACHED_READ_THRESHOLD
        );
        if (implementThreshold > 0 && isClaudeImplementBoundary(agent, nodeId) && cachedRead >= implementThreshold) {
            return new StabilityDecision(
                    true,
                    "implement boundary cachedReadTokens=" + cachedRead + " >= " + implementThreshold
            );
        }
        if (threshold <= 0 && implementThreshold <= 0) {
            return StabilityDecision.off("stability threshold disabled");
        }
        return StabilityDecision.off("cachedReadTokens=" + cachedRead + " < " + threshold);
    }

    private static Decision notApplicable(SessionScopePolicy.Decision baseDecision, String reason) {
        return new Decision(
                Mode.PROVIDER_CACHE_AWARE,
                false,
                baseDecision.sessionName(),
                baseDecision.segmentKey(),
                "",
                "env:" + ENV + "=provider_cache_aware; not_applicable_for_node; " + reason
        );
    }

    private static java.util.Optional<Decision> compactDecision(
            String agent,
            String nodeId,
            String workstreamId,
            String runId,
            String baseSessionName,
            Mode configured
    ) {
        if (isClaudeImplementBoundary(agent, nodeId) &&
                (configured == Mode.IMPLEMENT_BOUNDARY || configured == Mode.BOTH || configured == Mode.PROVIDER_CACHE_AWARE)) {
            var suffix = SessionScopePolicy.safe(workstreamId) + "-compact-" + SessionScopePolicy.safe(nodeId);
            return java.util.Optional.of(new Decision(
                    configured,
                    true,
                    baseSessionName + "-" + suffix,
                    "ws:" + workstreamId + "/compact:" + nodeId,
                    "agent_handoff",
                    "env:" + ENV + "=" + configured.wire() + "; implement boundary compaction"
            ));
        }
        if (isCodexReview(agent, nodeId) &&
                (configured == Mode.CODEX_INCREMENTAL || configured == Mode.BOTH || configured == Mode.PROVIDER_CACHE_AWARE)) {
            var suffix = SessionScopePolicy.safe(workstreamId) + "-compact-" + SessionScopePolicy.safe(runId);
            return java.util.Optional.of(new Decision(
                    configured,
                    true,
                    baseSessionName + "-" + suffix,
                    "ws:" + workstreamId + "/compact-run:" + runId,
                    "review_evidence_brief",
                    "env:" + ENV + "=" + configured.wire() + "; codex incremental review compaction"
            ));
        }
        return java.util.Optional.empty();
    }

    private static boolean isClaudeImplementBoundary(String agent, String nodeId) {
        return "claude".equals(agent) && (
                "implement.claude_implement".equals(nodeId)
                        || "implement.claude_self_test_report".equals(nodeId)
                        || "stage.claude_handoff".equals(nodeId)
        );
    }

    private static boolean isCodexReview(String agent, String nodeId) {
        return "codex".equals(agent) && nodeId != null && nodeId.contains("codex");
    }

    private static Mode mode(String raw) {
        var normalized = raw == null ? "" : raw.trim().toLowerCase(Locale.ROOT);
        return switch (normalized) {
            case "implement_boundary" -> Mode.IMPLEMENT_BOUNDARY;
            case "codex_incremental" -> Mode.CODEX_INCREMENTAL;
            case "both" -> Mode.BOTH;
            case "provider_cache_aware" -> Mode.PROVIDER_CACHE_AWARE;
            default -> Mode.OFF;
        };
    }

    private static ProviderCachePolicy.Decision providerCacheDecision(
            String agent,
            Path workspaceRoot,
            Function<String, String> lookup
    ) {
        var agentKey = agent == null ? "" : agent.trim().toUpperCase(Locale.ROOT);
        var runtimeMetadata = AcpxProviderMetadata.fromEnvironment(lookup, AcpxProviderMetadata.SOURCE_ENV);
        if (runtimeMetadata.isEmpty()) {
            runtimeMetadata = AcpxProviderMetadata.runtimeDefault();
        }
        var explicitProviderId = nonBlank(lookup.apply("DUAL_PROVIDER_ID_" + agentKey), lookup.apply("DUAL_PROVIDER_ID"));
        var explicitModel = nonBlank(lookup.apply("DUAL_MODEL_" + agentKey), lookup.apply("DUAL_MODEL"));
        var providerId = nonBlank(explicitProviderId, runtimeMetadata.providerId());
        var model = nonBlank(explicitModel, runtimeMetadata.model());
        if (providerId.isBlank() || model.isBlank() || workspaceRoot == null) {
            return new ProviderCachePolicy.Decision("measure_only", "", "provider/model pricing unavailable");
        }
        var price = ProviderPricingCatalog.load(workspaceRoot, OBJECT_MAPPER, lookup)
                .priceFor(providerId, model)
                .orElse(null);
        if (AcpxProviderMetadata.BILLING_SUBSCRIPTION_TOKENS.equals(runtimeMetadata.billingMode())
                && metadataMatches(runtimeMetadata, providerId, model)) {
            return new ProviderCachePolicy.Decision(
                    "measure_only",
                    "",
                    "subscription_token_only; cache economics are non-monetary; compaction controlled by stability thresholds"
            );
        }
        if (price == null) {
            return new ProviderCachePolicy.Decision("measure_only", "", "provider/model pricing unavailable");
        }
        return ProviderCachePolicy.decide(price.inputCacheHitPer1M(), price.inputCacheMissPer1M());
    }

    private static boolean metadataMatches(AcpxProviderMetadata metadata, String providerId, String model) {
        return metadata != null
                && metadata.providerId().equalsIgnoreCase(providerId == null ? "" : providerId)
                && modelMatches(metadata.model(), model);
    }

    private static boolean modelMatches(String metadataModel, String model) {
        if (metadataModel == null || metadataModel.isBlank() || model == null || model.isBlank()) {
            return false;
        }
        if (metadataModel.equalsIgnoreCase(model)) {
            return true;
        }
        if (model.endsWith("*")) {
            return metadataModel.regionMatches(true, 0, model, 0, model.length() - 1);
        }
        return false;
    }

    private static String lookup(String name) {
        var property = System.getProperty(name);
        return property == null || property.isBlank() ? System.getenv(name) : property;
    }

    private static String nonBlank(String first, String... fallbacks) {
        if (first != null && !first.isBlank()) {
            return first.trim();
        }
        if (fallbacks == null) {
            return "";
        }
        for (var fallback : fallbacks) {
            if (fallback != null && !fallback.isBlank()) {
                return fallback.trim();
            }
        }
        return "";
    }

    private static long longValue(Object value, long defaultValue) {
        if (value instanceof Number number) {
            return number.longValue();
        }
        if (value != null) {
            try {
                return Long.parseLong(String.valueOf(value).trim());
            } catch (NumberFormatException ignored) {
                return defaultValue;
            }
        }
        return defaultValue;
    }

    private record StabilityDecision(boolean shouldCompact, String reason) {
        static StabilityDecision off(String reason) {
            return new StabilityDecision(false, reason);
        }
    }

}

package dev.dual.adapter.acpx;

import dev.dual.core.execution.AdapterSignal;
import dev.dual.core.execution.ProcessResult;

import java.time.Duration;
import java.time.Instant;
import java.util.List;

public record AcpxRunResult(
        Instant startedAt,
        Instant finishedAt,
        List<String> command,
        List<AcpxExecutionEvent> executionTimeline,
        AcpxUsage usage,
        AcpxPromptCompletion promptCompletion,
        ProcessResult processResult,
        List<AdapterSignal> adapterSignals
) {
    public AcpxRunResult {
        command = command == null ? List.of() : List.copyOf(command);
        executionTimeline = executionTimeline == null ? List.of() : List.copyOf(executionTimeline);
        promptCompletion = promptCompletion == null ? AcpxPromptCompletion.EMPTY : promptCompletion;
        if (processResult == null) {
            throw new IllegalArgumentException("processResult is required");
        }
        adapterSignals = adapterSignals == null ? List.of() : List.copyOf(adapterSignals);
    }

    public int exitCode() {
        return processResult.exitCode() == null ? -1 : processResult.exitCode();
    }

    public List<AdapterSignal> activeAdapterSignals() {
        return adapterSignals.stream().filter(signal -> !signal.superseded()).toList();
    }

    public long durationMs() {
        return Duration.between(startedAt, finishedAt).toMillis();
    }

    public boolean reachedDeclaredTimeout(Duration grace) {
        var timeoutSeconds = declaredTimeoutSeconds();
        if (timeoutSeconds <= 0) {
            return false;
        }
        var thresholdMs = Duration.ofSeconds(timeoutSeconds).minus(grace).toMillis();
        return durationMs() >= Math.max(0, thresholdMs);
    }

    private long declaredTimeoutSeconds() {
        if (command == null) {
            return 0;
        }
        for (int i = 0; i < command.size() - 1; i++) {
            if (!"--timeout".equals(command.get(i))) {
                continue;
            }
            try {
                return Long.parseLong(command.get(i + 1));
            } catch (NumberFormatException ignored) {
                return 0;
            }
        }
        return 0;
    }

}

