package dev.dual.adapter.acpx;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.regex.Pattern;

/**
 * Per-run incremental reader for acpx stdout, stderr, and session stream events.
 *
 * stdout/stderr files are owned by one dual run, so they are consumed from byte
 * offset zero. acpx session streams are long-lived per acpx session, but acpx
 * can write recovery evidence before stderr exposes the session id. On first
 * discovery this reader consumes only a bounded tail so current session/new or
 * provider failure events can supersede wrapper reconnect text without loading
 * the whole session history.
 */
final class AgentLifecycleEventReader {
    private static final Pattern SESSION_ID_PATTERN = Pattern.compile(
            "\\(([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\\)"
    );
    private static final long INITIAL_STREAM_TAIL_BYTES = 128 * 1024;

    private final Path stdoutPath;
    private final Path stderrPath;
    private final Path sessionsDir;
    private final Map<String, Long> streamStartOffsets;
    private final boolean streamBaselineCaptured;
    private long stdoutOffset;
    private long stderrOffset;
    private long streamOffset = -1;
    private long sequence;
    private String sessionId;
    private boolean initialStreamTail;
    private byte[] pendingStreamBytes = new byte[0];
    private AcpxSessionStreamProjector streamProjector = new AcpxSessionStreamProjector();

    AgentLifecycleEventReader(Path stdoutPath, Path stderrPath) {
        this(stdoutPath, stderrPath, Path.of(System.getProperty("user.home"), ".acpx", "sessions"));
    }

    AgentLifecycleEventReader(Path stdoutPath, Path stderrPath, Path sessionsDir) {
        this(stdoutPath, stderrPath, sessionsDir, null);
    }

    AgentLifecycleEventReader(
            Path stdoutPath,
            Path stderrPath,
            Path sessionsDir,
            Map<String, Long> streamStartOffsets
    ) {
        this.stdoutPath = stdoutPath;
        this.stderrPath = stderrPath;
        this.sessionsDir = sessionsDir;
        this.streamBaselineCaptured = streamStartOffsets != null;
        this.streamStartOffsets = streamStartOffsets == null ? Map.of() : Map.copyOf(streamStartOffsets);
    }

    List<AgentLifecycleEvent> readNewEvents() {
        var events = new ArrayList<AgentLifecycleEvent>();
        readNewText(stdoutPath, stdoutOffset).ifPresent(chunk -> {
            stdoutOffset += chunk.bytesRead();
            for (var line : chunk.text().lines().toList()) {
                events.add(AgentLifecycleEvent.stdoutLine(sequence++, line));
            }
        });
        readNewText(stderrPath, stderrOffset).ifPresent(chunk -> {
            stderrOffset += chunk.bytesRead();
            updateSessionId(chunk.text());
            for (var line : chunk.text().lines().toList()) {
                events.add(AgentLifecycleEvent.stderrLine(sequence++, line));
            }
        });
        streamPath().ifPresent(path -> {
            initializeStreamOffset(path);
            readNewBytes(path, streamOffset).ifPresent(chunk -> {
                var initialTail = initialStreamTail;
                initialStreamTail = false;
                streamOffset += chunk.bytesRead();
                for (var line : completeStreamLines(chunk.bytes())) {
                    var event = streamProjector.accept(
                            sequence++, AcpxStreamWireLine.parse(line), !initialTail);
                    event.filter(value -> !initialTail || value.kind() != AgentLifecycleEvent.Kind.PROVIDER_FAILURE)
                            .ifPresent(events::add);
                }
            });
        });
        return events;
    }

    long nextSequence() {
        return sequence++;
    }

    AcpxPromptCompletion promptCompletion() {
        return streamProjector.promptCompletion();
    }

    private void updateSessionId(String text) {
        var matcher = SESSION_ID_PATTERN.matcher(text == null ? "" : text);
        while (matcher.find()) {
            var discovered = matcher.group(1);
            if (!discovered.equals(sessionId)) {
                sessionId = discovered;
                streamOffset = -1;
                initialStreamTail = false;
                pendingStreamBytes = new byte[0];
                streamProjector = new AcpxSessionStreamProjector();
            }
        }
    }

    private Optional<Path> streamPath() {
        if (sessionId == null || sessionId.isBlank()) {
            return Optional.empty();
        }
        if (streamBaselineCaptured
                && !streamStartOffsets.isEmpty()
                && !streamStartOffsets.containsKey(sessionId)) {
            return Optional.empty();
        }
        var path = sessionsDir.resolve(sessionId + ".stream.ndjson");
        return Files.isRegularFile(path) ? Optional.of(path) : Optional.empty();
    }

    private void initializeStreamOffset(Path path) {
        if (streamOffset >= 0) {
            return;
        }
        try {
            var size = Files.size(path);
            if (streamBaselineCaptured) {
                streamOffset = Math.min(size, Math.max(0, streamStartOffsets.getOrDefault(sessionId, 0L)));
                initialStreamTail = false;
                return;
            }
            streamOffset = Math.max(0, size - INITIAL_STREAM_TAIL_BYTES);
            initialStreamTail = streamOffset < size;
        } catch (IOException ignored) {
            streamOffset = 0;
            initialStreamTail = false;
        }
    }

    private Optional<Chunk> readNewText(Path path, long offset) {
        return readNewBytes(path, offset)
                .map(chunk -> new Chunk(new String(chunk.bytes(), StandardCharsets.UTF_8), chunk.bytesRead()));
    }

    private Optional<ByteChunk> readNewBytes(Path path, long offset) {
        if (path == null || !Files.isRegularFile(path)) {
            return Optional.empty();
        }
        try {
            var size = Files.size(path);
            if (size <= offset) {
                return Optional.empty();
            }
            var bytesToRead = size - offset;
            if (bytesToRead > Integer.MAX_VALUE) {
                offset = size - Integer.MAX_VALUE;
                bytesToRead = Integer.MAX_VALUE;
            }
            var buffer = ByteBuffer.allocate((int) bytesToRead);
            var bytesRead = 0;
            try (var channel = Files.newByteChannel(path, StandardOpenOption.READ)) {
                channel.position(offset);
                while (buffer.hasRemaining()) {
                    var count = channel.read(buffer);
                    if (count <= 0) {
                        break;
                    }
                    bytesRead += count;
                }
            }
            return bytesRead == 0
                    ? Optional.empty()
                    : Optional.of(new ByteChunk(Arrays.copyOf(buffer.array(), bytesRead), bytesRead));
        } catch (IOException ignored) {
            return Optional.empty();
        }
    }

    private List<String> completeStreamLines(byte[] chunk) {
        var incoming = chunk == null ? new byte[0] : chunk;
        var combined = Arrays.copyOf(pendingStreamBytes, pendingStreamBytes.length + incoming.length);
        System.arraycopy(incoming, 0, combined, pendingStreamBytes.length, incoming.length);
        var lastNewline = -1;
        for (int index = combined.length - 1; index >= 0; index--) {
            if (combined[index] == '\n') {
                lastNewline = index;
                break;
            }
        }
        if (lastNewline < 0) {
            pendingStreamBytes = combined;
            return List.of();
        }
        pendingStreamBytes = Arrays.copyOfRange(combined, lastNewline + 1, combined.length);
        var lines = new ArrayList<String>();
        var lineStart = 0;
        for (int index = 0; index <= lastNewline; index++) {
            if (combined[index] != '\n') {
                continue;
            }
            var lineEnd = index > lineStart && combined[index - 1] == '\r' ? index - 1 : index;
            lines.add(new String(combined, lineStart, lineEnd - lineStart, StandardCharsets.UTF_8));
            lineStart = index + 1;
        }
        return List.copyOf(lines);
    }

    private record Chunk(String text, long bytesRead) {
    }

    private record ByteChunk(byte[] bytes, long bytesRead) {
    }
}

package dev.dual.adapter.acpx;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * P0 session 生命周期止损：读取一个 workstream 的 run ledger，对其用过的每个
 * (agent, session) 调用 {@code acpx <agent> sessions close}。
 *
 * <p>设计要点：</p>
 * <ul>
 *     <li>session 名直接来自各 {@code runs/<runId>/run.json} 的 {@code agent}+{@code session}
 *     字段——即 adapter 实际开过的 session，不靠反推命名规则。</li>
 *     <li>整个方法 <b>永不抛异常</b>：任何 run 读不出、acpx 不可用、close 失败都计入 failed，
 *     绝不影响 workflow 状态。</li>
 *     <li>只调 {@code acpx sessions close}，不删 {@code ~/.acpx/sessions} 文件。</li>
 *     <li>把清理结果追加写入 {@code session-cleanup.log}，方便追踪。</li>
 * </ul>
 *
 * <p>本类只做 lifecycle cleanup，不解决 token 雪球。</p>
 */
public final class AcpxSessionLifecycle implements WorkstreamSessionCloser {

    private static final Set<String> SUPPORTED_AGENTS = Set.of("claude", "codex");

    private final AcpxAgentTransport transport;
    private final ObjectMapper objectMapper = new ObjectMapper();

    public AcpxSessionLifecycle() {
        this(new AcpxAgentTransport());
    }

    public AcpxSessionLifecycle(AcpxAgentTransport transport) {
        this.transport = transport;
    }

    @Override
    public CloseSummary closeWorkstreamSessions(Path workspaceRoot, String workstreamId) {
        var targets = collectSessionTargets(workspaceRoot, workstreamId);
        int closed = 0;
        int failed = 0;
        for (SessionTarget target : targets) {
            try {
                if (transport.closeSession(target.agent, workspaceRoot, target.session)) {
                    closed++;
                } else {
                    failed++;
                }
            } catch (RuntimeException ignored) {
                failed++;
            }
        }
        writeDiagnostic(workspaceRoot, workstreamId, targets, closed, failed);
        return new CloseSummary(workstreamId, targets.size(), closed, failed);
    }

    private List<SessionTarget> collectSessionTargets(Path workspaceRoot, String workstreamId) {
        var runsDir = workspaceRoot.resolve(".agent").resolve("workstreams").resolve(workstreamId).resolve("runs");
        var targets = new LinkedHashSet<SessionTarget>();
        if (!Files.isDirectory(runsDir)) {
            return List.of();
        }
        try (var stream = Files.list(runsDir)) {
            for (var runDir : stream.filter(Files::isDirectory).toList()) {
                var runJson = runDir.resolve("run.json");
                if (!Files.isRegularFile(runJson)) {
                    continue;
                }
                readTarget(runJson).ifPresent(targets::add);
            }
        } catch (IOException ignored) {
            // runs dir unreadable: nothing to close
        }
        return new ArrayList<>(targets);
    }

    private java.util.Optional<SessionTarget> readTarget(Path runJson) {
        try {
            JsonNode node = objectMapper.readTree(runJson.toFile());
            var agent = text(node.get("agent"));
            var session = text(node.get("session"));
            if (SUPPORTED_AGENTS.contains(agent) && !session.isBlank()) {
                return java.util.Optional.of(new SessionTarget(agent, session));
            }
        } catch (IOException ignored) {
            // skip unreadable run.json
        }
        return java.util.Optional.empty();
    }

    private void writeDiagnostic(Path workspaceRoot, String workstreamId,
                                 List<SessionTarget> targets, int closed, int failed) {
        var logPath = workspaceRoot.resolve(".agent").resolve("workstreams")
                .resolve(workstreamId).resolve("session-cleanup.log");
        try {
            Files.createDirectories(logPath.getParent());
            var builder = new StringBuilder()
                    .append("session-cleanup workstream=").append(workstreamId)
                    .append(" distinct=").append(targets.size())
                    .append(" closed=").append(closed)
                    .append(" failed=").append(failed)
                    .append(System.lineSeparator());
            for (var target : targets) {
                builder.append("  ").append(target.agent).append(' ').append(target.session)
                        .append(System.lineSeparator());
            }
            Files.writeString(logPath, builder.toString(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        } catch (IOException ignored) {
            // diagnostic is best-effort
        }
    }

    private static String text(JsonNode node) {
        return node == null || node.isNull() ? "" : node.asText("").trim();
    }

    record SessionTarget(String agent, String session) {
    }
}

package dev.dual.adapter.acpx;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.Optional;
import java.util.regex.Pattern;

/**
 * Extracts adapter-level tool telemetry from an acpx transcript.
 *
 * This reader intentionally produces execution facts only. Workflow routing and
 * product acceptance must continue to use typed artifacts and ledger state, not
 * these transcript heuristics.
 */
final class AcpxTranscriptToolUsageReader {
    private static final Pattern JSON_TOOL = Pattern.compile(
            "\"(?:name|tool|tool_name|toolName)\"\\s*:\\s*\"(?<tool>Read|Edit|Write|MultiEdit|Glob|Grep|Bash|LS|Task)\"",
            Pattern.CASE_INSENSITIVE
    );
    private static final Pattern TEXT_TOOL = Pattern.compile(
            "^\\s*(?:tool[_ -]?use\\s*)?(?<tool>Read|Edit|Write|MultiEdit|Glob|Grep|Bash|LS|Task)\\s*(?:\\(|\\{|:|$)",
            Pattern.CASE_INSENSITIVE
    );
    private static final Pattern PATH_VALUE = Pattern.compile(
            "\"(?:file_path|path|notebook_path)\"\\s*:\\s*\"(?<path>[^\"\\\\]*(?:\\\\.[^\"\\\\]*)*)\""
    );
    private static final Pattern COMMAND_VALUE = Pattern.compile(
            "\"command\"\\s*:\\s*\"(?<command>[^\"\\\\]*(?:\\\\.[^\"\\\\]*)*)\""
    );
    private static final Pattern COMMAND_ARRAY = Pattern.compile(
            "\"command\"\\s*:\\s*\\[(?<command>[^]]*)]"
    );
    private static final Pattern JSON_STRING = Pattern.compile("\"(?<value>[^\"\\\\]*(?:\\\\.[^\"\\\\]*)*)\"");
    private static final Pattern BRACKET_TOOL = Pattern.compile(
            "^\\s*\\[tool]\\s*(?<body>.*?)\\s*\\((?<state>pending|running|completed)\\)\\s*$",
            Pattern.CASE_INSENSITIVE
    );
    private static final Pattern INPUT_LINE = Pattern.compile("^\\s*input:\\s*(?<body>.*)$", Pattern.CASE_INSENSITIVE);

    AcpxToolUsage read(Path transcriptPath, Path workspaceRoot) throws IOException {
        if (transcriptPath == null || !Files.isRegularFile(transcriptPath)) {
            return AcpxToolUsage.empty();
        }
        var byTool = new LinkedHashMap<String, Integer>();
        var toolIds = new LinkedHashSet<String>();
        var readFiles = new LinkedHashSet<String>();
        var directReadFiles = new LinkedHashSet<String>();
        var writeFiles = new LinkedHashSet<String>();
        var bashCommands = new LinkedHashSet<String>();
        var commandExecutables = new LinkedHashSet<String>();
        PendingTool pending = null;
        for (var line : Files.readAllLines(transcriptPath, StandardCharsets.UTF_8)) {
            var bracketTool = bracketToolIn(line, workspaceRoot);
            if (bracketTool.isPresent()) {
                if (pending != null) {
                    record(pending, byTool, toolIds, readFiles, directReadFiles, writeFiles, bashCommands, commandExecutables);
                }
                pending = bracketTool.get();
                if (pending.hasEvidence()) {
                    record(pending, byTool, toolIds, readFiles, directReadFiles, writeFiles, bashCommands, commandExecutables);
                    pending = null;
                }
                continue;
            }
            if (pending != null && mergeInputLine(pending, line, workspaceRoot)) {
                record(pending, byTool, toolIds, readFiles, directReadFiles, writeFiles, bashCommands, commandExecutables);
                pending = null;
                continue;
            }
            if (pending != null && !line.trim().isBlank()) {
                record(pending, byTool, toolIds, readFiles, directReadFiles, writeFiles, bashCommands, commandExecutables);
                pending = null;
            }
            consumeLine(line, workspaceRoot, byTool, toolIds, readFiles, directReadFiles, writeFiles, bashCommands, commandExecutables);
        }
        if (pending != null) {
            record(pending, byTool, toolIds, readFiles, directReadFiles, writeFiles, bashCommands, commandExecutables);
        }
        var readCount = countMatching(byTool, "Read", "Glob", "Grep", "LS");
        var writeCount = countMatching(byTool, "Edit", "Write", "MultiEdit");
        var bashCount = countMatching(byTool, "Bash");
        var total = byTool.values().stream().mapToInt(Integer::intValue).sum();
        var known = readCount + writeCount + bashCount + countMatching(byTool, "Task");
        return new AcpxToolUsage(
                1,
                total,
                readCount,
                writeCount,
                bashCount,
                Math.max(0, total - known),
                Map.copyOf(byTool),
                List.copyOf(toolIds),
                List.copyOf(readFiles),
                List.copyOf(directReadFiles),
                List.copyOf(writeFiles),
                List.copyOf(bashCommands),
                List.copyOf(commandExecutables)
        );
    }

    private static void consumeLine(
            String line,
            Path workspaceRoot,
            Map<String, Integer> byTool,
            Set<String> toolIds,
            Set<String> readFiles,
            Set<String> directReadFiles,
            Set<String> writeFiles,
            Set<String> bashCommands,
            Set<String> commandExecutables
    ) {
        var tools = toolsIn(line);
        if (tools.isEmpty()) {
            return;
        }
        var paths = new LinkedHashSet<>(pathsIn(line, workspaceRoot));
        for (var tool : tools) {
            var behaviorTool = tool;
            toolIds.add(tool);
            if ("Bash".equals(tool)) {
                var command = commandIn(line);
                if (command.isPresent()) {
                    recordCommand(command.get(), bashCommands, commandExecutables);
                    behaviorTool = classifyCommand(command.get()).orElse("Bash");
                    commandPath(behaviorTool, command.get(), workspaceRoot).ifPresent(paths::add);
                }
            }
            byTool.merge(behaviorTool, 1, Integer::sum);
            if (isReadTool(behaviorTool)) {
                readFiles.addAll(paths);
                if (isDirectReadTool(behaviorTool)) {
                    directReadFiles.addAll(paths);
                }
            } else if (isWriteTool(behaviorTool)) {
                writeFiles.addAll(paths);
            }
        }
    }

    private static Optional<PendingTool> bracketToolIn(String line, Path workspaceRoot) {
        var matcher = BRACKET_TOOL.matcher(line);
        if (!matcher.find() || !"completed".equalsIgnoreCase(matcher.group("state"))) {
            return Optional.empty();
        }
        var body = matcher.group("body").trim();
        var toolId = toolIdFromBracketBody(body);
        var tool = toolFromBracketBody(body);
        var pending = new PendingTool(toolId, tool);
        pathsIn(body, workspaceRoot).forEach(pending::addPath);
        fallbackPathFromBody(tool, body, workspaceRoot).ifPresent(pending::addPath);
        if ("Bash".equals(tool) && !isGenericBashBody(body)) {
            pending.setCommand(body);
        }
        return Optional.of(pending);
    }

    private static boolean mergeInputLine(PendingTool pending, String line, Path workspaceRoot) {
        var matcher = INPUT_LINE.matcher(line);
        if (!matcher.find()) {
            return false;
        }
        var body = matcher.group("body");
        pathsIn(body, workspaceRoot).forEach(pending::addPath);
        commandIn(body).ifPresent(command -> {
            pending.setCommand(command);
            classifyCommand(command).ifPresent(pending::setTool);
            commandPath(pending.tool(), command, workspaceRoot).ifPresent(pending::addPath);
        });
        return true;
    }

    private static void record(
            PendingTool pending,
            Map<String, Integer> byTool,
            Set<String> toolIds,
            Set<String> readFiles,
            Set<String> directReadFiles,
            Set<String> writeFiles,
            Set<String> bashCommands,
            Set<String> commandExecutables
    ) {
        var tool = pending.tool();
        byTool.merge(tool, 1, Integer::sum);
        toolIds.add(pending.toolId());
        if (isReadTool(tool)) {
            readFiles.addAll(pending.paths());
            if (isDirectReadTool(tool)) {
                directReadFiles.addAll(pending.paths());
            }
        } else if (isWriteTool(tool)) {
            writeFiles.addAll(pending.paths());
        } else if ("Bash".equals(tool)) {
            pending.command().ifPresent(command -> recordCommand(command, bashCommands, commandExecutables));
        }
        pending.command().ifPresent(command -> executableIn(command).ifPresent(commandExecutables::add));
    }

    private static void recordCommand(String command, Set<String> bashCommands, Set<String> commandExecutables) {
        bashCommands.add(command);
        executableIn(command).ifPresent(commandExecutables::add);
    }

    private static List<String> toolsIn(String line) {
        var tools = new LinkedHashSet<String>();
        var json = JSON_TOOL.matcher(line);
        while (json.find()) {
            tools.add(canonicalTool(json.group("tool")));
        }
        var text = TEXT_TOOL.matcher(line);
        if (text.find()) {
            tools.add(canonicalTool(text.group("tool")));
        }
        return List.copyOf(tools);
    }

    private static List<String> pathsIn(String line, Path workspaceRoot) {
        var paths = new LinkedHashSet<String>();
        var matcher = PATH_VALUE.matcher(line);
        while (matcher.find()) {
            var normalized = normalizePath(unescapeJson(matcher.group("path")), workspaceRoot);
            if (!normalized.isBlank()) {
                paths.add(normalized);
            }
        }
        return List.copyOf(paths);
    }

    private static Optional<String> commandIn(String line) {
        var matcher = COMMAND_VALUE.matcher(line);
        if (matcher.find()) {
            var command = unescapeJson(matcher.group("command")).trim();
            return normalizedCommand(command);
        }
        var array = COMMAND_ARRAY.matcher(line);
        if (!array.find()) {
            return Optional.empty();
        }
        return commandFromArray(array.group("command"));
    }

    private static Optional<String> commandFromArray(String rawArray) {
        var values = new ArrayList<String>();
        var strings = JSON_STRING.matcher(rawArray);
        while (strings.find()) {
            values.add(unescapeJson(strings.group("value")));
        }
        if (values.isEmpty()) {
            return Optional.empty();
        }
        if (values.size() >= 3 && "-lc".equals(values.get(1))) {
            return normalizedCommand(values.get(2));
        }
        return normalizedCommand(String.join(" ", values));
    }

    private static Optional<String> normalizedCommand(String command) {
        if (command.length() > 240) {
            command = command.substring(0, 240) + "...";
        }
        return command.isBlank() ? Optional.empty() : Optional.of(command);
    }

    private static Optional<String> executableIn(String command) {
        var tokens = shellTokens(command);
        for (var token : tokens) {
            var text = unquote(token);
            if (text.isBlank() || text.contains("=") && text.indexOf('=') > 0 && !text.startsWith("./")) {
                continue;
            }
            if ("env".equals(text)) {
                continue;
            }
            return Optional.of(normalizeExecutable(text));
        }
        return Optional.empty();
    }

    private static List<String> shellTokens(String command) {
        var tokens = new ArrayList<String>();
        var current = new StringBuilder();
        char quote = 0;
        for (var i = 0; i < command.length(); i++) {
            var ch = command.charAt(i);
            if (quote != 0) {
                if (ch == quote) {
                    quote = 0;
                } else {
                    current.append(ch);
                }
                continue;
            }
            if (ch == '\'' || ch == '"') {
                quote = ch;
                continue;
            }
            if (Character.isWhitespace(ch)) {
                addShellToken(tokens, current);
                continue;
            }
            if (ch == '&' || ch == '|' || ch == ';') {
                addShellToken(tokens, current);
                break;
            }
            current.append(ch);
        }
        addShellToken(tokens, current);
        return List.copyOf(tokens);
    }

    private static void addShellToken(List<String> tokens, StringBuilder current) {
        if (!current.isEmpty()) {
            tokens.add(current.toString());
            current.setLength(0);
        }
    }

    private static String normalizeExecutable(String value) {
        var text = value.toLowerCase(Locale.ROOT);
        while (text.startsWith("./")) {
            text = text.substring(2);
        }
        var slash = text.lastIndexOf('/');
        return slash >= 0 ? text.substring(slash + 1) : text;
    }

    private static String toolFromBracketBody(String body) {
        var command = body.trim();
        return classifyCommand(command).orElse("Bash");
    }

    private static String toolIdFromBracketBody(String body) {
        var command = body.trim();
        return nativeToolId(command).orElse("Bash");
    }

    private static Optional<String> nativeToolId(String command) {
        var lower = command.trim().toLowerCase(Locale.ROOT);
        if (lower.equals("read file")) {
            return Optional.of("Read");
        }
        if (lower.equals("edit")) {
            return Optional.of("Edit");
        }
        if (lower.equals("write")) {
            return Optional.of("Write");
        }
        if (lower.equals("multiedit")) {
            return Optional.of("MultiEdit");
        }
        if (lower.equals("find") || lower.equals("glob")) {
            return Optional.of("Glob");
        }
        if (lower.equals("grep")) {
            return Optional.of("Grep");
        }
        if (lower.equals("ls")) {
            return Optional.of("LS");
        }
        if (lower.equals("task")) {
            return Optional.of("Task");
        }
        return Optional.empty();
    }

    private static Optional<String> classifyCommand(String command) {
        var normalized = command.trim();
        var lower = normalized.toLowerCase(Locale.ROOT);
        if (containsShellControlOperator(lower)) {
            return Optional.of("Bash");
        }
        var tokenTool = classifyCommandTokens(shellTokens(normalized));
        if (tokenTool.isPresent()) {
            return tokenTool;
        }
        if (lower.equals("read file") || lower.startsWith("read ") || lower.startsWith("rtk read ")) {
            return Optional.of("Read");
        }
        if (lower.startsWith("edit ")) {
            return Optional.of("Edit");
        }
        if (lower.startsWith("write ")) {
            return Optional.of("Write");
        }
        if (lower.startsWith("multiedit ")) {
            return Optional.of("MultiEdit");
        }
        if (lower.equals("find") || lower.startsWith("find ") || lower.startsWith("glob ") || lower.startsWith("rtk find ")) {
            return Optional.of("Glob");
        }
        if (lower.startsWith("grep ") || lower.startsWith("rg ") || lower.startsWith("rtk grep ")) {
            return Optional.of("Grep");
        }
        if (lower.equals("ls") || lower.startsWith("ls ") || lower.startsWith("rtk ls ")) {
            return Optional.of("LS");
        }
        if (lower.startsWith("task ")) {
            return Optional.of("Task");
        }
        return Optional.empty();
    }

    private static Optional<String> classifyCommandTokens(List<String> tokens) {
        if (tokens.isEmpty()) {
            return Optional.empty();
        }
        var executable = normalizeExecutable(unquote(tokens.get(0)));
        var commandIndex = 0;
        if ("rtk".equals(executable)) {
            if (tokens.size() < 2) {
                return Optional.empty();
            }
            executable = normalizeExecutable(unquote(tokens.get(1)));
            commandIndex = 1;
        }
        return switch (executable) {
            case "read" -> tokens.size() > commandIndex + 1 ? Optional.of("Read") : Optional.empty();
            case "edit" -> tokens.size() > commandIndex + 1 ? Optional.of("Edit") : Optional.empty();
            case "write" -> tokens.size() > commandIndex + 1 ? Optional.of("Write") : Optional.empty();
            case "multiedit" -> tokens.size() > commandIndex + 1 ? Optional.of("MultiEdit") : Optional.empty();
            case "find", "glob" -> Optional.of("Glob");
            case "grep", "rg" -> Optional.of("Grep");
            case "ls" -> Optional.of("LS");
            case "task" -> tokens.size() > commandIndex + 1 ? Optional.of("Task") : Optional.empty();
            default -> Optional.empty();
        };
    }

    private static boolean containsShellControlOperator(String command) {
        return command.contains("&&") || command.contains("||") || command.contains(";") || command.contains("|");
    }

    private static Optional<String> fallbackPathFromBody(String tool, String body, Path workspaceRoot) {
        if (!isReadTool(tool) && !isWriteTool(tool)) {
            return Optional.empty();
        }
        if ("read file".equalsIgnoreCase(body.trim())) {
            return Optional.empty();
        }
        return commandPath(tool, body, workspaceRoot);
    }

    private static boolean isGenericBashBody(String body) {
        var normalized = body.trim().toLowerCase(Locale.ROOT);
        return "bash".equals(normalized) || "terminal".equals(normalized);
    }

    private static Optional<String> commandPath(String behaviorTool, String command, Path workspaceRoot) {
        var parts = command.trim().split("\\s+");
        if (parts.length == 0) {
            return Optional.empty();
        }
        var index = pathArgumentIndex(behaviorTool, parts);
        while (index >= 0 && index < parts.length && parts[index].startsWith("-")) {
            index++;
        }
        if (index < 0 || index >= parts.length) {
            return Optional.empty();
        }
        var path = normalizePath(unquote(parts[index]), workspaceRoot);
        return path.isBlank() ? Optional.empty() : Optional.of(path);
    }

    private static int pathArgumentIndex(String behaviorTool, String[] parts) {
        if ("Grep".equals(behaviorTool)) {
            return grepPathArgumentIndex(parts);
        }
        if (parts.length >= 3 && isCommand(parts[0], "rtk")) {
            return 2;
        }
        if (parts.length >= 2) {
            return 1;
        }
        return -1;
    }

    private static int grepPathArgumentIndex(String[] parts) {
        if (parts.length < 3) {
            return -1;
        }
        var commandIndex = isCommand(parts[0], "rtk") ? 1 : 0;
        if (commandIndex >= parts.length || !isGrepExecutable(parts[commandIndex])) {
            return -1;
        }
        for (var index = parts.length - 1; index > commandIndex; index--) {
            var value = unquote(parts[index]);
            if (!value.isBlank() && !value.startsWith("-")) {
                return index;
            }
        }
        return -1;
    }

    private static boolean isGrepExecutable(String value) {
        return isCommand(value, "grep") || isCommand(value, "rg");
    }

    private static boolean isCommand(String value, String expected) {
        return normalizeExecutable(value).equals(expected);
    }

    private static String unquote(String text) {
        if ((text.startsWith("`") && text.endsWith("`"))) {
            return text.substring(1, text.length() - 1);
        }
        if ((text.startsWith("\"") && text.endsWith("\"")) || (text.startsWith("'") && text.endsWith("'"))) {
            return text.substring(1, text.length() - 1);
        }
        return text;
    }

    private static String canonicalTool(String tool) {
        return switch (tool.toLowerCase(Locale.ROOT)) {
            case "read" -> "Read";
            case "edit" -> "Edit";
            case "write" -> "Write";
            case "multiedit" -> "MultiEdit";
            case "glob" -> "Glob";
            case "grep" -> "Grep";
            case "bash" -> "Bash";
            case "ls" -> "LS";
            case "task" -> "Task";
            default -> tool;
        };
    }

    private static boolean isReadTool(String tool) {
        return "Read".equals(tool) || "Glob".equals(tool) || "Grep".equals(tool) || "LS".equals(tool);
    }

    private static boolean isDirectReadTool(String tool) {
        return "Read".equals(tool);
    }

    private static boolean isWriteTool(String tool) {
        return "Edit".equals(tool) || "Write".equals(tool) || "MultiEdit".equals(tool);
    }

    private static int countMatching(Map<String, Integer> byTool, String... tools) {
        var total = 0;
        for (var tool : tools) {
            total += byTool.getOrDefault(tool, 0);
        }
        return total;
    }

    private static String normalizePath(String raw, Path workspaceRoot) {
        var text = raw == null ? "" : raw.trim();
        if (text.isBlank()) {
            return "";
        }
        try {
            var path = Path.of(text);
            if (path.isAbsolute() && workspaceRoot != null) {
                var root = workspaceRoot.toAbsolutePath().normalize();
                var normalized = path.toAbsolutePath().normalize();
                if (normalized.startsWith(root)) {
                    return root.relativize(normalized).toString();
                }
            }
        } catch (RuntimeException ignored) {
            return stripRelativePrefix(text);
        }
        return stripRelativePrefix(text);
    }

    private static String stripRelativePrefix(String text) {
        while (text.startsWith("./")) {
            text = text.substring(2);
        }
        return text;
    }

    private static String unescapeJson(String text) {
        return text.replace("\\\"", "\"")
                .replace("\\/", "/")
                .replace("\\\\", "\\");
    }

    private static final class PendingTool {
        private final String toolId;
        private String tool;
        private final List<String> paths = new ArrayList<>();
        private String command;

        private PendingTool(String toolId, String tool) {
            this.toolId = toolId;
            this.tool = tool;
        }

        private String toolId() {
            return toolId;
        }

        private String tool() {
            return tool;
        }

        private void setTool(String tool) {
            this.tool = tool;
        }

        private List<String> paths() {
            return paths;
        }

        private void addPath(String path) {
            if (path != null && !path.isBlank() && !paths.contains(path)) {
                paths.add(path);
            }
        }

        private Optional<String> command() {
            return command == null || command.isBlank() ? Optional.empty() : Optional.of(command);
        }

        private void setCommand(String command) {
            normalizedCommand(command).ifPresent(value -> this.command = value);
        }

        private boolean hasEvidence() {
            return !paths.isEmpty() || command().isPresent();
        }
    }
}

package dev.dual.adapter.acpx;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.function.Function;
import java.util.regex.Pattern;

/**
 * acpx session-level provider metadata.
 *
 * <p>This is adapter metadata, not workflow state. The workflow never routes on model names, but
 * usage/cost projections need this metadata to avoid downgrading valid token usage to
 * {@code pricing_unknown}.</p>
 */
record AcpxProviderMetadata(String providerId, String model, String billingMode, String source) {
    static final String SOURCE_ACPX_SESSION_JSON = "acpx_session_json";
    static final String SOURCE_ENV = "env";
    static final String SOURCE_CLAUDE_SETTINGS_ENV = "claude_settings_env";
    static final String BILLING_METERED = "metered";
    static final String BILLING_SUBSCRIPTION_TOKENS = "subscription_token_only";

    private static final ObjectMapper MAPPER = new ObjectMapper();
    private static final Pattern DEFAULT_MODEL_PATTERN = Pattern.compile(
            "(?i)currently\\s+([A-Za-z0-9._/-]+(?:\\[[^\\]]+\\])?)"
    );
    private static final List<ProviderRule> PROVIDER_RULES = List.of(
            new ProviderRule("glm-", "zhipu", BILLING_SUBSCRIPTION_TOKENS),
            new ProviderRule("deepseek", "deepseek", BILLING_METERED),
            new ProviderRule("gpt-", "openai", BILLING_METERED),
            new ProviderRule("chatgpt", "openai", BILLING_METERED)
    );

    AcpxProviderMetadata {
        providerId = providerId == null ? "" : providerId;
        model = model == null ? "" : model;
        billingMode = billingMode == null ? "" : billingMode;
        source = source == null ? "" : source;
    }

    static AcpxProviderMetadata empty() {
        return new AcpxProviderMetadata("", "", "", "");
    }

    static AcpxProviderMetadata read(Path sessionJson) {
        if (sessionJson == null || !Files.isRegularFile(sessionJson)) {
            return empty();
        }
        try {
            return fromJson(MAPPER.readTree(sessionJson.toFile()));
        } catch (IOException ignored) {
            return empty();
        }
    }

    static AcpxProviderMetadata runtimeDefault() {
        var fromEnv = fromEnvironment(System::getenv, SOURCE_ENV);
        if (!fromEnv.isEmpty()) {
            return fromEnv;
        }
        var settingsPath = Path.of(
                firstNonBlank(System.getenv("CLAUDE_CONFIG_DIR"), Path.of(System.getProperty("user.home"), ".claude").toString()),
                "settings.json"
        );
        return fromClaudeSettings(settingsPath);
    }

    static AcpxProviderMetadata fromClaudeSettings(Path settingsJson) {
        if (settingsJson == null || !Files.isRegularFile(settingsJson)) {
            return empty();
        }
        try {
            var envNode = MAPPER.readTree(settingsJson.toFile()).get("env");
            return fromEnvironment(name -> text(envNode == null ? null : envNode.get(name)), SOURCE_CLAUDE_SETTINGS_ENV);
        } catch (IOException ignored) {
            return empty();
        }
    }

    static AcpxProviderMetadata fromEnvironment(Function<String, String> env, String source) {
        if (env == null) {
            return empty();
        }
        var explicitProvider = normalizeProvider(env.apply("DUAL_CLAUDE_PROVIDER"));
        var model = firstNonBlank(
                env.apply("DUAL_CLAUDE_MODEL"),
                env.apply("ANTHROPIC_MODEL"),
                env.apply("CLAUDE_CODE_MODEL"),
                env.apply("ANTHROPIC_DEFAULT_SONNET_MODEL"),
                env.apply("ANTHROPIC_DEFAULT_OPUS_MODEL"),
                env.apply("ANTHROPIC_DEFAULT_HAIKU_MODEL")
        );
        var providerFromModel = providerForModel(model);
        var providerFromBaseUrl = providerForBaseUrl(firstNonBlank(
                env.apply("DUAL_CLAUDE_BASE_URL"),
                env.apply("ANTHROPIC_BASE_URL")
        ));
        var provider = firstNonBlank(explicitProvider, providerFromModel, providerFromBaseUrl);
        var normalizedModel = normalizeModel(model);
        if (provider.isBlank() && normalizedModel.isBlank()) {
            return empty();
        }
        var billing = firstNonBlank(
                env.apply("DUAL_CLAUDE_BILLING_MODE"),
                billingForProvider(provider),
                billingForModel(normalizedModel)
        );
        return new AcpxProviderMetadata(provider, normalizedModel, billing, source);
    }

    static AcpxProviderMetadata fromJson(JsonNode root) {
        var model = configuredModel(root)
                .or(() -> currentModel(root))
                .or(() -> defaultModelFromDescription(root))
                .or(() -> firstKnownModelMention(root))
                .orElse("");
        if (model.isBlank()) {
            return empty();
        }
        return PROVIDER_RULES.stream()
                .filter(rule -> rule.matches(model))
                .findFirst()
                .map(rule -> new AcpxProviderMetadata(rule.providerId(), model, rule.billingMode(), SOURCE_ACPX_SESSION_JSON))
                .orElse(new AcpxProviderMetadata("", model, "", SOURCE_ACPX_SESSION_JSON));
    }

    boolean isEmpty() {
        return providerId.isBlank() && model.isBlank() && billingMode.isBlank();
    }

    private static Optional<String> currentModel(JsonNode root) {
        var raw = firstFieldText(root, "current_model_id");
        var normalized = normalizeModel(raw);
        if (normalized.isBlank() || "default".equalsIgnoreCase(normalized) || "auto".equalsIgnoreCase(normalized)) {
            return Optional.empty();
        }
        return Optional.of(normalized);
    }

    private static Optional<String> configuredModel(JsonNode root) {
        var options = root == null ? null : root.at("/acpx/config_options");
        if (options == null || !options.isArray()) {
            return Optional.empty();
        }
        for (var config : options) {
            if (!"model".equals(text(config.get("id")))) {
                continue;
            }
            var currentValue = text(config.get("currentValue"));
            var selected = selectedOption(config.get("options"), currentValue);
            if (selected.isEmpty()) {
                return Optional.empty();
            }
            var descriptionModel = modelFromDescription(text(selected.get().get("description")));
            if (descriptionModel.isPresent()) {
                return descriptionModel;
            }
            var name = normalizeModel(text(selected.get().get("name")));
            if (!name.isBlank() && PROVIDER_RULES.stream().anyMatch(rule -> rule.matches(name))) {
                return Optional.of(name);
            }
        }
        return Optional.empty();
    }

    private static Optional<JsonNode> selectedOption(JsonNode options, String currentValue) {
        if (options == null || !options.isArray()) {
            return Optional.empty();
        }
        for (var option : options) {
            if (text(option.get("value")).equals(currentValue)) {
                return Optional.of(option);
            }
        }
        return Optional.empty();
    }

    private static Optional<String> defaultModelFromDescription(JsonNode root) {
        for (var value : allText(root)) {
            var model = modelFromDescription(value);
            if (model.isPresent()) {
                return model;
            }
        }
        return Optional.empty();
    }

    private static Optional<String> modelFromDescription(String value) {
        var matcher = DEFAULT_MODEL_PATTERN.matcher(value == null ? "" : value);
        if (!matcher.find()) {
            return Optional.empty();
        }
        var model = normalizeModel(matcher.group(1));
        return model.isBlank() ? Optional.empty() : Optional.of(model);
    }

    private static Optional<String> firstKnownModelMention(JsonNode root) {
        for (var value : allText(root)) {
            var model = normalizeModel(value);
            if (PROVIDER_RULES.stream().anyMatch(rule -> rule.matches(model))) {
                return Optional.of(model);
            }
        }
        return Optional.empty();
    }

    private static List<String> allText(JsonNode root) {
        var out = new ArrayList<String>();
        collectText(root, out);
        return out;
    }

    private static void collectText(JsonNode node, List<String> out) {
        if (node == null || node.isMissingNode() || node.isNull()) {
            return;
        }
        if (node.isTextual()) {
            out.add(node.asText());
            return;
        }
        if (node.isContainerNode()) {
            node.elements().forEachRemaining(child -> collectText(child, out));
        }
    }

    private static String normalizeModel(String raw) {
        if (raw == null) {
            return "";
        }
        var value = raw.trim();
        var bracket = value.indexOf('[');
        if (bracket >= 0) {
            value = value.substring(0, bracket);
        }
        return value.replaceAll("[,.;:]+$", "").trim();
    }

    private static String normalizeProvider(String raw) {
        if (raw == null) {
            return "";
        }
        var value = raw.trim().toLowerCase(Locale.ROOT);
        if (value.equals("glm") || value.equals("zhipuai") || value.equals("bigmodel")) {
            return "zhipu";
        }
        return value;
    }

    private static String providerForModel(String model) {
        var normalized = normalizeModel(model);
        return PROVIDER_RULES.stream()
                .filter(rule -> rule.matches(normalized))
                .findFirst()
                .map(ProviderRule::providerId)
                .orElse("");
    }

    private static String providerForBaseUrl(String baseUrl) {
        if (baseUrl == null) {
            return "";
        }
        var value = baseUrl.toLowerCase(Locale.ROOT);
        if (value.contains("bigmodel") || value.contains("zhipu") || value.contains("glm")) {
            return "zhipu";
        }
        if (value.contains("deepseek")) {
            return "deepseek";
        }
        if (value.contains("openai")) {
            return "openai";
        }
        if (value.contains("anthropic")) {
            return "anthropic";
        }
        return "";
    }

    private static String billingForProvider(String provider) {
        return switch (provider == null ? "" : provider) {
            case "zhipu" -> BILLING_SUBSCRIPTION_TOKENS;
            case "deepseek", "openai", "anthropic" -> BILLING_METERED;
            default -> "";
        };
    }

    private static String billingForModel(String model) {
        return PROVIDER_RULES.stream()
                .filter(rule -> rule.matches(model))
                .findFirst()
                .map(ProviderRule::billingMode)
                .orElse("");
    }

    private static String firstNonBlank(String... values) {
        if (values == null) {
            return "";
        }
        for (var value : values) {
            if (value != null && !value.isBlank()) {
                return value.trim();
            }
        }
        return "";
    }

    private static String text(JsonNode node) {
        return node == null || node.isMissingNode() || node.isNull() ? "" : node.asText();
    }

    private static String firstFieldText(JsonNode node, String fieldName) {
        if (node == null || node.isMissingNode() || node.isNull()) {
            return "";
        }
        if (node.isObject()) {
            var direct = node.get(fieldName);
            if (direct != null && !direct.isNull()) {
                return direct.asText();
            }
            var fields = node.fields();
            while (fields.hasNext()) {
                var value = firstFieldText(fields.next().getValue(), fieldName);
                if (!value.isBlank()) {
                    return value;
                }
            }
        } else if (node.isArray()) {
            for (var child : node) {
                var value = firstFieldText(child, fieldName);
                if (!value.isBlank()) {
                    return value;
                }
            }
        }
        return "";
    }

    private record ProviderRule(String modelPrefix, String providerId, String billingMode) {
        boolean matches(String model) {
            return model != null && model.toLowerCase(Locale.ROOT).startsWith(modelPrefix);
        }
    }
}

package dev.dual.adapter.acpx;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

/**
 * Adapter-local wire view of one acpx session-stream NDJSON line.
 *
 * <p>This is the single owner of the top-level acpx JSON-RPC grammar. Consumers
 * receive typed request, result, notification, or error fields and must not
 * parse the raw NDJSON line again.</p>
 */
record AcpxStreamWireLine(
        Kind kind,
        String requestId,
        String method,
        Request request,
        Result result,
        Notification notification,
        Error error
) {
    private static final ObjectMapper MAPPER = new ObjectMapper();

    enum Kind {
        JSONRPC_ERROR,
        TYPED_FAILURE_EVENT,
        JSONRPC_OK,
        JSONRPC_REQUEST,
        NOTIFICATION,
        MALFORMED
    }

    record Request(
            String promptText,
            String permissionToolCallId,
            String permissionToolKind,
            String permissionTitle,
            String permissionCommand,
            List<String> permissionOptions
    ) {
        Request {
            promptText = promptText == null ? "" : promptText;
            permissionToolCallId = permissionToolCallId == null ? "" : permissionToolCallId;
            permissionToolKind = permissionToolKind == null ? "" : permissionToolKind;
            permissionTitle = permissionTitle == null ? "" : permissionTitle;
            permissionCommand = permissionCommand == null ? "" : permissionCommand;
            permissionOptions = permissionOptions == null ? List.of() : List.copyOf(permissionOptions);
        }
    }

    record Result(String sessionId, String stopReason, Usage usage, String permissionOutcome, String permissionOptionId) {
        Result {
            sessionId = sessionId == null ? "" : sessionId;
            stopReason = stopReason == null ? "" : stopReason;
            permissionOutcome = permissionOutcome == null ? "" : permissionOutcome;
            permissionOptionId = permissionOptionId == null ? "" : permissionOptionId;
        }
    }

    record Notification(
            String sessionId,
            String updateKind,
            String messageId,
            String contentType,
            String text,
            String toolCallId,
            String toolName,
            UsageUpdate usageUpdate
    ) {
        Notification {
            sessionId = sessionId == null ? "" : sessionId;
            updateKind = updateKind == null ? "" : updateKind;
            messageId = messageId == null ? "" : messageId;
            contentType = contentType == null ? "" : contentType;
            text = text == null ? "" : text;
            toolCallId = toolCallId == null ? "" : toolCallId;
            toolName = toolName == null ? "" : toolName;
        }
    }

    record Error(Integer code, String message, String dataMessage, String dataDetails) {
        Error {
            message = message == null ? "" : message;
            dataMessage = dataMessage == null ? "" : dataMessage;
            dataDetails = dataDetails == null ? "" : dataDetails;
        }
    }

    record Usage(
            long inputTokens,
            long outputTokens,
            long cachedReadTokens,
            long cachedWriteTokens,
            long totalTokens
    ) {
    }

    record UsageUpdate(long used, BigDecimal costAmount, String costCurrency) {
        UsageUpdate {
            costCurrency = costCurrency == null ? "" : costCurrency;
        }
    }

    static AcpxStreamWireLine parse(String line) {
        if (line == null) {
            return malformed();
        }
        var trimmed = line.strip();
        if (trimmed.isEmpty() || trimmed.charAt(0) != '{') {
            return malformed();
        }
        JsonNode node;
        try {
            node = MAPPER.readTree(trimmed);
        } catch (Exception ignored) {
            return malformed();
        }
        if (node == null || !node.isObject()) {
            return malformed();
        }

        var requestId = id(node.get("id"));
        var method = text(node.get("method"));
        var errorNode = node.get("error");
        if (errorNode != null && errorNode.isObject()) {
            return new AcpxStreamWireLine(
                    Kind.JSONRPC_ERROR,
                    requestId,
                    method,
                    null,
                    null,
                    null,
                    error(errorNode)
            );
        }

        var type = text(node.get("type"));
        if (isTypedFailure(type, method, errorNode)) {
            var failureType = !type.isBlank() ? type : method;
            return new AcpxStreamWireLine(
                    Kind.TYPED_FAILURE_EVENT,
                    requestId,
                    methodForFailureType(failureType),
                    null,
                    null,
                    null,
                    new Error(null, textualError(node, errorNode), "", "")
            );
        }

        if (node.has("result")) {
            var resultNode = node.path("result");
            return new AcpxStreamWireLine(
                    Kind.JSONRPC_OK,
                    requestId,
                    method,
                    null,
                    new Result(
                            text(resultNode.get("sessionId")),
                            text(resultNode.get("stopReason")),
                            usage(resultNode.get("usage")),
                            text(resultNode.at("/outcome/outcome")),
                            text(resultNode.at("/outcome/optionId"))
                    ),
                    null,
                    null
            );
        }

        if (!method.isBlank() && !requestId.isBlank()) {
            return new AcpxStreamWireLine(
                    Kind.JSONRPC_REQUEST,
                    requestId,
                    method,
                    new Request(
                            text(node.at("/params/prompt/0/text")),
                            text(node.at("/params/toolCall/toolCallId")),
                            text(node.at("/params/toolCall/kind")),
                            text(node.at("/params/toolCall/title")),
                            permissionResource(node.at("/params/toolCall/rawInput")),
                            strings(node.at("/params/options"), "optionId")
                    ),
                    null,
                    null,
                    null
            );
        }

        if (!method.isBlank()) {
            var update = node.at("/params/update");
            var updateKind = text(update.get("sessionUpdate"));
            return new AcpxStreamWireLine(
                    Kind.NOTIFICATION,
                    "",
                    method,
                    null,
                    null,
                    new Notification(
                            text(node.at("/params/sessionId")),
                            updateKind,
                            text(update.get("messageId")),
                            text(update.at("/content/type")),
                            text(update.at("/content/text")),
                            text(update.get("toolCallId")),
                            text(update.at("/_meta/claudeCode/toolName")),
                            usageUpdate(updateKind, update)
                    ),
                    null
            );
        }
        return malformed();
    }

    private static Error error(JsonNode errorNode) {
        var data = errorNode.path("data");
        var code = errorNode.get("code");
        return new Error(
                code != null && code.isInt() ? code.asInt() : null,
                text(errorNode.get("message")),
                text(data.get("message")),
                text(data.get("details"))
        );
    }

    private static String permissionResource(JsonNode rawInput) {
        if (rawInput == null || !rawInput.isObject()) {
            return "";
        }
        var command = text(rawInput.get("command"));
        return command.isBlank() ? text(rawInput.get("query")) : command;
    }

    private static Usage usage(JsonNode usage) {
        if (usage == null || !usage.isObject()) {
            return null;
        }
        return new Usage(
                number(usage.get("inputTokens")),
                number(usage.get("outputTokens")),
                number(usage.get("cachedReadTokens")),
                number(usage.get("cachedWriteTokens")),
                number(usage.get("totalTokens"))
        );
    }

    private static UsageUpdate usageUpdate(String updateKind, JsonNode update) {
        if (!"usage_update".equals(updateKind)) {
            return null;
        }
        var cost = update.path("cost");
        return new UsageUpdate(
                number(update.get("used")),
                decimal(cost.get("amount")),
                text(cost.get("currency"))
        );
    }

    private static boolean isTypedFailure(String type, String method, JsonNode errorNode) {
        return (type != null && type.endsWith("/failed"))
                || (method != null && method.endsWith("/failed") && errorNode != null && errorNode.isTextual());
    }

    private static String textualError(JsonNode node, JsonNode errorNode) {
        if (errorNode != null && errorNode.isTextual()) {
            return errorNode.asText();
        }
        return text(node.get("message"));
    }

    private static String methodForFailureType(String type) {
        return type == null ? "" : type.substring(0, type.length() - "/failed".length());
    }

    private static String id(JsonNode node) {
        return node == null || node.isNull() || (!node.isTextual() && !node.isNumber()) ? "" : node.asText();
    }

    private static String text(JsonNode node) {
        return node == null || node.isMissingNode() || node.isNull() ? "" : node.asText();
    }

    private static long number(JsonNode node) {
        return node == null || !node.isNumber() ? 0 : node.asLong();
    }

    private static BigDecimal decimal(JsonNode node) {
        return node == null || !node.isNumber() ? null : node.decimalValue();
    }

    private static List<String> strings(JsonNode node, String field) {
        if (node == null || !node.isArray()) {
            return List.of();
        }
        var values = new ArrayList<String>();
        for (var item : node) {
            var value = text(item.get(field));
            if (!value.isBlank()) {
                values.add(value);
            }
        }
        return List.copyOf(values);
    }

    private static AcpxStreamWireLine malformed() {
        return new AcpxStreamWireLine(Kind.MALFORMED, "", "", null, null, null, null);
    }
}

package dev.dual.adapter.acpx;

/**
 * 集中的 acpx session 命名 + per-agent scope 解析（P1 A/B 能力）。
 *
 * <p>这是 session name 的唯一拼装点：handler / CLI / UI 都不应再自己拼字符串。</p>
 *
 * <p>关键约束：</p>
 * <ul>
 *     <li>默认 scope 是 {@link Scope#WORKSTREAM}，且其 session name 与 P1 前的实现
 *     <b>逐字节一致</b>（{@code base + "-" + safe(workstreamId)}），不配置任何 env 时行为不变。</li>
 *     <li>session name 恒包含 workstreamId（RUN scope 用 runId），<b>永不</b>出现裸 base 名
 *     （如 {@code claude-main}），杜绝跨 task 泄漏。</li>
 *     <li>{@code stage} 来自 workflow 的语义 {@code stageId}，{@code iteration} 来自语义
 *     {@code iterationId}（语义修复轮），不靠 node id 子串猜。</li>
 *     <li>stage / iteration 无法可靠获取时，<b>显式</b> fallback 到 workstream 并给出 reason，
 *     不静默乱拼。</li>
 *     <li>非法 env 值：fallback 到 workstream + 明确 reason（不静默变成 workstream）。</li>
 * </ul>
 */
public final class SessionScopePolicy {

    public enum Scope {
        WORKSTREAM("workstream"),
        STAGE("stage"),
        STAGE_ITERATION("stage_iteration"),
        RUN("run");

        private final String wire;

        Scope(String wire) {
            this.wire = wire;
        }

        public String wire() {
            return wire;
        }

        static Scope fromWire(String value) {
            return switch (value == null ? "" : value.trim()) {
                case "workstream" -> WORKSTREAM;
                case "stage" -> STAGE;
                case "stage_iteration" -> STAGE_ITERATION;
                case "run" -> RUN;
                default -> throw new IllegalArgumentException("unsupported session scope: " + value);
            };
        }
    }

    /** 一次 session 命名决策：实际 name + 用的 scope + 人类可读 segment key + reason。 */
    public record Decision(String sessionName, Scope scope, String segmentKey, String reason) {
    }

    private static final String ENV_CLAUDE = "DUAL_SESSION_SCOPE_CLAUDE";
    private static final String ENV_CODEX = "DUAL_SESSION_SCOPE_CODEX";

    private SessionScopePolicy() {
    }

    /**
     * 按 agent 解析 session scope 并生成 session name（env 来自 {@link System#getenv}，无 node-config fallback）。
     */
    public static Decision resolve(
            String agent,
            String baseSessionName,
            String workstreamId,
            String stageId,
            String iterationId,
            String runId
    ) {
        return resolve(agent, baseSessionName, workstreamId, stageId, iterationId, runId, System::getenv, null);
    }

    /**
     * 同上，但 env 来源可注入（便于单测）。
     */
    public static Decision resolve(
            String agent,
            String baseSessionName,
            String workstreamId,
            String stageId,
            String iterationId,
            String runId,
            java.util.function.Function<String, String> envLookup
    ) {
        return resolve(agent, baseSessionName, workstreamId, stageId, iterationId, runId, envLookup, null);
    }

    /**
     * 同上，但允许传入 node-config 的 {@code session_scope}（legacy opt-in，workstream/run）作为
     * <b>env 之下</b>的 fallback：env 设了用 env，否则用 node-config，否则默认 workstream。
     * 这保证 P1 前 node-config {@code session_scope=run} 的既有行为不变。
     */
    public static Decision resolve(
            String agent,
            String baseSessionName,
            String workstreamId,
            String stageId,
            String iterationId,
            String runId,
            String nodeConfigScope
    ) {
        return resolve(agent, baseSessionName, workstreamId, stageId, iterationId, runId, System::getenv, nodeConfigScope);
    }

    /**
     * An occurrence-bound execution policy cannot share a physical provider session
     * with another run because its ref/SHA lineage includes the run id.
     */
    static Decision occurrenceBound(
            String baseSessionName,
            String workstreamId,
            String stageId,
            String iterationId,
            String runId
    ) {
        return build(
                baseSessionName,
                workstreamId,
                stageId,
                iterationId,
                runId,
                Scope.RUN,
                "execution-policy:occurrence-bound"
        );
    }

    public static Decision resolve(
            String agent,
            String baseSessionName,
            String workstreamId,
            String stageId,
            String iterationId,
            String runId,
            java.util.function.Function<String, String> envLookup,
            String nodeConfigScope
    ) {
        var envName = "codex".equals(agent) ? ENV_CODEX : ENV_CLAUDE;
        var raw = envLookup.apply(envName);
        Scope configured;
        String reason;
        if (raw != null && !raw.isBlank()) {
            try {
                configured = Scope.fromWire(raw);
                reason = "env:" + envName + "=" + configured.wire();
            } catch (IllegalArgumentException e) {
                configured = Scope.WORKSTREAM;
                reason = "invalid " + envName + "=" + raw.trim() + "; fallback:workstream";
            }
        } else if (nodeConfigScope != null && !nodeConfigScope.isBlank()) {
            // legacy node-config opt-in；非法值按旧逻辑抛错（明确错误，不静默）
            configured = Scope.fromWire(nodeConfigScope);
            reason = "node-config:session_scope=" + configured.wire();
        } else {
            configured = Scope.WORKSTREAM;
            reason = "default:workstream";
        }
        return build(baseSessionName, workstreamId, stageId, iterationId, runId, configured, reason);
    }

    private static Decision build(
            String base, String workstreamId, String stageId, String iterationId,
            String runId, Scope scope, String reason
    ) {
        var wsPart = safe(workstreamId);
        return switch (scope) {
            case RUN -> new Decision(base + "-" + wsPart + "-" + safe(runId), Scope.RUN,
                    "ws:" + workstreamId + "/run:" + runId, reason);
            case STAGE_ITERATION -> {
                if (isBlank(stageId) || isBlank(iterationId)) {
                    yield workstreamFallback(base, workstreamId,
                            "stage_iteration unavailable (stage=" + stageId + ", iter=" + iterationId + ")");
                }
                yield new Decision(base + "-" + wsPart + "-" + safe(stageId) + "-" + safe(iterationId),
                        Scope.STAGE_ITERATION,
                        "ws:" + workstreamId + "/stage:" + stageId + "/iter:" + iterationId,
                        reason);
            }
            case STAGE -> {
                if (isBlank(stageId)) {
                    yield workstreamFallback(base, workstreamId, "stage unavailable (stage=" + stageId + ")");
                }
                yield new Decision(base + "-" + wsPart + "-" + safe(stageId),
                        Scope.STAGE,
                        "ws:" + workstreamId + "/stage:" + stageId,
                        reason);
            }
            default -> new Decision(base + "-" + wsPart, Scope.WORKSTREAM, "ws:" + workstreamId, reason);
        };
    }

    private static Decision workstreamFallback(String base, String workstreamId, String why) {
        return new Decision(base + "-" + safe(workstreamId), Scope.WORKSTREAM,
                "ws:" + workstreamId, "fallback:" + why);
    }

    /**
     * 与 legacy safeSessionPart 逐字节一致，保证默认 workstream 行为不变。
     */
    static String safe(String value) {
        var safe = value == null ? "" : value.replaceAll("[^A-Za-z0-9_.-]", "-");
        if (safe.isBlank()) {
            return "workstream";
        }
        return safe.length() <= 80 ? safe : safe.substring(0, 80);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}

package dev.dual.adapter.acpx;

import dev.dual.core.execution.AdapterSignalType;

/**
 * acpx adapter 输出的稳定失败语义。
 *
 * Provider 或 ACP wrapper 的原始错误文案可以变化，但进入 runtime/ledger
 * 之前必须先归一化成这里的 reason。这样 workflow 和 recovery 只消费
 * typed failure fact，不依赖供应商自然语言。
 */
enum AcpxFailureReason {
    AGENT_MODEL_MISMATCH("RECOVERABLE_AGENT_MODEL_MISMATCH"),
    AGENT_OVERLOADED("RECOVERABLE_AGENT_OVERLOADED"),
    AGENT_RECONNECT("RECOVERABLE_AGENT_RECONNECT"),
    AGENT_OUTPUT_INTERRUPTED("RECOVERABLE_AGENT_OUTPUT_INTERRUPTED"),
    AGENT_PERMISSION_BLOCKED("RECOVERABLE_AGENT_PERMISSION_BLOCKED"),
    AGENT_AUTH_FAILED("RECOVERABLE_AGENT_AUTH_FAILED"),
    PROVIDER_CONNECTION_FAILED("RECOVERABLE_PROVIDER_CONNECTION_FAILED"),
    SESSION_BOOTSTRAP_FAILED("RECOVERABLE_SESSION_BOOTSTRAP_FAILED"),
    SESSION_MISSING("RECOVERABLE_SESSION_MISSING"),
    RATE_LIMIT("RECOVERABLE_RATE_LIMIT"),
    CONTEXT_WINDOW("RECOVERABLE_CONTEXT_WINDOW"),
    TRANSPORT_FAILED("RECOVERABLE_TRANSPORT_FAILED");

    private final String code;

    AcpxFailureReason(String code) {
        this.code = code;
    }

    String code() {
        return code;
    }

    AdapterSignalType adapterSignalType() {
        return switch (this) {
            case AGENT_MODEL_MISMATCH -> AdapterSignalType.MODEL_MISMATCH;
            case AGENT_OVERLOADED, RATE_LIMIT -> AdapterSignalType.RATE_LIMITED;
            case AGENT_RECONNECT -> AdapterSignalType.AGENT_RECONNECT_REQUIRED;
            case AGENT_OUTPUT_INTERRUPTED, TRANSPORT_FAILED -> AdapterSignalType.PROCESS_STALLED;
            case AGENT_PERMISSION_BLOCKED -> AdapterSignalType.PERMISSION_BLOCKED;
            case AGENT_AUTH_FAILED -> AdapterSignalType.AUTH_FAILED;
            case PROVIDER_CONNECTION_FAILED -> AdapterSignalType.PROVIDER_CONNECTION_FAILED;
            case SESSION_BOOTSTRAP_FAILED -> AdapterSignalType.SESSION_BOOTSTRAP_FAILED;
            case SESSION_MISSING -> AdapterSignalType.SESSION_RESUME_FAILED;
            case CONTEXT_WINDOW -> AdapterSignalType.CONTEXT_WINDOW_EXCEEDED;
        };
    }
}

