package dev.dual.adapter.acpx;

import org.junit.jupiter.api.Test;

import java.util.List;
import java.util.Map;
import java.util.function.Function;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SessionScopePolicyTest {

    private static final String BASE = "claude-main";
    private static final String CODEX_BASE = "codex-reviewer";
    private static final String WS = "ws-20260623T215939Z-RFCM";

    private static Function<String, String> env(Map<String, String> map) {
        return key -> map.get(key);
    }

    private static SessionScopePolicy.Decision resolve(String agent, String base, String scopeWire) {
        return SessionScopePolicy.resolve(agent, base, WS, "stage-design", "iter-001", "run-1",
                env(scopeWire == null ? Map.of() : Map.of(
                        "DUAL_SESSION_SCOPE_CLAUDE", scopeWire,
                        "DUAL_SESSION_SCOPE_CODEX", scopeWire)));
    }

    @Test
    void defaultIsWorkstreamAndProducesLegacyName() {
        var d = resolve("claude", BASE, null);
        assertEquals(SessionScopePolicy.Scope.WORKSTREAM, d.scope());
        // 旧行为：base + "-" + workstreamId，逐字节一致
        assertEquals(BASE + "-" + WS, d.sessionName());
        assertTrue(d.reason().contains("default"), d.reason());
    }

    @Test
    void claudeAndCodexScopesAreIndependent() {
        var lookup = env(Map.of("DUAL_SESSION_SCOPE_CLAUDE", "stage"));
        var claude = SessionScopePolicy.resolve("claude", BASE, WS, "stage-design", "iter-001", "run-1", lookup);
        var codex = SessionScopePolicy.resolve("codex", CODEX_BASE, WS, "stage-design", "iter-001", "run-1", lookup);
        assertEquals(SessionScopePolicy.Scope.STAGE, claude.scope());
        assertEquals(SessionScopePolicy.Scope.WORKSTREAM, codex.scope()); // codex unset -> default
    }

    @Test
    void stageScopeIncludesWorkstreamIdAndStage() {
        var d = resolve("claude", BASE, "stage");
        assertEquals(SessionScopePolicy.Scope.STAGE, d.scope());
        assertTrue(d.sessionName().contains(WS), d.sessionName());
        assertTrue(d.sessionName().contains("stage-design"), d.sessionName());
        assertTrue(d.segmentKey().contains("stage-design"), d.segmentKey());
    }

    @Test
    void stageIterationScopeIncludesWorkstreamStageIteration() {
        var d = SessionScopePolicy.resolve("claude", BASE, WS, "stage-plan", "iter-005", "run-9",
                env(Map.of("DUAL_SESSION_SCOPE_CLAUDE", "stage_iteration")));
        assertEquals(SessionScopePolicy.Scope.STAGE_ITERATION, d.scope());
        assertTrue(d.sessionName().contains(WS), d.sessionName());
        assertTrue(d.sessionName().contains("stage-plan"), d.sessionName());
        assertTrue(d.sessionName().contains("iter-005"), d.sessionName());
    }

    @Test
    void runScopeIncludesWorkstreamIdAndRunId() {
        var d = SessionScopePolicy.resolve("claude", BASE, WS, "stage-design", "iter-001", "run-42",
                env(Map.of("DUAL_SESSION_SCOPE_CLAUDE", "run")));
        assertEquals(SessionScopePolicy.Scope.RUN, d.scope());
        // run scope 必须同时含 workstreamId 和 runId：workstreamId 是领域边界（不是 runId 的概率唯一）
        assertTrue(d.sessionName().contains(WS), d.sessionName());
        assertTrue(d.sessionName().contains("run-42"), d.sessionName());
        assertEquals(BASE + "-" + WS + "-run-42", d.sessionName());
        assertTrue(d.segmentKey().contains(WS), d.segmentKey());
        assertTrue(d.segmentKey().contains("run-42"), d.segmentKey());
    }

    @Test
    void occurrenceBoundPolicyAlwaysUsesRunScope() {
        var first = SessionScopePolicy.occurrenceBound(
                BASE, WS, "stage-implement", "iter-003", "run-41");
        var second = SessionScopePolicy.occurrenceBound(
                BASE, WS, "stage-implement", "iter-003", "run-42");

        assertEquals(SessionScopePolicy.Scope.RUN, first.scope());
        assertEquals(BASE + "-" + WS + "-run-41", first.sessionName());
        assertEquals(BASE + "-" + WS + "-run-42", second.sessionName());
        assertNotEquals(first.sessionName(), second.sessionName());
        assertEquals("execution-policy:occurrence-bound", first.reason());
    }

    @Test
    void occurrenceBoundPolicyIgnoresLegacyWorkstreamEnvironment() {
        var legacy = SessionScopePolicy.resolve(
                "claude", BASE, WS, "stage-implement", "iter-003", "run-41",
                env(Map.of("DUAL_SESSION_SCOPE_CLAUDE", "workstream")));
        var occurrence = SessionScopePolicy.occurrenceBound(
                BASE, WS, "stage-implement", "iter-003", "run-41");

        assertEquals(SessionScopePolicy.Scope.WORKSTREAM, legacy.scope());
        assertEquals(BASE + "-" + WS, legacy.sessionName());
        assertEquals(SessionScopePolicy.Scope.RUN, occurrence.scope());
        assertEquals(BASE + "-" + WS + "-run-41", occurrence.sessionName());
    }

    @Test
    void neverEmitsBareBaseSessionName() {
        for (String wire : List.of("workstream", "stage", "stage_iteration", "run")) {
            var d = resolve("claude", BASE, wire);
            assertNotEquals(BASE, d.sessionName(), "bare base leaked for scope=" + wire);
            assertTrue(d.sessionName().startsWith(BASE + "-"), d.sessionName());
        }
    }

    @Test
    void stageScopeFallsBackWithReasonWhenStageMissing() {
        var d = SessionScopePolicy.resolve("claude", BASE, WS, "", "iter-001", "run-1",
                env(Map.of("DUAL_SESSION_SCOPE_CLAUDE", "stage")));
        assertEquals(SessionScopePolicy.Scope.WORKSTREAM, d.scope());
        assertTrue(d.reason().contains("fallback"), d.reason());
        assertTrue(d.reason().contains("stage unavailable"), d.reason());
    }

    @Test
    void stageIterationFallsBackWithReasonWhenIterationMissing() {
        var d = SessionScopePolicy.resolve("claude", BASE, WS, "stage-design", "", "run-1",
                env(Map.of("DUAL_SESSION_SCOPE_CLAUDE", "stage_iteration")));
        assertEquals(SessionScopePolicy.Scope.WORKSTREAM, d.scope());
        assertTrue(d.reason().contains("fallback"), d.reason());
    }

    @Test
    void invalidEnvFallsBackWithReasonNotSilent() {
        var d = SessionScopePolicy.resolve("claude", BASE, WS, "stage-design", "iter-001", "run-1",
                env(Map.of("DUAL_SESSION_SCOPE_CLAUDE", "bogus")));
        // 非法 env：fallback 到 workstream，但必须给出明确 reason（不能静默变成 workstream）
        assertEquals(SessionScopePolicy.Scope.WORKSTREAM, d.scope());
        assertEquals(BASE + "-" + WS, d.sessionName());
        assertTrue(d.reason().contains("invalid"), d.reason());
        assertTrue(d.reason().contains("bogus"), d.reason());
    }
}

package dev.dual.adapter.acpx;

import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class AcpxFailureSignalCatalogTest {
    private final AcpxFailureSignalCatalog catalog = new AcpxFailureSignalCatalog();

    @Test
    void oldAndCurrentProgressDiagnosticsHaveTheSameFailureOwner() {
        for (var message : List.of(
                "agent accepted the prompt but produced no trusted progress before the progress timeout",
                "agent process produced no observed progress before the progress timeout")) {
            assertEquals("agent_output_interrupted",
                    catalog.match(new AcpxFailureEvidence("", message, 4)).orElseThrow().id());
        }
    }

    @Test
    void matchesRateLimitSignalsAcrossStdoutAndLanguages() {
        var evidence = new AcpxFailureEvidence(
                "[error] RUNTIME: API Error: Request rejected (429) 已达到 5 小时的使用上限",
                "[acpx] session claude-main · agent connected",
                1
        );

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("rate_limit", signal.id());
        assertEquals("RECOVERABLE_RATE_LIMIT", signal.reason().code());
        assertTrue(signal.recoverable());
    }

    @Test
    void matchesProviderOverloadBeforeReconnect() {
        var evidence = new AcpxFailureEvidence(
                "",
                """
                [acpx] session claude-main · agent needs reconnect
                Internal error: API Error: 529 [1305][该模型当前访问量过大，请您稍后再试]
                """,
                1
        );

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("model_overloaded", signal.id());
        assertEquals("RECOVERABLE_AGENT_OVERLOADED", signal.reason().code());
        assertTrue(signal.recoverable());
    }

    @Test
    void matchesModelMismatchBeforeReconnectOrGenericInvalidRequest() {
        var evidence = new AcpxFailureEvidence(
                "",
                """
                [acpx] session claude-main · agent needs reconnect
                Internal error: API Error: 400 {"error":{"message":"The supported API model names are deepseek-v4-pro or deepseek-v4-flash, but you passed glm-5.2.","type":"invalid_request_error"}}
                """,
                1
        );

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("model_mismatch", signal.id());
        assertEquals("RECOVERABLE_AGENT_MODEL_MISMATCH", signal.reason().code());
        assertTrue(signal.recoverable());
    }

    @Test
    void matchesAuthFailureBeforeReconnect() {
        var evidence = new AcpxFailureEvidence(
                """
                [client] session/new (running)
                Failed to authenticate. API Error: 401 Invalid authentication credentials
                [error] RUNTIME: Internal error: Failed to authenticate. API Error: 401 Invalid authentication credentials
                """,
                "[acpx] session claude-main · agent needs reconnect",
                1
        );

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("agent_auth_failed", signal.id());
        assertEquals("RECOVERABLE_AGENT_AUTH_FAILED", signal.reason().code());
        assertTrue(signal.recoverable());
    }

    @Test
    void matchesProviderConnectionFailureBeforeGenericExit() {
        var evidence = new AcpxFailureEvidence(
                "[error] RUNTIME: API Error: Unable to connect to API (FailedToOpenSocket)",
                "",
                1
        );

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("provider_connection_failed", signal.id());
        assertEquals("RECOVERABLE_PROVIDER_CONNECTION_FAILED", signal.reason().code());
        assertTrue(signal.recoverable());
    }

    @Test
    void choosesHighestPrioritySignalInsteadOfListOrder() {
        var catalog = new AcpxFailureSignalCatalog(List.of(
                new AcpxFailureSignal(
                        "agent_reconnect",
                        AcpxFailureReason.AGENT_RECONNECT,
                        10,
                        "reconnect",
                        true,
                        false,
                        List.of(AcpxFailureSignal.contains("agent needs reconnect"))
                ),
                new AcpxFailureSignal(
                        "model_mismatch",
                        AcpxFailureReason.AGENT_MODEL_MISMATCH,
                        100,
                        "model mismatch",
                        true,
                        false,
                        List.of(AcpxFailureSignal.contains("supported api model names"))
                )
        ));
        var evidence = new AcpxFailureEvidence(
                "",
                """
                [acpx] session claude-main · agent needs reconnect
                The supported API model names are deepseek-v4-pro or deepseek-v4-flash, but you passed glm-5.2.
                """,
                1
        );

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("model_mismatch", signal.id());
        assertEquals("RECOVERABLE_AGENT_MODEL_MISMATCH", signal.reason().code());
    }

    @Test
    void matchesReconnectSignalFromStderr() {
        var evidence = new AcpxFailureEvidence("", "[acpx] session claude-main · agent needs reconnect", 5);

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("agent_reconnect", signal.id());
        assertEquals("RECOVERABLE_AGENT_RECONNECT", signal.reason().code());
    }

    @Test
    void matchesAdapterGeneratedOutputInterruptedDiagnostic() {
        var evidence = new AcpxFailureEvidence(
                "",
                "[dual] acpx recoverable signal persisted reason=RECOVERABLE_AGENT_OUTPUT_INTERRUPTED progress_timeout_ms=1000",
                4
        );

        var signal = catalog.match(evidence).orElseThrow();

        assertEquals("agent_output_interrupted", signal.id());
        assertEquals("RECOVERABLE_AGENT_OUTPUT_INTERRUPTED", signal.reason().code());
        assertTrue(signal.recoverable());
    }

    @Test
    void rawPermissionWordingCannotCreateCurrentTurnPermissionAuthority() {
        var evidence = new AcpxFailureEvidence(
                """
                <tool_use_error>Cancelled: parallel tool call Bash(ls /repo)
                Tool permission request failed: Error: Tool use aborted
                """,
                "",
                4
        );

        assertTrue(catalog.match(evidence).isEmpty());
    }

    @Test
    void doesNotMatchUnknownExitText() {
        var evidence = new AcpxFailureEvidence("plain failure", "tool exited", 9);

        assertTrue(catalog.match(evidence).isEmpty());
    }

    @Test
    void bareQuotaWordIsNotRateLimit() {
        // "quota" appearing without an explicit rate-limit indicator (e.g. in an
        // unrelated error message or agent prose that reached the catalog) must
        // not classify as RATE_LIMIT.
        var evidence = new AcpxFailureEvidence("", "billing quota update failed", 1);

        var match = catalog.match(evidence);
        assertTrue(match.isEmpty() || match.get().reason() != AcpxFailureReason.RATE_LIMIT);
    }

    @Test
    void sessionIdentifierContainingFourTwentyNineIsNotRateLimit() {
        var evidence = new AcpxFailureEvidence(
                "",
                "Resource not found: 0bf2d846-4e3e-429b-8f6d-86483c3e9326",
                4
        );

        var match = catalog.match(evidence);

        assertTrue(match.isEmpty() || match.get().reason() != AcpxFailureReason.RATE_LIMIT);
    }

    @Test
    void explicitRateLimitIndicatorsClassifyAsRateLimit() {
        for (var text : new String[]{
                "Request rejected (429): too many requests",
                "HTTP 429 from provider",
                "API error: 429",
                "status code 429",
                "rate_limit_exceeded",
                "Rate limit exceeded, please retry",
                "已达到 5 小时的使用上限"
        }) {
            var evidence = new AcpxFailureEvidence("", text, 1);
            var signal = catalog.match(evidence).orElseThrow();
            assertEquals(AcpxFailureReason.RATE_LIMIT, signal.reason(), "expected RATE_LIMIT for: " + text);
        }
    }
}

package dev.dual.adapter.acpx;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class AcpxSessionLifecycleTest {

    @TempDir
    Path tempDir;

    /** Records close calls instead of spawning acpx. */
    static class RecordingTransport extends AcpxAgentTransport {
        final List<String> closed = new ArrayList<>();

        RecordingTransport() {
            super("acpx-dummy");
        }

        @Override
        public boolean closeSession(String agent, Path workdir, String sessionName) {
            closed.add(agent + ":" + sessionName);
            return true;
        }
    }

    @Test
    void closesDistinctAgentSessionsReadFromRuns() throws Exception {
        var ws = "ws-close";
        writeRun(ws, "run-1", "claude", "claude-main-ws-close-run-1");
        writeRun(ws, "run-2", "codex", "codex-reviewer-ws-close");
        writeRun(ws, "run-3", "claude", "claude-main-ws-close-run-3");
        writeRun(ws, "run-4", "claude", "claude-main-ws-close-run-1"); // duplicate -> deduped
        writeRun(ws, "run-5", "", "blank-agent-skipped");        // blank agent -> skipped

        var transport = new RecordingTransport();
        var summary = new AcpxSessionLifecycle(transport).closeWorkstreamSessions(tempDir, ws);

        assertEquals(3, summary.distinctSessions());
        assertEquals(3, summary.closed());
        assertEquals(0, summary.failed());
        assertTrue(transport.closed.contains("claude:claude-main-ws-close-run-1"));
        assertTrue(transport.closed.contains("claude:claude-main-ws-close-run-3"));
        assertTrue(transport.closed.contains("codex:codex-reviewer-ws-close"));
    }

    @Test
    void neverThrowsWhenRunsDirMissing() {
        var transport = new RecordingTransport();
        var summary = new AcpxSessionLifecycle(transport).closeWorkstreamSessions(tempDir, "no-such-workstream");

        assertEquals(0, summary.distinctSessions());
        assertEquals(0, summary.closed());
        assertTrue(transport.closed.isEmpty());
    }

    @Test
    void countsFailedClosesWithoutThrowing() throws Exception {
        var ws = "ws-fail";
        writeRun(ws, "run-1", "claude", "claude-main-ws-fail");
        var transport = new RecordingTransport() {
            @Override
            public boolean closeSession(String agent, Path workdir, String sessionName) {
                super.closeSession(agent, workdir, sessionName);
                return false; // simulate acpx close failure
            }
        };

        var summary = new AcpxSessionLifecycle(transport).closeWorkstreamSessions(tempDir, ws);

        assertEquals(1, summary.distinctSessions());
        assertEquals(0, summary.closed());
        assertEquals(1, summary.failed());
    }

    @Test
    void writesDiagnosticLogAlongsideRuns() throws Exception {
        var ws = "ws-diag";
        writeRun(ws, "run-1", "claude", "claude-main-ws-diag");
        new AcpxSessionLifecycle(new RecordingTransport()).closeWorkstreamSessions(tempDir, ws);

        var log = tempDir.resolve(".agent/workstreams").resolve(ws).resolve("session-cleanup.log");
        assertTrue(Files.isRegularFile(log));
        var content = Files.readString(log);
        assertTrue(content.contains("session-cleanup workstream=ws-diag"));
        assertTrue(content.contains("claude claude-main-ws-diag"));
    }

    private void writeRun(String ws, String runId, String agent, String session) throws Exception {
        var dir = tempDir.resolve(".agent/workstreams").resolve(ws).resolve("runs").resolve(runId);
        Files.createDirectories(dir);
        Files.writeString(dir.resolve("run.json"),
                "{\"runId\":\"" + runId + "\",\"agent\":\"" + agent + "\",\"session\":\"" + session + "\"}");
    }
}

package dev.dual.adapter.acpx;

