    private void assertWriteFailure(String nodeId, boolean queued) throws Exception {
        var context = context(nodeId);
        var calls = new AtomicInteger();
        var writes = new AtomicInteger();
        var diskFailure = new IOException("simulated manifest write failure");
        var writer = new PromptManifestWriter() {
            @Override
            void write(Path path, String ws, String run, String node, String agent, String template,
                       Path prompt, List<AgentPromptRenderer.PromptSection> sections,
                       AuthoredExecutionContext.Snapshot snapshot) throws IOException {
                assertEquals(nodeId.equals("design.claude_design"), snapshot != null);
                writes.incrementAndGet();
                throw diskFailure;
            }
        };
        var handler = new AcpxAgentTaskHandler(forbiddenTransport(calls), false, new AcpxUsageReader(), writer);
        var result = execute(context, handler, queued);
        assertEquals("INPUT_PREPARATION_FAILED", result.result().get("reason"));
        assertEquals(IOException.class.getName(), result.result().get("failure_code"));
        assertEquals(List.of(diskFailure.getMessage()), result.result().get("errors"));
        assertEquals(1, writes.get());
        assertEquals(0, calls.get());
    }

    @Test
    void prepareOnlyWritesAndReadsTheSameManifestWithoutProvider() throws Exception {
        var context = context();
        var result = new AcpxAgentTaskHandler(forbiddenTransport(new AtomicInteger()), true).execute(context);
        assertEquals(NodeStatus.COMPLETED, result.status(), result.result().toString());
        var run = JSON.readTree(root.resolve((String) result.result().get("run_metadata")).toFile());
        var manifestPath = root.resolve(run.path("promptManifestPath").asText());
        var manifest = JSON.readTree(manifestPath.toFile());
        var snapshot = JSON.treeToValue(manifest.get("authoredContext"), AuthoredExecutionContext.Snapshot.class);
        AuthoredExecutionContext.verifyManifest(root, manifestPath, snapshot);
        assertTrue(result.result().containsKey("prepared"));
        assertFalse(run.has("authoredContext"), "run metadata locates the manifest; it must not copy its payload");
    }

    private void assertRejected(String corruption, boolean queued) throws Exception {
        var context = context();
        var writes = new AtomicInteger();
        var calls = new AtomicInteger();
        var writer = new PromptManifestWriter() {
            @Override
            void write(Path path, String ws, String run, String node, String agent, String template,
                       Path prompt, List<AgentPromptRenderer.PromptSection> sections,
                       AuthoredExecutionContext.Snapshot snapshot) throws IOException {
                super.write(path, ws, run, node, agent, template, prompt, sections, snapshot);
                if (corruption.equals("identity")) {
                    var json = (ObjectNode) JSON.readTree(path.toFile());
                    ((ObjectNode) json.get("authoredContext")).put("runId", "run-forged");
                    JSON.writeValue(path.toFile(), json);
                } else if (corruption.equals("partial")) {
                    Files.writeString(path, "{");
                } else {
                    Files.writeString(prompt, "Only refs remain; required authored input was lost.");
                }
                writes.incrementAndGet();
            }
        };
        var result = execute(context, new AcpxAgentTaskHandler(forbiddenTransport(calls), false, new AcpxUsageReader(), writer), queued);
        assertEquals(1, writes.get(), "the writer returned; dispatch must independently verify its output");
        assertEquals(0, calls.get());
        assertEquals(NodeStatus.FAILED, result.status());
        assertEquals("REQUIRED_AGENT_EVIDENCE_MISSING", result.result().get("reason"));
        assertEquals("AUTHORED_CONTEXT_INVALID", result.result().get("failure_code"));
    }

    private NodeInstanceDocument execute(TaskHandler.TaskContext context, AcpxAgentTaskHandler handler, boolean queued) throws Exception {
        var ledger = new WorkflowFileLedger();
        var paths = new WorkstreamPaths(root, new DualId(context.workstreamId()));
        var handlers = new HandlerRegistry(List.of(handler), List.of(), List.of());
        var command = new WorkflowCommand(root, context.workstreamId());
        new WorkflowRuntime(ledger, handlers, queued ? AgentTaskDispatchMode.WORKER : AgentTaskDispatchMode.INLINE).resume(command);
        if (queued) new AgentWorker(ledger, handlers).runOne(command);
        var current = ledger.loadCurrent(paths);
        assertEquals(WorkflowStatus.WAITING_FOR_RECOVERY, current.status());
        var node = ledger.loadNode(paths, current.activeNodeInstanceIds().getFirst());
        assertTrue(node.outputRefs().isEmpty());
        assertFalse(node.result().containsKey("parse_error"));
        assertEquals("input_preparation_failure", RecoveryAssessment.from(node, root, context.workstreamId()).classification());
        return node;
    }

    private TaskHandler.TaskContext context() throws Exception {
        return context("design.claude_design");
    }

    private TaskHandler.TaskContext context(String nodeId) throws Exception {
        var ws = "ws-manifest";
        var paths = new WorkstreamPaths(root, new DualId(ws));
        var design = new NodeDefinition(nodeId, NodeKind.TASK, "acpx.agent_run", Map.of(
                "agent", "claude", "session", "design", "prompt_template", "design-claude",
                "permission_profile", "observe", "requires_approved_task_contract", true));
        var ledger = new WorkflowFileLedger();
        var definition = new WorkflowDefinition("manifest-fixture", 1, design.id(), List.of(design,
                new NodeDefinition("contract.compile", NodeKind.TASK, "contract.compile", Map.of()),
                new NodeDefinition("gate.contract_review", NodeKind.GATE, "human.review", Map.of("gate_purpose", "contract"))),
                List.of(new EdgeDefinition("contract.compile", "completed", "gate.contract_review"),
                        new EdgeDefinition("gate.contract_review", "approved", design.id())));
        ledger.initialize(paths, "manifest-fixture", definition);
        DesignContractFixture.approve(root, ws);
        Files.writeString(paths.workstreamDir().resolve("requirement.md"), "Design a file conversion tool");
        var instance = ledger.loadNode(paths, ledger.loadCurrent(paths).activeNodeInstanceIds().getFirst());
        return new TaskHandler.TaskContext(root, ws, design, new NodeInstance(
                instance.nodeInstanceId(), instance.nodeDefinitionId(), instance.kind(), instance.handlerType(),
                instance.status(), instance.stageId(), instance.iterationId(), instance.inputRefs(),
                instance.outputRefs(), instance.result(), instance.runRef(), instance.startedAt(), instance.finishedAt()));
    }

    private AcpxAgentTransport forbiddenTransport(AtomicInteger calls) {
        return new AcpxAgentTransport() {
            @Override public AcpxRunResult runClaudeDesign(AcpxRunRequest request) {
                calls.incrementAndGet();
                throw new AssertionError("provider must not be invoked");
            }
        };
    }
}

package dev.dual.adapter.acpx;

import dev.dual.core.execution.AdapterSignalType;
import org.junit.jupiter.api.Test;

import java.time.Duration;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class AgentExecutionHealthTest {
    private final AcpxFailureSignalCatalog catalog = new AcpxFailureSignalCatalog();

    private AgentLifecycleEvent streamEvent(long sequence, String line) {
        return new AcpxSessionStreamProjector()
                .accept(sequence, AcpxStreamWireLine.parse(line))
                .orElseThrow();
    }

    @Test
    void recoveredReconnectDoesNotBecomeFailure() {
        var health = new AgentExecutionHealth(catalog, Duration.ofSeconds(30));

        health.observe(AgentLifecycleEvent.stderrLine(0, "[acpx] session claude-main · agent needs reconnect"));
        var stream = new AcpxSessionStreamProjector();
        health.observe(stream.accept(1, AcpxStreamWireLine.parse("{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"session/new\"}")).orElseThrow());
        health.observe(stream.accept(2, AcpxStreamWireLine.parse("{\"jsonrpc\":\"2.0\",\"result\":{\"sessionId\":\"abc\"},\"id\":1}")).orElseThrow());
        health.observe(stream.accept(3, AcpxStreamWireLine.parse("{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"session/prompt\"}")).orElseThrow());
        health.observe(AgentLifecycleEvent.stdoutLine(4, "[thinking] continuing after reconnect"));

        var assessment = health.assess(Duration.ofSeconds(5));

        assertEquals(AgentExecutionHealth.Status.HEALTHY, assessment.status());
        assertNull(assessment.signal());
        assertTrue(assessment.signals().stream().allMatch(signal -> signal.superseded()));
    }

    @Test
    void staleReconnectIsNotConsumedAgainWithoutNewSignal() {
        var health = new AgentExecutionHealth(catalog, Duration.ofSeconds(30));

        health.observe(AgentLifecycleEvent.stderrLine(0, "[acpx] session claude-main · agent needs reconnect"));
        assertEquals(AgentExecutionHealth.Status.RECOVERING, health.assess(Duration.ofSeconds(1)).status());
        assertEquals(AgentExecutionHealth.Status.RECOVERABLE_FAILURE, health.assess(Duration.ofSeconds(31)).status());
        var stream = new AcpxSessionStreamProjector();
        health.observe(stream.accept(1, AcpxStreamWireLine.parse("{\"jsonrpc\":\"2.0\",\"id\":4,\"method\":\"session/new\"}")).orElseThrow(), Duration.ofSeconds(59));
        health.observe(stream.accept(2, AcpxStreamWireLine.parse("{\"jsonrpc\":\"2.0\",\"result\":{\"sessionId\":\"new\"},\"id\":4}")).orElseThrow(), Duration.ofSeconds(59));

        var assessment = health.assess(Duration.ofSeconds(60));

        assertEquals(AgentExecutionHealth.Status.HEALTHY, assessment.status());
        assertNull(assessment.signal());
    }

    @Test
    void unrecoveredReconnectBecomesRecoverableFailureAfterGrace() {
        var health = new AgentExecutionHealth(catalog, Duration.ofSeconds(10));

        health.observe(AgentLifecycleEvent.stderrLine(0, "[acpx] session claude-main · agent needs reconnect"));

        var assessment = health.assess(Duration.ofSeconds(11));

        assertEquals(AgentExecutionHealth.Status.RECOVERABLE_FAILURE, assessment.status());
        assertEquals(AdapterSignalType.AGENT_RECONNECT_REQUIRED, assessment.signal().type());
        assertFalse(assessment.signal().superseded());
    }

    @Test
    void currentAgentActivitySupersedesReconnect() {
        var health = new AgentExecutionHealth(catalog, Duration.ofSeconds(10));

        health.observe(AgentLifecycleEvent.stderrLine(0, "[acpx] session claude-main · agent needs reconnect"));
        health.observe(streamEvent(1, "{\"jsonrpc\":\"2.0\",\"method\":\"session/update\",\"params\":{\"update\":{\"sessionUpdate\":\"agent_thought_chunk\",\"content\":{\"text\":\"working\"}}}}"), Duration.ofSeconds(19));

        var assessment = health.assess(Duration.ofSeconds(20));

        assertEquals(AgentExecutionHealth.Status.HEALTHY, assessment.status());
        assertNull(assessment.signal());
    }

    @Test
    void providerFailureOverridesReconnectAndActivity() {
        var health = new AgentExecutionHealth(catalog, Duration.ofSeconds(30));

        health.observe(AgentLifecycleEvent.stderrLine(0, "[acpx] session claude-main · agent needs reconnect"));
        var stream = new AcpxSessionStreamProjector();
        stream.accept(0, AcpxStreamWireLine.parse("{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"session/new\"}"));
        health.observe(stream.accept(1, AcpxStreamWireLine.parse("{\"jsonrpc\":\"2.0\",\"result\":{\"sessionId\":\"new\"},\"id\":1}")).orElseThrow());
        health.observe(stream.accept(2, AcpxStreamWireLine.parse("{\"jsonrpc\":\"2.0\",\"method\":\"session/prompt/failed\",\"error\":\"Internal error: API Error: 529 [1305][该模型当前访问量过大，请您稍后再试]\"}")).orElseThrow());

        var assessment = health.assess(Duration.ZERO);

        assertEquals(AgentExecutionHealth.Status.RECOVERABLE_FAILURE, assessment.status());
        assertEquals(AdapterSignalType.RATE_LIMITED, assessment.signal().type());
    }

    @Test
    void promptAcceptedWithoutTrustedProgressBecomesRecoverableOutputInterrupted() {
        var health = new AgentExecutionHealth(catalog, Duration.ofSeconds(30), Duration.ofSeconds(5));

        health.observe(streamEvent(0, "{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"session/prompt\",\"params\":{}}"), Duration.ofSeconds(1));

        var assessment = health.assess(Duration.ofSeconds(7));

        assertEquals(AgentExecutionHealth.Status.RECOVERABLE_FAILURE, assessment.status());
        assertEquals(AdapterSignalType.PROCESS_STALLED, assessment.signal().type());
    }

    @Test
    void trustedAgentActivityResetsProgressStallClock() {
        var health = new AgentExecutionHealth(catalog, Duration.ofSeconds(30), Duration.ofSeconds(5));

        health.observe(streamEvent(0, "{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"session/prompt\",\"params\":{}}"), Duration.ofSeconds(1));
        health.observe(streamEvent(1, "{\"jsonrpc\":\"2.0\",\"method\":\"session/update\",\"params\":{\"update\":{\"sessionUpdate\":\"agent_thought_chunk\",\"content\":{\"text\":\"working\"}}}}"), Duration.ofSeconds(4));

        var assessment = health.assess(Duration.ofSeconds(8));

        assertEquals(AgentExecutionHealth.Status.HEALTHY, assessment.status());
        assertNull(assessment.signal());
    }

    @Test
    void processSilentFromLaunchDoesNotWaitForeverWithoutTotalDeadline() {
        var health = new AgentExecutionHealth(catalog, Duration.ofSeconds(30), Duration.ofSeconds(5));
        assertEquals(AgentExecutionHealth.Status.UNKNOWN, health.assess(Duration.ofSeconds(4)).status());
        assertEquals(AdapterSignalType.PROCESS_STALLED, health.assess(Duration.ofSeconds(5)).signal().type());
    }

    @Test
    void continuedThoughtsRemainHealthyBeyondFormerTotalDeadline() {
        var health = new AgentExecutionHealth(catalog, Duration.ofSeconds(30), Duration.ofSeconds(600));
        for (int i = 0; i <= 30; i++) {
            var elapsed = Duration.ofSeconds(i * 100L);
            health.observe(streamEvent(i, "{\"jsonrpc\":\"2.0\",\"method\":\"session/update\",\"params\":{\"update\":{\"sessionUpdate\":\"agent_thought_chunk\",\"content\":{\"text\":\"working\"}}}}"), elapsed);
            assertEquals(AgentExecutionHealth.Status.HEALTHY, health.assess(elapsed.plusSeconds(99)).status());
        }
    }

    /** Transport-level cannot-bypass: ordinary ongoing output that mentions
     * quota / rate limit / is_error=false must never raise a recoverable signal
     * (so {@code waitForExitOrRecoverableSignal} does not terminate/cancel) and
     * the run continues to normal completion. */
    @Test
    void ongoingOutputWithQuotaAndRateLimitWordsDoesNotRaiseRecoverableSignal() {
        var health = new AgentExecutionHealth(catalog, Duration.ofSeconds(1), Duration.ofSeconds(60));

        health.observe(streamEvent(0, """
                {"jsonrpc":"2.0","method":"session/update","params":{"sessionId":"s","update":{"sessionUpdate":"agent_message_chunk","content":{"type":"text","text":"Consider the quota and rate limit policy; the tool returned is_error=false."}}}}
                """));
        health.observe(streamEvent(1, """
                {"jsonrpc":"2.0","method":"session/update","params":{"sessionId":"s","update":{"sessionUpdate":"usage_update","used":100,"size":200000,"cost":{"amount":0,"currency":"USD"}}}}
                """));
        health.observe(streamEvent(2, """
                {"jsonrpc":"2.0","method":"session/update","params":{"sessionId":"s","update":{"sessionUpdate":"tool_call_update","toolCallId":"exec-1","status":"completed","rawOutput":{"is_error":false}}}}
                """));

        // Poll past the recoverable-signal grace: still no recoverable failure.
        for (long t = 0; t <= 5; t++) {
            var assessment = health.assess(Duration.ofSeconds(t));
            assertTrue(
                    assessment.status() == AgentExecutionHealth.Status.HEALTHY
                            || assessment.status() == AgentExecutionHealth.Status.UNKNOWN,
                    "ongoing output must not raise a recoverable failure at t=" + t + "; got " + assessment.status());
            assertNull(assessment.signal(),
                    "ongoing output must not raise any recoverable signal at t=" + t);
        }
    }

    /** Transport-level cannot-bypass: a real prompt 429 still triggers the
     * correct recoverable RATE_LIMIT failure (the one case a cancel/retry is
     * warranted). */
    @Test
    void realPromptFourTwentyNineTriggersRecoverableRateLimit() {
        var health = new AgentExecutionHealth(catalog, Duration.ofSeconds(1));

        var stream = new AcpxSessionStreamProjector();
        stream.accept(0, AcpxStreamWireLine.parse("""
                {"jsonrpc":"2.0","method":"session/prompt","id":3,"params":{}}
                """));
        health.observe(stream.accept(1, AcpxStreamWireLine.parse("""
                {"jsonrpc":"2.0","id":3,"error":{"code":-32603,"message":"Request rejected (429): rate limit exceeded"}}
                """)).orElseThrow());

        var assessment = health.assess(Duration.ofSeconds(2));
        assertEquals(AgentExecutionHealth.Status.RECOVERABLE_FAILURE, assessment.status());
        assertEquals(AdapterSignalType.RATE_LIMITED, assessment.signal().type());
    }

    @Test
    void missingResumeSessionWhoseIdentifierContainsFourTwentyNineIsNotRateLimit() {
        var health = new AgentExecutionHealth(catalog, Duration.ofSeconds(1), Duration.ofSeconds(60));
        var stream = new AcpxSessionStreamProjector();
        stream.accept(0, AcpxStreamWireLine.parse("""
                {"jsonrpc":"2.0","id":1,"method":"session/resume","params":{}}
                """));

        health.observe(stream.accept(1, AcpxStreamWireLine.parse("""
                {"jsonrpc":"2.0","id":1,"error":{"code":-32002,"message":"Resource not found: 0bf2d846-4e3e-429b-8f6d-86483c3e9326"}}
                """)).orElseThrow());

        var assessment = health.assess(Duration.ofSeconds(2));
        assertTrue(assessment.status() != AgentExecutionHealth.Status.RECOVERABLE_FAILURE);
        assertTrue(assessment.signal() == null || assessment.signal().type() != AdapterSignalType.RATE_LIMITED);
    }

    @Test
    void currentPermissionDenialIsRecordedWithoutStoppingTheTurnEarly() {
        var health = new AgentExecutionHealth(catalog, Duration.ofSeconds(1), Duration.ofSeconds(60));
        var stream = new AcpxSessionStreamProjector();
        health.observe(stream.accept(0, AcpxStreamWireLine.parse("""
                {"jsonrpc":"2.0","id":9,"method":"session/request_permission","params":{"toolCall":{"title":"Run tests","rawInput":{"command":"mvn test"}}}}
                """)).orElseThrow());
        health.observe(stream.accept(1, AcpxStreamWireLine.parse("""
                {"jsonrpc":"2.0","id":9,"result":{"outcome":{"outcome":"selected","optionId":"reject"}}}
                """)).orElseThrow());

        var assessment = health.assess(Duration.ofSeconds(2));
        assertEquals(AgentExecutionHealth.Status.HEALTHY, assessment.status());
        assertNull(assessment.signal());
        assertEquals(1, assessment.signals().size());
        assertEquals(AdapterSignalType.PERMISSION_BLOCKED, assessment.signals().get(0).type());
        assertTrue(assessment.signals().get(0).message().contains("mvn test"));
    }
}

package dev.dual.adapter.acpx;

import org.junit.jupiter.api.Test;

import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;

class ToolUsageCapabilityClassifierTest {
    @Test
    void classifiesDirectReadsAndCatalogDeclaredProviders() {
        var usage = new AcpxToolUsage(
                1,
                3,
                1,
                0,
                2,
                0,
                Map.of("Read", 1, "Bash", 2),
                List.of("Read", "Bash"),
                List.of("README.md"),
                List.of(),
                List.of("rtk grep issueWorkflow src", "codegraph query Symbol"),
                List.of("rtk", "codegraph"));
        var catalog = catalog(List.of(
                capability("direct_file_read", "Read"),
                capability("token_filtered_shell", "rtk"),
                capability("symbol_index", "codegraph")));

        var result = ToolUsageCapabilityClassifier.classify(usage, catalog);

        assertEquals(List.of("direct_file_read", "token_filtered_shell", "symbol_index"), result);
        assertEquals(
                List.of(
                        Map.of("kind", "direct_file_read", "provider", "Read", "source", "tool_id"),
                        Map.of("kind", "token_filtered_shell", "provider", "rtk", "source", "command_executable"),
                        Map.of("kind", "symbol_index", "provider", "codegraph", "source", "command_executable")
                ),
                ToolUsageCapabilityClassifier.classifyUsages(usage, catalog));
    }

    @Test
    void usesCatalogProviderNamesRatherThanHardcodedToolNames() {
        var usage = new AcpxToolUsage(
                1,
                1,
                0,
                0,
                1,
                0,
                Map.of(),
                List.of(),
                List.of(),
                List.of(),
                List.of("symbol-router lookup PatientTimeline"),
                List.of("symbol-router"));
        var catalog = catalog(List.of(capability("symbol_index", "symbol-router")));

        assertEquals(List.of("symbol_index"), ToolUsageCapabilityClassifier.classify(usage, catalog));
    }

    @Test
    void ignoresCommandsWhenProviderIsNotDeclaredInCatalog() {
        var usage = new AcpxToolUsage(
                1,
                1,
                0,
                0,
                1,
                0,
                Map.of(),
                List.of(),
                List.of(),
                List.of(),
                List.of("codegraph query Symbol"),
                List.of("codegraph"));
        var catalog = catalog(List.of(capability("token_filtered_shell", "rtk")));

        assertEquals(List.of(), ToolUsageCapabilityClassifier.classify(usage, catalog));
    }

    @Test
    void ignoresProviderNamesThatOnlyAppearInCommandArguments() {
        var usage = new AcpxToolUsage(
                1,
                3,
                0,
                0,
                3,
                0,
                Map.of("Bash", 3),
                List.of("Bash"),
                List.of(),
                List.of(),
                List.of("grep codegraph docs", "echo rtk", "cat docs/gitnexus.md"),
                List.of("grep", "echo", "cat"));
        var catalog = catalog(List.of(
                capability("symbol_index", "codegraph"),
                capability("token_filtered_shell", "rtk"),
                capability("repo_graph", "gitnexus")));

        assertEquals(List.of(), ToolUsageCapabilityClassifier.classify(usage, catalog));
    }

    @Test
    void matchesNormalizedCommandExecutable() {
        var usage = new AcpxToolUsage(
                1,
                2,
                0,
                0,
                2,
                0,
                Map.of("Bash", 2),
                List.of("Bash"),
                List.of(),
                List.of(),
                List.of("/usr/local/bin/rtk grep x", "./codegraph query Symbol"),
                List.of("rtk", "codegraph"));
        var catalog = catalog(List.of(
                capability("token_filtered_shell", "rtk"),
                capability("symbol_index", "codegraph")));

        assertEquals(List.of("token_filtered_shell", "symbol_index"), ToolUsageCapabilityClassifier.classify(usage, catalog));
    }

    @Test
    void grepAndGlobDoNotCountAsDirectFileRead() {
        var usage = new AcpxToolUsage(
                1,
                2,
                2,
                0,
                0,
                0,
                Map.of("Grep", 1, "Glob", 1),
                List.of("Grep", "Glob"),
                List.of("src", "docs"),
                List.of(),
                List.of(),
                List.of());
        var catalog = catalog(List.of(capability("direct_file_read", "Read")));

        assertEquals(List.of(), ToolUsageCapabilityClassifier.classify(usage, catalog));
    }

    @Test
    void classifiedRtkReadDoesNotCountAsNativeReadTool() {
        var usage = new AcpxToolUsage(
                1,
                1,
                1,
                0,
                0,
                0,
                Map.of("Read", 1),
                List.of("Bash"),
                List.of("docs/product.md"),
                List.of(),
                List.of("rtk read docs/product.md"),
                List.of("rtk"));
        var catalog = catalog(List.of(
                capability("direct_file_read", "Read"),
                capability("token_filtered_shell", "rtk")));

        assertEquals(List.of("token_filtered_shell"), ToolUsageCapabilityClassifier.classify(usage, catalog));
    }

    private static Map<String, Object> catalog(List<Map<String, Object>> capabilities) {
        return Map.of("capabilities", capabilities);
    }

    private static Map<String, Object> capability(String kind, String provider) {
        return Map.of("kind", kind, "provider", provider);
    }
}

package dev.dual.adapter.acpx;

import dev.dual.runtime.handler.ContractRegistry;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import java.util.stream.Stream;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class PromptTemplateConsistencyTest {
    private static final String TEMPLATE_ROOT = "dev/dual/adapter/acpx/prompts/";
    private static final Set<String> KNOWN_VARIABLES = Set.of(
            "workstream_id", "run_id", "node_id", "prompt_template",
            "ledger_path", "requirement", "context_package",
            "contract_review_principles", "allowed_decisions",
            "required_control_keys", "decision_example", "agent_result_contract"
    );
    private static final Pattern VARIABLE_PATTERN = Pattern.compile("\\{\\{([a-z_]+)}}");
    private static final Map<String, String> TEMPLATE_NODE_IDS = Map.of(
            "intake-claude-brainstorm", "intake.claude_brainstorm",
            "intake-codex-product-review", "intake.codex_product_review",
            "design-claude", "design.claude_design",
            "design-codex-review", "design.codex_arch_review",
            "plan-claude", "plan.claude_plan",
            "plan-codex-review", "plan.codex_plan_review",
            "implement-claude", "implement.claude_implement",
            "implement-claude-self-test", "implement.claude_self_test_report",
            "acceptance-codex-review", "acceptance.codex_verifier_review",
            "stage-claude-handoff", "stage.claude_handoff"
    );

    static Stream<String> allTemplates() {
        return Stream.of(
                "intake-claude-brainstorm", "intake-codex-product-review",
                "design-claude", "design-codex-review",
                "plan-claude", "plan-codex-review",
                "implement-claude", "implement-claude-self-test",
                "acceptance-codex-review", "stage-claude-handoff"
        );
    }

    @ParameterizedTest
    @MethodSource("allTemplates")
    void allTemplatesUseOnlyKnownVariables(String templateName) {
        var content = loadTemplate(templateName);
        var matcher = VARIABLE_PATTERN.matcher(content);
        var unknown = new java.util.LinkedHashSet<String>();
        while (matcher.find()) {
            var variable = matcher.group(1);
            if (!KNOWN_VARIABLES.contains(variable)) {
                unknown.add(variable);
            }
        }
        assertTrue(unknown.isEmpty(),
                templateName + " references unknown variables: " + unknown);
    }

    @ParameterizedTest
    @MethodSource("allTemplates")
    void allTemplatesDelegateToTheStrictAgentResultContract(String templateName) {
        var content = loadTemplate(templateName);
        assertTrue(content.contains("{{agent_result_contract}}"),
                templateName + " must inject the strict AgentResultEnvelope contract");
        assertFalse(content.contains("dual-control"), templateName + " retains the old Markdown protocol");
        assertFalse(content.contains("<dual-artifact"), templateName + " retains the old artifact envelope");
    }

    @ParameterizedTest
    @MethodSource("allTemplates")
    void templatesDoNotDuplicateDecisionOrFieldRules(String templateName) {
        var content = loadTemplate(templateName);
        assertTrue(content.contains("{{agent_result_contract}}"));
        assertFalse(content.contains("{{allowed_decisions}}"));
        assertFalse(content.contains("{{required_control_keys}}"));
        assertFalse(content.contains("{{decision_example}}"));
        assertFalse(content.contains("|NEEDS_REVISION|"),
                templateName + " must not hardcode pipe-delimited decision values");
        assertFalse(content.contains("ACCEPT|ACCEPT_WITH_NOTES|REJECT"),
                templateName + " must not hardcode acceptance decision values");
    }

    @Test
    void reviewerTemplatesDoNotEmbedASecondResultSchema() {
        for (var templateName : List.of(
                "intake-codex-product-review",
                "design-codex-review",
                "plan-codex-review"
        )) {
            var content = loadTemplate(templateName);
            assertTrue(content.contains("{{agent_result_contract}}"));
            assertFalse(content.contains("\"lifecycle_status\""),
                    templateName + " must not duplicate fields owned by AgentResultPromptContract");
        }
    }

    @ParameterizedTest
    @MethodSource("allTemplates")
    void allTemplatesIncludeContextPackageSection(String templateName) {
        var content = loadTemplate(templateName);
        assertTrue(content.contains("{{context_package}}"),
                templateName + " missing {{context_package}} injection point");
    }

    @ParameterizedTest
    @MethodSource("allTemplates")
    void allTemplatesIncludeRequirementSection(String templateName) {
        var content = loadTemplate(templateName);
        assertTrue(content.contains("{{requirement}}"),
                templateName + " missing {{requirement}} injection point");
    }

    @Test
    void templateCountIs10() {
        assertEquals(10, allTemplates().count());
    }

    @Test
    void designTemplatesRequireCompleteReplacementAndCompleteCurrentReview() {
        var claude = loadTemplate("design-claude");
        assertTrue(claude.contains("complete replacement design"));
        assertTrue(claude.contains("interruption/crash"));
        assertTrue(claude.contains("restart/recovery"));
        assertTrue(claude.contains("rollback/conflict"));
        assertTrue(claude.contains("Prefer deleting unnecessary mechanisms"));

        var codex = loadTemplate("design-codex-review");
        assertTrue(codex.contains("complete current typed design"));
        assertTrue(codex.contains("complete blocking set"));
        assertTrue(codex.contains("interruption/crash"));
        assertTrue(codex.contains("restart/recovery"));
        assertTrue(codex.contains("rollback/conflict"));
        assertTrue(codex.contains("simplifying the state model"));
        assertTrue(codex.contains("Anchor every blocker to the TaskContract"));
        assertFalse(codex.contains("increase the revision budget"));
        assertFalse(codex.contains("relax the strict contract"));
    }

    private static String loadTemplate(String templateName) {
        var resource = TEMPLATE_ROOT + templateName + ".md";
        try (var stream = Thread.currentThread().getContextClassLoader().getResourceAsStream(resource)) {
            if (stream == null) {
                throw new IllegalArgumentException("missing template: " + resource);
            }
            return new String(stream.readAllBytes(), StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

