    private static Map<?, ?> readFile(Map<?, ?> memory, String path) {
        var files = (List<?>) memory.get("readFiles");
        return files.stream()
                .filter(Map.class::isInstance)
                .map(Map.class::cast)
                .filter(item -> path.equals(item.get("path")))
                .findFirst()
                .orElseThrow();
    }
