        }
    }

    @ParameterizedTest @ValueSource(booleans = {false, true})
    void interruptedHumanDecisionCannotDispatchAnOrphanOrRepeatApproval(boolean queued) throws Exception {
        for (var cut : List.of("gate", "node", "iteration", "successor", "event", "current")) {
            var f = new Fixture(root.resolve(cut), queued);
            f.untilGate();
            var current = f.ledger.loadCurrent(f.paths);
            var node = f.active();
            var gate = f.ledger.loadOpenGateForNode(f.paths, node.nodeInstanceId());
            long nextEvent = Long.parseLong(current.lastEventId().substring(4)) + 1;
            var target = switch (cut) {
                case "gate" -> f.paths.gateJson(gate.gateId());
                case "node" -> f.paths.nodeJson(node.nodeInstanceId());
                case "iteration" -> f.paths.iterationJson("iter-002");
                case "successor" -> f.paths.nodeJson("node-intake-claude_brainstorm-" + String.format("%03d", nextEvent));
                case "event" -> f.paths.eventsJsonl();
                default -> f.paths.workflowCurrentJson();
            };
            var fault = cut.equals("event") ? target : target.resolveSibling(target.getFileName() + ".tmp");
            var backup = fault.resolveSibling("fault-backup");
            if (cut.equals("event")) Files.move(fault, backup);
            Files.createDirectory(fault);
            try {
                assertThrows(Exception.class, () -> f.ledger.resolveOpenGate(f.paths, f.definition, "revise", "Clarify wording"), cut);
            } finally {
                Files.delete(fault);
                if (cut.equals("event")) Files.move(backup, fault);
            }
            var cold = new WorkflowFileLedger(FlowKernelProvider.create("liteflow"));
            assertEquals(current, cold.loadCurrent(f.paths), cut);
            try {
                new WorkflowRuntime(cold, f.handlers(), queued ? AgentTaskDispatchMode.WORKER : AgentTaskDispatchMode.INLINE)
                        .resume(new WorkflowCommand(f.root, f.ws));
            } catch (java.io.IOException | IllegalStateException expected) {
                assertFalse(cut.equals("gate"), "a failed first write leaves the original gate usable");
            }
            if (queued) new AgentWorker(cold, f.handlers()).runOne(new WorkflowCommand(f.root, f.ws));
            assertEquals(2, f.transport.calls.size(), cut + " must not consume an orphan successor");
            if (!cut.equals("gate")) {
                assertThrows(Exception.class, () -> cold.resolveOpenGate(f.paths, f.definition, "revise", "Do not replay partial decision"));
                assertThrows(Exception.class, () -> cold.retryActiveNode(f.paths, "Do not turn partial approval into retry"));
            }
        }
    }

