package dev.dual.runtime;

public enum AgentTaskDispatchMode {
    INLINE,
    WORKER
}

package dev.dual.runtime;

import java.util.Map;

/**
 * Resolves retry policy from the default failure catalog plus node-level
 * overrides.
 *
 * Keeping this outside WorkflowRuntime prevents retry limits from drifting
 * between auto-retry execution and operator-facing rejection messages.
 */
final class RetryPolicyResolver {
    private RetryPolicyResolver() {
    }

    static RetryPolicy resolve(String failureReason, Map<String, Object> config) {
        var defaultPolicy = RetryStrategies.forReason(failureReason);
        var maxRetries = config.get("retry.max_retries");
        var baseDelay = config.get("retry.base_delay_ms");
        var multiplier = config.get("retry.backoff_multiplier");
        if (maxRetries == null && baseDelay == null && multiplier == null) {
            return defaultPolicy;
        }
        return new RetryPolicy(
                maxRetries instanceof Number n ? n.intValue() : defaultPolicy.maxRetries(),
                baseDelay instanceof Number n ? n.longValue() : defaultPolicy.baseDelayMs(),
                multiplier instanceof Number n ? n.doubleValue() : defaultPolicy.backoffMultiplier()
        );
    }
}

package dev.dual.runtime;

import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeKind;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowDefinition;
import dev.dual.core.workflow.WorkflowStatus;
import dev.dual.ledger.file.NodeExecutionStatus;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkflowExecutionStatus;
import dev.dual.ledger.file.WorkflowExecutionDocument;
import dev.dual.ledger.file.WorkflowCurrentDocument;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkstreamPaths;
import dev.dual.runtime.handler.AgentExecutionAttemptReconciler;
import dev.dual.runtime.handler.AgentExecutionAttemptTimeoutPolicy;
import dev.dual.runtime.handler.ArtifactContractValidator;
import dev.dual.runtime.handler.ContractEventTypes;
import dev.dual.runtime.handler.DecisionHandler;
import dev.dual.runtime.handler.GateHandler;
import dev.dual.runtime.handler.HandlerRegistry;
import dev.dual.runtime.handler.TaskHandler;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Drives one workflow instance forward from the authoritative ledger state.
 *
 * Runtime owns transition execution and runtime facts only: it creates workflow
 * and node execution records, invokes handlers, validates artifact contracts,
 * and asks the ledger to route completed nodes. It must not infer product goal
 * satisfaction from prose, and it must guard terminal workflows before creating
 * any new execution side effects.
 */
public final class WorkflowRuntime {
    private final WorkflowFileLedger ledger;
    private final HandlerRegistry handlers;
    private final ArtifactContractValidator artifactContractValidator;
    private final AgentExecutionAttemptReconciler attemptReconciler;
    private final StaleRunningRecovery staleRunningRecovery;
    private final AgentTaskDispatchMode dispatchMode;

    public WorkflowRuntime(WorkflowFileLedger ledger, HandlerRegistry handlers) {
        this(ledger, handlers, AgentTaskDispatchMode.INLINE);
    }

    public WorkflowRuntime(WorkflowFileLedger ledger, HandlerRegistry handlers, AgentTaskDispatchMode dispatchMode) {
        if (ledger == null) {
            throw new IllegalArgumentException("ledger is required");
        }
        if (handlers == null) {
            throw new IllegalArgumentException("handlers is required");
        }
        this.ledger = ledger;
        this.handlers = handlers;
        this.dispatchMode = dispatchMode == null ? AgentTaskDispatchMode.INLINE : dispatchMode;
        this.artifactContractValidator = new ArtifactContractValidator();
        this.attemptReconciler = new AgentExecutionAttemptReconciler(new AgentExecutionAttemptTimeoutPolicy().timeout());
        this.staleRunningRecovery = new StaleRunningRecovery(ledger, attemptReconciler);
    }

    /**
     * Advances the current workflow until it reaches a gate, recovery boundary,
     * terminal state, or the current active-node snapshot is exhausted.
     *
     * Key steps:
     * 1. Load definition/current from the ledger.
     * 2. Refuse terminal workflows before creating a workflow execution.
     * 3. Create a workflow execution and per-node execution/task records.
     * 4. Execute handlers and validate structured artifacts.
     * 5. Finish the workflow execution with a typed runtime status.
     */
    public WorkflowRuntimeResult resume(WorkflowCommand command) throws Exception {
        var paths = new WorkstreamPaths(command.workspaceRoot(), new DualId(command.workstreamId()));
        var definition = ledger.loadDefinition(paths);
        var current = ledger.loadCurrent(paths);

        // Terminal observation is allowed elsewhere, but resume must be side-effect free.
        if (current.status().isTerminal()) {
            return new WorkflowRuntimeResult(
                    command.workstreamId(),
                    current.status(),
                    "",
                    "workflow is terminal: " + current.status()
            );
        }
        // Reconcile any in-flight agent run for the active node whose transport
        // never returned before this resume creates new execution side effects.
        // If a run is reconciled, stop at recovery instead of creating another
        // attempt for the same node.
        var reconciled = reconcileActiveNodeAttempts(command, paths, definition, current);
        if (reconciled != null) {
            return reconciled;
        }

        var workflowExecution = ledger.startWorkflowExecution(paths, current, "resume");
        var nodeExecutionIds = new ArrayList<String>();
        var workflowExecutionFinished = false;
        try {
            var outcome = resumeWithinExecution(command, paths, definition, current, workflowExecution, nodeExecutionIds);
            var finalResult = outcome.result();
            finishWorkflowExecution(paths, workflowExecution, nodeExecutionIds, outcome.executionStatus(), finalResult.message());
            workflowExecutionFinished = true;
            return finalResult;
        } catch (Exception failure) {
            if (!workflowExecutionFinished) {
                finishWorkflowExecution(paths, workflowExecution, nodeExecutionIds, WorkflowExecutionStatus.FAILED, failure.getMessage());
            }
            throw failure;
        }
    }

    private ResumeOutcome resumeWithinExecution(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds
    ) throws Exception {
        if (current.activeNodeInstanceIds().isEmpty()) {
            return stopped(new WorkflowRuntimeResult(command.workstreamId(), current.status(), "", "workflow has no active node"));
        }
        if (current.status() == WorkflowStatus.WAITING_FOR_RECOVERY) {
            var recoveryRejection = rejectRecoveryOrAutoRetry(command, paths, definition, current);
            if (recoveryRejection != null) {
                return stopped(recoveryRejection);
            }
            current = ledger.loadCurrent(paths);
        }
        var result = executeActiveSnapshot(command, paths, definition, current, workflowExecution, nodeExecutionIds);
        return new ResumeOutcome(result, workflowExecutionStatus(result.status()));
    }

    private WorkflowRuntimeResult reconcileActiveNodeAttempts(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current
    ) throws Exception {
        if (current.activeNodeInstanceIds().isEmpty()) {
            return null;
        }
        for (var activeNodeId : current.activeNodeInstanceIds()) {
            var node = ledger.loadNode(paths, activeNodeId);
            var count = attemptReconciler.reconcileRuns(paths.runsDir(), node.nodeDefinitionId());
            if (count <= 0) {
                continue;
            }
            if (node.status() == NodeStatus.RUNNING) {
                recoverStaleRunningNode(paths, node, node.result().getOrDefault("running_pid", ""));
            } else {
                ledger.completeAndRoute(
                        paths,
                        definition,
                        node.nodeInstanceId(),
                        NodeStatus.FAILED,
                        "STALE_RUNNING_ATTEMPT",
                        node.outputRefs(),
                        Map.of(
                                "reason", "STALE_RUNNING_ATTEMPT",
                                "message", "A previous agent execution attempt was reconciled to a typed terminal outcome before resume.",
                                "recoverable", true,
                                "reconciled_attempt_count", count
                        )
                );
            }
            var next = ledger.loadCurrent(paths);
            return new WorkflowRuntimeResult(
                    command.workstreamId(),
                    next.status(),
                    activeNodeDefinitionId(paths, next),
                    "workflow stopped at reconciled stale agent execution"
            );
        }
        return null;
    }

    private WorkflowRuntimeResult rejectRecoveryOrAutoRetry(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current
    ) throws Exception {
        var nodeDoc = ledger.loadNode(paths, current.activeNodeInstanceIds().get(0));
        var nodeDef = definition.node(nodeDoc.nodeDefinitionId());
        if (nodeDoc.status() == NodeStatus.FAILED && attemptAutoRetry(paths, nodeDoc, nodeDef)) {
            return null;
        }
        return rejectionResult(command, current, nodeDoc, nodeDef);
    }

    private WorkflowRuntimeResult executeActiveSnapshot(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds
    ) throws Exception {
        var activeSnapshot = new ArrayList<>(current.activeNodeInstanceIds());
        WorkflowRuntimeResult lastResult = null;

        for (var activeNodeId : activeSnapshot) {
            current = ledger.loadCurrent(paths);
            if (current.activeNodeInstanceIds().isEmpty()) {
                break;
            }
            if (!current.activeNodeInstanceIds().contains(activeNodeId)) {
                continue;
            }
            lastResult = executeActiveNode(command, paths, definition, workflowExecution, nodeExecutionIds, activeNodeId);
        }
        return lastResult != null
                ? lastResult
                : new WorkflowRuntimeResult(command.workstreamId(), current.status(), "", "workflow has no active node");
    }

    private WorkflowRuntimeResult executeActiveNode(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds,
            String activeNodeId
    ) throws Exception {
        var nodeDoc = ledger.loadNode(paths, activeNodeId);
        var nodeDefinition = definition.node(nodeDoc.nodeDefinitionId());

        if (nodeDefinition.kind() == NodeKind.GATE) {
            var node = ledger.loadCoreNode(paths, activeNodeId);
            handlers.gate(nodeDefinition.handlerType())
                    .openOrInspect(new GateHandler.GateContext(
                            command.workspaceRoot(), command.workstreamId(), nodeDefinition, node,
                            sourceOutcome(paths, activeNodeId)));
            return new WorkflowRuntimeResult(command.workstreamId(), WorkflowStatus.WAITING_FOR_HUMAN, nodeDefinition.id(), "waiting for human review");
        }

        var guardResult = resolveNodeForExecution(paths, nodeDoc);
        if (guardResult == null) {
            var refreshedCurrent = ledger.loadCurrent(paths);
            var refreshedNode = ledger.loadNode(paths, activeNodeId);
            var refreshedDefinition = definition.node(refreshedNode.nodeDefinitionId());
            return rejectionResult(command, refreshedCurrent, refreshedNode, refreshedDefinition);
        }

        if (dispatchMode == AgentTaskDispatchMode.WORKER) {
            return enqueueAgentTask(command, paths, workflowExecution, nodeDoc, nodeDefinition);
        }

        var result = executeAndRecordNode(command, paths, workflowExecution, nodeExecutionIds, nodeDoc, nodeDefinition);
        emitDomainEvents(paths, nodeDefinition.id(), nodeDefinition.handlerType(), nodeDoc.nodeInstanceId(), result);
        ledger.completeAndRoute(paths, definition, nodeDoc.nodeInstanceId(), result.status(), result.outcome(), result.outputRefs(), result.result());
        var next = ledger.loadCurrent(paths);
        openWaitingGates(command, paths, definition, next);
        var active = activeNodeDefinitionId(paths, next);
        var message = result.status() == NodeStatus.COMPLETED ? "resumed workflow" : "workflow stopped at " + result.status();
        return new WorkflowRuntimeResult(command.workstreamId(), next.status(), active, message);
    }

    private WorkflowRuntimeResult enqueueAgentTask(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowExecutionDocument workflowExecution,
            NodeInstanceDocument nodeDoc,
            NodeDefinition nodeDefinition
    ) throws Exception {
        var agentTask = ledger.createAgentTask(paths, workflowExecution.workflowExecutionId(), nodeDefinition, nodeDoc);
        ledger.markQueuedForAgentTask(paths, nodeDoc.nodeInstanceId(), agentTask.agentTaskId());
        return new WorkflowRuntimeResult(command.workstreamId(), WorkflowStatus.RUNNING, nodeDefinition.id(), "agent task queued");
    }

    private WorkflowRuntimeResult rejectionResult(
            WorkflowCommand command,
            WorkflowCurrentDocument current,
            NodeInstanceDocument node,
            NodeDefinition definition
    ) {
        var rejection = NodeExecutionGuard.reject(node, definition);
        return new WorkflowRuntimeResult(command.workstreamId(), current.status(), node.nodeDefinitionId(), rejection.message());
    }

    private String activeNodeDefinitionId(WorkstreamPaths paths, WorkflowCurrentDocument current) throws Exception {
        if (current.activeNodeInstanceIds().isEmpty()) {
            return "";
        }
        return ledger.loadNode(paths, current.activeNodeInstanceIds().get(0)).nodeDefinitionId();
    }

    private static ResumeOutcome stopped(WorkflowRuntimeResult result) {
        return new ResumeOutcome(result, WorkflowExecutionStatus.STOPPED);
    }

    private record ResumeOutcome(WorkflowRuntimeResult result, WorkflowExecutionStatus executionStatus) {
    }

    private NodeResult executeAndRecordNode(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds,
            NodeInstanceDocument nodeDoc,
            NodeDefinition nodeDefinition
    ) throws Exception {
        long pid = ProcessHandle.current().pid();
        var agentTask = ledger.createAgentTask(paths, workflowExecution.workflowExecutionId(), nodeDefinition, nodeDoc);
        var nodeExecution = ledger.startNodeExecution(paths, workflowExecution.workflowExecutionId(), nodeDoc, agentTask, pid);
        agentTask = ledger.markAgentTaskRunning(paths, agentTask, nodeExecution.nodeExecutionId());
        nodeExecutionIds.add(nodeExecution.nodeExecutionId());
        ledger.markRunning(paths, nodeDoc.nodeInstanceId(), pid);

        var node = ledger.loadCoreNode(paths, nodeDoc.nodeInstanceId());
        try {
            var result = dev.dual.runtime.handler.EvidenceCollection.execute(command.workspaceRoot(),
                    command.workstreamId(), nodeDoc, () -> executeNode(command, nodeDefinition, node));
            result = artifactContractValidator.validateAndFinalize(
                    command.workspaceRoot(),
                    command.workstreamId(),
                    node.nodeInstanceId(),
                    nodeDefinition,
                    node.inputRefs(),
                    result
            );
            ledger.markAgentTaskFinished(paths, agentTask, result);
            ledger.finishNodeExecution(paths, nodeExecution, result);
            return result;
        } catch (Exception nodeFailure) {
            ledger.markAgentTaskFailed(paths, agentTask, nodeFailure);
            ledger.failNodeExecution(paths, nodeExecution, nodeFailure);
            throw nodeFailure;
        }
    }

    private NodeResult executeNode(WorkflowCommand command, NodeDefinition nodeDefinition, dev.dual.core.workflow.NodeInstance node) throws Exception {
        return switch (nodeDefinition.kind()) {
            case TASK -> handlers.task(nodeDefinition.handlerType())
                    .execute(new TaskHandler.TaskContext(command.workspaceRoot(), command.workstreamId(), nodeDefinition, node));
            case DECISION -> handlers.decision(nodeDefinition.handlerType())
                    .evaluate(new DecisionHandler.DecisionContext(command.workspaceRoot(), command.workstreamId(), nodeDefinition, node));
            case GATE -> throw new IllegalStateException("gate nodes are handled before routing");
        };
    }

    private void finishWorkflowExecution(
            WorkstreamPaths paths,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds,
            WorkflowExecutionStatus status,
            String stopReason
    ) throws Exception {
        ledger.finishWorkflowExecution(paths, workflowExecution, nodeExecutionIds, status, stopReason);
    }

    private static WorkflowExecutionStatus workflowExecutionStatus(WorkflowStatus status) {
        return switch (status) {
            case CREATED -> WorkflowExecutionStatus.CREATED;
            case RUNNING -> WorkflowExecutionStatus.STOPPED;
            case WAITING_FOR_HUMAN -> WorkflowExecutionStatus.WAITING_FOR_HUMAN;
            case WAITING_FOR_RECOVERY -> WorkflowExecutionStatus.WAITING_FOR_RECOVERY;
            case BLOCKED -> WorkflowExecutionStatus.BLOCKED;
            case COMPLETED -> WorkflowExecutionStatus.ENDED;
            case FAILED -> WorkflowExecutionStatus.FAILED;
        };
    }

    private void openWaitingGates(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            WorkflowCurrentDocument current
    ) throws Exception {
        if (current.status() != WorkflowStatus.WAITING_FOR_HUMAN) {
            return;
        }
        for (var activeNodeId : current.activeNodeInstanceIds()) {
            var nodeDoc = ledger.loadNode(paths, activeNodeId);
            if (nodeDoc.kind() != NodeKind.GATE) {
                continue;
            }
            var nodeDefinition = definition.node(nodeDoc.nodeDefinitionId());
            var node = ledger.loadCoreNode(paths, activeNodeId);
            handlers.gate(nodeDefinition.handlerType())
                    .openOrInspect(new GateHandler.GateContext(
                            command.workspaceRoot(), command.workstreamId(), nodeDefinition, node,
                            sourceOutcome(paths, activeNodeId)));
        }
    }

    private String sourceOutcome(WorkstreamPaths paths, String nodeInstanceId) throws Exception {
        var value = ledger.loadOpenGateForNode(paths, nodeInstanceId).result().get("source_outcome");
        if (value == null || String.valueOf(value).isBlank()) {
            throw new IllegalStateException("open gate is missing source_outcome: " + nodeInstanceId);
        }
        return String.valueOf(value);
    }

    private void emitDomainEvents(WorkstreamPaths paths, String nodeDefinitionId,
                                 String handlerType, String nodeInstanceId,
                                 NodeResult result) throws Exception {
        if (result.status() != NodeStatus.COMPLETED) {
            return;
        }
        String eventId = "domain-" + nodeInstanceId;

        var commonPayload = new LinkedHashMap<String, Object>();
        commonPayload.put("handler_type", handlerType);
        commonPayload.put("node_id", nodeDefinitionId);
        commonPayload.put("node_instance_id", nodeInstanceId);

        switch (handlerType) {
            case "contract.compile" -> {
                commonPayload.put("contract_id", result.result().getOrDefault("contract_id", ""));
                commonPayload.put("contract_status", result.result().getOrDefault("contract_status", ""));
                ledger.appendEvent(paths, eventId,
                        ContractEventTypes.COMPILATION_COMPLETED, commonPayload);
            }
            case "acceptance.failure_classify" -> {
                commonPayload.put("category", result.result().getOrDefault("category", ""));
                commonPayload.put("matched_rule", result.result().getOrDefault("matched_rule", ""));
                commonPayload.put("review_decision", result.result().getOrDefault("review_decision", ""));
                ledger.appendEvent(paths, eventId,
                        ContractEventTypes.FAILURE_CLASSIFIED, commonPayload);
            }
            default -> { /* no domain event for this handler type */ }
        }
    }

    private boolean attemptAutoRetry(WorkstreamPaths paths, NodeInstanceDocument node, NodeDefinition nodeDef) throws Exception {
        var outcome = outcomeMap(node.result());
        if (!outcome.isEmpty()) {
            var retryPolicy = text(outcome.get("retryPolicy"));
            if (!"AUTO_ALLOWED".equals(retryPolicy)) {
                return false;
            }
            var policy = RetryPolicyResolver.resolve(text(outcome.get("primaryReason")), nodeDef.config());
            return autoRetry(paths, node, policy);
        }
        var recoverable = node.result().get("acpx_failure.recoverable");
        if (!Boolean.TRUE.equals(recoverable)) {
            return false;
        }
        var reasonValue = node.result().getOrDefault("acpx_failure.reason", "");
        var reason = reasonValue instanceof String s ? s : String.valueOf(reasonValue);
        var policy = RetryPolicyResolver.resolve(reason, nodeDef.config());
        return autoRetry(paths, node, policy);
    }

    private boolean autoRetry(WorkstreamPaths paths, NodeInstanceDocument node, RetryPolicy policy) throws Exception {
        var countValue = node.result().getOrDefault("auto_retry_count", 0);
        var count = (countValue instanceof Number n) ? n.intValue() : 0;
        if (count >= policy.maxRetries()) {
            return false;
        }

        var delay = policy.delayForAttempt(count + 1);
        ledger.autoRetryNode(paths, node.nodeInstanceId(), delay);
        if (delay > 0) {
            Thread.sleep(delay);
        }
        return true;
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> outcomeMap(Map<String, Object> result) {
        var value = result.get("agent_execution_outcome");
        return value instanceof Map<?, ?> map ? (Map<String, Object>) map : Map.of();
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    private Boolean resolveNodeForExecution(WorkstreamPaths paths, NodeInstanceDocument node) throws Exception {
        return switch (node.status()) {
            case READY -> true;
            case RUNNING -> resolveRunningNode(paths, node);
            case BLOCKED, WAITING, COMPLETED, CREATED, SKIPPED, FAILED -> null;
        };
    }

    private Boolean resolveRunningNode(WorkstreamPaths paths, NodeInstanceDocument node) throws Exception {
        if (hasActiveQueuedAgentTask(paths, node)) {
            return null;
        }
        var latestExecution = ledger.latestNodeExecution(paths, node);
        if (latestExecution.isPresent()) {
            var execution = latestExecution.get();
            if (execution.status() == NodeExecutionStatus.RUNNING) {
                var pid = execution.pid() == null ? 0L : execution.pid();
                var alive = pid > 0 && ProcessHandle.of(pid).map(ProcessHandle::isAlive).orElse(false);
                if (alive) {
                    return null;
                }
                ledger.markNodeExecutionStale(paths, execution, "detected by runtime resume");
                recoverStaleRunningNode(paths, node, pid <= 0 ? "" : pid);
                return null;
            }
        }
        var pidValue = node.result().get("running_pid");
        if (pidValue instanceof Number number) {
            var pid = number.longValue();
            var alive = ProcessHandle.of(pid).map(ProcessHandle::isAlive).orElse(false);
            if (alive) {
                return null;
            }
            recoverStaleRunningNode(paths, node, pid);
            return null;
        }
        recoverStaleRunningNode(paths, node, "");
        return null;
    }

    private boolean hasActiveQueuedAgentTask(WorkstreamPaths paths, NodeInstanceDocument node) throws Exception {
        var taskId = node.result().get("queued_agent_task_id");
        if (taskId == null || String.valueOf(taskId).isBlank()) {
            return false;
        }
        return ledger.readAgentTask(paths, String.valueOf(taskId))
                .map(task -> task.status() == dev.dual.ledger.file.AgentTaskStatus.QUEUED
                        || task.status() == dev.dual.ledger.file.AgentTaskStatus.RUNNING)
                .orElse(false);
    }

    private void recoverStaleRunningNode(WorkstreamPaths paths, NodeInstanceDocument node, Object pid) throws Exception {
        // Close any in-flight agent run.json (transport never returned / process killed) to a
        // typed terminal executionAttempt+executionOutcome before the node/workflow transition.
        ledger.appendEvent(paths, "stale-running-" + node.nodeInstanceId() + "-" + System.currentTimeMillis(),
                "node_stale_running_detected", Map.of(
                        "node", node.nodeDefinitionId(),
                        "node_instance_id", node.nodeInstanceId(),
                        "previous_running_pid", pid,
                        "action", "move_to_recovery"
                ));
        staleRunningRecovery.recover(paths, "detected by runtime resume");
    }

}

package dev.dual.runtime;

import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeKind;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowStatus;
import dev.dual.ledger.file.AgentTaskDocument;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkflowExecutionDocument;
import dev.dual.ledger.file.WorkflowExecutionStatus;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkstreamPaths;
import dev.dual.runtime.handler.ArtifactContractValidator;
import dev.dual.runtime.handler.DecisionHandler;
import dev.dual.runtime.handler.GateHandler;
import dev.dual.runtime.handler.HandlerRegistry;
import dev.dual.runtime.handler.TaskHandler;

import java.util.ArrayList;

/**
 * Executes one queued AgentTask.
 *
 * Worker owns dispatch execution only. It claims the queued task, records a
 * NodeExecution, invokes the handler, validates the artifact contract, and then
 * returns the node result to the ledger router. It does not choose workflow
 * transitions and it does not decide goal satisfaction.
 */
public final class AgentWorker {
    private final WorkflowFileLedger ledger;
    private final HandlerRegistry handlers;
    private final ArtifactContractValidator artifactContractValidator;

    public AgentWorker(WorkflowFileLedger ledger, HandlerRegistry handlers) {
        if (ledger == null) {
            throw new IllegalArgumentException("ledger is required");
        }
        if (handlers == null) {
            throw new IllegalArgumentException("handlers is required");
        }
        this.ledger = ledger;
        this.handlers = handlers;
        this.artifactContractValidator = new ArtifactContractValidator();
    }

    public AgentWorkerResult runOne(WorkflowCommand command) throws Exception {
        var paths = new WorkstreamPaths(command.workspaceRoot(), new DualId(command.workstreamId()));
        var task = ledger.firstQueuedAgentTask(paths);
        if (task.isEmpty()) {
            var current = ledger.loadCurrent(paths);
            return new AgentWorkerResult(command.workstreamId(), "", "", current.status(), false, "no queued agent task");
        }
        return executeQueued(command, paths, task.get());
    }

    private AgentWorkerResult executeQueued(
            WorkflowCommand command,
            WorkstreamPaths paths,
            AgentTaskDocument task
    ) throws Exception {
        var definition = ledger.loadDefinition(paths);
        var current = ledger.loadCurrent(paths);
        var nodeDoc = ledger.loadNode(paths, task.nodeInstanceId());
        var nodeDefinition = definition.node(nodeDoc.nodeDefinitionId());
        if (nodeDoc.status() != NodeStatus.RUNNING) {
            return new AgentWorkerResult(command.workstreamId(), task.agentTaskId(), nodeDefinition.id(),
                    current.status(), false, "queued task node is not running: " + nodeDoc.status());
        }

        var workflowExecution = ledger.startWorkflowExecution(paths, current, "worker");
        var nodeExecutionIds = new ArrayList<String>();
        var finished = false;
        try {
            var result = executeAndRecord(command, paths, workflowExecution, nodeExecutionIds, task, nodeDoc, nodeDefinition);
            ledger.completeAndRoute(paths, definition, nodeDoc.nodeInstanceId(), result.status(), result.outcome(),
                    result.outputRefs(), result.result());
            var next = ledger.loadCurrent(paths);
            openWaitingGates(command, paths, definition, next);
            var active = activeNodeDefinitionId(paths, next);
            ledger.finishWorkflowExecution(paths, workflowExecution, nodeExecutionIds, workflowExecutionStatus(next.status()),
                    "worker completed " + nodeDefinition.id());
            finished = true;
            return new AgentWorkerResult(command.workstreamId(), task.agentTaskId(), active, next.status(), true,
                    result.status() == NodeStatus.COMPLETED ? "agent task completed" : "workflow stopped at " + result.status());
        } catch (Exception failure) {
            if (!finished) {
                ledger.finishWorkflowExecution(paths, workflowExecution, nodeExecutionIds, WorkflowExecutionStatus.FAILED,
                        failure.getMessage());
            }
            throw failure;
        }
    }

    private NodeResult executeAndRecord(
            WorkflowCommand command,
            WorkstreamPaths paths,
            WorkflowExecutionDocument workflowExecution,
            ArrayList<String> nodeExecutionIds,
            AgentTaskDocument task,
            NodeInstanceDocument nodeDoc,
            NodeDefinition nodeDefinition
    ) throws Exception {
        long pid = ProcessHandle.current().pid();
        var nodeExecution = ledger.startNodeExecution(paths, workflowExecution.workflowExecutionId(), nodeDoc, task, pid);
        task = ledger.markAgentTaskRunning(paths, task, nodeExecution.nodeExecutionId());
        nodeExecutionIds.add(nodeExecution.nodeExecutionId());
        ledger.markRunning(paths, nodeDoc.nodeInstanceId(), pid);
        var node = ledger.loadCoreNode(paths, nodeDoc.nodeInstanceId());
        try {
            var result = dev.dual.runtime.handler.EvidenceCollection.execute(command.workspaceRoot(),
                    command.workstreamId(), nodeDoc, () -> executeNode(command, nodeDefinition, node));
            result = artifactContractValidator.validateAndFinalize(
                    command.workspaceRoot(),
                    command.workstreamId(),
                    node.nodeInstanceId(),
                    nodeDefinition,
                    node.inputRefs(),
                    result
            );
            ledger.markAgentTaskFinished(paths, task, result);
            ledger.finishNodeExecution(paths, nodeExecution, result);
            return result;
        } catch (Exception nodeFailure) {
            ledger.markAgentTaskFailed(paths, task, nodeFailure);
            ledger.failNodeExecution(paths, nodeExecution, nodeFailure);
            throw nodeFailure;
        }
    }

    private NodeResult executeNode(WorkflowCommand command, NodeDefinition nodeDefinition, dev.dual.core.workflow.NodeInstance node)
            throws Exception {
        return switch (nodeDefinition.kind()) {
            case TASK -> handlers.task(nodeDefinition.handlerType())
                    .execute(new TaskHandler.TaskContext(command.workspaceRoot(), command.workstreamId(), nodeDefinition, node));
            case DECISION -> handlers.decision(nodeDefinition.handlerType())
                    .evaluate(new DecisionHandler.DecisionContext(command.workspaceRoot(), command.workstreamId(), nodeDefinition, node));
            case GATE -> throw new IllegalStateException("gate nodes are not agent tasks");
        };
    }

    private void openWaitingGates(
            WorkflowCommand command,
            WorkstreamPaths paths,
            dev.dual.core.workflow.WorkflowDefinition definition,
            dev.dual.ledger.file.WorkflowCurrentDocument current
    ) throws Exception {
        if (current.status() != WorkflowStatus.WAITING_FOR_HUMAN) {
            return;
        }
        for (var activeNodeId : current.activeNodeInstanceIds()) {
            var nodeDoc = ledger.loadNode(paths, activeNodeId);
            if (nodeDoc.kind() != NodeKind.GATE) {
                continue;
            }
            var nodeDefinition = definition.node(nodeDoc.nodeDefinitionId());
            var node = ledger.loadCoreNode(paths, activeNodeId);
            handlers.gate(nodeDefinition.handlerType())
                    .openOrInspect(new GateHandler.GateContext(
                            command.workspaceRoot(), command.workstreamId(), nodeDefinition, node,
                            sourceOutcome(paths, activeNodeId)));
        }
    }

    private String sourceOutcome(WorkstreamPaths paths, String nodeInstanceId) throws Exception {
        var value = ledger.loadOpenGateForNode(paths, nodeInstanceId).result().get("source_outcome");
        if (value == null || String.valueOf(value).isBlank()) {
            throw new IllegalStateException("open gate is missing source_outcome: " + nodeInstanceId);
        }
        return String.valueOf(value);
    }

    private String activeNodeDefinitionId(WorkstreamPaths paths, dev.dual.ledger.file.WorkflowCurrentDocument current)
            throws Exception {
        if (current.activeNodeInstanceIds().isEmpty()) {
            return "";
        }
        return ledger.loadNode(paths, current.activeNodeInstanceIds().get(0)).nodeDefinitionId();
    }

    private static WorkflowExecutionStatus workflowExecutionStatus(WorkflowStatus status) {
        return switch (status) {
            case CREATED -> WorkflowExecutionStatus.CREATED;
            case RUNNING -> WorkflowExecutionStatus.STOPPED;
            case WAITING_FOR_HUMAN -> WorkflowExecutionStatus.WAITING_FOR_HUMAN;
            case WAITING_FOR_RECOVERY -> WorkflowExecutionStatus.WAITING_FOR_RECOVERY;
            case BLOCKED -> WorkflowExecutionStatus.BLOCKED;
            case COMPLETED -> WorkflowExecutionStatus.ENDED;
            case FAILED -> WorkflowExecutionStatus.FAILED;
        };
    }
}

package dev.dual.runtime;

import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.ledger.file.NodeInstanceDocument;

import java.util.Map;

/**
 * Explains why an active node is not executable by resume.
 *
 * This is a runtime guard/projection boundary: it reads typed node state and
 * retry policy facts, then produces a stable operator message. It does not
 * mutate ledger state and does not decide workflow routing.
 */
final class NodeExecutionGuard {
    private NodeExecutionGuard() {
    }

    static NodeExecutionRejection reject(NodeInstanceDocument node, NodeDefinition definition) {
        return new NodeExecutionRejection(switch (node.status()) {
            case RUNNING -> runningMessage(node);
            case FAILED -> failedMessage(node, definition.config());
            case BLOCKED -> "node " + node.nodeDefinitionId() + " BLOCKED (revision limit), use dualctl retry or recovery abort";
            case WAITING -> "node " + node.nodeDefinitionId() + " is WAITING, not executable via resume";
            case COMPLETED -> "node " + node.nodeDefinitionId() + " already COMPLETED, should not be active";
            case CREATED, SKIPPED -> "node " + node.nodeDefinitionId() + " has illegal status: " + node.status();
            default -> "unexpected node status: " + node.status();
        });
    }

    private static String runningMessage(NodeInstanceDocument node) {
        var pid = node.result().get("running_pid");
        return "node " + node.nodeDefinitionId() + " is RUNNING (PID=" + pid + "), agent process still alive";
    }

    private static String failedMessage(NodeInstanceDocument node, Map<String, Object> config) {
        var outcome = outcomeMap(node.result());
        if (!outcome.isEmpty()) {
            var retryPolicy = text(outcome.get("retryPolicy"));
            var reason = text(outcome.get("primaryReason"));
            if ("AUTO_ALLOWED".equals(retryPolicy)) {
                var policy = RetryPolicyResolver.resolve(reason, config);
                return autoRetryLimitMessage(node, policy, reason);
            }
            if ("MANUAL_ONLY".equals(retryPolicy)) {
                return "node " + node.nodeDefinitionId() + " FAILED (" + reason + "), manual recovery or retry required";
            }
            return "node " + node.nodeDefinitionId() + " FAILED (" + reason + "), use dualctl retry after inspection";
        }
        var recoverable = firstNonNull(node.result().get("acpx_failure.recoverable"), node.result().get("recoverable"));
        if (!Boolean.TRUE.equals(recoverable)) {
            return "node " + node.nodeDefinitionId() + " FAILED (not recoverable), use dualctl retry";
        }
        var reason = failureReason(node);
        var policy = RetryPolicyResolver.resolve(reason, config);
        return autoRetryLimitMessage(node, policy, reason);
    }

    private static String autoRetryLimitMessage(NodeInstanceDocument node, RetryPolicy policy, String reason) {
        var count = node.result().getOrDefault("auto_retry_count", 0);
        var countInt = count instanceof Number n ? n.intValue() : 0;
        return "node " + node.nodeDefinitionId() + " FAILED, auto-retry limit reached ("
                + countInt + "/" + policy.maxRetries() + " for " + reason + "), use dualctl retry";
    }

    private static String failureReason(NodeInstanceDocument node) {
        var reasonValue = node.result().getOrDefault("acpx_failure.reason", "");
        if (String.valueOf(reasonValue).isBlank()) {
            reasonValue = node.result().getOrDefault("reason", "");
        }
        return reasonValue instanceof String s ? s : String.valueOf(reasonValue);
    }

    private static Object firstNonNull(Object first, Object second) {
        return first != null ? first : second;
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> outcomeMap(Map<String, Object> result) {
        var value = result.get("agent_execution_outcome");
        return value instanceof Map<?, ?> map ? (Map<String, Object>) map : Map.of();
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    record NodeExecutionRejection(String message) {
    }
}

package dev.dual.runtime;

import java.util.Map;

public final class RetryStrategies {
    private static final RetryPolicy DEFAULT_POLICY = new RetryPolicy(3, 1000, 1.0);

    private static final Map<String, RetryPolicy> POLICIES = Map.of(
            "RECOVERABLE_RATE_LIMIT", new RetryPolicy(5, 3000, 2.0),
            "RECOVERABLE_SESSION_MISSING", new RetryPolicy(3, 2000, 1.5),
            "RECOVERABLE_AGENT_RECONNECT", new RetryPolicy(3, 2000, 1.5),
            "RECOVERABLE_AGENT_AUTH_FAILED", new RetryPolicy(0, 0, 1.0),
            "RECOVERABLE_PROVIDER_CONNECTION_FAILED", new RetryPolicy(3, 3000, 2.0),
            "RECOVERABLE_CONTEXT_WINDOW", new RetryPolicy(2, 1000, 1.0),
            "RECOVERABLE_AGENT_OUTPUT_INTERRUPTED", new RetryPolicy(2, 2000, 1.5)
    );

    public static RetryPolicy forReason(String failureReason) {
        return POLICIES.getOrDefault(failureReason, DEFAULT_POLICY);
    }

    private RetryStrategies() {}
}

package dev.dual.runtime;

import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkstreamPaths;
import dev.dual.runtime.handler.AgentExecutionAttemptReconciler;
import dev.dual.runtime.handler.AgentExecutionAttemptTimeoutPolicy;

/**
 * Performs stale execution closure before moving the node instance to recovery.
 */
public final class StaleRunningRecovery {
    private final WorkflowFileLedger ledger;
    private final AgentExecutionAttemptReconciler reconciler;

    public StaleRunningRecovery(WorkflowFileLedger ledger) {
        this(ledger, new AgentExecutionAttemptReconciler(new AgentExecutionAttemptTimeoutPolicy().timeout()));
    }

    StaleRunningRecovery(WorkflowFileLedger ledger, AgentExecutionAttemptReconciler reconciler) {
        if (ledger == null || reconciler == null) {
            throw new IllegalArgumentException("ledger and reconciler are required");
        }
        this.ledger = ledger;
        this.reconciler = reconciler;
    }

    public Result recover(WorkstreamPaths paths, String note) throws Exception {
        var reconciled = reconciler.reconcileRuns(paths.runsDir());
        assertExecutionsQuiescent(paths);
        ledger.recoverStaleRunningNode(paths, note);
        return new Result(0, reconciled);
    }

    public Result terminateAndRecover(WorkstreamPaths paths, String note) throws Exception {
        var terminated = reconciler.terminateInFlightProcesses(paths.runsDir());
        var reconciled = reconciler.reconcileRuns(paths.runsDir());
        assertExecutionsQuiescent(paths);
        ledger.recoverStaleRunningNode(paths, note);
        return new Result(terminated, reconciled);
    }

    public record Result(int terminatedProcessTrees, int reconciledRuns) {
    }

    private void assertExecutionsQuiescent(WorkstreamPaths paths) throws Exception {
        var inFlight = reconciler.countInFlightRuns(paths.runsDir());
        if (inFlight > 0) {
            throw new IllegalStateException(
                    "stale recovery refused because " + inFlight + " agent run(s) remain in-flight");
        }
    }
}

package dev.dual.runtime.handler;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

record AgentEvidenceState(
        boolean blocking,
        int evidenceCount,
        int missingEvidenceCount,
        int mustFixCount,
        int acceptanceNoteCount,
        int openRiskCount
) {
    static AgentEvidenceState from(AgentOutputContractDocument document) {
        return new AgentEvidenceState(
                document.blocking(),
                document.evidence().size(),
                document.missingEvidence().size(),
                document.mustFix().size(),
                document.acceptanceNotes().size(),
                document.openRisks().size()
        );
    }

    static AgentEvidenceState fromSidecar(Map<String, Object> document) {
        return new AgentEvidenceState(
                booleanValue(document.get("blocking")),
                listSize(document.get("evidence")),
                listSize(document.get("missing_evidence")),
                listSize(document.get("must_fix")),
                listSize(document.get("acceptance_notes")),
                listSize(document.get("open_risks"))
        );
    }

    boolean hasBlockingDecisionIssues() {
        return blocking || mustFixCount > 0;
    }

    boolean hasMaterialEvidenceGaps() {
        return missingEvidenceCount > 0;
    }

    boolean hasFinalAcceptanceConflicts() {
        return hasBlockingDecisionIssues() || hasMaterialEvidenceGaps();
    }

    boolean hasBlockingIssues() {
        return hasBlockingDecisionIssues() || hasMaterialEvidenceGaps();
    }

    Map<String, Object> toMap() {
        var result = new LinkedHashMap<String, Object>();
        result.put("blocking", blocking);
        result.put("evidence_count", evidenceCount);
        result.put("missing_evidence_count", missingEvidenceCount);
        result.put("must_fix_count", mustFixCount);
        result.put("acceptance_note_count", acceptanceNoteCount);
        result.put("open_risk_count", openRiskCount);
        return result;
    }

    private static int listSize(Object value) {
        return value instanceof List<?> list ? list.size() : 0;
    }

    private static boolean booleanValue(Object value) {
        if (value instanceof Boolean bool) {
            return bool;
        }
        return value != null && Boolean.parseBoolean(String.valueOf(value));
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.ledger.file.NodeExecutionStatus;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkstreamPaths;

import java.nio.file.Path;
import java.util.Optional;

/** Binds a projected agent-result sidecar to its authoritative ledger occurrence. */
final class AgentOutputLineageVerifier {
    private AgentOutputLineageVerifier() {
    }

    static Optional<String> violation(
            Path workspaceRoot,
            String workstreamId,
            Path sidecarPath,
            AgentOutputContractDocument document
    ) {
        if (!document.hasValidatedLineage(workstreamId, workspaceRoot, sidecarPath)) {
            return Optional.of("sidecar fields or source path are not internally consistent");
        }
        try {
            var paths = new WorkstreamPaths(workspaceRoot, new DualId(workstreamId));
            var ledger = new WorkflowFileLedger();
            var node = ledger.loadNode(paths, document.nodeInstanceId());
            if (!document.nodeId().equals(node.nodeDefinitionId())) {
                return Optional.of("sidecar node_id does not match the ledger node occurrence");
            }
            if (node.status() != NodeStatus.COMPLETED) {
                return Optional.of("sidecar node occurrence is not completed");
            }
            var sidecarRef = relativeRef(workspaceRoot, sidecarPath);
            if (!containsRef(node.outputRefs(), document.sourceOutputRef())
                    || !containsRef(node.outputRefs(), sidecarRef)) {
                return Optional.of("sidecar source is not published by the ledger node occurrence");
            }
            if (!document.runId().equals(text(node.result().get("run_id")))) {
                return Optional.of("sidecar run_id does not match the ledger node result");
            }
            if (!document.decision().equals(text(node.result().get("decision")))) {
                return Optional.of("sidecar decision does not match the ledger node result");
            }
            var expectedHash = text(node.result().get("contract_sidecar_sha256"));
            if (expectedHash.isBlank()
                    || !expectedHash.equals(AgentOutputContractSidecar.sha256(sidecarPath))) {
                return Optional.of("sidecar content hash does not match the ledger node result");
            }
            var execution = ledger.latestNodeExecution(paths, node);
            if (execution.isEmpty()) {
                return Optional.of("sidecar node occurrence has no execution fact");
            }
            var actual = execution.get();
            if (actual.status() != NodeExecutionStatus.SUCCEEDED
                    || !document.nodeInstanceId().equals(actual.nodeInstanceId())
                    || !document.nodeId().equals(actual.nodeDefinitionId())
                    || !document.runId().equals(actual.runRef())) {
                return Optional.of("sidecar lineage does not match the successful node execution");
            }
            if (!containsRef(actual.outputRefs(), document.sourceOutputRef())
                    || !containsRef(actual.outputRefs(), sidecarRef)) {
                return Optional.of("sidecar source is not published by the node execution");
            }
            if (!document.decision().equals(text(actual.result().get("decision")))) {
                return Optional.of("sidecar decision does not match the node execution result");
            }
            if (!expectedHash.equals(text(actual.result().get("contract_sidecar_sha256")))) {
                return Optional.of("sidecar content hash does not match the node execution result");
            }
            return Optional.empty();
        } catch (Exception e) {
            return Optional.of("sidecar ledger occurrence cannot be resolved: " + e.getMessage());
        }
    }

    private static String relativeRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize()
                .relativize(path.toAbsolutePath().normalize())
                .toString();
    }

    private static boolean containsRef(java.util.List<String> refs, String expected) {
        var normalized = normalize(expected);
        return refs.stream().map(AgentOutputLineageVerifier::normalize).anyMatch(normalized::equals);
    }

    private static String normalize(String value) {
        return value == null ? "" : value.replace('\\', '/');
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;

import java.io.IOException;
import java.nio.file.Path;
import java.util.HashSet;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.function.UnaryOperator;

/**
 * Marks verified typed payloads inside a context package so later free-text
 * projections can preserve their serialized bytes.
 */
public final class TypedContextPayloadBoundary {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper().registerModule(new JavaTimeModule());
    static final String START = "<!-- dual:typed-payload:start -->";
    static final String END = "<!-- dual:typed-payload:end -->";

    private TypedContextPayloadBoundary() {
    }

    public static String wrap(String payload) {
        return START + "\n" + Objects.requireNonNull(payload, "payload") + "\n" + END;
    }

    public static String wrapJson(Object payload) {
        try {
            return wrap("```json\n"
                    + OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(payload)
                    + "\n```");
        } catch (IOException failure) {
            throw new IllegalArgumentException("typed context payload cannot be serialized", failure);
        }
    }

    public static Optional<String> wrapVerifiedProposal(
            TaskContractProposalReference reference,
            Path workspaceRoot,
            String workstreamId,
            ObjectMapper objectMapper
    ) {
        return reference.resolveVerifiedProposal(workspaceRoot, workstreamId, objectMapper)
                .map(TypedContextPayloadBoundary::wrapJson);
    }

    public static TrustedPayloads trustOnce(Set<String> trustedWrappedPayloads) {
        return new TrustedPayloads(trustedWrappedPayloads);
    }

    public static String transformUntyped(
            String content,
            TrustedPayloads trustedPayloads,
            UnaryOperator<String> transform
    ) {
        Objects.requireNonNull(content, "content");
        Objects.requireNonNull(trustedPayloads, "trustedPayloads");
        Objects.requireNonNull(transform, "transform");
        var result = new StringBuilder(content.length());
        int cursor = 0;
        while (cursor < content.length()) {
            int start = content.indexOf(START, cursor);
            if (start < 0) {
                result.append(transform.apply(content.substring(cursor)));
                break;
            }
            int end = content.indexOf(END, start + START.length());
            if (end < 0) {
                // An incomplete boundary is not trusted; sanitize it as free text.
                result.append(transform.apply(content.substring(cursor)));
                break;
            }
            result.append(transform.apply(content.substring(cursor, start)));
            int boundaryEnd = end + END.length();
            var candidate = content.substring(start, boundaryEnd);
            if (trustedPayloads.consume(candidate)) {
                result.append(content, start + START.length(), end);
            }
            cursor = boundaryEnd;
        }
        return result.toString();
    }

    public static final class TrustedPayloads {
        private final Set<String> remaining;

        private TrustedPayloads(Set<String> trustedWrappedPayloads) {
            this.remaining = new HashSet<>(Objects.requireNonNull(
                    trustedWrappedPayloads, "trustedWrappedPayloads"));
        }

        private boolean consume(String candidate) {
            return remaining.remove(candidate);
        }
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.node.ObjectNode;
import dev.dual.core.execution.ArtifactContractResult;
import dev.dual.core.execution.AgentResultContractResult;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.regex.Pattern;

public final class ArtifactContractValidator {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };
    private final AgentResultEnvelopeParser resultParser = new AgentResultEnvelopeParser();
    private final AgentResultEnvelopeValidator resultValidator = new AgentResultEnvelopeValidator();
    private final AgentResultDocumentProjector resultProjector = new AgentResultDocumentProjector();
    private final TaskContractRevisionContextResolver revisionContextResolver =
            new TaskContractRevisionContextResolver();
    private final TaskContractProposalRevisionMerger revisionMerger =
            new TaskContractProposalRevisionMerger();

    public NodeResult validate(Path workspaceRoot, NodeDefinition nodeDefinition, NodeResult result) throws Exception {
        return validate(workspaceRoot, "", "", nodeDefinition, List.of(), result);
    }

    public NodeResult validate(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            NodeResult result
    ) throws Exception {
        return validate(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, List.of(), result);
    }

    public NodeResult validate(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            List<String> inputRefs,
            NodeResult result
    ) throws Exception {
        return prepare(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, inputRefs, result)
                .complete(workspaceRoot, false);
    }

    /** Validate in memory, persist one execution decision, then publish only eligible candidates. */
    public NodeResult validateAndFinalize(
            Path workspaceRoot, String workstreamId, String nodeInstanceId,
            NodeDefinition nodeDefinition, List<String> inputRefs, NodeResult result
    ) throws Exception {
        return prepare(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, inputRefs, result)
                .complete(workspaceRoot, true);
    }

    private Validation prepare(
            Path workspaceRoot, String workstreamId, String nodeInstanceId,
            NodeDefinition nodeDefinition, List<String> inputRefs, NodeResult result
    ) throws Exception {
        if (AgentExecutionResultFacts.inputPreparationFailed(result)) return new Validation(result, null);
        if (EvidenceCollection.FAILURE.equals(result.outcome())) return new Validation(result, null);
        if (!"acpx.agent_run".equals(nodeDefinition.handlerType()) || Boolean.TRUE.equals(result.result().get("prepared"))) {
            return new Validation(result, null);
        }
        try {
            EvidenceCollection.verify(workspaceRoot, workstreamId, nodeInstanceId);
        } catch (java.io.IOException | IllegalArgumentException invalid) {
            return new Validation(new NodeResult(EvidenceCollection.FAILURE, dev.dual.core.workflow.NodeStatus.FAILED, List.of(),
                    Map.of("failure_code", EvidenceCollection.FAILURE, "error", String.valueOf(invalid.getMessage())),
                    invalid.getMessage()), null);
        }
        if (!ContractRegistry.hasContract(nodeDefinition.id())) {
            return new Validation(result, null);
        }
        var acquisitionContract = AgentExecutionResultFacts.agentResultContract(result);
        if (acquisitionContract.present() && !acquisitionContract.valid()) {
            // Re-parsing a well-formed final candidate must not erase the acquisition's stricter diff rejection.
            return contractViolation(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, result,
                    ContractRegistry.forNode(nodeDefinition.id()), "", null,
                    ContractViolation.of("AGENT_RESULT_CONTRACT_VIOLATION", acquisitionContract.validationError(), Map.of()));
        }
        return validateAgentOutput(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, inputRefs, result);
    }

    private Validation validateAgentOutput(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            List<String> inputRefs,
            NodeResult result
    ) throws Exception {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var contract = ContractRegistry.forNode(nodeDefinition.id());
        ContractViolation lastInvalid = null;
        String lastSourceRef = "";
        var repositoryFactBindingRef = text(result.result().get("repository_fact_binding_ref"));
        for (int i = result.outputRefs().size() - 1; i >= 0; i--) {
            var ref = result.outputRefs().get(i);
            if (ref.startsWith("artifact://")
                    || !ref.endsWith(".json")
                    || ref.equals(repositoryFactBindingRef)) {
                continue;
            }
            var path = root.resolve(ref).normalize();
            if (!path.startsWith(root) || !Files.isRegularFile(path)) {
                continue;
            }
            var candidate = Files.readString(path, StandardCharsets.UTF_8);
            var parsed = resultParser.parse(candidate);
            if (!parsed.valid()) {
                lastInvalid = ContractViolation.of(parsed.errorCode(), parsed.message(), Map.of());
                lastSourceRef = ref;
                break;
            }
            var expectedRunId = text(result.result().get("run_id"));
            var validation = resultValidator.validate(parsed.envelope(), workstreamId, expectedRunId, contract);
            if (!validation.valid()) {
                lastInvalid = ContractViolation.of(
                        "AGENT_RESULT_CONTRACT_VIOLATION",
                        "AgentResultEnvelope failed contract validation: " + validation.errors(),
                        Map.of("errors", validation.errors())
                );
                lastSourceRef = ref;
                break;
            }
            try {
                EvidenceCollection.verifyResult(root, workstreamId, nodeInstanceId, parsed.envelope().result());
            } catch (java.io.IOException | IllegalArgumentException invalid) {
                return new Validation(new NodeResult(EvidenceCollection.FAILURE, dev.dual.core.workflow.NodeStatus.FAILED, List.of(),
                        Map.of("failure_code", EvidenceCollection.FAILURE, "error", String.valueOf(invalid.getMessage())), invalid.getMessage()), null);
            }
            if (parsed.envelope().result() instanceof AgentResultEnvelope.DesignResult design) {
                var errors = DesignScopeValidator.validate(root, workstreamId, design.design());
                if (!errors.isEmpty()) {
                    return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, ref,
                            parsed.envelope(), ContractViolation.of("DESIGN_SCOPE_INVALID",
                                    "Design is not within the approved contract", Map.of("errors", errors)));
                }
            }
            if (parsed.envelope().result() instanceof AgentResultEnvelope.PlanResult plan) {
                var errors = PlanScopeValidator.validate(root, workstreamId, plan.plan());
                if (!errors.isEmpty()) {
                    return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, ref,
                            parsed.envelope(), ContractViolation.of("PLAN_SCOPE_INVALID",
                                    "Plan is not within the approved contract", Map.of("errors", errors)));
                }
            }
            var repositoryFactBinding = resolveRepositoryFactBinding(
                    root, workstreamId, nodeInstanceId, expectedRunId, result);
            var proposalResolution = resolveProposalCandidate(
                    root, workstreamId, nodeInstanceId, nodeDefinition, parsed.envelope(), ref,
                    repositoryFactBinding);
            if (proposalResolution.failure() != null) {
                return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, ref,
                        parsed.envelope(), proposalResolution.failure());
            }
            return withResultSidecars(
                    root, workstreamId, nodeInstanceId, nodeDefinition, inputRefs, result, contract,
                    parsed.envelope(), ref, path, proposalResolution
            );
        }
        return contractViolation(workspaceRoot, workstreamId, nodeInstanceId, nodeDefinition, result, contract,
                lastSourceRef, null, lastInvalid);
    }

    private ProposalResolution resolveProposalCandidate(
            Path root,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            AgentResultEnvelope envelope,
            String sourceOutputRef,
            RepositoryFactBinding.Verification repositoryFactBinding
    ) {
        var isProposal = envelope.result() instanceof AgentResultEnvelope.TaskContractProposalResult;
        var isPatch = envelope.result() instanceof AgentResultEnvelope.TaskContractRevisionPatchResult;
        if (!isProposal && !isPatch) {
            return ProposalResolution.none();
        }
        if (!repositoryFactBinding.valid()) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_REPOSITORY_FACT_BINDING_INVALID",
                    "task contract proposal has no valid repository fact occurrence binding",
                    Map.of("errors", repositoryFactBinding.errors())));
        }
        if (!"intake.claude_brainstorm".equals(nodeDefinition.id())) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_PROPOSAL_INVALID",
                    "task contract proposal output is only allowed for intake",
                    Map.of()));
        }
        var resolved = revisionContextResolver.resolveForNode(root, workstreamId, nodeInstanceId);
        if (!resolved.valid()) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_REVISION_CONTEXT_INVALID",
                    "task contract proposal revision context could not be resolved",
                    Map.of("errors", resolved.errors())));
        }
        var context = resolved.context();
        TaskContractProposal proposal;
        AgentOutputContractDocument.ProposalDerivation derivation = null;
        if (isProposal) {
            if (context.revision()) {
                return ProposalResolution.failure(ContractViolation.of(
                        "TASK_CONTRACT_REVISION_SHAPE_INVALID",
                        "revision iteration requires task_contract_revision_patch",
                        Map.of()));
            }
            var proposalResult = (AgentResultEnvelope.TaskContractProposalResult) envelope.result();
            var resolvedScope = new TaskContractScopeResolver().resolve(
                    proposalResult.scope().included(), root);
            if (!resolvedScope.valid()) {
                return ProposalResolution.failure(ContractViolation.of(
                        "TASK_CONTRACT_SCOPE_RESOLUTION_FAILED",
                        "task contract scope paths could not be resolved",
                        Map.of("errors", resolvedScope.errors())));
            }
            proposal = resultProjector.taskContractProposal(proposalResult, resolvedScope.entries());
        } else {
            if (!context.revision()) {
                return ProposalResolution.failure(ContractViolation.of(
                        "TASK_CONTRACT_REVISION_SHAPE_INVALID",
                        "initial iteration requires task_contract_proposal",
                        Map.of()));
            }
            var merged = revisionMerger.merge(
                    context, (AgentResultEnvelope.TaskContractRevisionPatchResult) envelope.result(), root);
            if (!merged.valid()) {
                return ProposalResolution.failure(ContractViolation.of(
                        "TASK_CONTRACT_REVISION_PATCH_INVALID",
                        "task contract revision patch could not be merged",
                        Map.of("errors", merged.errors())));
            }
            proposal = merged.proposal();
            derivation = new AgentOutputContractDocument.ProposalDerivation(
                    "revision_patch_merge",
                    context.previousReference().proposalId(),
                    context.previousReference().sha256(),
                    context.previousReference(),
                    sourceOutputRef);
        }

        var proposalValidator = new TaskContractProposalValidator();
        var errors = proposalValidator.validate(proposal, root,
                context.approvedScopeBaseline(), context.originalBaseCommit(), context.scopeReviewCandidates());
        if (!errors.isEmpty()) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_PROPOSAL_VALIDATION_FAILED",
                    "task_contract_proposal failed mechanical validation: " + errors,
                    Map.of("errors", errors)));
        }
        var coverageErrors = context.revision()
                ? proposalValidator.validateRevisionCoverage(proposal, context.obligations())
                : proposalValidator.validateInitialIteration(proposal);
        if (!coverageErrors.isEmpty()) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_REVISION_COVERAGE_INVALID",
                    "task_contract_proposal failed revision obligation coverage",
                    Map.of("errors", coverageErrors)));
        }
        var evidenceErrors = proposalValidator.validateEvidenceTraceability(
                proposal, root, repositoryFactBinding.verified());
        if (!evidenceErrors.isEmpty()) {
            return ProposalResolution.failure(ContractViolation.of(
                    "TASK_CONTRACT_EVIDENCE_TRACEABILITY_INVALID",
                    "task_contract_proposal is not grounded in the tracked inventory",
                    Map.of("errors", evidenceErrors)));
        }
        if (context.revision()) {
            var deltaErrors = proposalValidator.validateRevisionDelta(context.previousProposal(), proposal);
            if (!deltaErrors.isEmpty()) {
                return ProposalResolution.failure(ContractViolation.of(
                        "TASK_CONTRACT_REVISION_DELTA_INVALID",
                        "task_contract_proposal contains an invalid revision delta",
                        Map.of(
                                "error_codes", deltaErrors.stream()
                                        .map(TaskContractProposalValidator.RevisionDeltaError::code).distinct().toList(),
                                "errors", deltaErrors.stream()
                                        .map(TaskContractProposalValidator.RevisionDeltaError::message).toList())));
            }
        }
        return new ProposalResolution(proposal, derivation, repositoryFactBinding.verified(), null);
    }

    private Validation withResultSidecars(
            Path root,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            List<String> inputRefs,
            NodeResult result,
            NodeOutputContract contract,
            AgentResultEnvelope envelope,
            String outputRef,
            Path outputPath,
            ProposalResolution proposalResolution
    ) throws Exception {
        var document = resultProjector.outputContract(
                envelope, contract, nodeDefinition.handlerType(), nodeInstanceId, outputRef,
                proposalResolution.proposal(), proposalResolution.derivation());
        var requiredReviewSubject = text(nodeDefinition.config().get("review_subject_artifact"));
        if (!requiredReviewSubject.isBlank()) {
            if (!"task_contract_proposal".equals(requiredReviewSubject)) {
                return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, outputRef,
                        envelope,
                        ContractViolation.of("REVIEW_SUBJECT_UNSUPPORTED",
                                "unsupported review_subject_artifact: " + requiredReviewSubject,
                                Map.of("review_subject_artifact", requiredReviewSubject)));
            }
            var reviewSubject = TaskContractProposalReference.resolveFromRefs(
                    root, workstreamId, inputRefs, OBJECT_MAPPER);
            if (reviewSubject.isEmpty()) {
                return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, outputRef,
                        envelope,
                        ContractViolation.of("REVIEW_SUBJECT_MISSING",
                                "exactly one validated task_contract_proposal reference is required",
                                Map.of("review_subject_artifact", requiredReviewSubject)));
            }
            document.put("review_subject", reviewSubject.get().reference().toMap());
        }
        if (proposalResolution.proposal() != null) {
            document.put("repository_fact_binding",
                    RepositoryFactBinding.reference(proposalResolution.repositoryFactBinding()).toMap());
        }
        AgentContractSemantics.addSidecarFields(document);
        var validatedDocument = AgentOutputContractDocument.from(document);
        var semanticFailure = AgentContractSemantics.validateOutputContract(validatedDocument);
        if (semanticFailure.isPresent()) {
            return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, outputRef,
                    envelope,
                    semanticFailure.get());
        }

        var sidecarPath = AgentOutputContractSidecar.pathFor(outputPath);
        if (AuthoredStageLineageResolver.participates(nodeDefinition.id())) {
            try {
                var authoredRef = AuthoredExecutionContext.validatePublication(root, workstreamId, nodeInstanceId,
                        envelope.runId(), envelope.result());
                document.put("authored_context", Map.of("ref", authoredRef.ref(), "sha256", authoredRef.sha256()));
            } catch (java.io.IOException | IllegalArgumentException failure) {
                return contractViolation(root, workstreamId, nodeInstanceId, nodeDefinition, result, contract, outputRef,
                        envelope, ContractViolation.of("AUTHORED_CONTEXT_INVALID", failure.getMessage(), Map.of()));
            }
        }
        try {
            EvidenceCollection.verifyResult(root, workstreamId, nodeInstanceId, envelope.result());
        } catch (java.io.IOException | IllegalArgumentException invalid) {
            return new Validation(new NodeResult(EvidenceCollection.FAILURE, dev.dual.core.workflow.NodeStatus.FAILED, List.of(),
                    Map.of("failure_code", EvidenceCollection.FAILURE, "error", String.valueOf(invalid.getMessage())), invalid.getMessage()), null);
        }
        var validated = AgentExecutionResultFacts.attach(result,
                AgentResultContractResult.valid(envelope.result().decision()),
                List.of(ArtifactContractResult.requiredValid(envelope.result().artifactType())),
                document.get("reread_reasons"));
        return new Validation(validated, execution -> {
            // A run write is an external I/O window: recheck evidence before business publication.
            EvidenceCollection.verifyResult(root, workstreamId, nodeInstanceId, envelope.result());
            Files.writeString(sidecarPath,
                    OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(document) + "\n",
                    StandardCharsets.UTF_8);
            var sidecarRef = root.relativize(sidecarPath).toString();
            var outputRefs = new ArrayList<>(result.outputRefs());
            if (!outputRefs.contains(sidecarRef)) {
                outputRefs.add(sidecarRef);
            }

            Optional<TaskContractProposalReference.Published> proposalReference = Optional.empty();
            if (proposalResolution.proposal() != null) {
                proposalReference = Optional.of(
                        envelope.result() instanceof AgentResultEnvelope.TaskContractRevisionPatchResult
                                ? TaskContractProposalReference.publishRevisionDerived(
                                root, workstreamId, sidecarPath, validatedDocument, OBJECT_MAPPER)
                                : TaskContractProposalReference.publishInitial(
                                root, workstreamId, sidecarPath, validatedDocument, OBJECT_MAPPER));
                if (!outputRefs.contains(proposalReference.get().referenceRef())) {
                    outputRefs.add(proposalReference.get().referenceRef());
                }
            }

            var planArtifactRef = writePlanArtifactSidecars(
                    root, envelope, outputPath);
            planArtifactRef.ifPresent(ref -> {
                if (!outputRefs.contains(ref)) {
                    outputRefs.add(ref);
                }
            });

            var augmented = new LinkedHashMap<String, Object>();
            augmented.putAll(execution.result());
            augmented.put("decision", envelope.result().decision());
            augmented.put("summary", envelope.result().summary());
            augmented.put("contract_sidecar_ref", sidecarRef);
            augmented.put("contract_sidecar_sha256", AgentOutputContractSidecar.sha256(sidecarPath));
            proposalReference.ifPresent(reference -> {
                augmented.put("task_contract_proposal_ref", reference.referenceRef());
                augmented.put("task_contract_proposal_id", reference.reference().proposalId());
            });
            planArtifactRef.ifPresent(ref -> augmented.put("plan_artifact_ref", ref));
            return AgentExecutionResultFacts.attach(new NodeResult(
                            execution.outcome(), execution.status(), outputRefs, augmented, execution.errorMessage()),
                    AgentResultContractResult.valid(envelope.result().decision()),
                    List.of(ArtifactContractResult.requiredValid(envelope.result().artifactType())),
                    document.get("reread_reasons"));
        });
    }

    @FunctionalInterface
    private interface Publication {
        NodeResult publish(NodeResult execution) throws Exception;
    }

    /** Transient validated candidate, never a persisted authority or a model-supplied control field. */
    private record Validation(NodeResult result, Publication publication) {
        NodeResult complete(Path root, boolean persistExecution) throws Exception {
            var finalizer = new AgentRunMetadataFinalizer();
            var execution = persistExecution
                    ? finalizer.finalizeNodeResult(root, result)
                    : publication == null ? result : finalizer.assessPublication(root, result);
            if (publication == null || execution.status() == NodeStatus.FAILED) {
                return execution;
            }
            return publication.publish(execution);
        }
    }

    private record ProposalResolution(
            TaskContractProposal proposal,
            AgentOutputContractDocument.ProposalDerivation derivation,
            RepositoryFactBinding.Verified repositoryFactBinding,
            ContractViolation failure
    ) {
        static ProposalResolution none() {
            return new ProposalResolution(null, null, null, null);
        }

        static ProposalResolution failure(ContractViolation failure) {
            return new ProposalResolution(null, null, null, failure);
        }
    }

    private RepositoryFactBinding.Verification resolveRepositoryFactBinding(
            Path root,
            String workstreamId,
            String nodeInstanceId,
            String runId,
            NodeResult result
    ) {
        var bindingRef = text(result.result().get("repository_fact_binding_ref"));
        var bindingSha256 = text(result.result().get("repository_fact_binding_sha256"));
        if (bindingRef.isBlank() || bindingSha256.isBlank() || !result.outputRefs().contains(bindingRef)) {
            return new RepositoryFactBinding.Verification(
                    null,
                    List.of("adapter-owned repository fact binding ref/sha is missing or not routed"));
        }
        return RepositoryFactBinding.verify(
                root,
                workstreamId,
                bindingRef,
                bindingSha256,
                nodeInstanceId,
                runId,
                OBJECT_MAPPER);
    }

    private Optional<String> writePlanArtifactSidecars(
            Path root,
            AgentResultEnvelope envelope,
            Path outputPath
    ) throws Exception {
        if (!(envelope.result() instanceof AgentResultEnvelope.PlanResult planResult)) {
            return Optional.empty();
        }
        var document = resultProjector.planArtifact(planResult);
        var sidecarPath = PlanArtifactSidecar.pathFor(outputPath);
        Files.writeString(sidecarPath,
                OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(document) + "\n",
                StandardCharsets.UTF_8);
        return Optional.of(root.relativize(sidecarPath).toString());
    }

    private static List<String> stringList(Object value) {
        if (!(value instanceof List<?> list)) {
            return List.of();
        }
        return list.stream()
                .filter(item -> item != null && !String.valueOf(item).isBlank())
                .map(item -> String.valueOf(item).trim())
                .toList();
    }

    private static String normalizeRepoPath(String value) {
        var text = value == null ? "" : value.trim();
        while (text.startsWith("./")) {
            text = text.substring(2);
        }
        return text;
    }

    private static Validation contractViolation(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            NodeResult result,
            NodeOutputContract contract,
            String sourceOutputRef,
            AgentResultEnvelope validatedEnvelope,
            ContractViolation lastInvalid
    ) throws Exception {
        var reason = lastInvalid == null
                ? "AGENT_RESULT_MISSING"
                : lastInvalid.errorCode();
        var message = lastInvalid == null
                ? "No readable agent output artifact found for contract validation."
                : lastInvalid.message();
        var details = lastInvalid == null ? Map.<String, Object>of() : lastInvalid.details();
        var diagnostic = ContractFailureDiagnosticWriter.write(
                workspaceRoot,
                workstreamId,
                nodeInstanceId,
                nodeDefinition,
                contract,
                sourceOutputRef,
                reason,
                message,
                details
        );
        var failed = new LinkedHashMap<String, Object>();
        failed.putAll(result.result());
        failed.put("reason", "AGENT_OUTPUT_CONTRACT_VIOLATION");
        failed.put("contract_node_id", nodeDefinition.id());
        failed.put("contract_required_keys", List.copyOf(contract.requiredKeys()));
        failed.put("contract_allowed_decisions", List.copyOf(contract.allowedDecisions()));
        failed.put("parse_error", Map.of(
                "code", reason,
                "message", message,
                "details", details
        ));
        if (diagnostic.present()) {
            failed.put("contract_failure_diagnostic_ref", diagnostic.jsonRef());
            failed.put("contract_failure_diagnostic_markdown_ref", diagnostic.markdownRef());
        }
        failed.put("message", message);
        var outputRefs = new ArrayList<>(result.outputRefs());
        if (diagnostic.present() && !outputRefs.contains(diagnostic.jsonRef())) {
            outputRefs.add(diagnostic.jsonRef());
        }
        if (diagnostic.present() && !outputRefs.contains(diagnostic.markdownRef())) {
            outputRefs.add(diagnostic.markdownRef());
        }
        return new Validation(AgentExecutionResultFacts.attach(new NodeResult(
                "AGENT_OUTPUT_CONTRACT_VIOLATION",
                NodeStatus.FAILED,
                outputRefs,
                failed,
                message
        ), terminalResultFor(reason, message, validatedEnvelope),
                List.of(artifactResultFor(nodeDefinition, reason, message, validatedEnvelope)), null), null);
    }

    private static AgentResultContractResult terminalResultFor(
            String reason,
            String message,
            AgentResultEnvelope validatedEnvelope
    ) {
        if (validatedEnvelope != null) {
            return AgentResultContractResult.valid(validatedEnvelope.result().decision());
        }
        if (reason == null || reason.isBlank() || "AGENT_RESULT_MISSING".equals(reason)) {
            return AgentResultContractResult.missing();
        }
        return AgentResultContractResult.invalid(message);
    }

    private static ArtifactContractResult artifactResultFor(
            NodeDefinition nodeDefinition,
            String reason,
            String message,
            AgentResultEnvelope validatedEnvelope
    ) {
        if (validatedEnvelope != null) {
            return new ArtifactContractResult(
                    requiredArtifactTypeOrDefault(nodeDefinition),
                    true,
                    true,
                    false,
                    "",
                    reason,
                    message
            );
        }
        if (reason != null && (reason.startsWith("AGENT_RESULT_") && !"AGENT_RESULT_MISSING".equals(reason))) {
            return new ArtifactContractResult(
                    requiredArtifactTypeOrDefault(nodeDefinition),
                    true,
                    false,
                    false,
                    "",
                    reason,
                    message
            );
        }
        return ArtifactContractResult.optionalMissing(requiredArtifactTypeOrDefault(nodeDefinition));
    }

    private static String requiredArtifactType(NodeDefinition nodeDefinition) {
        var configured = text(nodeDefinition.config().get("expected_artifact"));
        if (!configured.isBlank()) {
            return configured;
        }
        var contract = ContractRegistry.forNode(nodeDefinition.id());
        return contract.outputArtifactTypes().size() == 1
                ? contract.outputArtifactTypes().iterator().next()
                : "agent_output_contract";
    }

    private static String requiredArtifactTypeOrDefault(NodeDefinition nodeDefinition) {
        var required = requiredArtifactType(nodeDefinition);
        return required == null || required.isBlank() ? "agent_output_contract" : required;
    }

    private static Optional<Path> resolveWorkspaceRef(Path root, String ref) {
        if (ref == null || ref.isBlank()) {
            return Optional.empty();
        }
        var path = root.resolve(ref).normalize();
        if (!path.startsWith(root)) {
            return Optional.empty();
        }
        return Optional.of(path);
    }

    private static Object fieldOrLegacy(ObjectNode node, String field, String legacyField) {
        if (node.has(field)) {
            return OBJECT_MAPPER.convertValue(node.get(field), Object.class);
        }
        return OBJECT_MAPPER.convertValue(node.path(legacyField), Object.class);
    }

    private static String firstNonBlank(String first, String second) {
        return firstNonBlank(new String[]{first, second});
    }

    private static String firstNonBlank(String... values) {
        if (values == null) {
            return "";
        }
        for (var value : values) {
            if (value != null && !value.isBlank()) {
                return value;
            }
        }
        return "";
    }

    private static Optional<Map<String, Object>> readMap(Path path) {
        try {
            return Optional.of(OBJECT_MAPPER.readValue(path.toFile(), MAP_TYPE));
        } catch (Exception ignored) {
            return Optional.empty();
        }
    }

    private static List<String> capabilityKinds(ObjectNode report) {
        var values = new LinkedHashSet<String>();
        for (var item : mapList(OBJECT_MAPPER.convertValue(report.path("actualCapabilityUsages"), Object.class))) {
            var kind = text(item.get("kind"));
            if (!kind.isBlank()) {
                values.add(kind);
            }
        }
        return List.copyOf(values);
    }

    private static List<Map<String, Object>> mapList(Object value) {
        if (!(value instanceof Iterable<?> iterable)) {
            return List.of();
        }
        var values = new ArrayList<Map<String, Object>>();
        for (var item : iterable) {
            if (!(item instanceof Map<?, ?> map)) {
                continue;
            }
            var copy = new LinkedHashMap<String, Object>();
            for (var entry : map.entrySet()) {
                if (entry.getKey() instanceof String key) {
                    copy.put(key, entry.getValue());
                }
            }
            values.add(copy);
        }
        return List.copyOf(values);
    }

    private static Map<String, String> stringMap(Object value) {
        if (!(value instanceof Map<?, ?> map)) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, String>();
        for (var entry : map.entrySet()) {
            if (entry.getKey() instanceof String key && entry.getValue() != null) {
                var text = String.valueOf(entry.getValue()).trim();
                if (!text.isBlank()) {
                    copy.put(key, text);
                }
            }
        }
        return Map.copyOf(copy);
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.workflow.NodeResult;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;

public final class PromptGenerateNextStageHandler implements TaskHandler {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();

    @Override
    public String type() {
        return "prompt.generate_next_stage";
    }

    @Override
    public NodeResult execute(TaskContext context) throws IOException {
        var workstreamDir = context.workspaceRoot()
                .resolve(".agent")
                .resolve("workstreams")
                .resolve(context.workstreamId());
        var outputDir = workstreamDir.resolve("artifacts").resolve("next-stage");
        Files.createDirectories(outputDir);

        var sourceRefs = readableInputRefs(context);
        var structured = structuredHandoff(context, sourceRefs);
        if (structured.isEmpty()) {
            return new NodeResult(
                    "STAGE_HANDOFF_CONTRACT_MISSING",
                    dev.dual.core.workflow.NodeStatus.FAILED,
                    sourceRefs,
                    java.util.Map.of("reason", "validated stage_handoff sidecar is required"),
                    "validated stage_handoff sidecar is required; Markdown fallback is not a workflow fact"
            );
        }
        var handoffSource = new HandoffSource(structured.get(), renderStructuredHandoffContext(structured.get()));
        var handoff = withLatestVerificationState(sourceRefs, context, handoffSource.document());
        var handoffContextText = renderStructuredHandoffContext(handoff);
        var suggestedPrompt = handoff.suggestedNextPrompt();
        var promptPath = outputDir.resolve("next-stage-prompt.md");
        Files.writeString(promptPath, renderPrompt(context, sourceRefs, suggestedPrompt, handoffContextText), StandardCharsets.UTF_8);

        var handoffJsonPath = outputDir.resolve("handoff.json");
        Files.writeString(handoffJsonPath, renderHandoffJson(handoff), StandardCharsets.UTF_8);

        var promptRef = toWorkspaceRef(context.workspaceRoot(), promptPath);
        var handoffJsonRef = toWorkspaceRef(context.workspaceRoot(), handoffJsonPath);
        var result = new LinkedHashMap<String, Object>();
        result.put("generated", true);
        result.put("mode", "structured-handoff");
        result.put("prompt_path", promptRef);
        result.put("handoff_json_path", handoffJsonRef);
        result.put("source_refs", sourceRefs);
        result.put("used_suggested_prompt_section", !suggestedPrompt.isBlank());
        result.put("generated_at", Instant.now().toString());
        return NodeResult.completed("completed", List.of(promptRef, handoffJsonRef), result);
    }

    private static String renderPrompt(TaskContext context, List<String> sourceRefs, String suggestedPrompt, String handoffText) {
        var builder = new StringBuilder();
        builder.append("# Next Stage Prompt\n\n");
        builder.append("- Workstream: ").append(context.workstreamId()).append("\n");
        builder.append("- Builder Node: ").append(context.definition().id()).append("\n");
        builder.append("- Generated At: ").append(Instant.now()).append("\n");
        builder.append("- Source Handoff Refs: ").append(sourceRefs.isEmpty() ? "(none)" : String.join(", ", sourceRefs)).append("\n\n");

        builder.append("## Prompt\n\n");
        if (!suggestedPrompt.isBlank()) {
            builder.append(suggestedPrompt.stripTrailing()).append("\n\n");
        } else {
            builder.append("Continue the next stage using the handoff below. Preserve the existing scope, review open risks first, and do not invent unrelated requirements.\n\n");
        }

        builder.append("## Handoff Context\n\n");
        if (handoffText.isBlank()) {
            builder.append("(no handoff artifact was available)\n");
        } else {
            builder.append(handoffText.stripTrailing()).append("\n");
        }
        return builder.toString();
    }

    private static String renderStructuredHandoffContext(StageHandoffDocument handoff) {
        var builder = new StringBuilder();
        builder.append("### Source\n\n");
        builder.append(handoff.sourceHandoffPath().isBlank() ? "(unknown)" : handoff.sourceHandoffPath()).append("\n\n");
        appendList(builder, "Completed Work", handoff.completedWork());
        appendList(builder, "Important Decisions", handoff.importantDecisions());
        appendList(builder, "Changed Files", handoff.changedFiles());
        if (!handoff.verificationState().isBlank()) {
            builder.append("### Verification State\n\n").append(handoff.verificationState()).append("\n\n");
        }
        appendList(builder, "Open Risks", handoff.openRisks());
        if (!handoff.recommendedNextStage().isBlank()) {
            builder.append("### Recommended Next Stage\n\n").append(handoff.recommendedNextStage()).append("\n\n");
        }
        return builder.toString().stripTrailing();
    }

    private static void appendList(StringBuilder builder, String title, List<String> items) {
        if (items.isEmpty()) {
            return;
        }
        builder.append("### ").append(title).append("\n\n");
        for (var item : items) {
            builder.append("- ").append(item).append("\n");
        }
        builder.append("\n");
    }

    private static List<String> readableInputRefs(TaskContext context) {
        return context.instance().inputRefs().stream()
                .filter(ref -> !ref.startsWith("artifact://"))
                .filter(ref -> Files.isRegularFile(context.workspaceRoot().resolve(ref).normalize()))
                .toList();
    }

    private static String toWorkspaceRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize().relativize(path.toAbsolutePath().normalize()).toString();
    }

    private static String renderHandoffJson(StageHandoffDocument handoff) throws IOException {
        return OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(handoff.toMap());
    }

    private static StageHandoffDocument withLatestVerificationState(List<String> sourceRefs, TaskContext context, StageHandoffDocument handoff)
            throws IOException {
        var verificationState = latestVerificationState(sourceRefs, context);
        if (verificationState.isBlank()) {
            return handoff;
        }
        return new StageHandoffDocument(
                handoff.schemaVersion(),
                handoff.workstreamId(),
                handoff.stageId(),
                handoff.iterationId(),
                handoff.sourceHandoffPath(),
                handoff.completedWork(),
                handoff.importantDecisions(),
                handoff.changedFiles(),
                handoff.openRisks(),
                verificationState,
                handoff.recommendedNextStage(),
                handoff.suggestedNextPrompt(),
                handoff.generatedAt()
        );
    }

    private static String latestVerificationState(List<String> sourceRefs, TaskContext context) {
        var parts = new java.util.ArrayList<String>();
        latestInputContract(sourceRefs, context, "implement-claude-self-test.contract.json")
                .map(AgentOutputContractDocument::verificationSummary)
                .filter(summary -> !summary.isBlank())
                .ifPresent(summary -> parts.add("Self-test: " + summary));
        latestInputContract(sourceRefs, context, "acceptance-codex-review.contract.json")
                .filter(document -> !document.verificationSummary().isBlank())
                .map(document -> "Acceptance (" + document.decision() + "): " + document.verificationSummary())
                .filter(summary -> !summary.isBlank())
                .ifPresent(parts::add);
        return String.join("\n", parts);
    }

    private static java.util.Optional<AgentOutputContractDocument> latestInputContract(
            List<String> sourceRefs,
            TaskContext context,
            String fileName
    ) {
        for (int i = sourceRefs.size() - 1; i >= 0; i--) {
            var ref = sourceRefs.get(i);
            if (!Path.of(ref).getFileName().toString().equals(fileName)) {
                continue;
            }
            var path = context.workspaceRoot().resolve(ref).normalize();
            var document = AgentOutputContractDocument.read(path, OBJECT_MAPPER);
            if (document.isPresent() && AgentOutputLineageVerifier.violation(
                    context.workspaceRoot(), context.workstreamId(), path, document.get()).isEmpty()) {
                return document;
            }
        }
        return java.util.Optional.empty();
    }

    private static java.util.Optional<StageHandoffDocument> structuredHandoff(TaskContext context, List<String> sourceRefs) throws IOException {
        for (String sourceRef : sourceRefs) {
            var outputPath = context.workspaceRoot().resolve(sourceRef).normalize();
            var sidecarPath = AgentOutputContractSidecar.pathFor(outputPath);
            var sidecar = AgentOutputContractDocument.read(sidecarPath, OBJECT_MAPPER);
            if (sidecar.isEmpty()
                    || AgentOutputLineageVerifier.violation(
                            context.workspaceRoot(), context.workstreamId(), sidecarPath, sidecar.get()).isPresent()
                    || !sidecar.get().isStageHandoffArtifact()) {
                continue;
            }
            var changedFiles = sidecar.get().changedFiles();
            if (changedFiles.isEmpty()) {
                changedFiles = changedFilesFromGitEvidence(context);
            }
            return java.util.Optional.of(new StageHandoffDocument(
                    1,
                    context.workstreamId(),
                    context.instance().stageId(),
                    context.instance().iterationId(),
                    toWorkspaceRef(context.workspaceRoot(), sidecarPath),
                    sidecar.get().completedWork(),
                    sidecar.get().importantDecisions(),
                    changedFiles,
                    sidecar.get().openRisks(),
                    sidecar.get().verificationSummary(),
                    sidecar.get().recommendedNextStage(),
                    sidecar.get().suggestedNextPrompt(),
                    Instant.now().toString()
            ));
        }
        return java.util.Optional.empty();
    }

    private static List<String> changedFilesFromGitEvidence(TaskContext context) throws IOException {
        var path = context.workspaceRoot()
                .resolve(".agent")
                .resolve("workstreams")
                .resolve(context.workstreamId())
                .resolve("artifacts")
                .resolve("git-evidence")
                .resolve("changed-files.txt");
        if (!Files.isRegularFile(path)) {
            return List.of();
        }
        return Files.readAllLines(path, StandardCharsets.UTF_8).stream()
                .map(String::strip)
                .filter(line -> !line.isBlank())
                .toList();
    }

    private record HandoffSource(StageHandoffDocument document, String contextText) {
    }

}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeKind;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowDefinition;
import dev.dual.ledger.file.GateDocument;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkflowIterationDocument;
import dev.dual.ledger.file.WorkstreamPaths;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

import static dev.dual.runtime.handler.AuthoredExecutionContext.*;

/** Resolves the two registered authored stages from declared edges and routed occurrences. */
final class AuthoredStageLineageResolver {
    enum Stage {
        DESIGN("design.claude_design", "design.codex_arch_review", "design.decision", "design_result", "design"),
        PLAN("plan.claude_plan", "plan.codex_plan_review", "plan.decision", "plan_result", "plan");

        final String author, reviewer, decision, artifact, purpose;
        Stage(String author, String reviewer, String decision, String artifact, String purpose) {
            this.author = author; this.reviewer = reviewer; this.decision = decision;
            this.artifact = artifact; this.purpose = purpose;
        }
    }

    private static final TypeReference<Map<String, Object>> MAP = new TypeReference<>() { };
    private final Path root;
    private final String ws;
    private final String prefix;
    private final WorkstreamPaths paths;
    private final WorkflowFileLedger ledger = new WorkflowFileLedger();
    private final WorkflowDefinition definition;
    private final List<Event> events;
    private final long through;

    AuthoredStageLineageResolver(Path root, String ws, long through) throws IOException {
        this.root = root.toAbsolutePath().normalize(); this.ws = ws;
        this.prefix = ".agent/workstreams/" + ws + "/";
        this.paths = new WorkstreamPaths(root, new DualId(ws));
        this.definition = ledger.loadDefinition(paths);
        var history = new ArrayList<Event>();
        long previous = -1;
        for (var line : Files.readAllLines(paths.eventsJsonl())) {
            if (line.isBlank()) continue;
            var event = JSON.readValue(line, MAP);
            var id = text(event.get("event_id"));
            if (!id.matches("evt-[0-9]{6,}")) {
                require(!"node_routed".equals(text(event.get("event_type"))), "AUTHORED_EVENT_ID_INVALID");
                continue;
            }
            long sequence;
            try { sequence = Long.parseLong(id.substring(4)); }
            catch (NumberFormatException failure) { throw new IOException("AUTHORED_EVENT_ID_INVALID", failure); }
            require(sequence > previous, "AUTHORED_EVENT_ORDER_INVALID");
            previous = sequence;
            if (sequence <= through) history.add(new Event(sequence, id, text(event.get("event_type")), map(event.get("payload"))));
        }
        this.events = List.copyOf(history);
        this.through = history.isEmpty() ? 0 : history.getLast().sequence();
    }

    static boolean participates(String nodeId) {
        return nodeId.equals(Stage.DESIGN.author) || nodeId.equals(Stage.DESIGN.reviewer)
                || nodeId.equals(Stage.PLAN.author) || nodeId.equals(Stage.PLAN.reviewer)
                || Set.of("implement.claude_implement", "implement.claude_self_test_report").contains(nodeId);
    }

    static void validateDefinition(WorkflowDefinition definition) {
        if (definition.nodes().stream().noneMatch(node -> participates(node.id()))) return;
        for (var stage : Stage.values()) {
            var author = definition.node(stage.author);
            definitionRequire(author.kind() == NodeKind.TASK && author.handlerType().equals("acpx.agent_run"), "author role mismatch");
            var gates = definition.nodes().stream().filter(node -> stage.purpose.equals(text(node.config().get("gate_purpose")))).toList();
            definitionRequire(gates.size() == 1, "one " + stage.purpose + " gate is required");
            var gate = gates.getFirst();
            definitionRequire(gate.kind() == NodeKind.GATE && gate.handlerType().equals("human.review"), "gate role mismatch");
            var incoming = definition.edges().stream().filter(edge -> edge.to().equals(gate.id())).toList();
            definitionRequire(!incoming.isEmpty(), "gate must have a candidate source");
            var next = soleSuccessor(definition, author.id(), "completed");
            boolean direct = stage == Stage.PLAN && next.equals(gate.id());
            if (direct) {
                definitionRequire(incoming.stream().allMatch(edge -> edge.from().equals(stage.author) && edge.on().equals("completed")),
                        "direct plan gate cannot mix reviewed sources");
                definitionRequire(definition.nodes().stream().noneMatch(node -> node.id().equals(stage.reviewer) || node.id().equals(stage.decision)),
                        "direct plan topology cannot retain orphan reviewer roles");
            } else {
                var context = definition.node(next);
                definitionRequire(context.handlerType().equals("context.build_package") && context.kind() == NodeKind.TASK
                        && stage.reviewer.equals(text(context.config().get("target_node"))), "review context role mismatch");
                definitionRequire(soleSuccessor(definition, next, "completed").equals(stage.reviewer), "review context successor mismatch");
                var reviewer = definition.node(stage.reviewer);
                definitionRequire(reviewer.kind() == NodeKind.TASK && reviewer.handlerType().equals("acpx.agent_run"), "reviewer role mismatch");
                definitionRequire(soleSuccessor(definition, stage.reviewer, "completed").equals(stage.decision), "review decision successor mismatch");
                var decision = definition.node(stage.decision);
                definitionRequire(decision.kind() == NodeKind.DECISION && decision.handlerType().equals("review.decision"), "decision role mismatch");
                definitionRequire(incoming.stream().allMatch(edge -> edge.from().equals(stage.decision)), "reviewed gate source mismatch");
                definitionRequire(definition.edges().stream().filter(edge -> edge.to().equals(next))
                        .allMatch(edge -> edge.from().equals(stage.author) && edge.on().equals("completed")), "review context has an unrelated producer");
                definitionRequire(definition.edges().stream().filter(edge -> edge.to().equals(stage.reviewer))
                        .allMatch(edge -> edge.from().equals(next) && edge.on().equals("completed")), "reviewer bypasses its context");
                definitionRequire(definition.edges().stream().filter(edge -> edge.to().equals(stage.decision))
                        .allMatch(edge -> edge.from().equals(stage.reviewer) && edge.on().equals("completed")), "decision bypasses its reviewer");
                var revision = soleSuccessor(definition, stage.decision, "NEEDS_REVISION");
                definitionRequire(revision.equals(gate.id()) || (stage == Stage.PLAN && revision.equals(stage.author)), "unsupported revision topology");
            }
            definitionRequire(soleSuccessor(definition, gate.id(), "revise").equals(stage.author), "human revise must return to its author");
            var approved = soleSuccessor(definition, gate.id(), "approved");
            if (stage == Stage.DESIGN) definitionRequire(approved.equals(Stage.PLAN.author), "approved design must feed the planner");
            else {
                var target = definition.node(approved);
                definitionRequire(approved.equals("implement.claude_implement") || (target.handlerType().equals("context.build_package")
                        && "implement.claude_implement".equals(text(target.config().get("target_node")))
                        && soleSuccessor(definition, approved, "completed").equals("implement.claude_implement")),
                        "approved plan must feed implementation");
            }
        }
    }

    private static String soleSuccessor(WorkflowDefinition definition, String source, String outcome) {
        var edges = definition.edgesFrom(source).stream().filter(edge -> edge.on().equals(outcome)).toList();
        definitionRequire(edges.size() == 1, "exactly one " + outcome + " edge required for " + source);
        return edges.getFirst().to();
    }

    private static void definitionRequire(boolean valid, String message) {
        if (!valid) throw new IllegalArgumentException("AUTHORED_DEFINITION_INVALID: " + message);
    }

    Snapshot prepare(String nodeInstanceId, String runId) throws IOException {
        var node = node(nodeInstanceId);
        require(participates(node.nodeDefinitionId()), "AUTHORED_ROLE_UNSUPPORTED");
        var contractResolution = TaskContractProjectionVerifier.resolve(root, ws);
        require(contractResolution.failure() == null && contractResolution.qualified().isPresent(), "AUTHORED_CONTRACT_NOT_QUALIFIED");
        var qualified = contractResolution.qualified().orElseThrow();
        var contract = new ContractIdentity(qualified.compileNodeInstanceId(), qualified.approvalGateRef(), qualified.approvalEventId(),
                new Reference(qualified.contractRef(), qualified.sha256()), new Reference(qualified.resolutionRef(), qualified.resolutionSha256()));
        require(events.stream().anyMatch(event -> event.id().equals(contract.approvalEventId())), "AUTHORED_CONTRACT_OUTSIDE_HISTORY");
        Approval design = null, plan = null;
        Candidate parent = null, subject = null;
        Reference trigger = null;
        List<Obligation> obligations = List.of();
        var id = node.nodeDefinitionId();
        if (!id.equals(Stage.DESIGN.author) && !id.equals(Stage.DESIGN.reviewer)) design = approval(Stage.DESIGN);
        if (id.equals("implement.claude_implement") || id.equals("implement.claude_self_test_report")) plan = approval(Stage.PLAN);
        for (var stage : Stage.values()) {
            if (id.equals(stage.author)) {
                var baseline = baseline(stage, node, new HashSet<>());
                parent = baseline.parent(); trigger = baseline.trigger(); obligations = baseline.obligations();
            } else if (id.equals(stage.reviewer)) {
                subject = reviewSubject(stage, node);
                obligations = baseline(stage, node(subject.nodeInstanceId()), new HashSet<>()).obligations();
            }
        }
        var snapshot = new Snapshot(ws, nodeInstanceId, id, runId, through, contract, design, plan, parent, subject, trigger, obligations);
        var origins = events.stream().filter(event -> event.type().equals("node_routed")
                && nodeInstanceId.equals(text(event.payload().get("node_instance_id")))).toList();
        require(origins.size() <= 1, "AUTHORED_NODE_ORIGIN_NOT_UNIQUE");
        if (!origins.isEmpty() && origins.getFirst().sequence() < through) {
            // Node creation, not execution retry, fixes the semantic input epoch.
            var original = new AuthoredStageLineageResolver(root, ws, origins.getFirst().sequence()).prepare(nodeInstanceId, runId);
            require(snapshot.withHistoryThrough(original.historyThrough()).equals(original), "AUTHORED_NODE_AUTHORITY_CHANGED");
            return original;
        }
        return snapshot;
    }

    Approval approval(Stage stage) throws IOException {
        Event last = null;
        for (var event : events) {
            if (!event.type().equals("node_routed")) continue;
            var to = text(event.payload().get("to"));
            var target = definition.node(to);
            if (target.kind() == NodeKind.GATE && stage.purpose.equals(text(target.config().get("gate_purpose")))) last = event;
        }
        require(last != null, "AUTHORED_APPROVAL_MISSING: " + stage.purpose);
        var gate = gate(last);
        require(gate.node().status() == NodeStatus.COMPLETED && gate.document().status().equals("resolved"), "AUTHORED_APPROVAL_NOT_COMPLETED");
        require(text(gate.document().result().get("human_action")).equals("approved"), "AUTHORED_NOT_APPROVED");
        require(routedAfter(last, gate.node(), "approved"), "AUTHORED_APPROVAL_NOT_ROUTED");
        return new Approval(gate.reference(), last.id(), gateSubject(stage, gate));
    }

    private boolean routedAfter(Event origin, NodeInstanceDocument source, String outcome) throws IOException {
        for (var event : events) {
            if (event.sequence() <= origin.sequence() || !event.type().equals("node_routed")) continue;
            // A later occurrence of the same gate cannot supply this occurrence's completion.
            if (source.nodeDefinitionId().equals(text(event.payload().get("to")))) return false;
            if (!source.nodeDefinitionId().equals(text(event.payload().get("from")))
                    || !outcome.equals(text(event.payload().get("outcome")))) continue;
            var successor = node(text(event.payload().get("node_instance_id")));
            require(successor.nodeDefinitionId().equals(text(event.payload().get("to")))
                    && successor.iterationId().equals(source.iterationId())
                    && successor.inputRefs().equals(source.outputRefs()), "AUTHORED_APPROVAL_SUCCESSOR_MISMATCH");
            edge(source.nodeDefinitionId(), outcome, successor.nodeDefinitionId());
            return true;
        }
        return false;
    }

    private Gate gate(Event event) throws IOException {
        var payload = event.payload();
        var node = node(text(payload.get("node_instance_id")));
        require(node.kind() == NodeKind.GATE && node.nodeDefinitionId().equals(text(payload.get("to"))), "AUTHORED_GATE_NODE_MISMATCH");
        var ref = reference(root, prefix + "gates/" + text(payload.get("gate_id")) + ".json");
        var gate = JSON.readValue(verifiedPath(root, ref).toFile(), GateDocument.class);
        require(gate.gateId().equals(text(payload.get("gate_id")))
                && gate.nodeInstanceId().equals(node.nodeInstanceId()), "AUTHORED_GATE_INSTANCE_MISMATCH");
        require(strings(gate.result().get("subject_input_refs")).equals(node.inputRefs()), "AUTHORED_GATE_SUBJECT_MISMATCH");
        var source = text(payload.get("source_node_instance_id"));
        require(!source.isBlank() && source.equals(text(gate.result().get("source_node_instance_id")))
                && source.equals(text(node.result().get("source_node_instance_id"))), "AUTHORED_GATE_SOURCE_MISMATCH");
        require(text(gate.result().get("human_action")).equals(text(node.result().get("human_action")))
                && text(gate.result().get("note")).equals(text(node.result().get("note"))), "AUTHORED_GATE_ACTION_MISMATCH");
        var producer = node(source);
        completed(producer);
        require(producer.nodeDefinitionId().equals(text(payload.get("from"))), "AUTHORED_GATE_EVENT_SOURCE_MISMATCH");
        require(producer.iterationId().equals(node.iterationId()), "AUTHORED_GATE_ITERATION_MISMATCH");
        edge(producer.nodeDefinitionId(), text(payload.get("outcome")), node.nodeDefinitionId());
        return new Gate(node, gate, ref, producer);
    }

    private Candidate gateSubject(Stage stage, Gate gate) throws IOException {
        if (gate.source().nodeDefinitionId().equals(stage.author)) {
            require(stage == Stage.PLAN, "AUTHORED_DIRECT_DESIGN_GATE_UNSUPPORTED");
            return candidate(stage, gate.node().inputRefs(), gate.source());
        }
        require(gate.source().nodeDefinitionId().equals(stage.decision), "AUTHORED_GATE_SOURCE_ROLE_INVALID");
        var review = unique(gate.node().inputRefs(), stage.reviewer, "agent_output_contract");
        require(gate.source().inputRefs().contains(review.sidecar().ref()), "AUTHORED_DECISION_INPUT_MISMATCH");
        var reviewer = node(review.nodeInstanceId());
        require(reviewer.iterationId().equals(gate.source().iterationId()), "AUTHORED_REVIEW_ITERATION_MISMATCH");
        var doc = document(review);
        require(doc.decision().equals(text(gate.source().result().get("decision"))), "AUTHORED_DECISION_MISMATCH");
        edge(stage.reviewer, "completed", stage.decision);
        var subject = reviewSubject(stage, reviewer);
        var inputs = verifiedCandidateSnapshot(root, ws, review);
        require(subject.equals(inputs.subject()), "AUTHORED_REVIEW_INPUT_MISMATCH");
        return subject;
    }

    GateView gateView(String nodeInstanceId) throws IOException {
        var event = gateEvent(nodeInstanceId);
        var gate = gate(event);
        Stage stage = null;
        var purpose = text(definition.node(gate.node().nodeDefinitionId()).config().get("gate_purpose"));
        for (var value : Stage.values()) if (value.purpose.equals(purpose)) stage = value;
        require(stage != null, "AUTHORED_GATE_ROLE_UNSUPPORTED");
        var candidate = gateSubject(stage, gate);
        var inputs = verifiedCandidateSnapshot(root, ws, candidate);
        var latest = gate.source().nodeDefinitionId().equals(stage.author) ? candidate
                : unique(gate.node().inputRefs(), stage.reviewer, "agent_output_contract");
        var candidateDocument = JSON.readValue(verifiedPath(root, candidate.sidecar()).toFile(), MAP);
        var projection = new LinkedHashMap<String, Object>();
        projection.put("candidate", candidate);
        projection.put("contract", inputs.contract());
        projection.put("approvedDesign", inputs.approvedDesign());
        projection.put("activeObligations", inputs.obligations());
        projection.put("revisionResponses", candidateDocument.get("revision_responses"));
        projection.put("plannedFiles", candidateDocument.get("design"));
        projection.put("plan", candidateDocument.get("plan_artifact"));
        projection.put("newMustFix", latest.equals(candidate) ? List.of() : document(latest).mustFix());
        return new GateView(java.util.Collections.unmodifiableMap(projection), document(latest), latest.sidecar().ref());
    }

    record GateView(Map<String, Object> projection, AgentOutputContractDocument decision, String sidecarRef) { }

    String contextBody(TaskHandler.TaskContext context) throws IOException {
        var target = text(context.definition().config().get("target_node"));
        for (var stage : Stage.values()) {
            if (!target.equals(stage.reviewer)) continue;
            var subject = unique(context.instance().inputRefs(), stage.author, stage.artifact);
            var inputs = verifiedCandidateSnapshot(root, ws, subject);
            var body = new StringBuilder(inputs.render(root));
            body.append("\n## Current review candidate\n\n").append(subject.sidecar().ref()).append("\n\n")
                    .append(Files.readString(verifiedPath(root, subject.sidecar())));
            return body.toString();
        }
        if (target.equals("implement.claude_implement")) {
            var approved = approval(Stage.PLAN);
            var inputs = verifiedCandidateSnapshot(root, ws, approved.candidate());
            return inputs.render(root) + "\n## Approved implementation plan\n\n"
                    + Files.readString(verifiedPath(root, approved.candidate().sidecar()));
        }
        return "";
    }

    private Candidate reviewSubject(Stage stage, NodeInstanceDocument reviewer) throws IOException {
        var matches = new LinkedHashMap<String, NodeInstanceDocument>();
        for (var event : events) {
            if (!event.type().equals("node_routed")) continue;
            var publisher = node(text(event.payload().get("node_instance_id")));
            if (!publisher.handlerType().equals("context.build_package")) continue;
            var config = definition.node(publisher.nodeDefinitionId()).config();
            if (!stage.reviewer.equals(text(config.get("target_node")))) continue;
            if (publisher.outputRefs().stream().noneMatch(reviewer.inputRefs()::contains)) continue;
            completed(publisher);
            require(publisher.iterationId().equals(reviewer.iterationId()), "AUTHORED_CONTEXT_ITERATION_MISMATCH");
            edge(publisher.nodeDefinitionId(), "completed", stage.reviewer);
            edge(stage.author, "completed", publisher.nodeDefinitionId());
            matches.put(publisher.nodeInstanceId(), publisher);
        }
        require(matches.size() == 1, "AUTHORED_CONTEXT_PUBLISHER_NOT_UNIQUE");
        var publisher = matches.values().iterator().next();
        var candidate = unique(publisher.inputRefs(), stage.author, stage.artifact);
        require(node(candidate.nodeInstanceId()).iterationId().equals(publisher.iterationId()), "AUTHORED_CANDIDATE_ITERATION_MISMATCH");
        return candidate;
    }

    private Baseline baseline(Stage stage, NodeInstanceDocument author, Set<String> visiting) throws IOException {
        require(visiting.add(author.nodeInstanceId()), "AUTHORED_REVISION_CYCLE");
        var iterationRef = prefix + "iterations/" + author.iterationId() + ".json";
        var iteration = JSON.readValue(canonicalPath(root, iterationRef).toFile(), WorkflowIterationDocument.class);
        require(iteration.iterationId().equals(author.iterationId()), "AUTHORED_ITERATION_MISMATCH");
        if (!stage.author.equals(iteration.targetNodeDefinitionId()) || iteration.triggerNodeInstanceId().isBlank())
            return new Baseline(null, null, List.of());
        var source = node(iteration.triggerNodeInstanceId());
        Candidate parent;
        Reference trigger;
        var added = new ArrayList<Obligation>();
        if (source.kind() == NodeKind.GATE) {
            require(stage.purpose.equals(text(definition.node(source.nodeDefinitionId()).config().get("gate_purpose"))), "AUTHORED_REVISION_STAGE_MISMATCH");
            require(iteration.triggerAction().equals("revise"), "AUTHORED_REVISION_ACTION_INVALID");
            var event = gateEvent(source.nodeInstanceId());
            var gate = gate(event);
            require(source.status() == NodeStatus.COMPLETED && gate.document().status().equals("resolved")
                    && text(gate.document().result().get("human_action")).equals("revise"), "AUTHORED_REVISION_GATE_UNRESOLVED");
            var note = text(gate.document().result().get("note"));
            require(!note.isBlank(), "AUTHORED_REVISION_NOTE_MISSING");
            edge(source.nodeDefinitionId(), "revise", stage.author);
            parent = gateSubject(stage, gate); trigger = gate.reference();
            if (gate.source().nodeDefinitionId().equals(stage.decision)) {
                addReview(added, unique(gate.node().inputRefs(), stage.reviewer, "agent_output_contract"));
            }
            added.add(new Obligation("sha256:" + trigger.sha256() + "#human-note:0", trigger, note));
        } else {
            require(stage == Stage.PLAN && source.nodeDefinitionId().equals(stage.decision)
                    && iteration.triggerAction().equals("NEEDS_REVISION"), "AUTHORED_REVISION_TRIGGER_INVALID");
            completed(source);
            require(text(source.result().get("decision")).equals("NEEDS_REVISION"), "AUTHORED_REVISION_DECISION_MISMATCH");
            edge(source.nodeDefinitionId(), "NEEDS_REVISION", stage.author);
            var review = unique(source.inputRefs(), stage.reviewer, "agent_output_contract");
            require(document(review).decision().equals("NEEDS_REVISION"), "AUTHORED_REVIEW_DECISION_MISMATCH");
            parent = reviewSubject(stage, node(review.nodeInstanceId())); trigger = review.sidecar();
            require(parent.equals(verifiedCandidateSnapshot(root, ws, review).subject()), "AUTHORED_REVIEW_INPUT_MISMATCH");
            addReview(added, review);
        }
        require(node(parent.nodeInstanceId()).iterationId().equals(iteration.parentIterationId())
                && source.iterationId().equals(iteration.parentIterationId()), "AUTHORED_REVISION_PARENT_MISMATCH");
        var previous = baseline(stage, node(parent.nodeInstanceId()), visiting);
        var all = new LinkedHashMap<String, Obligation>();
        previous.obligations().forEach(value -> all.put(value.id(), value));
        added.forEach(value -> all.putIfAbsent(value.id(), value));
        return new Baseline(parent, trigger, List.copyOf(all.values()));
    }

    private void addReview(List<Obligation> result, Candidate review) throws IOException {
        var issues = document(review).mustFix();
        for (int i = 0; i < issues.size(); i++) result.add(new Obligation(
                "sha256:" + review.sidecar().sha256() + "#must_fix:" + i, review.sidecar(), issues.get(i)));
    }

    private Event gateEvent(String id) throws IOException {
        var matches = events.stream().filter(event -> event.type().equals("node_routed")
                && id.equals(text(event.payload().get("node_instance_id")))).toList();
        require(matches.size() == 1, "AUTHORED_GATE_EVENT_NOT_UNIQUE");
        return matches.getFirst();
    }

    private Candidate candidate(Stage stage, List<String> refs, NodeInstanceDocument producer) throws IOException {
        var candidate = unique(refs, stage.author, stage.artifact);
        require(candidate.nodeInstanceId().equals(producer.nodeInstanceId()), "AUTHORED_CANDIDATE_SOURCE_MISMATCH");
        return candidate;
    }

    private Candidate unique(List<String> refs, String expectedNode, String type) throws IOException {
        var matches = new LinkedHashMap<String, Candidate>();
        for (var ref : refs) {
            if (!ref.endsWith(".contract.json")) continue;
            var path = canonicalPath(root, ref);
            var document = AgentOutputContractDocument.read(path, JSON).orElseThrow(() -> new IOException("AUTHORED_SIDECAR_INVALID"));
            if (!document.nodeId().equals(expectedNode) || !document.sourceArtifactType().equals(type)) continue;
            require(document.hasRequiredTypedPayload(), "AUTHORED_TYPED_PAYLOAD_MISSING");
            var violation = AgentOutputLineageVerifier.violation(root, ws, path, document);
            require(violation.isEmpty(), "AUTHORED_CANDIDATE_LINEAGE_INVALID: " + violation.orElse(""));
            matches.put(ref, new Candidate(reference(root, ref), document.nodeInstanceId(), document.nodeId(), document.runId(), type));
        }
        require(matches.size() == 1, "AUTHORED_CANDIDATE_NOT_UNIQUE: " + expectedNode);
        return matches.values().iterator().next();
    }

    private AgentOutputContractDocument document(Candidate candidate) throws IOException {
        return AgentOutputContractDocument.read(verifiedPath(root, candidate.sidecar()), JSON)
                .orElseThrow(() -> new IOException("AUTHORED_SIDECAR_INVALID"));
    }

    private NodeInstanceDocument node(String id) throws IOException {
        require(!id.isBlank(), "AUTHORED_NODE_ID_MISSING");
        var node = JSON.readValue(canonicalPath(root, prefix + "nodes/" + id + ".json").toFile(), NodeInstanceDocument.class);
        require(node.nodeInstanceId().equals(id), "AUTHORED_NODE_ID_MISMATCH");
        return node;
    }

    private void edge(String from, String outcome, String to) throws IOException {
        require(definition.edgesFrom(from).stream().anyMatch(edge -> edge.on().equals(outcome) && edge.to().equals(to)), "AUTHORED_EDGE_NOT_DECLARED");
    }

    private static void completed(NodeInstanceDocument node) throws IOException {
        require(node.status() == NodeStatus.COMPLETED, "AUTHORED_SOURCE_NOT_COMPLETED");
    }

    static void require(boolean valid, String message) throws IOException { if (!valid) throw new IOException(message); }
    private static String text(Object value) { return value instanceof String text ? text : ""; }
    @SuppressWarnings("unchecked") private static Map<String, Object> map(Object value) { return value instanceof Map<?, ?> map ? (Map<String, Object>) map : Map.of(); }
    private static List<String> strings(Object value) { return value instanceof List<?> list ? list.stream().map(AuthoredStageLineageResolver::text).toList() : List.of(); }
    private record Event(long sequence, String id, String type, Map<String, Object> payload) { }
    private record Gate(NodeInstanceDocument node, GateDocument document, Reference reference, NodeInstanceDocument source) { }
    private record Baseline(Candidate parent, Reference trigger, List<Obligation> obligations) { }
}

package dev.dual.runtime.handler;

enum Degradation {
    FULL,
    SUMMARY,
    LATEST,
    DECISION_ONLY,
    DIFF_STAT,
    POINTER_ONLY,
    ADAPTIVE
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Typed boundary for artifacts/next-stage/handoff.json.
 *
 * The final assistant result is strict JSON; once projected to this sidecar the runtime
 * should consume this record instead of spreading hand-written map lookups.
 */
record StageHandoffDocument(
        int schemaVersion,
        String workstreamId,
        String stageId,
        String iterationId,
        String sourceHandoffPath,
        List<String> completedWork,
        List<String> importantDecisions,
        List<String> changedFiles,
        List<String> openRisks,
        String verificationState,
        String recommendedNextStage,
        String suggestedNextPrompt,
        String generatedAt
) {
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    static Optional<StageHandoffDocument> read(Path path, ObjectMapper objectMapper) {
        try {
            return Optional.of(from(objectMapper.readValue(path.toFile(), MAP_TYPE)));
        } catch (IOException | RuntimeException e) {
            return Optional.empty();
        }
    }

    static StageHandoffDocument from(Map<String, Object> document) {
        return new StageHandoffDocument(
                intValue(document.get("schemaVersion"), 1),
                text(document.get("workstreamId")),
                text(document.get("stageId")),
                text(document.get("iterationId")),
                text(document.get("sourceHandoffPath")),
                stringList(document.get("completedWork")),
                stringList(document.get("importantDecisions")),
                stringList(document.get("changedFiles")),
                stringList(document.get("openRisks")),
                text(document.get("verificationState")),
                text(document.get("recommendedNextStage")),
                text(document.get("suggestedNextPrompt")),
                text(document.get("generatedAt"))
        );
    }

    Map<String, Object> toMap() {
        var document = new LinkedHashMap<String, Object>();
        document.put("schemaVersion", schemaVersion);
        document.put("workstreamId", workstreamId);
        document.put("stageId", stageId);
        document.put("iterationId", iterationId);
        document.put("sourceHandoffPath", sourceHandoffPath);
        document.put("completedWork", completedWork);
        document.put("importantDecisions", importantDecisions);
        document.put("changedFiles", changedFiles);
        document.put("openRisks", openRisks);
        document.put("verificationState", verificationState);
        document.put("recommendedNextStage", recommendedNextStage);
        document.put("suggestedNextPrompt", suggestedNextPrompt);
        document.put("generatedAt", generatedAt);
        return document;
    }

    boolean hasCompletedWork() {
        return !completedWork.isEmpty();
    }

    boolean hasChangedFiles() {
        return !changedFiles.isEmpty();
    }

    boolean hasImportantDecisions() {
        return !importantDecisions.isEmpty();
    }

    boolean hasOpenRisks() {
        return !openRisks.isEmpty();
    }

    boolean hasRecommendedNextStage() {
        return !recommendedNextStage.isBlank();
    }

    private static List<String> stringList(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var result = new ArrayList<String>();
        for (var item : items) {
            var text = text(item);
            if (!text.isBlank()) {
                result.add(text);
            }
        }
        return List.copyOf(result);
    }

    private static int intValue(Object value, int fallback) {
        if (value instanceof Number number) {
            return number.intValue();
        }
        try {
            return Integer.parseInt(text(value));
        } catch (NumberFormatException e) {
            return fallback;
        }
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }
}

package dev.dual.runtime.handler;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;

/** Enforces patch-wide uniqueness for mutation targets across review obligations. */
final class TaskContractRevisionPatchTargetValidator {
    private TaskContractRevisionPatchTargetValidator() {
    }

    static List<String> validate(AgentResultEnvelope.TaskContractRevisionPatchResult patch) {
        if (patch == null || patch.obligationPatches() == null) {
            return List.of();
        }
        var errors = new ArrayList<String>();
        var clauseTargets = new HashSet<String>();
        var scopeTargets = new HashSet<String>();
        var evidenceTargets = new HashSet<String>();
        for (var obligationPatch : patch.obligationPatches()) {
            if (obligationPatch == null) {
                continue;
            }
            for (var change : safe(obligationPatch.clauseChanges())) {
                if (change != null && change.id() != null
                        && !clauseTargets.add(change.id().trim())) {
                    errors.add("DUPLICATE_CLAUSE_PATCH_TARGET: " + change.id().trim());
                }
            }
            for (var entry : safe(obligationPatch.scopeAdditions())) {
                if (entry != null && !scopeTargets.add(entry.path())) {
                    errors.add("DUPLICATE_SCOPE_PATCH_TARGET: " + entry.path());
                }
            }
            for (var ref : safe(obligationPatch.evidenceRefAdditions())) {
                if (ref != null && !evidenceTargets.add(ref)) {
                    errors.add("DUPLICATE_EVIDENCE_PATCH_TARGET: " + ref);
                }
            }
        }
        return List.copyOf(errors);
    }

    private static <T> List<T> safe(List<T> values) {
        return values == null ? List.of() : values;
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.JsonPointer;
import com.fasterxml.jackson.databind.PropertyNamingStrategies;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.IntNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.node.TextNode;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;

/** Node and execution lineage validation after strict JSON deserialization. */
public final class AgentResultEnvelopeValidator {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper()
            .setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE);

    public ValidationResult validate(
            AgentResultEnvelope envelope,
            String expectedWorkstreamId,
            String expectedRunId,
            NodeOutputContract contract
    ) {
        return validate(envelope, expectedWorkstreamId, expectedRunId, contract, List.of());
    }

    public ValidationResult validate(
            AgentResultEnvelope envelope,
            String expectedWorkstreamId,
            String expectedRunId,
            NodeOutputContract contract,
            List<String> activeObligationIds
    ) {
        var errors = new ValidationErrors();
        if (envelope == null) {
            errors.reject("envelope is required");
            return errors.result();
        }
        if (envelope.schemaVersion() == 0) {
            errors.repairable("schema_version", CorrectionValue.SCHEMA_VERSION, "schema_version must be 1");
        } else if (envelope.schemaVersion() != 1) {
            errors.reject("schema_version must be 1");
        }
        if (envelope.workstreamId() == null || envelope.workstreamId().isBlank()) {
            errors.repairable("workstream_id", CorrectionValue.WORKSTREAM_ID, "workstream_id is required");
        } else if (expectedWorkstreamId == null || expectedWorkstreamId.isBlank()
                || !expectedWorkstreamId.equals(envelope.workstreamId())) {
            errors.reject("workstream_id does not match current workstream");
        }
        if (envelope.runId() == null || envelope.runId().isBlank()) {
            errors.repairable("run_id", CorrectionValue.RUN_ID, "run_id is required");
        } else if (expectedRunId == null || expectedRunId.isBlank()
                || !expectedRunId.equals(envelope.runId())) {
            errors.reject("run_id does not match current execution");
        }
        if (envelope.nodeId() == null || envelope.nodeId().isBlank()) {
            errors.repairable("node_id", CorrectionValue.NODE_ID, "node_id is required");
        } else if (!contract.nodeId().equals(envelope.nodeId())) {
            errors.reject("node_id does not match current node");
        }
        if (envelope.result() == null) {
            errors.reject("result is required");
        } else {
            if (envelope.result().artifactType() == null || envelope.result().artifactType().isBlank()) {
                errors.reject("result.artifact_type is required");
            } else if (!contract.emitsArtifact(envelope.result().artifactType())) {
                errors.reject("result.artifact_type is not allowed for node " + contract.nodeId());
            }
            if (envelope.result().decision() == null || envelope.result().decision().isBlank()) {
                errors.reject("result.decision is required");
            } else if (!contract.allowedDecisions().contains(envelope.result().decision())) {
                errors.reject("result.decision is not allowed for node " + contract.nodeId());
            }
            if (envelope.result().summary() == null || envelope.result().summary().isBlank()) {
                errors.reject("result.summary is required");
            }
            validatePayload(envelope.result(), contract.nodeId(), errors, activeObligationIds);
        }
        return errors.result();
    }

    public ValidationResult validateCorrection(
            AgentResultEnvelope original,
            AgentResultEnvelope corrected,
            String expectedWorkstreamId,
            String expectedRunId,
            NodeOutputContract contract,
            ValidationResult originalValidation
    ) {
        return validateCorrection(original, corrected, expectedWorkstreamId, expectedRunId, contract, originalValidation, List.of());
    }

    public ValidationResult validateCorrection(
            AgentResultEnvelope original,
            AgentResultEnvelope corrected,
            String expectedWorkstreamId,
            String expectedRunId,
            NodeOutputContract contract,
            ValidationResult originalValidation,
            List<String> activeObligationIds
    ) {
        var correctedValidation = validate(corrected, expectedWorkstreamId, expectedRunId, contract);
        if (!correctedValidation.valid()) {
            return correctedValidation;
        }
        if (original == null || originalValidation == null || !originalValidation.schemaCorrectionAllowed()) {
            return ValidationResult.rejected("schema correction has no repairable original candidate");
        }
        if (originalValidation.correctsAuthoredReferences()) {
            if (!originalValidation.equals(validate(original, expectedWorkstreamId, expectedRunId, contract, activeObligationIds)))
                return ValidationResult.rejected("authored reference correction targets do not match the original candidate");
            var coverageErrors = AuthoredRevisionValidator.validate(authoredResponses(corrected.result()), activeObligationIds);
            if (!coverageErrors.isEmpty()) return ValidationResult.rejected(String.join("; ", coverageErrors));
        }
        var expected = OBJECT_MAPPER.valueToTree(original);
        if (!(expected instanceof ObjectNode expectedObject)) {
            return ValidationResult.rejected("schema correction baseline is not an object");
        }
        for (var target : originalValidation.correctionTargets()) {
            if (target.value() == CorrectionValue.ACTIVE_OBLIGATION_ID) {
                // Only malformed slots selected from the original can change. All other JSON values remain frozen.
                var pointer = JsonPointer.compile("/" + target.path().replace('.', '/'));
                var replacement = OBJECT_MAPPER.valueToTree(corrected).at(pointer);
                if (!replacement.isTextual() || !activeObligationIds.contains(replacement.asText())
                        || !(expectedObject.at(pointer.head()) instanceof ObjectNode response))
                    return ValidationResult.rejected("authored reference correction target is invalid: " + target.path());
                response.set("obligation_id", replacement);
                continue;
            }
            if (!applyExpectedValue(
                    expectedObject,
                    target,
                    expectedWorkstreamId,
                    expectedRunId,
                    contract.nodeId()
            )) {
                return ValidationResult.rejected("schema correction target is invalid: " + target.path());
            }
        }
        if (!expectedObject.equals(OBJECT_MAPPER.valueToTree(corrected))) {
            return ValidationResult.rejected("schema correction changed fields outside the repairable schema targets");
        }
        return correctedValidation;
    }

    private static void validatePayload(
            AgentResultEnvelope.AgentResult result,
            String nodeId,
            ValidationErrors errors,
            List<String> activeObligationIds
    ) {
        switch (result) {
            case AgentResultEnvelope.TaskContractProposalResult proposal -> {
                requiredText(proposal.objective(), "result.objective", errors);
                if (proposal.scope() == null) {
                    errors.reject("result.scope is required");
                } else {
                    requiredList(proposal.scope().included(), "result.scope.included", true, errors);
                    requiredList(proposal.scope().excluded(), "result.scope.excluded", false, errors);
                    validateScopeEntries(proposal.scope().included(), errors);
                }
                requiredList(proposal.acceptanceCriteria(), "result.acceptance_criteria", true, errors);
                requiredList(proposal.testRequirements(), "result.test_requirements", true, errors);
                requiredList(proposal.constraints(), "result.constraints", false, errors);
                requiredList(proposal.nonGoals(), "result.non_goals", false, errors);
                requiredList(proposal.riskAreas(), "result.risk_areas", false, errors);
                requiredList(proposal.evidenceRefs(), "result.evidence_refs", false, errors);
                requiredList(proposal.openQuestions(), "result.open_questions", false, errors);
                requiredList(proposal.revisionResponses(), "result.revision_responses", false, errors);
                validateContractClauses(proposal, errors);
                validateRevisionResponses(proposal.revisionResponses(), errors);
            }
            case AgentResultEnvelope.TaskContractRevisionPatchResult patch -> validateRevisionPatch(patch, errors);
            case AgentResultEnvelope.AgentOutputResult output -> {
                validateEvidencePayload(
                        output.lifecycleStatus(), output.checks(), output.evidence(), output.missingEvidence(),
                        output.mustFix(), output.acceptanceNotes(), output.openRisks(), output.changedFiles(),
                        output.verificationSummary(), output.failure(), errors);
                requiredList(output.rereadReasons(), "result.reread_reasons", false, errors);
                validateRereadReasons(output.rereadReasons(), errors);
                validateReviewObligations(nodeId, output, errors);
                validateNoVerificationRemediation(output.failure(), errors);
            }
            case AgentResultEnvelope.DesignResult design -> {
                validateAuthoredResponses(design.revisionResponses(), activeObligationIds, errors);
                requiredText(design.lifecycleStatus(), "result.lifecycle_status", errors);
                requiredList(design.checks(), "result.checks", false, errors);
                requiredList(design.evidence(), "result.evidence", false, errors);
                requiredList(design.missingEvidence(), "result.missing_evidence", false, errors);
                requiredList(design.mustFix(), "result.must_fix", false, errors);
                requiredList(design.openRisks(), "result.open_risks", false, errors);
                requiredText(design.verificationSummary(), "result.verification_summary", errors);
                for (var error : DesignScopeValidator.shapeErrors(design.design())) {
                    errors.reject(error);
                }
            }
            case AgentResultEnvelope.PlanResult plan -> {
                validateAuthoredResponses(plan.revisionResponses(), activeObligationIds, errors);
                validateEvidencePayload(
                        plan.lifecycleStatus(), plan.checks(), plan.evidence(), plan.missingEvidence(),
                        plan.mustFix(), plan.acceptanceNotes(), plan.openRisks(), plan.changedFiles(),
                        plan.verificationSummary(), plan.failure(), errors);
                if (plan.plan() == null) {
                    errors.reject("result.plan is required");
                } else {
                    requiredList(plan.plan().implementationSteps(), "result.plan.implementation_steps", true, errors);
                    requiredList(plan.plan().editFiles(), "result.plan.edit_files", true, errors);
                    PlanScopeValidator.shapeErrors(plan.plan()).forEach(errors::reject);
                    requiredList(plan.plan().referenceFiles(), "result.plan.reference_files", false, errors);
                    requiredList(plan.plan().fileLevelChanges(), "result.plan.file_level_changes", true, errors);
                    requiredList(plan.plan().validationPlan(), "result.plan.validation_plan", true, errors);
                    requiredText(plan.plan().rollbackNotes(), "result.plan.rollback_notes", errors);
                    requiredList(plan.plan().knownRisks(), "result.plan.known_risks", true, errors);
                    requiredList(plan.plan().humanReviewChecklist(), "result.plan.human_review_checklist", true, errors);
                }
                validateNoVerificationRemediation(plan.failure(), errors);
            }
            case AgentResultEnvelope.SelfTestResult selfTest -> {
                requiredText(selfTest.lifecycleStatus(), "result.lifecycle_status", errors);
                requiredList(selfTest.checksRun(), "result.checks_run", false, errors);
                requiredList(selfTest.checksSkipped(), "result.checks_skipped", false, errors);
                requiredList(selfTest.evidence(), "result.evidence", false, errors);
                requiredList(selfTest.missingEvidence(), "result.missing_evidence", false, errors);
                requiredList(selfTest.mustFix(), "result.must_fix", false, errors);
                if ("SELF_TEST_COMPLETE".equals(selfTest.decision())
                        && ((selfTest.mustFix() != null && !selfTest.mustFix().isEmpty())
                        || (selfTest.missingEvidence() != null && !selfTest.missingEvidence().isEmpty()))) {
                    errors.reject("SELF_TEST_COMPLETE cannot include must_fix or missing_evidence");
                }
                requiredList(selfTest.acceptanceNotes(), "result.acceptance_notes", false, errors);
                requiredText(selfTest.verificationSummary(), "result.verification_summary", errors);
            }
            case AgentResultEnvelope.AcceptanceReviewResult review -> {
                validateEvidencePayload(
                        review.lifecycleStatus(), review.checks(), review.evidence(), review.missingEvidence(),
                        review.mustFix(), review.acceptanceNotes(), review.openRisks(), review.changedFiles(),
                        review.verificationSummary(), review.failure(), errors);
                if (review.failure() != null) {
                    var failure = review.failure();
                    AgentContractSemantics.validateAcceptanceClassification(review.decision(), failure.categoryHint(),
                            failure.verificationRemediation(), failure.contractGaps(), failure.outOfScopeFiles(),
                            failure.missingTests(), failure.contextGaps(), failure.reason(),
                            review.mustFix(), review.missingEvidence()).ifPresent(v -> errors.reject(v.message()));
                }
            }
            case AgentResultEnvelope.StageHandoffResult handoff -> {
                requiredText(handoff.lifecycleStatus(), "result.lifecycle_status", errors);
                requiredList(handoff.completedWork(), "result.completed_work", true, errors);
                requiredList(handoff.importantDecisions(), "result.important_decisions", false, errors);
                requiredList(handoff.changedFiles(), "result.changed_files", false, errors);
                requiredText(handoff.verificationState(), "result.verification_state", errors);
                requiredList(handoff.openRisks(), "result.open_risks", false, errors);
                requiredText(handoff.recommendedNextStage(), "result.recommended_next_stage", errors);
                requiredText(handoff.suggestedNextPrompt(), "result.suggested_next_prompt", errors);
            }
        }
    }

    private static List<AgentResultEnvelope.AuthoredRevisionResponse> authoredResponses(AgentResultEnvelope.AgentResult result) {
        return switch (result) {
            case AgentResultEnvelope.DesignResult design -> design.revisionResponses();
            case AgentResultEnvelope.PlanResult plan -> plan.revisionResponses();
            default -> null;
        };
    }

    private static void validateAuthoredResponses(List<AgentResultEnvelope.AuthoredRevisionResponse> responses,
                                                List<String> activeIds, ValidationErrors errors) {
        var indexes = AuthoredRevisionValidator.repairableReferenceIndexes(responses, activeIds);
        if (indexes.isEmpty()) {
            AuthoredRevisionValidator.shapeErrors(responses).forEach(errors::reject);
        } else {
            for (int index : indexes) errors.repairable("result.revision_responses." + index + ".obligation_id",
                    CorrectionValue.ACTIVE_OBLIGATION_ID,
                    AuthoredRevisionValidator.invalidIdMessage(index, responses.get(index).obligationId()));
        }
    }

    private static void validateRevisionPatch(
            AgentResultEnvelope.TaskContractRevisionPatchResult patch,
            ValidationErrors errors
    ) {
        requiredText(patch.baseProposalId(), "result.base_proposal_id", errors);
        requiredText(patch.baseProposalSha256(), "result.base_proposal_sha256", errors);
        if (patch.baseProposalSha256() != null
                && !patch.baseProposalSha256().matches("[0-9a-f]{64}")) {
            errors.reject("result.base_proposal_sha256 must be 64 lowercase hexadecimal characters");
        }
        requiredList(patch.obligationPatches(), "result.obligation_patches", true, errors);
        if (patch.obligationPatches() == null) {
            return;
        }
        var obligationIds = new HashSet<String>();
        for (int index = 0; index < patch.obligationPatches().size(); index++) {
            var value = patch.obligationPatches().get(index);
            var item = "result.obligation_patches[" + index + "]";
            if (value == null) {
                errors.reject(item + " is required");
                continue;
            }
            requiredText(value.reviewObligationId(), item + ".review_obligation_id", errors);
            requiredList(value.resolvedByClauseIds(), item + ".resolved_by_clause_ids", true, errors);
            requiredList(value.clauseChanges(), item + ".clause_changes", false, errors);
            requiredList(value.scopeAdditions(), item + ".scope_additions", false, errors);
            requiredList(value.evidenceRefAdditions(), item + ".evidence_ref_additions", false, errors);
            if (value.reviewObligationId() != null && !value.reviewObligationId().isBlank()
                    && !obligationIds.add(value.reviewObligationId().trim())) {
                errors.reject("result.obligation_patches contains duplicate obligation id: "
                        + value.reviewObligationId().trim());
            }
            if (value.clauseChanges() != null) {
                for (int changeIndex = 0; changeIndex < value.clauseChanges().size(); changeIndex++) {
                    var change = value.clauseChanges().get(changeIndex);
                    var changeItem = item + ".clause_changes[" + changeIndex + "]";
                    if (change == null) {
                        errors.reject(changeItem + " is required");
                        continue;
                    }
                    if (change.operation() == null) {
                        errors.reject(changeItem + ".operation is required");
                    }
                    if (change.section() == null) {
                        errors.reject(changeItem + ".section is required");
                    }
                    requiredText(change.id(), changeItem + ".id", errors);
                    requiredText(change.text(), changeItem + ".text", errors);
                }
            }
            validateScopeEntries(value.scopeAdditions(), errors);
        }
        TaskContractRevisionPatchTargetValidator.validate(patch).forEach(errors::reject);
    }

    private static void validateContractClauses(
            AgentResultEnvelope.TaskContractProposalResult proposal,
            ValidationErrors errors
    ) {
        var ids = new HashSet<String>();
        validateContractClauses(proposal.acceptanceCriteria(), "result.acceptance_criteria", ids, errors);
        validateContractClauses(proposal.testRequirements(), "result.test_requirements", ids, errors);
        validateContractClauses(proposal.constraints(), "result.constraints", ids, errors);
        validateContractClauses(proposal.nonGoals(), "result.non_goals", ids, errors);
        validateContractClauses(proposal.riskAreas(), "result.risk_areas", ids, errors);
    }

    private static void validateContractClauses(
            List<AgentResultEnvelope.ContractClause> clauses,
            String field,
            HashSet<String> ids,
            ValidationErrors errors
    ) {
        if (clauses == null) {
            return;
        }
        for (int index = 0; index < clauses.size(); index++) {
            var clause = clauses.get(index);
            var item = field + "[" + index + "]";
            if (clause == null) {
                errors.reject(item + " is required");
                continue;
            }
            requiredText(clause.id(), item + ".id", errors);
            requiredText(clause.text(), item + ".text", errors);
            if (clause.id() != null && !clause.id().isBlank() && !ids.add(clause.id().trim())) {
                errors.reject("result contract clause id is duplicated: " + clause.id().trim());
            }
        }
    }

    private static void validateRevisionResponses(
            List<AgentResultEnvelope.RevisionResponse> responses,
            ValidationErrors errors
    ) {
        if (responses == null) {
            return;
        }
        var obligationIds = new HashSet<String>();
        for (int index = 0; index < responses.size(); index++) {
            var response = responses.get(index);
            var item = "result.revision_responses[" + index + "]";
            if (response == null) {
                errors.reject(item + " is required");
                continue;
            }
            requiredText(response.reviewObligationId(), item + ".review_obligation_id", errors);
            requiredList(response.resolvedByClauseIds(), item + ".resolved_by_clause_ids", true, errors);
            if (response.reviewObligationId() != null
                    && !response.reviewObligationId().isBlank()
                    && !obligationIds.add(response.reviewObligationId().trim())) {
                errors.reject("result.revision_responses contains duplicate obligation id: "
                        + response.reviewObligationId().trim());
            }
        }
    }

    private static void validateReviewObligations(
            String nodeId,
            AgentResultEnvelope.AgentOutputResult output,
            ValidationErrors errors
    ) {
        var obligations = output.contractObligations();
        var contractRevision = "intake.codex_product_review".equals(nodeId)
                && "NEEDS_REVISION".equals(output.decision())
                && output.failure() != null
                && output.failure().contractGaps() != null
                && !output.failure().contractGaps().isEmpty();
        if (contractRevision) {
            requiredList(obligations, "result.contract_obligations", true, errors);
        } else if (obligations != null && !obligations.isEmpty()) {
            errors.reject("result.contract_obligations is only allowed for intake contract revisions");
        }
        if (obligations == null) {
            return;
        }
        var ids = new HashSet<String>();
        for (int index = 0; index < obligations.size(); index++) {
            var obligation = obligations.get(index);
            var item = "result.contract_obligations[" + index + "]";
            if (obligation == null) {
                errors.reject(item + " is required");
                continue;
            }
            requiredText(obligation.id(), item + ".id", errors);
            requiredText(obligation.text(), item + ".text", errors);
            if (obligation.id() != null && !obligation.id().isBlank()
                    && !ids.add(obligation.id().trim())) {
                errors.reject("result.contract_obligations contains duplicate id: "
                        + obligation.id().trim());
            }
        }
    }

    private static void validateScopeEntries(
            List<AgentResultEnvelope.ProposalScopePath> entries,
            ValidationErrors errors
    ) {
        if (entries == null) {
            return;
        }
        for (var entry : entries) {
            if (entry == null) {
                errors.reject("result.scope.included contains null entry");
                continue;
            }
            requiredText(entry.path(), "result.scope.included.path", errors);
        }
    }

    private static void validateEvidencePayload(
            String lifecycleStatus,
            List<String> checks,
            List<String> evidence,
            List<String> missingEvidence,
            List<String> mustFix,
            List<String> acceptanceNotes,
            List<String> openRisks,
            List<String> changedFiles,
            String verificationSummary,
            AgentResultEnvelope.Failure failure,
            ValidationErrors errors
    ) {
        requiredText(lifecycleStatus, "result.lifecycle_status", errors);
        requiredList(checks, "result.checks", false, errors);
        requiredList(evidence, "result.evidence", false, errors);
        requiredList(missingEvidence, "result.missing_evidence", false, errors);
        requiredList(mustFix, "result.must_fix", false, errors);
        requiredList(acceptanceNotes, "result.acceptance_notes", false, errors);
        requiredList(openRisks, "result.open_risks", false, errors);
        requiredList(changedFiles, "result.changed_files", false, errors);
        requiredText(verificationSummary, "result.verification_summary", errors);
        if (failure == null) {
            errors.reject("result.failure is required");
            return;
        }
        requiredList(failure.contractGaps(), "result.failure.contract_gaps", false, errors);
        requiredList(failure.outOfScopeFiles(), "result.failure.out_of_scope_files", false, errors);
        requiredList(failure.missingTests(), "result.failure.missing_tests", false, errors);
        requiredList(failure.contextGaps(), "result.failure.context_gaps", false, errors);
    }


    private static void validateNoVerificationRemediation(
            AgentResultEnvelope.Failure failure,
            ValidationErrors errors
    ) {
        if (failure != null
                && failure.verificationRemediation() != null
                && failure.verificationRemediation() != AgentResultEnvelope.VerificationRemediation.NONE) {
            errors.reject("result.failure.verification_remediation must be NONE outside acceptance review");
        }
    }

    private static void validateRereadReasons(
            List<AgentResultEnvelope.RereadReason> reasons,
            ValidationErrors errors
    ) {
        if (reasons == null) {
            return;
        }
        for (int index = 0; index < reasons.size(); index++) {
            var reason = reasons.get(index);
            if (reason == null) {
                errors.reject("result.reread_reasons[" + index + "] is required");
                continue;
            }
            requiredText(reason.path(), "result.reread_reasons[" + index + "].path", errors);
            if (!ReadReuseContractReasons.isAllowed(reason.reason())) {
                errors.reject("result.reread_reasons[" + index + "].reason is not allowed");
            }
        }
    }

    private static void requiredText(String value, String field, ValidationErrors errors) {
        if (value == null || value.isBlank()) {
            errors.reject(field + " is required");
        }
    }

    private static void requiredList(List<?> value, String field, boolean nonEmpty, ValidationErrors errors) {
        if (value == null) {
            if (nonEmpty) {
                errors.reject(field + " is required");
            } else {
                errors.repairable(field, CorrectionValue.EMPTY_LIST, field + " is required");
            }
        } else if (nonEmpty && value.isEmpty()) {
            errors.reject(field + " must not be empty");
        }
    }

    private static boolean applyExpectedValue(
            ObjectNode root,
            CorrectionTarget target,
            String expectedWorkstreamId,
            String expectedRunId,
            String expectedNodeId
    ) {
        var value = switch (target.value()) {
            case SCHEMA_VERSION -> IntNode.valueOf(1);
            case WORKSTREAM_ID -> TextNode.valueOf(expectedWorkstreamId);
            case RUN_ID -> TextNode.valueOf(expectedRunId);
            case NODE_ID -> TextNode.valueOf(expectedNodeId);
            case EMPTY_LIST -> new ArrayNode(OBJECT_MAPPER.getNodeFactory());
            case ACTIVE_OBLIGATION_ID -> null;
        };
        if (value == null) return false;
        var segments = target.path().split("\\.");
        ObjectNode parent = root;
        for (int index = 0; index < segments.length - 1; index++) {
            var child = parent.get(segments[index]);
            if (!(child instanceof ObjectNode childObject)) {
                return false;
            }
            parent = childObject;
        }
        parent.set(segments[segments.length - 1], value);
        return true;
    }

    public enum CorrectionDisposition {
        NONE,
        SCHEMA_REPAIRABLE,
        NOT_REPAIRABLE
    }

    public enum CorrectionValue {
        SCHEMA_VERSION,
        WORKSTREAM_ID,
        RUN_ID,
        NODE_ID,
        EMPTY_LIST,
        ACTIVE_OBLIGATION_ID
    }

    public record CorrectionTarget(String path, CorrectionValue value) {
    }

    public record ValidationResult(
            boolean valid,
            List<String> errors,
            CorrectionDisposition correctionDisposition,
            List<CorrectionTarget> correctionTargets
    ) {
        static ValidationResult pass() {
            return new ValidationResult(true, List.of(), CorrectionDisposition.NONE, List.of());
        }

        static ValidationResult rejected(String error) {
            return new ValidationResult(
                    false,
                    List.of(error),
                    CorrectionDisposition.NOT_REPAIRABLE,
                    List.of()
            );
        }

        public boolean schemaCorrectionAllowed() {
            return correctionDisposition == CorrectionDisposition.SCHEMA_REPAIRABLE;
        }

        public boolean correctsAuthoredReferences() {
            return correctionTargets.stream().anyMatch(target -> target.value() == CorrectionValue.ACTIVE_OBLIGATION_ID);
        }
    }

    private static final class ValidationErrors {
        private final List<String> messages = new ArrayList<>();
        private final List<CorrectionTarget> correctionTargets = new ArrayList<>();
        private boolean rejected;

        void repairable(String field, CorrectionValue value, String message) {
            messages.add(message);
            correctionTargets.add(new CorrectionTarget(field, value));
        }

        void reject(String message) {
            messages.add(message);
            rejected = true;
        }

        ValidationResult result() {
            if (messages.isEmpty()) {
                return ValidationResult.pass();
            }
            var referenceOnly = correctionTargets.stream().noneMatch(target -> target.value() == CorrectionValue.ACTIVE_OBLIGATION_ID)
                    || correctionTargets.stream().allMatch(target -> target.value() == CorrectionValue.ACTIVE_OBLIGATION_ID);
            var disposition = !correctionTargets.isEmpty() && !rejected && referenceOnly
                    ? CorrectionDisposition.SCHEMA_REPAIRABLE
                    : CorrectionDisposition.NOT_REPAIRABLE;
            return new ValidationResult(
                    false,
                    List.copyOf(messages),
                    disposition,
                    List.copyOf(correctionTargets)
            );
        }
    }
}

package dev.dual.runtime.handler;

import java.util.List;

/**
 * Central catalog of reasons an agent may re-read a file already covered by the
 * read-reuse contract. Shared by {@code RepoScopeGovernance} (which writes the
 * contract into {@code read-reuse-contract.json}) and the artifact-contract
 * validator (which validates declared {@code reread_reasons}) so the allowed
 * set has exactly one source of truth.
 */
public final class ReadReuseContractReasons {
    public static final List<String> ALLOWED_REPEATED_READ_REASONS = List.of(
            "file changed after prior read",
            "exact current content is needed before editing",
            "previous evidence does not cover the selected stage");

    static boolean isAllowed(String reason) {
        return reason != null && ALLOWED_REPEATED_READ_REASONS.contains(reason);
    }

    private ReadReuseContractReasons() {
    }
}

package dev.dual.runtime.handler;

/**
 * Canonical stage outcome compiled by the orchestrator from Agent decisions,
 * declared artifact status, evidence fields, and runtime facts.
 *
 * Agent output may propose a decision, but workflow routing should consume this
 * normalized stage outcome plus the original routing decision. This keeps
 * runtime failures, semantic review results, and evidence gaps from collapsing
 * into one overloaded "decision" string.
 */
enum StageOutcome {
    READY,
    NEEDS_REVISION,
    BLOCKED,
    ACCEPTED,
    ACCEPTED_WITH_NOTES,
    REJECTED,
    INSUFFICIENT_EVIDENCE,
    UNKNOWN;

    static StageOutcome fromDecision(String decision) {
        return switch (normalized(decision)) {
            case "PASS",
                 "READY_FOR_PRODUCT_REVIEW",
                 "READY_FOR_ARCH_REVIEW",
                 "READY_FOR_PLAN_REVIEW",
                 "READY_TO_IMPLEMENT",
                 "IMPLEMENTED",
                 "SELF_TEST_COMPLETE",
                 "HANDOFF_READY",
                 "READY_FOR_REVIEW" -> READY;
            case "NEEDS_REVISION",
                 "NEEDS_CLARIFICATION",
                 "NEEDS_SCOPE_REDUCTION" -> NEEDS_REVISION;
            case "BLOCKED" -> BLOCKED;
            case "ACCEPT" -> ACCEPTED;
            case "ACCEPT_WITH_NOTES" -> ACCEPTED_WITH_NOTES;
            case "REJECT",
                 "REJECTED",
                 "REJECT_CONTRACT_GAP",
                 "REJECT_CONTRACT_AMBIGUITY",
                 "REJECT_IMPLEMENTATION_BUG",
                 "REJECT_CONTEXT_INSUFFICIENT",
                 "REJECT_TOOL_LIMITATION",
                 "REJECT_REVIEW_NOISE" -> REJECTED;
            case "REJECT_VERIFICATION_INSUFFICIENT" -> INSUFFICIENT_EVIDENCE;
            case "SELF_TEST_INCOMPLETE",
                 "NOTED_CONTEXT_INSUFFICIENT",
                 "NOTED_VERIFICATION_INSUFFICIENT" -> INSUFFICIENT_EVIDENCE;
            case "NOTED_CONTRACT_GAP",
                 "NOTED_CONTRACT_AMBIGUITY",
                 "NOTED_IMPLEMENTATION_BUG",
                 "NOTED_TOOL_LIMITATION",
                 "NOTED_REVIEW_NOISE" -> ACCEPTED_WITH_NOTES;
            default -> UNKNOWN;
        };
    }

    static StageOutcome fromText(String value) {
        try {
            return StageOutcome.valueOf(normalized(value));
        } catch (IllegalArgumentException e) {
            return UNKNOWN;
        }
    }

    private static String normalized(String value) {
        return value == null ? "" : value.trim().toUpperCase();
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Read-only projector from {@code workstream-memory.json} into the agent-facing
 * context-package memory sections.
 *
 * <p>The {@code working_memory} section (Claude implement) renders an
 * {@link #appendAgentHandoff AgentHandoff}; the {@code review_evidence} section
 * (Codex review) renders a {@link #appendReviewEvidenceBrief ReviewEvidenceBrief}.
 * Both are projections of the orchestrator-owned {@code WorkstreamMemory} (the
 * source of truth), not of the rebuilt {@code EvidenceManifest}. They embed real
 * ledger evidence refs so accuracy does not depend on dump volume: scope source,
 * prior verdict artifact path, changed-files/diff path, and readFiles with
 * path+sha+summary+trusted/invalidationReason.</p>
 *
 * <p>When memory is empty or key fields are missing, only minimal fallback refs
 * are emitted. The old top-N evidence dump is never restored.</p>
 */
public final class WorkstreamMemoryProjection {
    private static final ObjectMapper MAPPER = new ObjectMapper().registerModule(new JavaTimeModule());
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };
    private static final int MAX_READS = 12;
    private static final int MAX_OPEN_ISSUES = 12;
    private static final int MAX_CHANGED_FILES = 16;

    private WorkstreamMemoryProjection() {
    }

    /**
     * Claude implement handoff: decided scope, non-goals, reusable + invalidated
     * reads, last stage outcome, open issues, the reuse directive, and evidence
     * refs. Appends section body only (the caller writes the {@code ##} heading).
     */
    public static void appendAgentHandoff(StringBuilder builder, Path workstreamDir, Path workspaceRoot) {
        var memory = readMemory(workstreamDir);
        var qualification = qualificationStatus(memory, workstreamDir, workspaceRoot);
        var decidedScope = strings(memory.get("decidedScope"));
        var nonGoals = strings(memory.get("nonGoals"));
        var reads = list(memory.get("readFiles"));
        var openIssues = openIssues(list(memory.get("openIssues")));
        var lastOutcome = map(memory.get("lastStageOutcome"));
        var decisions = list(memory.get("decisions"));
        var hasAny = !decidedScope.isEmpty() || !nonGoals.isEmpty() || !reads.isEmpty()
                || !openIssues.isEmpty() || !decisions.isEmpty() || !lastOutcome.isEmpty();

        builder.append("Orchestrator-owned memory for this workstream. Reuse it instead of re-reading files or re-deriving scope.\n\n");
        builder.append("TaskContract projection: ").append(qualification).append("\n\n");

        appendBullets(builder, "Decided scope", decidedScope, MAX_OPEN_ISSUES);
        appendBullets(builder, "Non-goals", nonGoals, MAX_OPEN_ISSUES);
        appendReusableReads(builder, reads, "Reusable reads (summary trusted, do not re-read)");
        appendInvalidatedReads(builder, reads);
        appendLastOutcome(builder, lastOutcome, decisions);
        appendBullets(builder, "Open issues (resolve before claiming done)", issueTexts(openIssues), MAX_OPEN_ISSUES);

        builder.append("\nDo NOT re-explore from README/docs/source/test to re-derive this scope. ")
                .append("Re-read a listed file only when editing or verifying it, its sha changed, or the summary does not cover this stage — ")
                .append("and record the reason in your structured artifact.\n\n");

        if (!hasAny) {
            builder.append("(memory has no recorded scope, reads, or decisions yet for this workstream; ")
                    .append("proceed with the task contract and read-reuse contract below.)\n\n");
        }
        appendEvidenceRefs(builder, workstreamDir, workspaceRoot);
    }

    /**
     * Codex review brief: prior verdict + unresolved must-fix, open issues,
     * acceptance criteria, this round's changed files, a compact reusable-read /
     * decision summary, the incremental-audit directive, and evidence refs.
     * Appends section body only (the caller writes the {@code ##} heading).
     */
    public static void appendReviewEvidenceBrief(StringBuilder builder, Path workstreamDir, Path workspaceRoot) {
        var memory = readMemory(workstreamDir);
        var qualification = qualificationStatus(memory, workstreamDir, workspaceRoot);
        var verdicts = list(memory.get("priorVerdicts"));
        var openIssues = openIssues(list(memory.get("openIssues")));
        var acceptance = List.<String>of();
        var changedFiles = readChangedFiles(workstreamDir);
        var reusablePaths = reusableReadPaths(memory);

        var hasAny = !verdicts.isEmpty() || !openIssues.isEmpty() || !acceptance.isEmpty()
                || !changedFiles.isEmpty() || !reusablePaths.isEmpty();

        builder.append("TaskContract projection: ").append(qualification).append("\n\n");

        if (!hasAny) {
            builder.append("(no cumulative review verdict recorded; no open issues, changed files, or reusable memory recorded yet) Evidence: ")
                    .append(ref(workspaceRoot, workstreamDir.resolve("memory/workstream-memory.json")))
                    .append(".\n\n");
            return;
        }

        if (verdicts.isEmpty()) {
            builder.append("No cumulative review verdict recorded. Review the complete current subject against the contract baseline.\n\n");
        } else {
            builder.append("Incremental acceptance from orchestrator memory; verify it against the complete current subject.\n\n");
        }

        if (!verdicts.isEmpty()) {
            var verdict = verdicts.get(verdicts.size() - 1);
            var line = new StringBuilder();
            if (!text(verdict.get("stage")).isBlank()) {
                line.append(text(verdict.get("stage"))).append(" / ");
            }
            line.append(text(verdict.get("decision")));
            if (Boolean.TRUE.equals(verdict.get("blocking"))) {
                line.append(" (blocking)");
            }
            builder.append("**Prior verdict:** ").append(line).append("\n\n");
            appendBullets(builder, "Prior must-fix (verify resolved)", strings(verdict.get("mustFix")), MAX_OPEN_ISSUES);
        }
        appendBullets(builder, "Open issues to confirm", issueTexts(openIssues), MAX_OPEN_ISSUES);
        appendBullets(builder, "Acceptance criteria", acceptance, MAX_OPEN_ISSUES);
        appendBullets(builder, "Changed files this round", changedFiles, MAX_CHANGED_FILES);
        if (!reusablePaths.isEmpty()) {
            builder.append("- Relevant memory (reuse, do not re-read): ").append(String.join("; ", reusablePaths)).append("\n\n");
        }

        if (verdicts.isEmpty()) {
            builder.append("Derive the complete current blocker set from the review subject and acceptance criteria; ");
        } else {
            builder.append("Confirm prior must-fix and derive any additional current blockers from the complete review subject; ");
        }
        builder.append("re-read a file only with a reason (edit/verify/sha-changed/stage-gap).\n");
        builder.append("Evidence: memory ").append(ref(workspaceRoot, workstreamDir.resolve("memory/workstream-memory.json")))
                .append("; diff ").append(ref(workspaceRoot, workstreamDir.resolve("artifacts/git-evidence/diff.patch")))
                .append("; changed ").append(ref(workspaceRoot, workstreamDir.resolve("artifacts/git-evidence/changed-files.txt")))
                .append(".\n\n");
    }

    private static List<String> reusableReadPaths(Map<String, Object> memory) {
        var out = new ArrayList<String>();
        for (var read : list(memory.get("readFiles")).stream()
                .filter(r -> Boolean.TRUE.equals(r.get("trusted")) && text(r.get("invalidationReason")).isBlank())
                .limit(5).toList()) {
            var path = text(read.get("path"));
            if (!path.isBlank()) {
                out.add(path);
            }
        }
        return out;
    }

    private static void appendReusableReads(StringBuilder builder, List<Map<String, Object>> reads, String label) {
        var items = new ArrayList<String>();
        for (var read : reads.stream().limit(MAX_READS).toList()) {
            if (!Boolean.TRUE.equals(read.get("trusted")) || !text(read.get("invalidationReason")).isBlank()) {
                continue;
            }
            items.add(text(read.get("path")) + " — " + text(read.get("summary"))
                    + " [sha " + shortSha(text(read.get("sha"))) + ", read " + text(read.get("readRunId")) + "]"
                    + " reuse unless editing/verifying");
        }
        appendBullets(builder, label, items, MAX_READS);
    }

    private static void appendInvalidatedReads(StringBuilder builder, List<Map<String, Object>> reads) {
        var items = new ArrayList<String>();
        for (var read : reads.stream().limit(MAX_READS).toList()) {
            var reason = text(read.get("invalidationReason"));
            if (reason.isBlank()) {
                continue;
            }
            items.add(text(read.get("path")) + " — fresh read allowed (" + reason + ")");
        }
        appendBullets(builder, "Invalidated reads (fresh read allowed)", items, MAX_READS);
    }

    private static void appendLastOutcome(StringBuilder builder, Map<String, Object> outcome, List<Map<String, Object>> decisions) {
        Map<String, Object> latest = outcome.isEmpty() ? latestDecision(decisions) : outcome;
        if (latest.isEmpty()) {
            return;
        }
        var stage = text(latest.getOrDefault("stage", latest.get("stageId")));
        var decision = text(latest.get("decision"));
        var summary = text(latest.get("summary"));
        var verification = text(latest.get("verificationSummary"));
        var line = new StringBuilder();
        if (!stage.isBlank()) {
            line.append(stage).append(" / ");
        }
        if (!decision.isBlank()) {
            line.append(decision);
        }
        if (!summary.isBlank()) {
            line.append(line.isEmpty() ? "" : " — ").append(summary);
        }
        if (!verification.isBlank()) {
            line.append(" (verification: ").append(verification).append(")");
        }
        if (!line.isEmpty()) {
            builder.append("**Last stage outcome:**\n- ").append(line).append("\n\n");
        }
    }

    private static Map<String, Object> latestDecision(List<Map<String, Object>> decisions) {
        if (decisions.isEmpty()) {
            return Map.of();
        }
        return decisions.get(decisions.size() - 1);
    }

    private static List<Map<String, Object>> openIssues(List<Map<String, Object>> issues) {
        var open = new ArrayList<Map<String, Object>>();
        for (var issue : issues) {
            if (!"resolved".equalsIgnoreCase(text(issue.get("status")))) {
                open.add(issue);
            }
        }
        return open;
    }

    private static List<String> issueTexts(List<Map<String, Object>> issues) {
        var texts = new ArrayList<String>();
        for (var issue : issues) {
            var desc = text(issue.get("desc"));
            if (!desc.isBlank()) {
                texts.add(desc);
            }
        }
        return texts;
    }

    private static void appendBullets(StringBuilder builder, String label, List<String> items, int limit) {
        var bounded = items.stream().filter(s -> !s.isBlank()).distinct().limit(limit).toList();
        if (bounded.isEmpty()) {
            return;
        }
        builder.append("**").append(label).append(":**\n");
        for (var item : bounded) {
            builder.append("- ").append(item).append("\n");
        }
        builder.append("\n");
    }

    private static void appendEvidenceRefs(StringBuilder builder, Path workstreamDir, Path workspaceRoot) {
        var memory = readMemory(workstreamDir);
        var refs = map(memory.get("refs"));
        var qualification = map(memory.get("qualifiedTaskContract"));
        builder.append("Evidence refs:\n");
        builder.append("- Memory: ").append(ref(workspaceRoot, workstreamDir.resolve("memory/workstream-memory.json"))).append("\n");
        var contractRef = text(qualification.get("ref"));
        var contractSha = text(qualification.get("sha256"));
        if (!contractRef.isBlank() && !contractSha.isBlank()) {
            builder.append("- Qualified scope source: ").append(contractRef)
                    .append(" @ ").append(contractSha).append("\n");
        } else {
            builder.append("- Qualified scope source: unavailable\n");
        }
        var readReuseRef = text(refs.get("readReuseContract"));
        if (!readReuseRef.isBlank()) {
            builder.append("- Read-reuse contract: ").append(readReuseRef).append("\n");
        }
        builder.append("\n");
    }

    private static Map<String, Object> readMemory(Path workstreamDir) {
        return readJson(workstreamDir.resolve("memory/workstream-memory.json"));
    }

    private static Map<String, Object> readJson(Path path) {
        if (!Files.isRegularFile(path)) {
            return Map.of();
        }
        try {
            return MAPPER.readValue(path.toFile(), MAP_TYPE);
        } catch (IOException | RuntimeException ignored) {
            return Map.of();
        }
    }

    private static String qualificationStatus(
            Map<String, Object> memory,
            Path workstreamDir,
            Path workspaceRoot
    ) {
        var projected = map(memory.get("qualifiedTaskContract"));
        var projectedRef = text(projected.get("ref"));
        var projectedSha = text(projected.get("sha256"));
        if (projectedRef.isBlank() || projectedSha.isBlank()) {
            return "unavailable";
        }
        var workstreamId = workstreamDir.getFileName().toString();
        var current = TaskContractProjectionVerifier.resolve(workspaceRoot, workstreamId);
        if (current.failure() != null || current.qualified().isEmpty()) {
            return "stale_projection";
        }
        var qualified = current.qualified().orElseThrow();
        return projectedRef.equals(qualified.contractRef()) && projectedSha.equals(qualified.sha256())
                ? "qualified_projection"
                : "stale_projection";
    }

    private static List<String> readChangedFiles(Path workstreamDir) {
        var path = workstreamDir.resolve("artifacts/git-evidence/changed-files.txt");
        var out = new ArrayList<String>();
        if (!Files.isRegularFile(path)) {
            return out;
        }
        try {
            for (var line : Files.readAllLines(path, StandardCharsets.UTF_8)) {
                var trimmed = line.trim();
                if (!trimmed.isBlank()) {
                    out.add(trimmed);
                }
            }
        } catch (IOException ignored) {
            return out;
        }
        return out;
    }

    private static String shortSha(String sha) {
        return sha.length() > 8 ? sha.substring(0, 8) : sha;
    }

    private static String ref(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize()
                .relativize(path.toAbsolutePath().normalize()).toString();
    }

    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> list(Object value) {
        if (!(value instanceof List<?> raw) || raw.isEmpty()) {
            return List.of();
        }
        var out = new ArrayList<Map<String, Object>>();
        for (var item : raw) {
            if (item instanceof Map<?, ?> map) {
                var copy = new java.util.LinkedHashMap<String, Object>();
                for (var e : map.entrySet()) {
                    if (e.getKey() instanceof String key) {
                        copy.put(key, e.getValue());
                    }
                }
                out.add(copy);
            }
        }
        return out;
    }

    private static Map<String, Object> map(Object value) {
        if (!(value instanceof Map<?, ?> raw)) {
            return Map.of();
        }
        var copy = new java.util.LinkedHashMap<String, Object>();
        for (var e : raw.entrySet()) {
            if (e.getKey() instanceof String key) {
                copy.put(key, e.getValue());
            }
        }
        return copy;
    }

    private static List<String> strings(Object value) {
        if (!(value instanceof List<?> raw)) {
            return List.of();
        }
        var out = new ArrayList<String>();
        for (var item : raw) {
            var t = text(item);
            if (!t.isBlank()) {
                out.add(t);
            }
        }
        return out;
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.adapter.git.GitPatchMergeService;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeResult;
import dev.dual.ledger.file.DeliveryCandidateDocument;
import dev.dual.ledger.file.DeliveryCandidateWriter;
import dev.dual.ledger.file.WorkstreamDocument;
import dev.dual.ledger.file.WorkspaceDocument;
import dev.dual.ledger.file.WorkstreamPaths;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class DeliveryPrepareHandler implements TaskHandler {
    private static final int MAX_SECTION_CHARS = 4_000;

    private final GitPatchMergeService git;
    private final DeliveryCandidateWriter candidateWriter;
    private final ObjectMapper objectMapper;

    public DeliveryPrepareHandler() {
        this(new GitPatchMergeService(), new DeliveryCandidateWriter(), new ObjectMapper().findAndRegisterModules());
    }

    DeliveryPrepareHandler(
            GitPatchMergeService git,
            DeliveryCandidateWriter candidateWriter,
            ObjectMapper objectMapper
    ) {
        this.git = git;
        this.candidateWriter = candidateWriter;
        this.objectMapper = objectMapper;
    }

    @Override
    public String type() {
        return "delivery.prepare_pr";
    }

    @Override
    public NodeResult execute(TaskContext context) throws Exception {
        var paths = new WorkstreamPaths(context.workspaceRoot(), new DualId(context.workstreamId()));
        var existing = candidateWriter.existing(paths, context.instance().nodeInstanceId());
        if (existing != null) {
            restoreStableProjections(paths, existing.document());
            return result(paths, existing);
        }

        var sourceIdentity = sourceIdentity(paths, context.workspaceRoot());
        var capture = git.capture(context.workspaceRoot());
        var commitMessage = renderCommitMessage(context.workstreamId(), paths.workstreamDir());
        var prBody = renderPrBody(context, paths.workstreamDir());
        var patchBytes = capture.patch().getBytes(StandardCharsets.UTF_8);
        var commitBytes = commitMessage.getBytes(StandardCharsets.UTF_8);
        var prBodyBytes = prBody.getBytes(StandardCharsets.UTF_8);
        var occurrenceDir = paths.deliveryCandidateDir(context.instance().nodeInstanceId());
        var patchRef = workspaceRef(paths.workspaceRoot(), occurrenceDir.resolve("merge.patch"));
        var commitRef = workspaceRef(paths.workspaceRoot(), occurrenceDir.resolve("commit-message.txt"));
        var prBodyRef = workspaceRef(paths.workspaceRoot(), occurrenceDir.resolve("pr-body.md"));
        var candidate = new DeliveryCandidateDocument(
                1,
                context.workstreamId(),
                context.instance().nodeInstanceId(),
                context.instance().iterationId(),
                sourceIdentity.workspaceId(),
                sourceIdentity.effectiveWorkdir(),
                capture.baseCommit(),
                capture.baseTree(),
                capture.acceptedFiles(),
                capture.excludedFiles(),
                new DeliveryCandidateDocument.ArtifactReference(patchRef, DeliveryCandidateWriter.sha256(patchBytes)),
                capture.expectedResultTree(),
                new DeliveryCandidateDocument.ArtifactReference(commitRef, DeliveryCandidateWriter.sha256(commitBytes)),
                new DeliveryCandidateDocument.ArtifactReference(prBodyRef, DeliveryCandidateWriter.sha256(prBodyBytes)),
                context.instance().startedAt() == null ? Instant.now() : context.instance().startedAt()
        );
        var published = candidateWriter.publish(paths, candidate, Map.of(
                "merge.patch", patchBytes,
                "commit-message.txt", commitBytes,
                "pr-body.md", prBodyBytes
        ));
        restoreStableProjections(paths, candidate);
        return result(paths, published);
    }

    private NodeResult result(WorkstreamPaths paths, DeliveryCandidateWriter.Published published) {
        var stableCommitRef = workspaceRef(paths.workspaceRoot(), paths.deliveryDir().resolve("commit-message.txt"));
        var stablePrBodyRef = workspaceRef(paths.workspaceRoot(), paths.deliveryDir().resolve("pr-body.md"));
        var result = new LinkedHashMap<String, Object>();
        result.put("commit_message_path", stableCommitRef);
        result.put("pr_body_path", stablePrBodyRef);
        result.put("delivery_candidate_ref", published.ref());
        result.put("delivery_candidate_sha256", published.sha256());
        result.put("expected_result_tree", published.document().expectedResultTree());
        result.put("prepared_at", published.document().createdAt().toString());
        return NodeResult.completed(
                "completed",
                List.of(stableCommitRef, stablePrBodyRef, published.ref()),
                result
        );
    }

    private SourceIdentity sourceIdentity(WorkstreamPaths paths, Path workspaceRoot) throws IOException {
        if (!Files.isRegularFile(paths.workstreamJson())) {
            throw new IOException("workstream identity is missing: " + paths.workstreamJson());
        }
        var workstream = objectMapper.readValue(paths.workstreamJson().toFile(), WorkstreamDocument.class);
        if (workstream.primaryWorkspaceId() == null || workstream.primaryWorkspaceId().isBlank()) {
            throw new IOException("workstream primary workspace identity is missing");
        }
        var workspacePath = paths.workspaceJson(new DualId(workstream.primaryWorkspaceId()));
        if (!Files.isRegularFile(workspacePath)) {
            throw new IOException("workspace identity is missing: " + workspacePath);
        }
        var workspace = objectMapper.readValue(workspacePath.toFile(), WorkspaceDocument.class);
        var effective = Path.of(workspace.effectiveWorkdir()).toAbsolutePath().normalize();
        if (!workspace.workstreamId().equals(workstream.workstreamId())
                || !workspace.workspaceId().equals(workstream.primaryWorkspaceId())
                || !effective.equals(workspaceRoot.toAbsolutePath().normalize())) {
            throw new IOException("delivery source workspace identity does not match the execution workspace");
        }
        return new SourceIdentity(workspace.workspaceId(), effective.toString());
    }

    private void restoreStableProjections(WorkstreamPaths paths, DeliveryCandidateDocument candidate) throws IOException {
        Files.createDirectories(paths.deliveryDir());
        Files.copy(resolveRef(paths.workspaceRoot(), candidate.commitMessage().ref()),
                paths.deliveryDir().resolve("commit-message.txt"), java.nio.file.StandardCopyOption.REPLACE_EXISTING);
        Files.copy(resolveRef(paths.workspaceRoot(), candidate.prBody().ref()),
                paths.deliveryDir().resolve("pr-body.md"), java.nio.file.StandardCopyOption.REPLACE_EXISTING);
    }

    private static String renderCommitMessage(String workstreamId, Path workstreamDir) throws IOException {
        var summary = firstNonBlankLine(readOrDefault(workstreamDir.resolve("requirement.md"), "Dual agent task"));
        return """
                feat: dual agent task %s

                %s

                Run report: .agent/workstreams/%s/reports/latest-final-report.md
                """.formatted(workstreamId, summary, workstreamId);
    }

    private static String renderPrBody(TaskContext context, Path workstreamDir) throws IOException {
        var builder = new StringBuilder();
        builder.append("# Dual Agent Run PR\n\n");
        builder.append("- Workstream: ").append(context.workstreamId()).append("\n");
        builder.append("- Generated At: ").append(Instant.now()).append("\n");
        builder.append("- Final Report: .agent/workstreams/")
                .append(context.workstreamId()).append("/reports/latest-final-report.md\n\n");
        builder.append("## User Request\n\n")
                .append(readOrDefault(workstreamDir.resolve("requirement.md"), "(requirement.md not found)"))
                .append("\n\n");
        builder.append("## Summary\n\n")
                .append(snippet(readOrDefault(workstreamDir.resolve("reports/latest-final-report.md"), "(final report not generated)")))
                .append("\n\n");
        builder.append("## Verification\n\n")
                .append(readEvidenceFile(workstreamDir, "diff.stat", "(diff stat not available)"))
                .append("\n\n");
        builder.append("## Codex Final Acceptance\n\n")
                .append("See the typed acceptance evidence summarized in the final report.\n\n");
        builder.append("## Changed Files\n\n").append(readChangedFiles(workstreamDir)).append("\n\n");
        builder.append("## Run Artifacts\n\n")
                .append("- Final report: .agent/workstreams/").append(context.workstreamId()).append("/reports/latest-final-report.md\n")
                .append("- Git evidence: .agent/workstreams/").append(context.workstreamId()).append("/artifacts/git-evidence/\n")
                .append("- Events: .agent/workstreams/").append(context.workstreamId()).append("/events.jsonl\n")
                .append("- Runs: .agent/workstreams/").append(context.workstreamId()).append("/runs/\n\n")
                .append("## Risks / Notes\n\nReview the final acceptance evidence and immutable delivery candidate before merging.\n");
        return builder.toString();
    }

    private static String readChangedFiles(Path workstreamDir) throws IOException {
        var changed = readEvidenceFile(workstreamDir, "changed-files.txt", "");
        if (changed.isBlank()) return "(no changed files recorded)";
        var builder = new StringBuilder();
        for (var line : changed.split("\\R")) {
            if (!line.isBlank()) builder.append("- ").append(line.trim()).append("\n");
        }
        return builder.toString().stripTrailing();
    }

    private static String readEvidenceFile(Path workstreamDir, String fileName, String fallback) throws IOException {
        return readOrDefault(workstreamDir.resolve("artifacts/git-evidence").resolve(fileName), fallback);
    }

    private static String readOrDefault(Path path, String fallback) throws IOException {
        return Files.exists(path) ? Files.readString(path, StandardCharsets.UTF_8).stripTrailing() : fallback;
    }

    private static String firstNonBlankLine(String text) {
        return text.lines().map(String::trim).filter(line -> !line.isBlank()).findFirst().orElse("Dual agent task");
    }

    private static String snippet(String content) {
        return content.length() <= MAX_SECTION_CHARS
                ? content
                : content.substring(0, MAX_SECTION_CHARS).stripTrailing() + "\n\n[truncated]";
    }

    private static String workspaceRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize().relativize(path.toAbsolutePath().normalize()).toString();
    }

    private static Path resolveRef(Path workspaceRoot, String ref) throws IOException {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var path = root.resolve(ref).normalize();
        if (!path.startsWith(root)) throw new IOException("delivery artifact ref escapes workspace: " + ref);
        return path;
    }

    private record SourceIdentity(String workspaceId, String effectiveWorkdir) {
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.contract.TaskContract;
import dev.dual.core.contract.TaskContractValidator;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;

/** Checks declared file scope, never business relevance or actual Git changes. */
final class DesignScopeValidator {
    private DesignScopeValidator() {
    }

    static List<String> shapeErrors(AgentResultEnvelope.Design design) {
        if (design == null || design.plannedFiles() == null) {
            return List.of("DESIGN_SCOPE_MISSING: result.design.planned_files is required");
        }
        var errors = new ArrayList<String>();
        var paths = new HashSet<String>();
        for (var file : design.plannedFiles()) {
            if (file == null) {
                errors.add("DESIGN_SCOPE_ENTRY_INVALID: null entry");
                continue;
            }
            if (!TaskContractValidator.isCanonicalPath(file.path())) {
                errors.add("DESIGN_SCOPE_PATH_INVALID: " + file.path());
            }
            if (!paths.add(file.path())) {
                errors.add("DESIGN_SCOPE_PATH_DUPLICATE: " + file.path());
            }
            if (file.operation() == null) {
                errors.add("DESIGN_SCOPE_OPERATION_MISSING: " + file.path());
            }
            if (file.responsibility() == null || file.responsibility().isBlank()) {
                errors.add("DESIGN_SCOPE_RESPONSIBILITY_MISSING: " + file.path());
            }
        }
        return List.copyOf(errors);
    }

    static List<String> validate(Path root, String workstreamId, AgentResultEnvelope.Design design) {
        var errors = shapeErrors(design);
        if (!errors.isEmpty()) {
            return errors;
        }
        var resolution = TaskContractProjectionVerifier.resolve(root, workstreamId);
        if (resolution.failure() != null || resolution.qualified().isEmpty()) {
            return List.of("DESIGN_CONTRACT_NOT_QUALIFIED: " + (resolution.failure() == null
                    ? "approved contract is absent" : resolution.failure().reason()));
        }
        return scopeErrors(design, resolution.qualified().orElseThrow().contract());
    }

    private static List<String> scopeErrors(AgentResultEnvelope.Design design, TaskContract contract) {
        var errors = new ArrayList<String>();
        for (var file : design.plannedFiles()) {
            var authorized = contract.scope().included().stream()
                    .filter(entry -> entry.path().equals(file.path())).findFirst();
            if (authorized.isEmpty()) {
                errors.add("DESIGN_SCOPE_NOT_AUTHORIZED: " + file.path());
            } else if (authorized.get().operation() != file.operation()) {
                errors.add("DESIGN_SCOPE_OPERATION_MISMATCH: " + file.path());
            }
        }
        return List.copyOf(errors);
    }
}

package dev.dual.runtime.handler;

import java.time.Duration;

/**
 * Resolves the stale-attempt timeout policy for {@link AgentExecutionAttemptReconciler}.
 *
 * <p>Centralizes environment parsing so {@code WorkflowRuntime} injects a concrete
 * {@link Duration} and the reconciler never reads configuration directly. A
 * live-but-no-progress run is reconciled to TIMEOUT once it exceeds this boundary;
 * a dead pid is reconciled to INTERRUPTED immediately and is not gated by this
 * timeout.
 *
 * <p>The default (8 minutes) matches the real-case stop-loss semantics already used
 * for "single run unexpected long wait". Operators may override it with the
 * {@code DUAL_STALE_ATTEMPT_TIMEOUT_MS} environment variable (positive milliseconds).
 */
public final class AgentExecutionAttemptTimeoutPolicy {
    public static final String ENV = "DUAL_STALE_ATTEMPT_TIMEOUT_MS";
    static final Duration DEFAULT_TIMEOUT = Duration.ofMinutes(8);

    private final Duration timeout;
    private final String source;

    public AgentExecutionAttemptTimeoutPolicy() {
        this(System.getenv(ENV));
    }

    AgentExecutionAttemptTimeoutPolicy(String raw) {
        Duration parsed = parse(raw);
        if (parsed == null) {
            this.timeout = DEFAULT_TIMEOUT;
            this.source = "default";
        } else {
            this.timeout = parsed;
            this.source = "env:" + ENV;
        }
    }

    public Duration timeout() {
        return timeout;
    }

    public String source() {
        return source;
    }

    private static Duration parse(String raw) {
        if (raw == null || raw.isBlank()) {
            return null;
        }
        try {
            long ms = Long.parseLong(raw.trim());
            if (ms <= 0) {
                return null;
            }
            return Duration.ofMillis(ms);
        } catch (NumberFormatException ignored) {
            return null;
        }
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.arbitration.FailureClassification;
import dev.dual.core.arbitration.FailureCategory;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * TaskHandler that classifies acceptance review failures using FailureArbiter.
 * Type: "acceptance.failure_classify"
 *
 * Reads TaskContract and ledger-routed acceptance evidence,
 * runs FailureArbiter, and writes failure-classification.json.
 * Produces compound outcome strings: REJECT_{CATEGORY}.
 */
public final class FailureClassifyHandler implements TaskHandler {

    private final FailureArbiter arbiter = new FailureArbiter();
    private final ObjectMapper objectMapper = new ObjectMapper().registerModule(new JavaTimeModule());

    @Override
    public String type() {
        return "acceptance.failure_classify";
    }

    @Override
    public NodeResult execute(TaskContext context) throws IOException {
        var workstreamDir = context.workspaceRoot()
                .resolve(".agent/workstreams").resolve(context.workstreamId());

        TaskContractProjectionVerifier.QualifiedTaskContract qualified = null;
        if (AgentRunGovernanceContext.requiresApprovedTaskContract(context)) {
            var resolution = TaskContractProjectionVerifier.resolve(context.workspaceRoot(), context.workstreamId());
            if (resolution.failure() != null || resolution.qualified().isEmpty()) {
                var failure = resolution.failure() == null
                        ? TaskContractProjectionVerifier.Failure.of(
                                "APPROVAL_BINDING_MISSING", "failure classification requires an approved task contract")
                        : resolution.failure();
                return qualificationFailure(failure);
            }
            qualified = resolution.qualified().orElseThrow();
        } else {
            var legacy = TaskContractProjectionVerifier.readLegacyProjection(
                    context.workspaceRoot(), context.workstreamId());
            if (legacy.failure() != null) {
                throw new IOException(legacy.failure().message());
            }
        }

        var evidenceRead = AgentEvidenceIndex.latestDecisionFromRefs(context.workspaceRoot(),
                context.workstreamId(), context.instance().inputRefs(), objectMapper);
        if (evidenceRead.entry() == null) {
            var missing = evidenceRead.missing();
            return failedEvidence(
                    missing ? "MISSING_CONTRACT_SIDECAR" : "INVALID_CONTRACT_SIDECAR",
                    missing
                            ? "No acceptance contract sidecar found in failure-classification input refs."
                            : evidenceRead.message(),
                    context,
                    evidenceRead
            );
        }

        var reviewMetadata = evidenceRead.entry().document();
        if (!"acceptance_review".equals(reviewMetadata.sourceArtifactType())) {
            return new NodeResult("ACCEPTANCE_CLASSIFICATION_INVALID", NodeStatus.FAILED, List.of(),
                    Map.of("reason", "ACCEPTANCE_CLASSIFICATION_INVALID"), "An acceptance_review sidecar is required");
        }
        var semanticViolation = AgentContractSemantics.validateOutputContract(reviewMetadata);
        if (semanticViolation.isPresent()) {
            var invalid = semanticViolation.get();
            return new NodeResult(invalid.errorCode(), NodeStatus.FAILED, List.of(),
                    Map.of("reason", invalid.errorCode(), "error", invalid.message()), invalid.message());
        }
        var reviewDecision = reviewMetadata.decision();
        if (!"REJECT".equals(reviewDecision)) {
            return failedDecision(reviewDecision, context, evidenceRead.entry().path());
        }
        var stageOutcome = reviewMetadata.canonicalStageOutcome().isBlank()
                ? StageOutcome.fromDecision(reviewDecision).name()
                : reviewMetadata.canonicalStageOutcome();
        var failure = reviewMetadata.failure();

        final FailureCategory category;
        try {
            category = FailureCategory.valueOf(failure.categoryHint());
        } catch (IllegalArgumentException invalid) {
            return new NodeResult("ACCEPTANCE_CLASSIFICATION_INVALID", NodeStatus.FAILED, List.of(),
                    Map.of("reason", "ACCEPTANCE_CLASSIFICATION_INVALID"), "Canonical acceptance category is required");
        }
        var supportingEvidence = new ArrayList<String>();
        supportingEvidence.addAll(failure.contractGaps());
        supportingEvidence.addAll(reviewMetadata.mustFix());
        supportingEvidence.addAll(failure.outOfScopeFiles());
        supportingEvidence.addAll(failure.missingTests());
        supportingEvidence.addAll(reviewMetadata.missingEvidence());
        supportingEvidence.addAll(failure.contextGaps());
        if (!failure.reason().isBlank()) supportingEvidence.add(failure.reason());
        var classification = arbiter.classify(category, supportingEvidence);
        Map<String, Object> baseline = Map.of();
        if (category == FailureCategory.CONTRACT_GAP || category == FailureCategory.CONTRACT_AMBIGUITY) {
            try {
                if (qualified == null) throw new IOException("contract repair requires a qualified contract");
                baseline = TaskContractRevisionContextResolver.captureAcceptanceReworkBaseline(
                        context.workspaceRoot(), context.workstreamId(), qualified, evidenceRead.entry());
            } catch (IOException invalid) {
                return new NodeResult("ACCEPTANCE_REWORK_BASELINE_INVALID", NodeStatus.FAILED, List.of(),
                        Map.of("reason", "ACCEPTANCE_REWORK_BASELINE_INVALID", "error", invalid.getMessage()),
                        invalid.getMessage());
            }
        }

        var artifactsDir = workstreamDir.resolve("artifacts");
        Files.createDirectories(artifactsDir);
        var classificationPath = artifactsDir.resolve("failure-classification.json");
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(classificationPath.toFile(), classification);

        var outcome = "REJECT_" + classification.category().name();

        var classificationRef = ".agent/workstreams/" + context.workstreamId()
                + "/artifacts/failure-classification.json";
        var outputRefs = new ArrayList<String>();
        outputRefs.add(context.workspaceRoot().toAbsolutePath().normalize()
                .relativize(evidenceRead.entry().path()).toString());
        outputRefs.add(classificationRef);
        var result = new LinkedHashMap<String, Object>();
        result.putAll(baseline);
        result.put("category", classification.category().name());
        result.put("reasoning", classification.reasoning());
        result.put("suggested_action", classification.suggestedAction());
        result.put("matched_rule", classification.matchedRule());
        result.put("review_decision", reviewDecision);
        result.put("stage_outcome", stageOutcome);
        result.put("classification_ref", classificationRef);

        var candidateRef = writeCalibrationCandidateIfNeeded(
                context, workstreamDir, classification, classificationRef, stageOutcome);
        if (candidateRef != null) {
            outputRefs.add(candidateRef);
            result.put("calibration_candidate_ref", candidateRef);
        }

        var summaryRef = writeCurrentFailureSummary(
                context, workstreamDir, classification, classificationRef, candidateRef, stageOutcome);
        outputRefs.add(summaryRef);
        result.put("failure_summary_ref", summaryRef);

        return NodeResult.completed(outcome, outputRefs, result);
    }

    private NodeResult qualificationFailure(TaskContractProjectionVerifier.Failure failure) {
        return new NodeResult(
                TaskContractProjectionVerifier.FAILURE_OUTCOME,
                NodeStatus.FAILED,
                List.of(),
                Map.of(
                        "failure_code", TaskContractProjectionVerifier.FAILURE_OUTCOME,
                        "reason", failure.reason(),
                        "error", failure.message()),
                failure.message());
    }

    private NodeResult failedEvidence(String outcome, String message, TaskContext context,
                                      AgentEvidenceIndex.DecisionRead read) {
        var parseError = read.errorCode().isBlank()
                ? Map.of()
                : Map.of(
                    "code", read.errorCode(),
                    "message", read.message(),
                    "path", read.path()
                );
        return new NodeResult(outcome, NodeStatus.FAILED, List.of(), Map.of(
                "reason", outcome,
                "message", message,
                "input_refs", context.instance().inputRefs(),
                "parse_error", parseError
        ), message);
    }

    private NodeResult failedDecision(String decision, TaskContext context, Path sidecarPath) {
        var outcome = "ACCEPTANCE_CLASSIFICATION_NOT_REQUIRED";
        var message = "Failure classification requires a REJECT acceptance decision, but received: " + decision;
        return new NodeResult(outcome, NodeStatus.FAILED, List.of(), Map.of(
                "reason", outcome,
                "message", message,
                "review_decision", decision,
                "input_refs", context.instance().inputRefs(),
                "acceptance_sidecar", context.workspaceRoot().toAbsolutePath().normalize()
                        .relativize(sidecarPath).toString()
        ), message);
    }


    private String writeCalibrationCandidateIfNeeded(
            TaskContext context,
            Path workstreamDir,
            FailureClassification classification,
            String classificationRef,
            String stageOutcome
    ) throws IOException {
        var updateType = proposedUpdateType(classification.category());
        if (updateType == null) {
            return null;
        }

        var candidateId = context.instance().nodeInstanceId() + "-"
                + classification.category().name().toLowerCase().replace('_', '-');
        var candidatesDir = workstreamDir.resolve("calibration").resolve("candidates");
        Files.createDirectories(candidatesDir);

        var jsonRef = ".agent/workstreams/" + context.workstreamId()
                + "/calibration/candidates/" + candidateId + ".json";
        var mdRef = ".agent/workstreams/" + context.workstreamId()
                + "/calibration/candidates/" + candidateId + ".md";

        var candidate = new LinkedHashMap<String, Object>();
        candidate.put("schemaVersion", 1);
        candidate.put("candidateId", candidateId);
        candidate.put("sourceWorkstreamId", context.workstreamId());
        candidate.put("sourceNodeId", context.instance().nodeDefinitionId());
        candidate.put("failureCategory", classification.category().name());
        candidate.put("reviewDecision", classification.reviewDecision());
        candidate.put("stageOutcome", stageOutcome);
        candidate.put("matchedRule", classification.matchedRule());
        candidate.put("proposedUpdateType", updateType);
        candidate.put("reasoning", classification.reasoning());
        candidate.put("suggestedAction", classification.suggestedAction());
        candidate.put("evidenceRefs", List.of(classificationRef));
        candidate.put("status", "DRAFT");

        objectMapper.writerWithDefaultPrettyPrinter()
                .writeValue(candidatesDir.resolve(candidateId + ".json").toFile(), candidate);
        Files.writeString(candidatesDir.resolve(candidateId + ".md"),
                renderCalibrationCandidateMarkdown(candidate, mdRef), StandardCharsets.UTF_8);
        return jsonRef;
    }

    private String proposedUpdateType(FailureCategory category) {
        return switch (category) {
            case CONTRACT_GAP, CONTRACT_AMBIGUITY -> "CONTRACT_TEMPLATE";
            case CONTEXT_INSUFFICIENT -> "CONTEXT_RULE";
            case IMPLEMENTATION_BUG -> "REGRESSION_TEST";
            case VERIFICATION_INSUFFICIENT -> null;
            case TOOL_LIMITATION, REVIEW_NOISE -> null;
        };
    }

    private String renderCalibrationCandidateMarkdown(Map<String, Object> candidate, String mdRef) {
        return """
                # Calibration Candidate

                - Candidate: %s
                - Status: %s
                - Failure Category: %s
                - Proposed Update Type: %s
                - Review Decision: %s
                - Stage Outcome: %s
                - Source Node: %s

                ## Reasoning

                %s

                ## Suggested Action

                %s

                ## Artifact

                %s
                """.formatted(
                candidate.get("candidateId"),
                candidate.get("status"),
                candidate.get("failureCategory"),
                candidate.get("proposedUpdateType"),
                candidate.get("reviewDecision"),
                candidate.get("stageOutcome"),
                candidate.get("sourceNodeId"),
                candidate.get("reasoning"),
                candidate.get("suggestedAction"),
                mdRef
        );
    }

    private String writeCurrentFailureSummary(
            TaskContext context,
            Path workstreamDir,
            FailureClassification classification,
            String classificationRef,
            String candidateRef,
            String stageOutcome
    ) throws IOException {
        var recoveryDir = workstreamDir.resolve("recovery");
        Files.createDirectories(recoveryDir);
        var summaryRef = ".agent/workstreams/" + context.workstreamId()
                + "/recovery/current-failure.md";
        var candidateLine = candidateRef == null ? "- Calibration Candidate: N/A\n"
                : "- Calibration Candidate: " + candidateRef + "\n";
        var content = """
                # Current Failure

                - Node: %s
                - Decision: %s
                - Stage Outcome: %s
                - Category: %s
                - Matched Rule: %d
                - Classification: %s
                %s
                ## Reasoning

                %s

                ## Suggested Action

                %s
                """.formatted(
                context.instance().nodeDefinitionId(),
                classification.reviewDecision(),
                stageOutcome,
                classification.category().name(),
                classification.matchedRule(),
                classificationRef,
                candidateLine,
                classification.reasoning(),
                classification.suggestedAction()
        );
        Files.writeString(recoveryDir.resolve("current-failure.md"), content, StandardCharsets.UTF_8);
        return summaryRef;
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.execution.ArtifactContractResult;
import dev.dual.core.execution.AgentResultContractResult;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class AgentExecutionResultFacts {
    static final String AGENT_RESULT_CONTRACT = "agent_execution_result_contract";
    static final String ARTIFACT_CONTRACT_RESULTS = "agent_execution_artifact_contract_results";
    static final String REREAD_REASONS = "reread_reasons";

    private AgentExecutionResultFacts() {
    }

    /** Closed, machine-owned input rejection. No provider result or arbitrary metadata can enter here. */
    public static NodeResult inputPreparationFailed(String reason, String code, List<String> details) {
        if (reason == null || reason.isBlank() || code == null || code.isBlank()
                || details == null || details.isEmpty()) {
            throw new IllegalArgumentException("input rejection requires reason, code and details");
        }
        var errors = List.copyOf(details);
        return new NodeResult(reason, NodeStatus.FAILED, List.of(), Map.of(
                "reason", reason, "failure_code", code, "errors", errors,
                "input_preparation_failure", Map.of("reason", reason, "code", code, "details", errors,
                        "providerInvoked", false, "retryPolicy", "MANUAL_ONLY")), String.join("; ", errors));
    }

    /** Reject contradictory facts instead of letting a phase marker become a publication bypass. */
    static boolean inputPreparationFailed(NodeResult result) {
        if (!result.result().containsKey("input_preparation_failure")) return false;
        if (!(result.result().get("input_preparation_failure") instanceof Map<?, ?> failure)
                || !(failure.get("reason") instanceof String reason)
                || !(failure.get("code") instanceof String code)
                || !(failure.get("details") instanceof List<?> details)
                || details.stream().anyMatch(item -> !(item instanceof String))) {
            throw new IllegalArgumentException("invalid input preparation failure fact");
        }
        var expected = inputPreparationFailed(reason, code, details.stream().map(String.class::cast).toList());
        if (!expected.equals(result)) {
            throw new IllegalArgumentException("input preparation failure contradicts node result or execution evidence");
        }
        return true;
    }

    /** Carry an acquisition rejection to publication using the existing terminal contract fact. */
    public static NodeResult rejectAgentResult(NodeResult result, String message) {
        return attach(new NodeResult("AGENT_OUTPUT_CONTRACT_VIOLATION", NodeStatus.FAILED,
                        result.outputRefs(), result.result(), message),
                AgentResultContractResult.invalid(message), List.of(), null);
    }

    static NodeResult attach(
            NodeResult result,
            AgentResultContractResult agentResultContract,
            List<ArtifactContractResult> artifactContractResults,
            Object rereadReasons
    ) {
        var facts = new LinkedHashMap<String, Object>();
        facts.putAll(result.result());
        facts.put(AGENT_RESULT_CONTRACT, agentResultContractToMap(agentResultContract));
        facts.put(ARTIFACT_CONTRACT_RESULTS, artifactContractResults.stream()
                .map(AgentExecutionResultFacts::artifactContractToMap)
                .toList());
        if (rereadReasons != null) {
            facts.put(REREAD_REASONS, rereadReasons);
        }
        return new NodeResult(result.outcome(), result.status(), result.outputRefs(), facts, result.errorMessage());
    }

    static AgentResultContractResult agentResultContract(NodeResult result) {
        var value = result.result().get(AGENT_RESULT_CONTRACT);
        if (value instanceof Map<?, ?> map) {
            return new AgentResultContractResult(
                    booleanValue(map.get("present")),
                    booleanValue(map.get("valid")),
                    text(map.get("decision")),
                    text(map.get("summary")),
                    text(map.get("validationError"))
            );
        }
        return AgentResultContractResult.missing();
    }

    static List<ArtifactContractResult> artifactContractResults(NodeResult result) {
        var value = result.result().get(ARTIFACT_CONTRACT_RESULTS);
        if (!(value instanceof List<?> list)) {
            return List.of();
        }
        var results = new ArrayList<ArtifactContractResult>();
        for (var item : list) {
            if (item instanceof Map<?, ?> map) {
                results.add(new ArtifactContractResult(
                        text(map.get("contractType")),
                        booleanValue(map.get("required")),
                        booleanValue(map.get("present")),
                        booleanValue(map.get("valid")),
                        text(map.get("path")),
                        text(map.get("errorCode")),
                        text(map.get("errorMessage"))
                ));
            }
        }
        return List.copyOf(results);
    }

    static Object rereadReasons(NodeResult result) {
        return result.result().get(REREAD_REASONS);
    }

    static boolean present(NodeResult result) {
        return result.result().containsKey(AGENT_RESULT_CONTRACT)
                || result.result().containsKey(ARTIFACT_CONTRACT_RESULTS)
                || (result.result().containsKey("run_metadata")
                && result.result().containsKey("process_usability"));
    }

    static Map<String, Object> agentResultContractToMap(AgentResultContractResult result) {
        var map = new LinkedHashMap<String, Object>();
        map.put("present", result.present());
        map.put("valid", result.valid());
        map.put("decision", result.decision());
        map.put("summary", result.summary());
        map.put("validationError", result.validationError());
        return map;
    }

    static Map<String, Object> artifactContractToMap(ArtifactContractResult artifact) {
        var map = new LinkedHashMap<String, Object>();
        map.put("contractType", artifact.contractType());
        map.put("required", artifact.required());
        map.put("present", artifact.present());
        map.put("valid", artifact.valid());
        map.put("path", artifact.path());
        map.put("errorCode", artifact.errorCode());
        map.put("errorMessage", artifact.errorMessage());
        return map;
    }

    private static boolean booleanValue(Object value) {
        return value instanceof Boolean bool && bool;
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }
}

package dev.dual.runtime.handler;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;

/**
 * Compiles Agent-proposed status fields into a canonical stage outcome.
 *
 * This is the orchestration boundary between "the LLM said X" and "the
 * workflow may route as Y". Rules here are intentionally mechanical. A future
 * semantic judge can add recommendations, but the final canonical outcome must
 * still be produced by this compiler and recorded in the sidecar.
 */
final class StageOutcomeCompiler {
    private StageOutcomeCompiler() {
    }

    static StageOutcomeCompilation compile(String decision, String declaredStatus) {
        var derived = StageOutcome.fromDecision(decision);
        if (declaredStatus == null || declaredStatus.isBlank()) {
            return StageOutcomeCompilation.valid(derived, "decision");
        }
        var declared = StageOutcome.fromText(declaredStatus);
        if (declared == StageOutcome.UNKNOWN) {
            return StageOutcomeCompilation.invalid(
                    derived,
                    "STRUCTURED_ARTIFACT_UNKNOWN_STATUS",
                    "structured artifact lifecycle_status is not recognized: " + declaredStatus
            );
        }
        if (declared == derived) {
            return StageOutcomeCompilation.valid(declared, "declared_status");
        }
        if (derived == StageOutcome.REJECTED && declared == StageOutcome.INSUFFICIENT_EVIDENCE) {
            return StageOutcomeCompilation.valid(declared, "declared_status");
        }
        return StageOutcomeCompilation.invalid(
                derived,
                "STRUCTURED_ARTIFACT_STATUS_MISMATCH",
                "structured artifact lifecycle_status " + declared
                        + " conflicts with decision " + decision
        );
    }

    static void addSidecarFields(Map<String, Object> sidecar) {
        var declared = text(sidecar.get("lifecycle_status"));
        var compilation = compile(text(sidecar.get("decision")), declared);
        var outcome = compilation.outcome();
        var evidenceState = AgentEvidenceState.fromSidecar(sidecar);
        sidecar.put("stage_outcome", outcome.name());
        sidecar.put("stage_outcome_source", compilation.source());
        sidecar.put("lifecycle_status", outcome.name());
        sidecar.put("evidence_state", evidenceState.toMap());
    }

    static Optional<ContractViolation> validateEvidenceContract(
            String expectedType,
            String decision,
            String declaredStatus,
            AgentEvidenceState evidenceState,
            AgentOutputContractDocument.FailureFields failure
    ) {
        var compilation = compile(decision, declaredStatus);
        if (!compilation.valid()) {
            return violation(expectedType, compilation.errorCode(), compilation.message());
        }
        var outcome = compilation.outcome();
        if (outcome == StageOutcome.READY
                && evidenceState.hasBlockingDecisionIssues()) {
            return violation(
                    expectedType,
                    "POSITIVE_STATUS_EVIDENCE_CONFLICT",
                    "decision " + decision + " cannot include blocking=true or must_fix"
            );
        }
        if (outcome == StageOutcome.ACCEPTED
                && evidenceState.hasFinalAcceptanceConflicts()) {
            return violation(
                    expectedType,
                    "FINAL_ACCEPTANCE_EVIDENCE_CONFLICT",
                    "decision " + decision + " cannot include blocking=true, must_fix, or missing_evidence"
            );
        }
        if (outcome == StageOutcome.ACCEPTED_WITH_NOTES
                && evidenceState.hasBlockingDecisionIssues()) {
            return violation(
                    expectedType,
                    "NOTES_STATUS_BLOCKING_CONFLICT",
                    "decision " + decision + " cannot include blocking=true or must_fix; use REJECT for blocking issues"
            );
        }
        if ((outcome == StageOutcome.NEEDS_REVISION
                || outcome == StageOutcome.BLOCKED
                || outcome == StageOutcome.REJECTED
                || outcome == StageOutcome.INSUFFICIENT_EVIDENCE)
                && !evidenceState.hasBlockingIssues()
                && failure.isEmpty()) {
            return violation(
                    expectedType,
                    "NEGATIVE_STATUS_MISSING_EVIDENCE",
                    "decision " + decision + " must include blocking=true, must_fix, missing_evidence, or failure reason"
            );
        }
        return Optional.empty();
    }

    private static Optional<ContractViolation> violation(
            String expectedType,
            String code,
            String message
    ) {
        return Optional.of(ContractViolation.of(
                "STRUCTURED_ARTIFACT_SEMANTIC_VIOLATION",
                code + ": " + message,
                Map.of("required_artifact_type", expectedType, "semantic_code", code)
        ));
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    record StageOutcomeCompilation(
            StageOutcome outcome,
            String source,
            boolean valid,
            String errorCode,
            String message
    ) {
        static StageOutcomeCompilation valid(StageOutcome outcome, String source) {
            return new StageOutcomeCompilation(outcome, source, true, "", "");
        }

        static StageOutcomeCompilation invalid(StageOutcome fallback, String errorCode, String message) {
            return new StageOutcomeCompilation(fallback, "invalid", false, errorCode, message);
        }

        Map<String, Object> toMap() {
            var map = new LinkedHashMap<String, Object>();
            map.put("outcome", outcome.name());
            map.put("source", source);
            map.put("valid", valid);
            if (!errorCode.isBlank()) {
                map.put("error_code", errorCode);
                map.put("message", message);
            }
            return map;
        }
    }
}

