package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeInstance;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowDefinition;
import dev.dual.ledger.file.GoalDomainOutcome;
import dev.dual.ledger.file.GoalSatisfactionDocument;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkflowDefinitionDocument;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkflowInstanceDocument;
import dev.dual.ledger.file.WorkstreamPaths;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** Resolves final completion evidence exclusively through persisted ledger lineage. */
public final class CompletionEvidenceLineageResolver {
    public static final String GOAL_NOT_CONFIGURED = "COMPLETION_GOAL_NOT_CONFIGURED";
    public static final String GOAL_NOT_FINAL = "COMPLETION_GOAL_NOT_FINAL";
    public static final String GOAL_INVALID = "COMPLETION_GOAL_INVALID";
    public static final String ACCEPTANCE_INVALID = "COMPLETION_ACCEPTANCE_LINEAGE_INVALID";
    public static final String CONTEXT_INVALID = "COMPLETION_CONTEXT_LINEAGE_INVALID";
    public static final String SELF_TEST_INVALID = "COMPLETION_SELF_TEST_LINEAGE_INVALID";

    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper().registerModule(new JavaTimeModule())
            .registerModule(new dev.dual.ledger.file.EdgeConditionModule());

    private CompletionEvidenceLineageResolver() {
    }

    public static Resolution resolveCurrent(Path workspaceRoot, String workstreamId) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var paths = new WorkstreamPaths(root, new DualId(workstreamId));
        if (!Files.isRegularFile(paths.goalSatisfactionJson())) {
            return Resolution.notConfigured("goal satisfaction document is not configured");
        }
        try {
            var goal = OBJECT_MAPPER.readValue(paths.goalSatisfactionJson().toFile(), GoalSatisfactionDocument.class);
            if (!workstreamId.equals(goal.workstreamId())) {
                return Resolution.invalid(GOAL_INVALID, "goal workstream_id does not match", goal);
            }
            var ledger = new WorkflowFileLedger();
            var current = ledger.loadCurrent(paths);
            var instance = OBJECT_MAPPER.readValue(paths.workflowInstanceJson().toFile(), WorkflowInstanceDocument.class);
            var definitionDocument = OBJECT_MAPPER.readValue(
                    paths.workflowDefinitionJson().toFile(), WorkflowDefinitionDocument.class);
            var definition = new WorkflowDefinition(
                    definitionDocument.workflowId(),
                    definitionDocument.version(),
                    definitionDocument.entryNodeId(),
                    definitionDocument.nodes(),
                    definitionDocument.edges());
            if (!goal.workflowInstanceId().equals(current.workflowInstanceId())
                    || !goal.workflowInstanceId().equals(instance.workflowInstanceId())
                    || !current.workflowId().equals(definition.workflowId())
                    || current.definitionVersion() != definition.version()
                    || !instance.workflowId().equals(definition.workflowId())
                    || instance.definitionVersion() != definition.version()) {
                return Resolution.invalid(GOAL_INVALID, "goal workflow identity does not match persisted workflow", goal);
            }
            if (!"acceptance.decision".equals(goal.nodeDefinitionId())
                    || !Set.of(GoalDomainOutcome.SATISFIED, GoalDomainOutcome.SATISFIED_WITH_NOTES)
                    .contains(goal.domainOutcome())) {
                return Resolution.notFinal(goal, "current goal is not a final satisfied acceptance");
            }

            var decisionNode = ledger.loadNode(paths, goal.nodeInstanceId());
            var decisionViolation = decisionViolation(goal, decisionNode);
            if (!decisionViolation.isBlank()) {
                return Resolution.invalid(GOAL_INVALID, decisionViolation, goal);
            }

            var acceptance = acceptanceEvidence(root, workstreamId, paths, definition, goal, decisionNode);
            if (acceptance.failure() != null) {
                return Resolution.invalid(ACCEPTANCE_INVALID, acceptance.failure(), goal);
            }
            var context = contextNode(root, workstreamId, paths, definition, goal, acceptance.evidence());
            if (context.failure() != null) {
                return Resolution.invalid(CONTEXT_INVALID, context.failure(), goal);
            }
            var selfTest = selfTestEvidence(
                    root, workstreamId, paths, definition, goal, context.node(), context.definitionConfig());
            if (selfTest.failure() != null) {
                return Resolution.invalid(SELF_TEST_INVALID, selfTest.failure(), goal);
            }
            return Resolution.available(goal, decisionNode, context.node(), acceptance.evidence(), selfTest.evidence());
        } catch (Exception e) {
            return Resolution.invalid(GOAL_INVALID, "completion evidence cannot be resolved: " + e.getMessage(), null);
        }
    }

    public static Resolution resolveForReport(
            Path workspaceRoot,
            String workstreamId,
            NodeInstance reportNode
    ) {
        var resolution = resolveCurrent(workspaceRoot, workstreamId);
        if (resolution.status() != Status.AVAILABLE) {
            return resolution;
        }
        if (!"acceptance.generate_final_report".equals(reportNode.nodeDefinitionId())) {
            return Resolution.invalid(GOAL_INVALID, "report node definition is not acceptance.generate_final_report",
                    resolution.goal());
        }
        if (!resolution.goal().iterationId().equals(reportNode.iterationId())) {
            return Resolution.invalid(GOAL_INVALID, "report node iteration does not match final goal",
                    resolution.goal());
        }
        if (!sameRefs(resolution.goal().evidenceRefs(), reportNode.inputRefs())) {
            return Resolution.invalid(GOAL_INVALID, "report routed refs do not match final goal evidence refs",
                    resolution.goal());
        }
        return resolution;
    }

    private static String decisionViolation(GoalSatisfactionDocument goal, NodeInstanceDocument node) {
        if (!goal.nodeInstanceId().equals(node.nodeInstanceId())
                || !goal.nodeDefinitionId().equals(node.nodeDefinitionId())) {
            return "goal does not identify the persisted acceptance decision node";
        }
        if (node.status() != NodeStatus.COMPLETED || !goal.iterationId().equals(node.iterationId())) {
            return "acceptance decision node is not completed in the goal iteration";
        }
        if (!goal.outcome().equals(text(node.result().get("decision")))) {
            return "goal outcome does not match acceptance decision node result";
        }
        if (!sameRefs(goal.evidenceRefs(), node.outputRefs())) {
            return "goal evidence refs do not match acceptance decision output refs";
        }
        return "";
    }

    private static EvidenceRead acceptanceEvidence(
            Path root,
            String workstreamId,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            GoalSatisfactionDocument goal,
            NodeInstanceDocument decisionNode
    ) {
        try {
            var predecessors = definition.edges().stream()
                    .filter(edge -> "acceptance.decision".equals(edge.to()))
                    .map(edge -> edge.from())
                    .collect(java.util.stream.Collectors.toUnmodifiableSet());
            var matches = AgentEvidenceIndex.fromRefs(root, workstreamId, decisionNode.outputRefs(), OBJECT_MAPPER)
                    .recent(Math.max(1, decisionNode.outputRefs().size()))
                    .stream()
                    .filter(entry -> predecessors.contains(entry.document().nodeId()))
                    .filter(entry -> ContractRegistry.hasContract(entry.document().nodeId()))
                    .filter(entry -> ContractRegistry.forNode(entry.document().nodeId())
                            .emitsArtifact(entry.document().sourceArtifactType()))
                    .filter(entry -> "acceptance_review".equals(entry.document().sourceArtifactType()))
                    .filter(entry -> goal.outcome().equals(entry.document().decision()))
                    .toList();
            if (matches.size() != 1) {
                return EvidenceRead.failed("expected exactly one routed final acceptance sidecar, found " + matches.size());
            }
            var entry = matches.getFirst();
            var producer = new WorkflowFileLedger().loadNode(paths, entry.document().nodeInstanceId());
            if (!goal.iterationId().equals(producer.iterationId())) {
                return EvidenceRead.failed("acceptance sidecar producer is from another iteration");
            }
            return EvidenceRead.found(evidence(root, entry));
        } catch (Exception e) {
            return EvidenceRead.failed("acceptance evidence is invalid: " + e.getMessage());
        }
    }

    private static ContextRead contextNode(
            Path root,
            String workstreamId,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            GoalSatisfactionDocument goal,
            Evidence acceptance
    ) {
        try {
            var ledger = new WorkflowFileLedger();
            var producer = ledger.loadNode(paths, acceptance.document().nodeInstanceId());
            var packageRefs = producer.inputRefs().stream()
                    .filter(ref -> canonicalContextPackageRef(workstreamId, ref))
                    .toList();
            if (packageRefs.size() != 1) {
                return ContextRead.failed("expected exactly one acceptance context package ref, found "
                        + packageRefs.size());
            }
            var packageRef = normalizeRef(packageRefs.getFirst());
            var packagePath = root.resolve(packageRef).normalize();
            if (!regularFileWithin(root, packagePath)) {
                return ContextRead.failed("acceptance context package is not a regular workspace file");
            }
            var fileName = packagePath.getFileName().toString();
            var contextNodeId = fileName.substring(0, fileName.length() - ".md".length());
            var contextNode = ledger.loadNode(paths, contextNodeId);
            if (!contextNodeId.equals(contextNode.nodeInstanceId())
                    || contextNode.status() != NodeStatus.COMPLETED
                    || !goal.iterationId().equals(contextNode.iterationId())
                    || !"context.build_package".equals(contextNode.handlerType())
                    || !containsRef(contextNode.outputRefs(), packageRef)) {
                return ContextRead.failed("context package is not published by the completed context node occurrence");
            }
            var contextDefinition = definition.node(contextNode.nodeDefinitionId());
            var profile = text(contextDefinition.config().get("profile"));
            var target = text(contextDefinition.config().get("target_node"));
            if (!"acceptance".equals(profile) || !acceptance.document().nodeId().equals(target)) {
                return ContextRead.failed("context node definition does not target the acceptance producer");
            }
            var metadataRef = packageRef.substring(0, packageRef.length() - ".md".length()) + ".json";
            if (!containsRef(producer.inputRefs(), metadataRef)
                    || !containsRef(contextNode.outputRefs(), metadataRef)
                    || !regularFileWithin(root, root.resolve(metadataRef).normalize())) {
                return ContextRead.failed("acceptance context metadata is not published by the same context occurrence");
            }
            return ContextRead.found(contextNode, contextDefinition.config());
        } catch (Exception e) {
            return ContextRead.failed("acceptance context lineage is invalid: " + e.getMessage());
        }
    }

    private static EvidenceRead selfTestEvidence(
            Path root,
            String workstreamId,
            WorkstreamPaths paths,
            WorkflowDefinition definition,
            GoalSatisfactionDocument goal,
            NodeInstanceDocument contextNode,
            Map<String, Object> contextConfig
    ) {
        try {
            var required = requiredEvidence(contextConfig.get("required_agent_evidence"));
            var requiredDefinition = definition.node(required.nodeId());
            if (!ContractRegistry.hasContract(required.nodeId())
                    || !ContractRegistry.forNode(required.nodeId()).emitsArtifact(required.sourceArtifactType())
                    || !"acpx.agent_run".equals(requiredDefinition.handlerType())) {
                return EvidenceRead.failed("required self-test evidence is not compatible with its workflow contract");
            }
            var matches = AgentEvidenceIndex.fromRefs(root, workstreamId, contextNode.inputRefs(), OBJECT_MAPPER)
                    .recent(Math.max(1, contextNode.inputRefs().size()))
                    .stream()
                    .filter(entry -> required.nodeId().equals(entry.document().nodeId()))
                    .filter(entry -> required.sourceArtifactType().equals(entry.document().sourceArtifactType()))
                    .filter(entry -> required.decision().equals(entry.document().decision()))
                    .filter(entry -> entry.document().hasRequiredTypedPayload())
                    .toList();
            if (matches.size() != 1) {
                return EvidenceRead.failed("expected exactly one routed self-test sidecar, found " + matches.size());
            }
            var entry = matches.getFirst();
            var producer = new WorkflowFileLedger().loadNode(paths, entry.document().nodeInstanceId());
            if (!goal.iterationId().equals(producer.iterationId())) {
                return EvidenceRead.failed("self-test sidecar producer is from another iteration");
            }
            return EvidenceRead.found(evidence(root, entry));
        } catch (Exception e) {
            return EvidenceRead.failed("self-test evidence is invalid: " + e.getMessage());
        }
    }

    private static RequiredEvidence requiredEvidence(Object configured) {
        if (!(configured instanceof Map<?, ?> values)) {
            throw new IllegalArgumentException("required_agent_evidence must be an object");
        }
        return new RequiredEvidence(
                requiredText(values, "node_id"),
                requiredText(values, "source_artifact_type"),
                requiredText(values, "decision"));
    }

    private static String requiredText(Map<?, ?> values, String key) {
        var value = text(values.get(key));
        if (value.isBlank()) {
            throw new IllegalArgumentException("required_agent_evidence." + key + " is required");
        }
        return value;
    }

    private static Evidence evidence(Path root, AgentEvidenceIndex.Entry entry) {
        return new Evidence(
                normalizeRef(root.relativize(entry.path()).toString()),
                entry.path(),
                entry.document());
    }

    private static boolean canonicalContextPackageRef(String workstreamId, String ref) {
        var normalized = normalizeRef(ref);
        var prefix = ".agent/workstreams/" + workstreamId + "/context/";
        if (!normalized.startsWith(prefix) || !normalized.endsWith(".md")) {
            return false;
        }
        var name = normalized.substring(prefix.length(), normalized.length() - ".md".length());
        return !name.isBlank() && !name.contains("/") && !name.contains("\\");
    }

    private static boolean regularFileWithin(Path root, Path path) {
        try {
            return path.startsWith(root)
                    && Files.isRegularFile(path)
                    && !Files.isSymbolicLink(path)
                    && path.toRealPath().startsWith(root.toRealPath());
        } catch (Exception e) {
            return false;
        }
    }

    private static boolean sameRefs(List<String> left, List<String> right) {
        return left.stream().map(CompletionEvidenceLineageResolver::normalizeRef).toList()
                .equals(right.stream().map(CompletionEvidenceLineageResolver::normalizeRef).toList());
    }

    private static boolean containsRef(List<String> refs, String expected) {
        var normalized = normalizeRef(expected);
        return refs.stream().map(CompletionEvidenceLineageResolver::normalizeRef).anyMatch(normalized::equals);
    }

    private static String normalizeRef(String value) {
        return value == null ? "" : value.replace('\\', '/');
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    public enum Status {
        AVAILABLE,
        NOT_CONFIGURED,
        NOT_FINAL,
        INVALID
    }

    public record Evidence(String ref, Path path, AgentOutputContractDocument document) {
    }

    public record Resolution(
            Status status,
            String failureCode,
            String detail,
            GoalSatisfactionDocument goal,
            NodeInstanceDocument decisionNode,
            NodeInstanceDocument contextNode,
            Evidence acceptance,
            Evidence selfTest
    ) {
        static Resolution available(
                GoalSatisfactionDocument goal,
                NodeInstanceDocument decisionNode,
                NodeInstanceDocument contextNode,
                Evidence acceptance,
                Evidence selfTest
        ) {
            return new Resolution(Status.AVAILABLE, "", "", goal, decisionNode, contextNode, acceptance, selfTest);
        }

        static Resolution notConfigured(String detail) {
            return new Resolution(Status.NOT_CONFIGURED, GOAL_NOT_CONFIGURED, detail,
                    null, null, null, null, null);
        }

        static Resolution notFinal(GoalSatisfactionDocument goal, String detail) {
            return new Resolution(Status.NOT_FINAL, GOAL_NOT_FINAL, detail,
                    goal, null, null, null, null);
        }

        static Resolution invalid(String code, String detail, GoalSatisfactionDocument goal) {
            return new Resolution(Status.INVALID, code, detail, goal, null, null, null, null);
        }
    }

    private record EvidenceRead(Evidence evidence, String failure) {
        static EvidenceRead found(Evidence evidence) {
            return new EvidenceRead(evidence, null);
        }

        static EvidenceRead failed(String failure) {
            return new EvidenceRead(null, failure);
        }
    }

    private record ContextRead(NodeInstanceDocument node, Map<String, Object> definitionConfig, String failure) {
        static ContextRead found(NodeInstanceDocument node, Map<String, Object> definitionConfig) {
            return new ContextRead(node, definitionConfig, null);
        }

        static ContextRead failed(String failure) {
            return new ContextRead(null, null, failure);
        }
    }

    private record RequiredEvidence(String nodeId, String sourceArtifactType, String decision) {
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Immutable identity binding for one repository-governance occurrence. */
public final class RepositoryFactBinding {
    public static final int SCHEMA_VERSION = 1;
    private static final String BINDING_ROOT = "artifacts/context-governance/occurrences/";

    private RepositoryFactBinding() {
    }

    static Verified write(
            Path workspaceRoot,
            Path bindingPath,
            String workstreamId,
            String nodeInstanceId,
            String runId,
            String inventoryHead,
            String inventorySha256,
            int inventoryPathCount,
            Map<String, Path> artifacts,
            ObjectMapper objectMapper
    ) throws IOException {
        var artifactRefs = new LinkedHashMap<String, ArtifactRef>();
        for (var entry : artifacts.entrySet()) {
            artifactRefs.put(entry.getKey(), artifactRef(workspaceRoot, entry.getValue()));
        }
        var document = new Document(
                SCHEMA_VERSION,
                workstreamId,
                nodeInstanceId,
                blankToEmpty(runId),
                inventoryHead,
                inventorySha256,
                inventoryPathCount,
                artifactRefs
        );
        Files.createDirectories(bindingPath.getParent());
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(bindingPath.toFile(), document);
        var ref = workspaceRef(workspaceRoot, bindingPath);
        return new Verified(ref, sha256(bindingPath), document, bindingPath.toAbsolutePath().normalize());
    }

    public static Verification verify(
            Path workspaceRoot,
            String workstreamId,
            String bindingRef,
            String expectedBindingSha256,
            String expectedNodeInstanceId,
            String expectedRunId,
            ObjectMapper objectMapper
    ) {
        var errors = new ArrayList<String>();
        if (!canonicalBindingRef(workstreamId, bindingRef)) {
            return Verification.failure("repository fact binding ref is not canonical for the workstream");
        }
        var root = workspaceRoot.toAbsolutePath().normalize();
        var bindingPath = root.resolve(bindingRef).normalize();
        if (!bindingPath.startsWith(root) || !Files.isRegularFile(bindingPath)) {
            return Verification.failure("repository fact binding is missing");
        }
        var bindingSha = safeSha256(bindingPath, errors, "repository fact binding");
        if (!expectedBindingSha256.isBlank() && !expectedBindingSha256.equals(bindingSha)) {
            errors.add("repository fact binding sha256 does not match the lineage anchor");
        }
        final Document document;
        try {
            document = objectMapper.readValue(bindingPath.toFile(), Document.class);
        } catch (IOException | RuntimeException failure) {
            errors.add("repository fact binding cannot be parsed: " + failure.getMessage());
            return new Verification(null, List.copyOf(errors));
        }
        if (document.schemaVersion() != SCHEMA_VERSION) {
            errors.add("unsupported repository fact binding schemaVersion");
        }
        if (!workstreamId.equals(document.workstreamId())) {
            errors.add("repository fact binding workstreamId does not match");
        }
        if (!expectedNodeInstanceId.isBlank() && !expectedNodeInstanceId.equals(document.nodeInstanceId())) {
            errors.add("repository fact binding nodeInstanceId does not match");
        }
        if (!expectedRunId.isBlank() && !expectedRunId.equals(document.runId())) {
            errors.add("repository fact binding runId does not match");
        }
        if (!document.inventorySha256().isBlank()
                && !document.inventorySha256().matches("[0-9a-f]{64}")) {
            errors.add("repository fact binding inventorySha256 is invalid");
        }
        if (document.inventoryPathCount() < 0) {
            errors.add("repository fact binding inventoryPathCount is invalid");
        }
        for (var entry : document.artifacts().entrySet()) {
            verifyArtifact(root, workstreamId, entry.getKey(), entry.getValue(), errors);
        }
        verifyRepoMapIdentity(root, document, objectMapper, errors);
        if (!errors.isEmpty()) {
            return new Verification(null, List.copyOf(errors));
        }
        return new Verification(
                new Verified(bindingRef, bindingSha, document, bindingPath),
                List.of());
    }

    public static Verification verifyReference(
            Path workspaceRoot,
            String workstreamId,
            Reference reference,
            String expectedNodeInstanceId,
            String expectedRunId,
            ObjectMapper objectMapper
    ) {
        if (reference == null) {
            return Verification.failure("repository fact binding reference is missing");
        }
        return verify(workspaceRoot, workstreamId, reference.artifactRef(), reference.sha256(),
                expectedNodeInstanceId, expectedRunId, objectMapper);
    }

    public static Reference reference(Verified verified) {
        return new Reference(verified.ref(), verified.sha256());
    }

    private static ArtifactRef artifactRef(Path workspaceRoot, Path path) throws IOException {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var normalized = path.toAbsolutePath().normalize();
        if (!normalized.startsWith(root) || !Files.isRegularFile(normalized)) {
            throw new IOException("repository fact artifact is outside the workspace or missing: " + path);
        }
        return new ArtifactRef(root.relativize(normalized).toString(), sha256(normalized));
    }

    private static void verifyArtifact(
            Path root,
            String workstreamId,
            String name,
            ArtifactRef artifact,
            List<String> errors
    ) {
        if (artifact == null || artifact.ref() == null || artifact.ref().isBlank()) {
            errors.add("repository fact binding artifact ref is missing: " + name);
            return;
        }
        var normalizedRef = artifact.ref().replace('\\', '/');
        var expectedPrefix = ".agent/workstreams/" + workstreamId + "/artifacts/context-governance/occurrences/";
        if (!normalizedRef.startsWith(expectedPrefix) || normalizedRef.contains("../")) {
            errors.add("repository fact binding artifact ref is not occurrence-scoped: " + name);
            return;
        }
        var path = root.resolve(artifact.ref()).normalize();
        if (!path.startsWith(root) || !Files.isRegularFile(path)) {
            errors.add("repository fact binding artifact is missing: " + name);
            return;
        }
        var actualSha = safeSha256(path, errors, "repository fact artifact " + name);
        if (!artifact.sha256().equals(actualSha)) {
            errors.add("repository fact binding artifact sha256 does not match: " + name);
        }
    }

    @SuppressWarnings("unchecked")
    private static void verifyRepoMapIdentity(
            Path root,
            Document document,
            ObjectMapper objectMapper,
            List<String> errors
    ) {
        var repoMapRef = document.artifacts().get("repoMap");
        if (repoMapRef == null) {
            errors.add("repository fact binding has no repoMap artifact");
            return;
        }
        try {
            var repoMap = objectMapper.readValue(root.resolve(repoMapRef.ref()).toFile(), Map.class);
            if (!document.inventoryHead().equals(text(repoMap.get("inventoryHead")))
                    || !document.inventorySha256().equals(text(repoMap.get("inventorySha256")))
                    || document.inventoryPathCount() != intValue(repoMap.get("inventoryPathCount"))) {
                errors.add("repository fact binding inventory identity does not match repoMap");
            }
        } catch (IOException | RuntimeException failure) {
            errors.add("repository fact repoMap cannot be read: " + failure.getMessage());
        }
    }

    private static String safeSha256(Path path, List<String> errors, String label) {
        try {
            return sha256(path);
        } catch (IOException failure) {
            errors.add(label + " sha256 cannot be computed: " + failure.getMessage());
            return "";
        }
    }

    public static String sha256(Path path) throws IOException {
        try {
            var digest = MessageDigest.getInstance("SHA-256");
            try (var input = Files.newInputStream(path)) {
                var buffer = new byte[8192];
                int read;
                while ((read = input.read(buffer)) >= 0) {
                    digest.update(buffer, 0, read);
                }
            }
            return HexFormat.of().formatHex(digest.digest());
        } catch (java.security.NoSuchAlgorithmException impossible) {
            throw new IllegalStateException("SHA-256 is unavailable", impossible);
        }
    }

    private static boolean canonicalBindingRef(String workstreamId, String ref) {
        if (ref == null || ref.isBlank()) {
            return false;
        }
        var normalized = ref.replace('\\', '/');
        return normalized.startsWith(".agent/workstreams/" + workstreamId + "/" + BINDING_ROOT)
                && normalized.endsWith("/binding.json")
                && !normalized.contains("../");
    }

    private static String workspaceRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize()
                .relativize(path.toAbsolutePath().normalize()).toString();
    }

    private static String blankToEmpty(String value) {
        return value == null ? "" : value;
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    private static int intValue(Object value) {
        if (value instanceof Number number) {
            return number.intValue();
        }
        try {
            return Integer.parseInt(text(value));
        } catch (NumberFormatException ignored) {
            return -1;
        }
    }

    public record Document(
            @JsonProperty("schema_version") int schemaVersion,
            @JsonProperty("workstream_id") String workstreamId,
            @JsonProperty("node_instance_id") String nodeInstanceId,
            @JsonProperty("run_id") String runId,
            @JsonProperty("inventory_head") String inventoryHead,
            @JsonProperty("inventory_sha256") String inventorySha256,
            @JsonProperty("inventory_path_count") int inventoryPathCount,
            @JsonProperty("artifacts") Map<String, ArtifactRef> artifacts
    ) {
        public Document {
            artifacts = artifacts == null
                    ? Map.of()
                    : Collections.unmodifiableMap(new LinkedHashMap<>(artifacts));
            workstreamId = blankToEmpty(workstreamId);
            nodeInstanceId = blankToEmpty(nodeInstanceId);
            runId = blankToEmpty(runId);
            inventoryHead = blankToEmpty(inventoryHead);
            inventorySha256 = blankToEmpty(inventorySha256);
        }
    }

    public record ArtifactRef(String ref, String sha256) {
        public ArtifactRef {
            ref = blankToEmpty(ref);
            sha256 = blankToEmpty(sha256);
        }
    }

    public record Reference(String artifactRef, String sha256) {
        public Reference {
            artifactRef = blankToEmpty(artifactRef);
            sha256 = blankToEmpty(sha256);
        }

        public Map<String, Object> toMap() {
            return Map.of("artifact_ref", artifactRef, "sha256", sha256);
        }

        public static Reference fromMap(Map<String, Object> values) {
            if (values == null || values.isEmpty()) {
                return null;
            }
            return new Reference(text(values.get("artifact_ref")), text(values.get("sha256")));
        }
    }

    public record Verified(String ref, String sha256, Document document, Path path) {
    }

    public record Verification(Verified verified, List<String> errors) {
        public Verification {
            errors = errors == null ? List.of() : List.copyOf(errors);
        }

        public boolean valid() {
            return verified != null && errors.isEmpty();
        }

        static Verification failure(String error) {
            return new Verification(null, List.of(error));
        }
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.ledger.file.GateDocument;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkflowIterationDocument;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.Map;
import java.util.LinkedHashMap;
import java.util.HashSet;
import java.util.Collections;
import dev.dual.ledger.file.WorkflowDefinitionDocument;

/** Resolves the exact typed baseline and obligations for one intake revision. */
public final class TaskContractRevisionContextResolver {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper().registerModule(new JavaTimeModule())
            .registerModule(new dev.dual.ledger.file.EdgeConditionModule());

    public Result resolveForNode(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId
    ) {
        var workstreamDir = workstreamDir(workspaceRoot, workstreamId);
        try {
            var nodePath = workstreamDir.resolve("nodes").resolve(nodeInstanceId + ".json");
            if (!Files.isRegularFile(nodePath)) {
                return failure("current proposal node is missing", nodePath.toString());
            }
            var node = OBJECT_MAPPER.readValue(nodePath.toFile(), NodeInstanceDocument.class);
            if (!nodeInstanceId.equals(node.nodeInstanceId())
                    || !"intake.claude_brainstorm".equals(node.nodeDefinitionId())) {
                return failure("current proposal node identity is inconsistent", nodeInstanceId);
            }
            var resolved = resolveForIteration(workspaceRoot, workstreamId, node.iterationId());
            if (resolved.valid() && resolved.context().lateRoot() != null)
                new LateReader(workspaceRoot, workstreamId).verifyAuthor(node, resolved.context().iteration());
            return resolved;
        } catch (Exception failure) {
            return failure("revision context could not be resolved", message(failure));
        }
    }

    public Result resolveForIteration(
            Path workspaceRoot,
            String workstreamId,
            String iterationId
    ) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var workstreamDir = workstreamDir(root, workstreamId);
        try {
            var iterationPath = workstreamDir.resolve("iterations").resolve(iterationId + ".json");
            if (!Files.isRegularFile(iterationPath)) {
                return failure("current workflow iteration is missing", iterationPath.toString());
            }
            var iteration = OBJECT_MAPPER.readValue(iterationPath.toFile(), WorkflowIterationDocument.class);
            if (!iterationId.equals(iteration.iterationId())) {
                return failure("current workflow iteration identity is inconsistent",
                        iterationId, iteration.iterationId());
            }
            if ("workflow_started".equals(iteration.triggerAction())) {
                return new Result(new Context(iteration, false, null, null, List.of()), List.of());
            }
            var ancestry = lateAncestry(root, workstreamId, iteration);
            if (!ancestry.isEmpty()) {
                return new LateReader(root, workstreamId).resolve(ancestry);
            }
            if ("clarify".equals(iteration.triggerAction())) {
                return resolveContractClarification(
                        root, workstreamId, workstreamDir, iteration);
            }
            if ("revise".equals(iteration.triggerAction())) {
                return resolveHumanRequirementRevision(
                        root, workstreamId, workstreamDir, iteration);
            }
            if (!"NEEDS_REVISION".equals(iteration.triggerAction())) {
                return failure("contract revision reached an unsupported iteration trigger",
                        "trigger_action=" + iteration.triggerAction());
            }
            if (iteration.triggerNodeInstanceId().isBlank() || iteration.parentIterationId().isBlank()) {
                return failure("revision iteration trigger lineage is incomplete", iteration.iterationId());
            }
            var triggerPath = workstreamDir.resolve("nodes")
                    .resolve(iteration.triggerNodeInstanceId() + ".json");
            if (!Files.isRegularFile(triggerPath)) {
                return failure("revision trigger decision node is missing", triggerPath.toString());
            }
            var trigger = OBJECT_MAPPER.readValue(triggerPath.toFile(), NodeInstanceDocument.class);
            if (!"intake.decision".equals(trigger.nodeDefinitionId())
                    || !iteration.parentIterationId().equals(trigger.iterationId())
                    || trigger.status() != NodeStatus.COMPLETED
                    || !"NEEDS_REVISION".equals(text(trigger.result().get("decision")))) {
                return failure("revision trigger is not the completed intake decision",
                        iteration.triggerNodeInstanceId());
            }
            var baselines = verifiedBaselines(
                    root, workstreamId, workstreamDir, trigger.inputRefs(), iteration.parentIterationId(),
                    Set.of("NEEDS_REVISION"), true);
            if (baselines.size() != 1) {
                return failure("revision trigger must reference exactly one verified rejected intake review",
                        "review_count=" + baselines.size());
            }
            var baseline = baselines.get(0);
            return new Result(new Context(
                    iteration,
                    true,
                    baseline.previousProposal(),
                    baseline.previousReference(),
                    baseline.review().contractObligations()), List.of());
        } catch (Exception failure) {
            return failure("revision iteration lineage could not be resolved", message(failure));
        }
    }

    private Result resolveHumanRequirementRevision(
            Path root,
            String workstreamId,
            Path workstreamDir,
            WorkflowIterationDocument iteration
    ) throws IOException {
        if (iteration.triggerNodeInstanceId().isBlank() || iteration.parentIterationId().isBlank()) {
            return failure("human requirement revision trigger lineage is incomplete", iteration.iterationId());
        }
        var triggerPath = workstreamDir.resolve("nodes").resolve(iteration.triggerNodeInstanceId() + ".json");
        if (!Files.isRegularFile(triggerPath)) {
            return failure("human requirement revision gate node is missing", triggerPath.toString());
        }
        var trigger = OBJECT_MAPPER.readValue(triggerPath.toFile(), NodeInstanceDocument.class);
        var note = text(trigger.result().get("note"));
        if (!"gate.human_requirement_review".equals(trigger.nodeDefinitionId())
                || !iteration.parentIterationId().equals(trigger.iterationId())
                || trigger.status() != NodeStatus.COMPLETED
                || !"revise".equals(text(trigger.result().get("human_action")))
                || note.isBlank()) {
            return failure("revision trigger is not a completed human requirement revision gate",
                    iteration.triggerNodeInstanceId());
        }
        var baselines = verifiedBaselines(
                root, workstreamId, workstreamDir, trigger.inputRefs(), iteration.parentIterationId(),
                Set.of("READY_FOR_PRODUCT_REVIEW", "BLOCKED"), false);
        if (baselines.size() != 1) {
            return failure("human requirement revision must reference exactly one verified human-reviewable intake review",
                    "review_count=" + baselines.size());
        }
        var baseline = baselines.getFirst();
        // The completed node is not sufficient authority: the durable human decision and its
        // routed subject must agree, exactly as for later contract rework.
        var reader = new LateReader(root, workstreamId);
        var verified = reader.requirementSubject(reader.gate(trigger, "revise"),
                Set.of("READY_FOR_PRODUCT_REVIEW", "BLOCKED"));
        require(verified.previousReference().equals(baseline.previousReference()),
                "human requirement revision subject mismatch");
        reader.iterationRoute(iteration, trigger);
        return new Result(new Context(
                iteration,
                true,
                baseline.previousProposal(),
                baseline.previousReference(),
                List.of(new AgentResultEnvelope.ReviewObligation("HUMAN-REVISE-1", note))), List.of());
    }

    private Result resolveContractClarification(
            Path root,
            String workstreamId,
            Path workstreamDir,
            WorkflowIterationDocument iteration
    ) throws IOException {
        if (iteration.triggerNodeInstanceId().isBlank() || iteration.parentIterationId().isBlank()) {
            return failure("contract clarification iteration trigger lineage is incomplete", iteration.iterationId());
        }
        var triggerPath = workstreamDir.resolve("nodes").resolve(iteration.triggerNodeInstanceId() + ".json");
        if (!Files.isRegularFile(triggerPath)) {
            return failure("contract clarification gate node is missing", triggerPath.toString());
        }
        var trigger = OBJECT_MAPPER.readValue(triggerPath.toFile(), NodeInstanceDocument.class);
        var note = text(trigger.result().get("note"));
        if (!"gate.contract_review".equals(trigger.nodeDefinitionId())
                || !iteration.parentIterationId().equals(trigger.iterationId())
                || trigger.status() != NodeStatus.COMPLETED
                || !"clarify".equals(text(trigger.result().get("human_action")))
                || note.isBlank()) {
            return failure("revision trigger is not a completed contract clarification gate",
                    iteration.triggerNodeInstanceId());
        }
        // Resolve the exact compiled occurrence. The stable contract-resolution.json is rewritten
        // by the next compile and cannot be the authority for an earlier clarification.
        var reader = new LateReader(root, workstreamId);
        var gate = reader.gate(trigger, "clarify");
        var baseline = reader.compiledBaseline(gate.source().nodeInstanceId());
        reader.iterationRoute(iteration, trigger);
        return new Result(new Context(
                iteration,
                true,
                baseline.previousProposal(),
                baseline.previousReference(),
                List.of(new AgentResultEnvelope.ReviewObligation("HUMAN-CLARIFY-1", note))), List.of());
    }

    static boolean nodeBelongsToIteration(
            Path workstreamDir,
            String nodeInstanceId,
            String expectedIterationId
    ) throws IOException {
        if (nodeInstanceId == null || nodeInstanceId.isBlank()) {
            return false;
        }
        var nodePath = workstreamDir.resolve("nodes").resolve(nodeInstanceId + ".json");
        if (!Files.isRegularFile(nodePath)) {
            return false;
        }
        var node = OBJECT_MAPPER.readValue(nodePath.toFile(), NodeInstanceDocument.class);
        return expectedIterationId.equals(node.iterationId());
    }

    public Result resolveForProposal(Path root, String workstreamId, TaskContractProposalReference candidate) {
        try {
            require(candidate != null && candidate.resolveArtifact(root, workstreamId, OBJECT_MAPPER).isPresent(),
                    "proposal reference invalid");
            var result = resolveForNode(root, workstreamId, candidate.producerNodeInstanceId());
            if (result.valid() && result.context().lateRoot() != null) {
                var reader = new LateReader(root, workstreamId);
                reader.proposal(candidate);
                reader.derivedFrom(candidate, result.context().previousReference());
            }
            return result;
        } catch (Exception failure) {
            return failure("proposal revision context could not be resolved", message(failure));
        }
    }

    public Result resolveForDisplayIteration(Path root, String workstreamId, String iterationId) {
        return resolveForIteration(root, workstreamId, iterationId);
    }

    public TaskContractProposalReference proposalForCompile(Path root, String workstreamId, String compileId)
            throws IOException {
        return new LateReader(root, workstreamId).compiledBaseline(compileId).previousReference();
    }

    public TaskContractProposalReference proposalForContractGate(Path root, String workstreamId, String gateNodeId)
            throws IOException {
        var reader = new LateReader(root, workstreamId);
        return reader.compiledBaseline(contractGateCompile(reader, gateNodeId).nodeInstanceId()).previousReference();
    }

    TaskContractProjectionVerifier.LegacyProjection contractGateCandidate(Path root, String workstreamId, String gateNodeId)
            throws IOException {
        var reader = new LateReader(root, workstreamId);
        var compile = contractGateCompile(reader, gateNodeId);
        reader.compiledBaseline(compile.nodeInstanceId());
        var projection = TaskContractProjectionVerifier.readLegacyProjection(root, workstreamId).projection()
                .orElseThrow(() -> new IOException("contract candidate artifacts are missing or invalid"));
        reader.path(projection.contractRef());
        reader.path(projection.resolutionRef());
        require(compile.outputRefs().contains(projection.contractRef())
                && compile.outputRefs().contains(projection.resolutionRef()), "contract candidate refs are not bound by compile");
        require(TaskContractArtifactWriter.sha256(projection.rawJson().getBytes(java.nio.charset.StandardCharsets.UTF_8))
                        .equals(text(compile.result().get("task_contract_sha256")))
                && TaskContractArtifactWriter.sha256(projection.rawResolutionJson().getBytes(java.nio.charset.StandardCharsets.UTF_8))
                        .equals(text(compile.result().get("contract_resolution_sha256"))),
                "contract candidate SHA does not match source compile");
        // Return the checked snapshot; presentation must not read the stable files a second time.
        return projection;
    }

    private static NodeInstanceDocument contractGateCompile(LateReader reader, String gateNodeId) throws IOException {
        var gateNode = reader.node(gateNodeId);
        var event = reader.origin(gateNodeId);
        var gate = OBJECT_MAPPER.readValue(reader.path(reader.relative(
                reader.dir.resolve("gates/" + event.gateId() + ".json"))).toFile(), GateDocument.class);
        require(gateNode.nodeDefinitionId().equals("gate.contract_review")
                && event.to().equals(gateNode.nodeDefinitionId())
                && gate.nodeInstanceId().equals(gateNodeId) && gate.gateId().equals(event.gateId())
                && gateNode.inputRefs().equals(stringList(gate.result().get("subject_input_refs"))),
                "current contract gate subject mismatch");
        var sourceId = text(gateNode.result().get("source_node_instance_id"));
        require(sourceId.equals(event.sourceId())
                && sourceId.equals(text(gate.result().get("source_node_instance_id")))
                && event.action().equals(text(gate.result().get("source_outcome"))),
                "current contract gate source mismatch");
        var compile = reader.node(sourceId);
        reader.completed(compile, "contract.compile");
        require(compile.iterationId().equals(gateNode.iterationId()), "current contract gate iteration mismatch");
        reader.route(compile, gateNode, event.action());
        return compile;
    }

    public Result resolveForCompile(Path root, String workstreamId, String compileId) {
        try {
            return resolveForProposal(root, workstreamId, proposalForCompile(root, workstreamId, compileId));
        } catch (Exception failure) {
            return failure("compile revision context could not be resolved", message(failure));
        }
    }

    static Map<String, Object> captureAcceptanceReworkBaseline(
            Path root, String workstreamId, TaskContractProjectionVerifier.QualifiedTaskContract qualified,
            AgentEvidenceIndex.Entry acceptance) throws IOException {
        var reader = new LateReader(root, workstreamId);
        var reviewRef = reader.relative(acceptance.path());
        var review = reader.acceptance(reviewRef, reader.sha(reviewRef));
        require(review.equals(acceptance.document()), "acceptance capture changed while reading");
        var values = captureQualifiedBaseline(reader, qualified);
        values.put("acceptance_ref", reviewRef);
        values.put("acceptance_sha256", reader.sha(reviewRef));
        return Map.of("acceptance_rework_baseline", Map.copyOf(values));
    }

    static Map<String, Object> captureScopeReworkBaseline(
            Path root, String workstreamId, TaskContractProjectionVerifier.QualifiedTaskContract qualified,
            ChangeScopeEvaluationArtifact.Reference evaluation) throws IOException {
        var reader = new LateReader(root, workstreamId);
        var values = captureQualifiedBaseline(reader, qualified);
        values.put("evaluation_ref", evaluation.ref());
        values.put("evaluation_sha256", evaluation.sha256());
        return Map.of("scope_rework_baseline", Map.copyOf(values));
    }

    private static LinkedHashMap<String, Object> captureQualifiedBaseline(
            LateReader reader, TaskContractProjectionVerifier.QualifiedTaskContract qualified) throws IOException {
        var compile = reader.node(qualified.compileNodeInstanceId());
        var baseline = reader.compiledBaseline(compile.nodeInstanceId());
        var approval = reader.gateByRef(qualified.approvalGateRef(), "approved");
        reader.approvedRoute(approval);
        require(approval.node().nodeDefinitionId().equals("gate.contract_review")
                && approval.source().nodeInstanceId().equals(compile.nodeInstanceId())
                && approval.event().id().equals(qualified.approvalEventId()), "qualified contract gate mismatch");
        var requirement = reader.requirementApproval(compile, baseline);
        require(text(qualified.resolutionDocument().get("gate_ref")).equals(requirement.ref()),
                "qualified resolution requirement gate mismatch");
        require(qualified.sha256().equals(text(compile.result().get("task_contract_sha256")))
                && qualified.resolutionSha256().equals(text(compile.result().get("contract_resolution_sha256"))),
                "qualified compile hashes mismatch");
        require(reader.sha(qualified.contractRef()).equals(qualified.sha256())
                && reader.sha(qualified.resolutionRef()).equals(qualified.resolutionSha256()),
                "qualified capture artifacts changed");
        var workspace = reader.workspace();
        var values = new LinkedHashMap<String, Object>();
        values.put("proposal_reference", baseline.previousReference().toMap());
        var productReviewRef = reader.reviewRef(compile.inputRefs());
        values.put("proposal_review_ref", productReviewRef);
        values.put("proposal_review_sha256", reader.sha(productReviewRef));
        values.put("compile_node_instance_id", compile.nodeInstanceId());
        values.put("task_contract_sha256", qualified.sha256());
        values.put("contract_resolution_sha256", qualified.resolutionSha256());
        values.put("contract_gate_ref", approval.ref());
        values.put("contract_gate_sha256", reader.sha(approval.ref()));
        values.put("contract_gate_event_id", approval.event().id());
        values.put("requirement_gate_ref", requirement.ref());
        values.put("requirement_gate_sha256", reader.sha(requirement.ref()));
        values.put("workspace_id", workspace.get(0));
        values.put("base_commit", workspace.get(1));
        return values;
    }

    private static boolean contractRework(String action) {
        return Set.of("REJECT_CONTRACT_GAP", "REJECT_CONTRACT_AMBIGUITY", "request_scope_revision").contains(action);
    }

    // Only the nearest rework root belongs to this negotiation. Initial negotiation stays unchanged.
    private static List<WorkflowIterationDocument> lateAncestry(
            Path root, String ws, WorkflowIterationDocument current) throws IOException {
        var chain = new ArrayList<WorkflowIterationDocument>();
        var seen = new HashSet<String>();
        var dir = workstreamDir(root, ws);
        var item = current;
        while (true) {
            require(seen.add(item.iterationId()), "contract revision ancestry cycle");
            chain.add(item);
            if (contractRework(item.triggerAction())) {
                Collections.reverse(chain);
                return List.copyOf(chain);
            }
            if ("workflow_started".equals(item.triggerAction())) return List.of();
            require(!item.parentIterationId().isBlank(), "contract revision ancestry parent missing");
            var parentId = item.parentIterationId();
            var path = dir.resolve("iterations").resolve(parentId + ".json").normalize();
            require(path.getParent().equals(dir.resolve("iterations")) && Files.isRegularFile(path),
                    "contract revision ancestry parent missing");
            item = OBJECT_MAPPER.readValue(path.toFile(), WorkflowIterationDocument.class);
            require(parentId.equals(item.iterationId()), "contract revision ancestry identity mismatch");
        }
    }

    private static void require(boolean condition, String reason) throws IOException {
        if (!condition) throw new IOException(reason);
    }

    private static final class LateReader {
        private final Path root;
        private final String ws;
        private final Path dir;
        private final List<Event> events;
        private final WorkflowDefinitionDocument definition;

        LateReader(Path root, String ws) throws IOException {
            this.root = root.toAbsolutePath().normalize();
            this.ws = ws;
            this.dir = workstreamDir(this.root, ws);
            definition = OBJECT_MAPPER.readValue(path(relative(dir.resolve("workflow/definition.json"))).toFile(),
                    WorkflowDefinitionDocument.class);
            var items = new ArrayList<Event>();
            var ids = new HashSet<String>();
            for (var line : Files.readAllLines(path(relative(dir.resolve("events.jsonl"))))) {
                if (line.isBlank()) continue;
                var tree = OBJECT_MAPPER.readTree(line);
                var id = tree.path("event_id").asText();
                require(ids.add(id), "duplicate historical event identity");
                if (!tree.path("event_type").asText().equals("node_routed")) continue;
                require(id.matches("evt-[0-9]+"), "invalid routing event identity");
                var payload = tree.path("payload");
                items.add(new Event(id, Long.parseLong(id.substring(4)),
                        payload.path("from").asText(), payload.path("outcome").asText(),
                        payload.path("to").asText(), payload.path("node_instance_id").asText(),
                        payload.path("gate_id").asText(), payload.path("source_node_instance_id").asText()));
            }
            events = List.copyOf(items);
        }

        Path path(String ref) throws IOException {
            var value = root.resolve(ref).normalize();
            require(!ref.isBlank() && !Path.of(ref).isAbsolute() && relative(value).equals(ref)
                    && value.startsWith(dir) && Files.isRegularFile(value)
                    && value.toRealPath().equals(root.toRealPath().resolve(ref).normalize()),
                    "missing or noncanonical historical reference: " + ref);
            return value;
        }

        String relative(Path value) { return root.relativize(value.toAbsolutePath().normalize()).toString(); }
        String sha(String ref) throws IOException { return TaskContractArtifactWriter.sha256(path(ref)); }
        NodeInstanceDocument node(String id) throws IOException {
            require(id.matches("[A-Za-z0-9._-]+"), "invalid historical node identity");
            var node = OBJECT_MAPPER.readValue(path(relative(dir.resolve("nodes/" + id + ".json"))).toFile(),
                    NodeInstanceDocument.class);
            require(id.equals(node.nodeInstanceId()), "historical node identity mismatch");
            return node;
        }

        void completed(NodeInstanceDocument node, String role) throws IOException {
            require(node.status() == NodeStatus.COMPLETED && node.nodeDefinitionId().equals(role),
                    "historical node not completed with required role: " + role);
        }

        void edge(String from, String action, String to) throws IOException {
            require(definition.edges().stream().filter(e -> e.from().equals(from)
                    && e.on().equals(action) && e.to().equals(to)).count() == 1,
                    "historical transition is not uniquely declared");
        }

        Event origin(String id) throws IOException {
            var matches = events.stream().filter(e -> e.targetId().equals(id)).toList();
            require(matches.size() == 1, "historical routed occurrence missing or ambiguous: " + id);
            return matches.getFirst();
        }

        Event route(NodeInstanceDocument source, NodeInstanceDocument target, String action) throws IOException {
            var event = origin(target.nodeInstanceId());
            require(event.from().equals(source.nodeDefinitionId()) && event.to().equals(target.nodeDefinitionId())
                    && event.action().equals(action) && target.inputRefs().equals(source.outputRefs()),
                    "historical routed source/input mismatch");
            edge(event.from(), action, event.to());
            return event;
        }

        AgentOutputContractDocument document(String ref) throws IOException {
            var file = path(ref);
            var entries = AgentEvidenceIndex.fromRefs(root, ws, List.of(ref), OBJECT_MAPPER).recent(2);
            require(entries.size() == 1 && entries.getFirst().path().equals(file),
                    "historical sidecar publication lineage or semantics invalid");
            return entries.getFirst().document();
        }

        TaskContractProposal proposal(TaskContractProposalReference ref) throws IOException {
            require(ref != null && ref.resolveArtifact(root, ws, OBJECT_MAPPER).isPresent(),
                    "historical proposal reference invalid");
            var document = document(ref.artifactRef());
            require(document.taskContractProposal() != null, "historical proposal payload missing");
            return document.taskContractProposal();
        }

        AgentOutputContractDocument acceptance(String ref, String hash) throws IOException {
            require(sha(ref).equals(hash), "acceptance reference hash mismatch");
            var document = document(ref);
            require(document.nodeId().equals("acceptance.codex_verifier_review")
                    && document.sourceArtifactType().equals("acceptance_review")
                    && document.decision().equals("REJECT") && !document.failure().contractGaps().isEmpty(),
                    "late root requires a rejected acceptance with contract obligations");
            return document;
        }

        String reviewRef(List<String> refs) throws IOException {
            var matches = new ArrayList<String>();
            for (var ref : refs) {
                if (!ref.endsWith(".contract.json")) continue;
                var document = document(ref);
                if (document.nodeId().equals("intake.codex_product_review")) matches.add(ref);
            }
            require(matches.size() == 1, "exactly one historical proposal review required");
            return matches.getFirst();
        }

        Baseline reviewed(List<String> refs, String iteration, Set<String> decisions) throws IOException {
            var review = document(reviewRef(refs));
            require(review.sourceArtifactType().equals("agent_output_contract")
                    && decisions.contains(review.decision()) && review.reviewSubject() != null,
                    "historical proposal review subject/decision invalid");
            require(node(review.nodeInstanceId()).iterationId().equals(iteration)
                    && node(review.reviewSubject().producerNodeInstanceId()).iterationId().equals(iteration),
                    "historical review/proposal iteration mismatch");
            return new Baseline(review, review.reviewSubject(), proposal(review.reviewSubject()));
        }

        Gate gateByRef(String ref, String action) throws IOException {
            var document = OBJECT_MAPPER.readValue(path(ref).toFile(), GateDocument.class);
            var node = node(document.nodeInstanceId());
            var event = origin(node.nodeInstanceId());
            require(event.gateId().equals(document.gateId()) && event.to().equals(node.nodeDefinitionId())
                    && document.status().equals("resolved") && node.status() == NodeStatus.COMPLETED
                    && action.equals(text(document.result().get("human_action")))
                    && action.equals(text(node.result().get("human_action")))
                    && text(document.result().get("note")).equals(text(node.result().get("note")))
                    && node.inputRefs().equals(stringList(document.result().get("subject_input_refs"))),
                    "historical gate decision/subject mismatch");
            var sourceId = text(document.result().get("source_node_instance_id"));
            require(!sourceId.isBlank() && sourceId.equals(event.sourceId())
                    && sourceId.equals(text(node.result().get("source_node_instance_id"))),
                    "historical gate source identity mismatch");
            var source = node(sourceId);
            require(source.status() == NodeStatus.COMPLETED && source.iterationId().equals(node.iterationId())
                    && event.action().equals(text(document.result().get("source_outcome"))),
                    "historical gate source state mismatch");
            route(source, node, event.action());
            return new Gate(ref, node, document, source, event);
        }

        Gate gate(NodeInstanceDocument node, String action) throws IOException {
            var event = origin(node.nodeInstanceId());
            return gateByRef(relative(dir.resolve("gates/" + event.gateId() + ".json")), action);
        }

        Baseline requirementSubject(Gate gate, Set<String> decisions) throws IOException {
            completed(gate.node(), "gate.human_requirement_review");
            completed(gate.source(), "intake.decision");
            var baseline = reviewed(gate.node().inputRefs(), gate.node().iterationId(), decisions);
            require(gate.source().inputRefs().equals(gate.node().inputRefs())
                    && baseline.review().decision().equals(text(gate.source().result().get("decision")))
                    && baseline.review().decision().equals(gate.event().action()),
                    "requirement decision does not match reviewed subject");
            route(node(baseline.review().nodeInstanceId()), gate.source(), "completed");
            return baseline;
        }

        Gate requirementApproval(NodeInstanceDocument compile, Baseline baseline) throws IOException {
            var matches = new ArrayList<Gate>();
            try (var files = Files.list(dir.resolve("gates"))) {
                for (var file : files.filter(p -> p.getFileName().toString().endsWith(".json")).toList()) {
                    var doc = OBJECT_MAPPER.readValue(file.toFile(), GateDocument.class);
                    var candidate = node(doc.nodeInstanceId());
                    if (!candidate.nodeDefinitionId().equals("gate.human_requirement_review")
                            || !candidate.iterationId().equals(compile.iterationId())
                            || !candidate.outputRefs().equals(compile.inputRefs())
                            || !doc.status().equals("resolved")
                            || !text(doc.result().get("human_action")).equals("approved")) continue;
                    var gate = gateByRef(relative(file), "approved");
                    var subject = requirementSubject(gate, Set.of("READY_FOR_PRODUCT_REVIEW", "BLOCKED"));
                    require(subject.previousReference().equals(baseline.previousReference()),
                            "compile requirement subject mismatch");
                    if (subject.review().decision().equals("BLOCKED"))
                        require(!text(doc.result().get("note")).isBlank(), "blocked approval note missing");
                    route(candidate, compile, "approved");
                    matches.add(gate);
                }
            }
            require(matches.size() == 1, "compile requirement approval missing or ambiguous");
            return matches.getFirst();
        }

        Baseline compiledBaseline(String id) throws IOException {
            var compile = node(id);
            completed(compile, "contract.compile");
            var baseline = reviewed(compile.inputRefs(), compile.iterationId(),
                    Set.of("READY_FOR_PRODUCT_REVIEW", "BLOCKED"));
            requirementApproval(compile, baseline);
            return baseline;
        }

        void derivedFrom(TaskContractProposalReference candidate, TaskContractProposalReference parent) throws IOException {
            var doc = document(candidate.artifactRef());
            require(doc.proposalDerivation() != null && doc.sourceArtifactType().equals("task_contract_revision_patch")
                    && doc.proposalDerivation().baseProposalReference().equals(parent),
                    "late proposal does not derive from the preceding patch parent");
            var author = node(candidate.producerNodeInstanceId());
            var iteration = OBJECT_MAPPER.readValue(path(relative(dir.resolve("iterations/"
                    + author.iterationId() + ".json"))).toFile(), WorkflowIterationDocument.class);
            verifyAuthor(author, iteration);
        }

        void verifyAuthor(NodeInstanceDocument author, WorkflowIterationDocument iteration) throws IOException {
            require(author.iterationId().equals(iteration.iterationId()), "late author iteration mismatch");
            var trigger = trigger(iteration);
            var entry = node(iterationRoute(iteration, trigger).targetId());
            if (iteration.targetNodeDefinitionId().equals("intake.claude_brainstorm")) {
                require(entry.nodeInstanceId().equals(author.nodeInstanceId()), "late author is not the routed iteration entry");
            } else {
                completed(entry, "context.intake_claude_brainstorm");
                require(entry.iterationId().equals(author.iterationId()), "late intake context iteration mismatch");
                route(entry, author, "completed");
            }
        }

        Event approvedRoute(Gate gate) throws IOException {
            var matches = new ArrayList<Event>();
            for (var event : events) {
                if (event.sequence() <= gate.event().sequence() || !event.from().equals(gate.node().nodeDefinitionId())
                        || !event.action().equals("approved")) continue;
                var target = node(event.targetId());
                if (target.iterationId().equals(gate.node().iterationId())
                        && target.inputRefs().equals(gate.node().outputRefs()))
                    matches.add(route(gate.node(), target, "approved"));
            }
            require(matches.size() == 1, "contract approval successor missing or ambiguous");
            return matches.getFirst();
        }

        List<String> workspace() throws IOException {
            var workstream = OBJECT_MAPPER.readTree(path(relative(dir.resolve("workstream.json"))).toFile());
            var id = workstream.path("primaryWorkspaceId").asText();
            require(id.matches("[A-Za-z0-9._-]+"), "primary workspace missing");
            var workspace = OBJECT_MAPPER.readTree(path(relative(dir.resolve("workspaces/" + id + ".json"))).toFile());
            var workdir = workspace.path("effectiveWorkdir").asText(workspace.path("workdir").asText());
            require(workdir.isBlank() || Path.of(workdir).toAbsolutePath().normalize().equals(root),
                    "original workspace directory changed");
            var base = workspace.path("baseCommit").asText();
            require(!base.isBlank(), "original workspace base missing");
            return List.of(id, base);
        }

        Result resolve(List<WorkflowIterationDocument> chain) throws IOException {
            var first = chain.getFirst();
            var classifier = trigger(first);
            var scopeRevision = "request_scope_revision".equals(first.triggerAction());
            completed(classifier, scopeRevision ? "gate.human_implementation_repair" : "acceptance.classify_failure");
            require(first.targetNodeDefinitionId().equals("context.intake_claude_brainstorm"),
                    "late root target must be intake context");
            var rootEvent = iterationRoute(first, classifier);
            var baselineOwner = scopeRevision ? gate(classifier, "request_scope_revision").source() : classifier;
            var baselineKey = scopeRevision ? "scope_rework_baseline" : "acceptance_rework_baseline";
            require(baselineOwner.result().get(baselineKey) instanceof Map<?, ?>,
                    "fixed contract rework baseline missing");
            var binding = OBJECT_MAPPER.convertValue(baselineOwner.result().get(baselineKey),
                    new com.fasterxml.jackson.core.type.TypeReference<Map<String, Object>>() {});
            var ref = TaskContractProposalReference.fromMap(OBJECT_MAPPER.convertValue(binding.get("proposal_reference"),
                    new com.fasterxml.jackson.core.type.TypeReference<Map<String, Object>>() {})).orElseThrow(
                    () -> new IOException("fixed approved proposal reference missing"));
            var acceptanceRef = text(binding.get("acceptance_ref"));
            var acceptanceHash = text(binding.get("acceptance_sha256"));
            AgentOutputContractDocument acceptance = null;
            ChangeScopeEvaluationArtifact.Verified scopeEvidence = null;
            if (scopeRevision) {
                var scopeGate = gate(classifier, "request_scope_revision");
                require("CHANGE_SCOPE_VIOLATION".equals(text(scopeGate.document().result().get("source_outcome")))
                        && !text(classifier.result().get("note")).isBlank(), "scope revision source/note mismatch");
                scopeEvidence = ChangeScopeEvaluationArtifact.verifyGateSource(root, ws, classifier.iterationId(),
                        classifier.inputRefs());
                require(scopeEvidence.ref().equals(text(binding.get("evaluation_ref")))
                        && scopeEvidence.sha256().equals(text(binding.get("evaluation_sha256")))
                        && scopeEvidence.document().sourceNodeInstanceId().equals(baselineOwner.nodeInstanceId()),
                        "scope revision evaluation baseline mismatch");
            } else {
                acceptance = acceptance(acceptanceRef, acceptanceHash);
                require(classifier.inputRefs().contains(acceptanceRef) && classifier.outputRefs().contains(acceptanceRef)
                    && node(acceptance.nodeInstanceId()).iterationId().equals(classifier.iterationId())
                    && first.triggerAction().equals("REJECT_" + text(classifier.result().get("category")))
                    && text(classifier.result().get("category")).equals(acceptance.failure().categoryHint()),
                    "classifier acceptance identity/category mismatch");
                require(classifier.inputRefs().stream().filter(r -> r.endsWith(".contract.json")).count() == 1,
                    "classifier acceptance source is ambiguous");
            }
            var compile = node(text(binding.get("compile_node_instance_id")));
            var base = compiledBaseline(compile.nodeInstanceId());
            require(base.previousReference().equals(ref), "frozen compile proposal mismatch");
            var productRef = reviewRef(compile.inputRefs());
            require(productRef.equals(text(binding.get("proposal_review_ref")))
                    && sha(productRef).equals(text(binding.get("proposal_review_sha256")))
                    && text(compile.result().get("task_contract_sha256")).equals(text(binding.get("task_contract_sha256")))
                    && text(compile.result().get("contract_resolution_sha256")).equals(text(binding.get("contract_resolution_sha256"))),
                    "frozen compile/review hash mismatch");
            var contractGateRef = text(binding.get("contract_gate_ref"));
            require(sha(contractGateRef).equals(text(binding.get("contract_gate_sha256"))), "frozen contract gate hash mismatch");
            var approval = gateByRef(contractGateRef, "approved");
            require(approvedRoute(approval).sequence() < rootEvent.sequence(), "root precedes its contract approval");
            require(approval.node().nodeDefinitionId().equals("gate.contract_review")
                    && approval.source().nodeInstanceId().equals(compile.nodeInstanceId())
                    && approval.event().id().equals(text(binding.get("contract_gate_event_id"))),
                    "frozen contract approval mismatch");
            var requirement = requirementApproval(compile, base);
            require(requirement.ref().equals(text(binding.get("requirement_gate_ref")))
                    && sha(requirement.ref()).equals(text(binding.get("requirement_gate_sha256"))),
                    "frozen requirement approval mismatch");
            var workspace = workspace();
            require(workspace.equals(List.of(text(binding.get("workspace_id")), text(binding.get("base_commit")))),
                    "original workspace identity/base changed");
            var lateRoot = new LateRoot(classifier.nodeInstanceId(), first.iterationId(), ref,
                    acceptanceRef, acceptanceHash, workspace.get(0), workspace.get(1), acceptance,
                    scopeEvidence == null ? "" : scopeEvidence.ref(), scopeEvidence == null ? "" : scopeEvidence.sha256());
            var candidates = scopeEvidence == null ? List.<dev.dual.core.contract.TaskContract.ScopeEntry>of()
                    : new TaskContractScopeResolver().reviewedCreateCandidates(root, workspace.get(1), scopeEvidence);
            var obligations = new LinkedHashMap<String, AgentResultEnvelope.ReviewObligation>();
            if (scopeRevision) {
                add(obligations, "gate:" + classifier.nodeInstanceId() + "#scope-review", text(classifier.result().get("note")));
            } else {
                for (int i = 0; i < acceptance.failure().contractGaps().size(); i++)
                    add(obligations, "sha256:" + acceptanceHash + "#contract-gap:" + i,
                        acceptance.failure().contractGaps().get(i));
            }
            var direct = base;
            long through = rootEvent.sequence();
            for (int i = 1; i < chain.size(); i++) {
                var iteration = chain.get(i);
                require(iteration.parentIterationId().equals(chain.get(i - 1).iterationId()), "late parent chain mismatch");
                var trigger = trigger(iteration);
                var event = iterationRoute(iteration, trigger);
                require(event.sequence() > through, "late revision event order invalid");
                through = event.sequence();
                var previous = direct.previousReference();
                if (iteration.triggerAction().equals("NEEDS_REVISION")) {
                    completed(trigger, "intake.decision");
                    direct = reviewed(trigger.inputRefs(), trigger.iterationId(), Set.of("NEEDS_REVISION"));
                    require(text(trigger.result().get("decision")).equals("NEEDS_REVISION")
                            && !direct.review().contractObligations().isEmpty(), "late review obligations missing");
                    route(node(direct.review().nodeInstanceId()), trigger, "completed");
                } else if (iteration.triggerAction().equals("revise")) {
                    var gate = gate(trigger, "revise");
                    direct = requirementSubject(gate, Set.of("READY_FOR_PRODUCT_REVIEW", "BLOCKED"));
                } else if (iteration.triggerAction().equals("clarify")) {
                    var gate = gate(trigger, "clarify");
                    completed(trigger, "gate.contract_review");
                    direct = compiledBaseline(gate.source().nodeInstanceId());
                } else throw new IOException("unsupported late revision trigger");
                derivedFrom(direct.previousReference(), previous);
                addReview(obligations, direct.review(), reviewRef(
                        iteration.triggerAction().equals("clarify")
                                ? node(gate(trigger, "clarify").source().nodeInstanceId()).inputRefs() : trigger.inputRefs()));
                if (!iteration.triggerAction().equals("NEEDS_REVISION")) {
                    var note = text(trigger.result().get("note"));
                    require(!note.isBlank(), "late revision human note missing");
                    add(obligations, "gate:" + trigger.nodeInstanceId() + "#note", note);
                }
            }
            // Approval closes negotiation; a future rejection must capture a new root instead of inheriting it.
            for (var event : events) {
                if (event.sequence() <= approval.event().sequence() || event.sequence() > through
                        || !event.to().equals("gate.contract_review")) continue;
                var node = node(event.targetId());
                if (node.status() == NodeStatus.COMPLETED && text(node.result().get("human_action")).equals("approved"))
                    throw new IOException("late revision crosses a newer approved contract epoch");
            }
            return new Result(new Context(chain.getLast(), true, direct.previousProposal(), direct.previousReference(),
                    List.copyOf(obligations.values()), base.previousProposal(), lateRoot, candidates), List.of());
        }

        NodeInstanceDocument trigger(WorkflowIterationDocument iteration) throws IOException {
            var trigger = node(iteration.triggerNodeInstanceId());
            require(trigger.status() == NodeStatus.COMPLETED && trigger.iterationId().equals(iteration.parentIterationId()),
                    "late trigger parent/status mismatch");
            return trigger;
        }

        Event iterationRoute(WorkflowIterationDocument iteration, NodeInstanceDocument trigger) throws IOException {
            var matches = new ArrayList<Event>();
            for (var event : events) {
                if (!event.from().equals(trigger.nodeDefinitionId()) || !event.action().equals(iteration.triggerAction())
                        || !event.to().equals(iteration.targetNodeDefinitionId())) continue;
                var target = node(event.targetId());
                if (target.iterationId().equals(iteration.iterationId())) {
                    matches.add(route(trigger, target, iteration.triggerAction()));
                }
            }
            require(matches.size() == 1, "late iteration routing missing or ambiguous");
            return matches.getFirst();
        }

        void addReview(Map<String, AgentResultEnvelope.ReviewObligation> obligations,
                       AgentOutputContractDocument review, String ref) throws IOException {
            for (var obligation : review.contractObligations())
                add(obligations, "sha256:" + sha(ref) + "#review:" + obligation.id(), obligation.text());
        }

        void add(Map<String, AgentResultEnvelope.ReviewObligation> values, String id, String value) throws IOException {
            require(value != null && !value.isBlank(), "late obligation text missing");
            var obligation = new AgentResultEnvelope.ReviewObligation(id, value);
            var previous = values.putIfAbsent(id, obligation);
            require(previous == null || previous.equals(obligation), "late obligation source collision");
        }
    }

    private record Event(String id, long sequence, String from, String action, String to,
                         String targetId, String gateId, String sourceId) {}
    private record Gate(String ref, NodeInstanceDocument node, GateDocument document,
                        NodeInstanceDocument source, Event event) {}

    private List<Baseline> verifiedBaselines(
            Path root,
            String workstreamId,
            Path workstreamDir,
            List<String> refs,
            String expectedIterationId,
            Set<String> allowedDecisions,
            boolean requireObligations
    ) throws IOException {
        var baselines = new ArrayList<Baseline>();
        for (var ref : refs) {
            if (ref == null || !ref.endsWith(".contract.json")) {
                continue;
            }
            var path = root.resolve(ref).normalize();
            if (!path.startsWith(root) || !Files.isRegularFile(path)) {
                continue;
            }
            var document = AgentOutputContractDocument.read(path, OBJECT_MAPPER);
            if (document.isEmpty()
                    || AgentOutputLineageVerifier.violation(root, workstreamId, path, document.get()).isPresent()
                    || !"intake.codex_product_review".equals(document.get().nodeId())
                    || !"agent_output_contract".equals(document.get().sourceArtifactType())
                    || !allowedDecisions.contains(document.get().decision())
                    || document.get().reviewSubject() == null
                    || (requireObligations && document.get().contractObligations().isEmpty())
                    || !nodeBelongsToIteration(
                            workstreamDir, document.get().nodeInstanceId(), expectedIterationId)
                    || !nodeBelongsToIteration(
                            workstreamDir,
                            document.get().reviewSubject().producerNodeInstanceId(),
                            expectedIterationId)) {
                continue;
            }
            var artifactPath = document.get().reviewSubject().resolveArtifact(root, workstreamId, OBJECT_MAPPER);
            if (artifactPath.isEmpty()) {
                continue;
            }
            var proposalDocument = AgentOutputContractDocument.read(artifactPath.get(), OBJECT_MAPPER);
            if (proposalDocument.isEmpty() || proposalDocument.get().taskContractProposal() == null) {
                continue;
            }
            baselines.add(new Baseline(
                    document.get(),
                    document.get().reviewSubject(),
                    proposalDocument.get().taskContractProposal()));
        }
        return List.copyOf(baselines);
    }

    private static List<String> stringList(Object value) {
        if (!(value instanceof List<?> values)) {
            return List.of();
        }
        return values.stream().map(String::valueOf).filter(item -> !item.isBlank()).toList();
    }

    private static Path workstreamDir(Path workspaceRoot, String workstreamId) {
        return workspaceRoot.toAbsolutePath().normalize()
                .resolve(".agent/workstreams")
                .resolve(workstreamId);
    }

    private static Result failure(String message, String... facts) {
        var errors = new ArrayList<String>();
        errors.add(message);
        errors.addAll(List.of(facts));
        return new Result(null, List.copyOf(errors));
    }

    private static String message(Exception failure) {
        return failure.getMessage() == null ? failure.getClass().getSimpleName() : failure.getMessage();
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    public record Context(
            WorkflowIterationDocument iteration,
            boolean revision,
            TaskContractProposal previousProposal,
            TaskContractProposalReference previousReference,
            List<AgentResultEnvelope.ReviewObligation> obligations,
            TaskContractProposal approvedScopeBaseline,
            LateRoot lateRoot,
            List<dev.dual.core.contract.TaskContract.ScopeEntry> scopeReviewCandidates
    ) {
        public Context {
            scopeReviewCandidates = List.copyOf(scopeReviewCandidates);
        }
        public Context(WorkflowIterationDocument iteration, boolean revision,
                       TaskContractProposal previousProposal, TaskContractProposalReference previousReference,
                       List<AgentResultEnvelope.ReviewObligation> obligations,
                       TaskContractProposal approvedScopeBaseline, LateRoot lateRoot) {
            this(iteration, revision, previousProposal, previousReference, obligations, approvedScopeBaseline,
                    lateRoot, List.of());
        }
        public Context(WorkflowIterationDocument iteration, boolean revision,
                       TaskContractProposal previousProposal, TaskContractProposalReference previousReference,
                       List<AgentResultEnvelope.ReviewObligation> obligations) {
            this(iteration, revision, previousProposal, previousReference, obligations, null, null);
        }

        public String originalBaseCommit() { return lateRoot == null ? "" : lateRoot.baseCommit(); }
        public boolean scopeRevision() { return lateRoot != null && !lateRoot.scopeEvaluationRef().isBlank(); }
    }

    public record LateRoot(String classifierNodeInstanceId, String iterationId,
                           TaskContractProposalReference approvedProposalReference,
                           String acceptanceRef, String acceptanceSha256,
                           String workspaceId, String baseCommit,
                           AgentOutputContractDocument acceptanceEvidence,
                           String scopeEvaluationRef, String scopeEvaluationSha256) {}

    public record Result(Context context, List<String> errors) {
        public boolean valid() {
            return context != null && errors.isEmpty();
        }
    }

    private record Baseline(
            AgentOutputContractDocument review,
            TaskContractProposalReference previousReference,
            TaskContractProposal previousProposal
    ) {}
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.PropertyNamingStrategies;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;

/** Prompt projection of the authoritative {@link AgentResultEnvelope} schema. */
public final class AgentResultPromptContract {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper()
            .setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE);
    private static final String CANONICAL_SCOPE_PATH_REQUIREMENT =
            "Each scope path must name one exact file, not a directory; it must be repository-relative, "
                    + "must not end with `/`, and must already be canonical (no `./`, `..`, repeated separators, "
                    + "backslashes, leading/trailing whitespace, `.git`, or `.agent` segments). ";

    private AgentResultPromptContract() {
    }

    public static String render(
            String workstreamId,
            String runId,
            String nodeId,
            String decisionExample,
            Set<String> allowedDecisions
    ) {
        return render(workstreamId, runId, nodeId, decisionExample, allowedDecisions,
                ProposalEmissionContext.initial());
    }

    public static String render(
            String workstreamId,
            String runId,
            String nodeId,
            String decisionExample,
            Set<String> allowedDecisions,
            ProposalEmissionContext proposalContext
    ) {
        var exampleResult = exampleResult(nodeId, decisionExample, proposalContext);
        var envelope = new AgentResultEnvelope(
                1,
                workstreamId,
                runId,
                nodeId,
                exampleResult
        );
        try {
            return """
                    Return exactly one JSON object as the final assistant message.
                    Do not use Markdown fences, XML tags, headings, commentary, or text before/after the JSON.
                    Preserve the exact key names and JSON primitive types shown below. Replace example values with factual values.
                    Every JSON object is closed. Do not add keys that are not declared for that object.
                    Allowed `result.decision` values: %s
                    %s
                    %s
                    %s
                    %s

                    %s
                    """.formatted(
                            allowedDecisions.stream().sorted().toList(),
                            verificationRemediationAllowedValues(exampleResult),
                            rereadReasonInstruction(nodeId),
                            verificationRemediationInstruction(nodeId, exampleResult) + acceptanceClassificationInstruction(exampleResult),
                            contractRevisionInstruction(nodeId, proposalContext) + authoredRevisionInstruction(exampleResult)
                                    + selfTestInstruction(exampleResult),
                            OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(envelope)
                    ).stripTrailing();
        } catch (Exception failure) {
            throw new IllegalStateException("failed to render AgentResultEnvelope prompt contract", failure);
        }
    }

    private static String selfTestInstruction(AgentResultEnvelope.AgentResult result) {
        if (!(result instanceof AgentResultEnvelope.SelfTestResult)) return "";
        return "\n`result.must_fix` is required. List concrete product/test code defects there, not missing "
                + "permissions, tools, or external verification records. Use missing_evidence for missing proof. "
                + "Both lists may be non-empty when code defects and missing proof coexist. "
                + "SELF_TEST_COMPLETE requires both lists empty; otherwise use SELF_TEST_INCOMPLETE or BLOCKED. "
                + "Do not invent code changes to resolve an environment or evidence-only blocker.";
    }

    private static String authoredRevisionInstruction(AgentResultEnvelope.AgentResult result) {
        if (!(result instanceof AgentResultEnvelope.DesignResult) && !(result instanceof AgentResultEnvelope.PlanResult)) return "";
        return "\n`result.revision_responses` is required: return [] when there are no active authored obligations. "
                + "Otherwise cover every active obligation_id from Required Authored Context exactly once; "
                + "do not add unknown IDs or omit unresolved obligations. Each entry has exactly obligation_id, "
                + "disposition (ADDRESSED or NOT_ADDRESSED), and non-empty evidence. "
                + "Use NOT_ADDRESSED when unresolved; ADDRESSED is a claim for review, not an approval or closure. "
                + "Preserve all previously required behavior and the approved contract while making this revision."
                + (result instanceof AgentResultEnvelope.PlanResult
                    ? "\nedit_files must contain unique canonical paths within the approved TaskContract scope. "
                        + CANONICAL_SCOPE_PATH_REQUIREMENT + "A subset is allowed; reference_files do not authorize edits. "
                    : "")
                + closedItemFields("result.revision_responses", new AgentResultEnvelope.AuthoredRevisionResponse(
                        "sha256:" + "0".repeat(64) + "#human-note:0",
                        AgentResultEnvelope.AuthoredRevisionDisposition.NOT_ADDRESSED, "Explain what remains unresolved"));
    }

    private static String contractRevisionInstruction(String nodeId, ProposalEmissionContext context) {
        if ("intake.claude_brainstorm".equals(nodeId)) {
            if (context.revision()) {
                return "Return only `task_contract_revision_patch`; do not return or copy a full proposal. "
                        + "The patch is bound to base proposal id `" + context.baseProposalId()
                        + "` and sha256 `" + context.baseProposalSha256() + "`. "
                        + "Cover each authoritative routed obligation exactly once. Preserve its id and implement its text: "
                        + json(context.obligations())
                        + (context.acceptanceEvidence().isEmpty() ? "" :
                            ". Original verified rework evidence (retain non-contract defects as evidence; "
                            + "do not reinterpret them as contract obligations or approval): "
                            + context.acceptanceEvidence())
                        + ". Only clause ADD/REPLACE, exact scope ADD, and evidence-ref ADD are supported. "
                        + "No DELETE, section move, scope removal, objective/open-question change, JSON Pointer, "
                        + "or arbitrary field patch is allowed. `scope_additions` uses exact repository-relative "
                        + "paths. " + CANONICAL_SCOPE_PATH_REQUIREMENT
                        + "Dual derives CREATE/MODIFY from the effective worktree. `section` is authoritative; clause IDs are opaque "
                        + "and their prefixes do not determine section. "
                        + "Across the entire `result.obligation_patches` array, each `clause_changes[].id`, "
                        + "`scope_additions[].path`, and `evidence_ref_additions[]` target must appear at most once. "
                        + "When one evidence ref supports multiple obligations, add it in one most relevant patch only; "
                        + "use each obligation's `resolved_by_clause_ids` to express coverage instead of adding the ref again. "
                        + closedItemFields("result.obligation_patches",
                        new AgentResultEnvelope.ObligationPatch(
                                "CO-1", List.of("AC-1"),
                                List.of(new AgentResultEnvelope.ClauseChange(
                                        AgentResultEnvelope.ClauseChangeOperation.REPLACE,
                                        AgentResultEnvelope.ClauseSection.ACCEPTANCE_CRITERIA,
                                        "AC-1", "replacement text")),
                                List.of(), List.of()));
            }
            return "`result.scope.included` is the exhaustive authorization set for permitted repository changes; "
                    + "each entry names one exact repository-relative path. " + CANONICAL_SCOPE_PATH_REQUIREMENT
                    + "Dual derives CREATE/MODIFY from the effective worktree. "
                    + "It does not require every declared path to be changed. Acceptance criteria, constraints, "
                    + "risks, and other prose cannot authorize an undeclared path. Never describe the typed scope "
                    + "as illustrative or non-exhaustive. When a revision obligation identifies a scope gap, "
                    + "update the typed path entries directly and map the obligation to one or more "
                    + "genuinely relevant clause IDs. "
                    + "Each task-contract clause must contain stable string fields `id` and `text`. "
                    + "On an initial intake, `result.revision_responses` must be `[]`. "
                    + "On a revision, copy every routed Contract Obligation ID exactly once into "
                    + "`review_obligation_id` and list one or more clause IDs in `resolved_by_clause_ids`. "
                    + "Preserve every existing clause not named by the current `revision_responses` by copying "
                    + "its `id` and `text` character-for-character from the verified previous proposal, including "
                    + "whitespace, punctuation, capitalization, and Markdown backticks. Formatting normalization "
                    + "is a modification and is prohibited unless that clause ID is declared in "
                    + "`resolved_by_clause_ids`. "
                    + "List every added or modified clause ID in at least one `resolved_by_clause_ids` entry, "
                    + "and do not delete existing clause IDs. "
                    + closedItemFields(
                    "result.revision_responses",
                    new AgentResultEnvelope.RevisionResponse("CO-1", List.of("AC-1")));
        }
        if ("intake.codex_product_review".equals(nodeId)) {
            return "For NEEDS_REVISION with non-empty `result.failure.contract_gaps`, "
                    + "`result.contract_obligations` must contain one object per contract obligation "
                    + "with stable string fields `id` and `text`. Otherwise it must be `[]`. "
                    + closedItemFields(
                    "result.contract_obligations",
                    new AgentResultEnvelope.ReviewObligation("CO-1", "binding contract obligation"));
        }
        if (ContractRegistry.forNode(nodeId).emitsArtifact("agent_output_contract")) {
            return "For this node, `result.contract_obligations` must remain exactly `[]`; "
                    + "contract obligations are produced only by intake contract review.";
        }
        return "";
    }

    private static String rereadReasonInstruction(String nodeId) {
        var contract = ContractRegistry.forNode(nodeId);
        if (!contract.emitsArtifact("agent_output_contract")) {
            return "";
        }
        if (!ContractRegistry.supportsRereadReasonField(nodeId)) {
            return "For this node, `result.reread_reasons` must remain exactly `[]`.";
        }
        return "Each `result.reread_reasons` entry must use string fields; `reason` must be one of "
                + ReadReuseContractReasons.ALLOWED_REPEATED_READ_REASONS + ". "
                + closedItemFields(
                "result.reread_reasons",
                new AgentResultEnvelope.RereadReason(
                        "repo/file.ext",
                        ReadReuseContractReasons.ALLOWED_REPEATED_READ_REASONS.stream().sorted().findFirst().orElseThrow(),
                        "design",
                        "specific evidence"));
    }

    private static String closedItemFields(String fieldPath, Object sample) {
        var tree = OBJECT_MAPPER.valueToTree(sample);
        if (!tree.isObject()) {
            throw new IllegalArgumentException("closed item sample must serialize as an object: " + fieldPath);
        }
        var fields = new ArrayList<String>();
        tree.fieldNames().forEachRemaining(fields::add);
        return "Each `" + fieldPath + "` item is a closed object with exactly these fields: "
                + fields + ". No other keys are permitted.";
    }

    private static String json(Object value) {
        try {
            return OBJECT_MAPPER.writeValueAsString(value);
        } catch (Exception failure) {
            throw new IllegalStateException("failed to render typed prompt value", failure);
        }
    }

    private static String verificationRemediationAllowedValues(AgentResultEnvelope.AgentResult result) {
        if (!hasVerificationRemediation(result)) {
            return "";
        }
        var allowed = result instanceof AgentResultEnvelope.AcceptanceReviewResult
                ? java.util.Arrays.stream(AgentResultEnvelope.VerificationRemediation.values())
                        .map(Enum::name)
                        .sorted()
                        .toList()
                : List.of(AgentResultEnvelope.VerificationRemediation.NONE.name());
        return "Allowed `result.failure.verification_remediation` values for this node: " + allowed;
    }

    private static String verificationRemediationInstruction(
            String nodeId,
            AgentResultEnvelope.AgentResult result
    ) {
        if (!hasVerificationRemediation(result)) {
            return "";
        }
        if (!"acceptance.codex_verifier_review".equals(nodeId)) {
            return "For this node, `result.failure.verification_remediation` must remain `NONE`.";
        }
        return "For a REJECT with non-empty `result.failure.missing_tests`, set "
                + "`result.failure.verification_remediation` to `EVIDENCE_COLLECTION` only when "
                + "existing test/verification evidence must be collected, or `TEST_CODE_CHANGE` when "
                + "a test source change is required. Do not infer this from prose in downstream nodes.";
    }

    private static String acceptanceClassificationInstruction(AgentResultEnvelope.AgentResult result) {
        if (!(result instanceof AgentResultEnvelope.AcceptanceReviewResult)) return "";
        return "\nFor REJECT, failure.category_hint is required and must be exactly one of "
                + AgentContractSemantics.acceptanceCategories()
                + ". No aliases or case normalization. For accepted decisions leave category_hint empty. "
                + "Choose the repair owner: IMPLEMENTATION_BUG for product, documentation or test changes within the "
                + "existing contract, including mixed repair and missing evidence; VERIFICATION_INSUFFICIENT only for "
                + "collecting existing evidence. Contract categories require contract_gaps; all other categories forbid "
                + "contract_gaps (existing-contract violations belong in must_fix). IMPLEMENTATION_BUG requires must_fix, "
                + "out_of_scope_files or TEST_CODE_CHANGE. VERIFICATION_INSUFFICIENT requires missing_tests or missing_evidence "
                + "and forbids context_gaps, out_of_scope_files and TEST_CODE_CHANGE. CONTEXT_INSUFFICIENT requires context_gaps; "
                + "TOOL_LIMITATION requires failure.reason; both forbid out_of_scope_files and TEST_CODE_CHANGE. REVIEW_NOISE "
                + "requires failure.reason, empty failure lists, empty must_fix/missing_evidence and NONE remediation. "
                + "Contract categories may retain mixed issues. EVIDENCE_COLLECTION never overrides the category. "
                + "TEST_CODE_CHANGE permits only implementation or contract categories.";
    }

    private static boolean hasVerificationRemediation(AgentResultEnvelope.AgentResult result) {
        return result instanceof AgentResultEnvelope.AgentOutputResult
                || result instanceof AgentResultEnvelope.PlanResult
                || result instanceof AgentResultEnvelope.AcceptanceReviewResult;
    }

    private static AgentResultEnvelope.AgentResult exampleResult(
            String nodeId,
            String decision,
            ProposalEmissionContext proposalContext
    ) {
        return switch (nodeId) {
            case "intake.claude_brainstorm" -> proposalContext.revision()
                    ? new AgentResultEnvelope.TaskContractRevisionPatchResult(
                    "task_contract_revision_patch",
                    decision,
                    "one short sentence",
                    proposalContext.baseProposalId(),
                    proposalContext.baseProposalSha256(),
                    List.of(new AgentResultEnvelope.ObligationPatch(
                            proposalContext.obligations().isEmpty()
                                    ? "CO-1" : proposalContext.obligations().getFirst().id(),
                            List.of("AC-1"),
                            List.of(new AgentResultEnvelope.ClauseChange(
                                    AgentResultEnvelope.ClauseChangeOperation.REPLACE,
                                    AgentResultEnvelope.ClauseSection.ACCEPTANCE_CRITERIA,
                                    "AC-1",
                                    "replacement text")),
                            List.of(new AgentResultEnvelope.ProposalScopePath("repo/relative/new.ext")),
                            List.of("repo/relative/evidence.ext"))))
                    : new AgentResultEnvelope.TaskContractProposalResult(
                    "task_contract_proposal",
                    decision,
                    "one short sentence",
                    false,
                    "one clear objective",
                    new AgentResultEnvelope.ProposalScope(
                            List.of(
                                    new AgentResultEnvelope.ProposalScopePath("repo/relative/existing.ext"),
                                    new AgentResultEnvelope.ProposalScopePath("repo/relative/new.ext")
                            ),
                            List.of("explicit non-goal")
                    ),
                    List.of(
                            new AgentResultEnvelope.ContractClause("AC-1", "observable acceptance criterion"),
                            new AgentResultEnvelope.ContractClause("AC-2", "second observable criterion")),
                    List.of(new AgentResultEnvelope.ContractClause("TR-1", "required verification")),
                    List.of(new AgentResultEnvelope.ContractClause("C-1", "technical or product constraint")),
                    List.of(new AgentResultEnvelope.ContractClause("NG-1", "explicit non-goal")),
                    List.of(new AgentResultEnvelope.ContractClause("R-1", "risk for review")),
                    List.of("repo/relative/evidence.ext"),
                    List.of(),
                    List.of()
            );
            case "design.claude_design" -> new AgentResultEnvelope.DesignResult(
                    "design_result", decision, "one short sentence", "READY",
                    List.of("read the approved contract"), List.of("design evidence"),
                    List.of(), List.of(), List.of(), "Design only; no implementation performed.",
                    new AgentResultEnvelope.Design(List.of(new AgentResultEnvelope.PlannedFile(
                            "repo/relative/new.ext", dev.dual.core.contract.TaskContract.ScopeOperation.CREATE,
                            "responsibility assigned within the approved scope"))), List.of());
            case "plan.claude_plan" -> new AgentResultEnvelope.PlanResult(
                    "plan_result",
                    decision,
                    "one short sentence",
                    "READY",
                    false,
                    List.of("read approved design and review context"),
                    List.of("plan is scoped to the approved contract"),
                    List.of(),
                    List.of(),
                    List.of(),
                    List.of(),
                    List.of(),
                    "Planning only; implementation and verification happen later.",
                    emptyFailure(),
                    new AgentResultEnvelope.Plan(
                            List.of("ordered implementation step"),
                            List.of("path/to/file.ext"),
                            List.of(),
                            List.of("path/to/file.ext: intended change"),
                            List.of("verification command or check"),
                            "rollback approach",
                            List.of("None identified."),
                            List.of("review item")
                    ), List.of()
            );
            case "implement.claude_self_test_report" -> new AgentResultEnvelope.SelfTestResult(
                    "self_test_report",
                    decision,
                    "one short sentence",
                    "READY",
                    List.of("command or inspection performed"),
                    List.of(),
                    List.of("specific result evidence"),
                    List.of(),
                    List.of(),
                    List.of(),
                    "short verification adequacy summary"
            );
            case "acceptance.codex_verifier_review" -> new AgentResultEnvelope.AcceptanceReviewResult(
                    "acceptance_review",
                    decision,
                    "one short sentence",
                    "ACCEPTED",
                    false,
                    List.of("review performed"),
                    List.of("specific acceptance evidence"),
                    List.of(),
                    List.of(),
                    List.of(),
                    List.of(),
                    List.of(),
                    "short verification adequacy summary",
                    emptyFailure()
            );
            case "stage.claude_handoff" -> new AgentResultEnvelope.StageHandoffResult(
                    "stage_handoff",
                    decision,
                    "one short sentence",
                    "READY",
                    List.of("completed work"),
                    List.of(),
                    List.of(),
                    "short verification state",
                    List.of(),
                    "next stage",
                    "next prompt"
            );
            default -> new AgentResultEnvelope.AgentOutputResult(
                    "agent_output_contract",
                    decision,
                    "one short sentence",
                    "READY",
                    false,
                    List.of("check or review performed"),
                    List.of("specific evidence"),
                    List.of(),
                    List.of(),
                    List.of(),
                    List.of(),
                    List.of(),
                    "short verification summary",
                    emptyFailure(),
                    List.of()
            );
        };
    }

    public static ProposalEmissionContext proposalEmissionContext(
            TaskContractRevisionContextResolver.Context context
    ) {
        if (context == null || !context.revision()) {
            return ProposalEmissionContext.initial();
        }
        if (context.previousReference() == null) {
            throw new IllegalArgumentException("revision proposal reference is required");
        }
        return new ProposalEmissionContext(
                EmissionMode.REVISION_PATCH,
                context.previousReference().proposalId(),
                context.previousReference().sha256(),
                List.copyOf(context.obligations()),
                context.lateRoot() == null ? "" : json(context.lateRoot())
                        + (context.scopeRevision() ? "\nSCOPE REVIEW ONLY: add only a subset of these bound CREATE candidates: "
                            + json(context.scopeReviewCandidates())
                            + ". Do not change clauses, evidence refs, objective, exclusions or any existing scope entry. "
                            + "These files already exist but remain CREATE relative to the original Git base. "
                            + "Respond to obligations using existing clause ids; keep clause_changes and evidence_ref_additions empty."
                            : ""));
    }

    public enum EmissionMode {
        INITIAL_FULL,
        REVISION_PATCH,
        NOT_APPLICABLE
    }

    public record ProposalEmissionContext(
            EmissionMode mode,
            String baseProposalId,
            String baseProposalSha256,
            List<AgentResultEnvelope.ReviewObligation> obligations,
            String acceptanceEvidence
    ) {
        public ProposalEmissionContext {
            obligations = obligations == null ? List.of() : List.copyOf(obligations);
            acceptanceEvidence = acceptanceEvidence == null ? "" : acceptanceEvidence;
        }

        public ProposalEmissionContext(EmissionMode mode, String baseProposalId, String baseProposalSha256,
                                       List<AgentResultEnvelope.ReviewObligation> obligations) {
            this(mode, baseProposalId, baseProposalSha256, obligations, "");
        }

        public static ProposalEmissionContext initial() {
            return new ProposalEmissionContext(EmissionMode.INITIAL_FULL, "", "", List.of());
        }

        public static ProposalEmissionContext notApplicable() {
            return new ProposalEmissionContext(EmissionMode.NOT_APPLICABLE, "", "", List.of());
        }

        boolean revision() {
            return mode == EmissionMode.REVISION_PATCH;
        }
    }

    private static AgentResultEnvelope.Failure emptyFailure() {
        return new AgentResultEnvelope.Failure("", AgentResultEnvelope.VerificationRemediation.NONE,
                List.of(), List.of(), List.of(), List.of(), "");
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.workflow.NodeDefinition;
