package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.contract.TaskContract;

import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Typed reader for agent output sidecars.
 *
 * Map-based JSON handling is kept at this boundary. Runtime routing,
 * classification, and human guidance should consume this record instead of
 * repeatedly reading stringly-typed fields from raw maps.
 */
public record AgentOutputContractDocument(
        String workstreamId,
        String runId,
        String nodeId,
        String nodeInstanceId,
        String stageOutcome,
        String lifecycleStatus,
        String decision,
        String summary,
        String sourceArtifactType,
        String sourceOutputRef,
        boolean blocking,
        List<String> checks,
        List<String> evidence,
        List<String> mustFix,
        List<AgentResultEnvelope.ReviewObligation> contractObligations,
        List<String> missingEvidence,
        List<String> acceptanceNotes,
        List<String> openRisks,
        List<String> changedFiles,
        String verificationSummary,
        List<String> completedWork,
        List<String> importantDecisions,
        String recommendedNextStage,
        String suggestedNextPrompt,
        Map<String, String> control,
        FailureFields failure,
        List<RereadReason> rereadReasons,
        TaskContractProposalReference reviewSubject,
        TaskContractProposal taskContractProposal,
        RepositoryFactBinding.Reference repositoryFactBinding,
        ProposalDerivation proposalDerivation,
        PlanArtifactDocument planArtifact,
        AgentResultEnvelope.Design design,
        List<AgentResultEnvelope.AuthoredRevisionResponse> authoredRevisionResponses,
        AuthoredExecutionContext.Reference authoredContext
) {
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    static Optional<AgentOutputContractDocument> read(Path path, ObjectMapper objectMapper) {
        try {
            return Optional.of(from(objectMapper.readValue(path.toFile(), MAP_TYPE)));
        } catch (IOException | RuntimeException e) {
            return Optional.empty();
        }
    }

    public static AgentOutputContractDocument from(Map<String, Object> document) {
        return new AgentOutputContractDocument(
                text(document.get("workstream_id")),
                text(document.get("run_id")),
                text(document.get("node_id")),
                text(document.get("node_instance_id")),
                firstNonBlank(document.get("stage_outcome"), document.get("lifecycle_status")),
                text(document.get("lifecycle_status")),
                text(document.get("decision")),
                text(document.get("summary")),
                text(document.get("source_artifact_type")),
                text(document.get("source_output_ref")),
                booleanValue(document.get("blocking")),
                firstNonEmptyList(document.get("checks"), document.get("checks_run")),
                stringList(document.get("evidence")),
                stringList(document.get("must_fix")),
                reviewObligationList(document.get("contract_obligations")),
                stringList(document.get("missing_evidence")),
                stringList(document.get("acceptance_notes")),
                stringList(document.get("open_risks")),
                stringList(document.get("changed_files")),
                text(document.get("verification_summary")),
                stringList(document.get("completed_work")),
                stringList(document.get("important_decisions")),
                text(document.get("recommended_next_stage")),
                text(document.get("suggested_next_prompt")),
                stringMap(document.get("control")),
                FailureFields.from(objectMap(document.get("failure"))),
                rereadReasonList(document.get("reread_reasons")),
                TaskContractProposalReference.fromMap(objectMap(document.get("review_subject"))).orElse(null),
                taskContractProposal(objectMap(document.get("task_contract_proposal"))),
                RepositoryFactBinding.Reference.fromMap(objectMap(document.get("repository_fact_binding"))),
                ProposalDerivation.from(objectMap(document.get("proposal_derivation"))),
                planArtifact(objectMap(document.get("plan_artifact"))),
                design(objectMap(document.get("design"))),
                authoredResponses(document.get("revision_responses")),
                authoredReference(document.get("authored_context"))
        );
    }

    public record ProposalDerivation(
            String kind,
            String baseProposalId,
            String baseProposalSha256,
            TaskContractProposalReference baseProposalReference,
            String patchSourceOutputRef
    ) {
        static ProposalDerivation from(Map<String, Object> document) {
            if (document.isEmpty()) {
                return null;
            }
            return new ProposalDerivation(
                    text(document.get("kind")),
                    text(document.get("base_proposal_id")),
                    text(document.get("base_proposal_sha256")),
                    TaskContractProposalReference.fromMap(
                            objectMap(document.get("base_proposal_reference"))).orElse(null),
                    text(document.get("patch_source_output_ref")));
        }

        boolean validFor(TaskContractProposalReference reference, String sourceOutputRef) {
            return "revision_patch_merge".equals(kind)
                    && reference != null
                    && reference.proposalId().equals(baseProposalId)
                    && reference.sha256().equals(baseProposalSha256)
                    && reference.equals(baseProposalReference)
                    && sourceOutputRef != null
                    && sourceOutputRef.equals(patchSourceOutputRef);
        }

        Map<String, Object> toMap() {
            var map = new LinkedHashMap<String, Object>();
            map.put("kind", kind);
            map.put("base_proposal_id", baseProposalId);
            map.put("base_proposal_sha256", baseProposalSha256);
            map.put("base_proposal_reference", baseProposalReference.toMap());
            map.put("patch_source_output_ref", patchSourceOutputRef);
            return Map.copyOf(map);
        }
    }

    public boolean hasValidatedLineage(String expectedWorkstreamId) {
        var normalizedSource = sourceOutputRef.replace('\\', '/');
        return expectedWorkstreamId != null
                && !expectedWorkstreamId.isBlank()
                && expectedWorkstreamId.equals(workstreamId)
                && !runId.isBlank()
                && !nodeId.isBlank()
                && !nodeInstanceId.isBlank()
                && normalizedSource.contains("/runs/" + runId + "/");
    }

    public boolean hasValidatedLineage(
            String expectedWorkstreamId,
            Path workspaceRoot,
            Path sidecarPath
    ) {
        if (!hasValidatedLineage(expectedWorkstreamId)
                || workspaceRoot == null
                || sidecarPath == null) {
            return false;
        }
        var root = workspaceRoot.toAbsolutePath().normalize();
        var source = root.resolve(sourceOutputRef).normalize();
        if (!source.startsWith(root)) {
            return false;
        }
        return AgentOutputContractSidecar.pathFor(source)
                .equals(sidecarPath.toAbsolutePath().normalize());
    }

    public boolean hasDecision() {
        return !decision.isBlank();
    }

    public String canonicalStageOutcome() {
        return stageOutcome.isBlank() ? lifecycleStatus : stageOutcome;
    }

    public boolean hasRequiredTypedPayload() {
        if (("design_result".equals(sourceArtifactType) || "plan_result".equals(sourceArtifactType))
                && !AuthoredRevisionValidator.shapeErrors(authoredRevisionResponses).isEmpty()) return false;
        if ("design_result".equals(sourceArtifactType)) {
            return DesignScopeValidator.shapeErrors(design).isEmpty();
        }
        if (!"plan_result".equals(sourceArtifactType)) {
            return true;
        }
        return planArtifact != null
                && "plan_artifact".equals(planArtifact.artifactType())
                && planArtifact.schemaVersion() == 1
                && planArtifact.missingRequiredField().isEmpty();
    }

    private static PlanArtifactDocument planArtifact(Map<String, Object> document) {
        return document.isEmpty() ? null : PlanArtifactDocument.from(document);
    }

    private static AuthoredExecutionContext.Reference authoredReference(Object value) {
        if (value == null) return null;
        return AuthoredExecutionContext.JSON.convertValue(value, AuthoredExecutionContext.Reference.class);
    }

    private static List<AgentResultEnvelope.AuthoredRevisionResponse> authoredResponses(Object value) {
        if (!(value instanceof List<?> values)) return null;
        var result = new ArrayList<AgentResultEnvelope.AuthoredRevisionResponse>();
        for (var entry : values) {
            var map = objectMap(entry);
            result.add(new AgentResultEnvelope.AuthoredRevisionResponse(text(map.get("obligation_id")),
                    AgentResultEnvelope.AuthoredRevisionDisposition.valueOf(text(map.get("disposition"))), text(map.get("evidence"))));
        }
        return List.copyOf(result);
    }

    private static AgentResultEnvelope.Design design(Map<String, Object> document) {
        if (!(document.get("planned_files") instanceof List<?> files)) {
            return null;
        }
        var planned = new ArrayList<AgentResultEnvelope.PlannedFile>();
        for (var value : files) {
            var file = objectMap(value);
            TaskContract.ScopeOperation operation = null;
            try {
                operation = TaskContract.ScopeOperation.valueOf(text(file.get("operation")));
            } catch (IllegalArgumentException ignored) {
                // Invalid operations remain invalid, never inferred from the path.
            }
            planned.add(new AgentResultEnvelope.PlannedFile(
                    file.get("path") instanceof String path ? path : null,
                    operation, file.get("responsibility") instanceof String responsibility ? responsibility : null));
        }
        return new AgentResultEnvelope.Design(List.copyOf(planned));
    }

    private static TaskContractProposal taskContractProposal(Map<String, Object> document) {
        if (document.isEmpty()) {
            return null;
        }
        var scope = objectMap(document.get("scope"));
        return new TaskContractProposal(
                text(document.get("artifact_type")),
                integerValue(document.get("schema_version")),
                text(document.get("objective")),
                new TaskContractProposal.Scope(
                        scopeEntries(scope.get("included")),
                        stringList(scope.get("excluded"))),
                contractClauseList(document.get("acceptance_criteria")),
                contractClauseList(document.get("test_requirements")),
                contractClauseList(document.get("constraints")),
                contractClauseList(document.get("non_goals")),
                contractClauseList(document.get("risk_areas")),
                stringList(document.get("evidence_refs")),
                stringList(document.get("open_questions")),
                revisionResponseList(document.get("revision_responses")));
    }

    private static List<TaskContract.ScopeEntry> scopeEntries(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var entries = new ArrayList<TaskContract.ScopeEntry>();
        for (var item : items) {
            var entry = objectMap(item);
            var path = text(entry.get("path"));
            TaskContract.ScopeOperation operation = null;
            try {
                operation = TaskContract.ScopeOperation.valueOf(text(entry.get("operation")));
            } catch (IllegalArgumentException ignored) {
                // The proposal validator reports the missing/invalid operation.
            }
            entries.add(new TaskContract.ScopeEntry(path, operation));
        }
        return List.copyOf(entries);
    }

    boolean isStageHandoffArtifact() {
        return "stage_handoff".equals(sourceArtifactType);
    }

    record FailureFields(
            String categoryHint,
            AgentResultEnvelope.VerificationRemediation verificationRemediation,
            List<String> contractGaps,
            List<String> outOfScopeFiles,
            List<String> missingTests,
            List<String> contextGaps,
            String reason
    ) {
        static FailureFields from(Map<String, Object> document) {
            return new FailureFields(
                    document.get("category_hint") instanceof String category ? category : "",
                    verificationRemediation(document.get("verification_remediation")),
                    stringList(document.get("contract_gaps")),
                    stringList(document.get("out_of_scope_files")),
                    stringList(document.get("missing_tests")),
                    stringList(document.get("context_gaps")),
                    text(document.get("reason"))
            );
        }

        static FailureFields empty() {
            return new FailureFields("", AgentResultEnvelope.VerificationRemediation.NONE,
                    List.of(), List.of(), List.of(), List.of(), "");
        }

        Map<String, Object> toMap() {
            var document = new LinkedHashMap<String, Object>();
            document.put("category_hint", categoryHint);
            document.put("verification_remediation", verificationRemediation == null
                    ? "" : verificationRemediation.name());
            document.put("contract_gaps", contractGaps);
            document.put("out_of_scope_files", outOfScopeFiles);
            document.put("missing_tests", missingTests);
            document.put("context_gaps", contextGaps);
            document.put("reason", reason);
            return document;
        }

        boolean isEmpty() {
            return categoryHint.isBlank()
                    && (verificationRemediation == null
                    || verificationRemediation == AgentResultEnvelope.VerificationRemediation.NONE)
                    && contractGaps.isEmpty()
                    && outOfScopeFiles.isEmpty()
                    && missingTests.isEmpty()
                    && contextGaps.isEmpty()
                    && reason.isBlank();
        }

        private static AgentResultEnvelope.VerificationRemediation verificationRemediation(Object value) {
            var text = value == null ? "" : String.valueOf(value);
            if (text.isEmpty()) {
                return null;
            }
            try {
                return AgentResultEnvelope.VerificationRemediation.valueOf(text);
            } catch (IllegalArgumentException invalid) {
                throw new IllegalArgumentException("Unknown verification_remediation: " + text, invalid);
            }
        }
    }

    /**
     * One declared reason an agent re-read a file already covered by the read-reuse
     * contract. Optional structured field; presence is validated against the
     * allowed-reason catalog (see {@code ReadReuseContractReasons}).
     */
    public record RereadReason(String path, String reason, String stage, String evidence) {
        static RereadReason from(Map<String, Object> document) {
            return new RereadReason(
                    text(document.get("path")),
                    text(document.get("reason")),
                    text(document.get("stage")),
                    text(document.get("evidence")));
        }

        Map<String, Object> toMap() {
            var map = new LinkedHashMap<String, Object>();
            map.put("path", path);
            map.put("reason", reason);
            map.put("stage", stage);
            map.put("evidence", evidence);
            return map;
        }
    }

    static List<RereadReason> rereadReasonList(Object value) {
        if (!(value instanceof List<?> list)) {
            return List.of();
        }
        var out = new ArrayList<RereadReason>();
        for (var item : list) {
            if (item instanceof Map<?, ?> map) {
                var copy = new LinkedHashMap<String, Object>();
                for (var e : map.entrySet()) {
                    if (e.getKey() instanceof String key) {
                        copy.put(key, e.getValue());
                    }
                }
                out.add(RereadReason.from(copy));
            }
        }
        return List.copyOf(out);
    }

    private static List<TaskContractProposal.ContractClause> contractClauseList(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var clauses = new ArrayList<TaskContractProposal.ContractClause>();
        for (var item : items) {
            var document = objectMap(item);
            if (!document.isEmpty()) {
                clauses.add(new TaskContractProposal.ContractClause(
                        text(document.get("id")), text(document.get("text"))));
            }
        }
        return List.copyOf(clauses);
    }

    private static List<TaskContractProposal.RevisionResponse> revisionResponseList(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var responses = new ArrayList<TaskContractProposal.RevisionResponse>();
        for (var item : items) {
            var document = objectMap(item);
            if (!document.isEmpty()) {
                responses.add(new TaskContractProposal.RevisionResponse(
                        text(document.get("review_obligation_id")),
                        stringList(document.get("resolved_by_clause_ids"))));
            }
        }
        return List.copyOf(responses);
    }

    private static List<AgentResultEnvelope.ReviewObligation> reviewObligationList(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var obligations = new ArrayList<AgentResultEnvelope.ReviewObligation>();
        for (var item : items) {
            var document = objectMap(item);
            if (!document.isEmpty()) {
                obligations.add(new AgentResultEnvelope.ReviewObligation(
                        text(document.get("id")), text(document.get("text"))));
            }
        }
        return List.copyOf(obligations);
    }

    private static List<String> stringList(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var result = new ArrayList<String>();
        for (var item : items) {
            var text = text(item);
            if (!text.isBlank()) {
                result.add(text);
            }
        }
        return List.copyOf(result);
    }

    private static List<String> firstNonEmptyList(Object first, Object second) {
        var firstList = stringList(first);
        return firstList.isEmpty() ? stringList(second) : firstList;
    }

    private static Map<String, String> stringMap(Object value) {
        if (!(value instanceof Map<?, ?> source)) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, String>();
        for (var entry : source.entrySet()) {
            if (entry.getKey() != null && entry.getValue() != null) {
                copy.put(String.valueOf(entry.getKey()), String.valueOf(entry.getValue()));
            }
        }
        return copy;
    }

    private static Map<String, Object> objectMap(Object value) {
        if (!(value instanceof Map<?, ?> source)) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, Object>();
        for (var entry : source.entrySet()) {
            if (entry.getKey() instanceof String key) {
                copy.put(key, entry.getValue());
            }
        }
        return copy;
    }

    private static boolean booleanValue(Object value) {
        if (value instanceof Boolean bool) {
            return bool;
        }
        return Boolean.parseBoolean(text(value));
    }

    private static int integerValue(Object value) {
        if (value instanceof Number number) {
            return number.intValue();
        }
        try {
            return Integer.parseInt(text(value));
        } catch (NumberFormatException ignored) {
            return 0;
        }
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    private static String firstNonBlank(Object first, Object second) {
        var firstText = text(first);
        return firstText.isBlank() ? text(second) : firstText;
    }
}

package dev.dual.runtime.handler;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;

/** Checks response shape and exact coverage, never whether the claimed repair is correct. */
final class AuthoredRevisionValidator {
    private AuthoredRevisionValidator() { }

    static List<String> shapeErrors(List<AgentResultEnvelope.AuthoredRevisionResponse> responses) {
        var errors = new ArrayList<String>();
        if (responses == null) {
            return List.of("AUTHORED_RESPONSES_MISSING: result.revision_responses must be explicit");
        }
        var ids = new HashSet<String>();
        for (int index = 0; index < responses.size(); index++) {
            var response = responses.get(index);
            if (response == null || !validId(response.obligationId())) {
                errors.add(invalidIdMessage(index, response == null ? null : response.obligationId()));
                continue;
            }
            if (!ids.add(response.obligationId())) errors.add("AUTHORED_RESPONSE_DUPLICATE");
            if (response.disposition() == null) errors.add("AUTHORED_RESPONSE_DISPOSITION_MISSING");
            if (response.evidence() == null || response.evidence().isBlank()) errors.add("AUTHORED_RESPONSE_EVIDENCE_MISSING");
        }
        return List.copyOf(errors);
    }

    static String invalidIdMessage(int index, String id) {
        return "AUTHORED_RESPONSE_ID_INVALID: index=" + index + ", length=" + (id == null ? "missing" : id.length())
                + ", expected sha256:<64 lowercase hex>#must_fix:<index> or #human-note:0";
    }

    private static boolean validId(String id) {
        return id != null && id.matches("sha256:[0-9a-f]{64}#(?:must_fix:[0-9]+|human-note:0)");
    }

    static List<Integer> repairableReferenceIndexes(List<AgentResultEnvelope.AuthoredRevisionResponse> responses,
                                                    List<String> activeIds) {
        if (responses == null || responses.isEmpty() || activeIds == null || responses.size() != activeIds.size()
                || activeIds.stream().anyMatch(id -> !validId(id))
                || new HashSet<>(activeIds).size() != activeIds.size()) return List.of();
        var seen = new HashSet<String>();
        var indexes = new ArrayList<Integer>();
        for (int index = 0; index < responses.size(); index++) {
            var response = responses.get(index);
            if (response == null || response.obligationId() == null || response.obligationId().isBlank()
                    || response.disposition() == null || response.evidence() == null || response.evidence().isBlank()
                    || !seen.add(response.obligationId())) return List.of();
            if (!validId(response.obligationId())) indexes.add(index);
            else if (!activeIds.contains(response.obligationId())) return List.of();
        }
        return List.copyOf(indexes);
    }

    static List<String> validate(List<AgentResultEnvelope.AuthoredRevisionResponse> responses, List<String> activeIds) {
        var errors = new ArrayList<>(shapeErrors(responses));
        if (!errors.isEmpty()) return List.copyOf(errors);
        var actual = new HashSet<String>();
        responses.forEach(response -> actual.add(response.obligationId()));
        if (!actual.equals(new HashSet<>(activeIds))) errors.add("AUTHORED_RESPONSE_COVERAGE_MISMATCH");
        return List.copyOf(errors);
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.workflow.NodeKind;

import java.util.List;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Function;

public final class HandlerRegistry {
    private final Map<String, TaskHandler> taskHandlers;
    private final Map<String, DecisionHandler> decisionHandlers;
    private final Map<String, GateHandler> gateHandlers;

    public HandlerRegistry(
            List<TaskHandler> taskHandlers,
            List<DecisionHandler> decisionHandlers,
            List<GateHandler> gateHandlers
    ) {
        this.taskHandlers = index(taskHandlers == null ? List.of() : taskHandlers, TaskHandler::type);
        this.decisionHandlers = index(decisionHandlers == null ? List.of() : decisionHandlers, DecisionHandler::type);
        this.gateHandlers = index(gateHandlers == null ? List.of() : gateHandlers, GateHandler::type);
    }

    public Object resolve(NodeKind kind, String type) {
        if (kind == null) {
            throw new IllegalArgumentException("kind is required");
        }
        return switch (kind) {
            case TASK -> task(type);
            case DECISION -> decision(type);
            case GATE -> gate(type);
        };
    }

    public TaskHandler task(String type) {
        var handler = taskHandlers.get(requiredType(type));
        if (handler == null) {
            throw new IllegalArgumentException("missing handler: " + type);
        }
        return handler;
    }

    public DecisionHandler decision(String type) {
        var handler = decisionHandlers.get(requiredType(type));
        if (handler == null) {
            throw new IllegalArgumentException("missing handler: " + type);
        }
        return handler;
    }

    public GateHandler gate(String type) {
        var handler = gateHandlers.get(requiredType(type));
        if (handler == null) {
            throw new IllegalArgumentException("missing handler: " + type);
        }
        return handler;
    }

    private static String requiredType(String type) {
        if (type == null || type.isBlank()) {
            throw new IllegalArgumentException("handler type is required");
        }
        return type;
    }

    private static <T> Map<String, T> index(List<T> handlers, Function<T, String> typeExtractor) {
        var indexed = new LinkedHashMap<String, T>();
        for (T handler : handlers) {
            if (handler == null) {
                throw new IllegalArgumentException("handler is required");
            }
            var type = requiredType(typeExtractor.apply(handler));
            if (indexed.containsKey(type)) {
                throw new IllegalArgumentException("duplicate handler: " + type);
            }
            indexed.put(type, handler);
        }
        return Map.copyOf(indexed);
    }
}

package dev.dual.runtime.handler;

import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Projects one validated agent result into the existing durable read models. */
final class AgentResultDocumentProjector {
    Map<String, Object> outputContract(
            AgentResultEnvelope envelope,
            NodeOutputContract contract,
            String handlerType,
            String nodeInstanceId,
            String sourceOutputRef
    ) {
        return outputContract(envelope, contract, handlerType, nodeInstanceId, sourceOutputRef, null, null);
    }

    Map<String, Object> outputContract(
            AgentResultEnvelope envelope,
            NodeOutputContract contract,
            String handlerType,
            String nodeInstanceId,
            String sourceOutputRef,
            TaskContractProposal resolvedProposal,
            AgentOutputContractDocument.ProposalDerivation derivation
    ) {
        var result = envelope.result();
        var document = new LinkedHashMap<String, Object>();
        document.put("artifact_type", "agent_output_contract");
        document.put("schema_version", 1);
        document.put("workstream_id", envelope.workstreamId());
        document.put("run_id", envelope.runId());
        document.put("node_id", envelope.nodeId());
        document.put("node_instance_id", nodeInstanceId == null ? "" : nodeInstanceId);
        document.put("handler_type", handlerType);
        document.put("decision", result.decision());
        document.put("summary", result.summary());
        document.put("required_keys", List.copyOf(contract.requiredKeys()));
        document.put("allowed_decisions", List.copyOf(contract.allowedDecisions()));
        document.put("source_output_ref", sourceOutputRef);
        document.put("source_artifact_type", result.artifactType());
        document.put("generated_at", Instant.now().toString());
        document.put("control", Map.of("decision", result.decision(), "summary", result.summary()));
        document.put("control_source", Map.of("kind", "strict_agent_result_envelope"));

        switch (result) {
            case AgentResultEnvelope.TaskContractProposalResult ignored -> {
                if (resolvedProposal == null) {
                    throw new IllegalStateException("initial proposal must be scope-resolved before projection");
                }
                evidenceDefaults(document);
                document.put("task_contract_proposal", taskContractProposalMap(resolvedProposal));
            }
            case AgentResultEnvelope.TaskContractRevisionPatchResult ignored -> {
                if (resolvedProposal == null || derivation == null) {
                    throw new IllegalStateException("revision patch must be merged before projection");
                }
                evidenceDefaults(document);
                document.put("task_contract_proposal", taskContractProposalMap(resolvedProposal));
                document.put("proposal_derivation", derivation.toMap());
            }
            case AgentResultEnvelope.AgentOutputResult output -> {
                evidenceFields(document, output.lifecycleStatus(), output.blocking(), output.checks(), output.evidence(),
                        output.missingEvidence(), output.mustFix(), output.acceptanceNotes(), output.openRisks(),
                        output.changedFiles(), output.verificationSummary(), output.failure());
                document.put("contract_obligations", safeList(output.contractObligations()).stream()
                        .map(obligation -> Map.of("id", obligation.id(), "text", obligation.text()))
                        .toList());
                document.put("reread_reasons", output.rereadReasons().stream().map(this::rereadReason).toList());
            }
            case AgentResultEnvelope.DesignResult design -> {
                document.put("revision_responses", authoredResponses(design.revisionResponses()));
                document.put("lifecycle_status", design.lifecycleStatus());
                document.put("checks", design.checks());
                document.put("evidence", design.evidence());
                document.put("missing_evidence", design.missingEvidence());
                document.put("must_fix", design.mustFix());
                document.put("open_risks", design.openRisks());
                document.put("verification_summary", design.verificationSummary());
                document.put("design", Map.of("planned_files", design.design().plannedFiles().stream()
                        .map(file -> Map.of("path", file.path(), "operation", file.operation().name(),
                                "responsibility", file.responsibility())).toList()));
            }
            case AgentResultEnvelope.PlanResult plan -> {
                document.put("revision_responses", authoredResponses(plan.revisionResponses()));
                evidenceFields(
                        document, plan.lifecycleStatus(), plan.blocking(), plan.checks(), plan.evidence(),
                        plan.missingEvidence(), plan.mustFix(), plan.acceptanceNotes(), plan.openRisks(),
                        plan.changedFiles(), plan.verificationSummary(), plan.failure());
                document.put("plan_artifact", planArtifact(plan));
            }
            case AgentResultEnvelope.SelfTestResult selfTest -> {
                document.put("lifecycle_status", selfTest.lifecycleStatus());
                document.put("blocking", false);
                document.put("checks_run", selfTest.checksRun());
                document.put("checks_skipped", selfTest.checksSkipped());
                document.put("evidence", selfTest.evidence());
                document.put("missing_evidence", selfTest.missingEvidence());
                document.put("must_fix", selfTest.mustFix());
                document.put("acceptance_notes", selfTest.acceptanceNotes());
                document.put("verification_summary", selfTest.verificationSummary());
                evidenceDefaultsIfAbsent(document);
            }
            case AgentResultEnvelope.AcceptanceReviewResult review -> evidenceFields(
                    document, review.lifecycleStatus(), review.blocking(), review.checks(), review.evidence(),
                    review.missingEvidence(), review.mustFix(), review.acceptanceNotes(), review.openRisks(),
                    review.changedFiles(), review.verificationSummary(), review.failure());
            case AgentResultEnvelope.StageHandoffResult handoff -> {
                document.put("lifecycle_status", handoff.lifecycleStatus());
                document.put("blocking", false);
                document.put("completed_work", handoff.completedWork());
                document.put("important_decisions", handoff.importantDecisions());
                document.put("changed_files", handoff.changedFiles());
                document.put("verification_summary", handoff.verificationState());
                document.put("open_risks", handoff.openRisks());
                document.put("recommended_next_stage", handoff.recommendedNextStage());
                document.put("suggested_next_prompt", handoff.suggestedNextPrompt());
                evidenceDefaultsIfAbsent(document);
            }
        }
        return document;
    }

    private Map<String, Object> taskContractProposalMap(TaskContractProposal proposal) {
        var document = new LinkedHashMap<String, Object>();
        document.put("artifact_type", proposal.artifactType());
        document.put("schema_version", proposal.schemaVersion());
        document.put("objective", proposal.objective());
        document.put("scope", Map.of(
                "included", proposal.scope().included().stream()
                        .map(entry -> Map.of("path", entry.path(), "operation", entry.operation().name()))
                        .toList(),
                "excluded", proposal.scope().excluded()));
        document.put("acceptance_criteria", clauseMapsFromProposal(proposal.acceptanceCriteria()));
        document.put("test_requirements", clauseMapsFromProposal(proposal.testRequirements()));
        document.put("constraints", clauseMapsFromProposal(proposal.constraints()));
        document.put("non_goals", clauseMapsFromProposal(proposal.nonGoals()));
        document.put("risk_areas", clauseMapsFromProposal(proposal.riskAreas()));
        document.put("evidence_refs", proposal.evidenceRefs());
        document.put("open_questions", proposal.openQuestions());
        document.put("revision_responses", proposal.revisionResponses().stream()
                .map(response -> Map.of(
                        "review_obligation_id", response.reviewObligationId(),
                        "resolved_by_clause_ids", response.resolvedByClauseIds()))
                .toList());
        return document;
    }

    private static List<Map<String, String>> clauseMapsFromProposal(
            List<TaskContractProposal.ContractClause> clauses
    ) {
        return safeList(clauses).stream()
                .map(clause -> Map.of("id", clause.id(), "text", clause.text()))
                .toList();
    }

    TaskContractProposal taskContractProposal(
            AgentResultEnvelope.TaskContractProposalResult result,
            List<dev.dual.core.contract.TaskContract.ScopeEntry> resolvedScope
    ) {
        return new TaskContractProposal(
                result.artifactType(),
                TaskContractProposal.SCHEMA_VERSION,
                result.objective(),
                new TaskContractProposal.Scope(resolvedScope, result.scope().excluded()),
                proposalClauses(result.acceptanceCriteria()),
                proposalClauses(result.testRequirements()),
                proposalClauses(result.constraints()),
                proposalClauses(result.nonGoals()),
                proposalClauses(result.riskAreas()),
                result.evidenceRefs(),
                result.openQuestions(),
                revisionResponses(result.revisionResponses())
        );
    }

    private static List<TaskContractProposal.ContractClause> proposalClauses(
            List<AgentResultEnvelope.ContractClause> clauses
    ) {
        return safeList(clauses).stream()
                .map(clause -> new TaskContractProposal.ContractClause(clause.id(), clause.text()))
                .toList();
    }

    private static List<TaskContractProposal.RevisionResponse> revisionResponses(
            List<AgentResultEnvelope.RevisionResponse> responses
    ) {
        return safeList(responses).stream()
                .map(response -> new TaskContractProposal.RevisionResponse(
                        response.reviewObligationId(), response.resolvedByClauseIds()))
                .toList();
    }

    private static List<Map<String, String>> clauseMaps(List<AgentResultEnvelope.ContractClause> clauses) {
        return safeList(clauses).stream()
                .map(clause -> Map.of("id", clause.id(), "text", clause.text()))
                .toList();
    }

    private static <T> List<T> safeList(List<T> values) {
        return values == null ? List.of() : values;
    }

    private List<Map<String, String>> authoredResponses(List<AgentResultEnvelope.AuthoredRevisionResponse> responses) {
        return responses.stream().map(response -> Map.of("obligation_id", response.obligationId(),
                "disposition", response.disposition().name(), "evidence", response.evidence())).toList();
    }

    Map<String, Object> planArtifact(AgentResultEnvelope.PlanResult result) {
        var plan = result.plan();
        var document = new LinkedHashMap<String, Object>();
        document.put("artifact_type", "plan_artifact");
        document.put("schema_version", 1);
        document.put("implementation_steps", plan.implementationSteps());
        document.put("edit_files", plan.editFiles());
        document.put("reference_files", plan.referenceFiles());
        document.put("file_level_changes", plan.fileLevelChanges());
        document.put("validation_plan", plan.validationPlan());
        document.put("rollback_notes", plan.rollbackNotes());
        document.put("known_risks", plan.knownRisks());
        document.put("human_review_checklist", plan.humanReviewChecklist());
        return document;
    }

    private void evidenceFields(
            Map<String, Object> document,
            String lifecycleStatus,
            boolean blocking,
            List<String> checks,
            List<String> evidence,
            List<String> missingEvidence,
            List<String> mustFix,
            List<String> acceptanceNotes,
            List<String> openRisks,
            List<String> changedFiles,
            String verificationSummary,
            AgentResultEnvelope.Failure failure
    ) {
        document.put("lifecycle_status", lifecycleStatus);
        document.put("blocking", blocking);
        document.put("checks", checks);
        document.put("evidence", evidence);
        document.put("missing_evidence", missingEvidence);
        document.put("must_fix", mustFix);
        document.put("acceptance_notes", acceptanceNotes);
        document.put("open_risks", openRisks);
        document.put("changed_files", changedFiles);
        document.put("verification_summary", verificationSummary);
        document.put("failure", failure(failure));
        document.put("checks_run", List.of());
        document.put("checks_skipped", List.of());
    }

    private static void evidenceDefaults(Map<String, Object> document) {
        document.put("blocking", false);
        document.put("checks_run", List.of("task_contract_proposal mechanical validation"));
        document.put("checks_skipped", List.of());
        document.put("evidence", List.of("canonical task_contract_proposal result"));
        document.put("missing_evidence", List.of());
        document.put("must_fix", List.of());
        document.put("acceptance_notes", List.of());
        document.put("open_risks", List.of());
        document.put("changed_files", List.of());
        document.put("verification_summary", "task contract proposal validated");
        document.put("failure", Map.of());
    }

    private static void evidenceDefaultsIfAbsent(Map<String, Object> document) {
        document.putIfAbsent("checks", List.of());
        document.putIfAbsent("checks_run", List.of());
        document.putIfAbsent("checks_skipped", List.of());
        document.putIfAbsent("evidence", List.of());
        document.putIfAbsent("missing_evidence", List.of());
        document.putIfAbsent("must_fix", List.of());
        document.putIfAbsent("acceptance_notes", List.of());
        document.putIfAbsent("open_risks", List.of());
        document.putIfAbsent("changed_files", List.of());
        document.putIfAbsent("failure", Map.of());
    }

    private Map<String, Object> failure(AgentResultEnvelope.Failure value) {
        if (value == null) {
            return Map.of();
        }
        var failure = new LinkedHashMap<String, Object>();
        failure.put("category_hint", value.categoryHint());
        failure.put("verification_remediation", value.verificationRemediation() == null
                ? "" : value.verificationRemediation().name());
        failure.put("contract_gaps", value.contractGaps());
        failure.put("out_of_scope_files", value.outOfScopeFiles());
        failure.put("missing_tests", value.missingTests());
        failure.put("context_gaps", value.contextGaps());
        failure.put("reason", value.reason());
        return failure;
    }

    private Map<String, Object> rereadReason(AgentResultEnvelope.RereadReason value) {
        var reason = new LinkedHashMap<String, Object>();
        reason.put("path", value.path());
        reason.put("reason", value.reason());
        reason.put("stage", value.stage());
        reason.put("evidence", value.evidence());
        return reason;
    }

}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.*;
import dev.dual.ledger.file.*;
import java.io.IOException;
import java.nio.file.*;
import java.util.*;

/** Human-approved source identity for evidence collection, shared by inline and queued execution. */
public final class EvidenceCollection {
    public static final String FAILURE = "EVIDENCE_COLLECTION_SOURCE_INVALID";
    private static final ObjectMapper MAPPER = new ObjectMapper().findAndRegisterModules();
    private EvidenceCollection() {}

    /** CLI/API already hold the workstream lock; ordinary decisions retain their existing semantics. */
    public static void resolveGate(WorkflowFileLedger ledger, WorkstreamPaths paths, WorkflowDefinition definition,
                                   String action, String note) throws IOException {
        if (!HumanGateActionSemantics.COLLECT_EVIDENCE.equals(action)) {
            ledger.resolveOpenGate(paths, definition, action, note);
            return;
        }
        if (note == null || note.isBlank()) throw new IOException("collection requires an explicit note");
        var baseline = captureBaseline(ledger, paths, definition, action);
        ledger.collectEvidence(paths, definition, note, baseline);
    }

    static EvidenceCollectionBaseline captureBaseline(WorkflowFileLedger ledger, WorkstreamPaths paths,
                                                       WorkflowDefinition definition, String action) throws IOException {
        var current = ledger.loadCurrent(paths);
        if (current.status() != WorkflowStatus.WAITING_FOR_HUMAN || current.activeNodeInstanceIds().size() != 1
                ) throw new IOException("collection requires a waiting human gate");
        var node = ledger.loadNode(paths, current.activeNodeInstanceIds().getFirst());
        var gate = ledger.loadOpenGateForNode(paths, node.nodeInstanceId());
        if (gate == null || !HumanGateActionSemantics.allowedActions(definition.node(node.nodeDefinitionId()),
                String.valueOf(gate.result().get("source_outcome"))).contains(action))
            throw new IOException("collection is not available at this gate");
        var resolution = TaskContractProjectionVerifier.resolve(paths.workspaceRoot(), paths.workstreamId().value());
        var qualified = resolution.qualified().orElseThrow(() -> new IOException(
                "collection requires a qualified approved task contract: " + resolution.failure()));
        var included = qualified.contract().scope().included().stream().map(entry -> entry.path()).toList();
        var source = EvidenceCollectionSource.capture(paths.workspaceRoot(), included);
        var baseline = new EvidenceCollectionBaseline(node.nodeInstanceId(), qualified.contractRef(), qualified.sha256(),
                source.head(), source.indexSha256(), source.sha256(), source.paths());
        verifySource(paths.workspaceRoot(), baseline);
        return baseline;
    }

    @FunctionalInterface public interface Execution { NodeResult run() throws Exception; }

    /** Advisory projection only; execute() and publication validation own enforcement. */
    public static Optional<String> promptInstruction(Path root, String workstreamId, String nodeId) throws IOException {
        var file = new WorkstreamPaths(root, new DualId(workstreamId)).nodeJson(nodeId);
        if (!Files.isRegularFile(file)
                || !MAPPER.readTree(file.toFile()).path("inputTransition").has("evidence_collection_gate")) return Optional.empty();
        var refs = requiredReferences(root, workstreamId, nodeId);
        return Optional.of("This occurrence collects evidence against a human-approved source baseline. "
                + "Do not modify product source, tests, dependencies, or Git state. "
                + "Write evidence only to the designated run artifacts. If verification needs a code change, "
                + "report the concrete must_fix or missing_evidence instead of implementing it."
                + (refs.isEmpty() ? "" : "\nExternal verification materials (operator-declared execution, not automatic proof of success):\n"
                + String.join("\n", refs) + "\nRead these exact files. Include each exact ref as a separate string in result.evidence. "
                + "Assess their relevance and sufficiency; missing or failed verification must remain incomplete/rejected. "
                + "Do not replace refs with summaries or treat a submission as approval."));
    }

    static List<String> requiredReferences(Path root, String workstreamId, String nodeId) throws IOException {
        var paths = new WorkstreamPaths(root, new DualId(workstreamId));
        if (!Files.isRegularFile(paths.nodeJson(nodeId))) return List.of();
        var guard = open(root, workstreamId, MAPPER.readValue(paths.nodeJson(nodeId).toFile(), NodeInstanceDocument.class));
        return guard == null || guard.submission() == null ? List.of() : ExternalVerificationEvidence.refs(paths, guard.submission());
    }

    static void verifyResult(Path root, String workstreamId, String nodeId, AgentResultEnvelope.AgentResult result) throws IOException {
        var refs = requiredReferences(root, workstreamId, nodeId);
        if (refs.isEmpty()) return;
        List<String> evidence = result instanceof AgentResultEnvelope.SelfTestResult self ? self.evidence()
                : result instanceof AgentResultEnvelope.AcceptanceReviewResult acceptance ? acceptance.evidence() : null;
        if ((result instanceof AgentResultEnvelope.SelfTestResult || result instanceof AgentResultEnvelope.AcceptanceReviewResult)
                && (evidence == null || !evidence.containsAll(refs)))
            throw new IOException("result.evidence must contain every exact bound material ref");
    }

    public static NodeResult execute(Path root, String workstreamId, NodeInstanceDocument node, Execution execution)
            throws Exception {
        Guard guard;
        try { guard = open(root, workstreamId, node); }
        catch (IOException | IllegalArgumentException invalid) { return rejected(invalid); }
        if (guard == null) return execution.run();
        NodeResult result;
        try { result = execution.run(); }
        catch (Exception failure) {
            try { guard.verify(); }
            catch (IOException | IllegalArgumentException invalid) { return rejected(invalid); }
            throw failure;
        }
        try { guard.verify(); }
        catch (IOException | IllegalArgumentException invalid) { return rejected(invalid); }
        return result;
    }

    /** Recheck at sidecar publication too, including cold or direct validator calls. */
    static void verify(Path root, String workstreamId, String nodeId) throws IOException {
        var paths = new WorkstreamPaths(root, new DualId(workstreamId));
        var file = paths.nodeJson(nodeId);
        if (!Files.isRegularFile(file)) return; // Ordinary standalone validators have no ledger occurrence.
        open(root, workstreamId, MAPPER.readValue(file.toFile(), NodeInstanceDocument.class));
    }

    static Guard open(Path root, String workstreamId, NodeInstanceDocument node) throws IOException {
        var transition = node.inputTransition();
        var id = transition.get("evidence_collection_gate");
        var sha = transition.get("evidence_collection_gate_sha256");
        var paths = new WorkstreamPaths(root, new DualId(workstreamId));
        // A cold retry must not silently become ordinary self-test if its marker was removed.
        if (Files.isRegularFile(paths.eventsJsonl())) {
            try (var lines = Files.lines(paths.eventsJsonl())) {
                for (var iterator = lines.iterator(); iterator.hasNext();) {
                    var line = iterator.next();
                    if (line.isBlank()) continue;
                    var event = MAPPER.readTree(line);
                    if (!"node_routed".equals(event.path("event_type").asText())
                            || !node.nodeInstanceId().equals(event.path("payload").path("node_instance_id").asText())) continue;
                    var routed = event.path("payload").path("transition");
                    var routedId = routed.path("evidence_collection_gate").isMissingNode() ? null
                            : routed.path("evidence_collection_gate").asText();
                    var routedSha = routed.path("evidence_collection_gate_sha256").isMissingNode() ? null
                            : routed.path("evidence_collection_gate_sha256").asText();
                    if (!Objects.equals(id, routedId) || !Objects.equals(sha, routedSha))
                        throw new IOException("collection transition differs from its persisted route");
                }
            }
        }
        if (id == null && sha == null) return null;
        if (!(id instanceof String gateId) || !gateId.matches("[A-Za-z0-9._-]+")
                || !(sha instanceof String hash) || !hash.matches("[0-9a-f]{64}"))
            throw new IOException("invalid collection approval reference");
        var file = paths.nodeJson(gateId);
        requireCanonical(root, file);
        if (!hash.equals(TaskContractArtifactWriter.sha256(file))) throw new IOException("collection approval changed");
        var approval = MAPPER.readValue(file.toFile(), NodeInstanceDocument.class);
        if (!gateId.equals(approval.nodeInstanceId()) || approval.kind() != NodeKind.GATE
                || approval.status() != NodeStatus.COMPLETED
                || !("collect_evidence".equals(approval.result().get("human_action"))
                || "submit_evidence".equals(approval.result().get("human_action")))
                || !(approval.result().get("note") instanceof String note) || note.isBlank())
            throw new IOException("collection approval is not a completed human decision");
        var gateFile = paths.gateJson("gate-" + gateId);
        requireCanonical(root, gateFile);
        var gate = MAPPER.readValue(gateFile.toFile(), GateDocument.class);
        if (!"resolved".equals(gate.status()) || !gateId.equals(gate.nodeInstanceId())
                || !Objects.equals(approval.result().get("human_action"), gate.result().get("human_action"))
                || !Objects.equals(gate.result().get("note"), approval.result().get("note"))
                || !Objects.equals(gate.result().get("subject_input_refs"), approval.inputRefs()))
            throw new IOException("collection gate resolution is missing");
        var baseline = MAPPER.convertValue(approval.result().get("evidence_collection_baseline"), EvidenceCollectionBaseline.class);
        if (baseline == null || !gateId.equals(baseline.gateNodeInstanceId()))
            throw new IOException("collection source baseline is missing");
        var submission = MAPPER.convertValue(approval.result().get("external_evidence"), EvidenceSubmission.class);
        if ("submit_evidence".equals(approval.result().get("human_action")) != (submission != null)
                || (submission != null && !baseline.equals(submission.baseline())))
            throw new IOException("missing or inconsistent external material binding");
        var guard = new Guard(root, paths, file, hash, gateFile, TaskContractArtifactWriter.sha256(gateFile),
                node.nodeInstanceId(), baseline, submission);
        guard.verify();
        return guard;
    }

    record Guard(Path root, WorkstreamPaths paths, Path approvalFile, String approvalSha, Path gateFile,
                 String gateSha, String nodeId, EvidenceCollectionBaseline baseline, EvidenceSubmission submission) {
        void verify() throws IOException {
            requireCanonical(root, approvalFile);
            if (!approvalSha.equals(TaskContractArtifactWriter.sha256(approvalFile)))
                throw new IOException("collection approval changed during execution");
            requireCanonical(root, gateFile);
            if (!gateSha.equals(TaskContractArtifactWriter.sha256(gateFile)))
                throw new IOException("collection gate changed during execution");
            var node = MAPPER.readValue(paths.nodeJson(nodeId).toFile(), NodeInstanceDocument.class);
            if (!baseline.gateNodeInstanceId().equals(node.inputTransition().get("evidence_collection_gate"))
                    || !approvalSha.equals(node.inputTransition().get("evidence_collection_gate_sha256")))
                throw new IOException("collection execution lost its approval binding");
            if (!baseline.contractRef().equals(".agent/workstreams/" + paths.workstreamId().value() + "/artifacts/task-contract.json"))
                throw new IOException("collection contract belongs to another workstream");
            verifySource(root, baseline);
            if (submission != null) {
                var manifest = ExternalVerificationEvidence.verify(paths, submission);
                var approval = MAPPER.readValue(approvalFile.toFile(), NodeInstanceDocument.class);
                if (!manifest.note().equals(approval.result().get("note"))) throw new IOException("material note mismatch");
            }
        }
    }

    static void verifySource(Path root, EvidenceCollectionBaseline baseline) throws IOException {
        var contract = root.resolve(baseline.contractRef());
        requireCanonical(root, contract);
        if (!baseline.contractSha256().equals(TaskContractArtifactWriter.sha256(contract)))
            throw new IOException("collection approved contract changed");
        var actual = EvidenceCollectionSource.capture(root, baseline.paths());
        if (!actual.head().equals(baseline.head()) || !actual.indexSha256().equals(baseline.indexSha256())
                || !actual.paths().equals(baseline.paths()) || !actual.sha256().equals(baseline.sourceSha256()))
            throw new IOException("product source differs from the human-approved collection baseline");
    }

    private static void requireCanonical(Path root, Path file) throws IOException {
        if (!file.toRealPath().equals(root.toRealPath().resolve(root.toAbsolutePath().normalize().relativize(file.toAbsolutePath().normalize()))))
            throw new IOException("noncanonical collection authority path");
    }

    private static NodeResult rejected(Exception invalid) {
        return new NodeResult(FAILURE, NodeStatus.FAILED, List.of(),
                Map.of("failure_code", FAILURE, "error", String.valueOf(invalid.getMessage())), invalid.getMessage());
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.workflow.*;
import dev.dual.ledger.file.*;
import java.io.IOException;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;

/** Explicit operator material ingestion. No execution, approval inference, or directory discovery. */
public final class ExternalVerificationEvidence {
    private static final ObjectMapper JSON = new ObjectMapper().findAndRegisterModules();
    private static final int FILE_LIMIT = 8 * 1024 * 1024;
    private static final int TOTAL_LIMIT = 32 * 1024 * 1024;
    public record Reference(String ref, String sha256) {}
    public record Preparation(EvidenceCollectionBaseline baseline, Instant recordedAt) {}
    public record Declaration(String command, String environment, Instant startedAt, Instant finishedAt,
                              int exitCode, String purpose) {
        public Declaration {
            if (blank(command) || blank(environment) || blank(purpose) || startedAt == null || finishedAt == null
                    || finishedAt.isBefore(startedAt)) throw new IllegalArgumentException("complete execution declaration required");
        }
    }
    public record Material(String ref, String sha256, long size, String name) {}
    public record Manifest(String requestId, Reference preparation, EvidenceCollectionBaseline baseline,
                           Declaration declaredExecution, String note, List<Material> materials) {}
    private ExternalVerificationEvidence() {}

    public static Reference prepare(WorkflowFileLedger ledger, WorkstreamPaths paths) throws IOException {
        try (var lock = WorkstreamLock.acquire(paths.workstreamDir(), LockOwner.currentProcess(paths.workstreamId().value(), "prepare evidence"))) {
            var baseline = EvidenceCollection.captureBaseline(ledger, paths, ledger.loadDefinition(paths), "submit_evidence");
            return save(paths, "preparations", JSON.writeValueAsBytes(new Preparation(baseline, Instant.now())), ".json");
        }
    }

    public static EvidenceSubmission submit(WorkflowFileLedger ledger, WorkstreamPaths paths, Reference preparation,
                                             String requestId, List<Path> files, Declaration execution, String note) throws IOException {
        if (blank(note) || requestId == null || !requestId.matches("[A-Za-z0-9._-]{1,80}")
                || files == null || files.isEmpty() || files.size() > 32 || execution == null)
            throw new IOException("submission requires request id, note, declaration, and 1-32 explicit files");
        var prepared = readPreparation(paths, preparation);
        if (execution.startedAt().isBefore(prepared.recordedAt()))
            throw new IOException("declared execution precedes preparation; timestamps are operator declarations, not machine proof");
        EvidenceCollection.verifySource(paths.workspaceRoot(), prepared.baseline());
        var materials = new ArrayList<Material>();
        long total = 0;
        for (var file : files) {
            var source = file.toAbsolutePath().normalize();
            if (!source.toRealPath().equals(source) || !Files.isRegularFile(source, LinkOption.NOFOLLOW_LINKS))
                throw new IOException("material must be a canonical regular file: " + source);
            byte[] bytes;
            try (var input = Files.newInputStream(source, LinkOption.NOFOLLOW_LINKS)) { bytes = input.readNBytes(FILE_LIMIT + 1); }
            total += bytes.length;
            if (bytes.length > FILE_LIMIT || total > TOTAL_LIMIT) throw new IOException("material size limit exceeded");
            var name = source.getFileName().toString();
            var dot = name.lastIndexOf('.');
            var extension = dot >= 0 ? name.substring(dot) : ".bin";
            if (!extension.matches("\\.[A-Za-z0-9]{1,10}")) extension = ".bin";
            var stored = save(paths, "files", bytes, extension);
            materials.add(new Material(stored.ref(), stored.sha256(), bytes.length, source.getFileName().toString()));
        }
        var manifest = new Manifest(requestId, preparation, prepared.baseline(), execution, note, List.copyOf(materials));
        var reference = save(paths, "submissions", JSON.writeValueAsBytes(manifest), ".json");
        var submission = new EvidenceSubmission(requestId, preparation.ref(), preparation.sha256(),
                reference.ref(), reference.sha256(), prepared.baseline());
        try (var lock = WorkstreamLock.acquire(paths.workstreamDir(), LockOwner.currentProcess(paths.workstreamId().value(), "submit evidence"))) {
            verify(paths, submission);
            var definition = ledger.loadDefinition(paths);
            var gateNode = ledger.loadNode(paths, prepared.baseline().gateNodeInstanceId());
            // Only a fully routed prior decision is idempotent. Partial gate writes never authorize another route.
            if (gateNode.status() == NodeStatus.COMPLETED) {
                var prior = JSON.convertValue(gateNode.result().get("external_evidence"), EvidenceSubmission.class);
                if (!submission.equals(prior) || !"submit_evidence".equals(gateNode.result().get("human_action")))
                    throw new IOException("gate already resolved with different evidence");
                var gate = JSON.readValue(paths.gateJson("gate-" + gateNode.nodeInstanceId()).toFile(), GateDocument.class);
                if (!"resolved".equals(gate.status()) || !gateNode.nodeInstanceId().equals(gate.nodeInstanceId())
                        || !"submit_evidence".equals(gate.result().get("human_action"))
                        || !note.equals(gate.result().get("note")) || !note.equals(gateNode.result().get("note")))
                    throw new IOException("inconsistent prior evidence decision");
                var routed = false;
                try (var lines = Files.lines(paths.eventsJsonl())) {
                    for (var iterator = lines.iterator(); iterator.hasNext();) {
                        var line = iterator.next();
                        if (line.isBlank()) continue;
                        var event = JSON.readTree(line);
                        if ("node_routed".equals(event.path("event_type").asText())
                                && gateNode.nodeInstanceId().equals(event.path("payload").path("transition")
                                .path("evidence_collection_gate").asText())) routed = true;
                    }
                }
                if (!routed) throw new IOException("partial evidence decision; no automatic recovery");
                return prior;
            }
            var currentBaseline = EvidenceCollection.captureBaseline(ledger, paths, definition, "submit_evidence");
            if (!prepared.baseline().equals(currentBaseline)) throw new IOException("preparation no longer belongs to current source/gate");
            ledger.submitEvidence(paths, definition, note, submission);
            return submission;
        }
    }

    static Manifest verify(WorkstreamPaths paths, EvidenceSubmission submission) throws IOException {
        var preparation = new Reference(submission.preparationRef(), submission.preparationSha256());
        var prepared = readPreparation(paths, preparation);
        var manifest = JSON.readValue(read(paths, new Reference(submission.manifestRef(), submission.manifestSha256())), Manifest.class);
        if (!Objects.equals(manifest.preparation(), preparation) || !Objects.equals(manifest.baseline(), submission.baseline())
                || !Objects.equals(prepared.baseline(), submission.baseline()) || !submission.requestId().equals(manifest.requestId())
                || blank(manifest.note()) || manifest.declaredExecution() == null
                || manifest.declaredExecution().startedAt().isBefore(prepared.recordedAt())
                || manifest.materials() == null || manifest.materials().isEmpty() || manifest.materials().size() > 32)
            throw new IOException("external material manifest identity mismatch");
        long total = 0;
        for (var material : manifest.materials()) {
            var bytes = read(paths, new Reference(material.ref(), material.sha256()));
            total += bytes.length;
            if (bytes.length != material.size() || bytes.length > FILE_LIMIT || total > TOTAL_LIMIT)
                throw new IOException("external material size mismatch");
        }
        EvidenceCollection.verifySource(paths.workspaceRoot(), submission.baseline());
        return manifest;
    }

    static List<String> refs(WorkstreamPaths paths, EvidenceSubmission submission) throws IOException {
        var manifest = verify(paths, submission);
        var refs = new LinkedHashSet<String>();
        refs.add(submission.manifestRef());
        for (var material : manifest.materials()) refs.add(material.ref());
        return List.copyOf(refs);
    }

    private static Preparation readPreparation(WorkstreamPaths paths, Reference ref) throws IOException {
        var preparation = JSON.readValue(read(paths, ref), Preparation.class);
        if (preparation.baseline() == null || preparation.recordedAt() == null)
            throw new IOException("invalid evidence preparation");
        return preparation;
    }

    private static byte[] read(WorkstreamPaths paths, Reference reference) throws IOException {
        var prefix = ".agent/workstreams/" + paths.workstreamId().value() + "/artifacts/verification/";
        if (reference == null || reference.ref() == null || !reference.ref().startsWith(prefix)
                || !dev.dual.core.contract.TaskContractValidator.isCanonicalPath(reference.ref().substring(prefix.length()))
                || reference.sha256() == null || !reference.sha256().matches("[0-9a-f]{64}"))
            throw new IOException("invalid material reference");
        var file = paths.workspaceRoot().resolve(reference.ref());
        if (!file.toRealPath().equals(paths.workspaceRoot().toRealPath().resolve(reference.ref()))
                || !Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) throw new IOException("noncanonical material reference");
        byte[] bytes;
        try (var input = Files.newInputStream(file, LinkOption.NOFOLLOW_LINKS)) { bytes = input.readNBytes(FILE_LIMIT + 1); }
        if (bytes.length > FILE_LIMIT || !sha(bytes).equals(reference.sha256())) throw new IOException("material SHA mismatch");
        return bytes;
    }

    private static Reference save(WorkstreamPaths paths, String kind, byte[] bytes, String extension) throws IOException {
        var directory = paths.workstreamDir().resolve("artifacts/verification/" + kind);
        var root = paths.workspaceRoot().toRealPath();
        var cursor = root;
        for (var segment : paths.workspaceRoot().relativize(directory)) {
            cursor = cursor.resolve(segment);
            if (!Files.exists(cursor, LinkOption.NOFOLLOW_LINKS)) Files.createDirectory(cursor);
            if (!Files.isDirectory(cursor, LinkOption.NOFOLLOW_LINKS) || !cursor.toRealPath().equals(cursor))
                throw new IOException("noncanonical material storage");
        }
        var hash = sha(bytes);
        var target = directory.resolve(hash + extension);
        if (!Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
            var temporary = Files.createTempFile(directory, ".evidence-", ".tmp");
            try {
                Files.write(temporary, bytes);
                Files.move(temporary, target, StandardCopyOption.ATOMIC_MOVE);
            } finally { Files.deleteIfExists(temporary); }
        }
        var ref = new Reference(paths.workspaceRoot().relativize(target).toString().replace('\\', '/'), hash);
        read(paths, ref);
        return ref;
    }

    private static String sha(byte[] bytes) {
        try { return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes)); }
        catch (java.security.NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); }
    }
    private static boolean blank(String value) { return value == null || value.isBlank(); }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Stream;

/**
 * Rebuildable evidence index for one workstream.
 *
 * The manifest is not the evidence source of truth. It points to ledger and
 * artifact files so context packages can reuse known facts without expanding
 * raw transcripts or re-discovering the repository from scratch.
 */
final class EvidenceManifest {
    static final String MANIFEST_REF_NAME = "memory/evidence-manifest.json";

    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    private final String workstreamId;
    private final String updatedAt;
    private final List<EvidenceItem> items;

    EvidenceManifest(String workstreamId, String updatedAt, List<EvidenceItem> items) {
        this.workstreamId = workstreamId;
        this.updatedAt = updatedAt;
        this.items = List.copyOf(items);
    }

    static EvidenceManifest empty(String workstreamId) {
        return new EvidenceManifest(workstreamId, Instant.now().toString(), List.of());
    }

    static EvidenceManifest rebuild(Path workspaceRoot, Path workstreamDir, String workstreamId,
                                    List<String> routedRefs, ObjectMapper objectMapper) throws IOException {
        return rebuild(workspaceRoot, workstreamDir, workstreamId, routedRefs, objectMapper, Optional.empty());
    }

    static EvidenceManifest rebuild(
            Path workspaceRoot,
            Path workstreamDir,
            String workstreamId,
            List<String> routedRefs,
            ObjectMapper objectMapper,
            Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract
    ) throws IOException {
        var items = new ArrayList<EvidenceItem>();
        addFixedArtifacts(workspaceRoot, workstreamDir, objectMapper, items, qualifiedContract);
        addRoutedAgentContracts(workspaceRoot, workstreamDir, workstreamId, routedRefs, objectMapper, items);
        addHumanDecisions(workspaceRoot, workstreamDir, objectMapper, items);
        items.sort(Comparator
                .comparing(EvidenceItem::stageId)
                .thenComparing(EvidenceItem::iterationId)
                .thenComparing(EvidenceItem::type)
                .thenComparing(EvidenceItem::sourceRef));
        return new EvidenceManifest(workstreamId, Instant.now().toString(), items);
    }

    Path write(Path workstreamDir, ObjectMapper objectMapper) throws IOException {
        var memoryDir = workstreamDir.resolve("memory");
        Files.createDirectories(memoryDir);
        var path = memoryDir.resolve("evidence-manifest.json");
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(path.toFile(), toMap());
        return path;
    }

    List<EvidenceItem> items() {
        return items;
    }

    List<String> sourceRefs() {
        return items.stream()
                .map(EvidenceItem::sourceRef)
                .filter(ref -> !ref.isBlank())
                .distinct()
                .toList();
    }

    List<EvidenceItem> stageHandoffs() {
        return items.stream()
                .filter(item -> "stage_handoff".equals(item.type()))
                .toList();
    }

    List<EvidenceItem> reviewItems() {
        return items.stream()
                .filter(item -> List.of(
                        "task_contract",
                        "contract_resolution",
                        "agent_output_contract",
                        "design_result",
                        "self_test_report",
                        "acceptance_review",
                        "git_evidence",
                        "human_decision"
                ).contains(item.type()))
                .toList();
    }

    Map<String, Object> toMap() {
        var document = new LinkedHashMap<String, Object>();
        document.put("schemaVersion", 1);
        document.put("workstreamId", workstreamId);
        document.put("updatedAt", updatedAt);
        document.put("items", items.stream().map(EvidenceItem::toMap).toList());
        return document;
    }

    private static void addFixedArtifacts(
            Path workspaceRoot,
            Path workstreamDir,
            ObjectMapper objectMapper,
            List<EvidenceItem> items,
            Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract
    ) throws IOException {
        if (qualifiedContract.isPresent()) {
            items.add(itemFromJson(
                    workspaceRoot, workstreamDir, workspaceRoot.resolve(qualifiedContract.get().contractRef()), "task_contract",
                    qualifiedContract.get().document()));
            items.add(itemFromJson(
                    workspaceRoot,
                    workstreamDir,
                    workspaceRoot.resolve(qualifiedContract.get().resolutionRef()),
                    "requirement_resolution",
                    qualifiedContract.get().resolutionDocument()));
        } else {
            var legacy = TaskContractProjectionVerifier.readLegacyProjection(
                    workspaceRoot, workstreamDir.getFileName().toString()).projection();
            if (legacy.isPresent()) {
                if (legacy.get().contract() != null) {
                    items.add(itemFromJson(
                            workspaceRoot, workstreamDir, workspaceRoot.resolve(legacy.get().contractRef()),
                            "task_contract", legacy.get().document()));
                }
                if (!legacy.get().resolutionDocument().isEmpty()) {
                    items.add(itemFromJson(
                            workspaceRoot, workstreamDir, workspaceRoot.resolve(legacy.get().resolutionRef()),
                            "requirement_resolution", legacy.get().resolutionDocument()));
                }
            }
        }
        addJsonArtifact(workspaceRoot, workstreamDir, objectMapper, items,
                workstreamDir.resolve("artifacts/next-stage/handoff.json"), "stage_handoff");
        addJsonArtifact(workspaceRoot, workstreamDir, objectMapper, items,
                workstreamDir.resolve("artifacts/failure-classification.json"), "failure_classification");

        var gitEvidence = workstreamDir.resolve("artifacts/git-evidence/git-evidence.json");
        if (Files.isRegularFile(gitEvidence)) {
            addJsonArtifact(workspaceRoot, workstreamDir, objectMapper, items, gitEvidence, "git_evidence");
        }
    }

    private static void addRoutedAgentContracts(
            Path workspaceRoot,
            Path workstreamDir,
            String workstreamId,
            List<String> routedRefs,
            ObjectMapper objectMapper,
            List<EvidenceItem> items
    ) {
        for (var entry : AgentEvidenceIndex.fromRefs(
                workspaceRoot, workstreamId, routedRefs, objectMapper).recent(Integer.MAX_VALUE)) {
            var document = entry.document();
            var type = switch (document.sourceArtifactType()) {
                case "design_result" -> "design_result";
                case "self_test_report" -> "self_test_report";
                case "acceptance_review" -> "acceptance_review";
                case "stage_handoff" -> "stage_handoff";
                default -> "agent_output_contract";
            };
            var sourceRef = workspaceRef(workspaceRoot, entry.path());
            var claims = new ArrayList<String>();
            claims.addAll(document.completedWork());
            claims.addAll(document.importantDecisions());
            if (!document.decision().isBlank()) {
                claims.add("Decision: " + document.decision());
            }
            var risks = new ArrayList<String>();
            risks.addAll(document.openRisks());
            risks.addAll(document.mustFix());
            risks.addAll(document.missingEvidence());
            items.add(new EvidenceItem(
                    stableId(type, sourceRef),
                    type,
                    inferStageFromNode(document.nodeId()),
                    "",
                    document.nodeInstanceId(),
                    "",
                    sourceRef,
                    document.summary().isBlank() ? type : document.summary(),
                    List.copyOf(claims),
                    document.changedFiles(),
                    List.copyOf(risks),
                    "available"
            ));
        }
    }

    private static void addHumanDecisions(Path workspaceRoot, Path workstreamDir, ObjectMapper objectMapper,
                                          List<EvidenceItem> items) throws IOException {
        var nodesDir = workstreamDir.resolve("nodes");
        if (!Files.exists(nodesDir)) {
            return;
        }
        try (Stream<Path> paths = Files.list(nodesDir)) {
            var nodes = paths
                    .filter(Files::isRegularFile)
                    .filter(path -> path.getFileName().toString().endsWith(".json"))
                    .sorted()
                    .toList();
            for (var node : nodes) {
                var json = readJson(objectMapper, node).orElse(Map.of());
                var result = mapValue(json.get("result"));
                if (!result.containsKey("human_action")) {
                    continue;
                }
                items.add(new EvidenceItem(
                        stableId("human_decision", workspaceRef(workspaceRoot, node)),
                        "human_decision",
                        stageId(json),
                        text(json.get("iterationId")),
                        text(json.get("nodeInstanceId")),
                        "",
                        workspaceRef(workspaceRoot, node),
                        "Human action: " + text(result.get("human_action")),
                        List.of(text(result.get("note"))).stream().filter(s -> !s.isBlank()).toList(),
                        List.of(),
                        List.of(),
                        "available"
                ));
            }
        }
    }

    private static void addJsonArtifact(Path workspaceRoot, Path workstreamDir, ObjectMapper objectMapper,
                                        List<EvidenceItem> items, Path path, String type) throws IOException {
        if (!Files.isRegularFile(path)) {
            return;
        }
        var json = readJson(objectMapper, path).orElse(Map.of());
        items.add(itemFromJson(workspaceRoot, workstreamDir, path, type, json));
    }

    private static EvidenceItem itemFromJson(Path workspaceRoot, Path workstreamDir, Path path,
                                             String type, Map<String, Object> json) {
        var sourceRef = workspaceRef(workspaceRoot, path);
        var claims = claims(json);
        var files = files(json);
        var risks = risks(json);
        return new EvidenceItem(
                stableId(type, sourceRef),
                type,
                firstNonBlank(stageId(json), inferStageFromPath(workstreamDir, path)),
                text(json.get("iteration_id")).isBlank() ? text(json.get("iterationId")) : text(json.get("iteration_id")),
                text(json.get("node_instance_id")).isBlank() ? text(json.get("nodeInstanceId")) : text(json.get("node_instance_id")),
                text(json.get("node_execution_id")).isBlank() ? text(json.get("nodeExecutionId")) : text(json.get("node_execution_id")),
                sourceRef,
                summary(json, type),
                claims,
                files,
                risks,
                "available"
        );
    }

    private static String summary(Map<String, Object> json, String type) {
        for (var key : List.of("summary", "objective", "reasoning", "verification_summary", "verificationSummary")) {
            var value = text(json.get(key));
            if (!value.isBlank()) {
                return value;
            }
        }
        var decision = firstNonBlank(text(json.get("decision")), text(json.get("status")), text(json.get("lifecycle_status")));
        if (!decision.isBlank()) {
            return type + ": " + decision;
        }
        return type;
    }

    private static List<String> claims(Map<String, Object> json) {
        var result = new ArrayList<String>();
        for (var key : List.of("completedWork", "completed_work", "importantDecisions", "important_decisions", "acceptance_criteria")) {
            result.addAll(listOfText(json.get(key)));
        }
        var decision = firstNonBlank(text(json.get("decision")), text(json.get("status")), text(json.get("lifecycle_status")));
        if (!decision.isBlank()) {
            result.add("Decision: " + decision);
        }
        return List.copyOf(result);
    }

    private static List<String> files(Map<String, Object> json) {
        var result = new ArrayList<String>();
        for (var key : List.of("changedFiles", "changed_files", "touched_files", "files")) {
            result.addAll(listOfText(json.get(key)));
        }
        return List.copyOf(result);
    }

    private static List<String> risks(Map<String, Object> json) {
        var result = new ArrayList<String>();
        for (var key : List.of("openRisks", "open_risks", "must_fix", "missing_evidence", "risk_areas")) {
            result.addAll(listOfText(json.get(key)));
        }
        var failure = mapValue(json.get("failure"));
        var category = firstNonBlank(text(failure.get("category_hint")), text(failure.get("category")));
        if (!category.isBlank()) {
            result.add("Failure category: " + category);
        }
        return List.copyOf(result);
    }

    private static Optional<Map<String, Object>> readJson(ObjectMapper objectMapper, Path path) throws IOException {
        if (!Files.isRegularFile(path)) {
            return Optional.empty();
        }
        try {
            return Optional.of(objectMapper.readValue(path.toFile(), MAP_TYPE));
        } catch (IOException | RuntimeException e) {
            var fallback = new LinkedHashMap<String, Object>();
            fallback.put("summary", "Invalid JSON artifact: " + path.getFileName());
            fallback.put("raw_size", Files.isRegularFile(path)
                    ? Files.readString(path, StandardCharsets.UTF_8).length()
                    : 0);
            return Optional.of(fallback);
        }
    }

    private static String stageId(Map<String, Object> json) {
        return firstNonBlank(
                text(json.get("stage_id")),
                text(json.get("stageId")),
                inferStageFromNode(text(json.get("node_id"))),
                inferStageFromNode(text(json.get("nodeDefinitionId")))
        );
    }

    private static String inferStageFromPath(Path workstreamDir, Path path) {
        var ref = workstreamDir.relativize(path).toString();
        if (ref.contains("git-evidence")) return "implementation";
        if (ref.contains("next-stage")) return "handoff";
        if (ref.contains("failure-classification")) return "acceptance";
        return "";
    }

    private static String inferStageFromNode(String nodeId) {
        if (nodeId == null || nodeId.isBlank()) {
            return "";
        }
        var dot = nodeId.indexOf('.');
        return dot > 0 ? nodeId.substring(0, dot) : "";
    }

    private static String stableId(String type, String sourceRef) {
        return type + ":" + Integer.toHexString(sourceRef.hashCode());
    }

    private static String workspaceRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize()
                .relativize(path.toAbsolutePath().normalize())
                .toString();
    }

    private static Map<String, Object> mapValue(Object value) {
        if (!(value instanceof Map<?, ?> map)) {
            return Map.of();
        }
        var copy = new LinkedHashMap<String, Object>();
        for (var entry : map.entrySet()) {
            if (entry.getKey() instanceof String key) {
                copy.put(key, entry.getValue());
            }
        }
        return copy;
    }

    private static List<String> listOfText(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        return items.stream()
                .map(EvidenceManifest::text)
                .filter(item -> !item.isBlank())
                .toList();
    }

    private static String firstNonBlank(String... values) {
        for (var value : values) {
            if (value != null && !value.isBlank()) {
                return value;
            }
        }
        return "";
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    record EvidenceItem(
            String id,
            String type,
            String stageId,
            String iterationId,
            String nodeInstanceId,
            String nodeExecutionId,
            String sourceRef,
            String summary,
            List<String> claims,
            List<String> files,
            List<String> riskTags,
            String status
    ) {
        Map<String, Object> toMap() {
            var map = new LinkedHashMap<String, Object>();
            map.put("id", id);
            map.put("type", type);
            map.put("stageId", stageId);
            map.put("iterationId", iterationId);
            map.put("nodeInstanceId", nodeInstanceId);
            map.put("nodeExecutionId", nodeExecutionId);
            map.put("sourceRef", sourceRef);
            map.put("summary", summary);
            map.put("claims", claims);
            map.put("files", files);
            map.put("riskTags", riskTags);
            map.put("status", status);
            return map;
        }
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.contract.ContractStatus;
import dev.dual.core.contract.TaskContract;
import dev.dual.core.contract.TaskContractValidator;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.ledger.file.GateDocument;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkflowIterationDocument;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

public final class ContractCompileHandler implements TaskHandler {

    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper().registerModule(new JavaTimeModule());
    private final TaskContractProposalValidator proposalValidator = new TaskContractProposalValidator();
    private final TaskContractRevisionContextResolver revisionContextResolver =
            new TaskContractRevisionContextResolver();

    @Override
    public String type() {
        return "contract.compile";
    }

    @Override
    public NodeResult execute(TaskContext context) throws IOException {
        if (!"approved_task_contract_proposal".equals(
                String.valueOf(context.definition().config().getOrDefault("required_subject", "")))) {
            return proposalFailure(
                    "TASK_CONTRACT_SUBJECT_CONTRACT_MISSING",
                    "contract.compile requires required_subject=approved_task_contract_proposal",
                    List.of(context.definition().id())
            );
        }
        var workstreamDir = context.workspaceRoot()
                .resolve(".agent")
                .resolve("workstreams")
                .resolve(context.workstreamId());

        var requirementPath = workstreamDir.resolve("requirement.md");
        if (!Files.exists(requirementPath)) {
            return new NodeResult(
                    "failed", dev.dual.core.workflow.NodeStatus.FAILED,
                    List.of(),
                    Map.of("error", "requirement.md not found in workstream directory"),
                    "requirement.md not found: " + requirementPath
            );
        }

        var approvedProposal = resolveApprovedProposal(context);
        if (approvedProposal.failed() != null) {
            return approvedProposal.failed();
        }
        var revisionContext = resolveRevisionContext(
                context, approvedProposal.reviewedProposal(), approvedProposal.gate());
        if (revisionContext.failed() != null) {
            return revisionContext.failed();
        }
        var proposalResult = compileFromProposal(
                Optional.of(approvedProposal.sidecarPath()), context, revisionContext.context());
        if (proposalResult.failed() != null) {
            return proposalResult.failed();
        }
        if (proposalResult.contract() == null) {
            return proposalFailure(
                    "TASK_CONTRACT_PROPOSAL_MISSING",
                    "task_contract_proposal is required; strict mode does not compile canonical TaskContract from Markdown",
                    List.of("No validated intake.claude_brainstorm AgentResultEnvelope JSON was found")
            );
        }
        var contract = proposalResult.contract();
        var resolutionResult = resolveContractNegotiation(
                proposalResult.proposal(), approvedProposal.reviewedProposal(), approvedProposal.gate());
        if (resolutionResult.failed() != null) {
            return resolutionResult.failed();
        }

        var errors = TaskContractValidator.validate(contract);
        if (!errors.isEmpty()) {
            var ambiguityNotes = new ArrayList<>(contract.ambiguityNotes());
            ambiguityNotes.addAll(errors);
            var humanQuestions = new ArrayList<>(contract.humanQuestions());
            humanQuestions.add("Contract compilation produced validation errors — please clarify the requirement");
            contract = new TaskContract(
                    contract.id(), contract.version(), contract.createdAt(),
                    contract.objective(), contract.scope(), contract.acceptanceCriteria(),
                    contract.testRequirements(), contract.constraints(),
                    contract.nonGoals(), contract.riskAreas(), contract.evidenceRefs(),
                    ambiguityNotes, humanQuestions,
                    ContractStatus.NEEDS_CLARIFICATION, contract.compilationPass(), contract.source()
            );
        }

        // Write artifacts
        var artifactsDir = workstreamDir.resolve("artifacts");
        TaskContractArtifactWriter.writeJson(contract, artifactsDir);
        TaskContractArtifactWriter.writeMarkdown(contract, artifactsDir);
        var contractSha256 = TaskContractArtifactWriter.sha256(artifactsDir.resolve("task-contract.json"));
        var resolutionRefs = writeContractResolutionArtifacts(context, artifactsDir, resolutionResult.resolution());
        var resolutionPath = artifactsDir.resolve("contract-resolution.json");
        var resolutionSha256 = Files.isRegularFile(resolutionPath)
                ? TaskContractArtifactWriter.sha256(resolutionPath)
                : "";

        var now = Instant.now();
        var result = new LinkedHashMap<String, Object>();
        result.put("contract_id", contract.id());
        result.put("contract_status", contract.status().name());
        result.put("contract_version", contract.version());
        result.put("task_contract_sha256", contractSha256);
        result.put("contract_resolution_sha256", resolutionSha256);
        result.put("compilation_pass", contract.compilationPass());
        var outputRefs = new ArrayList<String>();
        outputRefs.add(".agent/workstreams/" + context.workstreamId() + "/artifacts/task-contract.json");
        outputRefs.add(".agent/workstreams/" + context.workstreamId() + "/artifacts/task-contract.md");
        outputRefs.addAll(resolutionRefs);
        result.put("artifacts", List.copyOf(outputRefs));
        result.put("generated_at", now.toString());

        return NodeResult.completed("completed", List.copyOf(outputRefs), result);
    }

    private ProposalCompileResult compileFromProposal(
            Optional<Path> sourcePath,
            TaskContext context,
            RevisionContext revisionContext
    ) {
        if (sourcePath.isEmpty()) {
            return new ProposalCompileResult(null, null, null);
        }
        try {
            var document = AgentOutputContractDocument.read(sourcePath.get(), OBJECT_MAPPER);
            if (document.isEmpty()) {
                return new ProposalCompileResult(null, null, proposalFailure(
                        "TASK_CONTRACT_PROPOSAL_PARSE_FAILED",
                        "validated task_contract_proposal sidecar could not be parsed",
                        List.of(sourcePath.get().toString())));
            }
            var validated = document.get();
            if (AgentOutputLineageVerifier.violation(
                        context.workspaceRoot(), context.workstreamId(), sourcePath.get(), validated).isPresent()
                    || !"intake.claude_brainstorm".equals(validated.nodeId())) {
                return new ProposalCompileResult(null, null, proposalFailure(
                        "TASK_CONTRACT_PROPOSAL_INVALID",
                        "validated task_contract_proposal sidecar lineage is invalid",
                        List.of(sourcePath.get().toString())));
            }
            var proposal = validated.taskContractProposal();
            if (proposal == null) {
                return new ProposalCompileResult(null, null, proposalFailure(
                        "TASK_CONTRACT_PROPOSAL_INVALID",
                        "validated sidecar does not contain task_contract_proposal",
                        List.of(sourcePath.get().toString())));
            }
            var errors = proposalValidator.validate(proposal, context.workspaceRoot().toAbsolutePath().normalize(),
                    revisionContext.approvedScopeBaseline(), revisionContext.originalBaseCommit(), revisionContext.scopeReviewCandidates());
            if (!errors.isEmpty()) {
                return new ProposalCompileResult(null, proposal, proposalFailure(
                        "TASK_CONTRACT_PROPOSAL_INVALID",
                        "task_contract_proposal failed mechanical validation",
                        errors
                ));
            }
            var coverageErrors = revisionContext.revision()
                    ? proposalValidator.validateRevisionCoverage(proposal, revisionContext.obligations())
                    : proposalValidator.validateInitialIteration(proposal);
            if (!coverageErrors.isEmpty()) {
                return new ProposalCompileResult(null, proposal, proposalFailure(
                        "TASK_CONTRACT_PROPOSAL_INVALID",
                        "task_contract_proposal failed revision obligation coverage",
                        coverageErrors
                ));
            }
            if (revisionContext.revision()) {
                var deltaErrors = proposalValidator.validateRevisionDelta(
                        revisionContext.previousProposal(), proposal);
                if (!deltaErrors.isEmpty()) {
                    return new ProposalCompileResult(null, proposal, proposalFailure(
                            "TASK_CONTRACT_REVISION_DELTA_INVALID",
                            "task_contract_proposal contains an invalid revision delta",
                            deltaErrors.stream().map(TaskContractProposalValidator.RevisionDeltaError::message).toList()
                    ));
                }
            }
            return new ProposalCompileResult(toTaskContract(proposal, context.workstreamId()), proposal, null);
        } catch (Exception e) {
            return new ProposalCompileResult(null, null, proposalFailure(
                    "TASK_CONTRACT_PROPOSAL_PARSE_FAILED",
                    "task_contract_proposal JSON could not be parsed: " + e.getMessage(),
                    List.of(e.getMessage())
            ));
        }
    }

    private static TaskContract toTaskContract(TaskContractProposal proposal, String workstreamId) {
        return new TaskContract(
                "tc-" + workstreamId + "-v1",
                1,
                Instant.now(),
                proposal.objective().trim(),
                new TaskContract.Scope(
                        List.copyOf(proposal.scope().included()),
                        cleanList(proposal.scope().excluded())
                ),
                cleanClauseTexts(proposal.acceptanceCriteria()),
                cleanClauseTexts(proposal.testRequirements()),
                cleanClauseTexts(proposal.constraints()),
                cleanClauseTexts(proposal.nonGoals()),
                cleanClauseTexts(proposal.riskAreas()),
                cleanList(proposal.evidenceRefs()),
                List.of(),
                List.of(),
                ContractStatus.READY_FOR_REVIEW,
                1,
                new TaskContract.Source(
                        ".agent/workstreams/" + workstreamId + "/requirement.md",
                        "task_contract_proposal"
                )
        );
    }

    private static List<String> cleanClauseTexts(List<TaskContractProposal.ContractClause> values) {
        if (values == null) {
            return List.of();
        }
        return values.stream()
                .filter(value -> value != null && value.text() != null && !value.text().isBlank())
                .map(value -> value.text().trim())
                .distinct()
                .toList();
    }

    private static List<String> cleanList(List<String> values) {
        if (values == null) {
            return List.of();
        }
        return values.stream()
                .filter(value -> value != null && !value.isBlank())
                .map(String::trim)
                .distinct()
                .toList();
    }

    private ApprovedProposalResult resolveApprovedProposal(TaskContext context) throws IOException {
        var reviewed = reviewedProposalFromInputs(context);
        if (reviewed.size() != 1) {
            return new ApprovedProposalResult(null, null, null, proposalFailure(
                    "TASK_CONTRACT_PROPOSAL_APPROVAL_MISSING",
                    "exactly one Codex review bound to a task_contract_proposal is required",
                    List.of("review_subject_count=" + reviewed.size())
            ));
        }
        var subject = reviewed.get(0);
        var gate = latestResolvedRequirementGate(context, subject.reviewRef());
        if (gate.isEmpty()) {
            return new ApprovedProposalResult(null, null, null, proposalFailure(
                    "TASK_CONTRACT_PROPOSAL_APPROVAL_MISSING",
                    "the current Codex review was not approved by the requirement gate",
                    List.of(subject.reviewRef())
            ));
        }
        var sidecarPath = subject.reference().resolveArtifact(
                context.workspaceRoot(), context.workstreamId(), OBJECT_MAPPER);
        if (sidecarPath.isEmpty()) {
            return new ApprovedProposalResult(null, null, null, proposalFailure(
                    "TASK_CONTRACT_PROPOSAL_INVALID",
                    "the approved task_contract_proposal reference is stale or tampered",
                    List.of(subject.reference().artifactRef())
            ));
        }
        return new ApprovedProposalResult(sidecarPath.get(), gate.get(), subject, null);
    }

    private RevisionContextResult resolveRevisionContext(
            TaskContext context,
            ReviewedProposal approvedReview,
            ResolvedGate gate
    ) {
        var workstreamDir = context.workspaceRoot().resolve(".agent/workstreams").resolve(context.workstreamId());
        try {
            var resolved = revisionContextResolver.resolveForIteration(
                    context.workspaceRoot(), context.workstreamId(), context.instance().iterationId());
            if (!resolved.valid()) {
                return revisionContextFailure(
                        resolved.errors().isEmpty()
                                ? "revision iteration lineage could not be resolved"
                                : resolved.errors().getFirst(),
                        resolved.errors());
            }
            var iteration = resolved.context().iteration();
            var currentLineageErrors = validateCurrentApprovedLineage(workstreamDir, iteration, approvedReview, gate);
            if (!currentLineageErrors.isEmpty()) {
                return revisionContextFailure("approved review and proposal are outside the current iteration",
                        currentLineageErrors);
            }
            return new RevisionContextResult(
                    new RevisionContext(
                            resolved.context().revision(),
                            resolved.context().previousProposal(),
                            resolved.context().obligations(), resolved.context().approvedScopeBaseline(),
                            resolved.context().originalBaseCommit(), resolved.context().scopeReviewCandidates()), null);
        } catch (Exception failure) {
            return revisionContextFailure("revision iteration lineage could not be resolved",
                    List.of(failure.getMessage() == null ? failure.getClass().getSimpleName() : failure.getMessage()));
        }
    }

    private List<String> validateCurrentApprovedLineage(
            Path workstreamDir,
            WorkflowIterationDocument iteration,
            ReviewedProposal approvedReview,
            ResolvedGate gate
    ) throws IOException {
        var errors = new ArrayList<String>();
        var reviewDecision = approvedReview.document().decision();
        var eligibleReady = "READY_FOR_PRODUCT_REVIEW".equals(reviewDecision)
                && "READY_FOR_PRODUCT_REVIEW".equals(gate.sourceOutcome());
        var eligibleBlocked = "BLOCKED".equals(reviewDecision)
                && "BLOCKED".equals(gate.sourceOutcome())
                && !gate.note().isBlank();
        if (!"intake.codex_product_review".equals(approvedReview.document().nodeId())
                || (!eligibleReady && !eligibleBlocked)) {
            errors.add("current review is not an approved intake product review");
        }
        if (!TaskContractRevisionContextResolver.nodeBelongsToIteration(
                workstreamDir, approvedReview.document().nodeInstanceId(), iteration.iterationId())) {
            errors.add("current review node does not belong to " + iteration.iterationId());
        }
        if (!TaskContractRevisionContextResolver.nodeBelongsToIteration(
                workstreamDir, approvedReview.reference().producerNodeInstanceId(), iteration.iterationId())) {
            errors.add("approved proposal node does not belong to " + iteration.iterationId());
        }
        return List.copyOf(errors);
    }

    private static RevisionContextResult revisionContextFailure(String message, List<String> errors) {
        return new RevisionContextResult(null, proposalFailure(
                "TASK_CONTRACT_PROPOSAL_INVALID", message, errors));
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    private List<ReviewedProposal> reviewedProposalFromInputs(TaskContext context) {
        var root = context.workspaceRoot().toAbsolutePath().normalize();
        var reviewed = new ArrayList<ReviewedProposal>();
        for (var inputRef : context.instance().inputRefs()) {
            if (inputRef == null || !inputRef.endsWith(".contract.json")) {
                continue;
            }
            var path = root.resolve(inputRef).normalize();
            if (!path.startsWith(root) || !Files.isRegularFile(path)) {
                continue;
            }
            var document = AgentOutputContractDocument.read(path, OBJECT_MAPPER);
            if (document.isEmpty()
                    || AgentOutputLineageVerifier.violation(
                            root, context.workstreamId(), path, document.get()).isPresent()
                    || !"intake.codex_product_review".equals(document.get().nodeId())
                    || document.get().reviewSubject() == null) {
                continue;
            }
            reviewed.add(new ReviewedProposal(
                    inputRef, path, document.get(), document.get().reviewSubject()));
        }
        return List.copyOf(reviewed);
    }

    private ContractResolutionResult resolveContractNegotiation(
            TaskContractProposal proposal,
            ReviewedProposal approvedReview,
            ResolvedGate gateResolution
    ) {
        var blockedReview = "BLOCKED".equals(approvedReview.document().decision())
                && "BLOCKED".equals(gateResolution.sourceOutcome());
        var openQuestions = blockedReview
                ? blockedReviewQuestions(approvedReview.document())
                : cleanList(proposal.openQuestions());
        if (blockedReview && (gateResolution.note().isBlank() || openQuestions.isEmpty())) {
            return new ContractResolutionResult(null, proposalFailure(
                    "TASK_CONTRACT_PROPOSAL_INVALID",
                    "a BLOCKED review requires typed questions and a human resolution note",
                    List.of(approvedReview.reviewRef())
            ));
        }
        var resolvedQuestions = new ArrayList<ContractResolutionDocument.ResolvedQuestion>();
        for (var question : openQuestions) {
            resolvedQuestions.add(new ContractResolutionDocument.ResolvedQuestion(
                    question,
                    gateResolution.note().isBlank()
                            ? "Human approved the requirement gate; this question is accepted as a non-blocking contract assumption."
                            : gateResolution.note(),
                    "human"
            ));
        }
        var assumptions = new ArrayList<String>();
        if (resolvedQuestions.isEmpty()) {
            assumptions.add("Human approved the requirement review gate before canonical contract generation.");
        } else {
            assumptions.add("Open proposal questions were resolved by the requirement review gate.");
        }
        var resolution = new ContractResolutionDocument(
                1,
                "APPROVE",
                resolvedQuestions,
                assumptions,
                List.of(),
                gateResolution.gateRef(),
                "human_gate",
                Instant.now()
        );
        return new ContractResolutionResult(resolution, null);
    }

    private static List<String> blockedReviewQuestions(AgentOutputContractDocument review) {
        var questions = new java.util.LinkedHashSet<String>();
        questions.addAll(cleanList(review.mustFix()));
        questions.addAll(cleanList(review.missingEvidence()));
        return List.copyOf(questions);
    }

    private Optional<ResolvedGate> latestResolvedRequirementGate(TaskContext context, String reviewRef) throws IOException {
        var workstreamDir = context.workspaceRoot()
                .resolve(".agent")
                .resolve("workstreams")
                .resolve(context.workstreamId());
        var gatesDir = workstreamDir.resolve("gates");
        if (!Files.isDirectory(gatesDir)) {
            return Optional.empty();
        }
        try (var paths = Files.walk(gatesDir)) {
            var gates = paths
                    .filter(Files::isRegularFile)
                    .filter(path -> path.getFileName().toString().endsWith(".json"))
                    .sorted(Comparator.comparing(path -> path.toAbsolutePath().normalize().toString()))
                    .toList();
            for (int i = gates.size() - 1; i >= 0; i--) {
                var gate = readResolvedGate(context, workstreamDir, gates.get(i), reviewRef);
                if (gate.isPresent()) {
                    return gate;
                }
            }
        }
        return Optional.empty();
    }

    private Optional<ResolvedGate> readResolvedGate(
            TaskContext context,
            Path workstreamDir,
            Path gatePath,
        String reviewRef
    ) {
        try {
            var gate = OBJECT_MAPPER.readValue(gatePath.toFile(), GateDocument.class);
            if (!"resolved".equals(gate.status())) {
                return Optional.empty();
            }
            var nodeInstanceId = gate.nodeInstanceId();
            var nodePath = workstreamDir.resolve("nodes").resolve(nodeInstanceId + ".json");
            if (!Files.isRegularFile(nodePath)) {
                return Optional.empty();
            }
            var node = OBJECT_MAPPER.readValue(nodePath.toFile(), NodeInstanceDocument.class);
            if (!"gate.human_requirement_review".equals(node.nodeDefinitionId())
                    || !context.instance().iterationId().equals(node.iterationId())) {
                return Optional.empty();
            }
            var result = gate.result();
            var subjectRefs = result.get("subject_input_refs") instanceof List<?> values
                    ? values.stream().map(String::valueOf).toList()
                    : List.<String>of();
            if (!subjectRefs.contains(reviewRef)) {
                return Optional.empty();
            }
            var actionValue = result.get("human_action");
            var action = actionValue == null ? "" : String.valueOf(actionValue);
            if (!"approved".equals(action)) {
                return Optional.empty();
            }
            var noteValue = result.get("note");
            var note = noteValue == null ? "" : String.valueOf(noteValue);
            var sourceOutcomeValue = result.get("source_outcome");
            var sourceOutcome = sourceOutcomeValue == null ? "" : String.valueOf(sourceOutcomeValue);
            var gateRef = context.workspaceRoot().relativize(gatePath).toString();
            return Optional.of(new ResolvedGate(gateRef, action, note, sourceOutcome));
        } catch (Exception ignored) {
            return Optional.empty();
        }
    }

    private List<String> writeContractResolutionArtifacts(
            TaskContext context,
            Path artifactsDir,
            ContractResolutionDocument resolution
    ) throws IOException {
        if (resolution == null) {
            return List.of();
        }
        Files.createDirectories(artifactsDir);
        var jsonPath = artifactsDir.resolve("contract-resolution.json");
        var markdownPath = artifactsDir.resolve("contract-resolution.md");
        OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValue(jsonPath.toFile(), resolution);
        Files.writeString(markdownPath, renderContractResolutionMarkdown(resolution), StandardCharsets.UTF_8);
        return List.of(
                ".agent/workstreams/" + context.workstreamId() + "/artifacts/contract-resolution.json",
                ".agent/workstreams/" + context.workstreamId() + "/artifacts/contract-resolution.md"
        );
    }

    private static String renderContractResolutionMarkdown(ContractResolutionDocument resolution) {
        var builder = new StringBuilder();
        builder.append("# Contract Resolution\n\n");
        builder.append("- Decision: ").append(resolution.decision()).append("\n");
        builder.append("- Approved By: ").append(resolution.approvedBy()).append("\n");
        builder.append("- Gate Ref: ").append(resolution.gateRef()).append("\n");
        builder.append("- Created At: ").append(resolution.createdAt()).append("\n\n");
        if (!resolution.resolvedQuestions().isEmpty()) {
            builder.append("## Resolved Questions\n\n");
            for (var item : resolution.resolvedQuestions()) {
                builder.append("- Question: ").append(item.question()).append("\n");
                builder.append("  Resolution: ").append(item.resolution()).append("\n");
                builder.append("  Source: ").append(item.source()).append("\n");
            }
            builder.append("\n");
        }
        if (!resolution.assumptions().isEmpty()) {
            builder.append("## Assumptions\n\n");
            for (var assumption : resolution.assumptions()) {
                builder.append("- ").append(assumption).append("\n");
            }
        }
        return builder.toString();
    }

    private static NodeResult proposalFailure(String reason, String message, List<String> errors) {
        return new NodeResult(
                reason,
                NodeStatus.FAILED,
                List.of(),
                Map.of(
                        "reason", reason,
                        "message", message,
                        "validation_errors", List.copyOf(errors)
                ),
                message
        );
    }

    private record ProposalCompileResult(TaskContract contract, TaskContractProposal proposal, NodeResult failed) {}

    private record ReviewedProposal(
            String reviewRef,
            Path reviewPath,
            AgentOutputContractDocument document,
            TaskContractProposalReference reference
    ) {}

    private record ApprovedProposalResult(
            Path sidecarPath,
            ResolvedGate gate,
            ReviewedProposal reviewedProposal,
            NodeResult failed
    ) {}

    private record RevisionContext(
            boolean revision,
            TaskContractProposal previousProposal,
            List<AgentResultEnvelope.ReviewObligation> obligations,
            TaskContractProposal approvedScopeBaseline,
            String originalBaseCommit,
            List<dev.dual.core.contract.TaskContract.ScopeEntry> scopeReviewCandidates
    ) {}

    private record RevisionContextResult(RevisionContext context, NodeResult failed) {}

    private record ContractResolutionResult(ContractResolutionDocument resolution, NodeResult failed) {}

    private record ResolvedGate(String gateRef, String action, String note, String sourceOutcome) {}

}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Typed reader for the {@code plan_artifact} envelope emitted by
 * {@code plan.claude_plan}.
 *
 * <p>This is the source of truth for the plan body — it replaces Markdown-section
 * parsing ({@code validateFormalArtifactBody}). The six required fields carry the
 * semantic content that used to live only in Markdown headings; programmatic plan
 * validation reads this typed artifact, not the prose. Markdown may still be
 * written for human reading, but it does not participate in contract / routing /
 * completion decisions.</p>
 */
public record PlanArtifactDocument(
        String artifactType,
        int schemaVersion,
        List<String> implementationSteps,
        List<String> editFiles,
        List<String> referenceFiles,
        List<String> fileLevelChanges,
        List<String> validationPlan,
        String rollbackNotes,
        List<String> knownRisks,
        List<String> humanReviewChecklist,
        boolean editFilesDeclared,
        boolean referenceFilesDeclared
) {
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    public static PlanArtifactDocument from(Map<String, Object> document) {
        return new PlanArtifactDocument(
                text(document.get("artifact_type")),
                intValue(document.get("schema_version"), 1),
                stringList(document.get("implementation_steps")),
                stringList(document.get("edit_files")),
                stringList(document.get("reference_files")),
                stringList(document.get("file_level_changes")),
                stringList(document.get("validation_plan")),
                text(document.get("rollback_notes")),
                stringList(document.get("known_risks")),
                stringList(document.get("human_review_checklist")),
                document.containsKey("edit_files"),
                document.containsKey("reference_files")
        );
    }

    static Optional<PlanArtifactDocument> read(Path path, ObjectMapper objectMapper) {
        try {
            return Optional.of(from(objectMapper.readValue(path.toFile(), MAP_TYPE)));
        } catch (IOException | RuntimeException ignored) {
            return Optional.empty();
        }
    }

    /**
     * Returns the first required field that is empty/blank (using the JSON field
     * name), or empty if the plan body is complete. Drives contract validation:
     * a missing field is a {@code PLAN_ARTIFACT_BODY_MISSING} failure.
     */
    public Optional<String> missingRequiredField() {
        if (implementationSteps.isEmpty()) {
            return Optional.of("implementation_steps");
        }
        if (!editFilesDeclared || editFiles.isEmpty()) {
            return Optional.of("edit_files");
        }
        if (!referenceFilesDeclared) {
            return Optional.of("reference_files");
        }
        if (fileLevelChanges.isEmpty()) {
            return Optional.of("file_level_changes");
        }
        if (validationPlan.isEmpty()) {
            return Optional.of("validation_plan");
        }
        if (rollbackNotes.isBlank()) {
            return Optional.of("rollback_notes");
        }
        if (knownRisks.isEmpty()) {
            return Optional.of("known_risks");
        }
        if (humanReviewChecklist.isEmpty()) {
            return Optional.of("human_review_checklist");
        }
        return Optional.empty();
    }

    private static List<String> stringList(Object value) {
        if (!(value instanceof List<?> list)) {
            return List.of();
        }
        var result = new ArrayList<String>();
        for (var item : list) {
            var text = text(item);
            if (!text.isBlank()) {
                result.add(text);
            }
        }
        return List.copyOf(result);
    }

    private static int intValue(Object value, int fallback) {
        if (value instanceof Number number) {
            return number.intValue();
        }
        try {
            return Integer.parseInt(text(value));
        } catch (NumberFormatException e) {
            return fallback;
        }
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.core.StreamReadFeature;
import com.fasterxml.jackson.core.io.JsonEOFException;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.PropertyNamingStrategies;
import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.databind.json.JsonMapper;

/** The only JSON grammar owner for final agent workflow results. */
public final class AgentResultEnvelopeParser {
    private final JsonMapper objectMapper;

    public AgentResultEnvelopeParser() {
        this.objectMapper = JsonMapper.builder(JsonFactory.builder()
                .enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION)
                .build())
                .propertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE)
                .disable(MapperFeature.ALLOW_COERCION_OF_SCALARS)
                .enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES)
                .enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS)
                .build();
    }

    public ParseResult parse(String candidate) {
        if (candidate == null || candidate.isBlank()) {
            return ParseResult.failed("AGENT_RESULT_MISSING", "Final ACP assistant message is empty.", null);
        }
        try {
            return ParseResult.valid(objectMapper.readValue(candidate, AgentResultEnvelope.class));
        } catch (JsonEOFException failure) {
            return ParseResult.failed(
                    "AGENT_RESULT_PARSE_FAILED",
                    failure.getMessage(),
                    ParseDiagnostic.at(ParseFailureKind.UNEXPECTED_END_OF_INPUT, failure.getLocation())
            );
        } catch (Exception failure) {
            return ParseResult.failed(
                    "AGENT_RESULT_PARSE_FAILED",
                    failure.getMessage(),
                    ParseDiagnostic.at(ParseFailureKind.INVALID_JSON, null)
            );
        }
    }

    public enum ParseFailureKind {
        UNEXPECTED_END_OF_INPUT,
        INVALID_JSON
    }

    public record ParseDiagnostic(ParseFailureKind kind, long offset, int line, int column) {
        private static ParseDiagnostic at(ParseFailureKind kind, JsonLocation location) {
            return new ParseDiagnostic(
                    kind,
                    location == null ? -1L : location.getCharOffset(),
                    location == null ? -1 : location.getLineNr(),
                    location == null ? -1 : location.getColumnNr()
            );
        }
    }

    public record ParseResult(
            AgentResultEnvelope envelope,
            String errorCode,
            String message,
            ParseDiagnostic diagnostic
    ) {
        static ParseResult valid(AgentResultEnvelope envelope) {
            return new ParseResult(envelope, "", "", null);
        }

        static ParseResult failed(String errorCode, String message, ParseDiagnostic diagnostic) {
            return new ParseResult(null, errorCode, message == null ? "" : message, diagnostic);
        }

        public boolean valid() {
            return envelope != null;
        }
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.contract.TaskContractValidator;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;

/** Validates proposed edit paths, not business completeness or actual Git operations. */
final class PlanScopeValidator {
    private PlanScopeValidator() {
    }

    static List<String> shapeErrors(AgentResultEnvelope.Plan plan) {
        if (plan == null || plan.editFiles() == null || plan.editFiles().isEmpty()) {
            return List.of("PLAN_SCOPE_MISSING: result.plan.edit_files is required and must not be empty");
        }
        var errors = new ArrayList<String>();
        var paths = new HashSet<String>();
        for (var path : plan.editFiles()) {
            if (!TaskContractValidator.isCanonicalPath(path)) {
                errors.add("PLAN_SCOPE_PATH_INVALID: " + path);
            }
            if (!paths.add(path)) {
                errors.add("PLAN_SCOPE_PATH_DUPLICATE: " + path);
            }
        }
        return List.copyOf(errors);
    }

    static List<String> validate(Path root, String workstreamId, AgentResultEnvelope.Plan plan) {
        var errors = shapeErrors(plan);
        if (!errors.isEmpty()) {
            return errors;
        }
        var resolution = TaskContractProjectionVerifier.resolve(root, workstreamId);
        if (resolution.failure() != null || resolution.qualified().isEmpty()) {
            return List.of("PLAN_CONTRACT_NOT_QUALIFIED: " + (resolution.failure() == null
                    ? "approved contract is absent" : resolution.failure().reason()));
        }
        var included = resolution.qualified().orElseThrow().contract().scope().included();
        return plan.editFiles().stream()
                .filter(path -> included.stream().noneMatch(entry -> entry.path().equals(path)))
                .map(path -> "PLAN_SCOPE_NOT_AUTHORIZED: " + path)
                .toList();
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.contract.TaskContract;
import dev.dual.runtime.governance.AgentCapabilityCatalog;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/**
 * Builds passive repository-scope governance artifacts for one context package.
 *
 * These documents are execution guardrails and evidence projections, not
 * workflow truth. They are rebuildable from the effective workdir, task
 * contract, evidence manifest, and node context, then consumed by prompts,
 * trace, and operator views to compare planned scope with actual agent
 * behavior.
 */
final class RepoScopeGovernance {
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };
    private static final int MAX_SCOPE_FILES = 24;

    private RepoScopeGovernance() {
    }

    static Documents build(
            Path workspaceRoot,
            Path workstreamDir,
            TaskHandler.TaskContext context,
            ObjectMapper objectMapper
    ) throws IOException {
        return build(workspaceRoot, workstreamDir, context, objectMapper, Optional.empty());
    }

    static Documents build(
            Path workspaceRoot,
            Path workstreamDir,
            TaskHandler.TaskContext context,
            ObjectMapper objectMapper,
            Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract
    ) throws IOException {
        return build(workspaceRoot, workstreamDir, context, objectMapper, qualifiedContract, "");
    }

    static Documents build(
            Path workspaceRoot,
            Path workstreamDir,
            TaskHandler.TaskContext context,
            ObjectMapper objectMapper,
            Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract,
            String runId
    ) throws IOException {
        var stageId = stageId(context);
        var targetNodeDefinitionId = targetNodeDefinitionId(context);
        var memoryDir = workstreamDir.resolve("memory");
        var workstreamMemoryPath = memoryDir.resolve("workstream-memory.json");
        var existingMemory = readWorkstreamMemory(workstreamMemoryPath, objectMapper);
        var governanceDir = workstreamDir.resolve("artifacts").resolve("context-governance");
        var nodeKey = safeFileName(context.instance().nodeInstanceId());
        var occurrenceKey = runId == null || runId.isBlank()
                ? nodeKey
                : nodeKey + "-" + safeFileName(runId);
        var occurrenceDir = governanceDir.resolve("occurrences").resolve(occurrenceKey);
        var repoMapPath = occurrenceDir.resolve("repo-map.json");
        var planPath = occurrenceDir.resolve("file-relevance-plan.json");
        var policyPath = occurrenceDir.resolve("stage-scope-policy.json");
        var workingSetPath = occurrenceDir.resolve("working-set.json");
        var fileSummariesPath = occurrenceDir.resolve("file-summaries.json");
        var readReuseContractPath = occurrenceDir.resolve("read-reuse-contract.json");
        var capabilityCatalogPath = occurrenceDir.resolve("agent-capability-catalog.json");
        var reportPath = occurrenceDir.resolve("planned-report.json");
        var bindingPath = occurrenceDir.resolve("binding.json");
        Files.createDirectories(memoryDir);
        Files.createDirectories(occurrenceDir);
        var trackedInventory = contractDiscovery(context)
                ? GitTrackedPathInventory.capture(workspaceRoot)
                : GitTrackedPathInventory.empty();
        var plan = buildFileRelevancePlan(
                workstreamDir, context, objectMapper, stageId, targetNodeDefinitionId, qualifiedContract,
                trackedInventory, ref(workspaceRoot, repoMapPath));
        var repoMapPaths = contractDiscovery(context)
                ? trackedInventory.paths()
                : textList(plan.get("readCandidates"));
        var repoMap = buildRepoMap(
                workspaceRoot,
                workstreamDir,
                context,
                objectMapper,
                repoMapPaths,
                trackedInventory
        );
        var policy = buildStageScopePolicy(context, stageId, plan, targetNodeDefinitionId);
        var report = buildInitialReport(context, stageId, plan, policy, targetNodeDefinitionId);
        var workingSet = buildWorkingSet(context, stageId, plan, policy, targetNodeDefinitionId);
        var fileSummaries = buildFileSummaries(context, stageId, workingSet);
        var readReuseContract = buildReadReuseContract(context, stageId, plan, policy, targetNodeDefinitionId, existingMemory);
        var capabilityCatalog = AgentCapabilityCatalog.detect(
                context.workstreamId(),
                targetNodeDefinitionId,
                context.definition().config()
        );
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(repoMapPath.toFile(), repoMap);
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(planPath.toFile(), plan);
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(policyPath.toFile(), policy);
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(workingSetPath.toFile(), workingSet);
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(fileSummariesPath.toFile(), fileSummaries);
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(readReuseContractPath.toFile(), readReuseContract);
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(capabilityCatalogPath.toFile(), capabilityCatalog.toDocument());
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(reportPath.toFile(), report);
        var binding = RepositoryFactBinding.write(
                workspaceRoot,
                bindingPath,
                context.workstreamId(),
                context.instance().nodeInstanceId(),
                runId,
                trackedInventory.head(),
                trackedInventory.sha256(),
                trackedInventory.paths().size(),
                Map.of(
                        "repoMap", repoMapPath,
                        "fileRelevancePlan", planPath,
                        "stageScopePolicy", policyPath,
                        "workingSet", workingSetPath,
                        "fileSummaries", fileSummariesPath,
                        "readReuseContract", readReuseContractPath,
                        "agentCapabilityCatalog", capabilityCatalogPath,
                        "plannedReport", reportPath
                ),
                objectMapper
        );
        var workstreamMemory = buildWorkstreamMemory(
                context,
                workspaceRoot,
                stageId,
                existingMemory,
                repoMapPath,
                planPath,
                policyPath,
                workingSetPath,
                fileSummariesPath,
                readReuseContractPath,
                binding.path()
        );
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(workstreamMemoryPath.toFile(), workstreamMemory);

        return new Documents(
                repoMap,
                plan,
                policy,
                report,
                workingSet,
                fileSummaries,
                readReuseContract,
                capabilityCatalog.toDocument(),
                repoMapPath,
                planPath,
                policyPath,
                reportPath,
                workingSetPath,
                fileSummariesPath,
                readReuseContractPath,
                capabilityCatalogPath,
                workstreamMemoryPath,
                binding
        );
    }

    static void appendMarkdownGuidance(StringBuilder builder, Documents documents, Path workspaceRoot) {
        appendMarkdownGuidance(builder, documents, workspaceRoot, false);
    }

    static void appendMarkdownGuidance(StringBuilder builder, Documents documents, Path workspaceRoot, boolean compact) {
        if (documents == null) {
            return;
        }
        builder.append("## Repo Scope Guidance\n\n");
        builder.append("This section is a passive harness guardrail. It guides repository exploration but does not replace task contract, artifact validation, or human approval.\n\n");
        builder.append("- Stage: ").append(text(documents.policy().get("stageId"))).append("\n");
        if (compact) {
            appendCompactMarkdownGuidance(builder, documents, workspaceRoot);
            return;
        }
        builder.append("- Repo map: ").append(ref(workspaceRoot, documents.repoMapPath())).append("\n");
        builder.append("- Repository fact binding: ")
                .append(documents.repositoryFactBinding().ref()).append("\n");
        appendInventoryIdentity(builder, documents);
        builder.append("- File relevance plan: ").append(ref(workspaceRoot, documents.fileRelevancePlanPath())).append("\n");
        builder.append("- Stage scope policy: ").append(ref(workspaceRoot, documents.stageScopePolicyPath())).append("\n");
        builder.append("- Workstream memory: ").append(ref(workspaceRoot, documents.workstreamMemoryPath())).append("\n");
        builder.append("- Working set: ").append(ref(workspaceRoot, documents.workingSetPath())).append("\n");
        builder.append("- File summaries: ").append(ref(workspaceRoot, documents.fileSummariesPath())).append("\n");
        builder.append("- Read reuse contract: ").append(ref(workspaceRoot, documents.readReuseContractPath())).append("\n");
        builder.append("- Agent capability catalog: ").append(ref(workspaceRoot, documents.agentCapabilityCatalogPath())).append("\n");
        builder.append("- Governance report: ").append(ref(workspaceRoot, documents.governanceReportPath())).append("\n\n");
        appendPathList(builder, "Recommended read files", textList(documents.plan().get("readCandidates")), 8);
        appendPathList(builder, "Contract scope candidates", textList(documents.plan().get("contractScopeCandidates")), 12);
        appendPathList(builder, "Allowed write files", textList(documents.policy().get("writeScope")), 8);
        appendPathList(builder, "Forbidden scope", textList(documents.policy().get("forbiddenScope")), 8);
        appendPathList(builder, "Already inspected files", textList(documents.plan().get("previouslyReadFiles")), 8);
        appendReadAvoidanceRules(builder, documents);
        builder.append("Read recommendations are context only. Declared edits must match TaskContract.scope and are verified from Git evidence.\n\n");
    }

    private static void appendCompactMarkdownGuidance(StringBuilder builder, Documents documents, Path workspaceRoot) {
        builder.append("- Governance refs: capabilityCatalog=")
                .append(ref(workspaceRoot, documents.agentCapabilityCatalogPath()))
                .append("; readReuseContract=")
                .append(ref(workspaceRoot, documents.readReuseContractPath()))
                .append("; repoMap=")
                .append(ref(workspaceRoot, documents.repoMapPath()))
                .append("; repositoryFactBinding=")
                .append(documents.repositoryFactBinding().ref())
                .append("\n\n");
        appendInventoryIdentity(builder, documents);
        builder.append("- Available context capabilities: ")
                .append(inlineList(capabilitySummaries(documents.agentCapabilityCatalog()), 4))
                .append("\n\n");
        appendPathList(builder, "Recommended read files", textList(documents.plan().get("readCandidates")), 4);
        appendPathList(builder, "Expected edit files", textList(documents.policy().get("writeScope")), 4);
    }

    private static Map<String, Object> buildRepoMap(
            Path workspaceRoot,
            Path workstreamDir,
            TaskHandler.TaskContext context,
            ObjectMapper objectMapper,
            List<String> knownPaths,
            GitTrackedPathInventory trackedInventory
    ) throws IOException {
        var files = new ArrayList<Map<String, Object>>();
        var root = workspaceRoot.toAbsolutePath().normalize();
        for (var relative : new LinkedHashSet<>(knownPaths)) {
            var path = root.resolve(relative).normalize();
            if (!path.startsWith(root) || !Files.isRegularFile(path) || ignoredPath(relative)) {
                continue;
            }
            var item = new LinkedHashMap<String, Object>();
            item.put("path", relative);
            item.put("kind", fileKind(relative));
            item.put("sizeBytes", safeSize(path));
            files.add(item);
        }
        files.sort(Comparator.comparing(item -> text(item.get("path"))));
        var document = new LinkedHashMap<String, Object>();
        document.put("schemaVersion", 1);
        document.put("artifactType", "repo_map");
        document.put("workstreamId", context.workstreamId());
        document.put("generatedAt", Instant.now().toString());
        document.put("effectiveWorkdir", workspaceRoot.toAbsolutePath().normalize().toString());
        document.put("baseCommit", readBaseCommit(workstreamDir, objectMapper));
        document.put("source", contractDiscovery(context)
                ? "git_tracked_inventory"
                : "task_contract_scope+git_evidence");
        document.put("inventoryHead", trackedInventory.head());
        document.put("inventorySha256", trackedInventory.sha256());
        document.put("inventoryPathCount", trackedInventory.paths().size());
        document.put("files", files);
        document.put("fileCount", files.size());
        document.put("truncated", false);
        return document;
    }

    private static Map<String, Object> buildFileRelevancePlan(
            Path workstreamDir,
            TaskHandler.TaskContext context,
            ObjectMapper objectMapper,
            String stageId,
            String targetNodeDefinitionId,
            Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract,
            GitTrackedPathInventory trackedInventory,
            String trackedInventoryRef
    ) throws IOException {
        var contractScope = contractScopePaths(
                context.workspaceRoot(), workstreamDir, qualifiedContract);
        var candidates = new LinkedHashSet<String>();
        candidates.addAll(contractScope);
        addGitChangedFiles(candidates, workstreamDir);
        if (contractDiscovery(context)) {
            candidates.addAll(trackedInventory.paths());
        }
        var readCandidates = bounded(candidates, MAX_SCOPE_FILES);
        var writeCandidates = stageAllowsBusinessWrites(stageId)
                ? contractScope
                : List.<String>of();
        var previousReads = previousReadCounts(workstreamDir, "", objectMapper);
        var evidenceFiles = evidenceFiles(workstreamDir, objectMapper);
        var repeatedReadAvoidance = repeatedReadAvoidance(readCandidates, previousReads, evidenceFiles);

        var document = new LinkedHashMap<String, Object>();
        document.put("schemaVersion", 1);
        document.put("artifactType", "file_relevance_plan");
        document.put("workstreamId", context.workstreamId());
        document.put("stageId", stageId);
        document.put("nodeInstanceId", context.instance().nodeInstanceId());
        document.put("nodeDefinitionId", context.definition().id());
        document.put("builderNodeDefinitionId", context.definition().id());
        document.put("targetNodeDefinitionId", targetNodeDefinitionId);
        document.put("iterationId", context.instance().iterationId());
        document.put("source", contractDiscovery(context)
                ? "git_tracked_inventory+task_contract_scope+git_evidence"
                : "task_contract_scope+git_evidence");
        document.put("trackedInventoryRef", contractDiscovery(context) ? trackedInventoryRef : "");
        document.put("trackedInventoryHead", trackedInventory.head());
        document.put("trackedInventorySha256", trackedInventory.sha256());
        document.put("trackedInventoryPathCount", trackedInventory.paths().size());
        document.put("readCandidates", readCandidates);
        document.put("contractScopeCandidates", contractScope);
        document.put("writeCandidates", writeCandidates);
        document.put("previouslyReadFiles", previousReads.keySet().stream().limit(MAX_SCOPE_FILES).toList());
        document.put("repeatedReadAvoidance", repeatedReadAvoidance);
        document.put("expansionRules", List.of(
                "Use only routed artifacts and canonical task-contract or Git facts as prepared context.",
                "Do not re-read previously inspected files unless this stage needs fresh file contents.",
                "Do not infer task relevance from filenames, directory layout, or requirement prose."
        ));
        document.put("generatedAt", Instant.now().toString());
        return document;
    }

    private static Map<String, Object> buildStageScopePolicy(
            TaskHandler.TaskContext context,
            String stageId,
            Map<String, Object> plan,
            String targetNodeDefinitionId
    ) {
        var writeCandidates = textList(plan.get("writeCandidates"));
        var previouslyReadFiles = textList(plan.get("previouslyReadFiles"));
        var policy = new LinkedHashMap<String, Object>();
        policy.put("schemaVersion", 1);
        policy.put("artifactType", "stage_scope_policy");
        policy.put("workstreamId", context.workstreamId());
        policy.put("stageId", stageId);
        policy.put("nodeInstanceId", context.instance().nodeInstanceId());
        policy.put("nodeDefinitionId", context.definition().id());
        policy.put("builderNodeDefinitionId", context.definition().id());
        policy.put("targetNodeDefinitionId", targetNodeDefinitionId);
        policy.put("iterationId", context.instance().iterationId());
        policy.put("writeScope", writeCandidates);
        policy.put("previouslyReadFiles", previouslyReadFiles);
        policy.put("readReusePolicy", Map.of(
                "preferExistingEvidence", true,
                "avoidRepeatedReads", previouslyReadFiles.stream().limit(12).toList(),
                "requireReasonWhenRereading", targetSupportsRereadReasonField(targetNodeDefinitionId),
                "reasonField", targetSupportsRereadReasonField(targetNodeDefinitionId)
                        ? "agent_output_contract.reread_reasons"
                        : ""
        ));
        policy.put("forbiddenScope", forbiddenScope(stageId));
        policy.put("generatedAt", Instant.now().toString());
        return policy;
    }

    private static Map<String, Object> buildInitialReport(
            TaskHandler.TaskContext context,
            String stageId,
            Map<String, Object> plan,
            Map<String, Object> policy,
            String targetNodeDefinitionId
    ) {
        var report = new LinkedHashMap<String, Object>();
        report.put("schemaVersion", 1);
        report.put("artifactType", "context_governance_report");
        report.put("workstreamId", context.workstreamId());
        report.put("stageId", stageId);
        report.put("nodeInstanceId", context.instance().nodeInstanceId());
        report.put("nodeDefinitionId", context.definition().id());
        report.put("builderNodeDefinitionId", context.definition().id());
        report.put("targetNodeDefinitionId", targetNodeDefinitionId);
        report.put("iterationId", context.instance().iterationId());
        report.put("reportPhase", "planned");
        report.put("plannedReadFiles", textList(plan.get("readCandidates")));
        report.put("plannedWriteFiles", textList(policy.get("writeScope")));
        report.put("plannedPreviouslyReadFiles", textList(plan.get("previouslyReadFiles")));
        report.put("plannedRepeatedReadAvoidance", mapList(plan.get("repeatedReadAvoidance")));
        report.put("actualReadFiles", List.of());
        report.put("actualWriteFiles", List.of());
        report.put("telemetryPending", true);
        report.put("generatedAt", Instant.now().toString());
        return report;
    }

    private static Map<String, Object> buildWorkingSet(
            TaskHandler.TaskContext context,
            String stageId,
            Map<String, Object> plan,
            Map<String, Object> policy,
            String targetNodeDefinitionId
    ) {
        var repeatedByPath = new LinkedHashMap<String, Map<String, Object>>();
        for (var item : mapList(plan.get("repeatedReadAvoidance"))) {
            var path = text(item.get("path"));
            if (!path.isBlank()) {
                repeatedByPath.put(path, item);
            }
        }

        var coreFiles = new ArrayList<Map<String, Object>>();
        var supportingFiles = new ArrayList<Map<String, Object>>();
        for (var path : textList(plan.get("readCandidates"))) {
            var file = memoryFile(path, repeatedByPath.get(path), "Read candidate from task contract, evidence, git, or repo map.");
            if (coreFiles.size() < 12) {
                coreFiles.add(file);
            } else {
                supportingFiles.add(file);
            }
        }

        var document = new LinkedHashMap<String, Object>();
        document.put("schemaVersion", 1);
        document.put("artifactType", "working_set");
        document.put("workstreamId", context.workstreamId());
        document.put("stageId", stageId);
        document.put("nodeInstanceId", context.instance().nodeInstanceId());
        document.put("nodeDefinitionId", context.definition().id());
        document.put("targetNodeDefinitionId", targetNodeDefinitionId);
        document.put("iterationId", context.instance().iterationId());
        document.put("coreFiles", coreFiles);
        document.put("supportingFiles", supportingFiles);
        document.put("allowedWriteFiles", textList(policy.get("writeScope")));
        document.put("forbiddenScope", textList(policy.get("forbiddenScope")));
        document.put("generatedAt", Instant.now().toString());
        return document;
    }

    private static Map<String, Object> buildFileSummaries(
            TaskHandler.TaskContext context,
            String stageId,
            Map<String, Object> workingSet
    ) {
        var files = new ArrayList<Map<String, Object>>();
        for (var item : mapList(workingSet.get("coreFiles"))) {
            files.add(fileSummary(item, "core"));
        }
        for (var item : mapList(workingSet.get("supportingFiles"))) {
            files.add(fileSummary(item, "supporting"));
        }

        var document = new LinkedHashMap<String, Object>();
        document.put("schemaVersion", 1);
        document.put("artifactType", "file_summaries");
        document.put("workstreamId", context.workstreamId());
        document.put("stageId", stageId);
        document.put("nodeInstanceId", context.instance().nodeInstanceId());
        document.put("iterationId", context.instance().iterationId());
        document.put("files", files);
        document.put("generatedAt", Instant.now().toString());
        return document;
    }

    private static Map<String, Object> buildReadReuseContract(
            TaskHandler.TaskContext context,
            String stageId,
            Map<String, Object> plan,
            Map<String, Object> policy,
            String targetNodeDefinitionId,
            Map<String, Object> workstreamMemory
    ) {
        var reusePolicy = mapValue(policy.get("readReusePolicy"));
        var repeated = mapList(plan.get("repeatedReadAvoidance"));
        var reusableReadFiles = reusableReadFiles(workstreamMemory);
        var invalidatedReadFiles = invalidatedReadFiles(workstreamMemory);
        var allowedRereadFiles = allowedRereadFiles(targetNodeDefinitionId, reusableReadFiles);
        var document = new LinkedHashMap<String, Object>();
        document.put("schemaVersion", 1);
        document.put("artifactType", "read_reuse_contract");
        document.put("workstreamId", context.workstreamId());
        document.put("stageId", stageId);
        document.put("nodeInstanceId", context.instance().nodeInstanceId());
        document.put("nodeDefinitionId", context.definition().id());
        document.put("targetNodeDefinitionId", targetNodeDefinitionId);
        document.put("iterationId", context.instance().iterationId());
        document.put("preferExistingEvidence", true);
        document.put("avoidRepeatingReads", repeated);
        document.put("reusableReadFiles", reusableReadFiles);
        document.put("invalidatedReadFiles", invalidatedReadFiles);
        document.put("allowedRereadFiles", allowedRereadFiles);
        document.put("reuseSource", reusableReadFiles.isEmpty() ? "run_history" : "workstream_memory.readFiles");
        var requireReason = Boolean.TRUE.equals(reusePolicy.getOrDefault(
                "requireReasonWhenRereading",
                targetSupportsRereadReasonField(targetNodeDefinitionId)
        ));
        document.put("requireReasonWhenRereading", requireReason);
        document.put("reasonField", requireReason
                ? reusePolicy.getOrDefault("reasonField", "agent_output_contract.reread_reasons")
                : "");
        if (requireReason) {
            document.put("allowedRepeatedReadReasons", ReadReuseContractReasons.ALLOWED_REPEATED_READ_REASONS);
        }
        document.put("generatedAt", Instant.now().toString());
        return document;
    }

