import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.regex.Pattern;

/** Resolves the last human-approved contract.compile occurrence into one immutable snapshot. */
final class TaskContractProjectionVerifier {
    static final String FAILURE_OUTCOME = "TASK_CONTRACT_PROJECTION_QUALIFICATION_FAILED";
    private static final Pattern WORKFLOW_EVENT_ID = Pattern.compile("evt-(\\d{6,})");
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper().registerModule(new JavaTimeModule());
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    private TaskContractProjectionVerifier() {
    }

    static Resolution resolve(Path workspaceRoot, String workstreamId) {
        var workstreamDir = workspaceRoot.resolve(".agent/workstreams").resolve(workstreamId);
        var nodes = readNodes(workstreamDir.resolve("nodes"));
        if (nodes.failure() != null) {
            return Resolution.failed(nodes.failure());
        }
        var occurrenceRead = lastContractGateOccurrence(workstreamDir.resolve("events.jsonl"));
        if (occurrenceRead.failure() != null) {
            return Resolution.failed(occurrenceRead.failure());
        }
        var contractPath = workstreamDir.resolve("artifacts/task-contract.json");
        var resolutionPath = workstreamDir.resolve("artifacts/contract-resolution.json");
        if (occurrenceRead.occurrence() == null) {
            return Files.isRegularFile(contractPath) || Files.isRegularFile(resolutionPath)
                    ? Resolution.failed(Failure.of(
                            "APPROVAL_BINDING_MISSING", "contract artifacts have no routed contract approval gate"))
                    : Resolution.absent();
        }
        var occurrence = occurrenceRead.occurrence();
        var gateNode = node(nodes.nodes(), occurrence.nodeInstanceId());
        if (gateNode == null || !"gate.contract_review".equals(gateNode.nodeDefinitionId())) {
            return Resolution.failed(Failure.of("GATE_NODE_MISSING", "contract approval gate node is missing"));
        }
        if (gateNode.status() != NodeStatus.COMPLETED) {
            return Resolution.failed(Failure.of("GATE_NOT_COMPLETED", "latest contract approval gate is not completed"));
        }
        var gateRead = readGate(workstreamDir.resolve("gates").resolve(occurrence.gateId() + ".json"));
        if (gateRead.failure() != null) {
            return Resolution.failed(gateRead.failure());
        }
        var gate = gateRead.gate();
        if (!gate.nodeInstanceId().equals(gateNode.nodeInstanceId()) || !"resolved".equals(gate.status())) {
            return Resolution.failed(Failure.of("GATE_LINEAGE_INVALID", "latest contract gate lineage or status is invalid"));
        }
        var gateAction = text(gate.result().get("human_action"));
        var nodeAction = text(gateNode.result().get("human_action"));
        if (!"approved".equals(gateAction) || !gateAction.equals(nodeAction)) {
            return Resolution.failed(Failure.of(
                    "CONTRACT_NOT_APPROVED", "latest contract gate action is not approved: " + gateAction));
        }
        if (!text(gate.result().get("note")).equals(text(gateNode.result().get("note")))) {
            return Resolution.failed(Failure.of("GATE_RESULT_MISMATCH", "contract gate note does not match node result"));
        }
        var gateRefs = textList(gate.result().get("subject_input_refs"));
        if (!gateRefs.equals(gateNode.inputRefs())) {
            return Resolution.failed(Failure.of("GATE_SUBJECT_MISMATCH", "contract gate subject refs do not match node input refs"));
        }
        var sourceId = text(gate.result().get("source_node_instance_id"));
        if (sourceId.isBlank()
                || !sourceId.equals(text(gateNode.result().get("source_node_instance_id")))
                || !sourceId.equals(occurrence.sourceNodeInstanceId())) {
            return Resolution.failed(Failure.of("GATE_SOURCE_MISMATCH", "contract gate source occurrence identity is missing or inconsistent"));
        }
        var compileNode = node(nodes.nodes(), sourceId);
        if (compileNode == null
                || !"contract.compile".equals(compileNode.nodeDefinitionId())
                || compileNode.status() != NodeStatus.COMPLETED) {
            return Resolution.failed(Failure.of("COMPILE_BINDING_MISSING", "approved source is not a completed contract.compile node"));
        }
        if (!compileNode.nodeDefinitionId().equals(occurrence.fromNodeDefinitionId())) {
            return Resolution.failed(Failure.of("EVENT_SOURCE_MISMATCH", "routing event source does not match approved compile node"));
        }
        var newerCompile = newerCompletedCompile(nodes.nodes(), compileNode);
        if (newerCompile != null) {
            return Resolution.failed(Failure.of(
                    "UNAPPROVED_RECOMPILE", "completed contract.compile is newer than the approved source: "
                            + newerCompile.nodeInstanceId()));
        }
        if (!Files.isRegularFile(contractPath) || !Files.isRegularFile(resolutionPath)) {
            return Resolution.failed(Failure.of("ARTIFACT_MISSING", "approved contract or requirement resolution artifact is missing"));
        }
        var contractRef = ".agent/workstreams/" + workstreamId + "/artifacts/task-contract.json";
        var resolutionRef = ".agent/workstreams/" + workstreamId + "/artifacts/contract-resolution.json";
        if (!compileNode.outputRefs().contains(contractRef)
                || !compileNode.outputRefs().contains(resolutionRef)
                || !gateRefs.contains(contractRef)
                || !gateRefs.contains(resolutionRef)) {
            return Resolution.failed(Failure.of("OUTPUT_REF_MISMATCH", "approved compile/gate refs do not bind both contract artifacts"));
        }

        final byte[] contractBytes;
        final byte[] resolutionBytes;
        final TaskContract contract;
        final Map<String, Object> document;
        final Map<String, Object> resolutionDocument;
        try {
            contractBytes = Files.readAllBytes(contractPath);
            resolutionBytes = Files.readAllBytes(resolutionPath);
            contract = TaskContractArtifactWriter.mapper().readValue(contractBytes, TaskContract.class);
            document = OBJECT_MAPPER.readValue(contractBytes, MAP_TYPE);
            resolutionDocument = OBJECT_MAPPER.readValue(resolutionBytes, MAP_TYPE);
        } catch (Exception failure) {
            return Resolution.failed(Failure.of("CONTRACT_INVALID", "approved contract artifacts cannot be parsed"));
        }
        var errors = TaskContractValidator.validate(contract);
        if (!errors.isEmpty()) {
            return Resolution.failed(Failure.of(
                    "CONTRACT_INVALID", "task-contract.json is invalid: " + String.join("; ", errors)));
        }

        var sha256 = TaskContractArtifactWriter.sha256(contractBytes);
        var resolutionSha256 = TaskContractArtifactWriter.sha256(resolutionBytes);
        var expectedSha = text(compileNode.result().get("task_contract_sha256"));
        var expectedResolutionSha = text(compileNode.result().get("contract_resolution_sha256"));
        if (expectedSha.isBlank() || expectedResolutionSha.isBlank()) {
            return Resolution.failed(Failure.of(
                    "COMPILE_BINDING_MISSING", "approved contract.compile has incomplete artifact SHA binding"));
        }
        if (!sha256.equals(expectedSha) || !resolutionSha256.equals(expectedResolutionSha)) {
            return Resolution.failed(Failure.of("HASH_MISMATCH", "approved contract artifact SHA-256 does not match compile result"));
        }
        if (!contract.id().equals(text(compileNode.result().get("contract_id")))
                || !contract.status().name().equals(text(compileNode.result().get("contract_status")))
                || contract.version() != intValue(compileNode.result().get("contract_version"))) {
            return Resolution.failed(Failure.of(
                    "IDENTITY_MISMATCH", "task-contract.json identity does not match compile result"));
        }
        var nodeRef = ".agent/workstreams/" + workstreamId + "/nodes/"
                + compileNode.nodeInstanceId() + ".json";
        var gateRef = ".agent/workstreams/" + workstreamId + "/gates/" + occurrence.gateId() + ".json";
        return Resolution.qualified(new QualifiedTaskContract(
                new String(contractBytes, StandardCharsets.UTF_8), contract, Map.copyOf(document), sha256,
                contractRef, new String(resolutionBytes, StandardCharsets.UTF_8), Map.copyOf(resolutionDocument),
                resolutionSha256, resolutionRef, compileNode.nodeInstanceId(), nodeRef, gateRef, occurrence.eventId()));
    }

    static LegacyRead readLegacyProjection(Path workspaceRoot, String workstreamId) {
        var workstreamDir = workspaceRoot.resolve(".agent/workstreams").resolve(workstreamId);
        var contractPath = workstreamDir.resolve("artifacts/task-contract.json");
        var resolutionPath = workstreamDir.resolve("artifacts/contract-resolution.json");
        var hasContract = Files.isRegularFile(contractPath);
        var hasResolution = Files.isRegularFile(resolutionPath);
        if (!hasContract && !hasResolution) {
            return LegacyRead.absent();
        }
        try {
            byte[] contractBytes = hasContract ? Files.readAllBytes(contractPath) : new byte[0];
            var contract = hasContract
                    ? TaskContractArtifactWriter.mapper().readValue(contractBytes, TaskContract.class)
                    : null;
            Map<String, Object> contractDocument = hasContract
                    ? OBJECT_MAPPER.readValue(contractBytes, MAP_TYPE)
                    : Map.of();
            Map<String, Object> resolutionDocument = Map.of();
            String rawResolution = "";
            if (hasResolution) {
                var resolutionBytes = Files.readAllBytes(resolutionPath);
                resolutionDocument = OBJECT_MAPPER.readValue(resolutionBytes, MAP_TYPE);
                rawResolution = new String(resolutionBytes, StandardCharsets.UTF_8);
            }
            return LegacyRead.present(new LegacyProjection(
                    contract,
                    java.util.Collections.unmodifiableMap(new java.util.LinkedHashMap<>(contractDocument)),
                    new String(contractBytes, StandardCharsets.UTF_8),
                    java.util.Collections.unmodifiableMap(new java.util.LinkedHashMap<>(resolutionDocument)),
                    rawResolution,
                    ".agent/workstreams/" + workstreamId + "/artifacts/task-contract.json",
                    ".agent/workstreams/" + workstreamId + "/artifacts/contract-resolution.json"));
        } catch (Exception failure) {
            return LegacyRead.failed(Failure.of(
                    "CONTRACT_INVALID", "legacy task contract projection cannot be read"));
        }
    }

    static Optional<String> trustedWrappedPayload(
            Path workspaceRoot,
            String workstreamId,
            String nodeId,
            List<String> inputRefs
    ) {
        var binding = AcceptanceContextBinding.fromRefs(workspaceRoot, workstreamId, nodeId, inputRefs, OBJECT_MAPPER);
        if (binding.isEmpty()) {
            return Optional.empty();
        }
        var resolution = resolve(workspaceRoot, workstreamId);
        if (resolution.failure() != null || resolution.qualified().isEmpty()) {
            throw new IllegalArgumentException(resolution.failure() == null
                    ? "qualified task contract is required"
                    : resolution.failure().reason() + ": " + resolution.failure().message());
        }
        var qualified = resolution.qualified().orElseThrow();
        var mismatch = binding.get().validate(qualified);
        if (mismatch.isPresent()) {
            throw new IllegalArgumentException(mismatch.get().reason() + ": " + mismatch.get().message());
        }
        return Optional.of(qualified.wrappedPayload());
    }

    static Resolution resolveRoutedAcceptance(
            Path workspaceRoot,
            String workstreamId,
            String nodeId,
            List<String> inputRefs
    ) {
        final Optional<AcceptanceContextBinding> binding;
        try {
            binding = AcceptanceContextBinding.fromRefs(
                    workspaceRoot, workstreamId, nodeId, inputRefs, OBJECT_MAPPER);
        } catch (IllegalArgumentException failure) {
            return Resolution.failed(Failure.of("CONTEXT_BINDING_INVALID", failure.getMessage()));
        }
        if (binding.isEmpty()) {
            return Resolution.absent();
        }
        var resolution = resolve(workspaceRoot, workstreamId);
        if (resolution.failure() != null || resolution.qualified().isEmpty()) {
            return resolution.failure() == null
                    ? Resolution.failed(Failure.of("COMPILE_BINDING_MISSING", "qualified task contract is required"))
                    : resolution;
        }
        var mismatch = binding.get().validate(resolution.qualified().orElseThrow());
        return mismatch.map(Resolution::failed).orElse(resolution);
    }

    private static OccurrenceRead lastContractGateOccurrence(Path eventsPath) {
        if (!Files.isRegularFile(eventsPath)) {
            return new OccurrenceRead(null, null);
        }
        ContractGateOccurrence last = null;
        long previous = -1;
        try {
            for (var line : Files.readAllLines(eventsPath, StandardCharsets.UTF_8)) {
                if (line.isBlank()) {
                    continue;
                }
                final Map<String, Object> event;
                try {
                    event = OBJECT_MAPPER.readValue(line, MAP_TYPE);
                } catch (Exception failure) {
                    return new OccurrenceRead(null, Failure.of(
                            "EVENT_HISTORY_INVALID", "workflow event history contains invalid JSON"));
                }
                var eventId = text(event.get("event_id"));
                var matcher = WORKFLOW_EVENT_ID.matcher(eventId);
                if (!matcher.matches()) {
                    if ("node_routed".equals(text(event.get("event_type")))) {
                        return new OccurrenceRead(null, Failure.of(
                                "EVENT_HISTORY_INVALID", "routing event does not have a workflow event id"));
                    }
                    continue;
                }
                var sequence = Long.parseLong(matcher.group(1));
                if (sequence <= previous) {
                    return new OccurrenceRead(null, Failure.of(
                            "EVENT_HISTORY_INVALID", "workflow event history is not strictly ordered"));
                }
                previous = sequence;
                if (!"node_routed".equals(text(event.get("event_type")))) {
                    continue;
                }
                var payload = map(event.get("payload"));
                if (!"gate.contract_review".equals(text(payload.get("to")))) {
                    continue;
                }
                var gateId = text(payload.get("gate_id"));
                var nodeInstanceId = text(payload.get("node_instance_id"));
                var sourceNodeInstanceId = text(payload.get("source_node_instance_id"));
                var from = text(payload.get("from"));
                if (gateId.isBlank() || nodeInstanceId.isBlank()
                        || sourceNodeInstanceId.isBlank() || from.isBlank()) {
                    return new OccurrenceRead(null, Failure.of(
                            "GATE_SOURCE_MISSING", "contract gate routing event has incomplete source lineage"));
                }
                last = new ContractGateOccurrence(eventId, gateId, nodeInstanceId, sourceNodeInstanceId, from);
            }
            return new OccurrenceRead(last, null);
        } catch (IOException failure) {
            return new OccurrenceRead(null, Failure.of(
                    "EVENT_HISTORY_UNREADABLE", "cannot read workflow event history"));
        }
    }

    private static GateRead readGate(Path path) {
        if (!Files.isRegularFile(path)) {
            return new GateRead(null, Failure.of("GATE_DOCUMENT_MISSING", "contract approval gate document is missing"));
        }
        try {
            return new GateRead(OBJECT_MAPPER.readValue(path.toFile(), GateDocument.class), null);
        } catch (Exception failure) {
            return new GateRead(null, Failure.of("GATE_DOCUMENT_INVALID", "contract approval gate document cannot be parsed"));
        }
    }

    private static NodeInstanceDocument node(List<NodeInstanceDocument> nodes, String nodeInstanceId) {
        var matches = nodes.stream().filter(node -> node.nodeInstanceId().equals(nodeInstanceId)).toList();
        return matches.size() == 1 ? matches.getFirst() : null;
    }

    private static NodeInstanceDocument newerCompletedCompile(
            List<NodeInstanceDocument> nodes,
            NodeInstanceDocument approved
    ) {
        if (approved.finishedAt() == null) {
            return approved;
        }
        return nodes.stream()
                .filter(node -> !node.nodeInstanceId().equals(approved.nodeInstanceId()))
                .filter(node -> "contract.compile".equals(node.nodeDefinitionId()))
                .filter(node -> node.status() == NodeStatus.COMPLETED)
                .filter(node -> node.finishedAt() == null || !node.finishedAt().isBefore(approved.finishedAt()))
                .findFirst()
                .orElse(null);
    }

    private static Nodes readNodes(Path nodesDir) {
        if (!Files.isDirectory(nodesDir)) {
            return new Nodes(List.of(), null);
        }
        var nodes = new ArrayList<NodeInstanceDocument>();
        try (var paths = Files.list(nodesDir)) {
            for (var path : paths.filter(Files::isRegularFile)
                    .filter(path -> path.getFileName().toString().endsWith(".json"))
                    .sorted().toList()) {
                try {
                    nodes.add(OBJECT_MAPPER.readValue(path.toFile(), NodeInstanceDocument.class));
                } catch (Exception failure) {
                    return new Nodes(List.of(), Failure.of(
                            "NODE_LEDGER_UNREADABLE", "cannot read node ledger document " + path.getFileName()));
                }
            }
            return new Nodes(List.copyOf(nodes), null);
        } catch (IOException failure) {
            return new Nodes(List.of(), Failure.of("NODE_LEDGER_UNREADABLE", "cannot list node ledger"));
        }
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> map(Object value) {
        return value instanceof Map<?, ?> raw ? (Map<String, Object>) raw : Map.of();
    }

    private static List<String> textList(Object value) {
        return value instanceof List<?> list ? list.stream().map(String::valueOf).toList() : List.of();
    }

    private static int intValue(Object value) {
        if (value instanceof Number number) {
            return number.intValue();
        }
        try {
            return Integer.parseInt(text(value));
        } catch (NumberFormatException ignored) {
            return Integer.MIN_VALUE;
        }
    }

    record QualifiedTaskContract(
            String rawJson,
            TaskContract contract,
            Map<String, Object> document,
            String sha256,
            String contractRef,
            String rawResolutionJson,
            Map<String, Object> resolutionDocument,
            String resolutionSha256,
            String resolutionRef,
            String compileNodeInstanceId,
            String compileNodeRef,
            String approvalGateRef,
            String approvalEventId
    ) {
        String wrappedPayload() {
            return TypedContextPayloadBoundary.wrap("```json\n" + rawJson + "\n```");
        }
    }

    record Failure(String reason, String message) {
        static Failure of(String reason, String message) {
            return new Failure(reason, message);
        }
    }

    record LegacyProjection(
            TaskContract contract,
            Map<String, Object> document,
            String rawJson,
            Map<String, Object> resolutionDocument,
            String rawResolutionJson,
            String contractRef,
            String resolutionRef
    ) {
    }

    record LegacyRead(Optional<LegacyProjection> projection, Failure failure) {
        static LegacyRead absent() {
            return new LegacyRead(Optional.empty(), null);
        }

        static LegacyRead present(LegacyProjection projection) {
            return new LegacyRead(Optional.of(projection), null);
        }

        static LegacyRead failed(Failure failure) {
            return new LegacyRead(Optional.empty(), failure);
        }
    }

    record Resolution(Optional<QualifiedTaskContract> qualified, Failure failure) {
        static Resolution absent() {
            return new Resolution(Optional.empty(), null);
        }

        static Resolution qualified(QualifiedTaskContract contract) {
            return new Resolution(Optional.of(contract), null);
        }

        static Resolution failed(Failure failure) {
            return new Resolution(Optional.empty(), failure);
        }
    }

    private record Nodes(List<NodeInstanceDocument> nodes, Failure failure) {
    }

    private record ContractGateOccurrence(
            String eventId,
            String gateId,
            String nodeInstanceId,
            String sourceNodeInstanceId,
            String fromNodeDefinitionId
    ) {
    }

    private record OccurrenceRead(ContractGateOccurrence occurrence, Failure failure) {
    }

    private record GateRead(GateDocument gate, Failure failure) {
    }

    private record AcceptanceContextBinding(String sha256, String compileNodeRef) {
        static Optional<AcceptanceContextBinding> fromRefs(
                Path workspaceRoot,
                String workstreamId,
                String nodeId,
                List<String> inputRefs,
                ObjectMapper objectMapper
        ) {
            var root = workspaceRoot.toAbsolutePath().normalize();
            var contextDir = root.resolve(".agent/workstreams").resolve(workstreamId).resolve("context").normalize();
            var matches = new ArrayList<Map<String, Object>>();
            for (var ref : inputRefs == null ? List.<String>of() : inputRefs) {
                var path = root.resolve(ref).normalize();
                if (!path.startsWith(contextDir)
                        || !contextDir.equals(path.getParent())
                        || !path.getFileName().toString().endsWith(".json")
                        || !Files.isRegularFile(path)
                        || Files.isSymbolicLink(path)) {
                    continue;
                }
                try {
                    var document = objectMapper.readValue(path.toFile(), MAP_TYPE);
                    if ("acceptance".equals(text(document.get("profile")))
                            && nodeId.equals(text(document.get("targetNode")))) {
                        matches.add(document);
                    }
                } catch (IOException failure) {
                    throw new IllegalArgumentException("cannot read routed acceptance context metadata", failure);
                }
            }
            if (matches.isEmpty()) {
                return Optional.empty();
            }
            if (matches.size() != 1) {
                throw new IllegalArgumentException("multiple routed acceptance context metadata documents");
            }
            var document = matches.getFirst();
            var sha256 = text(document.get("taskContractSha256"));
            var compileNodeRef = text(document.get("taskContractCompileNodeRef"));
            if (sha256.isBlank() || compileNodeRef.isBlank()) {
                throw new IllegalArgumentException("routed acceptance context metadata has no task contract binding");
            }
            return Optional.of(new AcceptanceContextBinding(sha256, compileNodeRef));
        }

        Optional<Failure> validate(QualifiedTaskContract qualified) {
            if (!sha256.equals(qualified.sha256())) {
                return Optional.of(Failure.of(
                        "CONTEXT_BINDING_HASH_MISMATCH", "routed context SHA does not match current task contract"));
            }
            if (!compileNodeRef.equals(qualified.compileNodeRef())) {
                return Optional.of(Failure.of(
                        "CONTEXT_BINDING_LINEAGE_MISMATCH", "routed context compile ref does not match current binding"));
            }
            return Optional.empty();
        }
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.Map;
import com.fasterxml.jackson.core.type.TypeReference;

/** Runtime-owned provenance of required authored inputs; it never grants an approval. */
public final class AuthoredExecutionContext {
    static final ObjectMapper JSON = new ObjectMapper().registerModule(new JavaTimeModule());
    public static final String SECTION_NAME = "authored-context";
    private static final TypeReference<Map<String, Object>> MAP = new TypeReference<>() { };

    private AuthoredExecutionContext() { }

    public static void validateDefinition(dev.dual.core.workflow.WorkflowDefinition definition) {
        AuthoredStageLineageResolver.validateDefinition(definition);
    }

    public static Optional<Snapshot> prepare(TaskHandler.TaskContext context, String runId) throws IOException {
        if (!AuthoredStageLineageResolver.participates(context.definition().id())) return Optional.empty();
        try {
            var snapshot = new AuthoredStageLineageResolver(context.workspaceRoot(), context.workstreamId(), Long.MAX_VALUE)
                    .prepare(context.instance().nodeInstanceId(), runId);
            require(snapshot.nodeId().equals(context.definition().id())
                    && snapshot.nodeId().equals(context.instance().nodeDefinitionId()), "AUTHORED_CONTEXT_NODE_MISMATCH");
            verifyDirectInputs(context.workspaceRoot(), snapshot);
            return Optional.of(snapshot);
        } catch (IllegalArgumentException failure) {
            throw new IOException("AUTHORED_CONTEXT_INVALID", failure);
        }
    }

    public static void verifyManifest(Path root, Path manifestPath, Snapshot expected) throws IOException {
        var ref = root.toAbsolutePath().normalize().relativize(manifestPath.toAbsolutePath().normalize()).toString();
        var path = manifestPath(root, expected.workstreamId(), expected.runId(), ref);
        var document = JSON.readValue(path.toFile(), MAP);
        var actual = snapshot(document);
        require(expected.equals(actual), "AUTHORED_MANIFEST_IDENTITY_MISMATCH");
        require(expected.workstreamId().equals(document.get("workstreamId"))
                && expected.runId().equals(document.get("runId")) && expected.nodeId().equals(document.get("nodeId")),
                "AUTHORED_MANIFEST_RUN_MISMATCH");
        var required = expected.render(root);
        var sections = document.get("sections");
        require(sections instanceof List<?>, "AUTHORED_MANIFEST_SECTIONS_MISSING");
        int count = 0;
        for (var value : (List<?>) sections) {
            if (!(value instanceof Map<?, ?> section) || !SECTION_NAME.equals(section.get("name"))) continue;
            count++;
            require(Boolean.TRUE.equals(section.get("required")) && expected.nodeInstanceId().equals(section.get("sourceRef"))
                    && TaskContractArtifactWriter.sha256(required.getBytes(java.nio.charset.StandardCharsets.UTF_8)).equals(section.get("sha256")),
                    "AUTHORED_REQUIRED_SECTION_MISMATCH");
        }
        require(count == 1, "AUTHORED_REQUIRED_SECTION_MISSING_OR_DUPLICATED");
        var promptPath = Path.of(String.valueOf(document.get("promptPath"))).toAbsolutePath().normalize();
        require(promptPath.getParent().equals(path.getParent()) && Files.isRegularFile(promptPath), "AUTHORED_PROMPT_PATH_INVALID");
        var prompt = Files.readString(promptPath);
        require(prompt.contains(required), "AUTHORED_REQUIRED_CONTENT_MISSING");
    }

    static Reference validatePublication(Path root, String ws, String nodeInstanceId, String runId,
                                         AgentResultEnvelope.AgentResult result) throws IOException {
        var loaded = runSnapshot(root, ws, nodeInstanceId, runId);
        var expected = new AuthoredStageLineageResolver(root, ws, Long.MAX_VALUE).prepare(nodeInstanceId, runId);
        // New unrelated ledger events do not change the input identity.
        expected = new Snapshot(expected.workstreamId(), expected.nodeInstanceId(), expected.nodeId(), expected.runId(),
                loaded.snapshot().historyThrough(), expected.contract(), expected.approvedDesign(), expected.approvedPlan(),
                expected.parent(), expected.subject(), expected.trigger(), expected.obligations());
        verifyManifest(root, verifiedPath(root, loaded.reference()), expected);
        verifyDirectInputs(root, expected);
        List<AgentResultEnvelope.AuthoredRevisionResponse> responses = switch (result) {
            case AgentResultEnvelope.DesignResult design -> design.revisionResponses();
            case AgentResultEnvelope.PlanResult plan -> plan.revisionResponses();
            default -> null;
        };
        if (result instanceof AgentResultEnvelope.DesignResult || result instanceof AgentResultEnvelope.PlanResult) {
            var errors = AuthoredRevisionValidator.validate(responses, expected.obligations().stream().map(Obligation::id).toList());
            require(errors.isEmpty(), String.join("; ", errors));
        }
        return loaded.reference();
    }

    private static Bound runSnapshot(Path root, String ws, String nodeId, String runId) throws IOException {
        var runPath = canonicalPath(root, ".agent/workstreams/" + ws + "/runs/" + runId + "/run.json");
        var run = JSON.readValue(runPath.toFile(), MAP);
        var declaredPath = String.valueOf(run.get("promptManifestPath"));
        var absolute = Path.of(declaredPath);
        var relative = absolute.isAbsolute() ? root.toAbsolutePath().normalize().relativize(absolute.normalize()).toString() : declaredPath;
        var path = manifestPath(root, ws, runId, relative);
        var snapshot = snapshot(JSON.readValue(path.toFile(), MAP));
        require(snapshot.workstreamId().equals(ws) && snapshot.nodeInstanceId().equals(nodeId)
                && snapshot.runId().equals(runId), "AUTHORED_RUN_SNAPSHOT_MISMATCH");
        return new Bound(reference(root, relative), snapshot);
    }

    private static Snapshot snapshot(Map<String, Object> document) throws IOException {
        require(document.get("authoredContext") instanceof Map<?, ?>, "AUTHORED_MANIFEST_CONTEXT_MISSING");
        try { return JSON.convertValue(document.get("authoredContext"), Snapshot.class); }
        catch (IllegalArgumentException failure) { throw new IOException("AUTHORED_MANIFEST_CONTEXT_INVALID", failure); }
    }

    private static Path manifestPath(Path root, String ws, String run, String ref) throws IOException {
        var path = canonicalPath(root, ref);
        var directory = root.toAbsolutePath().normalize().resolve(".agent/workstreams/" + ws + "/runs/" + run + "/prompts");
        require(directory.equals(path.getParent()), "AUTHORED_MANIFEST_OUTSIDE_RUN");
        return path;
    }

    private static void verifyDirectInputs(Path root, Snapshot snapshot) throws IOException {
        var candidates = new java.util.ArrayList<Candidate>();
        if (snapshot.approvedDesign() != null) candidates.add(snapshot.approvedDesign().candidate());
        if (snapshot.approvedPlan() != null) candidates.add(snapshot.approvedPlan().candidate());
        if (snapshot.parent() != null) candidates.add(snapshot.parent());
        if (snapshot.subject() != null) candidates.add(snapshot.subject());
        for (var candidate : candidates) {
            var bound = verifiedCandidateSnapshot(root, snapshot.workstreamId(), candidate);
            require(Objects.equals(bound.contract(), snapshot.contract()), "AUTHORED_CONTRACT_EPOCH_MISMATCH");
            if (candidate.artifactType().equals("plan_result"))
                require(Objects.equals(bound.approvedDesign(), snapshot.approvedDesign()), "AUTHORED_PLAN_DESIGN_MISMATCH");
        }
    }

    static Snapshot verifiedCandidateSnapshot(Path root, String ws, Candidate candidate) throws IOException {
        var doc = JSON.readValue(verifiedPath(root, candidate.sidecar()).toFile(), MAP);
        require(doc.get("authored_context") instanceof Map<?, ?>, "AUTHORED_CANDIDATE_INPUT_BINDING_MISSING");
        final Reference ref;
        try { ref = JSON.convertValue(doc.get("authored_context"), Reference.class); }
        catch (IllegalArgumentException failure) { throw new IOException("AUTHORED_CANDIDATE_INPUT_BINDING_INVALID", failure); }
        // Publication already verified the prompt. Consumers follow its sealed binding,
        // not the historical run locator or a recursive replay of ancestor prompts.
        var path = manifestPath(root, ws, candidate.runId(), ref.ref());
        verifiedPath(root, ref);
        var manifest = JSON.readValue(path.toFile(), MAP);
        var bound = snapshot(manifest);
        require(ws.equals(bound.workstreamId()) && candidate.nodeInstanceId().equals(bound.nodeInstanceId())
                && candidate.runId().equals(bound.runId()) && candidate.nodeId().equals(bound.nodeId())
                && ws.equals(manifest.get("workstreamId")) && candidate.runId().equals(manifest.get("runId"))
                && candidate.nodeId().equals(manifest.get("nodeId")), "AUTHORED_INPUT_BINDING_MISMATCH");
        return bound;
    }

    private static void require(boolean value, String message) throws IOException {
        AuthoredStageLineageResolver.require(value, message);
    }
    private record Bound(Reference reference, Snapshot snapshot) { }

    public record Reference(String ref, String sha256) {
        public Reference {
            Objects.requireNonNull(ref);
            if (sha256 == null || !sha256.matches("[0-9a-f]{64}")) throw new IllegalArgumentException("invalid authored SHA");
        }
    }

    public record ContractIdentity(String compileNodeInstanceId, String approvalGateRef, String approvalEventId,
                                   Reference contract, Reference resolution) { }

    public record Candidate(Reference sidecar, String nodeInstanceId, String nodeId, String runId, String artifactType) { }

    public record Approval(Reference gate, String eventId, Candidate candidate) { }

    public record Obligation(String id, Reference source, String text) { }

    public record Snapshot(String workstreamId, String nodeInstanceId, String nodeId, String runId,
                           long historyThrough, ContractIdentity contract, Approval approvedDesign,
                           Approval approvedPlan, Candidate parent, Candidate subject, Reference trigger,
                           List<Obligation> obligations) {
        public Snapshot { obligations = List.copyOf(obligations); }

        Snapshot withHistoryThrough(long through) {
            return new Snapshot(workstreamId, nodeInstanceId, nodeId, runId, through, contract,
                    approvedDesign, approvedPlan, parent, subject, trigger, obligations);
        }

        public String render(Path root) throws IOException {
            var text = new StringBuilder("# Required Authored Context\n\n");
            text.append("The following verified inputs are mandatory. Respond to every active obligation; ")
                    .append("ADDRESSED does not close it. Use NOT_ADDRESSED honestly. Initial authors return [].\n\n");
            append(text, root, "Approved design", approvedDesign == null ? null : approvedDesign.candidate());
            append(text, root, "Approved plan", approvedPlan == null ? null : approvedPlan.candidate());
            append(text, root, "Revision parent", parent);
            append(text, root, "Review candidate", subject);
            text.append("## Active obligations\n\n")
                    .append(JSON.writerWithDefaultPrettyPrinter().writeValueAsString(obligations)).append('\n');
            return text.toString();
        }

        private static void append(StringBuilder text, Path root, String title, Candidate candidate) throws IOException {
            if (candidate == null) return;
            var path = verifiedPath(root, candidate.sidecar());
            text.append("## ").append(title).append("\n\n")
                    .append(candidate.sidecar().ref()).append("\n\n")
                    .append(Files.readString(path)).append("\n\n");
        }
    }

    static Path verifiedPath(Path root, Reference reference) throws IOException {
        var path = canonicalPath(root, reference.ref());
        if (!TaskContractArtifactWriter.sha256(Files.readAllBytes(path)).equals(reference.sha256()))
            throw new IOException("AUTHORED_SOURCE_HASH_MISMATCH: " + reference.ref());
        return path;
    }

    static Path canonicalPath(Path root, String ref) throws IOException {
        var base = root.toAbsolutePath().normalize();
        if (ref == null || ref.isBlank() || ref.indexOf('\\') >= 0 || Path.of(ref).isAbsolute())
            throw new IOException("AUTHORED_REF_INVALID");
        var path = base.resolve(ref).normalize();
        if (!path.startsWith(base) || !base.relativize(path).toString().equals(ref)
                || !Files.isRegularFile(path) || !path.toRealPath().equals(base.toRealPath().resolve(ref)))
            throw new IOException("AUTHORED_REF_INVALID: " + ref);
        return path;
    }

    static Reference reference(Path root, String ref) throws IOException {
        return new Reference(ref, TaskContractArtifactWriter.sha256(Files.readAllBytes(canonicalPath(root, ref))));
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.contract.TaskContractValidator;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;

/** Authoritative tracked-path snapshot for contract discovery; it does not infer task relevance. */
record GitTrackedPathInventory(String head, String sha256, List<String> paths) {
    GitTrackedPathInventory {
        head = text(head);
        sha256 = text(sha256);
        paths = paths == null ? List.of() : List.copyOf(paths);
    }

    static GitTrackedPathInventory capture(Path workspaceRoot) throws IOException {
        var root = workspaceRoot.toRealPath();
        var gitRoot = text(command(root, "rev-parse", "--show-toplevel"));
        if (!root.equals(Path.of(gitRoot).toRealPath())) {
            throw new IOException("effective workspace is not the Git worktree root: " + root);
        }
        var head = text(command(root, "rev-parse", "HEAD"));
        var raw = commandBytes(root, "ls-files", "-z", "--cached", "--", ".", ":!.agent");
        var paths = parseNulPaths(raw).stream()
                .map(GitTrackedPathInventory::normalize)
                .filter(TaskContractValidator::isCanonicalPath)
                .distinct()
                .sorted()
                .toList();
        return new GitTrackedPathInventory(head, digest(paths), paths);
    }

    static GitTrackedPathInventory empty() {
        return new GitTrackedPathInventory("", "", List.of());
    }

    static String command(Path root, String... args) throws IOException {
        return new String(commandBytes(root, args), StandardCharsets.UTF_8);
    }

    static byte[] commandBytes(Path root, String... args) throws IOException {
        var command = new ArrayList<String>();
        command.add("git");
        command.addAll(List.of(args));
        var process = new ProcessBuilder(command)
                .directory(root.toFile())
                .start();
        var stdout = process.getInputStream().readAllBytes();
        var stderr = new String(process.getErrorStream().readAllBytes(), StandardCharsets.UTF_8).trim();
        try {
            var exitCode = process.waitFor();
            if (exitCode != 0) {
                throw new IOException("git " + String.join(" ", args) + " failed: " + stderr);
            }
        } catch (InterruptedException interrupted) {
            Thread.currentThread().interrupt();
            throw new IOException("git inventory capture interrupted", interrupted);
        }
        return stdout;
    }

    static List<String> parseNulPaths(byte[] raw) throws IOException {
        var paths = new ArrayList<String>();
        var start = 0;
        for (var index = 0; index < raw.length; index++) {
            if (raw[index] != 0) {
                continue;
            }
            if (index > start) {
                paths.add(new String(raw, start, index - start, StandardCharsets.UTF_8));
            }
            start = index + 1;
        }
        if (start != raw.length) {
            throw new IOException("git tracked-path inventory has malformed NUL framing");
        }
        return List.copyOf(paths);
    }

    private static String digest(List<String> paths) throws IOException {
        try {
            var digest = MessageDigest.getInstance("SHA-256");
            for (var path : paths) {
                digest.update(path.getBytes(StandardCharsets.UTF_8));
                digest.update((byte) 0);
            }
            return HexFormat.of().formatHex(digest.digest());
        } catch (NoSuchAlgorithmException impossible) {
            throw new IOException("SHA-256 is unavailable", impossible);
        }
    }

    private static String normalize(String value) {
        var normalized = text(value).replace('\\', '/');
        while (normalized.startsWith("./")) {
            normalized = normalized.substring(2);
        }
        return normalized;
    }

    private static String text(String value) {
        return value == null ? "" : value.trim();
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.contract.TaskContract;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.BasicFileAttributes;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Stream;

final class ContextPackageSectionRenderer {
    private static final int DEFAULT_SNIPPET_CHARS = 4_000;
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper().registerModule(new JavaTimeModule());
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    private ContextPackageSectionRenderer() {
    }

    static void appendTaskContract(StringBuilder builder, Path contractPath) throws IOException {
        var contract = OBJECT_MAPPER.readValue(contractPath.toFile(), TaskContract.class);
        appendTaskContract(builder, contract);
    }

    static void appendLegacyTaskContract(
            StringBuilder builder,
            TaskContractProjectionVerifier.LegacyProjection legacy
    ) {
        if (legacy.contract() != null) {
            appendTaskContract(builder, legacy.contract());
        }
    }

    private static void appendTaskContract(StringBuilder builder, TaskContract contract) {
        builder.append("**Objective:** ").append(contract.objective()).append("\n\n");
        builder.append("**Status:** ").append(contract.status()).append("\n\n");
        if (contract.scope() != null) {
            builder.append("**Scope Included:**\n");
            for (var item : contract.scope().included()) {
                builder.append("- ").append(item.operation()).append(": ").append(item.path()).append("\n");
            }
            builder.append("\n**Scope Excluded:**\n");
            for (var item : contract.scope().excluded()) {
                builder.append("- ").append(item).append("\n");
            }
            builder.append("\n");
        }
        appendListSection(builder, "Acceptance Criteria", contract.acceptanceCriteria());
        appendListSection(builder, "Non-Goals", contract.nonGoals());
        appendListSection(builder, "Constraints", contract.constraints());
        appendListSection(builder, "Risk Areas", contract.riskAreas());
        appendListSection(builder, "Evidence References", contract.evidenceRefs());
    }

    static void appendQualifiedTaskContract(
            StringBuilder builder,
            TaskContractProjectionVerifier.QualifiedTaskContract qualifiedContract
    ) {
        appendTaskContract(builder, qualifiedContract.contract());
    }

    static void appendRequirementResolution(StringBuilder builder, Path resolutionPath) throws IOException {
        if (!Files.exists(resolutionPath)) {
            return;
        }
        var json = OBJECT_MAPPER.readValue(resolutionPath.toFile(), MAP_TYPE);
        appendRequirementResolution(builder, json);
    }

    static void appendQualifiedRequirementResolution(
            StringBuilder builder,
            TaskContractProjectionVerifier.QualifiedTaskContract qualifiedContract
    ) {
        appendRequirementResolution(builder, qualifiedContract.resolutionDocument());
    }

    static void appendLegacyRequirementResolution(
            StringBuilder builder,
            TaskContractProjectionVerifier.LegacyProjection legacy
    ) {
        appendRequirementResolution(builder, legacy.resolutionDocument());
    }

    private static void appendRequirementResolution(StringBuilder builder, Map<String, Object> json) {
        builder.append("**Requirement Resolution**\n");
        builder.append("- Decision: ").append(text(json.get("decision"))).append("\n");
        builder.append("- Approved By: ").append(text(json.get("approved_by"))).append("\n");
        builder.append("- Gate Ref: ").append(text(json.get("gate_ref"))).append("\n");
        appendListSection(builder, "Resolution Assumptions", listOfText(json.get("assumptions")));
        appendListSection(builder, "Accepted Risks", listOfText(json.get("accepted_risks")));
        appendListSection(builder, "Resolved Questions", resolvedQuestionTexts(json.get("resolved_questions")));
    }

    static void appendInputArtifactsSummary(StringBuilder builder, TaskHandler.TaskContext context) throws IOException {
        if (context.instance().inputRefs().isEmpty()) {
            builder.append("(no direct input refs)\n\n");
            return;
        }
        var evidence = AgentEvidenceIndex.fromRefs(
                context.workspaceRoot(), context.workstreamId(), context.instance().inputRefs(), OBJECT_MAPPER);
        var renderedSidecars = new HashSet<Path>();
        for (String inputRef : context.instance().inputRefs()) {
            var path = context.workspaceRoot().resolve(inputRef).normalize();
            if (evidence.isValidatedPlanProjectionRef(context.workspaceRoot(), inputRef)) {
                continue;
            }
            var entry = evidence.entryForRef(context.workspaceRoot(), inputRef);
            if (entry.isPresent()) {
                if (!renderedSidecars.add(entry.get().path())) {
                    continue;
                }
                var contract = entry.get().document();
                builder.append("- ").append(inputRef).append(" — ");
                if (!contract.decision().isBlank()) {
                    builder.append(contract.decision());
                    if (!contract.summary().isBlank()) {
                        builder.append(": ");
                    }
                }
                builder.append(contract.summary().isBlank()
                        ? "(validated agent result)"
                        : contract.summary().replace("\n", " / "));
                builder.append("\n");
                appendTypedPlanArtifact(builder, contract.planArtifact());
                continue;
            }
            builder.append("- ").append(inputRef);
            if (!Files.exists(path) || Files.isDirectory(path)) {
                builder.append(" (unavailable)\n");
                continue;
            }
            if (isTranscriptArtifact(path)) {
                builder.append(" (execution transcript; omitted from context)\n");
                continue;
            }
            if (isExecutionDiagnostic(path)) {
                builder.append(" (execution diagnostic; omitted from context)\n");
                continue;
            }
            if (isAgentResultCandidate(path)) {
                builder.append(" (unvalidated agent result omitted from context)\n");
                continue;
            }
            builder.append(" (routed artifact has no typed context projection; content omitted)\n");
        }
        builder.append("\n");
    }

    static void appendIterationHistoryDecisions(StringBuilder builder, Path workstreamDir, int maxItems) throws IOException {
        var iterationsDir = workstreamDir.resolve("iterations");
        if (!Files.exists(iterationsDir)) {
            builder.append("(no iteration history)\n\n");
            return;
        }
        try (Stream<Path> paths = Files.list(iterationsDir)) {
            var iterations = paths
                    .filter(Files::isRegularFile)
                    .filter(path -> path.getFileName().toString().endsWith(".json"))
                    .map(ContextPackageSectionRenderer::readJsonUnchecked)
                    .filter(iteration -> !text(iteration.get("iterationId")).isBlank())
                    .sorted(Comparator.comparingInt(ContextPackageSectionRenderer::iterationNumber).reversed())
                    .limit(maxItems)
                    .toList();
            if (iterations.isEmpty()) {
                builder.append("(no iteration history)\n\n");
                return;
            }
            for (var iteration : iterations) {
                builder.append("- ").append(text(iteration.get("iterationId")));
                builder.append(": trigger=").append(text(iteration.get("triggerAction")));
                builder.append(", target=").append(text(iteration.get("targetNodeDefinitionId")));
                var reason = text(iteration.get("reason"));
                if (!reason.isBlank()) {
                    builder.append(", reason=").append(reason.replace("\n", " "));
                }
                builder.append("\n");
            }
            builder.append("\n");
        }
    }

    static void appendHumanFeedbackLimited(StringBuilder builder, Path workstreamDir, int maxItems) throws IOException {
        var nodesDir = workstreamDir.resolve("nodes");
        if (!Files.exists(nodesDir)) {
            builder.append("(no human feedback)\n\n");
            return;
        }
        try (Stream<Path> paths = Files.list(nodesDir)) {
            var feedbackNodes = paths
                    .filter(Files::isRegularFile)
                    .filter(path -> path.getFileName().toString().endsWith(".json"))
                    .map(ContextPackageSectionRenderer::readNodeUnchecked)
                    .filter(ContextPackageSectionRenderer::hasHumanFeedback)
                    .sorted(Comparator.comparing(ContextPackageSectionRenderer::finishedAtText).reversed())
                    .limit(maxItems)
                    .toList();
            if (feedbackNodes.isEmpty()) {
                builder.append("(no human feedback)\n\n");
                return;
            }
            for (Map<String, Object> node : feedbackNodes) {
                appendHumanFeedbackNode(builder, node);
            }
        }
    }

    static void appendRecentAgentOutputsLimited(
            StringBuilder builder,
            TaskHandler.TaskContext context,
            int maxItems
    ) {
        appendRoutedAgentOutputs(builder, context, maxItems);
    }

    static void appendGitEvidenceDiffStat(StringBuilder builder, Path workstreamDir,
                                          StageHandoffDocument handoff) throws IOException {
        var evidenceDir = workstreamDir.resolve("artifacts/git-evidence");
        var changedFilesPath = evidenceDir.resolve("changed-files.txt");

        builder.append("### Changed Files\n\n");
        if (Files.exists(changedFilesPath)) {
            builder.append("```text\n");
            builder.append(snippet(changedFilesPath, 2_000));
            builder.append("\n```\n\n");
        } else if (handoff.hasChangedFiles()) {
            for (var file : handoff.changedFiles()) {
                builder.append("- ").append(file).append("\n");
            }
            builder.append("\n");
        } else if (!Files.exists(evidenceDir)) {
            builder.append("(git evidence not generated yet)\n\n");
            return;
        }

        var diffStat = evidenceDir.resolve("diff.stat");
        if (Files.exists(diffStat)) {
            builder.append("### Diff Stat\n\n");
            builder.append("```text\n");
            builder.append(snippet(diffStat, 1_000));
            builder.append("\n```\n\n");
        }
    }

