    static void appendInputArtifacts(StringBuilder builder, TaskHandler.TaskContext context, int maxSnippetChars) throws IOException {
        if (context.instance().inputRefs().isEmpty()) {
            builder.append("(no direct input refs)\n\n");
            return;
        }
        var evidence = AgentEvidenceIndex.fromRefs(
                context.workspaceRoot(), context.workstreamId(), context.instance().inputRefs(), OBJECT_MAPPER);
        var renderedSidecars = new HashSet<Path>();
        for (String inputRef : context.instance().inputRefs()) {
            var path = context.workspaceRoot().resolve(inputRef).normalize();
            if (evidence.isValidatedPlanProjectionRef(context.workspaceRoot(), inputRef)) {
                continue;
            }
            var entry = evidence.entryForRef(context.workspaceRoot(), inputRef);
            if (entry.isPresent()) {
                if (!renderedSidecars.add(entry.get().path())) {
                    continue;
                }
                builder.append("### ").append(inputRef).append("\n\n");
                appendAgentContractFields(builder, entry.get().document(), entry.get().path());
                continue;
            }
            builder.append("### ").append(inputRef).append("\n\n");
            if (!Files.exists(path) || Files.isDirectory(path)) {
                builder.append("(artifact unavailable or not a file)\n\n");
                continue;
            }
            if (isTranscriptArtifact(path)) {
                builder.append("(execution transcript omitted from context; inspect raw file at ")
                        .append(toDisplayRef(path))
                        .append(")\n\n");
                continue;
            }
            if (isExecutionDiagnostic(path)) {
                builder.append("(execution diagnostic omitted from context)\n\n");
                continue;
            }
            if (isAgentResultCandidate(path)) {
                builder.append("(unvalidated agent result omitted from context)\n\n");
                continue;
            }
            builder.append("(routed artifact has no typed context projection; content omitted)\n\n");
        }
    }

    static void appendGitEvidence(StringBuilder builder, Path workstreamDir, int maxSnippetChars) throws IOException {
        var evidenceDir = workstreamDir.resolve("artifacts/git-evidence");
        if (!Files.exists(evidenceDir)) {
            builder.append("(git evidence not generated yet)\n\n");
            return;
        }
        for (String fileName : List.of("git-evidence.json", "git-status-short.txt", "diff.stat", "changed-files.txt")) {
            var path = evidenceDir.resolve(fileName);
            builder.append("- ").append(fileName).append(": ").append(toDisplayRef(path)).append("\n");
        }
        var diffPatch = evidenceDir.resolve("diff.patch");
        if (Files.exists(diffPatch)) {
            builder.append("- diff.patch: ").append(toDisplayRef(diffPatch)).append("\n");
        }
        builder.append("\n");
        var evidenceJson = evidenceDir.resolve("git-evidence.json");
        if (Files.exists(evidenceJson)) {
            builder.append("```json\n");
            builder.append(snippet(evidenceJson, maxSnippetChars));
            builder.append("\n```\n\n");
        }
    }

    static void appendHumanFeedback(StringBuilder builder, Path workstreamDir) throws IOException {
        var nodesDir = workstreamDir.resolve("nodes");
        if (!Files.exists(nodesDir)) {
            builder.append("(no workflow node state yet)\n\n");
            return;
        }
        try (Stream<Path> paths = Files.list(nodesDir)) {
            var feedbackNodes = paths
                    .filter(Files::isRegularFile)
                    .filter(path -> path.getFileName().toString().endsWith(".json"))
                    .map(ContextPackageSectionRenderer::readNodeUnchecked)
                    .filter(ContextPackageSectionRenderer::hasHumanFeedback)
                    .sorted(Comparator.comparing(ContextPackageSectionRenderer::finishedAtText).reversed())
                    .limit(5)
                    .toList();
            if (feedbackNodes.isEmpty()) {
                builder.append("(no human gate feedback yet)\n\n");
                return;
            }
            for (Map<String, Object> node : feedbackNodes) {
                appendHumanFeedbackNode(builder, node);
            }
        }
    }

    static void appendIterationHistory(StringBuilder builder, Path workstreamDir) throws IOException {
        var iterationsDir = workstreamDir.resolve("iterations");
        if (!Files.exists(iterationsDir)) {
            builder.append("(no workflow iteration history yet)\n\n");
            return;
        }
        try (Stream<Path> paths = Files.list(iterationsDir)) {
            var iterations = paths
                    .filter(Files::isRegularFile)
                    .filter(path -> path.getFileName().toString().endsWith(".json"))
                    .map(ContextPackageSectionRenderer::readJsonUnchecked)
                    .filter(iteration -> !text(iteration.get("iterationId")).isBlank())
                    .sorted(Comparator.comparingInt(ContextPackageSectionRenderer::iterationNumber).reversed())
                    .limit(5)
                    .toList();
            if (iterations.isEmpty()) {
                builder.append("(no workflow iteration history yet)\n\n");
                return;
            }
            for (Map<String, Object> iteration : iterations) {
                builder.append("### ").append(text(iteration.get("iterationId"))).append("\n\n");
                builder.append("- Parent: ").append(blankAsNone(text(iteration.get("parentIterationId")))).append("\n");
                builder.append("- Trigger: ").append(text(iteration.get("triggerAction"))).append("\n");
                builder.append("- Target Node: ").append(text(iteration.get("targetNodeDefinitionId"))).append("\n");
                builder.append("- Created At: ").append(text(iteration.get("createdAt"))).append("\n");
                var reason = text(iteration.get("reason"));
                if (!reason.isBlank()) {
                    builder.append("\n```text\n");
                    builder.append(reason.stripTrailing());
                    builder.append("\n```\n");
                }
                builder.append("\n");
            }
        }
    }

    static void appendRecentAgentOutputs(
            StringBuilder builder,
            TaskHandler.TaskContext context,
            int maxRecentAgentOutputs
    ) {
        appendRoutedAgentOutputs(builder, context, maxRecentAgentOutputs);
    }

    private static void appendHumanFeedbackNode(StringBuilder builder, Map<String, Object> node) {
        var result = resultMap(node);
        builder.append("### ").append(text(node.get("nodeDefinitionId"))).append("\n\n");
        builder.append("- Action: ").append(text(result.get("human_action"))).append("\n");
        builder.append("- Finished At: ").append(text(node.get("finishedAt"))).append("\n\n");
        builder.append("```text\n");
        builder.append(text(result.get("note")).stripTrailing());
        builder.append("\n```\n\n");
    }

    private static void appendRoutedAgentOutputs(
            StringBuilder builder,
            TaskHandler.TaskContext context,
            int maxItems
    ) {
        var entries = AgentEvidenceIndex.fromRefs(
                context.workspaceRoot(), context.workstreamId(), context.instance().inputRefs(), OBJECT_MAPPER)
                .recent(maxItems);
        if (entries.isEmpty()) {
            builder.append("(no routed validated agent outputs)\n\n");
            return;
        }
        for (var entry : entries) {
            appendAgentContractSummary(builder, entry);
        }
    }

    private static void appendAgentContractSummary(StringBuilder builder, AgentEvidenceIndex.Entry entry) {
        var contract = entry.document();
        builder.append("### ").append(toDisplayRef(entry.path())).append("\n\n");
        appendAgentContractFields(builder, contract, entry.path());
    }

    private static void appendAgentContractFields(
            StringBuilder builder,
            AgentOutputContractDocument contract,
            Path sidecar
    ) {
        appendAgentContractFields(builder, contract, sidecar, false);
    }

    private static void appendAgentContractFields(
            StringBuilder builder,
            AgentOutputContractDocument contract,
            Path sidecar,
            boolean includeArchitectureEvidence
    ) {
        var nodeId = contract.nodeId();
        var decision = contract.decision();
        var summary = contract.summary();
        if (nodeId.isBlank() && decision.isBlank() && summary.isBlank()) {
            builder.append("(validated agent result has no summary fields)\n\n");
            return;
        }
        if (!nodeId.isBlank()) {
            builder.append("- Contract: ").append(nodeId).append("\n");
        }
        if (!decision.isBlank()) {
            builder.append("- Decision: ").append(decision).append("\n");
        }
        if (!summary.isBlank()) {
            builder.append("- Summary: ").append(summary).append("\n");
        }
        if (includeArchitectureEvidence) {
            appendListSection(builder, "Checks", contract.checks());
            appendListSection(builder, "Evidence", contract.evidence());
        }
        appendListSummary(builder, "Must Fix", contract.mustFix());
        appendReviewObligations(builder, contract.contractObligations());
        appendListSummary(builder, "Open Risks", contract.openRisks());
        appendListSummary(builder, "Changed Files", contract.changedFiles());
        var verification = contract.verificationSummary();
        if (!verification.isBlank()) {
            builder.append("- Verification: ").append(verification.replace("\n", " / ")).append("\n");
        }
        builder.append("- Contract Sidecar: ").append(toDisplayRef(sidecar)).append("\n");
        builder.append("- Raw Output: ").append(contract.sourceOutputRef()).append("\n\n");
        appendTypedPlanArtifact(builder, contract.planArtifact());
    }

    private static void appendReviewObligations(
            StringBuilder builder,
            List<AgentResultEnvelope.ReviewObligation> obligations
    ) {
        if (obligations == null || obligations.isEmpty()) {
            return;
        }
        builder.append("- Contract Obligations:\n");
        for (var obligation : obligations) {
            builder.append("  - [").append(obligation.id()).append("] ")
                    .append(obligation.text()).append("\n");
        }
    }

    private static void appendTypedPlanArtifact(StringBuilder builder, PlanArtifactDocument plan) {
        if (plan == null) {
            return;
        }
        builder.append("**Typed Plan Evidence:**\n\n");
        appendListSection(builder, "Implementation Steps", plan.implementationSteps());
        appendListSection(builder, "Edit Files", plan.editFiles());
        appendListSection(builder, "Reference Files", plan.referenceFiles());
        appendListSection(builder, "File-Level Changes", plan.fileLevelChanges());
        appendListSection(builder, "Validation Plan", plan.validationPlan());
        if (!plan.rollbackNotes().isBlank()) {
            builder.append("**Rollback Notes:** ").append(plan.rollbackNotes()).append("\n\n");
        }
        appendListSection(builder, "Known Risks", plan.knownRisks());
        appendListSection(builder, "Human Review Checklist", plan.humanReviewChecklist());
    }

    private static void appendListSummary(StringBuilder builder, String label, Object value) {
        if (!(value instanceof List<?> items) || items.isEmpty()) {
            return;
        }
        var texts = items.stream()
                .map(ContextPackageSectionRenderer::text)
                .filter(item -> !item.isBlank())
                .toList();
        if (!texts.isEmpty()) {
            builder.append("- ").append(label).append(": ").append(String.join("; ", texts)).append("\n");
        }
    }

    private static void appendListSection(StringBuilder builder, String title, List<String> items) {
        if (items.isEmpty()) {
            return;
        }
        builder.append("**").append(title).append(":**\n");
        for (var item : items) {
            builder.append("- ").append(item).append("\n");
        }
        builder.append("\n");
    }

    private static List<String> resolvedQuestionTexts(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var result = new ArrayList<String>();
        for (var item : items) {
            if (item instanceof Map<?, ?> map) {
                var question = text(map.get("question"));
                var resolution = text(map.get("resolution"));
                if (!question.isBlank()) {
                    result.add(resolution.isBlank() ? question : question + " -> " + resolution);
                }
            }
        }
        return List.copyOf(result);
    }

    private static List<String> listOfText(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        return items.stream()
                .map(ContextPackageSectionRenderer::text)
                .filter(item -> !item.isBlank())
                .toList();
    }

    private static Map<String, Object> readNodeUnchecked(Path path) {
        return readJsonUnchecked(path);
    }

    private static Map<String, Object> readJsonUnchecked(Path path) {
        try {
            return OBJECT_MAPPER.readValue(path.toFile(), MAP_TYPE);
        } catch (IOException e) {
            return Map.of();
        }
    }

    private static boolean hasHumanFeedback(Map<String, Object> node) {
        var result = resultMap(node);
        return result.containsKey("human_action") && !text(result.get("note")).isBlank();
    }

    private static String finishedAtText(Map<String, Object> node) {
        return text(node.get("finishedAt"));
    }

    private static Map<String, Object> resultMap(Map<String, Object> node) {
        var result = node.get("result");
        if (result instanceof Map<?, ?> map) {
            var copy = new LinkedHashMap<String, Object>();
            for (Map.Entry<?, ?> entry : map.entrySet()) {
                if (entry.getKey() instanceof String key) {
                    copy.put(key, entry.getValue());
                }
            }
            return copy;
        }
        return Map.of();
    }

    private static boolean isAgentResultCandidate(Path path) {
        var parent = path.getParent();
        return parent != null
                && "outputs".equals(parent.getFileName().toString())
                && path.getFileName().toString().endsWith(".json");
    }

    private static boolean isExecutionDiagnostic(Path path) {
        var fileName = path.getFileName().toString();
        return fileName.endsWith(".stderr.log")
                || fileName.endsWith(".stdout.log")
                || fileName.endsWith(".transcript.log")
                || fileName.endsWith(".meta.json");
    }

    private static boolean isTranscriptArtifact(Path path) {
        return path.getFileName().toString().endsWith(".transcript.log");
    }

    private static Instant lastModified(Path path) {
        try {
            return Files.readAttributes(path, BasicFileAttributes.class).lastModifiedTime().toInstant();
        } catch (IOException ignored) {
            return Instant.EPOCH;
        }
    }

    private static String snippet(Path path, int maxSnippetChars) throws IOException {
        var content = Files.readString(path, StandardCharsets.UTF_8);
        if (content.length() <= maxSnippetChars) {
            return content.stripTrailing();
        }
        return content.substring(0, maxSnippetChars).stripTrailing()
                + "\n\n[truncated; read full artifact at " + toDisplayRef(path) + "]";
    }

    private static String snippetWithoutToolLog(Path path, int maxSnippetChars) throws IOException {
        var content = Files.readString(path, StandardCharsets.UTF_8);
        var sanitized = content.lines()
                .filter(line -> !line.startsWith("[tool] "))
                .filter(line -> !line.startsWith("[client] "))
                .filter(line -> !line.startsWith("  input: "))
                .filter(line -> !line.startsWith("  output:"))
                .filter(line -> !line.startsWith("  kind: "))
                .limit(80)
                .collect(java.util.stream.Collectors.joining("\n"));
        if (sanitized.isBlank()) {
            sanitized = "(agent output contains only tool/client frames; read raw output at " + toDisplayRef(path) + ")";
        }
        if (sanitized.length() <= maxSnippetChars) {
            return sanitized.stripTrailing();
        }
        return sanitized.substring(0, maxSnippetChars).stripTrailing()
                + "\n\n[truncated sanitized fallback; read raw output at " + toDisplayRef(path) + "]";
    }

    private static String toDisplayRef(Path path) {
        return path.toAbsolutePath().normalize().toString();
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    private static int iterationNumber(Map<String, Object> iteration) {
        var number = iteration.get("number");
        if (number instanceof Number numeric) {
            return numeric.intValue();
        }
        var iterationId = text(iteration.get("iterationId"));
        if (iterationId.matches("iter-\\d{3}")) {
            return Integer.parseInt(iterationId.substring("iter-".length()));
        }
        return 0;
    }

    private static String blankAsNone(String value) {
        return value == null || value.isBlank() ? "(none)" : value;
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.contract.TaskContract;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.ledger.file.WorkstreamPaths;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class ArtifactValidateHandler implements TaskHandler {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper()
            .registerModule(new JavaTimeModule())
            .enable(SerializationFeature.INDENT_OUTPUT);

    @Override
    public String type() {
        return "artifact.validate";
    }

    @Override
    public NodeResult execute(TaskContext context) throws Exception {
        var qualified = qualifiedContract(context);
        if (qualified.failure() != null) {
            return qualificationFailure(qualified.failure());
        }
        var evidenceDir = context.workspaceRoot()
                .resolve(".agent")
                .resolve("workstreams")
                .resolve(context.workstreamId())
                .resolve("artifacts")
                .resolve("git-evidence");
        Files.createDirectories(evidenceDir);

        var evidence = collectEvidence(context.workspaceRoot(), context.workstreamId(), evidenceDir);
        writeEvidenceJson(evidenceDir.resolve("git-evidence.json"), evidence);
        var evaluation = evaluateChangeScope(evidence, qualified.contract());
        var evaluationPath = evidenceDir.resolve("change-scope-evaluation.json");
        OBJECT_MAPPER.writeValue(evaluationPath.toFile(), evaluation);
        var occurrence = ChangeScopeEvaluationArtifact.publish(
                context.workspaceRoot(),
                context.workstreamId(),
                context.instance().nodeInstanceId(),
                evaluation);

        var outputRefs = new ArrayList<String>();
        outputRefs.addAll(AgentEvidenceIndex.fromRefs(
                        context.workspaceRoot(), context.workstreamId(), context.instance().inputRefs(), OBJECT_MAPPER)
                .validatedSidecarRefs(context.workspaceRoot()));
        for (String fileName : List.of(
                "git-evidence.json",
                "base-commit.txt",
                "head-commit.txt",
                "branch.txt",
                "git-root.txt",
                "git-status-short.txt",
                "git-name-status.txt",
                "diff.stat",
                "diff.patch",
                "changed-files.txt",
                "hygiene-warnings.txt",
                "change-scope-evaluation.json"
        )) {
            var path = evidenceDir.resolve(fileName);
            if (Files.exists(path)) {
                outputRefs.add(toWorkspaceRef(context.workspaceRoot(), path));
            }
        }
        outputRefs.add(occurrence.ref());

        var result = new LinkedHashMap<String, Object>();
        result.put("validation", evidence.available() ? "git_evidence_collected" : "git_unavailable");
        result.put("mode", "git-evidence");
        result.put("git_available", evidence.available());
        result.put("has_changes", evidence.hasChanges());
        result.put("changed_file_count", evidence.changedFileCount());
        result.put("hygiene_warning_count", evidence.hygieneWarningCount());
        result.put("change_scope_status", evaluation.status().name());
        result.put("change_scope_violation_count", evaluation.violations().size());
        result.put("change_scope_missing_declared_count", evaluation.missingDeclared().size());
        result.put("evidence_path", toWorkspaceRef(
                context.workspaceRoot(),
                evidenceDir.resolve("git-evidence.json")
        ));
        result.put("change_scope_evaluation_path", toWorkspaceRef(context.workspaceRoot(), evaluationPath));
        result.put("change_scope_evaluation_ref", occurrence.ref());
        result.put("change_scope_evaluation_sha256", occurrence.sha256());
        result.put("error", evidence.error());

        if (!evaluation.passed()) {
            var outcome = evaluation.status() == ChangeScopeEvaluation.Status.UNAVAILABLE
                    ? "CHANGE_SCOPE_EVIDENCE_UNAVAILABLE"
                    : "CHANGE_SCOPE_VIOLATION";
            var error = evaluation.error() == null
                    ? "actual Git changes do not satisfy TaskContract.scope"
                    : evaluation.error();
            if (evaluation.status() == ChangeScopeEvaluation.Status.FAIL && routesScopeViolation(context)) {
                if (qualified.reference() != null) {
                    result.putAll(TaskContractRevisionContextResolver.captureScopeReworkBaseline(
                            context.workspaceRoot(), context.workstreamId(), qualified.reference(), occurrence));
                }
                result.put("change_scope_disposition", "CHANGE_SCOPE_VIOLATION");
                result.put("change_scope_message", error);
                return new NodeResult(outcome, NodeStatus.COMPLETED, outputRefs, result, null);
            }
            return new NodeResult(outcome, NodeStatus.FAILED, outputRefs, result, error);
        }
        return NodeResult.completed("completed", outputRefs, result);
    }

    private static boolean routesScopeViolation(TaskContext context) {
        var configured = context.definition().config().get("route_scope_violation");
        if (configured == null) {
            return false;
        }
        if (!(configured instanceof Boolean enabled)) {
            throw new IllegalArgumentException("route_scope_violation must be a boolean");
        }
        return enabled;
    }

    private static GitEvidence collectEvidence(Path workdir, String workstreamId, Path evidenceDir) throws IOException, InterruptedException {
        var generatedAt = Instant.now().toString();
        var gitRoot = git(workdir, "rev-parse", "--show-toplevel");
        if (gitRoot.exitCode() != 0) {
            return new GitEvidence(
                    "1",
                    false,
                    workdir.toAbsolutePath().normalize().toString(),
                    null,
                    null,
                    null,
                    null,
                    null,
                    null,
                    null,
                    false,
                    0,
                    0,
                    generatedAt,
                    "git repository unavailable: " + gitRoot.output().trim(),
                    List.of()
            );
        }

        var branchResult = git(workdir, "branch", "--show-current");
        var headResult = git(workdir, "rev-parse", "HEAD");
        var statusResult = git(workdir, "status", "--short", "--untracked-files=all", "--", ".", ":!.agent");
        if (branchResult.exitCode() != 0 || headResult.exitCode() != 0 || statusResult.exitCode() != 0) {
            return new GitEvidence(
                    "1",
                    false,
                    workdir.toAbsolutePath().normalize().toString(),
                    gitRoot.output().trim(),
                    null,
                    null,
                    null,
                    null,
                    null,
                    null,
                    false,
                    0,
                    0,
                    generatedAt,
                    "required Git evidence command failed",
                    List.of()
            );
        }
        var branch = branchResult.output().trim();
        var headCommit = headResult.output().trim();
        var base = readWorkspaceBase(workdir, workstreamId);
        var statusShort = statusResult.output();
        var untrackedResult = git(
                workdir,
                "ls-files",
                "--others",
                "--exclude-standard",
                "-z",
                "--",
                ".",
                ":!.agent"
        );
        if (untrackedResult.exitCode() != 0) {
            return unavailableGitEvidence(
                    workdir,
                    gitRoot.output().trim(),
                    branch,
                    base,
                    headCommit,
                    generatedAt,
                    "git ls-files --others failed: " + untrackedResult.output().trim()
            );
        }
        final List<String> untrackedFiles;
        try {
            untrackedFiles = parseNulPaths(untrackedResult.output());
        } catch (IllegalArgumentException exception) {
            return unavailableGitEvidence(
                    workdir,
                    gitRoot.output().trim(),
                    branch,
                    base,
                    headCommit,
                    generatedAt,
                    "git ls-files --others returned malformed NUL framing: " + exception.getMessage()
            );
        }
        var branchRange = base.baseCommit() == null || base.baseCommit().isBlank()
                ? null
                : base.baseCommit() + "...HEAD";
        if (branchRange != null && !commitExists(workdir, base.baseCommit())) {
            branchRange = null;
        }
        var diffStat = buildDiffStat(workdir, untrackedFiles, branchRange);
        var diffPatch = buildDiffPatch(workdir, untrackedFiles, branchRange);
        var nameStatus = buildNameStatus(workdir, untrackedFiles, base.baseCommit());
        if (nameStatus.exitCode() != 0) {
            return new GitEvidence(
                    "1",
                    false,
                    workdir.toAbsolutePath().normalize().toString(),
                    gitRoot.output().trim(),
                    branch,
                    base.baseBranch(),
                    base.baseCommit(),
                    headCommit,
                    base.source(),
                    branchRange,
                    false,
                    0,
                    0,
                    generatedAt,
                    "git diff --name-status failed: " + nameStatus.output().trim(),
                    List.of()
            );
        }
        final List<ChangeScopeEvaluation.ActualChange> actualChanges;
        try {
            actualChanges = ChangeScopeEvaluator.parseNameStatus(nameStatus.exitCode(), nameStatus.output());
        } catch (IllegalArgumentException exception) {
            return unavailableGitEvidence(
                    workdir,
                    gitRoot.output().trim(),
                    branch,
                    base,
                    headCommit,
                    generatedAt,
                    "git diff --name-status returned malformed NUL framing: " + exception.getMessage()
            );
        }
        var changedFiles = actualChanges.stream()
                .map(ChangeScopeEvaluation.ActualChange::path)
                .distinct()
                .toList();
        var hygieneWarnings = hygieneWarnings(changedFiles);

        write(evidenceDir.resolve("git-root.txt"), gitRoot.output().trim() + "\n");
        write(evidenceDir.resolve("branch.txt"), branch + "\n");
        write(evidenceDir.resolve("base-commit.txt"), textOrEmpty(base.baseCommit()) + "\n");
        write(evidenceDir.resolve("head-commit.txt"), headCommit + "\n");
        write(evidenceDir.resolve("git-status-short.txt"), statusShort);
        write(evidenceDir.resolve("git-name-status.txt"), nameStatus.output());
        write(evidenceDir.resolve("diff.stat"), diffStat);
        write(evidenceDir.resolve("diff.patch"), diffPatch);
        var changedFilesText = String.join("\n", changedFiles) + (changedFiles.isEmpty() ? "" : "\n");
        write(evidenceDir.resolve("changed-files.txt"), changedFilesText);
        if (!hygieneWarnings.isEmpty()) {
            write(evidenceDir.resolve("hygiene-warnings.txt"), String.join("\n", hygieneWarnings) + "\n");
        }

        return new GitEvidence(
                "1",
                true,
                workdir.toAbsolutePath().normalize().toString(),
                gitRoot.output().trim(),
                branch,
                base.baseBranch(),
                base.baseCommit(),
                headCommit,
                base.source(),
                branchRange,
                !statusShort.isBlank() || !changedFiles.isEmpty(),
                changedFiles.size(),
                hygieneWarnings.size(),
                generatedAt,
                null,
                actualChanges
        );
    }

    private static GitEvidence unavailableGitEvidence(
            Path workdir,
            String gitRoot,
            String branch,
            WorkspaceBase base,
            String headCommit,
            String generatedAt,
            String error
    ) {
        return new GitEvidence(
                "1",
                false,
                workdir.toAbsolutePath().normalize().toString(),
                gitRoot,
                branch,
                base.baseBranch(),
                base.baseCommit(),
                headCommit,
                base.source(),
                null,
                false,
                0,
                0,
                generatedAt,
                error,
                List.of()
        );
    }

    private static CommandResult buildNameStatus(Path workdir, List<String> untrackedFiles, String baseCommit)
            throws IOException, InterruptedException {
        var comparisonBase = baseCommit != null && !baseCommit.isBlank() && commitExists(workdir, baseCommit)
                ? baseCommit
                : "HEAD";
        var result = git(
                workdir,
                "diff",
                "--name-status",
                "-z",
                "--find-renames",
                comparisonBase,
                "--",
                ".",
                ":!.agent"
        );
        if (result.exitCode() != 0) {
            return result;
        }
        var builder = new StringBuilder(result.output());
        for (var file : untrackedFiles) {
            if (!Files.isDirectory(workdir.resolve(file))) {
                builder.append("A").append('\0').append(file).append('\0');
            }
        }
        return new CommandResult(0, builder.toString());
    }

    private static String buildDiffStat(Path workdir, List<String> untrackedFiles, String branchRange)
            throws IOException, InterruptedException {
        var builder = new StringBuilder();
        if (branchRange != null) {
            builder.append(git(workdir, "diff", "--stat", branchRange, "--", ".", ":!.agent").output());
        }
        builder.append(git(workdir, "diff", "--cached", "--stat", "--", ".", ":!.agent").output());
        builder.append(git(workdir, "diff", "--stat", "--", ".", ":!.agent").output());
        for (String file : untrackedFiles) {
            if (Files.isDirectory(workdir.resolve(file))) {
                continue;
            }
            var result = git(workdir, "diff", "--no-index", "--stat", "--", "/dev/null", file);
            if (!result.output().isBlank()) {
                builder.append(result.output());
            }
        }
        return builder.toString();
    }

    private static String buildDiffPatch(Path workdir, List<String> untrackedFiles, String branchRange)
            throws IOException, InterruptedException {
        var builder = new StringBuilder();
        if (branchRange != null) {
            builder.append(git(workdir, "diff", branchRange, "--", ".", ":!.agent").output());
        }
        builder.append(git(workdir, "diff", "--cached", "--", ".", ":!.agent").output());
        builder.append(git(workdir, "diff", "--", ".", ":!.agent").output());
        for (String file : untrackedFiles) {
            if (Files.isDirectory(workdir.resolve(file))) {
                continue;
            }
            var result = git(workdir, "diff", "--no-index", "--", "/dev/null", file);
            if (!result.output().isBlank()) {
                builder.append(result.output());
            }
        }
        return builder.toString();
    }

    private static WorkspaceBase readWorkspaceBase(Path workdir, String workstreamId) throws IOException {
        if (workstreamId == null || workstreamId.isBlank()) {
            return WorkspaceBase.unavailable();
        }
        var paths = new WorkstreamPaths(workdir, new dev.dual.core.id.DualId(workstreamId));
        if (!Files.isRegularFile(paths.workstreamJson())) {
            return WorkspaceBase.unavailable();
        }
        var workstream = OBJECT_MAPPER.readTree(paths.workstreamJson().toFile());
        var workspaceId = workstream.path("primaryWorkspaceId").asText("");
        if (workspaceId.isBlank()) {
            return WorkspaceBase.unavailable();
        }
        var workspaceJson = paths.workstreamDir().resolve("workspaces").resolve(workspaceId + ".json");
        if (!Files.isRegularFile(workspaceJson)) {
            return WorkspaceBase.unavailable();
        }
        var workspace = OBJECT_MAPPER.readTree(workspaceJson.toFile());
        return new WorkspaceBase(
                textOrNull(workspace.path("baseBranch").asText("")),
                textOrNull(workspace.path("baseCommit").asText("")),
                "workspace_metadata"
        );
    }

    private static boolean commitExists(Path workdir, String commit) throws IOException, InterruptedException {
        return git(workdir, "cat-file", "-e", commit + "^{commit}").exitCode() == 0;
    }

    private static List<String> parseNulPaths(String framedPaths) {
        if (framedPaths == null || framedPaths.isEmpty()) {
            return List.of();
        }
        var fields = framedPaths.split(String.valueOf('\0'), -1);
        if (fields.length < 2 || !fields[fields.length - 1].isEmpty()) {
            throw new IllegalArgumentException("git path output is not NUL terminated");
        }
        var paths = new ArrayList<String>(fields.length - 1);
        for (var index = 0; index < fields.length - 1; index++) {
            if (fields[index].isEmpty()) {
                throw new IllegalArgumentException("git path output contains an empty path");
            }
            paths.add(fields[index]);
        }
        return List.copyOf(paths);
    }

    private static List<String> hygieneWarnings(List<String> changedFiles) {
        var warnings = new ArrayList<String>();
        for (String file : changedFiles) {
            if (isLikelyGeneratedByproduct(file)) {
                warnings.add(file + " looks like a generated self-test byproduct; remove it unless it is an intentional deliverable.");
            }
        }
        return warnings;
    }

    private static boolean isLikelyGeneratedByproduct(String file) {
        return file.equals("__pycache__/")
                || file.startsWith("__pycache__/")
                || file.contains("/__pycache__/")
                || file.equals(".pytest_cache/")
                || file.startsWith(".pytest_cache/")
                || file.contains("/.pytest_cache/")
                || file.endsWith(".pyc")
                || file.endsWith(".pyo")
                || file.endsWith(".coverage")
                || file.endsWith(".tmp")
                || file.endsWith(".log")
                || file.equals(".DS_Store")
                || file.endsWith("/.DS_Store");
    }

    private static void write(Path path, String content) throws IOException {
        Files.writeString(path, content, StandardCharsets.UTF_8);
    }

    private static void writeEvidenceJson(Path path, GitEvidence evidence) throws IOException {
        var json = new LinkedHashMap<String, Object>();
        json.put("schemaVersion", evidence.schemaVersion());
        json.put("available", evidence.available());
        json.put("workdir", evidence.workdir());
        json.put("gitRoot", evidence.gitRoot());
        json.put("branch", evidence.branch());
        json.put("baseBranch", evidence.baseBranch());
        json.put("baseCommit", evidence.baseCommit());
        json.put("headCommit", evidence.headCommit());
        json.put("baseSource", evidence.baseSource());
        json.put("comparisonRange", evidence.comparisonRange());
        json.put("hasChanges", evidence.hasChanges());
        json.put("changedFileCount", evidence.changedFileCount());
        json.put("hygieneWarningCount", evidence.hygieneWarningCount());
        json.put("generatedAt", evidence.generatedAt());
        json.put("error", evidence.error());
        json.put("actualChanges", evidence.actualChanges());
        OBJECT_MAPPER.writeValue(path.toFile(), json);
    }

    private static ChangeScopeEvaluation evaluateChangeScope(
            GitEvidence evidence,
            TaskContract contract
    ) {
        if (!evidence.available()) {
            return ChangeScopeEvaluation.unavailable("Git evidence is unavailable");
        }
        if (evidence.comparisonRange() == null || evidence.comparisonRange().isBlank()) {
            return ChangeScopeEvaluation.unavailable("Workspace base commit is unavailable");
        }
        if (contract == null) {
            return ChangeScopeEvaluation.unavailable("TaskContract artifact is missing");
        }
        return ChangeScopeEvaluator.evaluate(contract, evidence.actualChanges());
    }

    private static QualifiedContract qualifiedContract(TaskContext context) {
        if (!AgentRunGovernanceContext.requiresApprovedTaskContract(context)) {
            var legacy = TaskContractProjectionVerifier.readLegacyProjection(
                    context.workspaceRoot(), context.workstreamId());
            if (legacy.projection().isPresent()
                    && legacy.projection().orElseThrow().contract() != null) {
                var contract = legacy.projection().orElseThrow().contract();
                var errors = dev.dual.core.contract.TaskContractValidator.validate(contract);
                if (!errors.isEmpty()) {
                    return new QualifiedContract(null, TaskContractProjectionVerifier.Failure.of(
                            "CONTRACT_INVALID", String.join("; ", errors)));
                }
            }
            return legacy.failure() != null
                    ? new QualifiedContract(null, legacy.failure())
                    : new QualifiedContract(
                            legacy.projection().map(TaskContractProjectionVerifier.LegacyProjection::contract).orElse(null),
                            null);
        }
        var resolution = TaskContractProjectionVerifier.resolve(context.workspaceRoot(), context.workstreamId());
        if (resolution.failure() != null) {
            return new QualifiedContract(null, resolution.failure());
        }
        return resolution.qualified()
                .map(value -> new QualifiedContract(value.contract(), null, value))
                .orElseGet(() -> new QualifiedContract(null, TaskContractProjectionVerifier.Failure.of(
                        "APPROVAL_BINDING_MISSING", "change-scope validation requires an approved task contract")));
    }

    private static NodeResult qualificationFailure(TaskContractProjectionVerifier.Failure failure) {
        return new NodeResult(
                TaskContractProjectionVerifier.FAILURE_OUTCOME,
                NodeStatus.FAILED,
                List.of(),
                Map.of(
                        "failure_code", TaskContractProjectionVerifier.FAILURE_OUTCOME,
                        "reason", failure.reason(),
                        "error", failure.message()),
                failure.message());
    }

    private static String toWorkspaceRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize().relativize(path.toAbsolutePath().normalize()).toString();
    }

    private static CommandResult git(Path workdir, String... args) throws IOException, InterruptedException {
        var command = new ArrayList<String>();
        command.add("git");
        command.addAll(List.of(args));
        var process = new ProcessBuilder(command)
                .directory(workdir.toFile())
                .redirectErrorStream(true)
                .start();
        var output = new String(process.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
        var exitCode = process.waitFor();
        return new CommandResult(exitCode, output);
    }

    private record CommandResult(int exitCode, String output) {
    }

    private record QualifiedContract(TaskContract contract, TaskContractProjectionVerifier.Failure failure,
                                     TaskContractProjectionVerifier.QualifiedTaskContract reference) {
        QualifiedContract(TaskContract contract, TaskContractProjectionVerifier.Failure failure) {
            this(contract, failure, null);
        }
    }

    private static String textOrNull(String value) {
        return value == null || value.isBlank() ? null : value.trim();
    }

    private static String textOrEmpty(String value) {
        return value == null ? "" : value;
    }

    private record WorkspaceBase(String baseBranch, String baseCommit, String source) {
        static WorkspaceBase unavailable() {
            return new WorkspaceBase(null, null, "unavailable");
        }
    }

    private record GitEvidence(
            String schemaVersion,
            boolean available,
            String workdir,
            String gitRoot,
            String branch,
            String baseBranch,
            String baseCommit,
            String headCommit,
            String baseSource,
            String comparisonRange,
            boolean hasChanges,
            int changedFileCount,
            int hygieneWarningCount,
            String generatedAt,
            String error,
            List<ChangeScopeEvaluation.ActualChange> actualChanges
    ) {
        GitEvidence {
            actualChanges = List.copyOf(actualChanges == null ? List.of() : actualChanges);
        }
    }
}

package dev.dual.runtime.handler;

record DegradationPolicy(
        Degradation strategy,
        int maxItems
) {
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.NodeStatus;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

public final class ContextBuildPackageHandler implements TaskHandler {
    private static final int MAX_SNIPPET_CHARS = 4_000;
    private static final int MAX_RECENT_AGENT_OUTPUTS = 8;
    private static final TokenEstimator TOKEN_ESTIMATOR = TokenEstimator.defaultEstimator();
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper().registerModule(new JavaTimeModule());
    private static final List<String> FULL_SECTIONS = List.of(
            "requirement",
            "input_artifacts",
            "iteration_history",
            "human_feedback",
            "recent_agent_outputs",
            "working_memory",
            "review_evidence",
            "git_evidence",
            "ledger_pointers",
            "task_contract"
    );
    private static final List<String> MEMORY_SECTIONS = List.of("working_memory", "review_evidence");

    @Override
    public String type() {
        return "context.build_package";
    }

    @Override
    public NodeResult execute(TaskContext context) throws Exception {
        var workstreamDir = context.workspaceRoot()
                .resolve(".agent")
                .resolve("workstreams")
                .resolve(context.workstreamId());
        var contextDir = workstreamDir.resolve("context");
        var packagePath = contextDir.resolve(context.instance().nodeInstanceId() + ".md");
        var profileName = profile(context);
        var hasSectionOverride = context.definition().config().get("include_sections") instanceof List<?>;
        if ("acceptance".equals(profileName) && hasSectionOverride) {
            return new NodeResult(
                    "MANDATORY_CONTEXT_SECTION_OVERRIDE_REJECTED",
                    NodeStatus.FAILED,
                    List.of(),
                    Map.of(
                            "failure_code", "MANDATORY_CONTEXT_SECTION_OVERRIDE_REJECTED",
                            "error", "acceptance profile cannot override mandatory context sections"),
                    null);
        }
        var qualifiedContract = Optional.<TaskContractProjectionVerifier.QualifiedTaskContract>empty();
        var requiresQualification = AgentRunGovernanceContext.requiresApprovedTaskContract(context);
        if (requiresQualification || "acceptance".equals(profileName)) {
            var resolution = TaskContractProjectionVerifier.resolve(context.workspaceRoot(), context.workstreamId());
            if (resolution.failure() != null) {
                return qualificationFailure(resolution.failure());
            }
            qualifiedContract = resolution.qualified();
            if (requiresQualification && qualifiedContract.isEmpty()) {
                return qualificationFailure(TaskContractProjectionVerifier.Failure.of(
                        "APPROVAL_BINDING_MISSING", "node requires an approved task contract"));
            }
        }
        var requiredInputArtifact = configText(context, "required_input_artifact", "");
        if (!requiredInputArtifact.isBlank() && !"task_contract_proposal".equals(requiredInputArtifact)) {
            return new NodeResult(
                    "failed",
                    NodeStatus.FAILED,
                    List.of(),
                    Map.of("error", "unsupported required input artifact: " + requiredInputArtifact),
                    null);
        }
        var reviewSubject = resolveRequiredReviewSubject(context);
        var architectureReviewSubject = resolveRequiredArchitectureReviewSubject(context);
        if (requiresTaskContractProposal(context) && reviewSubject.isEmpty()) {
            return new NodeResult(
                    "failed",
                    NodeStatus.FAILED,
                    List.of(),
                    Map.of("error", "verified task-contract proposal reference is required for product review"),
                    null);
        }
        if (requiresArchitectureReviewSubject(context) && architectureReviewSubject.isEmpty()) {
            return new NodeResult(
                    "REQUIRED_AGENT_EVIDENCE_MISSING",
                    NodeStatus.FAILED,
                    List.of(),
                    Map.of(
                            "failure_code", "REQUIRED_AGENT_EVIDENCE_MISSING",
                            "error", "validated design review subject is required for architecture review"),
                    null);
        }
        var missingAgentEvidence = missingRequiredAgentEvidence(context);
        if (missingAgentEvidence.isPresent()) {
            return new NodeResult(
                    "REQUIRED_AGENT_EVIDENCE_MISSING",
                    NodeStatus.FAILED,
                    List.of(),
                    Map.of(
                            "failure_code", "REQUIRED_AGENT_EVIDENCE_MISSING",
                            "required_agent_evidence", missingAgentEvidence.get().toMap(),
                            "error", "required validated agent evidence is missing: "
                                    + missingAgentEvidence.get().description()),
                    null);
        }

        String revisionBody = "";
        if (reviewSubject.isPresent()) {
            try {
                revisionBody = renderContractRevision(contractRevisionProjection(
                        context.workspaceRoot(), context.workstreamId(), context.instance().iterationId(),
                        reviewSubject.get().reference()));
            } catch (IOException | IllegalArgumentException failure) {
                return new NodeResult("REQUIRED_AGENT_EVIDENCE_MISSING", NodeStatus.FAILED, List.of(),
                        Map.of("failure_code", "CONTRACT_REVISION_CONTEXT_INVALID", "error", failure.getMessage()),
                        failure.getMessage());
            }
        }
        String authoredBody = "";
        if (AuthoredStageLineageResolver.participates(configText(context, "target_node", ""))) {
            try {
                authoredBody = new AuthoredStageLineageResolver(context.workspaceRoot(), context.workstreamId(), Long.MAX_VALUE)
                        .contextBody(context);
            } catch (IOException | IllegalArgumentException failure) {
                return new NodeResult("REQUIRED_AGENT_EVIDENCE_MISSING", NodeStatus.FAILED, List.of(),
                        Map.of("failure_code", "AUTHORED_CONTEXT_INVALID", "error", failure.getMessage()), failure.getMessage());
            }
        }
        Files.createDirectories(contextDir);

        if (ContextProfiles.hasProfile(profileName) && !hasSectionOverride) {
            return executeGoverned(context, workstreamDir, packagePath, profileName,
                    reviewSubject, architectureReviewSubject, qualifiedContract, authoredBody, revisionBody);
        }

        var requestedSections = effectiveSections(context);
        var manifest = requestedSections.stream().anyMatch(ContextBuildPackageHandler::requiresEvidenceManifest)
                ? EvidenceManifest.rebuild(context.workspaceRoot(), workstreamDir, context.workstreamId(),
                        context.instance().inputRefs(), OBJECT_MAPPER)
                : null;
        var manifestPath = manifest == null ? null : manifest.write(workstreamDir, OBJECT_MAPPER);
        var governance = governanceEnabled()
                ? RepoScopeGovernance.build(context.workspaceRoot(), workstreamDir, context, OBJECT_MAPPER)
                : null;
        var markdown = renderPackage(context, workstreamDir, manifest, governance,
                reviewSubject, architectureReviewSubject);
        if (!authoredBody.isEmpty()) markdown += "\n\n" + authoredBody;
        markdown += revisionBody;
        Files.writeString(packagePath, markdown, StandardCharsets.UTF_8);
        var requiredTypedSubjectTokens = new LinkedHashMap<>(
                requiredTypedSubjectTokens(reviewSubject, architectureReviewSubject));
        if (!revisionBody.isEmpty()) requiredTypedSubjectTokens.put("contract_revision", tokenCount(revisionBody));
        var metadataPath = writeContextPackageMetadata(
                context,
                packagePath,
                profileName,
                null,
                tokenCount(markdown),
                List.of(),
                manifest,
                manifestPath,
                memoryEnabled(),
                disabledMemorySections(sections(context), requestedSections),
                governance,
                requiredTypedSubjectTokens
        );

        return buildLegacyResult(context, packagePath, metadataPath, requestedSections);
    }

    private static NodeResult buildLegacyResult(TaskContext context, Path packagePath) {
        return buildLegacyResult(context, packagePath, null, effectiveSections(context));
    }

    private static NodeResult buildLegacyResult(TaskContext context, Path packagePath, Path metadataPath) {
        return buildLegacyResult(context, packagePath, metadataPath, effectiveSections(context));
    }

    private static NodeResult buildLegacyResult(
            TaskContext context,
            Path packagePath,
            Path metadataPath,
            List<String> includedSections
    ) {
        var packageRef = toWorkspaceRef(context.workspaceRoot(), packagePath);
        var result = new LinkedHashMap<String, Object>();
        result.put("context_package", packageRef);
        if (metadataPath != null) {
            result.put("context_package_metadata", toWorkspaceRef(context.workspaceRoot(), metadataPath));
        }
        result.put("target_node", configText(context, "target_node", ""));
        result.put("profile", profile(context));
        result.put("sections", includedSections);
        result.put("input_ref_count", context.instance().inputRefs().size());
        result.put("generated_at", Instant.now().toString());
        var outputRefs = new ArrayList<String>();
        outputRefs.add(packageRef);
        if (metadataPath != null && "acceptance".equals(profile(context))) {
            outputRefs.add(toWorkspaceRef(context.workspaceRoot(), metadataPath));
        }
        for (var inputRef : context.instance().inputRefs()) {
            if (TaskContractProposalReference.readVerified(
                    context.workspaceRoot(), context.workstreamId(), inputRef, OBJECT_MAPPER).isPresent()) {
                outputRefs.add(inputRef);
            }
        }
        return NodeResult.completed("completed", List.copyOf(outputRefs), result);
    }

    private static NodeResult executeGoverned(
            TaskContext context,
            Path workstreamDir,
            Path packagePath,
            String profileName,
            Optional<TaskContractProposalReference.ResolvedProposal> reviewSubject,
            Optional<AgentEvidenceIndex.Entry> architectureReviewSubject,
            Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract,
            String authoredBody,
            String revisionBody
    ) throws IOException {
        var rawBudget = ContextProfiles.budgetFor(profileName);
        var budget = effectiveBudget(rawBudget);
        var handoff = loadHandoff(workstreamDir);
        var manifest = budget.sections().stream().anyMatch(req -> requiresEvidenceManifest(req.section()))
                ? EvidenceManifest.rebuild(context.workspaceRoot(), workstreamDir, context.workstreamId(),
                        context.instance().inputRefs(), OBJECT_MAPPER, qualifiedContract)
                : null;
        var manifestPath = manifest == null ? null : manifest.write(workstreamDir, OBJECT_MAPPER);
        var governance = governanceEnabled()
                ? RepoScopeGovernance.build(
                        context.workspaceRoot(), workstreamDir, context, OBJECT_MAPPER, qualifiedContract)
                : null;

        // Phase 2: Resolve section availability
        var resolved = new ArrayList<ResolvedSection>();
        for (var req : budget.sections()) {
            var available = checkAvailability(req, context, workstreamDir, qualifiedContract);
            if (req.missingPolicy() == MissingPolicy.FAIL && !available) {
                return new NodeResult("failed", NodeStatus.FAILED, List.of(), Map.of("error", "required section '" + req.section() + "' data not found"), null);
            }
            resolved.add(new ResolvedSection(req, available));
        }

        // Phase 3: Plan budgets - priority order, softBudget allocation
        var sorted = new ArrayList<>(resolved);
        sorted.sort(java.util.Comparator.comparingInt((ResolvedSection rs) -> rs.req.priority().ordinal()));
        int allocated = 0;
        for (var rs : sorted) {
            if (!rs.available) continue;
            if (allocated + rs.req.softBudget() > budget.totalBudget()) {
                if (rs.req.overflowPolicy() == OverflowPolicy.PRESERVE_FULL) {
                    continue;
                }
                rs.degraded = true;
                if (rs.req.overflowPolicy() == OverflowPolicy.DROP_OPTIONAL) {
                    rs.dropped = true;
                } else if (rs.req.overflowPolicy() == OverflowPolicy.FAIL) {
                    return new NodeResult("failed", NodeStatus.FAILED, List.of(), Map.of("error", "budget exceeded at section '" + rs.req.section() + "'"), null);
                }
            } else {
                allocated += rs.req.softBudget();
            }
        }

        // Phase 4: Render sections with degradation
        var builder = new StringBuilder();
        appendGovernedHeader(builder, context, budget, sorted);
        ContextStateEvidenceBoundaryRenderer.append(
                builder, context, workstreamDir, OBJECT_MAPPER, qualifiedContract);
        RepoScopeGovernance.appendMarkdownGuidance(builder, governance, context.workspaceRoot(), compactGovernance(budget));

        for (var rs : sorted) {
            if (rs.dropped || !rs.available) {
                if (rs.req.missingPolicy() == MissingPolicy.PLACEHOLDER) {
                    builder.append("## ").append(sectionTitle(rs.req.section())).append("\n\n");
                    builder.append("(not available)\n\n");
                }
                continue;
            }
            var section = renderGovernedSectionOrFailure(
                    rs, context, workstreamDir, handoff, manifest, budget, qualifiedContract);
            if (section.failure() != null) {
                return section.failure();
            }
            builder.append(section.content());
        }

        // Phase 5: Validate total budget (token-based)
        builder.replace(0, builder.indexOf("## State & Evidence Boundary"),
                rebuildGovernedHeader(context, budget, sorted, Map.of()));
        if (tokenCount(builder.toString()) > budget.totalBudget()) {
            for (int i = sorted.size() - 1; i >= 0; i--) {
                if (tokenCount(builder.toString()) <= budget.totalBudget()) break;
                var rs = sorted.get(i);
                if (!rs.available || rs.dropped) continue;
                if (rs.req.overflowPolicy() == OverflowPolicy.FAIL
                        || rs.req.overflowPolicy() == OverflowPolicy.PRESERVE_FULL) {
                    continue;
                }
                rs.dropped = true;
                rs.renderedChars = 0;
                // Re-measure the actual package after each removal before considering higher priorities.
                builder.setLength(0);
                appendGovernedHeader(builder, context, budget, sorted);
                ContextStateEvidenceBoundaryRenderer.append(
                        builder, context, workstreamDir, OBJECT_MAPPER, qualifiedContract);
                RepoScopeGovernance.appendMarkdownGuidance(builder, governance, context.workspaceRoot(), compactGovernance(budget));
                for (var remaining : sorted) {
                    if (remaining.dropped || !remaining.available) {
                        if (remaining.req.missingPolicy() == MissingPolicy.PLACEHOLDER) {
                            builder.append("## ").append(sectionTitle(remaining.req.section())).append("\n\n");
                            builder.append("(not available)\n\n");
                        }
                        continue;
                    }
                    var section = renderGovernedSectionOrFailure(
                            remaining, context, workstreamDir, handoff, manifest, budget, qualifiedContract);
                    if (section.failure() != null) {
                        return section.failure();
                    }
                    builder.append(section.content());
                }
                builder.replace(0, builder.indexOf("## State & Evidence Boundary"),
                        rebuildGovernedHeader(context, budget, sorted, Map.of()));
            }
            var governedTokens = tokenCount(builder.toString());
            var preservedTokens = sorted.stream()
                    .filter(rs -> rs.req.overflowPolicy() == OverflowPolicy.PRESERVE_FULL)
                    .mapToInt(rs -> rs.renderedChars)
                    .sum();
            if (governedTokens > budget.totalBudget()
                    && governedTokens - preservedTokens > budget.totalBudget()) {
                return new NodeResult("failed", NodeStatus.FAILED, List.of(),
                        Map.of("error", "budget exceeded: " + governedTokens + " > "
                                + budget.totalBudget() + " tokens"), null);
            }
        }

        var requiredTypedSubjectTokens = new LinkedHashMap<String, Integer>();
        if (reviewSubject.isPresent()) {
            var start = builder.length();
            ContextPackageSectionRenderer.appendRequiredReviewSubject(builder, reviewSubject.get());
            requiredTypedSubjectTokens.put("required_review_subject", tokenCount(builder.substring(start)));
        }
        if (architectureReviewSubject.isPresent()) {
            var start = builder.length();
            ContextPackageSectionRenderer.appendRequiredArchitectureReviewSubject(
                    builder, architectureReviewSubject.get());
            requiredTypedSubjectTokens.put(
                    "required_architecture_review_subject", tokenCount(builder.substring(start)));
        }
        if (!revisionBody.isEmpty()) {
            builder.append(revisionBody);
            requiredTypedSubjectTokens.put("contract_revision", tokenCount(revisionBody));
        }
        // Required typed evidence is never dropped; report its cost instead of hiding it behind the soft budget.
        builder.replace(0, builder.indexOf("## State & Evidence Boundary"),
                rebuildGovernedHeader(context, budget, sorted, requiredTypedSubjectTokens));
        if (!authoredBody.isEmpty()) builder.append("\n\n").append(authoredBody);
        var markdown = builder.toString();
        Files.writeString(packagePath, markdown, StandardCharsets.UTF_8);
        var declaredSections = budget.sections().stream()
                .map(SectionRequirement::section)
                .toList();
        var metadataPath = writeContextPackageMetadata(
                context,
                packagePath,
                profileName,
                budget,
                tokenCount(markdown),
                sorted,
                manifest,
                manifestPath,
                memoryEnabled(),
                disabledMemorySections(rawBudget.sections().stream().map(SectionRequirement::section).toList(),
                        budget.sections().stream().map(SectionRequirement::section).toList()),
                governance,
                requiredTypedSubjectTokens,
                qualifiedContract
        );
        return buildLegacyResult(context, packagePath, metadataPath, declaredSections);
    }

    /**
     * Writes the structured context governance sidecar.
     *
     * The markdown package remains the agent-facing artifact. The sidecar is
     * the machine-facing evidence boundary used by trace, metrics, and later
     * budget audits; callers should not parse the markdown table for lifecycle
     * decisions.
     */
    private static Path writeContextPackageMetadata(
            TaskContext context,
            Path packagePath,
            String profileName,
            ContextBudget budget,
            int estimatedTokens,
            List<ResolvedSection> sections
    ) throws IOException {
        return writeContextPackageMetadata(context, packagePath, profileName, budget, estimatedTokens, sections, null, null);
    }

    private static Path writeContextPackageMetadata(
            TaskContext context,
            Path packagePath,
            String profileName,
            ContextBudget budget,
            int estimatedTokens,
            List<ResolvedSection> sections,
            EvidenceManifest manifest,
            Path manifestPath
    ) throws IOException {
        return writeContextPackageMetadata(context, packagePath, profileName, budget, estimatedTokens, sections,
                manifest, manifestPath, memoryEnabled(), List.of());
    }

    private static Path writeContextPackageMetadata(
            TaskContext context,
            Path packagePath,
            String profileName,
            ContextBudget budget,
            int estimatedTokens,
            List<ResolvedSection> sections,
            EvidenceManifest manifest,
            Path manifestPath,
            boolean memoryEnabled,
