    private static Optional<TaskContractProposalReference.ResolvedProposal> resolveRequiredReviewSubject(
            TaskContext context
    ) {
        if (!requiresTaskContractProposal(context)) {
            return Optional.empty();
        }
        return TaskContractProposalReference.resolveProposalFromRefs(
                context.workspaceRoot(),
                context.workstreamId(),
                context.instance().inputRefs(),
                OBJECT_MAPPER);
    }

    private static boolean requiresTaskContractProposal(TaskContext context) {
        return "task_contract_proposal".equals(configText(context, "required_input_artifact", ""));
    }

    private static Optional<AgentEvidenceIndex.Entry> resolveRequiredArchitectureReviewSubject(
            TaskContext context
    ) {
        if (!requiresArchitectureReviewSubject(context)) {
            return Optional.empty();
        }
        var candidates = AgentEvidenceIndex.fromRefs(
                        context.workspaceRoot(), context.workstreamId(), context.instance().inputRefs(), OBJECT_MAPPER)
                .recent(Math.max(1, context.instance().inputRefs().size()))
                .stream()
                .filter(entry -> "design.claude_design".equals(entry.document().nodeId()))
                .toList();
        if (candidates.size() != 1
                || !"design_result".equals(candidates.getFirst().document().sourceArtifactType())
                || !candidates.getFirst().document().hasRequiredTypedPayload()) {
            return Optional.empty();
        }
        return Optional.of(candidates.getFirst());
    }

    private static boolean requiresArchitectureReviewSubject(TaskContext context) {
        return "architecture_review".equals(profile(context))
                && "design.codex_arch_review".equals(configText(context, "target_node", ""));
    }

    static Map<String, Object> contractRevisionProjection(
            Path root, String workstreamId, String iterationId, TaskContractProposalReference candidate
    ) throws IOException {
        var resolved = new TaskContractRevisionContextResolver().resolveForProposal(root, workstreamId, candidate);
        if (!resolved.valid()) throw new IOException("CONTRACT_REVISION_CONTEXT_INVALID: " + resolved.errors());
        var revision = resolved.context();
        if (!iterationId.equals(revision.iteration().iterationId())) {
            throw new IOException("CONTRACT_REVISION_CONTEXT_INVALID: candidate belongs to another iteration");
        }
        if (revision.lateRoot() == null) return Map.of();
        var proposal = candidate.resolveVerifiedProposal(root, workstreamId, OBJECT_MAPPER)
                .orElseThrow(() -> new IOException("CONTRACT_REVISION_CONTEXT_INVALID: candidate is unverified"));
        var projection = new LinkedHashMap<String, Object>();
        projection.put("candidate", candidate.toMap());
        projection.put("direct_parent", revision.previousReference().toMap());
        projection.put("late_root", revision.lateRoot());
        projection.put("obligations", revision.obligations());
        projection.put("revision_responses", proposal.revisionResponses());
        return projection;
    }

    static String renderContractRevision(Map<String, Object> projection) throws IOException {
        if (projection.isEmpty()) return "";
        return "\n\n## Contract Revision Obligations And Candidate Responses\n\n"
                + "Cumulative obligations at candidate generation remain visible with their sources. "
                + "Candidate responses are claims, not verified closure or approval. "
                + "The current review is shown separately; newly raised findings enter the next revision.\n\n"
                + "```json\n" + OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(projection)
                + "\n```\n\n";
    }

    private static Map<String, Integer> requiredTypedSubjectTokens(
            Optional<TaskContractProposalReference.ResolvedProposal> reviewSubject,
            Optional<AgentEvidenceIndex.Entry> architectureReviewSubject
    ) throws IOException {
        var tokens = new LinkedHashMap<String, Integer>();
        if (reviewSubject.isPresent()) {
            var rendered = new StringBuilder();
            ContextPackageSectionRenderer.appendRequiredReviewSubject(rendered, reviewSubject.get());
            tokens.put("required_review_subject", tokenCount(rendered.toString()));
        }
        if (architectureReviewSubject.isPresent()) {
            var rendered = new StringBuilder();
            ContextPackageSectionRenderer.appendRequiredArchitectureReviewSubject(
                    rendered, architectureReviewSubject.get());
            tokens.put("required_architecture_review_subject", tokenCount(rendered.toString()));
        }
        return Map.copyOf(tokens);
    }

    private static Optional<RequiredAgentEvidence> missingRequiredAgentEvidence(TaskContext context) {
        var configured = context.definition().config().get("required_agent_evidence");
        if (configured == null) {
            return Optional.empty();
        }
        var required = RequiredAgentEvidence.from(configured);
        var evidence = AgentEvidenceIndex.fromRefs(
                context.workspaceRoot(), context.workstreamId(), context.instance().inputRefs(), OBJECT_MAPPER);
        return evidence.contains(required.nodeId(), required.sourceArtifactType(), required.decision())
                ? Optional.empty()
                : Optional.of(required);
    }

    private record RequiredAgentEvidence(String nodeId, String sourceArtifactType, String decision) {
        static RequiredAgentEvidence from(Object configured) {
            if (!(configured instanceof Map<?, ?> values)) {
                throw new IllegalArgumentException("required_agent_evidence must be an object");
            }
            var requirement = new RequiredAgentEvidence(
                    requiredText(values, "node_id"),
                    requiredText(values, "source_artifact_type"),
                    requiredText(values, "decision"));
            return requirement;
        }

        String description() {
            return nodeId + "/" + sourceArtifactType + "/" + decision;
        }

        Map<String, Object> toMap() {
            return Map.of(
                    "node_id", nodeId,
                    "source_artifact_type", sourceArtifactType,
                    "decision", decision);
        }

        private static String requiredText(Map<?, ?> values, String key) {
            var value = values.get(key);
            if (!(value instanceof String text) || text.isBlank()) {
                throw new IllegalArgumentException("required_agent_evidence." + key + " is required");
            }
            return text;
        }
    }

    private static String snippetToTokens(String content, int maxTokens, Path path) {
        var tokens = tokenCount(content);
        if (tokens <= maxTokens) return content.stripTrailing();
        // Estimate char position from token budget (4 chars/token ratio)
        var estimatedChars = Math.min(content.length(), maxTokens * 4);
        var truncated = content.substring(0, estimatedChars).stripTrailing();
        return truncated + "\n\n[adaptively compressed to ~" + maxTokens + " tokens; full data at " + toDisplayRef(path) + "]";
    }

    private static String capSectionToBudget(String section, String content, int maxTokens, Path workstreamDir) {
        var heading = "## " + sectionTitle(section) + "\n\n";
        var marker = "\n\n[adaptively compressed; section degraded to stay within ~" + maxTokens
                + " tokens; full source remains in ledger under " + toDisplayRef(workstreamDir) + "]\n\n";
        var bodyBudget = Math.max(100, maxTokens - tokenCount(heading) - tokenCount(marker));
        var maxChars = Math.min(content.length(), bodyBudget * 4);
        var body = content.substring(0, maxChars).stripTrailing();
        if (body.startsWith(heading)) {
            return body + marker;
        }
        return heading + body + marker;
    }

    private record RenderedSection(String content, NodeResult failure) {
        static RenderedSection content(String content) {
            return new RenderedSection(content, null);
        }

        static RenderedSection failure(NodeResult failure) {
            return new RenderedSection("", failure);
        }
    }

    private static String readOrDefault(Path path, String fallback) throws IOException {
        if (!Files.exists(path)) {
            return fallback;
        }
        return Files.readString(path, StandardCharsets.UTF_8).stripTrailing();
    }

    private static String configText(TaskContext context, String key, String fallback) {
        var value = context.definition().config().get(key);
        if (value instanceof String text && !text.isBlank()) {
            return text;
        }
        return fallback;
    }

    private static String profile(TaskContext context) {
        return configText(context, "profile", "full");
    }

    private static List<String> sections(TaskContext context) {
        var override = context.definition().config().get("include_sections");
        if (override instanceof List<?> values && !values.isEmpty()) {
            return values.stream()
                    .filter(String.class::isInstance)
                    .map(String.class::cast)
                    .filter(section -> FULL_SECTIONS.contains(section))
                    .distinct()
                    .toList();
        }
        return switch (profile(context)) {
            case "product_review" -> List.of(
                    "requirement",
                    "input_artifacts",
                    "recent_agent_outputs",
                    "ledger_pointers"
            );
            case "architecture_review" -> List.of(
                    "requirement",
                    "input_artifacts",
                    "iteration_history",
                    "human_feedback",
                    "recent_agent_outputs",
                    "ledger_pointers"
            );
            case "plan_review" -> List.of(
                    "requirement",
                    "input_artifacts",
                    "iteration_history",
                    "human_feedback",
                    "recent_agent_outputs",
                    "ledger_pointers"
            );
            case "implementation" -> List.of(
                    "requirement",
                    "input_artifacts",
                    "iteration_history",
                    "human_feedback",
                    "recent_agent_outputs",
                    "ledger_pointers"
            );
            case "acceptance" -> List.of(
                    "requirement",
                    "input_artifacts",
                    "iteration_history",
                    "human_feedback",
                    "recent_agent_outputs",
                    "git_evidence",
                    "task_contract",
                    "ledger_pointers"
            );
            default -> FULL_SECTIONS;
        };
    }

    private static List<String> effectiveSections(TaskContext context) {
        return filterMemorySections(sections(context));
    }

    private static ContextBudget effectiveBudget(ContextBudget budget) {
        var filtered = budget.sections().stream()
                .filter(req -> memoryEnabled() || !MEMORY_SECTIONS.contains(req.section()))
                .toList();
        if (filtered.size() == budget.sections().size()) {
            return budget;
        }
        return new ContextBudget(budget.totalBudget(), filtered, budget.configOverrides());
    }

    private static List<String> filterMemorySections(List<String> sections) {
        if (memoryEnabled()) {
            return sections;
        }
        return sections.stream()
                .filter(section -> !MEMORY_SECTIONS.contains(section))
                .toList();
    }

    private static List<String> disabledMemorySections(List<String> rawSections, List<String> effectiveSections) {
        if (memoryEnabled()) {
            return List.of();
        }
        return rawSections.stream()
                .filter(MEMORY_SECTIONS::contains)
                .filter(section -> !effectiveSections.contains(section))
                .distinct()
                .toList();
    }

    private static boolean memoryEnabled() {
        var property = System.getProperty("dual.context.memory.enabled");
        if (property != null && !property.isBlank()) {
            return !isFalse(property);
        }
        var env = System.getenv("DUAL_CONTEXT_MEMORY_ENABLED");
        if (env != null && !env.isBlank()) {
            return !isFalse(env);
        }
        return true;
    }

    private static boolean governanceEnabled() {
        var property = System.getProperty("dual.context.governance.enabled");
        if (property != null && !property.isBlank()) {
            return !isFalse(property);
        }
        var env = System.getenv("DUAL_CONTEXT_GOVERNANCE_ENABLED");
        if (env != null && !env.isBlank()) {
            return !isFalse(env);
        }
        return true;
    }

    private static boolean isFalse(String value) {
        var normalized = value.trim().toLowerCase(java.util.Locale.ROOT);
        return normalized.equals("false") || normalized.equals("0") || normalized.equals("no") || normalized.equals("off");
    }

    private static int maxSnippetChars(TaskContext context) {
        return positiveIntConfig(context, "max_snippet_chars", MAX_SNIPPET_CHARS, Map.of());
    }

    private static int maxSnippetChars(TaskContext context, ContextBudget budget) {
        return positiveIntConfig(context, "max_snippet_chars", MAX_SNIPPET_CHARS, budget.configOverrides());
    }

    private static int maxRecentAgentOutputs(TaskContext context) {
        return positiveIntConfig(context, "max_recent_agent_outputs", MAX_RECENT_AGENT_OUTPUTS, Map.of());
    }

    private static boolean compactGovernance(ContextBudget budget) {
        return Boolean.TRUE.equals(budget.configOverrides().get("compact_governance"));
    }

    private static int positiveIntConfig(TaskContext context, String key, int fallback, Map<String, Object> overrides) {
        var override = overrides.get(key);
        if (override instanceof Number number && number.intValue() > 0) {
            return number.intValue();
        }
        if (override instanceof String text && text.matches("\\d+")) {
            return Integer.parseInt(text);
        }
        var value = context.definition().config().get(key);
        if (value instanceof Number number && number.intValue() > 0) {
            return number.intValue();
        }
        if (value instanceof String text && text.matches("\\d+")) {
            return Integer.parseInt(text);
        }
        return fallback;
    }

    private static String toWorkspaceRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize().relativize(path.toAbsolutePath().normalize()).toString();
    }

    private static String toDisplayRef(Path path) {
        return path.toAbsolutePath().normalize().toString();
    }

    private static StageHandoffDocument loadHandoff(Path workstreamDir) {
        var path = workstreamDir.resolve("artifacts/next-stage/handoff.json");
        if (!Files.exists(path)) return emptyHandoff();
        return StageHandoffDocument.read(path, OBJECT_MAPPER).orElseGet(ContextBuildPackageHandler::emptyHandoff);
    }

    private static StageHandoffDocument emptyHandoff() {
        return new StageHandoffDocument(1, "", "", "", "", List.of(), List.of(), List.of(), List.of(), "", "", "", "");
    }
}

package dev.dual.runtime.handler;

import java.util.List;
import java.util.Map;
import java.util.Optional;
import dev.dual.core.arbitration.FailureCategory;

public final class AgentContractSemantics {
    private AgentContractSemantics() {
    }

    static Optional<ContractViolation> validateRereadReasons(Object rawValue) {
        if (!(rawValue instanceof List<?> list) || list.isEmpty()) {
            return Optional.empty();
        }
        for (int i = 0; i < list.size(); i++) {
            var item = list.get(i);
            if (!(item instanceof Map<?, ?> raw)) {
                return violation("REREAD_REASON_ENTRY_NOT_OBJECT",
                        "reread_reasons[" + i + "] must be an object", Map.of("index", i));
            }
            if (text(raw.get("path")).isBlank()) {
                return violation("REREAD_REASON_PATH_REQUIRED",
                        "reread_reasons[" + i + "] requires a non-blank 'path'", Map.of("index", i));
            }
            var reason = text(raw.get("reason"));
            if (!ReadReuseContractReasons.isAllowed(reason)) {
                return violation("REREAD_REASON_REASON_NOT_ALLOWED",
                        "reread_reasons[" + i + "] reason is not in the allowed catalog: " + reason,
                        Map.of("index", i, "reason", reason));
            }
            if (raw.containsKey("stage") && text(raw.get("stage")).isBlank()) {
                return violation("REREAD_REASON_STAGE_BLANK",
                        "reread_reasons[" + i + "] 'stage' is present but blank", Map.of("index", i));
            }
            if (raw.containsKey("evidence") && text(raw.get("evidence")).isBlank()) {
                return violation("REREAD_REASON_EVIDENCE_BLANK",
                        "reread_reasons[" + i + "] 'evidence' is present but blank", Map.of("index", i));
            }
        }
        return Optional.empty();
    }

    static Optional<ContractViolation> validateOutputContract(AgentOutputContractDocument document) {
        if ("self_test_report".equals(document.sourceArtifactType())
                && "SELF_TEST_COMPLETE".equals(document.decision())
                && (!document.mustFix().isEmpty() || !document.missingEvidence().isEmpty())) {
            return violation("SELF_TEST_COMPLETION_CONFLICT",
                    "SELF_TEST_COMPLETE cannot include must_fix or missing_evidence", Map.of());
        }
        if (isAcceptanceReview(document)) {
            var failure = document.failure();
            var classification = validateAcceptanceClassification(document.decision(), failure.categoryHint(),
                    failure.verificationRemediation(), failure.contractGaps(), failure.outOfScopeFiles(),
                    failure.missingTests(), failure.contextGaps(), failure.reason(),
                    document.mustFix(), document.missingEvidence());
            if (classification.isPresent()) return classification;
        }
        return StageOutcomeCompiler.validateEvidenceContract(
                "agent_output_contract",
                document.decision(),
                document.lifecycleStatus(),
                AgentEvidenceState.from(document),
                document.failure());
    }

    static List<String> acceptanceCategories() {
        return java.util.Arrays.stream(FailureCategory.values()).map(Enum::name).toList();
    }

    static boolean isAcceptanceReview(AgentOutputContractDocument document) {
        return "acceptance_review".equals(document.sourceArtifactType())
                || "acceptance.codex_verifier_review".equals(document.nodeId());
    }

    static Optional<ContractViolation> validateAcceptanceClassification(
            String decision, String categoryHint, AgentResultEnvelope.VerificationRemediation remediation,
            List<String> contractGaps, List<String> outOfScope, List<String> missingTests,
            List<String> contextGaps, String reason, List<String> mustFix, List<String> missingEvidence) {
        boolean reject = "REJECT".equals(decision);
        boolean tests = nonempty(missingTests);
        boolean activeRemediation = remediation != null
                && remediation != AgentResultEnvelope.VerificationRemediation.NONE;
        if (reject && tests && !activeRemediation)
            return classificationViolation("result.failure.verification_remediation is required when REJECT lists missing_tests");
        if (!(reject && tests) && activeRemediation)
            return classificationViolation("result.failure.verification_remediation is only allowed when REJECT lists missing_tests");
        if (!reject) {
            return categoryHint == null || categoryHint.isEmpty() ? Optional.empty()
                    : classificationViolation("accepted review must not declare a failure category");
        }
        final FailureCategory category;
        try { category = FailureCategory.valueOf(categoryHint == null ? "" : categoryHint); }
        catch (IllegalArgumentException failure) {
            return classificationViolation("REJECT requires exact failure.category_hint from " + acceptanceCategories());
        }
        boolean contract = category == FailureCategory.CONTRACT_GAP || category == FailureCategory.CONTRACT_AMBIGUITY;
        boolean testChange = remediation == AgentResultEnvelope.VerificationRemediation.TEST_CODE_CHANGE;
        if (contract != nonempty(contractGaps)) {
            return classificationViolation("contract categories require contract_gaps; other categories forbid them");
        }
        boolean valid = switch (category) {
            case CONTRACT_GAP, CONTRACT_AMBIGUITY -> true;
            case IMPLEMENTATION_BUG -> nonempty(mustFix) || nonempty(outOfScope) || testChange;
            case VERIFICATION_INSUFFICIENT -> (tests || nonempty(missingEvidence))
                    && !nonempty(outOfScope) && !nonempty(contextGaps) && !testChange;
            case CONTEXT_INSUFFICIENT -> nonempty(contextGaps) && !nonempty(outOfScope) && !testChange;
            case TOOL_LIMITATION -> reason != null && !reason.isBlank() && !nonempty(outOfScope) && !testChange;
            case REVIEW_NOISE -> reason != null && !reason.isBlank() && !nonempty(outOfScope)
                    && !tests && !nonempty(contextGaps) && !nonempty(missingEvidence)
                    && !nonempty(mustFix) && !activeRemediation;
        };
        return valid ? Optional.empty() : classificationViolation("failure evidence contradicts category " + category);
    }

    private static boolean nonempty(List<?> values) { return values != null && !values.isEmpty(); }

    private static Optional<ContractViolation> classificationViolation(String message) {
        return violation("ACCEPTANCE_CLASSIFICATION_INVALID", message, Map.of());
    }

    static void addSidecarFields(Map<String, Object> sidecar) {
        StageOutcomeCompiler.addSidecarFields(sidecar);
    }

    private static Optional<ContractViolation> violation(String code, String message, Map<String, Object> details) {
        return Optional.of(ContractViolation.of(code, message, details));
    }

    private static StringListValidation stringList(Object rawValue) {
        if (rawValue == null) {
            return new StringListValidation(List.of(), -1);
        }
        if (!(rawValue instanceof List<?> list)) {
            return new StringListValidation(List.of(), 0);
        }
        var values = new java.util.ArrayList<String>();
        for (int i = 0; i < list.size(); i++) {
            var value = list.get(i);
            if (!(value instanceof String item) || item.trim().isBlank()) {
                return new StringListValidation(List.of(), i);
            }
            values.add(item.trim());
        }
        return new StringListValidation(List.copyOf(values), -1);
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    private record StringListValidation(List<String> values, int invalidIndex) {
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.contract.TaskContract;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.Optional;

/**
 * Builds the per-agent-run governance context consumed by acpx prompts.
 *
 * Workflow context-package nodes still own rich cross-node packets. This class
 * only guarantees that every concrete agent execution receives its own typed
 * exploration plan and capability catalog projection, even when the workflow
 * graph does not include a dedicated context node before that agent.
 */
public final class AgentRunGovernanceContext {
    public static final String QUALIFICATION_FAILURE_OUTCOME =
            TaskContractProjectionVerifier.FAILURE_OUTCOME;
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper()
            .registerModule(new JavaTimeModule())
            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
            .enable(SerializationFeature.INDENT_OUTPUT);

    private AgentRunGovernanceContext() {
    }

    public static String ensure(TaskHandler.TaskContext context, String runId) throws IOException {
        return ensureQualified(context, runId).contextRef();
    }

    public static PreparedContext ensureQualified(TaskHandler.TaskContext context, String runId) throws IOException {
        var workspaceRoot = context.workspaceRoot();
        var workstreamDir = workspaceRoot.resolve(".agent")
                .resolve("workstreams")
                .resolve(context.workstreamId());
        var expectedArtifact = String.valueOf(
                context.definition().config().getOrDefault("expected_artifact", "")).trim();
        var requiresQualification = requiresApprovedTaskContract(context);
        var contractResolution = requiresQualification || "acceptance_review".equals(expectedArtifact)
                ? ("acceptance_review".equals(expectedArtifact)
                        ? TaskContractProjectionVerifier.resolveRoutedAcceptance(
                                workspaceRoot,
                                context.workstreamId(),
                                context.definition().id(),
                                context.instance().inputRefs())
                        : TaskContractProjectionVerifier.resolve(workspaceRoot, context.workstreamId()))
                : TaskContractProjectionVerifier.Resolution.absent();
        if (contractResolution.failure() != null) {
            throw qualificationFailure(contractResolution.failure());
        }
        if (requiresQualification && contractResolution.qualified().isEmpty()) {
            throw new QualificationException(TaskContractProjectionVerifier.FAILURE_OUTCOME
                    + ": APPROVAL_BINDING_MISSING: node requires an approved task contract");
        }
        if ("acceptance_review".equals(expectedArtifact) && contractResolution.qualified().isEmpty()) {
            throw new QualificationException(TaskContractProjectionVerifier.FAILURE_OUTCOME
                    + ": CONTEXT_BINDING_MISSING: acceptance agent has no routed task contract binding");
        }
        Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract =
                contractResolution.qualified();
        final Optional<AuthoredExecutionContext.Snapshot> authoredContext;
        try {
            authoredContext = AuthoredExecutionContext.prepare(context, runId);
        } catch (IOException failure) {
            throw new AuthoredContextException(failure.getMessage(), failure);
        }

        var contextDir = workstreamDir.resolve("context");
        Files.createDirectories(contextDir);

        var manifest = EvidenceManifest.rebuild(workspaceRoot, workstreamDir, context.workstreamId(),
                context.instance().inputRefs(), OBJECT_MAPPER, qualifiedContract);
        manifest.write(workstreamDir, OBJECT_MAPPER);
        var governance = RepoScopeGovernance.build(
                workspaceRoot, workstreamDir, context, OBJECT_MAPPER, qualifiedContract, runId);

        var packagePath = contextDir.resolve("agent-governance-"
                + safeFileName(context.instance().nodeInstanceId())
                + "-"
                + safeFileName(runId)
                + ".md");
        var builder = new StringBuilder();
        builder.append("# Agent Run Governance Context\n\n");
        builder.append("- Workstream: ").append(context.workstreamId()).append("\n");
        builder.append("- Target Node: ").append(context.definition().id()).append("\n");
        builder.append("- Agent Node Instance: ").append(context.instance().nodeInstanceId()).append("\n");
        builder.append("- Run Id: ").append(runId == null ? "" : runId).append("\n");
        builder.append("- Generated At: ").append(Instant.now()).append("\n\n");
        RepoScopeGovernance.appendMarkdownGuidance(builder, governance, workspaceRoot, true);
        Files.writeString(packagePath, builder.toString(), StandardCharsets.UTF_8);
        return new PreparedContext(
                workspaceRoot.relativize(packagePath).toString(),
                qualifiedContract.map(TaskContractProjectionVerifier.QualifiedTaskContract::wrappedPayload),
                governance.repositoryFactBinding(),
                qualifiedContract.map(TaskContractProjectionVerifier.QualifiedTaskContract::contract),
                qualifiedContract.map(TaskContractProjectionVerifier.QualifiedTaskContract::contractRef).orElse(""),
                qualifiedContract.map(TaskContractProjectionVerifier.QualifiedTaskContract::sha256).orElse(""),
                authoredContext);
    }

    public static Optional<String> trustedTaskContractPayload(
            Path workspaceRoot,
            String workstreamId,
            String nodeId,
            java.util.List<String> inputRefs
    ) {
        return TaskContractProjectionVerifier.trustedWrappedPayload(
                workspaceRoot, workstreamId, nodeId, inputRefs);
    }

    private static QualificationException qualificationFailure(TaskContractProjectionVerifier.Failure failure) {
        return new QualificationException(TaskContractProjectionVerifier.FAILURE_OUTCOME
                + ": " + failure.reason() + ": " + failure.message());
    }

    public static boolean requiresApprovedTaskContract(TaskHandler.TaskContext context) {
        var configured = context.definition().config().get("requires_approved_task_contract");
        if (configured == null) {
            return false;
        }
        if (!(configured instanceof Boolean required)) {
            throw new IllegalArgumentException("requires_approved_task_contract must be a boolean");
        }
        return required;
    }

    public static final class QualificationException extends IOException {
        QualificationException(String message) {
            super(message);
        }
    }

    public record PreparedContext(
            String contextRef,
            Optional<String> trustedTaskContractPayload,
            RepositoryFactBinding.Verified repositoryFactBinding,
            Optional<TaskContract> qualifiedTaskContract,
            String taskContractRef,
            String taskContractSha256,
            Optional<AuthoredExecutionContext.Snapshot> authoredContext
    ) {
    }

    public static final class AuthoredContextException extends IOException {
        AuthoredContextException(String message, Throwable cause) { super(message, cause); }
    }

    private static String safeFileName(String value) {
        var text = value == null || value.isBlank() ? "unknown" : value.trim();
        return text.replaceAll("[^A-Za-z0-9._-]", "_");
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.annotation.JsonSubTypes;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import dev.dual.core.contract.TaskContract;
import java.util.List;

/** Strict, lineage-bound workflow result emitted as the final ACP assistant message. */
public record AgentResultEnvelope(
        int schemaVersion,
        String workstreamId,
        String runId,
        String nodeId,
        AgentResult result
) {
    @JsonTypeInfo(
            use = JsonTypeInfo.Id.NAME,
            include = JsonTypeInfo.As.EXISTING_PROPERTY,
            property = "artifact_type",
            visible = true
    )
    @JsonSubTypes({
            @JsonSubTypes.Type(value = TaskContractProposalResult.class, name = "task_contract_proposal"),
            @JsonSubTypes.Type(value = TaskContractRevisionPatchResult.class, name = "task_contract_revision_patch"),
            @JsonSubTypes.Type(value = AgentOutputResult.class, name = "agent_output_contract"),
            @JsonSubTypes.Type(value = DesignResult.class, name = "design_result"),
            @JsonSubTypes.Type(value = PlanResult.class, name = "plan_result"),
            @JsonSubTypes.Type(value = SelfTestResult.class, name = "self_test_report"),
            @JsonSubTypes.Type(value = AcceptanceReviewResult.class, name = "acceptance_review"),
            @JsonSubTypes.Type(value = StageHandoffResult.class, name = "stage_handoff")
    })
    public sealed interface AgentResult permits
            TaskContractProposalResult,
            TaskContractRevisionPatchResult,
            AgentOutputResult,
            DesignResult,
            PlanResult,
            SelfTestResult,
            AcceptanceReviewResult,
            StageHandoffResult {
        String artifactType();

        String decision();

        String summary();
    }

    public record DesignResult(
            String artifactType,
            String decision,
            String summary,
            String lifecycleStatus,
            List<String> checks,
            List<String> evidence,
            List<String> missingEvidence,
            List<String> mustFix,
            List<String> openRisks,
            String verificationSummary,
            Design design,
            List<AuthoredRevisionResponse> revisionResponses
    ) implements AgentResult {
    }

    public record Design(List<PlannedFile> plannedFiles) {
    }

    public record PlannedFile(String path, TaskContract.ScopeOperation operation, String responsibility) {
    }

    public record AuthoredRevisionResponse(String obligationId, AuthoredRevisionDisposition disposition, String evidence) {
    }

    public enum AuthoredRevisionDisposition {
        ADDRESSED, NOT_ADDRESSED
    }

    public record TaskContractProposalResult(
            String artifactType,
            String decision,
            String summary,
            boolean needsHumanInput,
            String objective,
            ProposalScope scope,
            List<ContractClause> acceptanceCriteria,
            List<ContractClause> testRequirements,
            List<ContractClause> constraints,
