package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.workflow.NodeDefinition;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Writes harness-owned diagnostics for agent output contract failures.
 *
 * Agent output remains in the run output directories. These diagnostics live under
 * artifacts because they are deterministic harness judgments about the output.
 */
final class ContractFailureDiagnosticWriter {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();

    private ContractFailureDiagnosticWriter() {
    }

    static DiagnosticRefs write(
            Path workspaceRoot,
            String workstreamId,
            String nodeInstanceId,
            NodeDefinition nodeDefinition,
            NodeOutputContract contract,
            String sourceOutputRef,
            String reason,
            String message,
            Map<String, Object> details
    ) throws Exception {
        if (workstreamId == null || workstreamId.isBlank() || nodeInstanceId == null || nodeInstanceId.isBlank()) {
            return DiagnosticRefs.empty();
        }
        var root = workspaceRoot.toAbsolutePath().normalize();
        var dir = root.resolve(".agent")
                .resolve("workstreams")
                .resolve(workstreamId)
                .resolve("artifacts")
                .resolve("contract-failures");
        Files.createDirectories(dir);

        var baseName = safeFileName(nodeInstanceId);
        var jsonPath = dir.resolve(baseName + ".json");
        var markdownPath = dir.resolve(baseName + ".md");
        var category = category(reason);
        var recovery = recoveryHint(category, nodeDefinition.id());

        var document = new LinkedHashMap<String, Object>();
        document.put("schema_version", 1);
        document.put("artifact_type", "contract_failure_diagnostic");
        document.put("generated_at", Instant.now().toString());
        document.put("workstream_id", workstreamId);
        document.put("node_instance_id", nodeInstanceId);
        document.put("node_id", nodeDefinition.id());
        document.put("handler_type", nodeDefinition.handlerType());
        document.put("category", category);
        document.put("reason", reason);
        document.put("message", message);
        document.put("source_output_ref", sourceOutputRef == null ? "" : sourceOutputRef);
        document.put("required_keys", List.copyOf(contract.requiredKeys()));
        document.put("allowed_decisions", List.copyOf(contract.allowedDecisions()));
        document.put("details", details == null ? Map.of() : details);
        document.put("recovery_hint", recovery);
        document.put("recommended_owner", recommendedOwner(category));

        Files.writeString(
                jsonPath,
                OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(document) + "\n",
                StandardCharsets.UTF_8
        );
        Files.writeString(markdownPath, markdown(document), StandardCharsets.UTF_8);

        return new DiagnosticRefs(root.relativize(jsonPath).toString(), root.relativize(markdownPath).toString());
    }

    private static String markdown(Map<String, Object> document) {
        var builder = new StringBuilder();
        builder.append("# Contract Failure Diagnostic\n\n");
        appendField(builder, "Category", document.get("category"));
        appendField(builder, "Reason", document.get("reason"));
        appendField(builder, "Node", document.get("node_id"));
        appendField(builder, "Node Instance", document.get("node_instance_id"));
        appendField(builder, "Source Output", document.get("source_output_ref"));
        appendField(builder, "Recommended Owner", document.get("recommended_owner"));
        builder.append("\n## Message\n\n");
        builder.append(text(document.get("message"))).append("\n\n");
        builder.append("## Recovery Hint\n\n");
        builder.append(text(document.get("recovery_hint"))).append("\n\n");
        builder.append("## Contract Shape\n\n");
        builder.append("- Required Keys: ").append(document.get("required_keys")).append("\n");
        builder.append("- Allowed Decisions: ").append(document.get("allowed_decisions")).append("\n");
        return builder.toString();
    }

    private static void appendField(StringBuilder builder, String label, Object value) {
        var text = text(value);
        if (!text.isBlank()) {
            builder.append("- ").append(label).append(": ").append(text).append("\n");
        }
    }

    private static String category(String reason) {
        return switch (reason == null ? "" : reason) {
            case "AGENT_RESULT_MISSING" -> "missing_agent_result";
            case "AGENT_RESULT_PARSE_FAILED", "AGENT_RESULT_CONTRACT_VIOLATION" -> "malformed_agent_result";
            case "STRUCTURED_ARTIFACT_SEMANTIC_VIOLATION" -> "semantic_conflict";
            default -> "contract_violation";
        };
    }

    private static String recommendedOwner(String category) {
        return switch (category) {
            case "missing_agent_result", "malformed_agent_result", "semantic_conflict" -> "agent_or_prompt";
            default -> "harness_or_prompt";
        };
    }

    private static String recoveryHint(String category, String nodeId) {
        return switch (category) {
            case "missing_agent_result" -> "Ask the agent step to emit one strict AgentResultEnvelope JSON object as its final assistant message for " + nodeId + ".";
            case "malformed_agent_result" -> "Repair the final AgentResultEnvelope JSON so it matches the node contract and contains no Markdown or trailing prose.";
            case "semantic_conflict" -> "Resolve the contradiction between lifecycle status, decision, and evidence fields.";
            default -> "Inspect the diagnostic details, prompt contract, and source output before retrying the node.";
        };
    }

    private static String safeFileName(String value) {
        return value.replaceAll("[^A-Za-z0-9._-]", "_");
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    record DiagnosticRefs(String jsonRef, String markdownRef) {
        static DiagnosticRefs empty() {
            return new DiagnosticRefs("", "");
        }

        boolean present() {
            return !jsonRef.isBlank();
        }
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;

import dev.dual.core.contract.TaskContract;
import dev.dual.core.contract.TaskContractValidator;

final class TaskContractProposalValidator {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    List<String> validate(TaskContractProposal proposal, Path workspaceRoot) {
        return validate(proposal, workspaceRoot, null, null);
    }

    List<String> validate(TaskContractProposal proposal, Path workspaceRoot,
                          TaskContractProposal approvedScopeBaseline, String originalBaseCommit) {
        return validate(proposal, workspaceRoot, approvedScopeBaseline, originalBaseCommit, List.of());
    }

    List<String> validate(TaskContractProposal proposal, Path workspaceRoot,
                          TaskContractProposal approvedScopeBaseline, String originalBaseCommit,
                          List<TaskContract.ScopeEntry> scopeReviewCandidates) {
        var errors = new ArrayList<String>();
        if (!scopeReviewCandidates.isEmpty()) {
            if (approvedScopeBaseline == null) return List.of("scope review requires its approved baseline");
            if (!Objects.equals(proposal.objective(), approvedScopeBaseline.objective())
                    || !Objects.equals(proposal.acceptanceCriteria(), approvedScopeBaseline.acceptanceCriteria())
                    || !Objects.equals(proposal.testRequirements(), approvedScopeBaseline.testRequirements())
                    || !Objects.equals(proposal.constraints(), approvedScopeBaseline.constraints())
                    || !Objects.equals(proposal.nonGoals(), approvedScopeBaseline.nonGoals())
                    || !Objects.equals(proposal.riskAreas(), approvedScopeBaseline.riskAreas())
                    || !Objects.equals(proposal.openQuestions(), approvedScopeBaseline.openQuestions())
                    || !Objects.equals(proposal.evidenceRefs(), approvedScopeBaseline.evidenceRefs())
                    || proposal.scope() == null
                    || !Objects.equals(proposal.scope().excluded(), approvedScopeBaseline.scope().excluded())
                    || proposal.scope().included() == null
                    || !proposal.scope().included().containsAll(approvedScopeBaseline.scope().included())) {
                errors.add("scope review must preserve the approved contract outside candidate additions");
            } else {
                for (var entry : proposal.scope().included()) {
                    if (entry == null || (!approvedScopeBaseline.scope().included().contains(entry) && !scopeReviewCandidates.contains(entry)))
                        errors.add("scope review addition is not in the bound evaluation: " + entry);
                }
            }
        }
        java.util.Set<String> originalPaths = java.util.Set.of();
        if (approvedScopeBaseline != null) {
            try {
                originalPaths = TaskContractScopeResolver.originalPaths(workspaceRoot, originalBaseCommit);
            } catch (IOException failure) {
                return List.of("approved scope workspace base is invalid: " + failure.getMessage());
            }
        }
        if (!"task_contract_proposal".equals(proposal.artifactType())) {
            errors.add("artifact_type must be task_contract_proposal");
        }
        if (proposal.schemaVersion() != TaskContractProposal.SCHEMA_VERSION) {
            errors.add("schema_version must be " + TaskContractProposal.SCHEMA_VERSION);
        }
        if (isBlank(proposal.objective())) {
            errors.add("objective must not be blank");
        }
        if (proposal.scope() == null) {
            errors.add("scope must not be null");
        } else {
            validateScopeEntries(proposal.scope().included(), errors);
            validateList("scope.excluded", proposal.scope().excluded(), false, errors);
            if (proposal.scope().included() != null) {
                for (var ref : proposal.scope().included()) {
                    var inheritedCreate = ref != null && ref.operation() == TaskContract.ScopeOperation.CREATE
                            && approvedScopeBaseline != null
                            && (approvedScopeBaseline.scope().included().contains(ref)
                                || scopeReviewCandidates.contains(ref));
                    validateWorkspacePathRef(ref, workspaceRoot, inheritedCreate, errors);
                    if (approvedScopeBaseline != null && ref != null
                            && ref.operation() == TaskContract.ScopeOperation.MODIFY
                            && !originalPaths.contains(ref.path())) {
                        errors.add("scope.included MODIFY path is absent from original workspace base: " + ref.path());
                    }
                }
            }
            validateScopeOverlap(proposal.scope(), errors);
        }
        var clauseIds = new HashSet<String>();
        validateClauses("acceptance_criteria", proposal.acceptanceCriteria(), true, clauseIds, errors);
        if (proposal.acceptanceCriteria() != null && nonBlankClauseCount(proposal.acceptanceCriteria()) < 2) {
            errors.add("acceptance_criteria requires at least two observable items");
        }
        validateClauses("constraints", proposal.constraints(), false, clauseIds, errors);
        validateClauses("non_goals", proposal.nonGoals(), false, clauseIds, errors);
        if (nonBlankClauseCount(proposal.constraints()) == 0 && nonBlankClauseCount(proposal.nonGoals()) == 0) {
            errors.add("constraints or non_goals must define task boundaries");
        }
        validateClauses("risk_areas", proposal.riskAreas(), false, clauseIds, errors);
        validateClauses("test_requirements", proposal.testRequirements(), true, clauseIds, errors);
        validateList("evidence_refs", proposal.evidenceRefs(), false, errors);
        validateList("open_questions", proposal.openQuestions(), false, errors);
        validateRevisionResponses(proposal.revisionResponses(), clauseIds, errors);
        return errors;
    }

    List<String> validateInitialIteration(TaskContractProposal proposal) {
        if (proposal.revisionResponses() == null || proposal.revisionResponses().isEmpty()) {
            return List.of();
        }
        return List.of("revision_responses must be empty for the initial workflow iteration");
    }

    List<String> validateEvidenceTraceability(
            TaskContractProposal proposal,
            Path workspaceRoot,
            RepositoryFactBinding.Verified repositoryFactBinding
    ) {
        var errors = new ArrayList<String>();
        if (repositoryFactBinding == null) {
            return List.of("tracked inventory occurrence binding is required before task contract proposal validation");
        }
        var repoMapArtifact = repositoryFactBinding.document().artifacts().get("repoMap");
        if (repoMapArtifact == null) {
            return List.of("tracked inventory occurrence binding has no repoMap artifact");
        }
        var repoMapPath = workspaceRoot.toAbsolutePath().normalize().resolve(repoMapArtifact.ref()).normalize();
        if (!Files.isRegularFile(repoMapPath)) {
            return List.of("tracked inventory is required before task contract proposal validation");
        }
        final Map<String, Object> repoMap;
        try {
            repoMap = OBJECT_MAPPER.readValue(repoMapPath.toFile(), MAP_TYPE);
        } catch (IOException failure) {
            return List.of("tracked inventory cannot be read: " + failure.getMessage());
        }
        if ("git_tracked_inventory".equals(String.valueOf(repoMap.get("source")))) {
            try {
                var current = GitTrackedPathInventory.capture(workspaceRoot);
                var expectedHead = repositoryFactBinding.document().inventoryHead();
                var expectedSha = repositoryFactBinding.document().inventorySha256();
                var expectedCount = repositoryFactBinding.document().inventoryPathCount();
                if (!current.head().equals(expectedHead)
                        || !current.sha256().equals(expectedSha)
                        || current.paths().size() != expectedCount) {
                    errors.add("tracked inventory identity changed after context projection");
                }
            } catch (IOException failure) {
                errors.add("tracked inventory identity cannot be revalidated: " + failure.getMessage());
            }
        }
        var inventoryPaths = new LinkedHashSet<String>();
        if (repoMap.get("files") instanceof List<?> files) {
            for (var item : files) {
                if (item instanceof Map<?, ?> file) {
                    var value = file.get("path");
                    var path = value == null ? "" : String.valueOf(value).trim();
                    if (!path.isBlank()) {
                        inventoryPaths.add(path);
                    }
                }
            }
        }
        var evidenceRefs = proposal.evidenceRefs() == null ? List.<String>of() : proposal.evidenceRefs();
        var tracedRepositoryFact = false;
        for (var evidenceRef : evidenceRefs) {
            if (isBlank(evidenceRef)) {
                continue;
            }
            var ref = evidenceRef.trim();
            if (!TaskContractValidator.isCanonicalPath(ref)) {
                errors.add("evidence_refs contains a non-canonical path: " + ref);
            } else if (inventoryPaths.contains(ref) && !Files.isRegularFile(workspaceRoot.resolve(ref).normalize())) {
                errors.add("evidence_refs does not resolve to an existing file: " + ref);
            } else if (inventoryPaths.contains(ref)) {
                tracedRepositoryFact = true;
            }
        }
        if (!inventoryPaths.isEmpty() && !tracedRepositoryFact) {
            errors.add("evidence_refs requires at least one fact from the tracked inventory");
        }
        return List.copyOf(errors);
    }

    List<String> validateRevisionCoverage(
            TaskContractProposal proposal,
            List<AgentResultEnvelope.ReviewObligation> obligations
    ) {
        var errors = new ArrayList<String>();
        if (obligations == null || obligations.isEmpty()) {
            errors.add("revision iteration requires verified contract obligations");
            return errors;
        }
        var expected = new LinkedHashMap<String, AgentResultEnvelope.ReviewObligation>();
        for (var obligation : obligations) {
            if (obligation == null || isBlank(obligation.id()) || isBlank(obligation.text())) {
                errors.add("verified contract obligation must contain nonblank id and text");
                continue;
            }
            if (expected.putIfAbsent(obligation.id().trim(), obligation) != null) {
                errors.add("verified contract obligation id is duplicated: " + obligation.id().trim());
            }
        }
        var actual = new LinkedHashMap<String, TaskContractProposal.RevisionResponse>();
        if (proposal.revisionResponses() == null || proposal.revisionResponses().isEmpty()) {
            errors.add("revision_responses is required for a revision iteration");
            return errors;
        }
        for (var response : proposal.revisionResponses()) {
            if (response == null || isBlank(response.reviewObligationId())) {
                continue;
            }
            var id = response.reviewObligationId().trim();
            if (actual.putIfAbsent(id, response) != null) {
                errors.add("revision_responses contains duplicate obligation id: " + id);
            }
        }
        for (var id : expected.keySet()) {
            if (!actual.containsKey(id)) {
                errors.add("revision_responses does not cover obligation: " + id);
            }
        }
        for (var id : actual.keySet()) {
            if (!expected.containsKey(id)) {
                errors.add("revision_responses refers to unknown obligation: " + id);
            }
        }
        return errors;
    }

    List<RevisionDeltaError> validateRevisionDelta(
            TaskContractProposal previous,
            TaskContractProposal current
    ) {
        var errors = new ArrayList<RevisionDeltaError>();
        if (previous == null) {
            return List.of(new RevisionDeltaError("REVISION_BASELINE_UNRESOLVABLE", ""));
        }
        var previousClauses = clauseSnapshot(previous);
        var currentClauses = clauseSnapshot(current);
        var modified = new LinkedHashSet<String>();
        var added = new LinkedHashSet<String>();
        var deleted = new LinkedHashSet<String>();
        for (var entry : currentClauses.entrySet()) {
            var baseline = previousClauses.get(entry.getKey());
            if (baseline == null) {
                added.add(entry.getKey());
            } else if (!baseline.equals(entry.getValue())) {
                modified.add(entry.getKey());
            }
        }
        for (var id : previousClauses.keySet()) {
            if (!currentClauses.containsKey(id)) {
                deleted.add(id);
            }
        }

        var declared = new LinkedHashSet<String>();
        if (current.revisionResponses() != null) {
            for (var response : current.revisionResponses()) {
                if (response != null && response.resolvedByClauseIds() != null) {
                    response.resolvedByClauseIds().stream()
                            .filter(id -> !isBlank(id))
                            .map(String::trim)
                            .forEach(declared::add);
                }
            }
        }
        modified.stream()
                .filter(id -> !declared.contains(id))
                .forEach(id -> errors.add(
                        new RevisionDeltaError("UNDECLARED_CONTRACT_CLAUSE_CHANGE", id)));
        added.stream()
                .filter(id -> !declared.contains(id))
                .forEach(id -> errors.add(
                        new RevisionDeltaError("UNDECLARED_CONTRACT_CLAUSE_ADDITION", id)));
        deleted.forEach(id -> errors.add(
                new RevisionDeltaError("CONTRACT_CLAUSE_DELETION_NOT_ALLOWED", id)));

        return List.copyOf(errors);
    }

    private static Map<String, ClauseSnapshot> clauseSnapshot(TaskContractProposal proposal) {
        var clauses = new LinkedHashMap<String, ClauseSnapshot>();
        addClauseSnapshots(clauses, "acceptance_criteria", proposal.acceptanceCriteria());
        addClauseSnapshots(clauses, "test_requirements", proposal.testRequirements());
        addClauseSnapshots(clauses, "constraints", proposal.constraints());
        addClauseSnapshots(clauses, "non_goals", proposal.nonGoals());
        addClauseSnapshots(clauses, "risk_areas", proposal.riskAreas());
        return Map.copyOf(clauses);
    }

    private static void addClauseSnapshots(
            Map<String, ClauseSnapshot> target,
            String section,
            List<TaskContractProposal.ContractClause> clauses
    ) {
        if (clauses == null) {
            return;
        }
        for (var clause : clauses) {
            if (clause != null && !isBlank(clause.id()) && !isBlank(clause.text())) {
                target.put(clause.id().trim(), new ClauseSnapshot(section, clause.text().trim()));
            }
        }
    }

    private static void validateClauses(
            String name,
            List<TaskContractProposal.ContractClause> clauses,
            boolean required,
            HashSet<String> ids,
            List<String> errors
    ) {
        if (clauses == null) {
            if (required) {
                errors.add(name + " must not be null");
            }
            return;
        }
        if (required && clauses.stream().noneMatch(clause -> clause != null && !isBlank(clause.text()))) {
            errors.add(name + " must not be empty");
        }
        var texts = new HashSet<String>();
        for (var clause : clauses) {
            if (clause == null) {
                errors.add(name + " contains null clause");
                continue;
            }
            if (isBlank(clause.id())) {
                errors.add(name + " contains blank clause id");
            } else if (!ids.add(clause.id().trim())) {
                errors.add("contract clause id is duplicated: " + clause.id().trim());
            }
            if (isBlank(clause.text())) {
                errors.add(name + " contains blank clause text");
            } else {
                if (containsMetadataNoise(clause.text())) {
                    errors.add(name + " contains ledger/context metadata: " + clause.text());
                }
                if (!texts.add(clause.text().trim().toLowerCase())) {
                    errors.add(name + " contains duplicate item: " + clause.text());
                }
            }
        }
    }

    private static void validateRevisionResponses(
            List<TaskContractProposal.RevisionResponse> responses,
            HashSet<String> clauseIds,
            List<String> errors
    ) {
        if (responses == null) {
            errors.add("revision_responses must not be null");
            return;
        }
        var obligationIds = new HashSet<String>();
        for (var response : responses) {
            if (response == null) {
                errors.add("revision_responses contains null response");
                continue;
            }
            if (isBlank(response.reviewObligationId())) {
                errors.add("revision_responses contains blank obligation id");
            } else if (!obligationIds.add(response.reviewObligationId().trim())) {
                errors.add("revision_responses contains duplicate obligation id: "
                        + response.reviewObligationId().trim());
            }
            if (response.resolvedByClauseIds() == null || response.resolvedByClauseIds().isEmpty()) {
                errors.add("revision_responses resolved_by_clause_ids must not be empty");
                continue;
            }
            var targets = new HashSet<String>();
            for (var clauseId : response.resolvedByClauseIds()) {
                if (isBlank(clauseId)) {
                    errors.add("revision_responses contains blank clause id");
                } else if (!targets.add(clauseId.trim())) {
                    errors.add("revision_responses contains duplicate clause target: " + clauseId.trim());
                } else if (!clauseIds.contains(clauseId.trim())) {
                    errors.add("revision_responses refers to unknown clause id: " + clauseId.trim());
                }
            }
        }
    }

    private static void validateList(String name, List<String> values, boolean required, List<String> errors) {
        if (values == null) {
            if (required) {
                errors.add(name + " must not be null");
            }
            return;
        }
        if (required && values.stream().allMatch(TaskContractProposalValidator::isBlank)) {
            errors.add(name + " must not be empty");
        }
        var seen = new HashSet<String>();
        for (var value : values) {
            if (containsMetadataNoise(value)) {
                errors.add(name + " contains ledger/context metadata: " + value);
            }
            if (!isBlank(value) && !seen.add(value.trim().toLowerCase())) {
                errors.add(name + " contains duplicate item: " + value);
            }
        }
    }

    private static void validateScopeOverlap(TaskContractProposal.Scope scope, List<String> errors) {
        if (scope.included() == null || scope.excluded() == null) {
            return;
        }
        var excluded = new HashSet<String>();
        for (var value : scope.excluded()) {
            if (!isBlank(value)) {
                excluded.add(value.trim());
            }
        }
        for (var included : scope.included()) {
            if (included != null
                    && !isBlank(included.path())
                    && excluded.contains(included.path())) {
                errors.add("scope.included overlaps scope.excluded: " + included.path());
            }
        }
    }

    private static void validateScopeEntries(
            List<TaskContract.ScopeEntry> entries,
            List<String> errors
    ) {
        if (entries == null || entries.isEmpty()) {
            errors.add("scope.included must not be empty");
            return;
        }
        var seen = new HashSet<String>();
        for (var entry : entries) {
            if (entry == null) {
                errors.add("scope.included contains null entry");
                continue;
            }
            if (isBlank(entry.path())) {
                errors.add("scope.included contains blank path");
                continue;
            }
            if (entry.operation() == null) {
                errors.add("scope.included operation is required: " + entry.path());
            }
            if (!seen.add(entry.path())) {
                errors.add("scope.included contains duplicate path: " + entry.path());
            }
        }
    }

    private static int nonBlankClauseCount(List<TaskContractProposal.ContractClause> values) {
        if (values == null) {
            return 0;
        }
        return (int) values.stream()
                .filter(value -> value != null && !isBlank(value.text()))
                .count();
    }

    private static void validateWorkspacePathRef(
            TaskContract.ScopeEntry ref,
            Path workspaceRoot,
            boolean inheritedCreate,
            List<String> errors
    ) {
        if (ref == null || isBlank(ref.path())) {
            errors.add("scope.included contains blank file ref");
            return;
        }
        if (containsMetadataNoise(ref.path())) {
            errors.add("scope.included contains ledger/context metadata: " + ref.path());
            return;
        }
        if (ref.path().startsWith("new:")) {
            errors.add("scope.included legacy new: prefix is not allowed: " + ref.path());
            return;
        }
        if (!TaskContractValidator.isCanonicalPath(ref.path())) {
            errors.add("scope.included is not a canonical relative file path: " + ref.path());
            return;
        }
        var path = workspaceRoot.resolve(ref.path()).normalize();
        if (!path.startsWith(workspaceRoot.toAbsolutePath().normalize()) && workspaceRoot.isAbsolute()) {
            errors.add("scope.included escapes workspace root: " + ref.path());
            return;
        }
        if (Files.isDirectory(path)) {
            errors.add("scope.included must be an exact file path, not a directory: " + ref.path());
            return;
        }
        // Resolution and this durable guard run synchronously against the same effective worktree.
        if (ref.operation() == TaskContract.ScopeOperation.MODIFY && !Files.exists(path)) {
            errors.add("scope.included MODIFY path does not exist: " + ref.path());
        }
        if (ref.operation() == TaskContract.ScopeOperation.CREATE && Files.exists(path) && !inheritedCreate) {
            errors.add("scope.included CREATE path already exists: " + ref.path());
        }
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }

    private static boolean containsMetadataNoise(String value) {
        if (value == null) {
            return false;
        }
        var lower = value.trim().toLowerCase();
        return lower.startsWith("workstream:")
                || lower.startsWith("builder node:")
                || lower.startsWith("target node:")
                || lower.startsWith("generated at:")
                || lower.startsWith("profile:")
                || lower.startsWith("total:")
                || lower.contains("context package")
                || lower.contains("context governance");
    }

    record RevisionDeltaError(String code, String targetId) {
        String message() {
            return targetId == null || targetId.isBlank() ? code : code + ": " + targetId;
        }
    }

    private record ClauseSnapshot(String section, String text) {}
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import dev.dual.core.execution.AdapterSignal;
import dev.dual.core.execution.AdapterSignalType;
import dev.dual.core.execution.AgentExecutionAttempt;
import dev.dual.core.execution.AgentExecutionAttemptStatus;
import dev.dual.core.execution.AgentExecutionEvidence;
import dev.dual.core.execution.AgentExecutionFinalizer;
import dev.dual.core.execution.AgentExecutionOutcome;
import dev.dual.core.execution.AgentExecutionOutcomeResolver;
import dev.dual.core.execution.AgentExecutionProcessStatus;
import dev.dual.core.execution.AgentExecutionRetryPolicy;
import dev.dual.core.execution.AgentExecutionTimelineEventKind;
import dev.dual.core.execution.ArtifactContractResult;
import dev.dual.core.execution.ProcessResult;
import dev.dual.core.execution.ProcessUsability;
import dev.dual.core.execution.AgentResultContractResult;
import dev.dual.core.workflow.NodeResult;

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Owns the run.json execution finalization projection.
 *
 * <p>Artifact validators provide result/artifact facts. This class is the
 * single runtime writer that combines those facts with process evidence and
 * persists terminal attempt/outcome fields into the agent run read model.</p>
 */
public final class AgentRunMetadataFinalizer {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    private final AgentExecutionFinalizer executionFinalizer;

    public AgentRunMetadataFinalizer() {
        this(new AgentExecutionFinalizer(new AgentExecutionOutcomeResolver()));
    }

    AgentRunMetadataFinalizer(AgentExecutionFinalizer executionFinalizer) {
        if (executionFinalizer == null) {
            throw new IllegalArgumentException("executionFinalizer is required");
        }
        this.executionFinalizer = executionFinalizer;
    }

    public NodeResult finalizeNodeResult(Path workspaceRoot, NodeResult result) {
        return resolveNodeResult(workspaceRoot, result, true);
    }

    /** Read the same execution facts before publication, without writing a terminal run projection. */
    NodeResult assessPublication(Path workspaceRoot, NodeResult result) {
        return resolveNodeResult(workspaceRoot, result, false);
    }

    private NodeResult resolveNodeResult(Path workspaceRoot, NodeResult result, boolean persist) {
        if (AgentExecutionResultFacts.inputPreparationFailed(result)) return result;
        if (!AgentExecutionResultFacts.present(result)) {
            return result;
        }
        var outcome = finalizeRunMetadata(
                workspaceRoot,
                result,
                AgentExecutionResultFacts.agentResultContract(result),
                AgentExecutionResultFacts.artifactContractResults(result),
                AgentExecutionResultFacts.rereadReasons(result), persist
        );
        var finalized = new LinkedHashMap<String, Object>();
        finalized.putAll(result.result());
        finalized.put("agent_execution_outcome", outcomeToMap(outcome));
        return new NodeResult(
                outcome.nodeMaySucceed() ? result.outcome() : outcome.primaryReason(),
                outcome.nodeMaySucceed() ? result.status() : dev.dual.core.workflow.NodeStatus.FAILED,
                result.outputRefs(),
                finalized,
                outcome.nodeMaySucceed() ? result.errorMessage() : outcome.operatorMessage()
        );
    }

    AgentExecutionOutcome finalizeRunMetadata(
            Path workspaceRoot,
            NodeResult result,
            AgentResultContractResult agentResultContract,
            List<ArtifactContractResult> artifactContractResults,
            Object rereadReasons
    ) {
        return finalizeRunMetadata(workspaceRoot, result, agentResultContract, artifactContractResults, rereadReasons, true);
    }

    private AgentExecutionOutcome finalizeRunMetadata(
            Path workspaceRoot, NodeResult result, AgentResultContractResult agentResultContract,
            List<ArtifactContractResult> artifactContractResults, Object rereadReasons, boolean persist
    ) {
        var runMetadataRef = text(result.result().get("run_metadata"));
        if (runMetadataRef.isBlank()) {
            var evidence = new AgentExecutionEvidence(
                    legacyProcessResult(result),
                    agentResultContract,
                    artifactContractResults,
                    resultAdapterSignals(result)
            );
            return executionFinalizer.finalize(baseAttempt(OBJECT_MAPPER.createObjectNode(), result), evidence).outcome();
        }
        var root = workspaceRoot.toAbsolutePath().normalize();
        var path = root.resolve(runMetadataRef).normalize();
        if (!path.startsWith(root) || !Files.isRegularFile(path)) {
            var evidence = new AgentExecutionEvidence(
                    legacyProcessResult(result),
                    agentResultContract,
                    artifactContractResults,
                    resultAdapterSignals(result)
            );
            return executionFinalizer.finalize(baseAttempt(OBJECT_MAPPER.createObjectNode(), result), evidence).outcome();
        }
        try {
            var json = (ObjectNode) OBJECT_MAPPER.readTree(path.toFile());
            var process = processResultFromRunMetadata(json);
            if (process == null) {
                process = legacyProcessResult(result);
            }
            var signals = json.path("adapterSignals").isMissingNode()
                    ? resultAdapterSignals(result)
                    : adapterSignalsFromRunMetadata(json);
            var evidence = new AgentExecutionEvidence(
                    process,
                    agentResultContract,
                    artifactContractResults,
                    signals
            );
            var processResult = mergedProcessResult(json, process);
            var finalized = executionFinalizer.finalize(baseAttempt(json, result), evidence);
            if (!persist) return finalized.outcome();
            json.put("schemaVersion", Math.max(json.path("schemaVersion").asInt(0), 3));
            json.put("status", finalized.legacyStatus());
            json.put("failureReason", finalized.legacyFailureReason());
            json.put("recoverable", finalized.legacyRecoverable());
            json.set("processResult", OBJECT_MAPPER.valueToTree(processResult));
            json.set("adapterSignals", OBJECT_MAPPER.valueToTree(signals.stream()
                    .map(AgentRunMetadataFinalizer::adapterSignalToMap)
                    .toList()));
            json.set("agentResultContract", OBJECT_MAPPER.valueToTree(
                    AgentExecutionResultFacts.agentResultContractToMap(agentResultContract)));
            json.set("artifactContractResults", OBJECT_MAPPER.valueToTree(artifactContractResults.stream()
                    .map(AgentExecutionResultFacts::artifactContractToMap)
                    .toList()));
            if (rereadReasons != null) {
                json.set("reread_reasons", OBJECT_MAPPER.valueToTree(rereadReasons));
            }
            appendTimelineEvent(json, AgentExecutionTimelineEventKind.CONTRACT_VALIDATED);
            json.set("executionAttempt", OBJECT_MAPPER.valueToTree(executionAttemptToMap(finalized.attempt())));
            json.set("executionOutcome", OBJECT_MAPPER.valueToTree(outcomeToMap(finalized.outcome())));
            OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValue(path.toFile(), json);
            return finalized.outcome();
        } catch (Exception failure) {
            throw new IllegalStateException("failed to finalize typed agent run metadata", failure);
        }
    }

    private static List<AdapterSignal> resultAdapterSignals(NodeResult result) {
        if (result.result().containsKey("adapter_signals")) {
            return adapterSignalsFromValue(result.result().get("adapter_signals"));
        }
        return legacyAdapterSignals(result);
    }

    private static List<AdapterSignal> legacyAdapterSignals(NodeResult result) {
        var reason = text(result.result().get("acpx_failure.reason"));
        if (reason.isBlank()) {
            return List.of();
        }
        var type = switch (reason) {
            case "RECOVERABLE_AGENT_RECONNECT" -> AdapterSignalType.AGENT_RECONNECT_REQUIRED;
            case "RECOVERABLE_AGENT_MODEL_MISMATCH" -> AdapterSignalType.MODEL_MISMATCH;
            case "RECOVERABLE_SESSION_BOOTSTRAP_FAILED" -> AdapterSignalType.SESSION_BOOTSTRAP_FAILED;
            case "RECOVERABLE_SESSION_MISSING" -> AdapterSignalType.SESSION_RESUME_FAILED;
            case "RECOVERABLE_AGENT_AUTH_FAILED" -> AdapterSignalType.AUTH_FAILED;
            case "RECOVERABLE_PROVIDER_CONNECTION_FAILED" -> AdapterSignalType.PROVIDER_CONNECTION_FAILED;
            case "RECOVERABLE_RATE_LIMIT", "RECOVERABLE_AGENT_OVERLOADED" -> AdapterSignalType.RATE_LIMITED;
            case "RECOVERABLE_CONTEXT_WINDOW" -> AdapterSignalType.CONTEXT_WINDOW_EXCEEDED;
            case "RECOVERABLE_AGENT_PERMISSION_BLOCKED" -> AdapterSignalType.PERMISSION_BLOCKED;
            case "RECOVERABLE_AGENT_OUTPUT_INTERRUPTED" -> AdapterSignalType.PROCESS_STALLED;
            case "RECOVERABLE_TRANSPORT_FAILED" -> AdapterSignalType.PROCESS_STALLED;
            default -> null;
        };
        return type == null ? List.of() : List.of(new AdapterSignal(type, reason, 0));
    }

    static List<AdapterSignal> adapterSignalsFromRunMetadata(ObjectNode json) {
        var existing = json.path("adapterSignals");
        if (!existing.isArray()) {
            throw new IllegalArgumentException("typed adapterSignals must be an array");
        }
        var signals = new ArrayList<AdapterSignal>();
        for (var item : existing) {
            if (!item.isObject()) {
                throw new IllegalArgumentException("typed adapterSignals entries must be objects");
            }
            var type = enumValue(AdapterSignalType.class, item.path("type").asText(""), null);
            if (type == null) {
                throw new IllegalArgumentException("typed adapterSignals.type is missing or invalid");
            }
            signals.add(new AdapterSignal(
                    type,
                    item.path("message").asText(""),
                    item.path("observedSequence").isNumber() ? Math.max(0L, item.path("observedSequence").asLong()) : 0L,
                    item.path("source").asText(""),
                    item.path("sessionId").asText(""),
                    item.path("superseded").isBoolean() && item.path("superseded").asBoolean()
            ));
        }
        return List.copyOf(signals);
    }

    private static List<AdapterSignal> adapterSignalsFromValue(Object value) {
        if (!(value instanceof List<?> list)) {
            throw new IllegalArgumentException("typed adapter_signals must be a list");
        }
        var signals = new ArrayList<AdapterSignal>();
        for (var item : list) {
            if (!(item instanceof Map<?, ?> map)) {
                throw new IllegalArgumentException("typed adapter_signals entries must be maps");
            }
            var type = enumValue(AdapterSignalType.class, text(map.get("type")), null);
            if (type == null) {
                throw new IllegalArgumentException("typed adapter_signals.type is missing or invalid");
            }
            var sequence = map.get("observedSequence") instanceof Number number
                    ? Math.max(0L, number.longValue())
                    : 0L;
            signals.add(new AdapterSignal(
                    type,
                    text(map.get("message")),
                    sequence,
                    text(map.get("source")),
                    text(map.get("sessionId")),
                    Boolean.TRUE.equals(map.get("superseded"))
            ));
        }
        return List.copyOf(signals);
    }

    static Map<String, Object> outcomeToMap(AgentExecutionOutcome outcome) {
        var map = new LinkedHashMap<String, Object>();
        map.put("status", outcome.status().name());
        map.put("primaryReason", outcome.primaryReason());
        map.put("nodeMaySucceed", outcome.nodeMaySucceed());
        map.put("retryPolicy", outcome.retryPolicy().name());
        map.put("recoveryCategory", outcome.recoveryCategory().name());
        map.put("operatorMessage", outcome.operatorMessage());
        map.put("secondarySignals", outcome.secondarySignals().stream()
                .map(AgentRunMetadataFinalizer::signalToMap)
                .toList());
        return map;
    }

    private static Map<String, Object> signalToMap(AdapterSignal signal) {
        var map = new LinkedHashMap<String, Object>();
        map.put("type", signal.type().name());
        map.put("severity", signal.type().severity().name());
        map.put("message", signal.message());
        map.put("observedSequence", signal.observedSequence());
        map.put("source", signal.source());
        map.put("sessionId", signal.sessionId());
        map.put("superseded", signal.superseded());
        return map;
    }

    private static ProcessResult legacyProcessResult(NodeResult result) {
        var usability = processUsability(result);
        var exitCode = result.result().get("exit_code");
        if (exitCode instanceof Number number && number.intValue() != 0) {
            if (usability == ProcessUsability.EXITED_NON_ZERO_WITH_COMPLETE_OUTPUT) {
                return ProcessResult.nonZeroComplete(number.intValue());
            }
            if (usability == ProcessUsability.KILLED_AFTER_RECOVERABLE_SIGNAL) {
                return ProcessResult.killedAfterRecoverableSignal();
            }
            return ProcessResult.nonZeroIncomplete(number.intValue());
        }
        if (usability == ProcessUsability.INTERRUPTED) {
            return ProcessResult.interruptedProcess();
        }
        if (usability == ProcessUsability.TIMED_OUT || usability == ProcessUsability.STALLED) {
            return ProcessResult.timedOutProcess();
        }
        return ProcessResult.exitedZero();
    }

    private static ProcessUsability processUsability(NodeResult result) {
        var explicit = text(result.result().get("process_usability"));
        if (!explicit.isBlank()) {
            try {
                return ProcessUsability.valueOf(explicit);
            } catch (IllegalArgumentException ignored) {
                // Fall back to legacy inference below for historical ledgers.
            }
        }
        var reason = text(result.result().get("acpx_failure.reason"));
        if ("RECOVERABLE_AGENT_OUTPUT_INTERRUPTED".equals(reason)) {
            return ProcessUsability.INTERRUPTED;
        }
        var exitCode = result.result().get("exit_code");
        if (exitCode instanceof Number number && number.intValue() != 0) {
            return result.status() == dev.dual.core.workflow.NodeStatus.COMPLETED
                    ? ProcessUsability.EXITED_NON_ZERO_WITH_COMPLETE_OUTPUT
                    : ProcessUsability.EXITED_NON_ZERO_WITH_INCOMPLETE_OUTPUT;
        }
        return ProcessUsability.EXITED_ZERO;
    }

    private static Map<String, Object> processResultToMap(ProcessResult process) {
        var map = new LinkedHashMap<String, Object>();
        map.put("command", process.command());
        map.put("pid", process.pid());
        map.put("exitCode", process.exitCode());
        map.put("usability", process.usability().name());
        map.put("durationMs", process.durationMs());
        map.put("stdoutPath", process.stdoutPath());
        map.put("stderrPath", process.stderrPath());
        map.put("interrupted", process.interrupted());
        map.put("timedOut", process.timedOut());
        return map;
    }

    private static AgentExecutionAttempt baseAttempt(ObjectNode json, NodeResult result) {
        var attempt = json.path("executionAttempt");
        var runId = firstNonBlank(json.path("runId").asText(""), text(result.result().get("run_id")), "run-unknown");
        return new AgentExecutionAttempt(
                firstNonBlank(attempt.path("attemptId").asText(""), "att-" + runId),
                runId,
                firstNonBlank(json.path("workstreamId").asText(""), attempt.path("workstreamId").asText("")),
                firstNonBlank(json.path("nodeId").asText(""), attempt.path("nodeId").asText("")),
                firstNonBlank(json.path("agent").asText(""), attempt.path("agent").asText(""), text(result.result().get("agent"))),
                AgentExecutionAttemptStatus.RUNNING,
                AgentExecutionProcessStatus.RUNNING,
                null,
                false,
                false,
                firstNonBlank(attempt.path("message").asText(""), "process exited"),
                attempt.path("stderrPath").asText(""),
                attempt.path("transcriptPath").asText(""),
                attempt.path("sessionName").asText(""),
                attempt.path("sessionId").asText(""),
                attempt.path("sessionScope").asText(""),
                attempt.path("sessionSegmentKey").asText(""),
                firstInstant(attempt.path("startedAt").asText(""), json.path("startedAt").asText("")),
                firstInstant(attempt.path("finishedAt").asText(""), json.path("finishedAt").asText(""))
        );
    }

    private static Map<String, Object> executionAttemptToMap(AgentExecutionAttempt attempt) {
        var map = new LinkedHashMap<String, Object>();
        map.put("attemptId", attempt.attemptId());
        map.put("runId", attempt.runId());
        map.put("workstreamId", attempt.workstreamId());
        map.put("nodeId", attempt.nodeId());
        map.put("agent", attempt.agent());
        map.put("status", attempt.status().name());
        map.put("processStatus", attempt.processStatus().name());
        map.put("failureSignal", attempt.failureSignal() == null ? null : attempt.failureSignal().name());
        map.put("recoverable", attempt.recoverable());
        map.put("retrySafe", attempt.retrySafe());
        map.put("message", attempt.message());
        map.put("stderrPath", attempt.stderrPath());
        map.put("transcriptPath", attempt.transcriptPath());
        map.put("sessionName", attempt.sessionName());
        map.put("sessionId", attempt.sessionId());
        map.put("sessionScope", attempt.sessionScope());
        map.put("sessionSegmentKey", attempt.sessionSegmentKey());
        map.put("startedAt", attempt.startedAt() == null ? null : attempt.startedAt().toString());
        map.put("finishedAt", attempt.finishedAt() == null ? null : attempt.finishedAt().toString());
        return map;
    }

    private static Map<String, Object> mergedProcessResult(ObjectNode json, ProcessResult process) {
        var merged = new LinkedHashMap<String, Object>();
        var existing = json.path("processResult");
        if (existing.isObject()) {
            existing.fields().forEachRemaining(entry -> merged.put(entry.getKey(), OBJECT_MAPPER.convertValue(entry.getValue(), Object.class)));
        }
        var semantic = processResultToMap(process);
        for (var entry : semantic.entrySet()) {
            if (entry.getValue() != null && !String.valueOf(entry.getValue()).isBlank()) {
                merged.put(entry.getKey(), entry.getValue());
            }
        }
        return merged;
    }

    static ProcessResult processResultFromRunMetadata(ObjectNode json) {
        var existing = json.path("processResult");
        if (existing.isMissingNode()) {
            return null;
        }
        if (!existing.isObject()) {
            throw new IllegalArgumentException("typed processResult must be an object");
        }
        var usability = enumValue(ProcessUsability.class, existing.path("usability").asText(""), null);
        if (usability == null) {
            throw new IllegalArgumentException("typed processResult.usability is missing or invalid");
        }
        Long pid = existing.path("pid").isNumber() ? existing.path("pid").asLong() : null;
        Integer exitCode = existing.path("exitCode").isNumber() ? existing.path("exitCode").asInt() : null;
        return new ProcessResult(
                existing.path("command").asText(""),
                pid,
                exitCode,
                usability,
                existing.path("durationMs").isNumber() ? Math.max(0L, existing.path("durationMs").asLong()) : 0L,
                existing.path("stdoutPath").asText(""),
                existing.path("stderrPath").asText(""),
                existing.path("interrupted").asBoolean(false),
                existing.path("timedOut").asBoolean(false)
        );
    }

    private static Map<String, Object> adapterSignalToMap(AdapterSignal signal) {
        var map = new LinkedHashMap<String, Object>();
        map.put("type", signal.type().name());
        map.put("severity", signal.type().severity().name());
        map.put("source", signal.source());
        map.put("message", signal.message());
        map.put("sessionId", signal.sessionId());
        map.put("observedSequence", signal.observedSequence());
        map.put("superseded", signal.superseded());
        return map;
    }

    private static Instant instantOrNull(String value) {
        if (value == null || value.isBlank()) {
            return null;
        }
        try {
            return Instant.parse(value);
        } catch (RuntimeException ignored) {
            return null;
        }
    }

    private static Instant firstInstant(String first, String second) {
        var parsed = instantOrNull(first);
        return parsed == null ? instantOrNull(second) : parsed;
    }

    private static <E extends Enum<E>> E enumValue(Class<E> type, String value, E fallback) {
        if (value == null || value.isBlank()) {
            return fallback;
        }
        try {
            return Enum.valueOf(type, value);
        } catch (RuntimeException ignored) {
            return fallback;
        }
    }

    private static int intValue(Object value) {
        if (value instanceof Number number) {
            return number.intValue();
        }
        if (value == null) {
            return 0;
        }
        try {
            return Integer.parseInt(String.valueOf(value));
        } catch (NumberFormatException ignored) {
            return 0;
        }
    }

    private static String firstNonBlank(String first, String second) {
        return firstNonBlank(new String[]{first, second});
    }

    private static String firstNonBlank(String... values) {
        if (values == null) {
            return "";
        }
        for (var value : values) {
            if (value != null && !value.isBlank()) {
                return value;
            }
        }
        return "";
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value);
    }

    private static void appendTimelineEvent(ObjectNode json, AgentExecutionTimelineEventKind kind) {
        var timeline = new ArrayList<Map<String, Object>>();
        var existing = json.get("executionTimeline");
        if (existing != null && existing.isArray()) {
            for (var item : existing) {
                timeline.add(OBJECT_MAPPER.convertValue(item, MAP_TYPE));
            }
        }
        var startedAt = instantOrNull(text(json.get("startedAt")));
        var observedAt = Instant.now();
        timeline.add(Map.of(
                "kind", kind.wireName(),
                "source", "runtime",
                "sequence", timeline.size() + 1L,
                "observedAt", observedAt.toString(),
                "elapsedMs", startedAt == null ? 0L : Math.max(0L, Duration.between(startedAt, observedAt).toMillis())
        ));
        json.set("executionTimeline", OBJECT_MAPPER.valueToTree(timeline));
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.UUID;
import java.util.regex.Pattern;

final class ChangeScopeEvaluationArtifact {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper()
            .findAndRegisterModules()
            .enable(SerializationFeature.INDENT_OUTPUT);
    private static final Pattern REF = Pattern.compile(
            "\\.agent/workstreams/([^/]+)/artifacts/git-evidence/occurrences/([^/]+)/change-scope-evaluation-([0-9a-f]{64})\\.json");

    private ChangeScopeEvaluationArtifact() {
    }

    static Reference publish(
            Path workspaceRoot,
            String workstreamId,
            String sourceNodeInstanceId,
            ChangeScopeEvaluation evaluation
    ) throws IOException {
        var document = new Document(1, workstreamId, sourceNodeInstanceId, evaluation);
        var bytes = OBJECT_MAPPER.writeValueAsBytes(document);
        var sha256 = sha256(bytes);
        var ref = ".agent/workstreams/" + workstreamId
                + "/artifacts/git-evidence/occurrences/" + sourceNodeInstanceId
                + "/change-scope-evaluation-" + sha256 + ".json";
        var target = resolveInside(workspaceRoot, ref);
        Files.createDirectories(target.getParent());
        if (Files.exists(target)) {
            if (!Files.isRegularFile(target) || !sha256(Files.readAllBytes(target)).equals(sha256)) {
                throw new IOException("existing change-scope occurrence does not match its content address");
            }
            return new Reference(ref, sha256);
        }
        var temporary = target.resolveSibling(target.getFileName() + ".tmp-" + UUID.randomUUID());
        try {
            Files.write(temporary, bytes);
            try {
                Files.move(temporary, target, StandardCopyOption.ATOMIC_MOVE);
            } catch (IOException atomicMoveFailure) {
                Files.move(temporary, target);
            }
        } finally {
            Files.deleteIfExists(temporary);
        }
        return new Reference(ref, sha256);
    }

    static Verified verify(
            Path workspaceRoot,
            String expectedWorkstreamId,
            String expectedSourceNodeInstanceId,
            String ref,
            String expectedSha256
    ) throws IOException {
        var matcher = REF.matcher(ref == null ? "" : ref);
        if (!matcher.matches()
                || !expectedWorkstreamId.equals(matcher.group(1))
                || !expectedSourceNodeInstanceId.equals(matcher.group(2))) {
            throw new IOException("change-scope evaluation ref is not canonical for the expected occurrence");
        }
        if (expectedSha256 == null || !expectedSha256.matches("[0-9a-f]{64}")
                || !expectedSha256.equals(matcher.group(3))) {
            throw new IOException("change-scope evaluation ref sha256 does not match the lineage anchor");
        }
        var path = resolveInside(workspaceRoot, ref);
        if (!Files.isRegularFile(path)) {
            throw new IOException("change-scope evaluation occurrence is missing");
        }
        var bytes = Files.readAllBytes(path);
        var actualSha256 = sha256(bytes);
        if (!expectedSha256.equals(actualSha256)) {
            throw new IOException("change-scope evaluation occurrence sha256 mismatch");
        }
        final Document document;
        try {
            document = OBJECT_MAPPER.readValue(bytes, Document.class);
        } catch (Exception failure) {
            throw new IOException("change-scope evaluation occurrence cannot be parsed", failure);
        }
        if (document.schemaVersion() != 1
                || !expectedWorkstreamId.equals(document.workstreamId())
                || !expectedSourceNodeInstanceId.equals(document.sourceNodeInstanceId())
                || document.evaluation() == null) {
            throw new IOException("change-scope evaluation occurrence lineage mismatch");
        }
        return new Verified(ref, actualSha256, document, path);
    }

    static String sourceNodeInstanceId(String ref) {
        var matcher = REF.matcher(ref == null ? "" : ref);
        return matcher.matches() ? matcher.group(2) : "";
    }

    static Verified verifyGateSource(Path root, String workstreamId, String iterationId,
                                     java.util.List<String> inputRefs) throws IOException {
        var refs = inputRefs.stream().filter(ref -> isCanonicalRefForWorkstream(ref, workstreamId)).toList();
        if (refs.size() != 1) {
            throw new IOException("change-scope violation gate must receive exactly one occurrence evaluation");
        }
        var ref = refs.getFirst();
        var sourceId = sourceNodeInstanceId(ref);
        var sourcePath = resolveInside(root, ".agent/workstreams/" + workstreamId + "/nodes/" + sourceId + ".json");
        var source = OBJECT_MAPPER.readValue(sourcePath.toFile(), dev.dual.ledger.file.NodeInstanceDocument.class);
        if (!sourceId.equals(source.nodeInstanceId())
                || !"implement.artifact_validation".equals(source.nodeDefinitionId())
                || !"artifact.validate".equals(source.handlerType())
                || source.status() != dev.dual.core.workflow.NodeStatus.COMPLETED
                || !iterationId.equals(source.iterationId()) || !source.outputRefs().contains(ref)
                || !"FAIL".equals(source.result().get("change_scope_status"))
                || !"CHANGE_SCOPE_VIOLATION".equals(source.result().get("change_scope_disposition"))
                || !ref.equals(source.result().get("change_scope_evaluation_ref"))) {
            throw new IOException("change-scope evaluation producer lineage is invalid");
        }
        var verified = verify(root, workstreamId, sourceId, ref,
                String.valueOf(source.result().get("change_scope_evaluation_sha256")));
        if (verified.document().evaluation().status() != ChangeScopeEvaluation.Status.FAIL) {
            throw new IOException("change-scope occurrence is not a failed evaluation");
        }
        return verified;
    }

    static boolean isCanonicalRefForWorkstream(String ref, String workstreamId) {
        var matcher = REF.matcher(ref == null ? "" : ref);
        return matcher.matches() && workstreamId.equals(matcher.group(1));
    }

    private static Path resolveInside(Path workspaceRoot, String ref) throws IOException {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var path = root.resolve(ref).normalize();
        if (!path.startsWith(root)) {
            throw new IOException("change-scope evaluation ref escapes the workspace");
        }
        return path;
    }

    private static String sha256(byte[] bytes) throws IOException {
        try {
            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
        } catch (NoSuchAlgorithmException impossible) {
            throw new IOException("SHA-256 is unavailable", impossible);
        }
    }

    record Document(
            int schemaVersion,
            String workstreamId,
            String sourceNodeInstanceId,
            ChangeScopeEvaluation evaluation
    ) {
    }

    record Reference(String ref, String sha256) {
    }

    record Verified(String ref, String sha256, Document document, Path path) {
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.BasicFileAttributes;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Stream;

/**
 * Renders a compact boundary between harness facts, human decisions, agent
 * proposals, and pending evidence gaps.
 */
final class ContextStateEvidenceBoundaryRenderer {
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    private ContextStateEvidenceBoundaryRenderer() {
    }

    static void append(StringBuilder builder, TaskHandler.TaskContext context, Path workstreamDir, ObjectMapper objectMapper) throws IOException {
        append(builder, context, workstreamDir, objectMapper, Optional.empty());
    }

    static void append(
            StringBuilder builder,
            TaskHandler.TaskContext context,
            Path workstreamDir,
            ObjectMapper objectMapper,
            Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract
    ) throws IOException {
        builder.append("## State & Evidence Boundary\n\n");
        builder.append("This package separates deterministic harness facts from agent proposals.\n\n");

        appendTrustedFacts(builder, workstreamDir, objectMapper, qualifiedContract);
        var routedEvidence = AgentEvidenceIndex.fromRefs(
                context.workspaceRoot(), context.workstreamId(), context.instance().inputRefs(), objectMapper);
        appendCurrentRepairObjective(builder, workstreamDir, objectMapper, routedEvidence);
        appendHumanDecisions(builder, qualifiedContract);
        appendAgentProposedStates(builder, routedEvidence);
        appendPendingGaps(builder, workstreamDir, objectMapper);
    }

    private static void appendTrustedFacts(
            StringBuilder builder,
            Path workstreamDir,
            ObjectMapper objectMapper,
            Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract
    ) throws IOException {
        builder.append("### Trusted Harness Facts\n\n");
        if (qualifiedContract.isPresent()) {
            var snapshot = qualifiedContract.orElseThrow();
            var contract = snapshot.contract();
            builder.append("- TaskContract: ").append(contract.status()).append(" - ")
                    .append(contract.objective()).append(" (").append(snapshot.contractRef()).append(")\n");
        } else {
            builder.append("- TaskContract qualification: not available\n");
        }

        var gitEvidencePath = workstreamDir.resolve("artifacts/git-evidence/git-evidence.json");
        if (Files.exists(gitEvidencePath)) {
            var git = readJsonUnchecked(gitEvidencePath, objectMapper);
            builder.append("- Git Evidence: available=").append(text(git.get("available")));
            var changedFileCount = text(git.get("changedFileCount"));
            if (!changedFileCount.isBlank()) {
                builder.append(", changedFileCount=").append(changedFileCount);
            }
            builder.append(" (").append(toDisplayRef(gitEvidencePath)).append(")\n");
        } else {
            builder.append("- Git Evidence: not generated yet\n");
        }
    }

    private static void appendCurrentRepairObjective(
            StringBuilder builder,
            Path workstreamDir,
            ObjectMapper objectMapper,
            AgentEvidenceIndex routedEvidence
    ) throws IOException {
        var latestRejected = routedEvidence.recent(20)
                .stream()
                .filter(ContextStateEvidenceBoundaryRenderer::isRejectedAcceptance)
                .findFirst();
        if (latestRejected.isEmpty()) {
            return;
        }

        var entry = latestRejected.get();
        var contract = entry.document();
        var classification = readJsonUnchecked(workstreamDir.resolve("artifacts/failure-classification.json"), objectMapper);

        builder.append("\n### Current Repair Objective\n\n");
        var category = firstNonBlank(
                text(classification.get("category")),
                contract.failure().categoryHint()
        );
        if (!category.isBlank()) {
            builder.append("- Category: ").append(category).append("\n");
        }
        builder.append("- Source: ").append(toDisplayRef(entry.path())).append("\n");
        if (!contract.summary().isBlank()) {
            builder.append("- Summary: ").append(contract.summary()).append("\n");
        }
        appendList(builder, "Must Fix", contract.mustFix(), 8);
        appendList(builder, "Contract Gaps", contract.failure().contractGaps(), 8);
        if (!contract.failure().reason().isBlank()) {
            builder.append("- Failure Reason: ").append(contract.failure().reason()).append("\n");
        }
        var suggestedAction = text(classification.get("suggested_action"));
        if (!suggestedAction.isBlank()) {
            builder.append("- Suggested Action: ").append(suggestedAction).append("\n");
        }
        builder.append("\n");
    }

    private static boolean isRejectedAcceptance(AgentEvidenceIndex.Entry entry) {
        var document = entry.document();
        return "acceptance.codex_verifier_review".equals(document.nodeId())
                && ("REJECT".equals(document.decision()) || "REJECTED".equals(document.canonicalStageOutcome()));
    }

    private static void appendHumanDecisions(
            StringBuilder builder,
            Optional<TaskContractProjectionVerifier.QualifiedTaskContract> qualifiedContract
    ) {
        builder.append("\n### Human Decisions\n\n");
        if (qualifiedContract.isPresent()) {
            var snapshot = qualifiedContract.orElseThrow();
            var resolution = snapshot.resolutionDocument();
            builder.append("- Requirement Resolution: ").append(text(resolution.get("decision")))
                    .append(" by ").append(text(resolution.get("approved_by")))
                    .append(" (").append(snapshot.resolutionRef()).append(")\n");
            for (var item : resolvedQuestionTexts(resolution.get("resolved_questions")).stream().limit(3).toList()) {
                builder.append("  - ").append(item).append("\n");
            }
        } else {
            builder.append("- Requirement Resolution: not available\n");
        }
    }

    private static void appendAgentProposedStates(StringBuilder builder, AgentEvidenceIndex routedEvidence) {
        builder.append("\n### Agent Proposed States\n\n");
        var entries = routedEvidence.recent(5);
        if (entries.isEmpty()) {
            builder.append("- No routed validated agent sidecars yet\n");
            return;
        }
        for (var entry : entries) {
            var contract = entry.document();
            builder.append("- ").append(blankAsNone(contract.nodeId()))
                    .append(": decision=").append(blankAsNone(contract.decision()));
            if (!contract.canonicalStageOutcome().isBlank()) {
                builder.append(", stageOutcome=").append(contract.canonicalStageOutcome());
            }
            var evidenceState = entry.evidenceState();
            if (!evidenceState.isEmpty()) {
                builder.append(", evidenceState=").append(evidenceState);
            }
            builder.append(" (").append(toDisplayRef(entry.path())).append(")\n");
        }
    }

    private static void appendPendingGaps(StringBuilder builder, Path workstreamDir, ObjectMapper objectMapper) throws IOException {
        builder.append("\n### Pending Contract/Evidence Gaps\n\n");
        var failures = recentContractFailures(workstreamDir, 3);
        if (failures.isEmpty()) {
            builder.append("- No contract failure diagnostics recorded\n\n");
            return;
        }
        for (var failurePath : failures) {
            var failure = readJsonUnchecked(failurePath, objectMapper);
            builder.append("- ").append(blankAsNone(text(failure.get("node_id"))))
                    .append(": ").append(blankAsNone(text(failure.get("category"))))
                    .append(" / ").append(blankAsNone(text(failure.get("reason"))))
                    .append(" (").append(toDisplayRef(failurePath)).append(")\n");
            var hint = text(failure.get("recovery_hint"));
            if (!hint.isBlank()) {
                builder.append("  - Recovery: ").append(hint).append("\n");
            }
        }
        builder.append("\n");
    }

    private static List<Path> recentContractFailures(Path workstreamDir, int maxItems) throws IOException {
        var failureDir = workstreamDir.resolve("artifacts/contract-failures");
        if (!Files.exists(failureDir)) {
            return List.of();
        }
        try (Stream<Path> paths = Files.list(failureDir)) {
            return paths
                    .filter(Files::isRegularFile)
                    .filter(path -> path.getFileName().toString().endsWith(".json"))
                    .sorted(Comparator.comparing(ContextStateEvidenceBoundaryRenderer::lastModified).reversed())
                    .limit(maxItems)
                    .toList();
        }
    }

    private static List<String> resolvedQuestionTexts(Object value) {
        if (!(value instanceof List<?> items)) {
            return List.of();
        }
        var result = new ArrayList<String>();
        for (var item : items) {
            if (item instanceof Map<?, ?> map) {
                var question = text(map.get("question"));
                var resolution = text(map.get("resolution"));
                if (!question.isBlank()) {
                    result.add(resolution.isBlank() ? question : question + " -> " + resolution);
                }
            }
        }
        return List.copyOf(result);
    }

    private static Map<String, Object> readJsonUnchecked(Path path, ObjectMapper objectMapper) {
        try {
            return objectMapper.readValue(path.toFile(), MAP_TYPE);
        } catch (IOException e) {
            return Map.of();
        }
    }

    private static Instant lastModified(Path path) {
        try {
            return Files.readAttributes(path, BasicFileAttributes.class).lastModifiedTime().toInstant();
        } catch (IOException ignored) {
            return Instant.EPOCH;
        }
    }

    private static String blankAsNone(String value) {
        return value == null || value.isBlank() ? "(none)" : value;
    }

    private static String toDisplayRef(Path path) {
        return path.toAbsolutePath().normalize().toString();
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    private static void appendList(StringBuilder builder, String label, List<String> values, int maxItems) {
        if (values.isEmpty()) {
            return;
        }
        builder.append("- ").append(label).append(":\n");
        for (var value : values.stream().limit(maxItems).toList()) {
            builder.append("  - ").append(value).append("\n");
        }
    }

    private static String firstNonBlank(String first, String second) {
        return first == null || first.isBlank() ? (second == null ? "" : second) : first;
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.annotation.JsonProperty;
import dev.dual.core.contract.TaskContract;

import java.util.List;

record TaskContractProposal(
        @JsonProperty("artifact_type") String artifactType,
        @JsonProperty("schema_version") int schemaVersion,
        String objective,
        Scope scope,
        @JsonProperty("acceptance_criteria") List<ContractClause> acceptanceCriteria,
        @JsonProperty("test_requirements") List<ContractClause> testRequirements,
        List<ContractClause> constraints,
        @JsonProperty("non_goals") List<ContractClause> nonGoals,
        @JsonProperty("risk_areas") List<ContractClause> riskAreas,
        @JsonProperty("evidence_refs") List<String> evidenceRefs,
        @JsonProperty("open_questions") List<String> openQuestions,
        @JsonProperty("revision_responses") List<RevisionResponse> revisionResponses
) {
    static final int SCHEMA_VERSION = 3;

    record Scope(
            List<TaskContract.ScopeEntry> included,
            List<String> excluded
    ) {}

    record ContractClause(String id, String text) {}

    record RevisionResponse(
            @JsonProperty("review_obligation_id") String reviewObligationId,
            @JsonProperty("resolved_by_clause_ids") List<String> resolvedByClauseIds
    ) {}
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;

/** Immutable identity and lineage for one validated task-contract proposal sidecar. */
public record TaskContractProposalReference(
        @JsonProperty("schema_version") int schemaVersion,
        @JsonProperty("proposal_id") String proposalId,
        @JsonProperty("workstream_id") String workstreamId,
        @JsonProperty("producer_node_id") String producerNodeId,
        @JsonProperty("producer_node_instance_id") String producerNodeInstanceId,
        @JsonProperty("artifact_ref") String artifactRef,
        @JsonProperty("sha256") String sha256
) {
    private static final int SCHEMA_VERSION = 1;

    public TaskContractProposalReference {
        if (schemaVersion != SCHEMA_VERSION) {
            throw new IllegalArgumentException("unsupported proposal reference schema_version: " + schemaVersion);
        }
        requireText(proposalId, "proposal_id");
        requireText(workstreamId, "workstream_id");
        requireText(producerNodeId, "producer_node_id");
        requireText(producerNodeInstanceId, "producer_node_instance_id");
        requireText(artifactRef, "artifact_ref");
        if (sha256 == null || !sha256.matches("[0-9a-f]{64}")) {
            throw new IllegalArgumentException("sha256 must be 64 lowercase hexadecimal characters");
        }
    }

    static Published publishInitial(
            Path workspaceRoot,
            String workstreamId,
            Path sidecarPath,
            AgentOutputContractDocument document,
            ObjectMapper objectMapper
    ) throws Exception {
        if (!"task_contract_proposal".equals(document.sourceArtifactType())
                || document.proposalDerivation() != null) {
            throw new IllegalArgumentException("direct task-contract proposal lineage is required");
        }
        return publishVerified(workspaceRoot, workstreamId, sidecarPath, document, objectMapper);
    }

    static Published publishRevisionDerived(
            Path workspaceRoot,
            String workstreamId,
            Path sidecarPath,
            AgentOutputContractDocument document,
            ObjectMapper objectMapper
    ) throws Exception {
        if (!"task_contract_revision_patch".equals(document.sourceArtifactType())
                || document.proposalDerivation() == null) {
            throw new IllegalArgumentException("revision-derived task-contract proposal lineage is required");
        }
        return publishVerified(workspaceRoot, workstreamId, sidecarPath, document, objectMapper);
    }

    private static Published publishVerified(
            Path workspaceRoot,
            String workstreamId,
            Path sidecarPath,
            AgentOutputContractDocument document,
            ObjectMapper objectMapper
    ) throws Exception {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var sidecar = sidecarPath.toAbsolutePath().normalize();
        if (!sidecar.startsWith(root)
                || !Files.isRegularFile(sidecar)
                || !document.hasValidatedLineage(workstreamId, root, sidecar)
                || !"intake.claude_brainstorm".equals(document.nodeId())
                || document.taskContractProposal() == null
                || !validProposalSource(root, workstreamId, document, objectMapper)) {
            throw new IllegalArgumentException("validated task-contract proposal lineage is required");
        }
        var digest = sha256(sidecar);
        var proposalId = document.nodeInstanceId() + ":" + digest.substring(0, 16);
        var reference = new TaskContractProposalReference(
                SCHEMA_VERSION,
                proposalId,
                workstreamId,
                document.nodeId(),
                document.nodeInstanceId(),
                root.relativize(sidecar).toString(),
                digest
        );
        var referencePath = root.resolve(".agent/workstreams")
                .resolve(workstreamId)
                .resolve("artifacts/task-contract-proposals")
                .resolve(safeFileName(document.nodeInstanceId()) + "-" + digest.substring(0, 16) + ".ref.json")
                .normalize();
        Files.createDirectories(referencePath.getParent());
        objectMapper.writerWithDefaultPrettyPrinter().writeValue(referencePath.toFile(), reference);
        return new Published(reference, root.relativize(referencePath).toString());
    }

    private static boolean validProposalSource(
            Path root,
            String workstreamId,
            AgentOutputContractDocument document,
            ObjectMapper objectMapper
    ) {
        if (document.repositoryFactBinding() != null
                && !RepositoryFactBinding.verifyReference(
                        root,
                        workstreamId,
                        document.repositoryFactBinding(),
                        document.nodeInstanceId(),
                        document.runId(),
                        objectMapper).valid()) {
            return false;
        }
        if ("task_contract_proposal".equals(document.sourceArtifactType())) {
            return document.proposalDerivation() == null;
        }
        if (!"task_contract_revision_patch".equals(document.sourceArtifactType())) {
            return false;
        }
        var derivation = document.proposalDerivation();
        if (derivation == null
                || !derivation.validFor(derivation.baseProposalReference(), document.sourceOutputRef())) {
            return false;
        }
        try {
            return derivation.baseProposalReference()
                    .resolveArtifact(root, workstreamId, objectMapper).isPresent();
        } catch (RuntimeException ignored) {
            return false;
        }
    }

    static Optional<TaskContractProposalReference> readVerified(
            Path workspaceRoot,
            String expectedWorkstreamId,
            String referenceRef,
            ObjectMapper objectMapper
    ) {
        try {
            var root = workspaceRoot.toAbsolutePath().normalize();
            var referencePath = root.resolve(referenceRef).normalize();
            if (!referencePath.startsWith(root) || !Files.isRegularFile(referencePath)) {
                return Optional.empty();
            }
            var reference = objectMapper.readValue(referencePath.toFile(), TaskContractProposalReference.class);
            if (!expectedWorkstreamId.equals(reference.workstreamId())) {
                return Optional.empty();
            }
            if (reference.resolveArtifact(root, expectedWorkstreamId, objectMapper).isEmpty()) {
                return Optional.empty();
            }
            return Optional.of(reference);
        } catch (Exception ignored) {
            return Optional.empty();
        }
    }

    static Optional<Resolved> resolveFromRefs(
            Path workspaceRoot,
            String expectedWorkstreamId,
            Iterable<String> refs,
            ObjectMapper objectMapper
    ) {
        Resolved resolved = null;
        for (var ref : refs) {
            var candidate = readVerified(workspaceRoot, expectedWorkstreamId, ref, objectMapper);
            if (candidate.isEmpty()) {
                continue;
            }
            if (resolved != null && !resolved.reference().proposalId().equals(candidate.get().proposalId())) {
                return Optional.empty();
            }
            resolved = new Resolved(candidate.get(), ref);
        }
        return Optional.ofNullable(resolved);
    }

    public static Optional<ResolvedProposal> resolveProposalFromRefs(
            Path workspaceRoot,
            String expectedWorkstreamId,
            Iterable<String> refs,
            ObjectMapper objectMapper
    ) {
        var resolved = resolveFromRefs(workspaceRoot, expectedWorkstreamId, refs, objectMapper);
        if (resolved.isEmpty()) {
            return Optional.empty();
        }
        var reference = resolved.get().reference();
        var proposalArtifact = reference.resolveProposalArtifact(
                workspaceRoot, expectedWorkstreamId, objectMapper);
        if (proposalArtifact.isEmpty()) {
            return Optional.empty();
        }
        return Optional.of(new ResolvedProposal(
                reference,
                resolved.get().referenceRef(),
                proposalArtifact.get().path(),
                proposalArtifact.get().proposal()));
    }

    /** Resolves the exact proposal carried by this verified immutable reference. */
    Optional<TaskContractProposal> resolveVerifiedProposal(
            Path workspaceRoot,
            String expectedWorkstreamId,
            ObjectMapper objectMapper
    ) {
        return resolveProposalArtifact(workspaceRoot, expectedWorkstreamId, objectMapper)
                .map(ProposalArtifact::proposal);
    }

    private Optional<ProposalArtifact> resolveProposalArtifact(
            Path workspaceRoot,
            String expectedWorkstreamId,
            ObjectMapper objectMapper
    ) {
        var artifactPath = resolveArtifact(workspaceRoot, expectedWorkstreamId, objectMapper);
        if (artifactPath.isEmpty()) {
            return Optional.empty();
        }
        var document = AgentOutputContractDocument.read(artifactPath.get(), objectMapper);
        if (document.isEmpty()
                || document.get().taskContractProposal() == null
                || document.get().taskContractProposal().schemaVersion() != TaskContractProposal.SCHEMA_VERSION) {
            return Optional.empty();
        }
        return Optional.of(new ProposalArtifact(artifactPath.get(), document.get().taskContractProposal()));
    }

    Optional<Path> resolveArtifact(Path workspaceRoot, String expectedWorkstreamId, ObjectMapper objectMapper) {
        try {
            var root = workspaceRoot.toAbsolutePath().normalize();
            if (!expectedWorkstreamId.equals(workstreamId)) {
                return Optional.empty();
            }
            var artifactPath = root.resolve(artifactRef).normalize();
            if (!artifactPath.startsWith(root)
                    || !Files.isRegularFile(artifactPath)
                    || !sha256.equals(sha256(artifactPath))) {
                return Optional.empty();
            }
            var document = AgentOutputContractDocument.read(artifactPath, objectMapper);
            if (document.isEmpty()
                    || !document.get().hasValidatedLineage(expectedWorkstreamId, root, artifactPath)
                    || !producerNodeId.equals(document.get().nodeId())
                    || !producerNodeInstanceId.equals(document.get().nodeInstanceId())
                    || !validProposalSource(root, expectedWorkstreamId, document.get(), objectMapper)) {
                return Optional.empty();
            }
            return Optional.of(artifactPath);
        } catch (Exception ignored) {
            return Optional.empty();
        }
    }

    Map<String, Object> toMap() {
        var map = new LinkedHashMap<String, Object>();
        map.put("schema_version", schemaVersion);
        map.put("proposal_id", proposalId);
        map.put("workstream_id", workstreamId);
        map.put("producer_node_id", producerNodeId);
        map.put("producer_node_instance_id", producerNodeInstanceId);
        map.put("artifact_ref", artifactRef);
        map.put("sha256", sha256);
        return Map.copyOf(map);
    }

    static Optional<TaskContractProposalReference> fromMap(Map<String, Object> map) {
        try {
            return Optional.of(new TaskContractProposalReference(
                    integer(map.get("schema_version")),
                    text(map.get("proposal_id")),
                    text(map.get("workstream_id")),
                    text(map.get("producer_node_id")),
                    text(map.get("producer_node_instance_id")),
                    text(map.get("artifact_ref")),
                    text(map.get("sha256"))
            ));
        } catch (RuntimeException ignored) {
            return Optional.empty();
        }
    }

    private static String sha256(Path path) throws Exception {
        return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(path)));
    }

    private static String safeFileName(String value) {
        return value.replaceAll("[^A-Za-z0-9._-]", "_");
    }

    private static int integer(Object value) {
        return value instanceof Number number ? number.intValue() : Integer.parseInt(text(value));
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }

    private static void requireText(String value, String field) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(field + " is required");
        }
    }

    record Published(TaskContractProposalReference reference, String referenceRef) {}

    record Resolved(TaskContractProposalReference reference, String referenceRef) {}

    public record ResolvedProposal(
            TaskContractProposalReference reference,
            String referenceRef,
            Path artifactPath,
            TaskContractProposal proposal
    ) {}

    private record ProposalArtifact(Path path, TaskContractProposal proposal) {}
}

package dev.dual.runtime.handler;

enum OverflowPolicy {
    FAIL,
    PRESERVE_FULL,
    DEGRADE,
    DROP_OPTIONAL
}

package dev.dual.runtime.handler;

import dev.dual.core.workflow.NodeResult;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class ReportGenerateFinalHandler implements TaskHandler {
    private static final int MAX_SNIPPET_CHARS = 4_000;
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();

    @Override
    public String type() {
        return "report.generate_final";
    }

    @Override
    public NodeResult execute(TaskContext context) throws IOException {
        var qualifiedContract = qualifiedContract(context);
        if (qualifiedContract.failure() != null) {
            return qualificationFailure(qualifiedContract.failure());
        }
        var evidence = CompletionEvidenceLineageResolver.resolveForReport(
                context.workspaceRoot(), context.workstreamId(), context.instance());
        if (evidence.status() != CompletionEvidenceLineageResolver.Status.AVAILABLE) {
            var result = new LinkedHashMap<String, Object>();
            result.put("failure_code", evidence.failureCode());
            result.put("error", evidence.detail());
            if (evidence.goal() != null) {
                result.put("goal_node_instance_id", evidence.goal().nodeInstanceId());
                result.put("goal_iteration_id", evidence.goal().iterationId());
            }
            return new NodeResult(
                    evidence.failureCode(),
                    dev.dual.core.workflow.NodeStatus.FAILED,
                    List.of(),
                    result,
                    evidence.detail());
        }
        var workstreamDir = context.workspaceRoot()
                .resolve(".agent")
                .resolve("workstreams")
                .resolve(context.workstreamId());
        var reportsDir = workstreamDir.resolve("reports");
        Files.createDirectories(reportsDir);

        var iterationId = context.instance().iterationId();
        var reportPath = reportsDir.resolve(iterationId + "-final-report.md");
        var latestPath = reportsDir.resolve("latest-final-report.md");
        var markdown = renderReport(context, workstreamDir, evidence, qualifiedContract.contract());
        Files.writeString(reportPath, markdown, StandardCharsets.UTF_8);
        Files.writeString(latestPath, markdown, StandardCharsets.UTF_8);

        var reportRef = toWorkspaceRef(context.workspaceRoot(), reportPath);
        var latestRef = toWorkspaceRef(context.workspaceRoot(), latestPath);
        var result = new LinkedHashMap<String, Object>();
        result.put("report_path", reportRef);
        result.put("latest_report_path", latestRef);
        result.put("iteration_id", iterationId);
        result.put("generated_at", Instant.now().toString());
        return NodeResult.completed("completed", List.of(reportRef, latestRef), result);
    }

    private static String renderReport(
            TaskContext context,
            Path workstreamDir,
            CompletionEvidenceLineageResolver.Resolution evidence,
            TaskContractProjectionVerifier.QualifiedTaskContract qualifiedContract
    ) throws IOException {
        var builder = new StringBuilder();
        builder.append("# Dual Final Report\n\n");
        builder.append("- Workstream: ").append(context.workstreamId()).append("\n");
        builder.append("- Iteration: ").append(context.instance().iterationId()).append("\n");
        builder.append("- Generated At: ").append(Instant.now()).append("\n");
        builder.append("- Report Scope: pre-human-delivery verification snapshot\n");
        builder.append("- Excludes: subsequent human acceptance, delivery apply, and delivery commit status\n");
        builder.append("- Ledger: ").append(toDisplayRef(workstreamDir)).append("\n\n");

        builder.append("## User Request\n\n");
        builder.append(readOrDefault(workstreamDir.resolve("requirement.md"), "(requirement.md not found)")).append("\n\n");

        builder.append("## TaskContract\n\n");
        var legacyContract = qualifiedContract == null
                ? TaskContractProjectionVerifier.readLegacyProjection(
                        context.workspaceRoot(), context.workstreamId()).projection().orElse(null)
                : null;
        appendTaskContractSection(builder, qualifiedContract, legacyContract);
        appendRequirementResolutionSection(builder, qualifiedContract, legacyContract);

        appendFailureClassificationSection(builder, workstreamDir);

        builder.append("## Verification Evidence\n\n");
        appendVerificationEvidence(builder, evidence);

        builder.append("## Acceptance Summary\n\n");
        appendContractSummary(builder, evidence.acceptance());

        builder.append("## Developer Self-Test Summary\n\n");
        appendContractSummary(builder, evidence.selfTest());

        builder.append("## Git Evidence\n\n");
        appendGitEvidence(builder, workstreamDir);

        builder.append("## Selected Typed Outputs\n\n");
        appendSelectedOutputs(builder, evidence);

        builder.append("## Run Artifacts\n\n");
        builder.append("- Workflow current: ").append(toDisplayRef(workstreamDir.resolve("workflow/current.json"))).append("\n");
        builder.append("- Events: ").append(toDisplayRef(workstreamDir.resolve("events.jsonl"))).append("\n");
        builder.append("- Runs: ").append(toDisplayRef(workstreamDir.resolve("runs"))).append("\n");
        builder.append("- Context: ").append(toDisplayRef(workstreamDir.resolve("context"))).append("\n");
        builder.append("- Git evidence: ").append(toDisplayRef(workstreamDir.resolve("artifacts/git-evidence"))).append("\n");
        return builder.toString();
    }

    private static void appendTaskContractSection(
            StringBuilder builder,
            TaskContractProjectionVerifier.QualifiedTaskContract qualifiedContract,
            TaskContractProjectionVerifier.LegacyProjection legacyContract
    ) {
        if (qualifiedContract == null && (legacyContract == null || legacyContract.contract() == null)) {
            builder.append("(no TaskContract — legacy workflow)\n\n");
            return;
        }
        var contract = qualifiedContract == null
                ? legacyContract.contract()
                : qualifiedContract.contract();
        builder.append("- **Contract ID:** ").append(contract.id()).append("\n");
        builder.append("- **Objective:** ").append(contract.objective()).append("\n");
        builder.append("- **Status:** ").append(contract.status()).append("\n");
        if (qualifiedContract != null) {
            builder.append("- **Contract Ref:** ").append(qualifiedContract.contractRef()).append("\n");
            builder.append("- **Contract SHA-256:** ").append(qualifiedContract.sha256()).append("\n");
            builder.append("- **Approval Gate:** ").append(qualifiedContract.approvalGateRef()).append("\n");
        } else {
            builder.append("- **Authority:** legacy unqualified projection\n");
        }
        builder.append("- **Scope Included:** ").append(contract.scope().included().isEmpty()
                ? "(none)"
                : contract.scope().included().stream()
                        .map(item -> item.operation() + ": " + item.path())
                        .collect(java.util.stream.Collectors.joining(", "))).append("\n");
        builder.append("- **Scope Excluded:** ").append(contract.scope().excluded().isEmpty() ? "(none)" : String.join(", ", contract.scope().excluded())).append("\n");
        builder.append("- **Acceptance Criteria:** ").append(contract.acceptanceCriteria().size()).append(" items").append("\n");
        builder.append("- **Non-Goals:** ").append(contract.nonGoals().isEmpty() ? "(none)" : String.join(", ", contract.nonGoals())).append("\n");
        builder.append("- **Contract Gaps Found:** 0\n");
        builder.append("- **Out-of-scope Changes:** 0\n\n");
    }

    private static void appendRequirementResolutionSection(
            StringBuilder builder,
            TaskContractProjectionVerifier.QualifiedTaskContract qualifiedContract,
            TaskContractProjectionVerifier.LegacyProjection legacyContract
    ) {
        if (qualifiedContract == null
                && (legacyContract == null || legacyContract.resolutionDocument().isEmpty())) {
            return;
        }
        builder.append("## Requirement Resolution\n\n");
        builder.append("- Source: ").append(qualifiedContract == null
                ? legacyContract.resolutionRef()
                : qualifiedContract.resolutionRef()).append("\n");
        if (qualifiedContract != null) {
            builder.append("- SHA-256: ").append(qualifiedContract.resolutionSha256()).append("\n");
        } else {
            builder.append("- Authority: requirement history only\n");
        }
        var json = qualifiedContract == null
                ? OBJECT_MAPPER.valueToTree(legacyContract.resolutionDocument())
                : OBJECT_MAPPER.valueToTree(qualifiedContract.resolutionDocument());
        appendJsonField(builder, "Decision", json.path("decision").asText(""));
        appendJsonField(builder, "Approved By", json.path("approved_by").asText(""));
        appendJsonField(builder, "Gate Ref", json.path("gate_ref").asText(""));
        appendResolvedQuestions(builder, json.path("resolved_questions"));
        appendJsonList(builder, "Assumptions", json.path("assumptions"));
        appendJsonList(builder, "Accepted Risks", json.path("accepted_risks"));
        builder.append("\n");
    }

    private static QualifiedContract qualifiedContract(TaskContext context) {
        if (!AgentRunGovernanceContext.requiresApprovedTaskContract(context)) {
            return new QualifiedContract(null, null);
        }
        var resolved = TaskContractProjectionVerifier.resolve(context.workspaceRoot(), context.workstreamId());
        if (resolved.failure() != null) {
            return new QualifiedContract(null, resolved.failure());
        }
        return resolved.qualified()
                .map(value -> new QualifiedContract(value, null))
                .orElseGet(() -> new QualifiedContract(null, TaskContractProjectionVerifier.Failure.of(
                        "APPROVAL_BINDING_MISSING", "final report requires an approved task contract")));
    }

    private static NodeResult qualificationFailure(TaskContractProjectionVerifier.Failure failure) {
        return new NodeResult(
                TaskContractProjectionVerifier.FAILURE_OUTCOME,
                dev.dual.core.workflow.NodeStatus.FAILED,
                List.of(),
                Map.of(
                        "failure_code", TaskContractProjectionVerifier.FAILURE_OUTCOME,
                        "reason", failure.reason(),
                        "error", failure.message()),
                failure.message());
    }

    private record QualifiedContract(
            TaskContractProjectionVerifier.QualifiedTaskContract contract,
            TaskContractProjectionVerifier.Failure failure
    ) {
    }

    private static void appendResolvedQuestions(StringBuilder builder, JsonNode node) {
        if (node == null || !node.isArray() || node.isEmpty()) {
            return;
        }
        builder.append("- **Resolved Questions:**\n");
        for (var item : node) {
            var question = item.path("question").asText("");
            var resolution = item.path("resolution").asText("");
            var source = item.path("source").asText("");
            if (!question.isBlank()) {
                builder.append("  - ").append(question);
                if (!resolution.isBlank()) {
                    builder.append(" -> ").append(resolution);
                }
                if (!source.isBlank()) {
                    builder.append(" (").append(source).append(")");
                }
                builder.append("\n");
            }
        }
    }

    private static void appendFailureClassificationSection(StringBuilder builder, Path workstreamDir) throws IOException {
        var classificationPath = workstreamDir.resolve("artifacts/failure-classification.json");
        if (!Files.exists(classificationPath)) {
            builder.append("## Failure Classification\n\n");
            builder.append("(no failure classification — accepted or legacy workflow)\n\n");
            return;
        }
        var mapper = new com.fasterxml.jackson.databind.ObjectMapper()
                .registerModule(new com.fasterxml.jackson.datatype.jsr310.JavaTimeModule());
        try {
            var tree = mapper.readTree(classificationPath.toFile());
            var reviewDecision = tree.path("review_decision").asText("(unknown)");
            if ("ACCEPT_WITH_NOTES".equals(reviewDecision)) {
                builder.append("## Acceptance Notes Classification\n\n");
            } else {
                builder.append("## Failure Classification\n\n");
            }
            builder.append("- **Category:** ").append(tree.path("category").asText("(unknown)")).append("\n");
            builder.append("- **Reasoning:** ").append(tree.path("reasoning").asText("(none)")).append("\n");
            builder.append("- **Suggested Action:** ").append(tree.path("suggested_action").asText("(none)")).append("\n");
            builder.append("- **Matched Rule:** ").append(tree.path("matched_rule").asInt(0)).append("\n");
            builder.append("- **Review Decision:** ").append(reviewDecision).append("\n");
            builder.append("- **Source:** ").append(tree.path("source").asText("(unknown)")).append("\n");
            builder.append("- **Classified At:** ").append(tree.path("classified_at").asText("(unknown)")).append("\n");
            var evidence = tree.path("evidence");
            if (evidence.isArray() && !evidence.isEmpty()) {
                builder.append("- **Evidence:**\n");
                for (var item : evidence) {
                    builder.append("  - ").append(item.asText()).append("\n");
                }
            }
            builder.append("\n");
        } catch (Exception e) {
            builder.append("## Failure Classification\n\n");
            builder.append("(error reading failure classification: ").append(e.getMessage()).append(")\n\n");
        }
    }

    private static void appendVerificationEvidence(
            StringBuilder builder,
            CompletionEvidenceLineageResolver.Resolution evidence
    ) throws IOException {
        appendContractEvidence(builder, "Developer Self-Test Evidence", evidence.selfTest().path());
        appendContractEvidence(builder, "Codex Acceptance Evidence", evidence.acceptance().path());
    }

    private static void appendContractEvidence(StringBuilder builder, String title, Path sidecar) throws IOException {
        builder.append("### ").append(title).append("\n\n");
        builder.append("- Source: ").append(toDisplayRef(sidecar)).append("\n");
        try {
            var json = OBJECT_MAPPER.readTree(sidecar.toFile());
            appendJsonField(builder, "Decision", json.path("decision").asText(""));
            appendJsonField(builder, "Summary", json.path("summary").asText(""));
            appendJsonField(builder, "Verification Summary", json.path("verification_summary").asText(""));
            appendJsonList(builder, "Checks Run", json.path("checks_run"));
            appendJsonList(builder, "Checks Skipped", json.path("checks_skipped"));
            appendJsonList(builder, "Evidence", json.path("evidence"));
            appendJsonList(builder, "Missing Evidence", json.path("missing_evidence"));
            appendJsonList(builder, "Acceptance Notes", json.path("acceptance_notes"));
        } catch (Exception e) {
            builder.append("- Error reading structured evidence: ").append(e.getMessage()).append("\n");
        }
        builder.append("\n");
    }

    private static void appendJsonField(StringBuilder builder, String label, String value) {
        if (value == null || value.isBlank()) {
            return;
        }
        builder.append("- **").append(label).append(":** ").append(value).append("\n");
    }

    private static void appendJsonList(StringBuilder builder, String label, JsonNode node) {
        if (node == null || !node.isArray() || node.isEmpty()) {
            return;
        }
        builder.append("- **").append(label).append(":**\n");
        for (var item : node) {
            var text = item.asText("");
            if (!text.isBlank()) {
                builder.append("  - ").append(text).append("\n");
            }
        }
    }

    private static void appendContractSummary(
            StringBuilder builder,
            CompletionEvidenceLineageResolver.Evidence evidence
    ) throws IOException {
        var sidecar = evidence.path();
        builder.append("- Source: ").append(evidence.ref()).append("\n");
        try {
            var json = OBJECT_MAPPER.readTree(sidecar.toFile());
            appendJsonField(builder, "Node", json.path("node_id").asText(""));
            appendJsonField(builder, "Decision", json.path("decision").asText(""));
            appendJsonField(builder, "Stage Outcome", json.path("stage_outcome").asText(""));
            appendJsonField(builder, "Summary", json.path("summary").asText(""));
            appendJsonField(builder, "Verification Summary", json.path("verification_summary").asText(""));
            appendJsonList(builder, "Evidence", json.path("evidence"));
            appendJsonList(builder, "Missing Evidence", json.path("missing_evidence"));
            appendJsonList(builder, "Must Fix", json.path("must_fix"));
            appendJsonList(builder, "Open Risks", json.path("open_risks"));
            appendJsonList(builder, "Acceptance Notes", json.path("acceptance_notes"));
        } catch (Exception e) {
            builder.append("- Error reading structured summary: ").append(e.getMessage()).append("\n");
        }
        builder.append("\n");
    }

    private static void appendGitEvidence(StringBuilder builder, Path workstreamDir) throws IOException {
        var evidenceDir = workstreamDir.resolve("artifacts/git-evidence");
        if (!Files.exists(evidenceDir)) {
            builder.append("(git evidence not generated)\n\n");
            return;
        }
        for (String fileName : List.of(
                "git-evidence.json",
                "git-status-short.txt",
                "diff.stat",
                "changed-files.txt",
                "hygiene-warnings.txt",
                "diff.patch"
        )) {
            var path = evidenceDir.resolve(fileName);
            if (Files.exists(path)) {
                builder.append("- ").append(fileName).append(": ").append(toDisplayRef(path)).append("\n");
            }
        }
        builder.append("\n");
        var hygieneWarnings = evidenceDir.resolve("hygiene-warnings.txt");
        if (Files.exists(hygieneWarnings) && !Files.readString(hygieneWarnings, StandardCharsets.UTF_8).isBlank()) {
            builder.append("## Repository Hygiene Warnings\n\n");
            builder.append("```text\n");
            builder.append(snippet(hygieneWarnings, MAX_SNIPPET_CHARS));
            builder.append("\n```\n\n");
        }
        var evidenceJson = evidenceDir.resolve("git-evidence.json");
        if (Files.exists(evidenceJson)) {
            builder.append("```json\n");
            builder.append(snippet(evidenceJson, MAX_SNIPPET_CHARS));
            builder.append("\n```\n\n");
        }
    }

    private static void appendSelectedOutputs(
            StringBuilder builder,
            CompletionEvidenceLineageResolver.Resolution evidence
    ) {
        for (var selected : List.of(evidence.selfTest(), evidence.acceptance())) {
            builder.append("- Source output: ").append(selected.document().sourceOutputRef()).append("\n");
            builder.append("  Sidecar: ").append(selected.ref()).append("\n");
        }
        builder.append("\n");
    }

    private static String readOrDefault(Path path, String fallback) throws IOException {
        if (!Files.exists(path)) {
            return fallback;
        }
        return Files.readString(path, StandardCharsets.UTF_8).stripTrailing();
    }

    private static String snippet(Path path, int maxChars) throws IOException {
        var content = Files.readString(path, StandardCharsets.UTF_8).stripTrailing();
        if (content.length() <= maxChars) {
            return content;
        }
        return content.substring(0, maxChars).stripTrailing()
                + "\n\n[truncated; read the full artifact at " + path.toAbsolutePath().normalize() + "]";
    }

    private static String toDisplayRef(Path path) {
        return path.toAbsolutePath().normalize().toString();
    }

    private static String toWorkspaceRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize().relativize(path.toAbsolutePath().normalize()).toString();
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.annotation.JsonProperty;

import java.time.Instant;
import java.util.List;

record ContractResolutionDocument(
        @JsonProperty("schema_version") int schemaVersion,
        String decision,
        @JsonProperty("resolved_questions") List<ResolvedQuestion> resolvedQuestions,
        List<String> assumptions,
        @JsonProperty("accepted_risks") List<String> acceptedRisks,
        @JsonProperty("gate_ref") String gateRef,
        @JsonProperty("approved_by") String approvedBy,
        @JsonProperty("created_at") Instant createdAt
) {
    ContractResolutionDocument {
        resolvedQuestions = resolvedQuestions == null ? List.of() : List.copyOf(resolvedQuestions);
        assumptions = assumptions == null ? List.of() : List.copyOf(assumptions);
        acceptedRisks = acceptedRisks == null ? List.of() : List.copyOf(acceptedRisks);
    }

    record ResolvedQuestion(
            String question,
            String resolution,
            String source
    ) {}
}

package dev.dual.runtime.handler;

import dev.dual.core.arbitration.FailureCategory;
import dev.dual.core.arbitration.FailureClassification;

import java.time.Instant;
import java.util.List;
import java.util.Objects;

/** Consumes the canonical category only after shared acceptance semantic validation. */
public final class FailureArbiter {
    public FailureClassification classify(FailureCategory category, List<String> evidence) {
        Objects.requireNonNull(category, "validated acceptance category is required");
        var action = switch (category) {
            case CONTRACT_GAP, CONTRACT_AMBIGUITY -> "Revise the proposal and obtain new approvals before compiling";
            case IMPLEMENTATION_BUG -> "Repair within the approved contract, then run self-test";
            case VERIFICATION_INSUFFICIENT -> "Collect existing verification evidence in self-test";
            case CONTEXT_INSUFFICIENT, TOOL_LIMITATION ->
                    "Obtain human disposition of the missing prerequisites: collect evidence or explicitly authorize repair";
            case REVIEW_NOISE -> "Re-run acceptance review";
        };
        return new FailureClassification(category, "Validated explicit acceptance category: " + category,
                action, "deterministic", Instant.now(), 0, "REJECT", List.copyOf(evidence));
    }
}

