package dev.dual.runtime.handler;

import dev.dual.core.contract.TaskContract;
import dev.dual.core.contract.TaskContractValidator;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;

record ChangeScopeEvaluation(
        int schemaVersion,
        Status status,
        List<ActualChange> actualChanges,
        List<String> matchedPaths,
        List<TaskContract.ScopeEntry> missingDeclared,
        List<Violation> violations,
        String error
) {
    ChangeScopeEvaluation {
        actualChanges = List.copyOf(actualChanges == null ? List.of() : actualChanges);
        matchedPaths = List.copyOf(matchedPaths == null ? List.of() : matchedPaths);
        missingDeclared = List.copyOf(missingDeclared == null ? List.of() : missingDeclared);
        violations = List.copyOf(violations == null ? List.of() : violations);
    }

    boolean passed() {
        return status == Status.PASS;
    }

    static ChangeScopeEvaluation unavailable(String error) {
        return new ChangeScopeEvaluation(1, Status.UNAVAILABLE, List.of(), List.of(), List.of(), List.of(), error);
    }

    enum Status {
        PASS,
        FAIL,
        UNAVAILABLE
    }

    enum ActualOperation {
        CREATE,
        MODIFY,
        DELETE,
        RENAME,
        UNKNOWN
    }

    record ActualChange(
            String path,
            ActualOperation operation,
            String previousPath,
            String rawStatus
    ) {}

    record Violation(
            String code,
            String path,
            TaskContract.ScopeOperation declaredOperation,
            ActualOperation actualOperation,
            String previousPath
    ) {}
}

final class ChangeScopeEvaluator {
    private ChangeScopeEvaluator() {}

    static List<ChangeScopeEvaluation.ActualChange> parseNameStatus(String nameStatus) {
        return parseNameStatus(0, nameStatus);
    }

    static List<ChangeScopeEvaluation.ActualChange> parseNameStatus(int exitCode, String nameStatus) {
        if (exitCode != 0) {
            throw new IllegalArgumentException("git name-status command failed with exit code " + exitCode);
        }
        if (nameStatus == null || nameStatus.isBlank()) {
            return List.of();
        }
        var fields = nameStatus.split(String.valueOf('\0'), -1);
        if (fields.length < 2 || !fields[fields.length - 1].isEmpty()) {
            throw new IllegalArgumentException("git name-status output is not NUL terminated");
        }
        var changes = new ArrayList<ChangeScopeEvaluation.ActualChange>();
        for (var index = 0; index < fields.length - 1;) {
            var rawStatus = fields[index++].trim();
            if (rawStatus.isEmpty()) {
                throw new IllegalArgumentException("git name-status output contains an empty status");
            }
            var code = rawStatus.isEmpty() ? '\0' : rawStatus.charAt(0);
            var operation = switch (code) {
                case 'A' -> ChangeScopeEvaluation.ActualOperation.CREATE;
                case 'M' -> ChangeScopeEvaluation.ActualOperation.MODIFY;
                case 'D' -> ChangeScopeEvaluation.ActualOperation.DELETE;
                case 'R' -> ChangeScopeEvaluation.ActualOperation.RENAME;
                default -> ChangeScopeEvaluation.ActualOperation.UNKNOWN;
            };
            var twoPathStatus = code == 'R' || code == 'C';
            var requiredFields = twoPathStatus ? 2 : 1;
            if (index + requiredFields > fields.length - 1) {
                throw new IllegalArgumentException("git name-status output is truncated for status " + rawStatus);
            }
            var previousPath = twoPathStatus ? fields[index++] : null;
            var path = fields[index++];
            if (path.isEmpty() || (twoPathStatus && previousPath.isEmpty())) {
                throw new IllegalArgumentException("git name-status output contains an empty path");
            }
            changes.add(new ChangeScopeEvaluation.ActualChange(path, operation, previousPath, rawStatus));
        }
        return List.copyOf(changes);
    }

    static ChangeScopeEvaluation evaluate(
            TaskContract contract,
            List<ChangeScopeEvaluation.ActualChange> actualChanges
    ) {
        var declaredByPath = new LinkedHashMap<String, TaskContract.ScopeEntry>();
        for (var entry : contract.scope().included()) {
            declaredByPath.put(entry.path(), entry);
        }

        var matchedPaths = new ArrayList<String>();
        var observedPaths = new LinkedHashSet<String>();
        var violations = new ArrayList<ChangeScopeEvaluation.Violation>();
        for (var actual : actualChanges) {
            observedPaths.add(actual.path());
            var declared = declaredByPath.get(actual.path());
            if (!TaskContractValidator.isCanonicalPath(actual.path())) {
                violations.add(violation("INVALID_ACTUAL_PATH", actual, declared));
                continue;
            }
            if (actual.operation() == ChangeScopeEvaluation.ActualOperation.DELETE
                    || actual.operation() == ChangeScopeEvaluation.ActualOperation.RENAME
                    || actual.operation() == ChangeScopeEvaluation.ActualOperation.UNKNOWN) {
                violations.add(violation("UNSUPPORTED_ACTUAL_OPERATION", actual, declared));
                continue;
            }
            if (declared == null) {
                violations.add(violation("UNEXPECTED_ACTUAL_CHANGE", actual, null));
                continue;
            }
            if (expectedActualOperation(declared.operation()) != actual.operation()) {
                violations.add(violation("OPERATION_MISMATCH", actual, declared));
                continue;
            }
            matchedPaths.add(actual.path());
        }

        var missingDeclared = contract.scope().included().stream()
                .filter(entry -> !observedPaths.contains(entry.path()))
                .toList();
        return new ChangeScopeEvaluation(
                1,
                violations.isEmpty() ? ChangeScopeEvaluation.Status.PASS : ChangeScopeEvaluation.Status.FAIL,
                actualChanges,
                matchedPaths,
                missingDeclared,
                violations,
                null
        );
    }

    private static ChangeScopeEvaluation.ActualOperation expectedActualOperation(
            TaskContract.ScopeOperation operation
    ) {
        return switch (operation) {
            case CREATE -> ChangeScopeEvaluation.ActualOperation.CREATE;
            case MODIFY -> ChangeScopeEvaluation.ActualOperation.MODIFY;
        };
    }

    private static ChangeScopeEvaluation.Violation violation(
            String code,
            ChangeScopeEvaluation.ActualChange actual,
            TaskContract.ScopeEntry declared
    ) {
        return new ChangeScopeEvaluation.Violation(
                code,
                actual.path(),
                declared == null ? null : declared.operation(),
                actual.operation(),
                actual.previousPath()
        );
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Read model for validated agent output sidecars.
 *
 * Consumers should use this index instead of walking runs and re-parsing raw
 * maps independently. It keeps ordering and structured-field interpretation in
 * one place while preserving the file ledger as the source of truth.
 */
public final class AgentEvidenceIndex {
    private final List<Entry> entries;

    private AgentEvidenceIndex(List<Entry> entries) {
        this.entries = List.copyOf(entries);
    }

    static AgentEvidenceIndex fromRefs(
            Path workspaceRoot,
            String workstreamId,
            List<String> refs,
            ObjectMapper objectMapper
    ) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        var entries = refs.stream()
                .map(ref -> sidecarPathForRef(root, ref))
                .flatMap(Optional::stream)
                .distinct()
                .map(path -> readEntry(root, workstreamId, path, objectMapper))
                .flatMap(Optional::stream)
                .sorted(Entry.ORDER.reversed())
                .toList();
        return new AgentEvidenceIndex(entries);
    }

    static Optional<Entry> latestFromRefs(
            Path workspaceRoot,
            String workstreamId,
            List<String> refs,
            ObjectMapper objectMapper
    ) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        return refs.stream()
                .map(ref -> sidecarPathForRef(root, ref))
                .flatMap(Optional::stream)
                .map(path -> readEntry(root, workstreamId, path, objectMapper))
                .flatMap(Optional::stream)
                .sorted(Entry.ORDER.reversed())
                .findFirst();
    }

    static DecisionRead latestDecisionFromRefs(
            Path workspaceRoot,
            String workstreamId,
            List<String> refs,
            ObjectMapper objectMapper
    ) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        for (int i = refs.size() - 1; i >= 0; i--) {
            var path = sidecarPathForRef(root, refs.get(i));
            if (path.isEmpty()) {
                continue;
            }
            var read = readValidatedEntry(root, workstreamId, path.get(), objectMapper);
            if (read.entry() == null) {
                return DecisionRead.invalid(read.errorCode(), read.message(), path.get().toString());
            }
            if (!read.entry().document().hasDecision()) {
                return DecisionRead.invalid(
                        "CONTRACT_SIDECAR_MISSING_DECISION",
                        "Contract sidecar is missing required decision: " + path.get().getFileName(),
                        path.get().toString()
                );
            }
            return DecisionRead.valid(read.entry(), path.get().toString());
        }
        return DecisionRead.notFound();
    }

    public static Optional<AgentOutputContractDocument> validatedDocument(
            Path workspaceRoot,
            String workstreamId,
            String ref,
            ObjectMapper objectMapper
    ) {
        var index = fromRefs(workspaceRoot, workstreamId, List.of(ref), objectMapper);
        return index.entryForRef(workspaceRoot, ref).map(Entry::document);
    }

    List<Entry> recent(int maxItems) {
        if (maxItems <= 0) {
            return List.of();
        }
        return entries.stream().limit(maxItems).toList();
    }

    Optional<Entry> latest() {
        return entries.stream().findFirst();
    }

    Optional<Entry> entryForRef(Path workspaceRoot, String ref) {
        var normalizedRef = normalizeRef(ref);
        return entries.stream()
                .filter(entry -> normalizedRef.equals(normalizeRef(entry.document().sourceOutputRef()))
                        || normalizedRef.equals(normalizeRef(relativeRef(workspaceRoot, entry.path()))))
                .findFirst();
    }

    boolean isValidatedPlanProjectionRef(Path workspaceRoot, String ref) {
        var normalizedRef = normalizeRef(ref);
        return entries.stream()
                .filter(entry -> entry.document().planArtifact() != null)
                .map(entry -> workspaceRoot.resolve(entry.document().sourceOutputRef()).normalize())
                .map(PlanArtifactSidecar::pathFor)
                .map(path -> relativeRef(workspaceRoot, path))
                .map(AgentEvidenceIndex::normalizeRef)
                .anyMatch(normalizedRef::equals);
    }

    List<String> validatedSidecarRefs(Path workspaceRoot) {
        var root = workspaceRoot.toAbsolutePath().normalize();
        return entries.stream()
                .map(Entry::path)
                .map(root::relativize)
                .map(Path::toString)
                .toList();
    }

    boolean contains(String nodeId, String sourceArtifactType, String decision) {
        return entries.stream().map(Entry::document).anyMatch(document ->
                nodeId.equals(document.nodeId())
                        && sourceArtifactType.equals(document.sourceArtifactType())
                        && decision.equals(document.decision())
                        && document.hasRequiredTypedPayload());
    }

    private static Optional<Path> sidecarPathForRef(Path workspaceRoot, String ref) {
        if (ref == null || ref.isBlank() || ref.startsWith("artifact://")) {
            return Optional.empty();
        }
        var referenced = workspaceRoot.resolve(ref).normalize();
        if (!referenced.startsWith(workspaceRoot)) {
            return Optional.empty();
        }
        var path = ref.endsWith(".contract.json")
                ? referenced
                : AgentOutputContractSidecar.pathFor(referenced);
        if (!path.startsWith(workspaceRoot)
                || Files.isSymbolicLink(path)
                || !Files.isRegularFile(path)) {
            return Optional.empty();
        }
        try {
            if (!path.toRealPath().startsWith(workspaceRoot.toRealPath())) {
                return Optional.empty();
            }
        } catch (Exception e) {
            return Optional.empty();
        }
        return Optional.of(path);
    }

    private static Optional<Entry> readEntry(
            Path workspaceRoot,
            String workstreamId,
            Path path,
            ObjectMapper objectMapper
    ) {
        var read = readValidatedEntry(workspaceRoot, workstreamId, path, objectMapper);
        if (read.entry() == null) {
            throw new IllegalStateException(read.message());
        }
        return Optional.of(read.entry());
    }

    private static EntryRead readValidatedEntry(
            Path workspaceRoot,
            String workstreamId,
            Path path,
            ObjectMapper objectMapper
    ) {
        var document = AgentOutputContractDocument.read(path, objectMapper);
        if (document.isEmpty()) {
            return EntryRead.invalid(
                    "CONTRACT_SIDECAR_PARSE_FAILED",
                    "routed agent evidence sidecar is unreadable: " + path
            );
        }
        var violation = AgentOutputLineageVerifier.violation(workspaceRoot, workstreamId, path, document.get());
        if (violation.isPresent()) {
            return EntryRead.invalid(
                    "CONTRACT_SIDECAR_LINEAGE_INVALID",
                    "routed agent evidence lineage is invalid: " + violation.get()
            );
        }
        var semanticViolation = AgentContractSemantics.isAcceptanceReview(document.get())
                ? AgentContractSemantics.validateOutputContract(document.get()) : java.util.Optional.<ContractViolation>empty();
        if (semanticViolation.isPresent()) {
            return EntryRead.invalid(semanticViolation.get().errorCode(), semanticViolation.get().message());
        }
        return EntryRead.valid(new Entry(path.toAbsolutePath().normalize(), document.get(), lastModified(path)));
    }

    private static Instant lastModified(Path path) {
        try {
            return Files.getLastModifiedTime(path).toInstant();
        } catch (IOException ignored) {
            return Instant.EPOCH;
        }
    }

    private static String relativeRef(Path workspaceRoot, Path path) {
        return workspaceRoot.toAbsolutePath().normalize()
                .relativize(path.toAbsolutePath().normalize())
                .toString();
    }

    private static String normalizeRef(String value) {
        return value == null ? "" : value.replace('\\', '/');
    }

    record Entry(
            Path path,
            AgentOutputContractDocument document,
            Instant lastModified
    ) {
        private static final Comparator<Entry> ORDER = Comparator
                .comparing(Entry::lastModified)
                .thenComparing(entry -> entry.path().toString());

        Map<String, Object> evidenceState() {
            return AgentEvidenceState.from(document).toMap();
        }
    }

    record DecisionRead(
            Entry entry,
            String errorCode,
            String message,
            String path,
            boolean missing
    ) {
        static DecisionRead valid(Entry entry, String path) {
            return new DecisionRead(entry, "", "", path, false);
        }

        static DecisionRead invalid(String code, String message, String path) {
            return new DecisionRead(null, code, message, path, false);
        }

        static DecisionRead notFound() {
            return new DecisionRead(null, "", "", "", true);
        }
    }

    private record EntryRead(Entry entry, String errorCode, String message) {
        static EntryRead valid(Entry entry) {
            return new EntryRead(entry, "", "");
        }

        static EntryRead invalid(String code, String message) {
            return new EntryRead(null, code, message);
        }
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.contract.TaskContract;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeResult;
import dev.dual.core.workflow.HumanGateActionSemantics;
import dev.dual.ledger.file.DeliveryCandidateWriter;
import dev.dual.ledger.file.NodeInstanceDocument;
import dev.dual.ledger.file.WorkstreamPaths;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class HumanReviewGateHandler implements GateHandler {
    private final ObjectMapper objectMapper = new ObjectMapper()
            .registerModule(new JavaTimeModule())
            .enable(SerializationFeature.INDENT_OUTPUT);

    @Override
    public String type() {
        return "human.review";
    }

    @Override
    public NodeResult openOrInspect(GateContext context) throws Exception {
        var authored = authoredGate(context);
        var decision = latestAgentDecision(context, authored);
        var subject = latestReviewSubject(context, authored);
        assertBlockedSourceMatchesReview(context, decision);
        assertChangeScopeViolationSource(context);
        var contractRevision = contractRevision(context);
        var contractView = contractView(context);
        var allowedActions = HumanGateActionSemantics.allowedActions(context.definition(), context.sourceOutcome());
        var packetRef = reviewPacketRef(context, ".md");
        var packetJsonRef = reviewPacketRef(context, ".json");
        writeReviewPacket(context, allowedActions, packetRef, packetJsonRef, contractView, authored, decision, subject,
                contractRevision);

        return NodeResult.waiting("open", Map.of(
                "allowed_actions", allowedActions,
                "review_packet", packetRef,
                "review_packet_json", packetJsonRef
        ));
    }

    private void assertBlockedSourceMatchesReview(GateContext context, AgentDecisionSummary review) {
        if (!"BLOCKED".equals(context.sourceOutcome())) {
            return;
        }
        var decision = review.decision();
        if (!"BLOCKED".equals(decision) && !matchesRevisionLimitEscalation(context, decision)) {
            throw new IllegalStateException(
                    "BLOCKED gate source does not match the validated reviewer decision");
        }
    }

    private boolean matchesRevisionLimitEscalation(GateContext context, String decision) {
        var result = context.instance().result();
        if (!"revision_limit_reached".equals(text(result.get("reason")))
                || decision.isBlank()
                || !decision.equals(text(result.get("revision_limit_original_outcome")))) {
            return false;
        }
        var maxRevisions = integralValue(result.get("max_revisions"));
        var currentRevisionCount = integralValue(result.get("current_revision_count"));
        return maxRevisions >= 0 && currentRevisionCount >= maxRevisions;
    }

    private void assertChangeScopeViolationSource(GateContext context) {
        if (!"CHANGE_SCOPE_VIOLATION".equals(context.sourceOutcome())) {
            return;
        }
        changeScopeEvaluationSummary(context);
    }

    private long integralValue(Object value) {
        if (!(value instanceof Number number)) {
            return -1;
        }
        var asDouble = number.doubleValue();
        var asLong = number.longValue();
        return Double.isFinite(asDouble) && asDouble == asLong ? asLong : -1;
    }

    private String reviewPacketRef(GateContext context, String extension) {
        return ".agent/workstreams/" + context.workstreamId()
                + "/reviews/" + context.instance().nodeInstanceId() + extension;
    }

    private void writeReviewPacket(
            GateContext context,
            List<String> allowedActions,
            String packetRef,
            String packetJsonRef,
            GateContractView contractView,
            AuthoredStageLineageResolver.GateView authored,
            AgentDecisionSummary decision,
            Map<String, Object> subject,
            Map<String, Object> contractRevision
    ) throws Exception {
        var packetPath = context.workspaceRoot().resolve(packetRef);
        var packetJsonPath = context.workspaceRoot().resolve(packetJsonRef);
        Files.createDirectories(packetPath.getParent());

        var packet = new LinkedHashMap<String, Object>();
        packet.put("schemaVersion", 1);
        packet.put("workstreamId", context.workstreamId());
        packet.put("gateNodeInstanceId", context.instance().nodeInstanceId());
        packet.put("gateNodeDefinitionId", context.instance().nodeDefinitionId());
        packet.put("stageId", context.instance().stageId());
        packet.put("iterationId", context.instance().iterationId());
        packet.put("sourceOutcome", context.sourceOutcome());
        packet.put("runtimeDisposition", runtimeDisposition(context));
        packet.put("actionRequests", context.instance().result().getOrDefault("action_requests", List.of()));
        packet.put("allowedActions", allowedActions);
        if (allowedActions.contains("submit_evidence")) packet.put("externalEvidenceInstructions",
                "CLI only: review prepare-evidence before verification, then review submit-evidence with preparation ref/SHA, explicit files and execution declaration. Submission continues to self-test; it is not acceptance.");
        packet.put("inputRefs", context.instance().inputRefs());
        packet.put("inputArtifacts", inputArtifactSummaries(context));
        packet.put("reviewPacketPath", packetRef);
        packet.put("taskContract", taskContractSummary(context, contractView));
        packet.put("requirementResolution", requirementResolutionSummary(context, contractView));
        packet.put("latestAgentDecision", decision.toReviewPacketMap());
        packet.put("reviewSubject", subject);
        if (!contractRevision.isEmpty()) packet.put("contractRevision", contractRevision);
        if (authored != null) packet.put("authoredStage", authored.projection());
        packet.put("gitEvidence", gitEvidenceSummary(context));
        packet.put("delivery", deliverySummary(context));
        packet.put("operatorGuidance", operatorGuidance(context, allowedActions, decision));
        packet.put("createdAt", Instant.now().toString());

        objectMapper.writeValue(packetJsonPath.toFile(), packet);
        Files.writeString(packetPath, renderMarkdown(context, allowedActions, contractView, authored, decision, subject,
                contractRevision), StandardCharsets.UTF_8);
    }

    private String renderMarkdown(
            GateContext context,
            List<String> allowedActions,
            GateContractView contractView,
            AuthoredStageLineageResolver.GateView authored,
            AgentDecisionSummary decision,
            Map<String, Object> subject,
            Map<String, Object> contractRevision
    ) throws Exception {
        var builder = new StringBuilder();
        builder.append("# Human Review Packet\n\n");
        builder.append("- Workstream: ").append(context.workstreamId()).append("\n");
        builder.append("- Gate: ").append(context.instance().nodeDefinitionId()).append("\n");
        builder.append("- Gate Instance: ").append(context.instance().nodeInstanceId()).append("\n");
        builder.append("- Stage: ").append(context.instance().stageId()).append("\n");
        builder.append("- Iteration: ").append(context.instance().iterationId()).append("\n");
        builder.append("- Source Outcome: ").append(context.sourceOutcome()).append("\n");
        var runtimeDisposition = runtimeDisposition(context);
        if (!runtimeDisposition.isEmpty()) {
            builder.append("- Runtime Disposition: ").append(runtimeDisposition).append("\n");
        }
        builder.append("- Allowed Actions: ").append(String.join(", ", allowedActions)).append("\n\n");
        if (allowedActions.contains("submit_evidence")) builder.append(
                "External evidence: use `review prepare-evidence` before testing unchanged source, then `review submit-evidence --help`. "
                + "CLI-only ingestion; submitted materials must still pass self-test and acceptance.\n\n");

        appendOperatorGuidance(builder, context, allowedActions, decision);

        builder.append("## Review Focus\n\n");
        builder.append("- Read the complete referenced design and review sidecars before approving; the packet summary is not a substitute.\n");
        builder.append("- Use `approve` only when the current gate is good enough to continue.\n");
        builder.append("- Use `revise` when the agent should address concrete feedback first.\n\n");

        appendReviewSummary(builder, context, contractView, decision);
        appendTaskContract(builder, context, contractView);
        appendRequirementResolution(builder, context, contractView);
        appendLatestAgentDecision(builder, decision);
        if (authored != null) {
            builder.append("## Authored Candidate And Revision History\n\n")
                    .append("Historical obligations remain active until approval. Responses are claims, not verified closure. ")
                    .append("New must-fix items were raised after this candidate and enter its next revision.\n\n")
                    .append("```json\n").append(objectMapper.writerWithDefaultPrettyPrinter().writeValueAsString(authored.projection()))
                    .append("\n```\n\n");
        }
        if (authored == null) appendReviewSubject(builder, subject);
        builder.append(ContextBuildPackageHandler.renderContractRevision(contractRevision));
        appendGitEvidence(builder, context);
        appendDelivery(builder, context);

        appendInputArtifacts(builder, context);
        return builder.toString();
    }

    private void appendInputArtifacts(StringBuilder builder, GateContext context) {
        builder.append("## Input Artifacts\n\n");
        var artifacts = inputArtifactSummaries(context);
        if (artifacts.isEmpty()) {
            builder.append("No input artifacts were attached to this gate.\n");
            return;
        }
        builder.append("Raw agent logs are not embedded here by default. Use the paths below when deeper debugging is needed.\n\n");
        for (var artifact : artifacts) {
            builder.append("### ").append(text(artifact.get("ref"))).append("\n\n");
            appendField(builder, "Status", text(artifact.get("status")));
            appendField(builder, "Kind", text(artifact.get("kind")));
            appendField(builder, "Sidecar", text(artifact.get("sidecar")));
            appendField(builder, "Decision", text(artifact.get("decision")));
            appendField(builder, "Summary", text(artifact.get("summary")));
            appendList(builder, "Must Fix", artifact.get("mustFix"));
            appendList(builder, "Open Risks", artifact.get("openRisks"));
            appendField(builder, "Raw Artifact", text(artifact.get("ref")));
            builder.append("\n");
        }
    }

