class SelfTestContinuationSequenceTest {
    @TempDir Path temp;

    @Test
    void missingOrUnknownDispositionIsRejectedBeforeAnyLedgerWrite() throws Exception {
        var loaded = new WorkflowDefinitionLoader().loadOrDefault(null, "terminal-delivery");
        var definition = new WorkflowDefinition(loaded.workflowId(), loaded.version(),
                "implement.self_test_decision", loaded.nodes(), loaded.edges());
        var paths = new WorkstreamPaths(temp.resolve("invalid"), new DualId("ws-test"));
        try (var kernel = new LiteFlowPrototypeKernel()) {
            var ledger = new WorkflowFileLedger(kernel);
            ledger.initialize(paths, "workflow-test", definition);
            var current = ledger.loadCurrent(paths);
            var id = current.activeNodeInstanceIds().getFirst();
            var before = Files.readString(paths.nodeJson(id));
            var events = Files.readString(paths.eventsJsonl());
            for (var facts : List.of(Map.<String, Object>of(), Map.<String, Object>of("continuation_kind", "UNKNOWN"))) {
                assertThrows(IllegalArgumentException.class, () -> ledger.completeAndRoute(paths, definition,
                        id, NodeStatus.COMPLETED, "SELF_TEST_INCOMPLETE", List.of(), facts));
                assertEquals(before, Files.readString(paths.nodeJson(id)));
                assertEquals(events, Files.readString(paths.eventsJsonl()));
                assertEquals(current, ledger.loadCurrent(paths));
            }
        }
    }

    @Test
    void deletedBranchOrConditionCannotLoadAsAValidDefinition() throws Exception {
        var loaded = new WorkflowDefinitionLoader().loadOrDefault(null, "terminal-delivery");
        var edges = new java.util.ArrayList<>(loaded.edges());
        var index = java.util.stream.IntStream.range(0, edges.size()).filter(i ->
                edges.get(i).from().equals("implement.self_test_decision")
                        && edges.get(i).on().equals("SELF_TEST_INCOMPLETE")).findFirst().orElseThrow();
        var edge = edges.remove(index);
        assertThrows(IllegalArgumentException.class, () -> new WorkflowDefinition(loaded.workflowId(),
                loaded.version(), loaded.entryNodeId(), loaded.nodes(), edges));
        edges.add(index, new dev.dual.core.workflow.EdgeDefinition(edge.from(), edge.on(), edge.to(), null, edge.metadata()));
        assertThrows(IllegalArgumentException.class, () -> new WorkflowDefinition(loaded.workflowId(),
                loaded.version(), loaded.entryNodeId(), loaded.nodes(), edges));
    }

    @Test
    void realLiteFlowRoutesValidatedSelfTestAndColdLoadsTheCorrectSuccessorAcrossSiblings() throws Exception {
        for (var variant : List.of("contract", "full", "terminal-delivery")) {
            for (var mode : List.of("complete", "evidence", "mixed", "blocked")) {
                var workspace = temp.resolve(variant + "-" + mode);
                var paths = new WorkstreamPaths(workspace, new DualId("ws-test"));
                var loaded = new WorkflowDefinitionLoader().loadOrDefault(null, variant);
                // Enter at the affected stage; upstream qualification is not bypassed by a provider run.
                var definition = new WorkflowDefinition(loaded.workflowId(), loaded.version(),
                        "implement.claude_self_test_report", loaded.nodes(), loaded.edges());
                try (var kernel = new LiteFlowPrototypeKernel()) {
                    var ledger = new WorkflowFileLedger(kernel);
                    ledger.initialize(paths, "workflow-test", definition);
                    var sourceId = ledger.loadCurrent(paths).activeNodeInstanceIds().getFirst();
                    var decision = mode.equals("complete") ? "SELF_TEST_COMPLETE"
                            : mode.equals("blocked") ? "BLOCKED" : "SELF_TEST_INCOMPLETE";
                    var mustFix = mode.equals("mixed") ? List.of("Correct rollback behavior") : List.<String>of();
                    var missing = mode.equals("complete") ? List.<String>of() : List.of("Device verification record");
                    var payload = new AgentResultEnvelope.SelfTestResult("self_test_report", decision,
                            "Verification result", mode.equals("complete") ? "READY"
                                    : mode.equals("blocked") ? "BLOCKED" : "INSUFFICIENT_EVIDENCE",
                            List.of("local test"), List.of(), List.of("local result"), missing, mustFix,
                            List.of(), "Recorded actual evidence");
                    var envelope = new AgentResultEnvelope(1, "ws-test", "run-test",
                            "implement.claude_self_test_report", payload);
                    var contract = ContractRegistry.forNode(envelope.nodeId());
                    var validation = new AgentResultEnvelopeValidator().validate(envelope, "ws-test", "run-test", contract);
                    assertTrue(validation.valid(), validation.errors().toString());
                    var ref = ".agent/workstreams/ws-test/runs/run-test/outputs/self-test.contract.json";
                    var sidecar = new AgentResultDocumentProjector().outputContract(envelope, contract,
                            "acpx.agent_run", sourceId,
                            ".agent/workstreams/ws-test/runs/run-test/outputs/self-test.json");
                    Files.createDirectories(workspace.resolve(ref).getParent());
                    new ObjectMapper().writeValue(workspace.resolve(ref).toFile(), sidecar);
                    AgentOutputLineageFixture.publish(workspace, "ws-test", workspace.resolve(ref), "iter-001");
                    var published = ledger.loadNode(paths, sourceId);
                    ledger.completeAndRoute(paths, definition, sourceId, NodeStatus.COMPLETED,
                            "completed", published.outputRefs(), published.result());
                    var decisionNode = ledger.loadCoreNode(paths,
                            ledger.loadCurrent(paths).activeNodeInstanceIds().getFirst());
                    assertEquals("implement.self_test_decision", decisionNode.nodeDefinitionId());
                    var result = new ReviewDecisionHandler().evaluate(new DecisionHandler.DecisionContext(
                            workspace, "ws-test", definition.node(decisionNode.nodeDefinitionId()), decisionNode));
                    assertEquals(NodeStatus.COMPLETED, result.status(), result.toString());
                    ledger.completeAndRoute(paths, definition, decisionNode.nodeInstanceId(), result.status(),
                            result.outcome(), result.outputRefs(), result.result());
                }
                try (var coldKernel = new LiteFlowPrototypeKernel()) {
                    var cold = new WorkflowFileLedger(coldKernel);
                    var current = cold.loadCurrent(paths);
                    assertEquals(1, current.activeNodeInstanceIds().size());
                    var next = cold.loadNode(paths, current.activeNodeInstanceIds().getFirst());
                    var expected = mode.equals("complete") ? "implement.artifact_validation"
                            : mode.equals("mixed") ? "context.implement_claude" : "gate.human_implementation_repair";
                    assertEquals(expected, next.nodeDefinitionId(), variant + ":" + mode);
                    assertEquals(List.of(".agent/workstreams/ws-test/runs/run-test/outputs/self-test.json",
                                    ".agent/workstreams/ws-test/runs/run-test/outputs/self-test.contract.json"),
                            next.inputRefs());
                    if (mode.equals("evidence") || mode.equals("blocked")) {
                        assertEquals(WorkflowStatus.WAITING_FOR_HUMAN, current.status());
                        assertThrows(Exception.class, () -> cold.resolveOpenGate(paths, cold.loadDefinition(paths),
                                "revise", ""));
                        assertEquals(current, cold.loadCurrent(paths), "invalid human action must not alter state");
                    }
                }
            }
        }
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.core.workflow.WorkflowDefinition;
import dev.dual.core.workflow.WorkflowStatus;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.ledger.file.WorkstreamPaths;
import dev.dual.runtime.lifecycle.WorkflowDefinitionLoader;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SmallWorkflowProfileGateIntegrationTest {
    private static final String EXPERIMENT_RESOURCE =
            "/dev/dual/runtime/lifecycle/agent-lifecycle.small-plan-human-review-experiment.json";
    private final ObjectMapper objectMapper = new ObjectMapper();

    @TempDir
    Path tempDir;

    @Test
    void validatedPlanSidecarRoutesDirectlyToHumanGateAndApproveStartsImplementationContext() throws Exception {
        var workspace = tempDir.resolve("approve-workspace");
        var state = initializeAtPlan(workspace, "ws-small-approve");
        var evidence = publishPlanSidecar(workspace, state.paths().workstreamId().value(), "run-plan-approve");

        routePlanToGate(state, evidence.refs(), "completed");
        var gateNode = state.ledger().loadCoreNode(
                state.paths(), state.ledger().loadCurrent(state.paths()).activeNodeInstanceIds().getFirst());
        var gate = state.ledger().loadOpenGateForNode(state.paths(), gateNode.nodeInstanceId());
        var result = new HumanReviewGateHandler().openOrInspect(new GateHandler.GateContext(
                workspace,
                state.paths().workstreamId().value(),
                state.definition().node("gate.human_plan_approval"),
                gateNode,
                String.valueOf(gate.result().get("source_outcome"))));

        @SuppressWarnings("unchecked")
        var packet = (Map<String, Object>) objectMapper.readValue(
                workspace.resolve(String.valueOf(result.result().get("review_packet_json"))).toFile(), Map.class);
        @SuppressWarnings("unchecked")
        var latestDecision = (Map<String, Object>) packet.get("latestAgentDecision");

        assertEquals("completed", packet.get("sourceOutcome"));
        assertEquals(List.of("approve", "revise"), packet.get("allowedActions"));
        assertEquals(evidence.refs(), packet.get("inputRefs"));
        assertEquals("READY_FOR_PLAN_REVIEW", latestDecision.get("decision"));
        assertFalse(objectMapper.writeValueAsString(packet).contains("plan.codex_plan_review"));

        state.ledger().resolveOpenGate(state.paths(), state.definition(), "approve", "Plan reviewed by operator.");
        var next = state.ledger().loadNode(
                state.paths(), state.ledger().loadCurrent(state.paths()).activeNodeInstanceIds().getFirst());
        assertEquals("context.implement_claude", next.nodeDefinitionId());
        try (var files = Files.walk(workspace)) {
            assertFalse(files.anyMatch(path -> path.toString().contains("plan-codex-review")));
        }
    }

    @Test
    void humanPlanRevisionMayContinueBeyondTheAutomaticBudget() throws Exception {
        var workspace = tempDir.resolve("revise-workspace");
        var state = initializeAtPlan(workspace, "ws-small-revise");

        for (var revision = 1; revision <= 3; revision++) {
            var evidence = publishPlanSidecar(
                    workspace, state.paths().workstreamId().value(), "run-plan-revise-" + revision);
            routePlanToGate(state, evidence.refs(), "completed");
            state.ledger().resolveOpenGate(
                    state.paths(), state.definition(), "revise", "Human plan revision " + revision);

            var plan = state.ledger().loadNode(
                    state.paths(), state.ledger().loadCurrent(state.paths()).activeNodeInstanceIds().getFirst());
            assertEquals("plan.claude_plan", plan.nodeDefinitionId());
            assertEquals("iter-00" + (revision + 1), plan.iterationId());
        }

        var fourthEvidence = publishPlanSidecar(
                workspace, state.paths().workstreamId().value(), "run-plan-revise-4");
        routePlanToGate(state, fourthEvidence.refs(), "completed");
        state.ledger().resolveOpenGate(
                state.paths(), state.definition(), "revise", "Human explicitly authorizes plan revision 4");

        assertEquals(WorkflowStatus.RUNNING, state.ledger().loadCurrent(state.paths()).status());
        var fourthRevision = state.ledger().loadNode(
                state.paths(), state.ledger().loadCurrent(state.paths()).activeNodeInstanceIds().getFirst());
        assertEquals("plan.claude_plan", fourthRevision.nodeDefinitionId());
        assertEquals("iter-005", fourthRevision.iterationId());
        var events = Files.readString(state.paths().eventsJsonl());
        assertFalse(events.contains("revision_limit_reached"));
        assertFalse(events.contains("plan.decision"));
    }

    @Test
    void lineageInvalidPlanSidecarCannotBecomeHumanReviewEvidence() throws Exception {
        var workspace = tempDir.resolve("invalid-workspace");
        var state = initializeAtPlan(workspace, "ws-small-invalid");
        var evidence = writePlanSidecar(
                workspace, state.paths().workstreamId().value(), "run-plan-forged");

        routePlanToGate(state, evidence.refs(), "completed");
        var gateNode = state.ledger().loadCoreNode(
                state.paths(), state.ledger().loadCurrent(state.paths()).activeNodeInstanceIds().getFirst());
        var gate = state.ledger().loadOpenGateForNode(state.paths(), gateNode.nodeInstanceId());

        assertThrows(IllegalStateException.class, () -> new HumanReviewGateHandler().openOrInspect(
                new GateHandler.GateContext(
                        workspace,
                        state.paths().workstreamId().value(),
                        state.definition().node("gate.human_plan_approval"),
                        gateNode,
                        String.valueOf(gate.result().get("source_outcome")))));
        assertFalse(Files.exists(workspace.resolve(
                ".agent/workstreams/" + state.paths().workstreamId().value()
                        + "/reviews/" + gateNode.nodeInstanceId() + ".json")));
    }

    @Test
    void blockedPlanOutcomeHasTheSameFailClosedBehaviorAsTerminalDelivery() throws Exception {
        var baseline = new WorkflowDefinitionLoader().loadOrDefault(null, "terminal-delivery");
        var experiment = loadExperiment();
        var baselineState = initializeAtPlan(
                tempDir.resolve("blocked-baseline"), "ws-blocked-baseline", baseline);
        var experimentState = initializeAtPlan(
                tempDir.resolve("blocked-experiment"), "ws-blocked-experiment", experiment);

        var baselinePlan = completeBlockedPlan(baselineState);
        var experimentPlan = completeBlockedPlan(experimentState);

        assertEquals(baselineState.ledger().loadCurrent(baselineState.paths()).status(),
                experimentState.ledger().loadCurrent(experimentState.paths()).status());
        assertEquals(WorkflowStatus.WAITING_FOR_RECOVERY,
                experimentState.ledger().loadCurrent(experimentState.paths()).status());
        assertEquals(baselineState.ledger().loadNode(baselineState.paths(), baselinePlan).status(),
                experimentState.ledger().loadNode(experimentState.paths(), experimentPlan).status());
        assertEquals(NodeStatus.BLOCKED,
                experimentState.ledger().loadNode(experimentState.paths(), experimentPlan).status());
    }

    private TestState initializeAtPlan(Path workspace, String workstreamId) throws Exception {
        Files.createDirectories(workspace);
        return initializeAtPlan(workspace, workstreamId, loadExperiment());
    }

    private TestState initializeAtPlan(
            Path workspace,
            String workstreamId,
            WorkflowDefinition loaded
    ) throws Exception {
        Files.createDirectories(workspace);
        var fixture = new AuthoredStageSequenceTest.Fixture(workspace, "src/Main.java",
                AuthoredStageSequenceTest.PlanTopology.DIRECT_HUMAN, workstreamId, loaded);
        fixture.before("plan.claude_plan");
        return new TestState(fixture.paths, fixture.ledger, fixture.ledger.loadDefinition(fixture.paths));
    }

    private WorkflowDefinition loadExperiment() throws Exception {
        return new WorkflowDefinitionLoader().load(
                Path.of(SmallWorkflowProfileGateIntegrationTest.class
                        .getResource(EXPERIMENT_RESOURCE).toURI()));
    }

    private void routePlanToGate(TestState state, List<String> evidenceRefs, String outcome) throws Exception {
        var plan = state.ledger().loadCurrent(state.paths()).activeNodeInstanceIds().getFirst();
        state.ledger().completeAndRoute(
                state.paths(), state.definition(), plan, NodeStatus.COMPLETED, outcome, evidenceRefs,
                state.ledger().loadNode(state.paths(), plan).result());
        var gate = state.ledger().loadNode(
                state.paths(), state.ledger().loadCurrent(state.paths()).activeNodeInstanceIds().getFirst());
        assertEquals("gate.human_plan_approval", gate.nodeDefinitionId());
        assertEquals(evidenceRefs, gate.inputRefs());
    }

    private String completeBlockedPlan(TestState state) throws Exception {
        var plan = state.ledger().loadCurrent(state.paths()).activeNodeInstanceIds().getFirst();
        state.ledger().completeAndRoute(
                state.paths(), state.definition(), plan, NodeStatus.BLOCKED, "BLOCKED", List.of(), Map.of());
        return plan;
    }

    private PlanEvidence publishPlanSidecar(Path workspace, String workstreamId, String runId) throws Exception {
        var evidence = writePlanSidecar(workspace, workstreamId, runId);
        var paths = new WorkstreamPaths(workspace, new DualId(workstreamId));
        var ledger = new WorkflowFileLedger();
        var node = ledger.loadCoreNode(paths, ledger.loadCurrent(paths).activeNodeInstanceIds().getFirst());
        var context = new TaskHandler.TaskContext(workspace, workstreamId, ledger.loadDefinition(paths).node(node.nodeDefinitionId()), node);
        AuthoredInputFixture.record(context, runId);
        var snapshot = AuthoredExecutionContext.prepare(context, runId).orElseThrow();
        var prompt = AgentResultPromptContract.render(workstreamId, runId, "plan.claude_plan",
                "READY_FOR_PLAN_REVIEW", java.util.Set.of("READY_FOR_PLAN_REVIEW"));
        var envelope = (com.fasterxml.jackson.databind.node.ObjectNode) objectMapper.readTree(prompt.substring(prompt.indexOf('{')));
        var editFiles = ((com.fasterxml.jackson.databind.node.ObjectNode) envelope.at("/result/plan")).putArray("edit_files");
        TaskContractProjectionVerifier.resolve(workspace, workstreamId).qualified().orElseThrow().contract()
                .scope().included().forEach(entry -> editFiles.add(entry.path()));
        var responses = ((com.fasterxml.jackson.databind.node.ObjectNode) envelope.get("result")).putArray("revision_responses");
        snapshot.obligations().forEach(obligation -> responses.addObject().put("obligation_id", obligation.id())
                .put("disposition", "ADDRESSED").put("evidence", "Plan revised with the human note"));
        objectMapper.writeValue(workspace.resolve(evidence.outputRef()).toFile(), envelope);
        var result = new ArtifactContractValidator().validate(workspace, workstreamId, node.nodeInstanceId(),
                context.definition(), dev.dual.core.workflow.NodeResult.completed("completed", List.of(evidence.outputRef()),
                        Map.of("run_id", runId)));
        assertEquals(NodeStatus.COMPLETED, result.status(), result.result().toString());
        AgentOutputLineageFixture.publish(workspace, workstreamId, workspace.resolve(evidence.sidecarRef()),
                node.iterationId(), node.inputRefs());
        return evidence;
    }

    private PlanEvidence writePlanSidecar(Path workspace, String workstreamId, String runId) throws Exception {
        var outputRef = ".agent/workstreams/" + workstreamId + "/runs/" + runId + "/outputs/plan.json";
        var sidecarRef = ".agent/workstreams/" + workstreamId + "/runs/" + runId
                + "/outputs/plan.contract.json";
        var output = workspace.resolve(outputRef);
        var sidecar = workspace.resolve(sidecarRef);
        Files.createDirectories(output.getParent());
        Files.writeString(output, "{}", StandardCharsets.UTF_8);
        Files.writeString(sidecar, """
                {
                  "artifact_type": "agent_output_contract",
                  "schema_version": 1,
                  "workstream_id": "%s",
