    @Test void coldJvmRequiresPreparationAndMaterialAndExecutionRechecksAfterTheTool() throws Exception {
        var paths = waiting("cold-jvm");
        var preparation = ExternalVerificationEvidence.prepare(ledger, paths);
        ExternalVerificationEvidence.submit(ledger, paths, preparation, "r", List.of(report()), declaration(), "note");
        var id = ledger.loadCurrent(paths).activeNodeInstanceIds().getFirst();
        assertEquals(0, cold(paths, id));
        var original = Files.readAllBytes(paths.workspaceRoot().resolve(preparation.ref()));
        Files.delete(paths.workspaceRoot().resolve(preparation.ref()));
        assertNotEquals(0, cold(paths, id));
        Files.write(paths.workspaceRoot().resolve(preparation.ref()), original);
        var refs = EvidenceCollection.requiredReferences(paths.workspaceRoot(), paths.workstreamId().value(), id);
        var node = ledger.loadNode(paths, id);
        assertEquals(EvidenceCollection.FAILURE, EvidenceCollection.execute(paths.workspaceRoot(), paths.workstreamId().value(), node,
                () -> {
                    Files.delete(paths.workspaceRoot().resolve(refs.getLast()));
                    return NodeResult.completed("completed", List.of(), Map.of());
                }).outcome());
    }

    private int cold(WorkstreamPaths paths, String id) throws Exception {
        var process = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin/java").toString(), "-cp",
                System.getProperty("java.class.path"), ColdReader.class.getName(), paths.workspaceRoot().toString(), paths.workstreamId().value(), id)
                .redirectErrorStream(true).redirectOutput(ProcessBuilder.Redirect.DISCARD).start();
        if (!process.waitFor(30, java.util.concurrent.TimeUnit.SECONDS)) { process.destroyForcibly(); fail("cold evidence read timed out"); }
        return process.exitValue();
    }
    public static final class ColdReader {
        public static void main(String[] args) throws Exception {
            if (EvidenceCollection.requiredReferences(Path.of(args[0]), args[1], args[2]).isEmpty()) throw new IllegalStateException("binding lost");
        }
    }

    private WorkstreamPaths waiting(String name) throws Exception {
        temp = temp.toRealPath();
        var fixture = new EvidenceCollectionSequenceTest(); fixture.temp = temp;
        return fixture.waiting(name);
    }
    private Path report() throws Exception {
        var path = Files.createTempFile(temp, "device-report-", ".txt");
        Files.writeString(path, "device check passed"); return path;
    }
    private ExternalVerificationEvidence.Declaration declaration() {
        var now = Instant.now(); return new ExternalVerificationEvidence.Declaration("device verify", "operator host", now, now, 0, "device evidence");
    }
    private AgentResultEnvelope.SelfTestResult self(List<String> refs) {
        return new AgentResultEnvelope.SelfTestResult("self_test_report", "SELF_TEST_COMPLETE", "verified", "IMPLEMENTED",
                List.of("device verification"), List.of(), refs, List.of(), List.of(), List.of(), "verified material");
    }
    private AgentResultEnvelope.AcceptanceReviewResult acceptance(List<String> refs) {
        return new AgentResultEnvelope.AcceptanceReviewResult("acceptance_review", "ACCEPT", "verified", "ACCEPTED", false,
                List.of("device evidence"), refs, List.of(), List.of(), List.of(), List.of(), List.of(), "verified", null);
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.workflow.NodeKind;
import dev.dual.core.workflow.NodeStatus;
import dev.dual.ledger.file.NodeExecutionDocument;
import dev.dual.ledger.file.NodeExecutionStatus;
import dev.dual.ledger.file.NodeInstanceDocument;

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.List;
import java.util.Map;

public final class AgentOutputLineageFixture {
    private static final ObjectMapper MAPPER = new ObjectMapper().registerModule(new JavaTimeModule());
    private static final TypeReference<Map<String, Object>> MAP_TYPE = new TypeReference<>() {
    };

    private AgentOutputLineageFixture() {
    }

    public static void completeAndPublish(Path workspaceRoot, String workstreamId, Path sidecarPath) throws Exception {
        completeAndPublish(workspaceRoot, workstreamId, sidecarPath, "iteration-fixture", List.of());
    }

    public static void completeAndPublish(
            Path workspaceRoot,
            String workstreamId,
            Path sidecarPath,
            String iterationId,
            List<String> inputRefs
    ) throws Exception {
        var tree = MAPPER.readTree(sidecarPath.toFile());
        if (!(tree instanceof ObjectNode sidecar)) {
            throw new IllegalArgumentException("agent output sidecar must be a JSON object");
        }
        var runId = runId(sidecarPath);
        var source = sourcePath(sidecarPath);
        sidecar.put("workstream_id", workstreamId);
        sidecar.put("run_id", runId);
        sidecar.put("node_instance_id", "node-fixture-" + runId + "-"
                + sidecarPath.getFileName().toString().replaceAll("[^A-Za-z0-9._-]", "-"));
        sidecar.put("source_output_ref", relative(workspaceRoot, source));
        MAPPER.writerWithDefaultPrettyPrinter().writeValue(sidecarPath.toFile(), sidecar);
        publish(workspaceRoot, workstreamId, sidecarPath, iterationId, inputRefs);
    }

    public static void publish(Path workspaceRoot, String workstreamId, Path sidecarPath) throws Exception {
        publish(workspaceRoot, workstreamId, sidecarPath, "iteration-fixture");
    }

    public static void publish(
            Path workspaceRoot,
            String workstreamId,
            Path sidecarPath,
            String iterationId
    ) throws Exception {
        publish(workspaceRoot, workstreamId, sidecarPath, iterationId, List.of());
    }

    public static void publish(
            Path workspaceRoot,
            String workstreamId,
            Path sidecarPath,
            String iterationId,
            List<String> inputRefs
    ) throws Exception {
        var sidecar = MAPPER.readValue(sidecarPath.toFile(), MAP_TYPE);
        var runId = text(sidecar.get("run_id"));
        var nodeId = text(sidecar.get("node_id"));
        var nodeInstanceId = text(sidecar.get("node_instance_id"));
        var sourceRef = text(sidecar.get("source_output_ref"));
        if (runId.isBlank() || nodeId.isBlank() || nodeInstanceId.isBlank() || sourceRef.isBlank()) {
            return;
        }
        var source = workspaceRoot.resolve(sourceRef).normalize();
        Files.createDirectories(source.getParent());
        if (!Files.exists(source)) {
            Files.writeString(source, "{}");
        }
        var sidecarRef = relative(workspaceRoot, sidecarPath);
        var decision = text(sidecar.get("decision"));
        var outputs = List.of(sourceRef, sidecarRef);
        var result = Map.<String, Object>of(
                "run_id", runId,
                "decision", decision,
                "contract_sidecar_sha256", AgentOutputContractSidecar.sha256(sidecarPath));
        var executionId = "nxe-" + nodeInstanceId.replaceAll("[^A-Za-z0-9._-]", "-");
        var workstreamDir = workspaceRoot.resolve(".agent/workstreams").resolve(workstreamId);
        var nodesDir = workstreamDir.resolve("nodes");
        var executionsDir = workstreamDir.resolve("executions/nodes");
        Files.createDirectories(nodesDir);
        Files.createDirectories(executionsDir);
        var now = Instant.parse("2026-07-21T00:00:00Z");
        MAPPER.writeValue(nodesDir.resolve(nodeInstanceId + ".json").toFile(), new NodeInstanceDocument(
                1, nodeInstanceId, nodeId, NodeKind.TASK, "acpx.agent_run", NodeStatus.COMPLETED,
                "stage-fixture", iterationId, inputRefs, Map.of(), outputs,
                result, runId, executionId, now, now));
        MAPPER.writeValue(executionsDir.resolve(executionId + ".json").toFile(), new NodeExecutionDocument(
                1, executionId, "agent-task-fixture", "workflow-execution-fixture",
                nodeInstanceId, nodeId, "acpx.agent_run", NodeExecutionStatus.SUCCEEDED,
                1L, "completed", NodeStatus.COMPLETED, outputs,
                result, "",
                runId, "", "fixture-agent", "fixture-session", 0, now, now, 1L));
    }

    private static String relative(Path root, Path path) {
        return root.toAbsolutePath().normalize().relativize(path.toAbsolutePath().normalize()).toString();
    }

    private static String runId(Path sidecarPath) {
        for (var index = 0; index + 1 < sidecarPath.getNameCount(); index++) {
            if ("runs".equals(sidecarPath.getName(index).toString())) {
                return sidecarPath.getName(index + 1).toString();
            }
        }
        throw new IllegalArgumentException("sidecar is not under a run: " + sidecarPath);
    }

    private static Path sourcePath(Path sidecarPath) {
        var name = sidecarPath.getFileName().toString();
        if (!name.endsWith(".contract.json")) {
            throw new IllegalArgumentException("not an agent output sidecar: " + sidecarPath);
        }
        var stem = name.substring(0, name.length() - ".contract.json".length());
        var json = sidecarPath.resolveSibling(stem + ".json");
        var markdown = sidecarPath.resolveSibling(stem + ".md");
        if (Files.exists(json)) {
            return json;
        }
        return Files.exists(markdown) ? markdown : json;
    }

    private static String text(Object value) {
        return value == null ? "" : String.valueOf(value).trim();
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import dev.dual.core.arbitration.FailureCategory;
import dev.dual.core.workflow.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class FailureClassifyHandlerTest {
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final String WS = "ws-classification";
    private static final String REVIEW = "acceptance.codex_verifier_review";
    @TempDir Path root;

    private ObjectNode envelope(FailureCategory category) throws Exception {
        var prompt = AgentResultPromptContract.render(WS, "run-review", REVIEW, "ACCEPT",
                ContractRegistry.forNode(REVIEW).allowedDecisions());
        for (var value : FailureCategory.values()) assertTrue(prompt.contains(value.name()));
        var tree = (ObjectNode) JSON.readTree(prompt.substring(prompt.indexOf("{")));
        var result = (ObjectNode) tree.get("result");
        result.put("decision", "REJECT");
        result.put("lifecycle_status", "REJECTED");
        var failure = (ObjectNode) result.get("failure");
        failure.put("category_hint", category.name());
        switch (category) {
            case CONTRACT_GAP, CONTRACT_AMBIGUITY -> failure.putArray("contract_gaps").add("Specify the service retention contract");
            case IMPLEMENTATION_BUG -> result.putArray("must_fix").add("Repair site/README.md or service/main.py");
            case VERIFICATION_INSUFFICIENT -> {
                failure.putArray("missing_tests").add("Run the Java tool test suite");
                failure.put("verification_remediation", "EVIDENCE_COLLECTION");
            }
            case CONTEXT_INSUFFICIENT -> failure.putArray("context_gaps").add("Provide the deployment input");
            case TOOL_LIMITATION, REVIEW_NOISE -> failure.put("reason", "Explicit prerequisite or reviewer reevaluation needed");
        }
        return tree;
    }

    private NodeResult publish(ObjectNode tree) throws Exception {
        String ref = ".agent/workstreams/" + WS + "/runs/run-review/outputs/review.json";
        Files.createDirectories(root.resolve(ref).getParent());
        JSON.writeValue(root.resolve(ref).toFile(), tree);
        return new ArtifactContractValidator().validate(root, WS, "node-review", new NodeDefinition(
                REVIEW, NodeKind.TASK, "acpx.agent_run", Map.of()), NodeResult.completed(
                "completed", List.of(ref), Map.of("run_id", "run-review")));
    }

    private Path sidecar() { return root.resolve(".agent/workstreams/" + WS + "/runs/run-review/outputs/review.contract.json"); }
    private String sidecarRef() { return root.relativize(sidecar()).toString(); }
    private Path classification() { return root.resolve(".agent/workstreams/" + WS + "/artifacts/failure-classification.json"); }

    private NodeResult classify() throws Exception {
        var instance = new NodeInstance("node-classify", "acceptance.classify_failure", NodeKind.TASK,
                "acceptance.failure_classify", NodeStatus.READY, "stage-acceptance", "iter-001",
                List.of(sidecarRef()), List.of(), Map.of(), "", Instant.now(), null);
        return new FailureClassifyHandler().execute(new TaskHandler.TaskContext(root, WS,
                new NodeDefinition("acceptance.classify_failure", NodeKind.TASK, "acceptance.failure_classify", Map.of()),
                instance));
    }

    @Test
    void renderParsePublishColdReadClassifyEveryCategory() throws Exception {
        for (var category : FailureCategory.values()) {
            Files.deleteIfExists(classification());
            var tree = envelope(category);
            var parsed = new AgentResultEnvelopeParser().parse(tree.toString());
            assertNotNull(parsed.envelope(), category.name());
            assertTrue(new AgentResultEnvelopeValidator().validate(parsed.envelope(), WS, "run-review",
                    ContractRegistry.forNode(REVIEW)).valid(), category.name());
            var published = publish(tree);
            assertEquals(NodeStatus.COMPLETED, published.status(), published.toString());
            AgentOutputLineageFixture.completeAndPublish(root, WS, sidecar());
            var cold = AgentEvidenceIndex.latestDecisionFromRefs(root, WS, List.of(sidecarRef()), new ObjectMapper());
            assertNotNull(cold.entry(), cold.toString());
            assertEquals(category.name(), cold.entry().document().failure().categoryHint());
            var classified = classify();
            if (category == FailureCategory.CONTRACT_GAP || category == FailureCategory.CONTRACT_AMBIGUITY) {
                assertEquals("ACCEPTANCE_REWORK_BASELINE_INVALID", classified.outcome());
                assertFalse(Files.exists(classification()), "no contract classification writes without approved baseline");
            } else {
                assertEquals("REJECT_" + category, classified.outcome(), classified.toString());
                assertEquals(category.name(), JSON.readTree(classification().toFile()).path("category").asText());
                assertTrue(classified.outputRefs().contains(sidecarRef()), "retain original mixed evidence");
            }
        }
    }

    @Test
    void mixedProductRepairCannotBeOverriddenByMissingVerification() throws Exception {
        var tree = envelope(FailureCategory.IMPLEMENTATION_BUG);
        var result = (ObjectNode) tree.get("result");
        var failure = (ObjectNode) result.get("failure");
        failure.putArray("missing_tests").add("Collect existing test output");
        failure.put("verification_remediation", "EVIDENCE_COLLECTION");
        result.putArray("missing_evidence").add("Desktop UI record");
        assertEquals(NodeStatus.COMPLETED, publish(tree).status());
        AgentOutputLineageFixture.completeAndPublish(root, WS, sidecar());
        var classified = classify();
        assertEquals("REJECT_IMPLEMENTATION_BUG", classified.outcome());
        var evidence = JSON.readTree(classification().toFile()).path("evidence").toString();
        assertTrue(evidence.contains("Desktop UI record"));
        assertTrue(evidence.contains("Collect existing test output"));
    }

    @Test
    void mechanicalCombinationMatrixAgreesAtEnvelopePublicationAndColdRead() throws Exception {
        // Columns: category, contract gaps, must-fix, out-of-scope, missing tests,
        // context gaps, reason, missing evidence, remediation, expected validity.
        var rows = List.of(
                "CONTRACT_GAP|1|1|1|1|1|1|1|TEST_CODE_CHANGE|true",
                "CONTRACT_AMBIGUITY|1|1|1|1|1|1|1|EVIDENCE_COLLECTION|true",
                "CONTRACT_GAP|0|1|0|0|0|0|0|NONE|false",
                "IMPLEMENTATION_BUG|0|1|0|0|0|0|0|NONE|true",
                "IMPLEMENTATION_BUG|0|0|1|0|0|0|0|NONE|true",
                "IMPLEMENTATION_BUG|0|0|0|1|0|0|0|TEST_CODE_CHANGE|true",
                "IMPLEMENTATION_BUG|0|1|0|1|0|0|1|EVIDENCE_COLLECTION|true",
                "IMPLEMENTATION_BUG|0|0|0|1|0|1|1|EVIDENCE_COLLECTION|false",
                "IMPLEMENTATION_BUG|1|1|0|0|0|0|0|NONE|false",
                "VERIFICATION_INSUFFICIENT|0|0|0|0|0|0|1|NONE|true",
                "VERIFICATION_INSUFFICIENT|0|1|0|1|0|0|0|EVIDENCE_COLLECTION|true",
                "VERIFICATION_INSUFFICIENT|0|0|0|1|0|0|0|TEST_CODE_CHANGE|false",
                "VERIFICATION_INSUFFICIENT|0|0|1|1|0|0|0|EVIDENCE_COLLECTION|false",
                "VERIFICATION_INSUFFICIENT|0|0|0|1|1|0|0|EVIDENCE_COLLECTION|false",
                "VERIFICATION_INSUFFICIENT|0|0|0|0|0|1|0|NONE|false",
                "CONTEXT_INSUFFICIENT|0|0|0|1|1|0|1|EVIDENCE_COLLECTION|true",
                "CONTEXT_INSUFFICIENT|0|0|0|0|0|1|0|NONE|false",
                "CONTEXT_INSUFFICIENT|0|0|1|0|1|1|0|NONE|false",
                "CONTEXT_INSUFFICIENT|0|0|0|1|1|1|0|TEST_CODE_CHANGE|false",
                "TOOL_LIMITATION|0|0|0|1|0|1|1|EVIDENCE_COLLECTION|true",
                "TOOL_LIMITATION|0|0|0|0|0|0|0|NONE|false",
                "TOOL_LIMITATION|0|0|1|0|0|1|0|NONE|false",
                "TOOL_LIMITATION|0|0|0|1|0|1|0|TEST_CODE_CHANGE|false",
                "REVIEW_NOISE|0|0|0|0|0|1|0|NONE|true",
                "REVIEW_NOISE|0|1|0|0|0|1|0|NONE|false",
                "REVIEW_NOISE|0|0|0|0|0|1|1|NONE|false",
                "REVIEW_NOISE|0|0|0|1|0|1|0|EVIDENCE_COLLECTION|false",
                "REVIEW_NOISE|0|0|0|0|1|1|0|NONE|false",
                "IMPLEMENTATION_BUG|0|1|0|1|0|0|0|NONE|false",
                "IMPLEMENTATION_BUG|0|1|0|0|0|0|0|TEST_CODE_CHANGE|false");
        for (var row : rows) {
            var values = row.split("\\|");
            var tree = envelope(FailureCategory.valueOf(values[0]));
            var result = (ObjectNode) tree.get("result");
            var failure = (ObjectNode) result.get("failure");
            String[] keys = {"contract_gaps", "must_fix", "out_of_scope_files", "missing_tests",
                    "context_gaps", "reason", "missing_evidence"};
            for (int i = 0; i < keys.length; i++) {
                var owner = i == 1 || i == 6 ? result : failure;
                if (i == 5) owner.put(keys[i], values[i + 1].equals("1") ? "Explicit reason" : "");
                else {
                    var list = owner.putArray(keys[i]);
                    if (values[i + 1].equals("1")) list.add("A concrete fact, not a routing keyword");
                }
            }
            failure.put("verification_remediation", values[8]);
            boolean expected = Boolean.parseBoolean(values[9]);
            var parsed = new AgentResultEnvelopeParser().parse(tree.toString());
            assertNotNull(parsed.envelope(), row);
            assertEquals(expected, new AgentResultEnvelopeValidator().validate(parsed.envelope(), WS,
                    "run-review", ContractRegistry.forNode(REVIEW)).valid(), row);
            Files.deleteIfExists(sidecar());
            assertEquals(expected ? NodeStatus.COMPLETED : NodeStatus.FAILED, publish(tree).status(), row);
            if (expected) {
                AgentOutputLineageFixture.completeAndPublish(root, WS, sidecar());
                assertNotNull(AgentEvidenceIndex.latestDecisionFromRefs(root, WS, List.of(sidecarRef()), JSON).entry(), row);
            } else assertFalse(Files.exists(sidecar()), row);
        }
    }

    @Test
    void legacyUnknownAndContradictoryCategoryFailBeforePublicationAndOnColdReread() throws Exception {
        for (String category : List.of("", "implementation_bug", "IMPLEMENTATION_BUG ", "MISSING_TEST", "UNKNOWN",
                "CONTRACT_GAP", "REVIEW_NOISE", "VERIFICATION_INSUFFICIENT")) {
            var invalid = envelope(FailureCategory.IMPLEMENTATION_BUG);
            ((ObjectNode) invalid.path("result").path("failure")).put("category_hint", category);
            Files.deleteIfExists(sidecar());
            Files.deleteIfExists(classification());
            assertEquals(NodeStatus.FAILED, publish(invalid).status(), category);
            assertFalse(Files.exists(sidecar()), category);

            assertEquals(NodeStatus.COMPLETED, publish(envelope(FailureCategory.IMPLEMENTATION_BUG)).status());
            var persisted = (ObjectNode) JSON.readTree(sidecar().toFile());
            ((ObjectNode) persisted.get("failure")).put("category_hint", category);
            JSON.writeValue(sidecar().toFile(), persisted);
            // Give invalid historical bytes a valid lineage: semantic checks must still reject.
            AgentOutputLineageFixture.completeAndPublish(root, WS, sidecar());
            assertNull(AgentEvidenceIndex.latestDecisionFromRefs(root, WS, List.of(sidecarRef()), JSON).entry(), category);
            assertEquals(NodeStatus.FAILED, classify().status(), category);
            assertFalse(Files.exists(classification()), category);
        }
    }

    @Test
    void unknownRemediationCannotDisappearDuringSidecarParsing() throws Exception {
        assertEquals(NodeStatus.COMPLETED, publish(envelope(FailureCategory.IMPLEMENTATION_BUG)).status());
        var persisted = (ObjectNode) JSON.readTree(sidecar().toFile());
        ((ObjectNode) persisted.get("failure")).put("verification_remediation", "GUESS");
        JSON.writeValue(sidecar().toFile(), persisted);
        AgentOutputLineageFixture.completeAndPublish(root, WS, sidecar());
        assertNull(AgentEvidenceIndex.latestDecisionFromRefs(root, WS, List.of(sidecarRef()), JSON).entry());
        assertEquals(NodeStatus.FAILED, classify().status());
        assertFalse(Files.exists(classification()));
    }

    @Test
    void successKeepsExistingStageOutcomeGuardAndRejectsFailureCategory() throws Exception {
        var tree = envelope(FailureCategory.REVIEW_NOISE);
        var result = (ObjectNode) tree.get("result");
        result.put("decision", "ACCEPT_WITH_NOTES");
        result.put("lifecycle_status", "ACCEPTED_WITH_NOTES");
        assertEquals(NodeStatus.FAILED, publish(tree).status());
        ((ObjectNode) result.get("failure")).put("category_hint", "");
        result.put("blocking", true);
        assertEquals(NodeStatus.FAILED, publish(tree).status());
        result.put("blocking", false);
        result.putArray("must_fix").add("Unresolved issue");
        assertEquals(NodeStatus.FAILED, publish(tree).status());
        result.putArray("must_fix");
        result.putArray("missing_evidence").add("Optional follow-up");
        assertEquals(NodeStatus.COMPLETED, publish(tree).status(), "notes may retain optional evidence");
        AgentOutputLineageFixture.completeAndPublish(root, WS, sidecar());
        assertEquals("ACCEPTANCE_CLASSIFICATION_NOT_REQUIRED", classify().outcome());
    }

    @Test
    void acceptedSidecarAllowsAbsentRemediationButRejectsUnknownRemediation() throws Exception {
        var tree = envelope(FailureCategory.REVIEW_NOISE);
        var result = (ObjectNode) tree.get("result");
        result.put("decision", "ACCEPT");
        result.put("lifecycle_status", "ACCEPTED");
        var failure = (ObjectNode) result.get("failure");
        failure.put("category_hint", "");
        failure.put("reason", "");
        assertEquals(NodeStatus.COMPLETED, publish(tree).status());
        var persisted = (ObjectNode) JSON.readTree(sidecar().toFile());
        ((ObjectNode) persisted.get("failure")).remove("verification_remediation");
        JSON.writeValue(sidecar().toFile(), persisted);
        AgentOutputLineageFixture.completeAndPublish(root, WS, sidecar());
        assertNotNull(AgentEvidenceIndex.latestDecisionFromRefs(root, WS, List.of(sidecarRef()), JSON).entry());
        assertEquals("ACCEPTANCE_CLASSIFICATION_NOT_REQUIRED", classify().outcome());

        ((ObjectNode) persisted.get("failure")).put("verification_remediation", "UNKNOWN");
        JSON.writeValue(sidecar().toFile(), persisted);
        AgentOutputLineageFixture.completeAndPublish(root, WS, sidecar());
        assertNull(AgentEvidenceIndex.latestDecisionFromRefs(root, WS, List.of(sidecarRef()), JSON).entry());
        assertEquals(NodeStatus.FAILED, classify().status());
        assertFalse(Files.exists(classification()));
    }

    @Test
    void missingOrTamperedSidecarNeverProducesClassification() throws Exception {
        assertEquals(NodeStatus.FAILED, classify().status());
        assertEquals(NodeStatus.COMPLETED, publish(envelope(FailureCategory.IMPLEMENTATION_BUG)).status());
        AgentOutputLineageFixture.completeAndPublish(root, WS, sidecar());
        Files.writeString(sidecar(), Files.readString(sidecar()) + " ");
        assertEquals(NodeStatus.FAILED, classify().status());
        assertFalse(Files.exists(classification()));
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.id.DualId;
import dev.dual.core.workflow.*;
import dev.dual.ledger.file.*;

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.List;
import java.util.Map;

/** Test adapter input recording; semantic identities are still resolved by production code. */
public final class AuthoredInputFixture {
    private static final ObjectMapper JSON = new ObjectMapper().registerModule(new JavaTimeModule()).registerModule(new EdgeConditionModule());

    public static TaskHandler.TaskContext before(Path root, String ws, String target, String run) throws Exception {
        var fixture = new AuthoredStageSequenceTest.Fixture(root, "src/Main.java",
                AuthoredStageSequenceTest.PlanTopology.DIRECT_HUMAN, ws);
        var context = fixture.before(target);
        record(context, run);
        return context;
    }

    static void publish(TaskHandler.TaskContext context, Path source, String run) throws Exception {
        var root = context.workspaceRoot();
        var sidecar = AgentOutputContractSidecar.pathFor(source);
        var tree = (com.fasterxml.jackson.databind.node.ObjectNode) JSON.readTree(sidecar.toFile());
        tree.put("workstream_id", context.workstreamId());
        tree.put("run_id", run);
        tree.put("node_id", context.definition().id());
        tree.put("node_instance_id", context.instance().nodeInstanceId());
        tree.put("source_output_ref", root.relativize(source).toString());
        var manifest = ".agent/workstreams/" + context.workstreamId() + "/runs/" + run + "/prompts/prompt.md.manifest.json";
        tree.set("authored_context", JSON.valueToTree(AuthoredExecutionContext.reference(root, manifest)));
        tree.putArray("revision_responses");
        JSON.writeValue(sidecar.toFile(), tree);
        AgentOutputLineageFixture.publish(root, context.workstreamId(), sidecar,
                context.instance().iterationId(), context.instance().inputRefs());
    }

    static void record(TaskHandler.TaskContext context, String run) throws Exception {
        var snapshot = AuthoredExecutionContext.prepare(context, run).orElseThrow();
        var root = context.workspaceRoot();
        var prompts = root.resolve(".agent/workstreams/" + context.workstreamId() + "/runs/" + run + "/prompts");
        Files.createDirectories(prompts);
        var prompt = prompts.resolve("prompt.md");
        var manifest = prompts.resolve("prompt.md.manifest.json");
        var body = snapshot.render(root);
        Files.writeString(prompt, body);
        JSON.writeValue(manifest.toFile(), Map.of("authoredContext", snapshot, "workstreamId", context.workstreamId(),
                "runId", run, "nodeId", context.definition().id(), "promptPath", prompt.toString(),
                "sections", List.of(Map.of("name", AuthoredExecutionContext.SECTION_NAME,
                        "sourceRef", context.instance().nodeInstanceId(), "required", true,
                        "sha256", TaskContractArtifactWriter.sha256(body.getBytes(java.nio.charset.StandardCharsets.UTF_8))))));
        var runPath = prompts.getParent().resolve("run.json");
        var metadata = Files.exists(runPath) ? (com.fasterxml.jackson.databind.node.ObjectNode) JSON.readTree(runPath.toFile())
                : JSON.createObjectNode();
        metadata.put("promptManifestPath", root.relativize(manifest).toString());
        JSON.writeValue(runPath.toFile(), metadata);
        AuthoredExecutionContext.verifyManifest(root, manifest, snapshot);
    }

    static void initialDesign(Path root, String ws, String nodeId, String run) throws Exception {
        var paths = new WorkstreamPaths(root, new DualId(ws));
        var author = new NodeDefinition("design.claude_design", NodeKind.TASK, "acpx.agent_run", Map.of(
                "expected_artifact", "design_result", "requires_approved_task_contract", true));
        if (!Files.exists(paths.workflowDefinitionJson())) {
            Files.createDirectories(paths.workflowDefinitionJson().getParent());
            JSON.writeValue(paths.workflowDefinitionJson().toFile(), new WorkflowDefinitionDocument(1, "scope-fixture", 1, author.id(),
                    List.of(author, new NodeDefinition("contract.compile", NodeKind.TASK, "contract.compile", Map.of()),
                            new NodeDefinition("gate.contract_review", NodeKind.GATE, "human.review", Map.of("gate_purpose", "contract"))),
                    List.of(new EdgeDefinition("contract.compile", "completed", "gate.contract_review"),
                            new EdgeDefinition("gate.contract_review", "approved", author.id()))));
        }
        Files.createDirectories(paths.iterationsDir());
        if (!Files.exists(paths.iterationJson("iter-001"))) JSON.writeValue(paths.iterationJson("iter-001").toFile(),
                WorkflowIterationDocument.initial(author.id(), Instant.parse("2026-09-05T00:00:00Z")));
        var instance = new NodeInstanceDocument(1, nodeId, author.id(), NodeKind.TASK, author.handlerType(), NodeStatus.RUNNING,
                "stage-design", "iter-001", List.of(), Map.of(), List.of(), Map.of(), null, "", Instant.now(), null);
        JSON.writeValue(paths.nodeJson(nodeId).toFile(), instance);
        record(new TaskHandler.TaskContext(root, ws, author, new WorkflowFileLedger().loadCoreNode(paths, nodeId)), run);
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import dev.dual.core.workflow.NodeDefinition;
import dev.dual.core.workflow.NodeInstance;
