package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.PropertyNamingStrategies;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class AgentResultEnvelopeValidatorTest {
    private static final ObjectMapper JSON = new ObjectMapper()
            .setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE);
    private final AgentResultEnvelopeParser parser = new AgentResultEnvelopeParser();
    private final AgentResultEnvelopeValidator validator = new AgentResultEnvelopeValidator();

    @Test
    void capturedV14ShapeParsesStrictlyButRejectsDuplicateTargetWithoutCorrection() throws Exception {
        var patch = new AgentResultEnvelope.TaskContractRevisionPatchResult(
                "task_contract_revision_patch", "READY_FOR_PRODUCT_REVIEW", "revision",
                "node-prev:0123456789abcdef", "a".repeat(64),
                List.of(
                        obligation("CO-1", "AC-1", "src/main/resources/application.yml"),
                        obligation("CO-3", "C-12", "src/main/resources/application.yml")));
        var captured = new AgentResultEnvelope(
                1, "ws-1", "run-1", "intake.claude_brainstorm", patch);
        var parsed = parser.parse(JSON.writeValueAsString(captured));

        assertTrue(parsed.valid(), parsed.message());

        var result = validator.validate(
                parsed.envelope(), "ws-1", "run-1", ContractRegistry.forNode("intake.claude_brainstorm"));

        assertFalse(result.valid());
        assertEquals(List.of(
                "DUPLICATE_EVIDENCE_PATCH_TARGET: src/main/resources/application.yml"), result.errors());
        assertEquals(AgentResultEnvelopeValidator.CorrectionDisposition.NOT_REPAIRABLE,
                result.correctionDisposition());
        assertFalse(result.schemaCorrectionAllowed());

        var correctedPatch = new AgentResultEnvelope.TaskContractRevisionPatchResult(
                patch.artifactType(), patch.decision(), patch.summary(),
                patch.baseProposalId(), patch.baseProposalSha256(),
                List.of(
                        patch.obligationPatches().get(0),
                        obligation("CO-3", "C-12", null)));
        var corrected = validator.validate(
                new AgentResultEnvelope(1, "ws-1", "run-1", "intake.claude_brainstorm", correctedPatch),
                "ws-1", "run-1", ContractRegistry.forNode("intake.claude_brainstorm"));
        assertTrue(corrected.valid(), corrected.errors().toString());
    }

    private static AgentResultEnvelope.ObligationPatch obligation(
            String obligationId,
            String clauseId,
            String evidenceRef
    ) {
        return new AgentResultEnvelope.ObligationPatch(
                obligationId,
                List.of(clauseId),
                List.of(new AgentResultEnvelope.ClauseChange(
                        AgentResultEnvelope.ClauseChangeOperation.ADD,
                        AgentResultEnvelope.ClauseSection.CONSTRAINTS,
                        clauseId,
                        "text")),
                List.of(),
                evidenceRef == null ? List.of() : List.of(evidenceRef));
    }
}

package dev.dual.runtime.handler;

import dev.dual.core.contract.TaskContract;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ChangeScopeEvaluationTest {
    @Test
    void approvedFileModificationIsNotProofOfEvidenceOnlyImmutability() {
        var result = ChangeScopeEvaluator.evaluate(
                contract(entry("src/Service.java", TaskContract.ScopeOperation.MODIFY)),
                List.of(new ChangeScopeEvaluation.ActualChange(
                        "src/Service.java", ChangeScopeEvaluation.ActualOperation.MODIFY, null, "M")));
        assertEquals(ChangeScopeEvaluation.Status.PASS, result.status(),
                "scope authorizes paths/operations; it cannot certify unchanged source bytes");
        assertEquals(List.of("src/Service.java"), result.matchedPaths());
    }

    @Test
    void parsesGitNameStatusIntoTypedActualChanges() {
        var changes = ChangeScopeEvaluator.parseNameStatus(
                "A\0new.txt\0"
                        + "M\0existing.txt\0"
                        + "D\0deleted.txt\0"
                        + "R100\0old.txt\0renamed.txt\0"
        );

        assertEquals(List.of(
                new ChangeScopeEvaluation.ActualChange(
                        "new.txt", ChangeScopeEvaluation.ActualOperation.CREATE, null, "A"),
                new ChangeScopeEvaluation.ActualChange(
                        "existing.txt", ChangeScopeEvaluation.ActualOperation.MODIFY, null, "M"),
                new ChangeScopeEvaluation.ActualChange(
                        "deleted.txt", ChangeScopeEvaluation.ActualOperation.DELETE, null, "D"),
                new ChangeScopeEvaluation.ActualChange(
                        "renamed.txt", ChangeScopeEvaluation.ActualOperation.RENAME, "old.txt", "R100")
        ), changes);
    }

    @Test
    void nulFramingPreservesUnicodeTabsAndNewlinesInPaths() {
        var path = "docs/路径\t说明\n补充.md";

        var changes = ChangeScopeEvaluator.parseNameStatus("M\0" + path + "\0");

        assertEquals(List.of(new ChangeScopeEvaluation.ActualChange(
                path,
                ChangeScopeEvaluation.ActualOperation.MODIFY,
                null,
                "M"
        )), changes);
    }

    @Test
    void lineFramedNameStatusIsRejected() {
        assertThrows(
                IllegalArgumentException.class,
                () -> ChangeScopeEvaluator.parseNameStatus("M\tREADME.md\n")
        );
    }

    @Test
    void failedGitNameStatusCommandCannotBecomeEmptyActualChanges() {
        assertThrows(
                IllegalArgumentException.class,
                () -> ChangeScopeEvaluator.parseNameStatus(128, "")
        );
    }

    @Test
    void missingDeclaredChangeIsObservationNotFailure() {
        var evaluation = ChangeScopeEvaluator.evaluate(
                contract(
                        entry("README.md", TaskContract.ScopeOperation.MODIFY),
                        entry("new.txt", TaskContract.ScopeOperation.CREATE)
                ),
                List.of(new ChangeScopeEvaluation.ActualChange(
                        "README.md",
                        ChangeScopeEvaluation.ActualOperation.MODIFY,
                        null,
                        "M"
                ))
        );

        assertEquals(ChangeScopeEvaluation.Status.PASS, evaluation.status());
        assertEquals(List.of("README.md"), evaluation.matchedPaths());
        assertEquals(List.of(entry("new.txt", TaskContract.ScopeOperation.CREATE)), evaluation.missingDeclared());
        assertTrue(evaluation.violations().isEmpty());
    }

    @Test
    void deleteAndRenameFailClosedBecauseContractDoesNotModelThem() {
        var evaluation = ChangeScopeEvaluator.evaluate(
                contract(entry("deleted.txt", TaskContract.ScopeOperation.MODIFY)),
                List.of(
                        new ChangeScopeEvaluation.ActualChange(
                                "deleted.txt", ChangeScopeEvaluation.ActualOperation.DELETE, null, "D"),
                        new ChangeScopeEvaluation.ActualChange(
                                "renamed.txt", ChangeScopeEvaluation.ActualOperation.RENAME, "old.txt", "R100")
                )
        );

        assertEquals(ChangeScopeEvaluation.Status.FAIL, evaluation.status());
        assertEquals(2, evaluation.violations().size());
        assertTrue(evaluation.violations().stream()
                .allMatch(violation -> "UNSUPPORTED_ACTUAL_OPERATION".equals(violation.code())));
    }

    private static TaskContract contract(TaskContract.ScopeEntry... entries) {
        return new TaskContract(
                "task-ws",
                1,
                java.time.Instant.parse("2026-07-26T00:00:00Z"),
                "Validate implementation changes",
                new TaskContract.Scope(List.of(entries), List.of()),
                List.of("AC1", "AC2"),
                List.of("Run tests"),
                List.of("Keep scope bounded"),
                List.of(),
                List.of(),
                List.of(),
                List.of(),
                dev.dual.core.contract.ContractStatus.READY_FOR_REVIEW,
                1,
                new TaskContract.Source("requirement.md", "test")
        );
    }

    private static TaskContract.ScopeEntry entry(String path, TaskContract.ScopeOperation operation) {
        return new TaskContract.ScopeEntry(path, operation);
    }
}

package dev.dual.runtime.handler;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

class EvidenceCollectionSourceTest {
    @TempDir Path root;

    @Test void rawContentsAndApprovedIgnoredFilesCannotHideBehindPathInventory() throws Exception {
        initialize();
        Files.writeString(root.resolve("ignored.java"), "first");
        var before = EvidenceCollectionSource.capture(root, List.of("ignored.java"));
        assertEquals(before, EvidenceCollectionSource.capture(root, before.paths()));
        Files.writeString(root.resolve("source.java"), "changed");
        assertNotEquals(before.sha256(), EvidenceCollectionSource.capture(root, before.paths()).sha256());
        Files.writeString(root.resolve("source.java"), "original");
        Files.writeString(root.resolve("ignored.java"), "second");
        assertNotEquals(before.sha256(), EvidenceCollectionSource.capture(root, before.paths()).sha256());
    }

    @Test void additionsDeletionsExecutableModeAndSymlinksAreObserved() throws Exception {
        initialize();
        Files.writeString(root.resolve("new file.txt"), "untracked");
        var before = EvidenceCollectionSource.capture(root, List.of());
        Files.delete(root.resolve("new file.txt"));
        assertNotEquals(before.sha256(), EvidenceCollectionSource.capture(root, before.paths()).sha256());
        Files.writeString(root.resolve("new file.txt"), "untracked");
        Files.writeString(root.resolve("another.txt"), "addition");
        assertNotEquals(before.sha256(), EvidenceCollectionSource.capture(root, before.paths()).sha256());
        Files.delete(root.resolve("another.txt"));
        assertTrue(root.resolve("source.java").toFile().setExecutable(true));
        assertNotEquals(before.sha256(), EvidenceCollectionSource.capture(root, before.paths()).sha256());
        Files.delete(root.resolve("source.java"));
        Files.createSymbolicLink(root.resolve("source.java"), Path.of(".git/config"));
        assertThrows(java.io.IOException.class, () -> EvidenceCollectionSource.capture(root, before.paths()));
    }

    @Test void internalEvidenceAndIgnoredBuildOutputAreNotProductChanges() throws Exception {
        initialize();
        var before = EvidenceCollectionSource.capture(root, List.of());
        Files.createDirectories(root.resolve(".agent/evidence"));
        Files.writeString(root.resolve(".agent/evidence/result.json"), "{}");
        Files.writeString(root.resolve("ignored.java"), "not part of contract");
        assertEquals(before, EvidenceCollectionSource.capture(root, before.paths()));
    }

    private void initialize() throws Exception {
        GitTrackedPathInventory.command(root, "init");
        Files.writeString(root.resolve("source.java"), "original");
        Files.writeString(root.resolve(".gitignore"), "ignored.java\n");
        GitTrackedPathInventory.command(root, "add", ".");
        GitTrackedPathInventory.command(root, "-c", "user.name=Test", "-c", "user.email=test@example.invalid",
                "commit", "-m", "baseline");
    }

    @Test void dirtyAndUntrackedContentsChangeWithoutChangingHeadIndexOrPorcelain() throws Exception {
        initialize();
        Files.writeString(root.resolve("source.java"), "dirty A");
        Files.writeString(root.resolve("new file.txt"), "untracked A");
        var before = EvidenceCollectionSource.capture(root, List.of());
        var status = GitTrackedPathInventory.command(root, "status", "--porcelain", "--untracked-files=all");
        for (var path : List.of("source.java", "new file.txt")) {
            Files.writeString(root.resolve(path), "different bytes B");
            var after = EvidenceCollectionSource.capture(root, before.paths());
            assertEquals(before.head(), after.head());
            assertEquals(before.indexSha256(), after.indexSha256());
            assertEquals(before.paths(), after.paths());
            assertEquals(status, GitTrackedPathInventory.command(root, "status", "--porcelain", "--untracked-files=all"));
            assertNotEquals(before.sha256(), after.sha256(), path);
            Files.writeString(root.resolve(path), path.equals("source.java") ? "dirty A" : "untracked A");
        }
    }
}

