import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ContextTaskContractSectionTest {

    @TempDir
    Path tempDir;

    private Path wsDir;

    @BeforeEach
    void setup() {
        wsDir = tempDir.resolve(".agent/workstreams/ws-ctx");
    }

    @Test
    void acceptanceProfileIncludesTaskContractSection() {
        var budget = ContextProfiles.acceptance();
        var sectionNames = budget.sections().stream()
                .map(SectionRequirement::section)
                .toList();
        assertTrue(sectionNames.contains("task_contract"),
                "acceptance profile should contain 'task_contract' section, got: " + sectionNames);
    }

    @Test
    void taskContractSectionIsCriticalPriority() {
        var budget = ContextProfiles.acceptance();
        var taskContractSection = budget.sections().stream()
                .filter(sr -> "task_contract".equals(sr.section()))
                .findFirst();
        assertTrue(taskContractSection.isPresent(),
                "task_contract section should exist in acceptance profile");
        assertEquals(Priority.CRITICAL, taskContractSection.get().priority(),
                "task_contract should be CRITICAL priority");
        assertEquals(2_500, taskContractSection.get().softBudget(),
                "acceptance must retain complete contracts that legitimately exceed the old 2k limit");
    }

    @Test
    void taskContractSectionIsOptionalForThinWorkflowAcceptance() {
        var budget = ContextProfiles.acceptance();
        var taskContractSection = budget.sections().stream()
                .filter(sr -> "task_contract".equals(sr.section()))
                .findFirst();

        assertTrue(taskContractSection.isPresent(),
                "task_contract section should exist in acceptance profile");
        assertEquals(MissingPolicy.PLACEHOLDER, taskContractSection.get().missingPolicy(),
                "custom workflows may omit task contracts, so acceptance context must render a placeholder instead of failing");
    }

    @Test
    void contextPackageRendersTaskContractSection() throws Exception {
        Files.createDirectories(wsDir);
        Files.writeString(wsDir.resolve("requirement.md"), "Build the feature.", StandardCharsets.UTF_8);

        // Create task-contract.json
        var artifactsDir = wsDir.resolve("artifacts");
        Files.createDirectories(artifactsDir);

        var contract = new TaskContract(
                "tc-001", 1, Instant.now(), "Test objective",
                new TaskContract.Scope(
                        List.of(new TaskContract.ScopeEntry(
                                "file1.java", TaskContract.ScopeOperation.MODIFY)),
                        List.of("file2.java")),
                List.of("AC1", "AC2"),
                List.of("TR1"),
                List.of("Use Java"),
                List.of("No Python"),
                List.of(), List.of(), List.of(),
                ContractStatus.READY_FOR_REVIEW, 1,
                new TaskContract.Source("requirement.md", "contract_compiler")
        );

        var mapper = new ObjectMapper()
                .registerModule(new JavaTimeModule())
                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
        mapper.writeValue(artifactsDir.resolve("task-contract.json").toFile(), contract);
        TaskContractProjectionFixture.seedCompileBinding(tempDir, "ws-ctx");

        // Also create git evidence for the acceptance profile
        var evidenceDir = wsDir.resolve("artifacts/git-evidence");
        Files.createDirectories(evidenceDir);
        Files.writeString(evidenceDir.resolve("git-evidence.json"), "{\"available\":true}", StandardCharsets.UTF_8);

        var handler = new ContextBuildPackageHandler();
        var context = new TaskHandler.TaskContext(
                tempDir, "ws-ctx",
                new NodeDefinition("ctx.test", NodeKind.TASK, "context.build_package", Map.of(
                        "target_node", "next.node",
                        "profile", "acceptance"
                )),
                new NodeInstance("node-001", "ctx.test", NodeKind.TASK, "context.build_package",
                        NodeStatus.READY, "stage-test", "iter-001", List.of(), List.of(), Map.of(), null, null, null)
        );

        var result = handler.execute(context);

        assertEquals(NodeStatus.COMPLETED, result.status(), "Handler should complete successfully");
        assertNotNull(result.result().get("context_package"));

        var markdown = Files.readString(tempDir.resolve((String) result.result().get("context_package")), StandardCharsets.UTF_8);

        assertTrue(markdown.contains("TaskContract"),
                "Context package should contain TaskContract section header");
        assertTrue(markdown.contains("Test objective"),
                "Context package should contain the objective text");
        assertTrue(markdown.contains("AC1"),
                "Context package should contain acceptance criteria");
        assertTrue(markdown.contains("AC2"),
                "Context package should contain acceptance criteria");
    }

    @Test
    void acceptancePackageWithoutTaskContractRendersPlaceholder() throws Exception {
        Files.createDirectories(wsDir);
        Files.writeString(wsDir.resolve("requirement.md"), "Build the feature.", StandardCharsets.UTF_8);

        var evidenceDir = wsDir.resolve("artifacts/git-evidence");
        Files.createDirectories(evidenceDir);
        Files.writeString(evidenceDir.resolve("git-evidence.json"), "{\"available\":true}", StandardCharsets.UTF_8);
        Files.writeString(evidenceDir.resolve("diff.stat"), "1 file changed\n", StandardCharsets.UTF_8);
        Files.writeString(wsDir.resolve("events.jsonl"), "", StandardCharsets.UTF_8);

        var handler = new ContextBuildPackageHandler();
        var context = new TaskHandler.TaskContext(
                tempDir, "ws-ctx",
                new NodeDefinition("ctx.test", NodeKind.TASK, "context.build_package", Map.of(
                        "target_node", "next.node",
                        "profile", "acceptance"
                )),
                new NodeInstance("node-001", "ctx.test", NodeKind.TASK, "context.build_package",
                        NodeStatus.READY, "stage-test", "iter-001", List.of(), List.of(), Map.of(), null, null, null)
        );

        var result = handler.execute(context);

        assertEquals(NodeStatus.COMPLETED, result.status(), "Baseline workflow acceptance context should not require task-contract.json");
        var markdown = Files.readString(tempDir.resolve((String) result.result().get("context_package")), StandardCharsets.UTF_8);
        assertTrue(markdown.contains("TaskContract"),
                "Context package should keep a stable TaskContract section");
        assertTrue(markdown.contains("(not available)"),
                "Missing task contract should be visible to the reviewer as unavailable");
    }
}

package dev.dual.runtime.handler;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import dev.dual.core.workflow.WorkflowStatus;
import dev.dual.ledger.file.WorkflowFileLedger;
import dev.dual.runtime.WorkflowCommand;
import dev.dual.runtime.WorkflowRuntime;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

class AcceptanceRepairInterruptionTest {
    private static final ObjectMapper JSON = new ObjectMapper().registerModule(new JavaTimeModule());
    @TempDir Path root;

    @Test
    void resolvedGateWithUnadvancedCurrentCannotBeReapprovedOrRetried() throws Exception {
        var f = new AcceptanceRepairSequenceTest.Fixture(root, "CONTRACT_GAP", "tool.py");
        f.until("gate.human_requirement_review"); f.step();
        var before = Files.readString(f.paths.workflowCurrentJson());
        var current = f.ledger.loadCurrent(f.paths);
        var gateFile = f.paths.workstreamDir().resolve("gates/" + current.openGateIds().getFirst() + ".json");
        var gate = (ObjectNode) JSON.readTree(gateFile.toFile());
        gate.put("status", "resolved");
        ((ObjectNode) gate.get("result")).put("human_action", "approved");
        JSON.writeValue(gateFile.toFile(), gate);
        var cold = new WorkflowFileLedger();
        var calls = List.copyOf(f.calls);
        var runtime = new WorkflowRuntime(cold, new HandlerRegistry(List.of(), List.of(), List.of(new HumanReviewGateHandler())));
        assertThrows(Exception.class, () -> runtime.resume(new WorkflowCommand(root, f.ws)));
        assertThrows(Exception.class, () -> cold.resolveOpenGate(f.paths, cold.loadDefinition(f.paths), "approve", "repeat"));
        assertThrows(Exception.class, () -> cold.retryActiveNode(f.paths, "retry partial gate"));
        assertThrows(Exception.class, () -> cold.abortRecovery(f.paths, "not a recovery state"));
        assertEquals(before, Files.readString(f.paths.workflowCurrentJson()));
        assertFalse(Files.exists(f.paths.workstreamDir().resolve("artifacts/task-contract.json")));
        assertEquals(calls, f.calls);
    }

    @Test
    void completedSourceWithUnadvancedCurrentDoesNotDispatchAnOrphanSuccessor() throws Exception {
        var f = new AcceptanceRepairSequenceTest.Fixture(root, "CONTRACT_GAP", "tool.py");
        f.until("acceptance.classify_failure");
        var currentBytes = Files.readAllBytes(f.paths.workflowCurrentJson());
        var source = f.ledger.loadCurrent(f.paths).activeNodeInstanceIds().getFirst();
        f.step();
        // Reproduce interruption after completed source/successor writes but before advancing current.
        Files.write(f.paths.workflowCurrentJson(), currentBytes);
        var cold = new WorkflowFileLedger();
        var calls = List.copyOf(f.calls);
        var runtime = new WorkflowRuntime(cold, new HandlerRegistry(List.of(), List.of(), List.of()));
        runtime.resume(new WorkflowCommand(root, f.ws));
        assertEquals(List.of(source), cold.loadCurrent(f.paths).activeNodeInstanceIds());
        assertThrows(Exception.class, () -> cold.retryActiveNode(f.paths, "completed source is not retryable"));
        assertThrows(Exception.class, () -> cold.abortRecovery(f.paths, "not recovery"));
        assertEquals(calls, f.calls);
    }

    @Test
    void partialRecompileCannotBeUsedAsNewApprovalOrRescueOldAuthoredInput() throws Exception {
        var f = new AcceptanceRepairSequenceTest.Fixture(root, "CONTRACT_GAP", "tool.py");
        f.until("acceptance.classify_failure"); f.step();
        f.until("gate.human_requirement_review"); f.approve();
        f.until("contract.compile");
        var calls = List.copyOf(f.calls);
        var oldInput = f.implementContexts.getFirst();
        var contract = f.paths.workstreamDir().resolve("artifacts/task-contract.json");
        Files.writeString(contract, "{\"id\":");
        assertTrue(TaskContractProjectionVerifier.resolve(root, f.ws).qualified().isEmpty());
        assertThrows(java.io.IOException.class, () -> AuthoredExecutionContext.prepare(oldInput, "retry-after-partial-write"));
        assertEquals(calls, f.calls);
        assertEquals(WorkflowStatus.RUNNING, f.ledger.loadCurrent(f.paths).status(),
                "consumer rejection does not invent a recovery ledger transition");
    }

    @Test
    void validNewContractWithOldResolutionCannotReuseApproval() throws Exception {
        var f = new AcceptanceRepairSequenceTest.Fixture(root, "CONTRACT_GAP", "tool.py");
        f.until("acceptance.classify_failure");
        var contract = f.paths.workstreamDir().resolve("artifacts/task-contract.json");
        var resolution = f.paths.workstreamDir().resolve("artifacts/contract-resolution.json");
        var oldResolution = Files.readAllBytes(resolution);
        var changed = (ObjectNode) JSON.readTree(contract.toFile());
        changed.put("objective", "A different but well-formed objective");
        JSON.writeValue(contract.toFile(), changed);
        assertTrue(JSON.readTree(contract.toFile()).isObject());
        assertArrayEquals(oldResolution, Files.readAllBytes(resolution));
        assertTrue(TaskContractProjectionVerifier.resolve(root, f.ws).qualified().isEmpty());
        assertThrows(java.io.IOException.class, () -> AuthoredExecutionContext.prepare(
                f.implementContexts.getFirst(), "retry-mixed-contract-generation"));
    }
}

