class FullWorkflowDefinitionTest {

    private final LifecycleWorkflowDefinitionFactory factory = new LifecycleWorkflowDefinitionFactory();

    @Test
    void fullVariantContainsClassifyFailureNode() {
        WorkflowDefinition wf = factory.forVariant("full");

        assertDoesNotThrow(() -> wf.node("acceptance.classify_failure"),
                "full variant should contain node acceptance.classify_failure");
    }

    @Test
    void fullVariantDeclaresTypedProposalAsProductReviewContextRequirement() {
        var contextNode = factory.forVariant("full").node("context.intake_codex_product_review");

        assertEquals("task_contract_proposal", contextNode.config().get("required_input_artifact"));
    }

    @Test
    void fullVariantLimitsWriteAccessToImplementationOwnedAgentNodes() {
        WorkflowDefinition wf = factory.forVariant("full");

        var writableNodes = wf.nodes().stream()
                .filter(node -> "acpx.agent_run".equals(node.handlerType()))
                .filter(node -> Boolean.TRUE.equals(node.config().get("approve_all")))
                .map(node -> node.id())
                .toList();

        assertEquals(List.of(
                "implement.claude_implement",
                "implement.claude_self_test_report"
        ), writableNodes);
    }

    @Test
    void fullVariantKeepsReviewAndPlanningAgentNodesReadOnly() {
        WorkflowDefinition wf = factory.forVariant("full");

        var readOnlyNodes = List.of(
                "intake.claude_brainstorm",
                "intake.codex_product_review",
                "design.claude_design",
                "design.codex_arch_review",
                "plan.claude_plan",
                "plan.codex_plan_review",
                "acceptance.codex_verifier_review",
                "stage.claude_handoff"
        );

        for (var nodeId : readOnlyNodes) {
            assertNotEquals(true, wf.node(nodeId).config().get("approve_all"),
                    nodeId + " must not have write permissions");
        }
    }

    @Test
    void fullVariantAcceptRoutesToReport() {
        WorkflowDefinition wf = factory.forVariant("full");

        var edges = wf.edgesFrom("acceptance.decision").stream()
                .filter(e -> "ACCEPT".equals(e.on()))
                .toList();

        assertEquals(1, edges.size(),
                "Expected exactly one edge from acceptance.decision on 'ACCEPT'");
        assertEquals("acceptance.generate_final_report", edges.get(0).to());
    }

    @Test
    void fullVariantAcceptWithNotesRoutesDirectlyToReport() {
        WorkflowDefinition wf = factory.forVariant("full");

        var edges = wf.edgesFrom("acceptance.decision").stream()
                .filter(e -> "ACCEPT_WITH_NOTES".equals(e.on()))
                .toList();

        assertEquals(1, edges.size(),
                "Expected exactly one edge from acceptance.decision on 'ACCEPT_WITH_NOTES'");
        assertEquals("acceptance.generate_final_report", edges.get(0).to());
    }

    @Test
    void fullVariantRejectRoutesToClassify() {
        WorkflowDefinition wf = factory.forVariant("full");

        var edges = wf.edgesFrom("acceptance.decision").stream()
                .filter(e -> "REJECT".equals(e.on()))
                .toList();

        assertEquals(1, edges.size(),
                "Expected exactly one edge from acceptance.decision on 'REJECT'");
        assertEquals("acceptance.classify_failure", edges.get(0).to());
    }

    @Test
    void fullVariantRejectContractGapRoutesToProposalContext() {
        WorkflowDefinition wf = factory.forVariant("full");

        var edges = wf.edgesFrom("acceptance.classify_failure").stream()
                .filter(e -> "REJECT_CONTRACT_GAP".equals(e.on()))
                .toList();

        assertEquals(1, edges.size(),
                "Expected exactly one edge from acceptance.classify_failure on 'REJECT_CONTRACT_GAP'");
        assertEquals("context.intake_claude_brainstorm", edges.get(0).to());
    }

    @Test
    void fullVariantRejectReviewNoiseRoutesToReReview() {
        WorkflowDefinition wf = factory.forVariant("full");

        var edges = wf.edgesFrom("acceptance.classify_failure").stream()
                .filter(e -> "REJECT_REVIEW_NOISE".equals(e.on()))
                .toList();

        assertEquals(1, edges.size(),
                "Expected exactly one edge from acceptance.classify_failure on 'REJECT_REVIEW_NOISE'");
        assertEquals("context.acceptance_codex_verifier_review", edges.get(0).to());
    }

    @Test
    void fullVariantFailureClassifierHasNoNotedOutcomes() {
        WorkflowDefinition wf = factory.forVariant("full");

        assertTrue(wf.edgesFrom("acceptance.classify_failure").stream()
                        .noneMatch(edge -> edge.on().startsWith("NOTED_")),
                "accepted decisions must bypass failure classification");
    }

    @Test
    void fullVariantRejectImplementationBugRoutesToImplement() {
        WorkflowDefinition wf = factory.forVariant("full");

        List<String> rejectOutcomes = List.of(
                "REJECT_IMPLEMENTATION_BUG"
        );

        for (String outcome : rejectOutcomes) {
            var edges = wf.edgesFrom("acceptance.classify_failure").stream()
                    .filter(e -> outcome.equals(e.on()))
                    .toList();

            assertEquals(1, edges.size(),
                    "Expected exactly one edge from acceptance.classify_failure on '" + outcome + "'");
            assertEquals("context.implement_claude", edges.get(0).to(),
                    "REJECT edge '" + outcome + "' should route to context.implement_claude");
            assertEquals("loop", edges.get(0).metadata().transitionType(),
                    "REJECT edge '" + outcome + "' should be an explicit semantic repair loop");
            assertFalse(edges.get(0).metadata().loopReason().isBlank(),
                    "REJECT edge '" + outcome + "' should explain why a new iteration starts");
        }
    }

    @Test
    void fullVariantRejectVerificationInsufficientRoutesToSelfTestEvidenceCollection() {
        WorkflowDefinition wf = factory.forVariant("full");

        var edges = wf.edgesFrom("acceptance.classify_failure").stream()
                .filter(e -> "REJECT_VERIFICATION_INSUFFICIENT".equals(e.on()))
                .toList();

        assertEquals(1, edges.size(),
                "Expected exactly one edge from acceptance.classify_failure on 'REJECT_VERIFICATION_INSUFFICIENT'");
        assertEquals("implement.claude_self_test_report", edges.get(0).to(),
                "Verification evidence gaps should rerun self-test evidence collection, not implementation repair");
        assertEquals("loop", edges.get(0).metadata().transitionType());
    }

    @Test
    void acceptanceContextRequiresCompletedSelfTestEvidence() {
        WorkflowDefinition wf = factory.forVariant("full");

        var contextNode = wf.node("context.acceptance_codex_verifier_review");
        assertEquals(Map.of(
                "node_id", "implement.claude_self_test_report",
                "source_artifact_type", "self_test_report",
                "decision", "SELF_TEST_COMPLETE"), contextNode.config().get("required_agent_evidence"));
    }

}

package dev.dual.runtime.lifecycle;

import dev.dual.core.workflow.NodeKind;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class LifecycleWorkflowDefinitionFactoryTest {
    @Test
    void includesFullVariantAcrossLifecycleStages() {
        var definition = new LifecycleWorkflowDefinitionFactory().forVariant("full");

        assertEquals("agent-lifecycle-full", definition.workflowId());
        assertEquals(10, definition.version());
        assertEquals("context.intake_claude_brainstorm", definition.entryNodeId());
        assertEquals(NodeKind.TASK, definition.node("context.intake_claude_brainstorm").kind());
        assertEquals("context.build_package", definition.node("context.intake_claude_brainstorm").handlerType());
        assertEquals(NodeKind.TASK, definition.node("intake.claude_brainstorm").kind());
        assertEquals(NodeKind.TASK, definition.node("contract.compile").kind());
        assertEquals(NodeKind.TASK, definition.node("design.codex_arch_review").kind());
        assertEquals(NodeKind.TASK, definition.node("plan.claude_plan").kind());
        assertEquals(NodeKind.TASK, definition.node("context.implement_claude").kind());
        assertEquals(NodeKind.TASK, definition.node("implement.claude_implement").kind());
        assertEquals(NodeKind.DECISION, definition.node("implement.self_test_decision").kind());
        assertEquals(NodeKind.GATE, definition.node("gate.human_implementation_repair").kind());
        assertEquals(NodeKind.TASK, definition.node("context.acceptance_codex_verifier_review").kind());
        assertEquals(NodeKind.TASK, definition.node("acceptance.codex_verifier_review").kind());
        assertEquals(NodeKind.TASK, definition.node("delivery.prepare_pr").kind());
        assertEquals(NodeKind.TASK, definition.node("stage.generate_next_prompt").kind());
        assertEquals(NodeKind.GATE, definition.node("gate.human_design_approval").kind());
        assertEquals(3, definition.node("intake.decision").config().get("max_revisions"));
        assertFalse(definition.node("design.decision").config().containsKey("max_revisions"));
        assertEquals(3, definition.node("gate.human_design_approval").config().get("max_revisions"));
        assertEquals(3, definition.node("plan.decision").config().get("max_revisions"));
        assertEquals(1, definition.node("implement.self_test_decision").config().get("max_revisions"));
        assertEquals(1, definition.node("gate.human_implementation_repair").config().get("max_revisions"));
        assertEquals("context.build_package", definition.node("context.implement_claude").handlerType());
        assertTrue(definition.edgesFrom("context.intake_claude_brainstorm").stream()
                .anyMatch(edge -> edge.to().equals("intake.claude_brainstorm")));
        assertTrue(definition.edgesFrom("intake.claude_brainstorm").stream()
                .anyMatch(edge -> edge.to().equals("context.intake_codex_product_review")));
        assertEquals(java.util.Map.of(
                        "READY_FOR_ARCH_REVIEW", "gate.human_design_approval",
                        "NEEDS_REVISION", "gate.human_design_approval",
                        "BLOCKED", "gate.human_design_approval"),
                definition.edgesFrom("design.decision").stream()
                        .collect(java.util.stream.Collectors.toMap(edge -> edge.on(), edge -> edge.to())));
        assertTrue(definition.edgesFrom("context.intake_codex_product_review").stream()
                .anyMatch(edge -> edge.to().equals("intake.codex_product_review")));
        assertTrue(definition.edgesFrom("acceptance.generate_final_report").stream()
                .anyMatch(edge -> edge.to().equals("delivery.prepare_pr")));
        assertTrue(definition.edgesFrom("implement.claude_self_test_report").stream()
                .anyMatch(edge -> edge.to().equals("implement.self_test_decision")));
        assertTrue(definition.edgesFrom("implement.self_test_decision").stream()
                .anyMatch(edge -> "SELF_TEST_INCOMPLETE".equals(edge.on())
                        && edge.to().equals("context.implement_claude")));
        assertTrue(definition.edgesFrom("implement.self_test_decision").stream()
                .anyMatch(edge -> "BLOCKED".equals(edge.on())
                        && edge.to().equals("gate.human_implementation_repair")));
        assertTrue(definition.edgesFrom("delivery.prepare_pr").stream()
                .anyMatch(edge -> edge.to().equals("gate.human_acceptance")));
    }

    @Test
    void allEdgesPointToDeclaredNodes() {
        var definition = new LifecycleWorkflowDefinitionFactory().forVariant("full");

        for (var edge : definition.edges()) {
            assertEquals(edge.from(), definition.node(edge.from()).id());
            assertEquals(edge.to(), definition.node(edge.to()).id());
        }
    }

    @Test
    void architectureReviewIsAdvisoryAcrossBundledVariants() {
        var factory = new LifecycleWorkflowDefinitionFactory();

        for (var variant : java.util.List.of("full", "contract", "terminal-delivery")) {
            var definition = factory.forVariant(variant);
            assertFalse(definition.node("design.decision").config().containsKey("max_revisions"), variant);
            assertEquals(3, definition.node("gate.human_design_approval").config().get("max_revisions"), variant);
            assertEquals(java.util.Map.of(
                            "READY_FOR_ARCH_REVIEW", "gate.human_design_approval",
                            "NEEDS_REVISION", "gate.human_design_approval",
                            "BLOCKED", "gate.human_design_approval"),
                    definition.edgesFrom("design.decision").stream()
                            .collect(java.util.stream.Collectors.toMap(edge -> edge.on(), edge -> edge.to())),
                    variant);
        }
    }

    @Test
    void selfTestAgentCanRunVerificationCommands() {
        var factory = new LifecycleWorkflowDefinitionFactory();

        assertEquals(true, factory.forVariant("contract")
                .node("implement.claude_self_test_report")
                .config()
                .get("approve_all"));
        assertEquals(true, factory.forVariant("full")
                .node("implement.claude_self_test_report")
                .config()
                .get("approve_all"));
    }

    @Test
    void builtInVariantsOnlyGrantWriteAccessToImplementationOwnedAgentNodes() {
        var factory = new LifecycleWorkflowDefinitionFactory();

        for (var definition : java.util.List.of(
                factory.forVariant("contract"),
                factory.forVariant("full")
        )) {
            var writableNodes = definition.nodes().stream()
                    .filter(node -> "acpx.agent_run".equals(node.handlerType()))
                    .filter(node -> Boolean.TRUE.equals(node.config().get("approve_all")))
                    .map(node -> node.id())
                    .toList();

            assertEquals(java.util.List.of(
                    "implement.claude_implement",
                    "implement.claude_self_test_report"
            ), writableNodes, definition.workflowId() + " must not grant write access outside implementation");
        }
    }

    @Test
    void finalNextStageGateCompletesWithoutStartingAnotherIteration() {
        var definition = new LifecycleWorkflowDefinitionFactory().forVariant("full");

        assertEquals(java.util.List.of("revise", "complete"),
                definition.node("gate.human_next_stage_approval").config().get("allowed_actions"));
        assertFalse(definition.edgesFrom("gate.human_next_stage_approval").stream()
                .anyMatch(edge -> "approved".equals(edge.on())));
        assertFalse(definition.edgesFrom("gate.human_next_stage_approval").stream()
                .anyMatch(edge -> "complete".equals(edge.on())));
        assertTrue(definition.edgesFrom("gate.human_next_stage_approval").stream()
                .anyMatch(edge -> "revise".equals(edge.on()) && "stage.claude_handoff".equals(edge.to())));
    }
}

