                     "config":{"gate_purpose":"contract","allowed_actions":["approve"]}},
                    {"id":"post-one","kind":"TASK","handlerType":"noop.task",
                     "config":{"requires_approved_task_contract":true}},
                    {"id":"post-two","kind":"TASK","handlerType":"noop.task",
                     "config":{"requires_approved_task_contract":true}}
                  ],
                  "edges":[
