package dev.dual.runtime.lifecycle;

import dev.dual.core.workflow.WorkflowDefinition;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class ContractWorkflowDefinitionTest {

    private final LifecycleWorkflowDefinitionFactory factory = new LifecycleWorkflowDefinitionFactory();

    @Test
    void contractVariantContainsContractNodes() {
        WorkflowDefinition wf = factory.forVariant("contract");

        assertDoesNotThrow(() -> wf.node("contract.compile"),
                "contract variant should contain node contract.compile");
        assertDoesNotThrow(() -> wf.node("gate.contract_review"),
                "contract variant should contain node gate.contract_review");
    }

    @Test
    void contractVariantDeclaresTypedProposalAsProductReviewContextRequirement() {
        var contextNode = factory.forVariant("contract").node("context.intake_codex_product_review");

        assertEquals("task_contract_proposal", contextNode.config().get("required_input_artifact"));
    }

    @Test
    void contractVariantRoutesContractReviewToDesign() {
        WorkflowDefinition wf = factory.forVariant("contract");

        var approvedEdges = wf.edgesFrom("gate.contract_review").stream()
                .filter(e -> "approved".equals(e.on()))
                .toList();

        assertEquals(1, approvedEdges.size(),
                "Expected exactly one edge from gate.contract_review on 'approved'");
        assertEquals("design.claude_design", approvedEdges.get(0).to());
    }

    @Test
    void contractVariantRoutesClarifyBackToTypedProposalOwner() {
        WorkflowDefinition wf = factory.forVariant("contract");

        var clarifyEdges = wf.edgesFrom("gate.contract_review").stream()
                .filter(e -> "clarify".equals(e.on()))
                .toList();

        assertEquals(1, clarifyEdges.size(),
                "Expected exactly one edge from gate.contract_review on 'clarify'");
        assertEquals("intake.claude_brainstorm", clarifyEdges.get(0).to());
        assertEquals("loop", clarifyEdges.get(0).metadata().transitionType());

        var reduceScopeEdges = wf.edgesFrom("gate.contract_review").stream()
                .filter(e -> "reduce_scope".equals(e.on()))
                .toList();

        assertTrue(reduceScopeEdges.isEmpty(),
                "Unsupported scope deletion must not be exposed as a working contract-review route");
        assertFalse(((java.util.List<?>) wf.node("gate.contract_review").config().get("allowed_actions"))
                .contains("reduce_scope"));
    }

    @Test
    void contractVariantRoutesAcceptanceRejectThroughFailureClassifier() {
        WorkflowDefinition wf = factory.forVariant("contract");

        assertDoesNotThrow(() -> wf.node("acceptance.classify_failure"),
                "contract variant should share the same typed acceptance failure classifier boundary");

        var rejectEdges = wf.edgesFrom("acceptance.decision").stream()
                .filter(e -> "REJECT".equals(e.on()))
                .toList();

        assertEquals(1, rejectEdges.size(),
                "Expected exactly one edge from acceptance.decision on 'REJECT'");
        assertEquals("acceptance.classify_failure", rejectEdges.get(0).to(),
                "Acceptance rejection must be classified before starting semantic repair");

        var implementationRepairEdges = wf.edgesFrom("acceptance.classify_failure").stream()
                .filter(e -> "REJECT_IMPLEMENTATION_BUG".equals(e.on()))
                .toList();

        assertEquals(1, implementationRepairEdges.size(),
                "Expected implementation repair classification to be routed");
        assertEquals("context.implement_claude", implementationRepairEdges.get(0).to());
        assertEquals("loop", implementationRepairEdges.get(0).metadata().transitionType(),
                "classified repair should start a semantic iteration");
    }

    @Test
    void contractVariantAcceptWithNotesBypassesFailureClassifier() {
        WorkflowDefinition wf = factory.forVariant("contract");

        var acceptedEdges = wf.edgesFrom("acceptance.decision").stream()
                .filter(edge -> "ACCEPT_WITH_NOTES".equals(edge.on()))
                .toList();

        assertEquals(1, acceptedEdges.size());
        assertEquals("acceptance.generate_final_report", acceptedEdges.get(0).to());
        assertTrue(wf.edgesFrom("acceptance.classify_failure").stream()
                        .noneMatch(edge -> edge.on().startsWith("NOTED_")),
                "accepted decisions must bypass failure classification");
    }

}

package dev.dual.runtime.lifecycle;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import dev.dual.core.workflow.WorkflowDefinition;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.nio.file.Path;
import java.util.List;
import java.util.function.Consumer;

import static org.junit.jupiter.api.Assertions.*;

class AcceptanceRepairWorkflowDefinitionTest {
    static final List<String> RESOURCES = List.of("full", "contract", "terminal-delivery",
            "small-plan-human-review-experiment");
    private static final ObjectMapper MAPPER = new ObjectMapper();
    @TempDir Path root;

    @Test
    void allFourDefinitionsDeclareBoundedContractRepairViaProposalContext() throws Exception {
        for (var variant : RESOURCES) {
            var definition = loadResource(root, variant);
            assertEquals(3, definition.node("acceptance.classify_failure").config().get("max_revisions"));
            for (var prerequisite : List.of("REJECT_TOOL_LIMITATION", "REJECT_CONTEXT_INSUFFICIENT")) {
                var routes = definition.edgesFrom("acceptance.classify_failure").stream()
                        .filter(edge -> prerequisite.equals(edge.on())).toList();
                assertEquals(1, routes.size());
                assertEquals("gate.human_implementation_repair", routes.getFirst().to());
                assertEquals("normal", routes.getFirst().metadata().transitionType(),
                        "missing prerequisites cannot start an automatic product revision");
            }
            var scope = definition.edgesFrom("gate.human_implementation_repair").stream()
                    .filter(edge -> edge.on().equals("request_scope_revision")).toList();
            assertEquals(1, scope.size());
            assertEquals("context.intake_claude_brainstorm", scope.getFirst().to());
            assertEquals("loop", scope.getFirst().metadata().transitionType());
            assertEquals(List.of("revise", "request_scope_revision", "request_action", "collect_evidence", "submit_evidence"), definition.node("gate.human_implementation_repair")
                    .config().get("allowed_actions"));
            for (var outcome : List.of("REJECT_CONTRACT_GAP", "REJECT_CONTRACT_AMBIGUITY")) {
                var edges = definition.edgesFrom("acceptance.classify_failure").stream()
                        .filter(edge -> outcome.equals(edge.on())).toList();
                assertEquals(1, edges.size());
                assertEquals("context.intake_claude_brainstorm", edges.getFirst().to());
                assertEquals("loop", edges.getFirst().metadata().transitionType());
            }
            assertEquals("intake.claude_brainstorm",
                    definition.edgesFrom("context.intake_claude_brainstorm").getFirst().to());
            assertEquals("task_contract_proposal",
                    definition.node("intake.claude_brainstorm").config().get("expected_artifact"));
            assertFalse(Boolean.TRUE.equals(definition.node("context.intake_claude_brainstorm")
                    .config().get("requires_approved_task_contract")));
        }
    }

    @Test
    void scopeRequestCannotUseAnotherSourceOrSkipProposalReview() throws Exception {
        for (var target : List.of("intake.claude_brainstorm", "contract.compile", "context.implement_claude")) {
            var json = resource("full");
            edge(json, "gate.human_implementation_repair", "request_scope_revision").put("to", target);
            assertThrows(IOException.class, () -> load(json));
        }
        var json = resource("full");
        edge(json, "gate.human_implementation_repair", "request_scope_revision").put("from", "gate.human_plan_approval");
        assertThrows(IOException.class, () -> load(json));
    }

    @Test
    void customWorkflowIdentityDoesNotNeedABundledName() throws Exception {
        var json = resource("full");
        json.put("workflowId", "custom-documentation-workflow");
        assertEquals("custom-documentation-workflow", load(json).workflowId());
    }

    @Test
    void rejectsInvalidContractRepairSourcesTargetsAndProducers() throws Exception {
        List<Consumer<ObjectNode>> mutations = List.of(
                json -> repair(json).put("from", "acceptance.decision"),
                json -> node(json, "acceptance.classify_failure").put("handlerType", "noop.task"),
                json -> node(json, "acceptance.classify_failure").put("kind", "DECISION"),
                json -> config(json, "acceptance.classify_failure").put("requires_approved_task_contract", false),
                json -> repair(json).put("to", "contract.compile"),
                json -> repair(json).put("to", "intake.claude_brainstorm"),
                json -> repair(json).put("to", "context.intake_codex_product_review"),
                json -> repair(json).withObject("metadata").put("transitionType", "normal"),
                json -> repair(json).withObject("metadata").put("branchGroupId", "fan-out"),
                json -> repair(json).withObject("metadata").put("required", false),
                json -> repair(json).putObject("condition").put("type", "config_equals")
                        .putObject("params").put("key", "x").put("value", "y"),
                json -> node(json, "context.intake_claude_brainstorm").put("handlerType", "noop.task"),
                json -> config(json, "context.intake_claude_brainstorm").put("target_node", "contract.compile"),
                json -> edge(json, "context.intake_claude_brainstorm", "completed").put("to", "contract.compile"),
                json -> config(json, "intake.claude_brainstorm").put("expected_artifact", "agent_output_contract"),
                json -> config(json, "intake.claude_brainstorm").put("artifact_compiler", "agent_output_contract_compiler"),
                json -> node(json, "intake.claude_brainstorm").put("handlerType", "noop.task"),
                json -> json.withArray("edges").add(repair(json).deepCopy()),
                json -> json.put("entryNodeId", "acceptance.classify_failure")
        );
        for (int i = 0; i < mutations.size(); i++) {
            var json = resource("full");
            mutations.get(i).accept(json);
            assertThrows(IOException.class, () -> load(json), "mutation " + i);
        }
    }

    @Test
    void otherOutcomesCannotReuseNegotiationOrCompileEntry() throws Exception {
        for (var target : List.of("context.intake_claude_brainstorm", "intake.claude_brainstorm",
                "contract.compile", "gate.human_requirement_review")) {
            var json = resource("full");
            edge(json, "acceptance.classify_failure", "REJECT_IMPLEMENTATION_BUG").put("to", target);
            assertThrows(IOException.class, () -> load(json), target);
        }
    }

    static WorkflowDefinition loadResource(Path root, String variant) throws Exception {
        var path = root.resolve(variant + ".json");
        MAPPER.writeValue(path.toFile(), resource(variant));
        return new WorkflowDefinitionLoader().load(path);
    }

    private WorkflowDefinition load(ObjectNode json) throws Exception {
        var path = root.resolve("custom.json");
        MAPPER.writeValue(path.toFile(), json);
        return new WorkflowDefinitionLoader().load(path);
    }

    private static ObjectNode resource(String variant) throws Exception {
        try (var stream = AcceptanceRepairWorkflowDefinitionTest.class.getResourceAsStream(
                "/dev/dual/runtime/lifecycle/agent-lifecycle." + variant + ".json")) {
            assertNotNull(stream, variant);
            return (ObjectNode) MAPPER.readTree(stream);
        }
    }

    private static ObjectNode repair(ObjectNode json) {
        return edge(json, "acceptance.classify_failure", "REJECT_CONTRACT_GAP");
    }

    private static ObjectNode edge(ObjectNode json, String from, String outcome) {
        for (var edge : json.withArray("edges")) {
            if (from.equals(edge.path("from").asText()) && outcome.equals(edge.path("on").asText())) {
                return (ObjectNode) edge;
            }
        }
        throw new AssertionError(from + ":" + outcome);
    }

    private static ObjectNode node(ObjectNode json, String id) {
        for (var node : json.withArray("nodes")) {
            if (id.equals(node.path("id").asText())) return (ObjectNode) node;
        }
        throw new AssertionError(id);
    }

    private static ObjectNode config(ObjectNode json, String id) {
        return node(json, id).withObject("config");
    }
}

package dev.dual.runtime.lifecycle;

import org.junit.jupiter.api.Test;

import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class TerminalDeliveryWorkflowDefinitionTest {
    private static final Set<String> OMITTED_TAIL_NODES = Set.of(
            "stage.claude_handoff",
            "stage.generate_next_prompt",
            "gate.human_next_stage_approval"
    );

    @Test
    void bundledVariantChangesOnlyTheAcceptedDeliveryTail() {
        var full = new LifecycleWorkflowDefinitionFactory().forVariant("full");
        var terminal = new LifecycleWorkflowDefinitionFactory().forVariant("terminal-delivery");

        assertEquals("agent-lifecycle-terminal-delivery", terminal.workflowId());
        assertEquals(31, terminal.nodes().size());
        assertEquals(56, terminal.edges().size());
        assertEquals(9, terminal.nodes().stream()
                .filter(node -> "acpx.agent_run".equals(node.handlerType()))
                .count());

        assertTrue(terminal.nodes().stream().noneMatch(node -> OMITTED_TAIL_NODES.contains(node.id())));
        assertTrue(terminal.edges().stream().noneMatch(edge ->
                OMITTED_TAIL_NODES.contains(edge.from()) || OMITTED_TAIL_NODES.contains(edge.to())));
        assertTrue(terminal.edgesFrom("gate.human_acceptance").stream()
                .noneMatch(edge -> "approved".equals(edge.on())));
        assertEquals("context.implement_claude", terminal.edgesFrom("gate.human_acceptance").stream()
                .filter(edge -> "revise".equals(edge.on()))
                .findFirst()
                .orElseThrow()
                .to());
        assertEquals(true, terminal.node("gate.human_acceptance").config().get("terminal_gate"));
        assertEquals(1, terminal.node("implement.self_test_decision").config().get("max_revisions"));
        assertEquals(java.util.List.of("revise", "request_scope_revision", "request_action", "collect_evidence", "submit_evidence"),
                terminal.node("gate.human_implementation_repair").config().get("allowed_actions"));
        assertEquals(java.util.Map.of(
                        "SELF_TEST_COMPLETE", "implement.artifact_validation",
                        "SELF_TEST_INCOMPLETE", "context.implement_claude",
                        "BLOCKED", "gate.human_implementation_repair"),
                terminal.edgesFrom("implement.self_test_decision").stream()
                        .filter(edge -> edge.condition().evaluate(java.util.Map.of(
                                "continuation_kind", "IMPLEMENTATION_REPAIR")))
                        .collect(java.util.stream.Collectors.toMap(edge -> edge.on(), edge -> edge.to())));
        assertEquals("gate.human_implementation_repair", terminal.edgesFrom("implement.self_test_decision",
                "SELF_TEST_INCOMPLETE", java.util.Map.of("continuation_kind", "HUMAN_REVIEW"))
                .getFirst().to());

        for (var node : full.nodes()) {
            if (OMITTED_TAIL_NODES.contains(node.id()) || "gate.human_acceptance".equals(node.id())) {
                continue;
            }
            assertEquals(node, terminal.node(node.id()), node.id());
        }
        var expectedEdges = full.edges().stream()
                .filter(edge -> !OMITTED_TAIL_NODES.contains(edge.from()))
                .filter(edge -> !OMITTED_TAIL_NODES.contains(edge.to()))
                .filter(edge -> !("gate.human_acceptance".equals(edge.from())
                        && "approved".equals(edge.on())))
                .toList();
        var json = new com.fasterxml.jackson.databind.ObjectMapper()
                .registerModule(new dev.dual.ledger.file.EdgeConditionModule());
        assertEquals(json.valueToTree(expectedEdges), json.valueToTree(terminal.edges()));

        assertFalse(Boolean.TRUE.equals(full.node("gate.human_acceptance").config().get("terminal_gate")));
        assertEquals("stage.claude_handoff", full.edgesFrom("gate.human_acceptance").stream()
                .filter(edge -> "approved".equals(edge.on()))
                .findFirst()
                .orElseThrow()
                .to());
    }
}

