/**
 * Distinguishes automatic runtime retry from manual operator retry.
 */
public enum AgentExecutionRetryPolicy {
    NONE,
    MANUAL_ONLY,
    AUTO_ALLOWED
}

package dev.dual.core.execution;

import java.time.Instant;

/**
 * Owns the terminal consistency boundary for one external agent attempt.
 *
 * <p>Adapters and validators provide typed facts. This class produces the only
 * terminal attempt/outcome/legacy-field combination that may be persisted.</p>
 */
public final class AgentExecutionFinalizer {
    private final AgentExecutionOutcomeResolver resolver;

    public AgentExecutionFinalizer() {
        this(new AgentExecutionOutcomeResolver());
    }

    public AgentExecutionFinalizer(AgentExecutionOutcomeResolver resolver) {
        if (resolver == null) {
            throw new IllegalArgumentException("resolver is required");
        }
        this.resolver = resolver;
    }

    public FinalizedAgentExecution finalize(AgentExecutionAttempt baseAttempt, AgentExecutionEvidence evidence) {
        if (baseAttempt == null) {
            throw new IllegalArgumentException("baseAttempt is required");
        }
        if (evidence == null) {
            throw new IllegalArgumentException("evidence is required");
        }
        var outcome = resolver.resolve(evidence);
        var attempt = terminalAttempt(baseAttempt, evidence, outcome);
        return new FinalizedAgentExecution(
                attempt,
                outcome,
                outcome.nodeMaySucceed() ? "completed" : "failed",
                outcome.nodeMaySucceed() ? null : outcome.primaryReason(),
                !outcome.nodeMaySucceed() && outcome.retryPolicy() != AgentExecutionRetryPolicy.NONE
        );
    }

    private AgentExecutionAttempt terminalAttempt(
            AgentExecutionAttempt base,
            AgentExecutionEvidence evidence,
            AgentExecutionOutcome outcome
    ) {
        var status = attemptStatus(evidence.processResult(), outcome);
        var processStatus = processStatus(evidence.processResult(), outcome);
        var failureSignal = status == AgentExecutionAttemptStatus.COMPLETED ? null : primaryFailureSignal(outcome);
        var recoverable = status == AgentExecutionAttemptStatus.RECOVERABLE_FAILED
                || status == AgentExecutionAttemptStatus.TIMED_OUT
                || status == AgentExecutionAttemptStatus.STALLED
                || status == AgentExecutionAttemptStatus.INTERRUPTED;
        return new AgentExecutionAttempt(
                base.attemptId(),
                base.runId(),
                base.workstreamId(),
                base.nodeId(),
                base.agent(),
                status,
                processStatus,
                failureSignal,
                recoverable,
                outcome.retryPolicy() != AgentExecutionRetryPolicy.NONE,
                outcome.operatorMessage(),
                base.stderrPath(),
                base.transcriptPath(),
                base.sessionName(),
                base.sessionId(),
                base.sessionScope(),
                base.sessionSegmentKey(),
                base.startedAt(),
                finishedAt(base)
        );
    }

    private static AgentExecutionAttemptStatus attemptStatus(
            ProcessResult process,
            AgentExecutionOutcome outcome
    ) {
        // Process terminal facts remain authoritative for the attempt shape even
        // when a blocking adapter signal owns the higher-level outcome reason.
        if (process.usability() == ProcessUsability.TIMED_OUT) {
            return AgentExecutionAttemptStatus.TIMED_OUT;
        }
        if (process.usability() == ProcessUsability.STALLED) {
            return AgentExecutionAttemptStatus.STALLED;
        }
        if (process.usability() == ProcessUsability.INTERRUPTED) {
            return AgentExecutionAttemptStatus.INTERRUPTED;
        }
        if (outcome.nodeMaySucceed()) {
            return AgentExecutionAttemptStatus.COMPLETED;
        }
        if (outcome.status() == AgentExecutionOutcomeStatus.CONTRACT_FAILED) {
            return AgentExecutionAttemptStatus.CONTRACT_FAILED;
        }
        if (outcome.status() == AgentExecutionOutcomeStatus.TIMEOUT) {
            return "process_stalled".equals(outcome.primaryReason())
                    ? AgentExecutionAttemptStatus.STALLED
                    : AgentExecutionAttemptStatus.TIMED_OUT;
        }
        if (outcome.status() == AgentExecutionOutcomeStatus.INTERRUPTED) {
            return AgentExecutionAttemptStatus.INTERRUPTED;
        }
        if (outcome.retryPolicy() != AgentExecutionRetryPolicy.NONE) {
            return AgentExecutionAttemptStatus.RECOVERABLE_FAILED;
        }
        return AgentExecutionAttemptStatus.RUNTIME_FAILED;
    }

    private static AgentExecutionProcessStatus processStatus(
            ProcessResult process,
            AgentExecutionOutcome outcome
    ) {
        if (outcome.nodeMaySucceed() || outcome.status() == AgentExecutionOutcomeStatus.CONTRACT_FAILED) {
            return AgentExecutionProcessStatus.EXITED;
        }
        return switch (process.usability()) {
            case TIMED_OUT -> AgentExecutionProcessStatus.TIMED_OUT;
            case INTERRUPTED -> AgentExecutionProcessStatus.INTERRUPTED;
            case STALLED -> AgentExecutionProcessStatus.STALLED;
            case KILLED_AFTER_RECOVERABLE_SIGNAL -> hasSignal(outcome, AdapterSignalType.AGENT_RECONNECT_REQUIRED)
                    ? AgentExecutionProcessStatus.RECONNECT_REQUIRED
                    : AgentExecutionProcessStatus.FAILED;
            case EXITED_ZERO, EXITED_NON_ZERO_WITH_COMPLETE_OUTPUT, EXITED_NON_ZERO_WITH_INCOMPLETE_OUTPUT ->
                    AgentExecutionProcessStatus.FAILED;
        };
    }

    private static boolean hasSignal(AgentExecutionOutcome outcome, AdapterSignalType type) {
        return outcome.secondarySignals().stream().anyMatch(signal -> signal.type() == type);
    }

    private static AdapterSignalType primaryFailureSignal(AgentExecutionOutcome outcome) {
        return outcome.secondarySignals().isEmpty() ? null : outcome.secondarySignals().get(0).type();
    }

    private static Instant finishedAt(AgentExecutionAttempt attempt) {
        return attempt.finishedAt() == null ? Instant.now() : attempt.finishedAt();
    }
}

package dev.dual.core.execution;

import java.util.List;

/**
 * The single semantic outcome for one agent execution.
 *
 * <p>Workflow runtime and projections should consume this object instead of
 * reinterpreting stderr, exit codes, raw assistant text, or artifact files.</p>
 */
public record AgentExecutionOutcome(
        AgentExecutionOutcomeStatus status,
        String primaryReason,
        List<AdapterSignal> secondarySignals,
        boolean nodeMaySucceed,
        AgentExecutionRetryPolicy retryPolicy,
        RecoveryCategory recoveryCategory,
        String operatorMessage
) {
    public AgentExecutionOutcome {
        if (status == null) {
            throw new IllegalArgumentException("status is required");
        }
        primaryReason = requireText("primaryReason", primaryReason);
        secondarySignals = secondarySignals == null ? List.of() : List.copyOf(secondarySignals);
        if (retryPolicy == null) {
            throw new IllegalArgumentException("retryPolicy is required");
        }
        if (recoveryCategory == null) {
            throw new IllegalArgumentException("recoveryCategory is required");
        }
        operatorMessage = requireText("operatorMessage", operatorMessage);
        if (nodeMaySucceed != (status == AgentExecutionOutcomeStatus.SUCCESS
                || status == AgentExecutionOutcomeStatus.SUCCESS_WITH_WARNINGS)) {
            throw new IllegalArgumentException("nodeMaySucceed must match success outcome status");
        }
    }

    private static String requireText(String field, String value) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(field + " is required");
        }
        return value;
    }
}

