/** Shared definition and runtime semantics for human gate actions. */
public final class HumanGateActionSemantics {
    public static final String REQUEST_SCOPE_REVISION = "request_scope_revision";
    public static final String REQUEST_ACTION = "request_action";
    public static final String COLLECT_EVIDENCE = "collect_evidence";
    public static final String SUBMIT_EVIDENCE = "submit_evidence";
    private static final List<String> DEFAULT_ACTIONS = List.of("approve", "revise");

    private HumanGateActionSemantics() {
    }

    /** A human revision supplies new instructions regardless of the model's recommendation. */
    public static boolean requiresDecisionNote(String action, String sourceOutcome) {
        return "revise".equals(action) || "clarify".equals(action) || "BLOCKED".equals(sourceOutcome);
    }

    public static List<String> allowedActions(NodeDefinition definition) {
        var configured = definition.config().get("allowed_actions");
        if (configured instanceof List<?> list && !list.isEmpty()) {
            return list.stream()
                    .map(String::valueOf)
                    .filter(action -> !action.isBlank())
                    .toList();
        }
        return DEFAULT_ACTIONS;
    }

    public static String canonicalAction(List<EdgeDefinition> outgoingEdges, String requestedAction) {
        if (!"approve".equals(requestedAction)) {
            return requestedAction;
        }
        var hasApproveEdge = outgoingEdges.stream().anyMatch(edge -> "approve".equals(edge.on()));
        var hasApprovedEdge = outgoingEdges.stream().anyMatch(edge -> "approved".equals(edge.on()));
        return !hasApproveEdge && hasApprovedEdge ? "approved" : requestedAction;
    }

    /** Definition declares possible actions; the source occurrence narrows their applicability. */
    public static List<String> allowedActions(NodeDefinition definition, String sourceOutcome) {
        var scopeRepair = definition.kind() == NodeKind.GATE
                && "human.review".equals(definition.handlerType())
                && "gate.human_implementation_repair".equals(definition.id())
                && "implementation_repair".equals(definition.config().get("gate_purpose"))
                && "CHANGE_SCOPE_VIOLATION".equals(sourceOutcome);
        return allowedActions(definition).stream()
                .filter(action -> !REQUEST_SCOPE_REVISION.equals(action) || scopeRepair)
                .filter(action -> !(COLLECT_EVIDENCE.equals(action) || SUBMIT_EVIDENCE.equals(action))
                        || !"CHANGE_SCOPE_VIOLATION".equals(sourceOutcome))
                .toList();
    }

    static void validateVisibility(List<NodeDefinition> nodes, List<EdgeDefinition> edges) {
        for (var node : nodes) {
            if (node.kind() != NodeKind.GATE) {
                continue;
            }
            var outgoingEdges = edges.stream().filter(edge -> edge.from().equals(node.id())).toList();
            var allowedActions = allowedActions(node);
            for (var collectionAction : List.of(COLLECT_EVIDENCE, SUBMIT_EVIDENCE)) {
              if (allowedActions.contains(collectionAction)) {
                var routes = outgoingEdges.stream().filter(edge -> collectionAction.equals(edge.on())).toList();
                if (!"human.review".equals(node.handlerType())
                        || !"implementation_repair".equals(node.config().get("gate_purpose"))
                        || routes.size() != 1 || !"unconditional".equals(routes.getFirst().condition().type())
                        || !"normal".equals(routes.getFirst().metadata().transitionType())
                        || nodes.stream().noneMatch(target -> target.id().equals(routes.getFirst().to())
                        && "acpx.agent_run".equals(target.handlerType())
                        && "self_test_report".equals(target.config().get("expected_artifact")))) {
                    throw new IllegalArgumentException(collectionAction + " requires one normal route to a self-test task");
                }
              }
            }
            if (allowedActions.contains(REQUEST_ACTION)
                    && (!"human.review".equals(node.handlerType())
                    || !"implementation_repair".equals(node.config().get("gate_purpose")))) {
                throw new IllegalArgumentException("request_action is limited to implementation repair gates");
            }
            for (var edge : outgoingEdges) {
                if (REQUEST_ACTION.equals(edge.on())) {
                    throw new IllegalArgumentException("request_action is non-resolving and cannot have an outgoing edge");
                }
                var visible = allowedActions.stream()
                        .map(action -> canonicalAction(outgoingEdges, action))
                        .anyMatch(edge.on()::equals);
                if (!visible) {
                    throw new IllegalArgumentException(
                            "gate " + node.id() + " has hidden outgoing action " + edge.on()
                                    + "; effective allowed actions: " + allowedActions);
                }
            }
        }
    }
}

package dev.dual.core.workflow;

import java.util.List;
import java.util.HashSet;
import java.util.Map;

public record WorkflowDefinition(
        String workflowId,
        int version,
        String entryNodeId,
        List<NodeDefinition> nodes,
        List<EdgeDefinition> edges
) {
    public WorkflowDefinition {
        if (workflowId == null || workflowId.isBlank()) {
            throw new IllegalArgumentException("workflow id is required");
        }
        if (version <= 0) {
            throw new IllegalArgumentException("workflow version must be positive");
        }
        nodes = copyNodes(nodes);
        edges = copyEdges(edges);
        var nodeIds = validateUniqueNodeIds(nodes);
        if (!nodeIds.contains(entryNodeId)) {
            throw new IllegalArgumentException("entry node does not exist: " + entryNodeId);
        }
        for (var edge : edges) {
            if (!nodeIds.contains(edge.from())) {
                throw new IllegalArgumentException("edge from node does not exist: " + edge.from());
            }
            if (!nodeIds.contains(edge.to())) {
                throw new IllegalArgumentException("edge to node does not exist: " + edge.to());
            }
        }
        HumanGateActionSemantics.validateVisibility(nodes, edges);
        ChangeScopeViolationRoutingSemantics.validate(nodes, edges);
        SelfTestContinuationSemantics.validate(nodes, edges);
    }

    public NodeDefinition node(String nodeId) {
        var node = nodeOrNull(nodeId, nodes);
        if (node == null) {
            throw new IllegalArgumentException("unknown node: " + nodeId);
        }
        return node;
    }

    public List<EdgeDefinition> edgesFrom(String nodeId) {
        return edges.stream().filter(edge -> edge.from().equals(nodeId)).toList();
    }

    /**
     * Find all edges from a node matching the given outcome, with condition evaluation.
     * Each edge's {@link EdgeCondition} is evaluated against the routing context.
     */
    public List<EdgeDefinition> edgesFrom(String nodeId, String outcome, Map<String, Object> routingContext) {
        return edges.stream()
                .filter(edge -> edge.from().equals(nodeId))
                .filter(edge -> edge.on().equals(outcome))
                .filter(edge -> edge.condition().evaluate(routingContext))
                .toList();
    }

    private static NodeDefinition nodeOrNull(String nodeId, List<NodeDefinition> candidates) {
        if (nodeId == null) {
            return null;
        }
        return candidates.stream().filter(node -> node.id().equals(nodeId)).findFirst().orElse(null);
    }

    private static List<NodeDefinition> copyNodes(List<NodeDefinition> source) {
        if (source == null) {
            return List.of();
        }
        for (var node : source) {
            if (node == null) {
                throw new IllegalArgumentException("nodes contains null element");
            }
        }
        return List.copyOf(source);
    }

    private static List<EdgeDefinition> copyEdges(List<EdgeDefinition> source) {
        if (source == null) {
            return List.of();
        }
        for (var edge : source) {
            if (edge == null) {
                throw new IllegalArgumentException("edges contains null element");
            }
        }
        return List.copyOf(source);
    }

    private static HashSet<String> validateUniqueNodeIds(List<NodeDefinition> nodes) {
        var nodeIds = new HashSet<String>();
        for (var node : nodes) {
            if (!nodeIds.add(node.id())) {
                throw new IllegalArgumentException("duplicate node id: " + node.id());
            }
        }
        return nodeIds;
    }
}

package dev.dual.core.workflow;

import java.util.LinkedHashMap;
import java.util.Map;

public record TransitionMetadata(
        String transitionType,
        String branchGroupId,
        boolean required,
        String purpose,
        String joinStrategy,
        String loopReason
) {
    public TransitionMetadata {
        transitionType = normalize(transitionType, "normal");
        branchGroupId = normalize(branchGroupId, "");
        purpose = normalize(purpose, "");
        joinStrategy = normalize(joinStrategy, "");
        loopReason = normalize(loopReason, "");
        if (!isKnownType(transitionType)) {
            throw new IllegalArgumentException("unknown transition type: " + transitionType);
        }
        if ("join".equals(transitionType) && joinStrategy.isBlank()) {
            joinStrategy = "all_terminal";
        }
    }

    public static TransitionMetadata normal() {
        return new TransitionMetadata("normal", "", true, "", "", "");
    }

    public static TransitionMetadata loop(String reason) {
        return new TransitionMetadata("loop", "", true, "", "", reason);
    }

    public static TransitionMetadata fork(String branchGroupId, boolean required, String purpose) {
        return new TransitionMetadata("fork", branchGroupId, required, purpose, "", "");
    }

    public static TransitionMetadata join(String branchGroupId, String strategy, String purpose) {
        return new TransitionMetadata("join", branchGroupId, true, purpose, strategy, "");
    }

    public Map<String, Object> toAttributes() {
        var attributes = new LinkedHashMap<String, Object>();
        attributes.put("transition_type", transitionType);
        attributes.put("required", required);
        if (!branchGroupId.isBlank()) {
            attributes.put("branch_group_id", branchGroupId);
        }
        if (!purpose.isBlank()) {
            attributes.put("purpose", purpose);
        }
        if (!joinStrategy.isBlank()) {
            attributes.put("join_strategy", joinStrategy);
        }
        if (!loopReason.isBlank()) {
            attributes.put("loop_reason", loopReason);
        }
        return Map.copyOf(attributes);
    }

    private static boolean isKnownType(String type) {
        return switch (type) {
            case "normal", "loop", "fork", "join" -> true;
            default -> false;
        };
    }

    private static String normalize(String value, String fallback) {
        if (value == null || value.isBlank()) {
            return fallback;
        }
        return value.trim();
    }
}

