            return Map.of();
        }
        var copy = new LinkedHashMap<String, Object>();
        for (var entry : source.entrySet()) {
            if (entry.getKey() == null || entry.getKey().isBlank()) {
                throw new IllegalArgumentException("context key is required");
            }
            copy.put(entry.getKey(), entry.getValue());
        }
        return Collections.unmodifiableMap(copy);
    }
}

package dev.dual.core.flow;

import dev.dual.core.workflow.WorkflowDefinition;

import java.util.ArrayList;
import java.util.LinkedHashMap;

public final class BuiltInFlowOrchestrationKernel implements FlowOrchestrationKernel {
    @Override
    public FlowValidationResult validate(WorkflowDefinition definition) {
        if (definition == null) {
            return FlowValidationResult.invalid(java.util.List.of("workflow definition is required"));
        }
        return FlowValidationResult.ok();
    }

    @Override
    public FlowAdvanceResult advance(
            WorkflowDefinition definition,
            FlowExecutionSnapshot snapshot,
            FlowSignal signal
    ) {
        if (definition == null) {
            throw new IllegalArgumentException("workflow definition is required");
        }
        if (snapshot == null) {
            throw new IllegalArgumentException("flow execution snapshot is required");
        }
        if (signal == null) {
            throw new IllegalArgumentException("flow signal is required");
        }
        if (!snapshot.activeNodeDefinitionIds().contains(signal.nodeDefinitionId())) {
            throw new IllegalArgumentException("signal node is not active: " + signal.nodeDefinitionId());
        }

        var routingContext = new LinkedHashMap<String, Object>();
        routingContext.put("outcome", signal.outcome());
        routingContext.putAll(signal.context());

        var transitions = new ArrayList<FlowTransitionCandidate>();
        for (var edge : definition.edgesFrom(signal.nodeDefinitionId(), signal.outcome(), routingContext)) {
            transitions.add(new FlowTransitionCandidate(edge.from(), edge.on(), edge.to(), edgeAttributes(edge)));
        }
        return FlowAdvanceResult.routed(transitions, java.util.List.of("builtin.route"));
    }

    private static java.util.Map<String, Object> edgeAttributes(dev.dual.core.workflow.EdgeDefinition edge) {
        var attributes = new LinkedHashMap<String, Object>(edge.metadata().toAttributes());
        attributes.put("condition", edge.condition().type());
        return java.util.Map.copyOf(attributes);
    }
}

package dev.dual.core.flow;

import java.util.List;

public record FlowValidationResult(boolean valid, List<String> errors) {
    public FlowValidationResult {
        errors = errors == null ? List.of() : List.copyOf(errors);
        if (valid && !errors.isEmpty()) {
            throw new IllegalArgumentException("valid result cannot contain errors");
        }
    }

    public static FlowValidationResult ok() {
        return new FlowValidationResult(true, List.of());
    }

    public static FlowValidationResult invalid(List<String> errors) {
        return new FlowValidationResult(false, errors);
    }
}

package dev.dual.core.flow;

import java.util.List;

public record FlowExecutionSnapshot(
        String workflowInstanceId,
        List<String> activeNodeDefinitionIds
) {
    public FlowExecutionSnapshot {
        if (workflowInstanceId == null || workflowInstanceId.isBlank()) {
            throw new IllegalArgumentException("workflow instance id is required");
        }
        activeNodeDefinitionIds = activeNodeDefinitionIds == null ? List.of() : List.copyOf(activeNodeDefinitionIds);
        for (var nodeId : activeNodeDefinitionIds) {
            if (nodeId == null || nodeId.isBlank()) {
                throw new IllegalArgumentException("active node definition id is required");
            }
        }
    }

    public static FlowExecutionSnapshot singleActiveNode(String workflowInstanceId, String nodeDefinitionId) {
        return new FlowExecutionSnapshot(workflowInstanceId, List.of(nodeDefinitionId));
    }
}

